Object.assign(quranData,{"1":{"name":"الفاتحة","verses":[{"text":"بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ","tafsir":"أي أستعين بالله، وإنما لم يقل «بالله» تعظيما، فكأن الاستعانة بالاسم، والله علم له سبحانه، والرحمن والرحيم صفتان تدلان على كونه تعالى عين الرحمة، فلا يرهب جانبه، كما يرهب جانب الطغاة والسفاكين، وتكرير الصفة للتأكيد."},{"text":"ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ","tafsir":"فإنه هو الذي يستحق الحمد ، لأن كل جميل منه ، وكل خير من عنده ، وهو رب العالمين ، الذي أوجدهم ورباهم. والتربية تطلق على الإنشاء والاستمرار ، والعالمين إشارة إلى عوالم الكون ، من جن وملك ، وإنسان وحيوان ، ونبات وجماد ، وروح وجسد ، وغيرها."},{"text":"ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ","tafsir":"تكرار للتأكيد ، لإفادة أن الرب ليس طاغيا ، كما هو الشأن في غالب الأرباب البشرية."},{"text":"مَـٰلِكِ يَوْمِ ٱلدِّينِ","tafsir":"الدين هو الجزاء ، فيوم الدين : « القيامة » ، والله مالك ذلك اليوم ، لا يشرك فيه أحد ( وَلا يَشْفَعُونَ إِلَّا لِمَنِ ارْتَضى ) (1) ."},{"text":"إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","tafsir":"أي عبادتنا وخضوعنا لك ، وقدم « إياك » لإفادة الحصر. ( وَإِيَّاكَ نَسْتَعِينُ ) أي نطلب الإعانة ، فإنه هو الذي بيده كل شيء ، فالاستعانة منه ، والإتيان بالتكلم مع الغير ، لإفادة كون المسلمين كلهم منخرطين في هذين السلكين : سلك العبادة لله ، وسلك الاستعانة به."},{"text":"ٱهْدِنَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ","tafsir":"غير المنحرف ، والهداية هو إرشاد الطريق ، ( 1) الأنبياء : 29. صِراطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلا الضَّالِّينَ (7) فإن الإنسان في كل آن يحتاج إلى من يرشده ويهديه ، وإن كان مهديا ، وحيث لم يذكر متعلق الصراط المستقيم ، دلّ على العموم ، فالمسلم يطلب منه سبحانه أن يهديه الصراط المستقيم ، في العقيدة ، والعمل ، والقول ، والرأي ، وغيرها."},{"text":"صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ","tafsir":"إنه تفسير ل : « الصراط المستقيم » أي إن الصراط المستقيم هو صراط الذين أنعمت عليهم ، بهدايتهم من النبيين والأئمة عليهم‌السلام والصالحين ( غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ ) فإن من أنعم الله عليه بالهداية ، لا يكون مغضوبا عليه ( وَلَا الضَّالِّينَ ) أي الضال المنحرف عن الطريق ، والضال يمكن أن يكون مغضوبا عليه إذا كان عن تقصير ، ويمكن أن يكون غير مغضوب عليه إذا كان عن قصور ، والمسلم يطلب من الله تعالى أن لا يكون من هؤلاء ولا هؤلاء. (2)"}]},"2":{"name":"البقرة","verses":[{"text":"الٓمٓ","tafsir":"ابتدأت السورة باسم الله تعالى، لتكرر الاستعانة به، وليتعلم المسلم كي يبتدئ جميع أعماله بهذا الاسم المبارك، وليتركز هذا الاسم الكريم في الأذهان، فإن للتكرار أثرا بالغا."},{"text":"ذَٰلِكَ ٱلْكِتَـٰبُ لَا رَيْبَ ۛ فِيهِ ۛ هُدًى لِّلْمُتَّقِينَ","tafsir":"أي من جنس هذه الحروف المقطعة : « أ » ، « ل » ، « م » ."},{"text":"ٱلَّذِينَ يُؤْمِنُونَ بِٱلْغَيْبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَـٰهُمْ يُنفِقُونَ","tafsir":"والإشارة بالبعيد ، للإشارة إلى كون القرآن سامي المقام ، عالي المنزلة ( لا رَيْبَ فِيهِ ) أي ليس محلّا للريب ، وإن ارتاب فيه الكفار ، كما أن النهار لا ريب فيه ، وإن ارتاب فيه السوفسطائيون ، و ( لا رَيْبَ فِيهِ ) صفة للكتاب ( هُدىً لِلْمُتَّقِينَ ) صفة بعد صفة ، أي أن هذا القرآن هداية لمن اتقى ، وخاف من التردي ، فإنه هو الذي يهتدي بالقرآن ، وإن كان القرآن صالحا ، لأن يهدي الكل."},{"text":"وَٱلَّذِينَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَبِٱلْـَٔاخِرَةِ هُمْ يُوقِنُونَ","tafsir":"صفة للمتقين ، والمراد بالإيمان الاعتقاد به ، والغيب هو الذي غاب عن الحواس الظاهرة ، أي ما وراء الطبيعة ، فالروح غيب ، وأحوال القبر غيب ، والله سبحانه غيب ، وهكذا ( وَيُقِيمُونَ الصَّلاةَ ) إقامة الصلاة ، الإتيان بها دائما على الوجه المأمور بها ، ولذا تدل على معنى أرفع ، من معنى « صل » ( وَمِمَّا رَزَقْناهُمْ يُنْفِقُونَ ) والرزق أعم من المأكول ، والملبوس ، والمسكون ، والعلم والصحة ، وغيرها ، وإنفاق كل شيء بحسبه."},{"text":"أُو۟لَـٰٓئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ","tafsir":"من الوحي والقرآن ( وَما أُنْزِلَ مِنْ قَبْلِكَ وَبِالْآخِرَةِ هُمْ يُوقِنُونَ (4) أُولئِكَ عَلى هُدىً مِنْ رَبِّهِمْ وَأُولئِكَ هُمُ الْمُفْلِحُونَ (5) إِنَّ الَّذِينَ كَفَرُوا سَواءٌ عَلَيْهِمْ أَ أَنْذَرْتَهُمْ أَمْ لَمْ تُنْذِرْهُمْ لا يُؤْمِنُونَ (6) قَبْلِكَ ) فإن من شرائط الإيمان ، الإيمان بكل الأنبياء عليهم‌السلام ( لا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ ) (1) ( وَبِالْآخِرَةِ هُمْ يُوقِنُونَ ) واليقين بالآخرة هو الاعتقاد بها ، والعمل بمقتضاها ، وبعض هذه الأمور ، وإن كانت داخلة في « الإيمان بالغيب » ، لكنها ذكرت لزيادة الاهتمام بها ، وذكر الخاص بعد العام."},{"text":"إِنَّ ٱلَّذِينَ كَفَرُوا۟ سَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ","tafsir":"أي على بصيرة ، وهذه البصيرة أتت إليهم من ناحية الله سبحانه ( وَأُولئِكَ هُمُ الْمُفْلِحُونَ ) الناجحون ، فهم في الدنيا على بصيرة ، وفي الآخرة في زمرة الناجين ، ثم أن القرآن لما ذكر المؤمنين ، ثنّاهم بذكر الكافرين ، ثم ثلّثهم بذكر المنافقين ، فإن كل دعوة ، لا بد وأن ينقسم الناس أمامها إلى ثلاثة أقسام : مؤمن بها وكافر بها ، ومذبذب بين ذلك يجامل الطرفين."},{"text":"خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ ۖ وَعَلَىٰٓ أَبْصَـٰرِهِمْ غِشَـٰوَةٌ ۖ وَلَهُمْ عَذَابٌ عَظِيمٌ","tafsir":"والكفر هو الستر ، كأن الكافر يستر الحقيقة ، ولا يبديها ( سَواءٌ عَلَيْهِمْ أَ أَنْذَرْتَهُمْ أَمْ لَمْ تُنْذِرْهُمْ لا يُؤْمِنُونَ ) والمراد ب « الذين كفروا » هنا هم المعاندون منهم ، لأنهم المصداق الأجلى للكافر ، وإلا فالذين آمنوا بالرسول صلى‌الله‌عليه‌وآله‌وسلم من الناس كانوا كفارا ثم ( 1) البقرة : 286. خَتَمَ اللهُ عَلى قُلُوبِهِمْ وَعَلى سَمْعِهِمْ وَعَلى أَبْصارِهِمْ غِشاوَةٌ وَلَهُمْ عَذابٌ عَظِيمٌ (7) آمنوا ، ومن المعلوم أن المعاند يتساوى في حقه الإنذار وعدمه ، نعم يجب إنذاره إتماما للحجة ، وهذا تسلية للنبي صلى‌الله‌عليه‌وآله‌وسلم ، حتى لا تذهب نفسه عليهم حسرات."},{"text":"وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلْيَوْمِ ٱلْـَٔاخِرِ وَمَا هُم بِمُؤْمِنِينَ","tafsir":"طبعها بالكفر ، أي جعلها بحيث يصعب إيمانها ، لأنها اعتادت الكفر ، وعدم الاستماع إلى الحق ، وإنما ختم الله ، لأنها لم تقبل الهداية ، كمن يطرد ولده عن داره بعد ما أرشده مرات ، فلم يفد فيه النصح ، كما قال تعالى ( طَبَعَ اللهُ عَلَيْها بِكُفْرِهِمْ ) (1) أي بسبب كفرهم ، وإنما فسرنا « الختم » ب « يصعب » لبداهة أن الإنسان ولو كان معاندا ، لا يخرج عن قابلية القبول والاهتداء ( وَعَلى سَمْعِهِمْ ) بمعنى إنهم لا يستفيدون من السمع ، كالأصم ، لأن في سمعهم خلل ( وَعَلى أَبْصارِهِمْ غِشاوَةٌ ) تشبيه للغشاوة المعنوية بالغشاوة الظاهرية ، فكما أن من على بصره غشاوة ، لا يرى المحسوسات ، كذلك من يعاند يكون على بصره مثل الغشاوة ، وهو تنزيل لفاقد الوصف منزلة فاقد الأصل ، كما تقول لمن لا ينتفع بالعلم ، هو جدار ( وَلَهُمْ عَذابٌ عَظِيمٌ ) في الدنيا والآخرة ، فإن من ينحرف عن قوانين الله تعالى ، يكون ( لَهُ مَعِيشَةً ضَنْكاً وَنَحْشُرُهُ يَوْمَ الْقِيامَةِ أَعْمى ) (2) . ( 1) النساء : 156. ( 2) طه : 125. وَمِنَ النَّاسِ مَنْ يَقُولُ آمَنَّا بِاللهِ وَبِالْيَوْمِ الْآخِرِ وَما هُمْ بِمُؤْمِنِينَ (8) يُخادِعُونَ اللهَ وَالَّذِينَ آمَنُوا وَما يَخْدَعُونَ إِلاَّ أَنْفُسَهُمْ وَما يَشْعُرُونَ (9) فِي قُلُوبِهِمْ مَرَضٌ فَزادَهُمُ اللهُ مَرَضاً"},{"text":"يُخَـٰدِعُونَ ٱللَّهَ وَٱلَّذِينَ ءَامَنُوا۟ وَمَا يَخْدَعُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ","tafsir":"المنافقون ، وهم القسم الثالث ، فهو ( مَنْ يَقُولُ آمَنَّا بِاللهِ وَبِالْيَوْمِ الْآخِرِ ) قولا باللفظ فقط ( وَما هُمْ بِمُؤْمِنِينَ ) حقيقة ، فلا يعملون أعمال المؤمنين ، وإن كانت قلوبهم أيضا متيقنة بحقائق الإيمان."},{"text":"فِى قُلُوبِهِم مَّرَضٌ فَزَادَهُمُ ٱللَّهُ مَرَضًا ۖ وَلَهُمْ عَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْذِبُونَ","tafsir":"أي يفعلون مع الله تعالى ، فعل المخادع ، الذي يريد الخديعة ، فيظهر ما لا يريده ، ويريد ما لا يظهره ( وَالَّذِينَ آمَنُوا ) فيرونهم خلاف ما يضمرونه ، لكن عملهم هذا ليس خدعة حقيقية لله وللمؤمنين ، فإنهما يعلمان نواياهم ، فلا ينخدعان بهم ، بل ( وَما يَخْدَعُونَ إِلَّا أَنْفُسَهُمْ ) إذ يجري عليهم أحكام المؤمنين ظاهرا ، ولا يشتركون معهم في أسرارهم ، كما لا يشتركون معهم في آخرتهم ، فهم مخدوعون من حيث ظنوا أنهم خادعين ( وَما يَشْعُرُونَ ) بأنهم خدعوا أنفسهم ، لا أنهم خدعوا الله والمؤمنين ، إذ لو شعروا بأنهم يخدعون أنفسهم ، لم يقدموا على ما ظنوه خدعة لغيرهم ، والحال أنها خدعة لهم حقيقة وواقعا."},{"text":"وَإِذَا قِيلَ لَهُمْ لَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ قَالُوٓا۟ إِنَّمَا نَحْنُ مُصْلِحُونَ","tafsir":"فإن قلب المنافق ملتو ، ونفسه معوجة ، لا تريد الاستقامة ( فَزادَهُمُ اللهُ مَرَضاً ) إذ نزول الآيات ، ونصب الرسول ، وَلَهُمْ عَذابٌ أَلِيمٌ بِما كانُوا يَكْذِبُونَ (10) وَإِذا قِيلَ لَهُمْ لا تُفْسِدُوا فِي الْأَرْضِ قالُوا إِنَّما نَحْنُ مُصْلِحُونَ (11) أَلا إِنَّهُمْ هُمُ الْمُفْسِدُونَ وَلكِنْ لا يَشْعُرُونَ (12) وَإِذا قِيلَ لَهُمْ أوجب أن يزيدوا في التوائهم ، لئلا يسلط النور عليهم ، فيعرفوا ( وَلَهُمْ عَذابٌ أَلِيمٌ ) أي مؤلم ( بِما كانُوا يَكْذِبُونَ ) أي بسبب كذبهم ، بمخالفة ظاهرهم لباطنهم ، فإنه نوع من الكذب ، وإن كان كلامهم مطابقا للواقع ، لكنهم حيث أخبروا عن إيمانهم ـ ولم يكونوا مؤمنين ـ كان ذلك كذبا."},{"text":"أَلَآ إِنَّهُمْ هُمُ ٱلْمُفْسِدُونَ وَلَـٰكِن لَّا يَشْعُرُونَ","tafsir":"أي للمنافقين ( لا تُفْسِدُوا فِي الْأَرْضِ ) فإن النفاق يلازم الإفساد ، إذ يعمل المنافق ضد الدعوة ، ويؤلب عليها ، وهو إفساد حينما تريد الدعوة الإصلاح والتقدم ( قالُوا إِنَّما نَحْنُ مُصْلِحُونَ ) فإنهم يظنون أن الدعوة إفساد ، وأنهم بوقوفهم ضدها يصلحون في الأرض."},{"text":"وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓا۟ أَنُؤْمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُ ۗ أَلَآ إِنَّهُمْ هُمُ ٱلسُّفَهَآءُ وَلَـٰكِن لَّا يَعْلَمُونَ","tafsir":"لأنهم بوقوفهم النفاقي ضد الإسلام ، يكونون مفسدين إفسادا بالغا أكثر من إفساد الكفار ، ولذا قال تعالى في آية أخرى ( هُمُ الْعَدُوُّ ) (1) على نحو الحصر ( وَلكِنْ لا يَشْعُرُونَ ) بذلك ، بل يحسبون أنهم يحسنون صنعا."},{"text":"وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ إِلَىٰ شَيَـٰطِينِهِمْ قَالُوٓا۟ إِنَّا مَعَكُمْ إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ","tafsir":"أي للمنافقين ، والقائل هم جماعة من المؤمنين ( 1) المنافقون : 5. آمِنُوا كَما آمَنَ النَّاسُ قالُوا أَ نُؤْمِنُ كَما آمَنَ السُّفَهاءُ أَلا إِنَّهُمْ هُمُ السُّفَهاءُ وَلكِنْ لا يَعْلَمُونَ (13) وَإِذا لَقُوا الَّذِينَ آمَنُوا قالُوا آمَنَّا وَإِذا خَلَوْا إِلى شَياطِينِهِمْ قالُوا إِنَّا مَعَكُمْ إِنَّما نَحْنُ مُسْتَهْزِؤُنَ (14) اللهُ يَسْتَهْزِئُ بِهِمْ وَيَمُدُّهُمْ الذين لا يخافونهم ( آمِنُوا كَما آمَنَ النَّاسُ ) إيمانا لا يشوبه نفاق ( قالُوا أَ نُؤْمِنُ كَما آمَنَ السُّفَهاءُ ) يعنون بالسفهاء المؤمنين الحقيقيين ( أَلا إِنَّهُمْ هُمُ السُّفَهاءُ ) وأية سفاهة أعظم من كون الإنسان حائد عن طريق الحق مع كونه متصفا بصفة النفاق الرذيلة ( وَلكِنْ لا يَعْلَمُونَ ) إنهم هم السفهاء ، لأنهم يظنون أن طريقتهم النفاقية ، أصلح الطرق."},{"text":"ٱللَّهُ يَسْتَهْزِئُ بِهِمْ وَيَمُدُّهُمْ فِى طُغْيَـٰنِهِمْ يَعْمَهُونَ","tafsir":"من « لقى » أي التقى المنافقون ب ( الَّذِينَ آمَنُوا قالُوا ) لهم ( آمَنَّا وَإِذا خَلَوْا إِلى شَياطِينِهِمْ ) أي أشباههم من المنافقين ( قالُوا ) لهم ( إِنَّا مَعَكُمْ ) يريدون بذلك إرضاء الجانبين ( إِنَّما نَحْنُ مُسْتَهْزِؤُنَ ) بالمؤمنين ، في إظهار الإيمان لهم ، وهذا هو دليل نفاقهم ، وإلّا لو كان الأمر بالعكس ، بأن أظهروا الكفر تقية لم يزيدوا على إظهاره."},{"text":"أُو۟لَـٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَـٰلَةَ بِٱلْهُدَىٰ فَمَا رَبِحَت تِّجَـٰرَتُهُمْ وَمَا كَانُوا۟ مُهْتَدِينَ","tafsir":"أي يفعل لهم فعل المستهزئ ، فيجري عليهم في الدنيا أحكام الإيمان ، وفي الآخرة يجازيهم بجزاء الكفار ، وفي بعض الأحاديث إنه يستهزئ بهم في الآخرة في النار ( وَيَمُدُّهُمْ ) إمداد الله سبحانه وتعالى ، بعدم الضرب على أيديهم كما يقال : الملك يمد فِي طُغْيانِهِمْ يَعْمَهُونَ (15) أُولئِكَ الَّذِينَ اشْتَرَوُا الضَّلالَةَ بِالْهُدى فَما رَبِحَتْ تِجارَتُهُمْ وَما كانُوا مُهْتَدِينَ (16) مَثَلُهُمْ كَمَثَلِ الَّذِي اسْتَوْقَدَ ناراً فَلَمَّا أَضاءَتْ ما حَوْلَهُ ذَهَبَ اللهُ بِنُورِهِمْ قطّاع الطريق حيث لا يستأصلهم ( فِي طُغْيانِهِمْ يَعْمَهُونَ ) الطغيان تجاوز الحد ، والعمه التحير ، فإن المنافق ، كالشخص المتحير ، وإنما يمدهم الله سبحانه ، لأن الدنيا دار اختبار وامتحان ، فلا جبر ولا إلجاء."},{"text":"مَثَلُهُمْ كَمَثَلِ ٱلَّذِى ٱسْتَوْقَدَ نَارًا فَلَمَّآ أَضَآءَتْ مَا حَوْلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمْ وَتَرَكَهُمْ فِى ظُلُمَـٰتٍ لَّا يُبْصِرُونَ","tafsir":"المنافقون ( الَّذِينَ اشْتَرَوُا الضَّلالَةَ بِالْهُدى ) فكأنهم أعطوا الهداية ، وأخذوا مكانها الضلالة ، أو كأنهم أعطوا أنفسهم بدل الضلالة ، بينما كان الذي ينبغي أن يعطوا أنفسهم بدل الهداية ، كما قال الشاعر : أنفاس عمرك أثمان الجنان فلا تشري بها لهبا في الحشر تشتعل ( فَما رَبِحَتْ تِجارَتُهُمْ ) المعنوية ، بل خسروا رأس المال الذي هو أنفسهم ( وَما كانُوا مُهْتَدِينَ ) في هذه التجارة والاشتراء."},{"text":"صُمٌّۢ بُكْمٌ عُمْىٌ فَهُمْ لَا يَرْجِعُونَ","tafsir":"أي مثل هؤلاء المنافقين ( كَمَثَلِ الَّذِي اسْتَوْقَدَ ناراً ) استوقد بمعنى أوقد ، أو بمعنى طلب الوقود الذي هو الحطب ونحوه ، والمعنى أشعل نارا ليستضيء ويدفأ بها ( فَلَمَّا أَضاءَتْ ) النار ( ما حَوْلَهُ ) وانتفع بها ( ذَهَبَ اللهُ بِنُورِهِمْ ) بأن أرسل ريحا فأطفأها وَتَرَكَهُمْ فِي ظُلُماتٍ لا يُبْصِرُونَ صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لا يَرْجِعُونَ (18) أَوْ كَصَيِّبٍ مِنَ السَّماءِ فِيهِ ظُلُماتٌ ( وَتَرَكَهُمْ فِي ظُلُماتٍ لا يُبْصِرُونَ ) ما حولهم وإنما كان هذا مثلا لهم ، لأن المنافق بإيمانه الظاهري ، يعبّد لنفسه سبيل الحياة ، وينور في طريقه ، فإن الإيمان نور ، وسبب لهداية الإنسان إلى الحق والعدل والخير ، فإذا قبض الله أرواحهم تركهم ، كسائر الكفار في نار وعذاب ، حين يقبض الله أرواح المؤمنين ، إلى نور أوسع ورحمة أكبر ، فهؤلاء المنافقون :"},{"text":"أَوْ كَصَيِّبٍ مِّنَ ٱلسَّمَآءِ فِيهِ ظُلُمَـٰتٌ وَرَعْدٌ وَبَرْقٌ يَجْعَلُونَ أَصَـٰبِعَهُمْ فِىٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ حَذَرَ ٱلْمَوْتِ ۚ وَٱللَّهُ مُحِيطٌۢ بِٱلْكَـٰفِرِينَ","tafsir":"جمع أصم ، لأنهم لا ينتفعون بالحق ، فهم والأصم سواء ( بُكْمٌ ) جمع أبكم ، وهو الأخرس ، لأنهم لا يقولون الحق فهم والأبكم سواء ( عُمْيٌ ) جمع أعمى ، لأنهم لا يبصرون الحق ، فهم والأعمى سواء ( فَهُمْ لا يَرْجِعُونَ ) عن غيهم وضلالهم ، و « ف » ، للإشارة إلى أنهم حيث صموا وأبكموا وعملوا لم يرج فيهم الخير ، فإنه ( وَلا يَسْمَعُ الصُّمُّ الدُّعاءَ ) (1) ."},{"text":"يَكَادُ ٱلْبَرْقُ يَخْطَفُ أَبْصَـٰرَهُمْ ۖ كُلَّمَآ أَضَآءَ لَهُم مَّشَوْا۟ فِيهِ وَإِذَآ أَظْلَمَ عَلَيْهِمْ قَامُوا۟ ۚ وَلَوْ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمْعِهِمْ وَأَبْصَـٰرِهِمْ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ","tafsir":"مثال آخر لحال المنافقين ، والفرق بين المثالين ، إن المثال الأول ، كان مثالا للمنافق نفسه ، وهذا المثال مثال الحق الذي يغمر المنافق ، لكنه لا ينتفع به والصيب هو المطر ، فالحق الذي يغمر هؤلاء كمطر ينزل من السماء ( فِيهِ ظُلُماتٌ ) ظلمة السحاب وظلمة المطر ، لأنه يحول بين الضياء وبين الأرض ، وظلمة ( 1) الأنبياء : 46. وَرَعْدٌ وَبَرْقٌ يَجْعَلُونَ أَصابِعَهُمْ فِي آذانِهِمْ مِنَ الصَّواعِقِ حَذَرَ الْمَوْتِ وَاللهُ مُحِيطٌ بِالْكافِرِينَ (19) يَكادُ الْبَرْقُ يَخْطَفُ أَبْصارَهُمْ كُلَّما أَضاءَ لَهُمْ مَشَوْا فِيهِ وَإِذا أَظْلَمَ عَلَيْهِمْ قامُوا وَلَوْ شاءَ اللهُ لَذَهَبَ بِسَمْعِهِمْ وَأَبْصارِهِمْ إِنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ (20) سحاب فوق سحاب ( وَرَعْدٌ وَبَرْقٌ ) من الأمور المخوفة ( يَجْعَلُونَ ) أي من ابتلى بهذا الصيب ( أَصابِعَهُمْ فِي آذانِهِمْ مِنَ ) خشية ( الصَّواعِقِ ) فإن الصاعقة إذا نزلت ، قرعت الأسماع بصوتها الشديد ( حَذَرَ الْمَوْتِ ) فإن الصوت الشديد يوجب انخلاع القلب ، فيموت الشخص ، لكن هؤلاء المنافقين الذين هم كفار في الباطن لا يظنون أنهم يتمكنون الفرار من بأس الله تعالى ( وَاللهُ مُحِيطٌ بِالْكافِرِينَ ) إحاطة علم وقدرة."},{"text":"يَـٰٓأَيُّهَا ٱلنَّاسُ ٱعْبُدُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُمْ وَٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ","tafsir":"اللامع في السحاب ( يَخْطَفُ أَبْصارَهُمْ ) أي أبصار من ابتلى بالصيب ، وخطف البصر كناية عن عماه ( كُلَّما أَضاءَ لَهُمْ ) بأن أبرق ، ورأوا طريقهم ( مَشَوْا فِيهِ ) أي في البرق ـ بمعنى استفادتهم من نوره فيمشون ( وَإِذا أَظْلَمَ عَلَيْهِمْ ) بأن لم يبرق ( قامُوا ) في أماكنهم ـ أي وقفوا ـ ( وَلَوْ شاءَ اللهُ لَذَهَبَ بِسَمْعِهِمْ ) بسبب صاعقة قوية فتصمهم ( وَأَبْصارِهِمْ ) بسبب برق قوي ، إذ النور إذا قوي أوجب ذهاب البصر ( إِنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) فلا يمنعه أن يحتمي الإنسان بإصبعه ، أو بغمض بصره عن أن يذهب بسمعه يا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ (21) أو بصره ، وهذا توضيح المثال بتطبيقه على المورد أن « الصيب » هو الحق النازل على الرسول صلى‌الله‌عليه‌وآله‌وسلم و « البرق » هو تقدم المسلمين ، وما يسبب لهم إنارة الطريق ، و « الرعد والصاعقة » إيعادات الرسل ، والأهوال المكتنفة بالدعوة ، والمنافقون كمن ابتلى بهذا الصيب في الصحراء ، فالحق كالمطر فيه الحياة ، لكن فيه ظلمات غلبة الكفار ، وذهاب الأنفس والأموال والثمرات ، وفيه برق ينير طريق الحياة السعيدة ، وفيه رعد وصاعقة مواعيد الرسول ، وفضيحة المنافقين ، وهؤلاء المنافقون تكاد سرعة تقدم المسلمين ، تعميهم ، فإن العين إذا نظرت إلى ما لا يسرها اضطربت ودمعت ، كلما أضاء لهم ، بأن غلبوا في الحرب ، وحصلوا على الغنائم ، اتبعوا الرسول ، وإذا أظلم عليهم ، بأن غلب عليهم الكفار ، وقفوا وقاموا في مكانهم ، لا يعلمون ولا يتقدمون وهم يخافون من الفضيحة ، إن نزلت آية في شأن المنافقين ، فيجعلون أصابعهم في آذانهم ، حتى لا يسمعونها ، أو يتغافلون عنها ، كي لا يرى أثر الانهزام في وجوههم ، فإن الإنسان المجرم إذا سمع ما يمس إجرامه ظهرت الصفرة وآثار الانهزام على وجهه ، لكن الله قادر على إماتتهم ، كما هو قادر على فضحهم والذهاب بسمعهم وبصرهم ، فليسوا هم في راحة من نفاقهم ـ كما زعموا ـ بل هم في أشد ابتلاء ومحنة."},{"text":"ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ فِرَٰشًا وَٱلسَّمَآءَ بِنَآءً وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًا لَّكُمْ ۖ فَلَا تَجْعَلُوا۟ لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ","tafsir":"خلق ( الَّذِينَ مِنْ قَبْلِكُمْ ) وكان السبب في الخلق ( لَعَلَّكُمْ تَتَّقُونَ ) أي خلقكم للتقوى الَّذِي جَعَلَ لَكُمُ الْأَرْضَ فِراشاً وَالسَّماءَ بِناءً وَأَنْزَلَ مِنَ السَّماءِ ماءً فَأَخْرَجَ بِهِ مِنَ الثَّمَراتِ رِزْقاً لَكُمْ فَلا تَجْعَلُوا لِلَّهِ أَنْداداً وَأَنْتُمْ تَعْلَمُونَ (22) وَإِنْ كُنْتُمْ فِي رَيْبٍ مِمَّا نَزَّلْنا عَلى عَبْدِنا فَأْتُوا بِسُورَةٍ مِنْ مِثْلِهِ وَادْعُوا شُهَداءَكُمْ والعبادة ، كما قال تعالى ( وَما خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ ) (1) ."},{"text":"وَإِن كُنتُمْ فِى رَيْبٍ مِّمَّا نَزَّلْنَا عَلَىٰ عَبْدِنَا فَأْتُوا۟ بِسُورَةٍ مِّن مِّثْلِهِۦ وَٱدْعُوا۟ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَـٰدِقِينَ","tafsir":"كالفراش الذي يكون راحة للبدن وزينة وجمالا ( وَالسَّماءَ بِناءً ) أي مبنيا ، وهذا يلائم كون السماء طبقة تحطم القذائف إلى الأرض ، فإن البناء ليس المراد منه أن يكون المبنى من جسم كثيف ( وَأَنْزَلَ مِنَ السَّماءِ ماءً ) والمراد من السماء هنا جهة العلو ، أو المراد من تلك الناحية ( فَأَخْرَجَ بِهِ ) أي بسبب الماء ( مِنَ الثَّمَراتِ رِزْقاً لَكُمْ ) فإذا كان الخلق وسائر النعم من الله سبحانه ( فَلا تَجْعَلُوا لِلَّهِ أَنْداداً ) شركاء من الأصنام أو غيرها ( وَأَنْتُمْ تَعْلَمُونَ ) أنها باطلة ، وأنه ليس لله شريك."},{"text":"فَإِن لَّمْ تَفْعَلُوا۟ وَلَن تَفْعَلُوا۟ فَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِى وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ ۖ أُعِدَّتْ لِلْكَـٰفِرِينَ","tafsir":"محمد بن عبد الله صلى‌الله‌عليه‌وآله‌وسلم ، وتزعمون أنه ليس من الله سبحانه ( فَأْتُوا بِسُورَةٍ ) واحدة ( مِنْ مِثْلِهِ ) أي من مثل هذا المنزل ، ولو كان قصر سورة نحو ( قُلْ هُوَ اللهُ أَحَدٌ ) (2) أو ( إِنَّا أَعْطَيْناكَ ) (3) ( وَادْعُوا شُهَداءَكُمْ ) ، الذين يشهدون ( 1) الذاريات : 57. ( 2) الإخلاص : 2. ( 3) الكوثر : 2. مِنْ دُونِ اللهِ إِنْ كُنْتُمْ صادِقِينَ (23) فَإِنْ لَمْ تَفْعَلُوا وَلَنْ تَفْعَلُوا فَاتَّقُوا النَّارَ الَّتِي وَقُودُهَا النَّاسُ وَالْحِجارَةُ أُعِدَّتْ لِلْكافِرِينَ (24) وَبَشِّرِ الَّذِينَ آمَنُوا وَعَمِلُوا معكم ، أن محمدا صلى‌الله‌عليه‌وآله‌وسلم ليس بنبي ( مِنْ دُونِ اللهِ ) أي كائن ما كان غير الله سبحانه ، كما يقال ما دون الله مخلوق ( إِنْ كُنْتُمْ صادِقِينَ ) في ريبكم وزعمكم ، أن محمدا ليس بنبي ، وأن القرآن ليس منزلا من عند الله تعالى ، إذ لو لم يكن محمد صلى‌الله‌عليه‌وآله‌وسلم نبيا ، لكان إنسانا عاديا ، فيمكن الإتيان بمثل كلامه."},{"text":"وَبَشِّرِ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أَنَّ لَهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۖ كُلَّمَا رُزِقُوا۟ مِنْهَا مِن ثَمَرَةٍ رِّزْقًا ۙ قَالُوا۟ هَـٰذَا ٱلَّذِى رُزِقْنَا مِن قَبْلُ ۖ وَأُتُوا۟ بِهِۦ مُتَشَـٰبِهًا ۖ وَلَهُمْ فِيهَآ أَزْوَٰجٌ مُّطَهَّرَةٌ ۖ وَهُمْ فِيهَا خَـٰلِدُونَ","tafsir":"ولم تأتوا بسورة من مثل هذا القرآن ( وَلَنْ تَفْعَلُوا ) هذا إخبار بأنهم لن يفعلوا ذلك أبدا ، إذ القرآن معجز ، فلا يمكن الإتيان بمثله ( فَاتَّقُوا ) عاقبة تكذيبكم ، لرسول الله ، ولكتاب الله ، التي هي ( النَّارَ الَّتِي وَقُودُهَا ) أي حطبها ، وما يسبب إيقادها ( النَّاسُ وَالْحِجارَةُ ) جمع حجر ولعل المراد بها أصنامهم ، كما قال تعالى ( إِنَّكُمْ وَما تَعْبُدُونَ مِنْ دُونِ اللهِ حَصَبُ جَهَنَّمَ ) (1) وتخصيص الحجارة بالذكر للتهويل ، إذ الحجارة لا تفنى ، فتكون النار دائمة ( أُعِدَّتْ ) هذه النار ( لِلْكافِرِينَ ) هذه عاقبة من يكذب."},{"text":"۞ إِنَّ ٱللَّهَ لَا يَسْتَحْىِۦٓ أَن يَضْرِبَ مَثَلًا مَّا بَعُوضَةً فَمَا فَوْقَهَا ۚ فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ ۖ وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَـٰذَا مَثَلًا ۘ يُضِلُّ بِهِۦ كَثِيرًا وَيَهْدِى بِهِۦ كَثِيرًا ۚ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلْفَـٰسِقِينَ","tafsir":"يا رسول الله ( الَّذِينَ آمَنُوا ) بقلوبهم وألسنتهم ( وَعَمِلُوا ( 1) الأنبياء : 99. الصَّالِحاتِ أَنَّ لَهُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ كُلَّما رُزِقُوا مِنْها مِنْ ثَمَرَةٍ رِزْقاً قالُوا هذَا الَّذِي رُزِقْنا مِنْ قَبْلُ وَأُتُوا بِهِ مُتَشابِهاً وَلَهُمْ فِيها أَزْواجٌ مُطَهَّرَةٌ وَهُمْ فِيها خالِدُونَ (25) الصَّالِحاتِ ) بجوارحهم ( أَنَّ لَهُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ ) الجنة باعتبار كونها بستانا ذات أشجار ونخيل ، تكون أرضها « من تحتها » فالأنهار جارية من تحت الجنة على أرضها ( كُلَّما رُزِقُوا ) أي رزق المؤمنون ( مِنْها ) أي من الجنات ( مِنْ ثَمَرَةٍ رِزْقاً ) بأن أتى لهم بفاكهة وثمرة ( قالُوا هذَا الَّذِي رُزِقْنا مِنْ قَبْلُ ) فإنهم يألفون تلك الثمار لما رأوا منها في الدنيا ، وليسوا كأصحاب الجحيم الذين لا يألفون طعامهم الذي من ضريع ، ولا شرابهم الذي من حميم ( وَأُتُوا بِهِ ) أي بذلك الرزق ( مُتَشابِهاً ) يشبه بعضه بعضا في الجودة والجدة ، لا كأثمار الدنيا ، بعضها ناضج ، وبعضها غير ناضج ، وبعضها جيد ، وبعضها رديء ( وَلَهُمْ فِيها ) أي في الجنات ( أَزْواجٌ مُطَهَّرَةٌ ) من القذارات الخلقية ، كالأوساخ والدماء ، والقذارات الخلقية ، كالسب والشتم والحسد ، ونحوها ( وَهُمْ فِيها ) أي في تلك الجنات ( خالِدُونَ ) أبدا لا يموتون ، ولا يتحولون عنها ، وحيث قسم الله الناس إلى أقسام ثلاثة ، مؤمن ومنافق وكافر ، ومثل للمنافق ، ثم أمر الناس عامة بالعبادة ، ودعاهم إلى حضيرة الإيمان ، وذكر لهم فوائده ، واحتج على من أنكر الرسالة ، أجاب عن سؤال سأله الكفار ومن إليهم تعنتا ، إِنَّ اللهَ لا يَسْتَحْيِي أَنْ يَضْرِبَ مَثَلاً ما بَعُوضَةً فَما فَوْقَها فَأَمَّا الَّذِينَ آمَنُوا فَيَعْلَمُونَ أَنَّهُ الْحَقُّ مِنْ رَبِّهِمْ وَأَمَّا الَّذِينَ كَفَرُوا فَيَقُولُونَ ما ذا أَرادَ اللهُ بِهذا مَثَلاً يُضِلُّ بِهِ كَثِيراً وَيَهْدِي بِهِ كَثِيراً وَما يُضِلُّ بِهِ وهو : أن الله لما ذا يضرب المثل ، كما مثل للمنافق هنا ، ومثل في سور أخرى بالعنكبوت ونحوها ؟ فإن المثال أوقع في النفوس ، وموجب لتقريب المطلب إلى الأذهان."},{"text":"ٱلَّذِينَ يَنقُضُونَ عَهْدَ ٱللَّهِ مِنۢ بَعْدِ مِيثَـٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفْسِدُونَ فِى ٱلْأَرْضِ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ","tafsir":"فإن الحياء من الأشياء القبيحة ، أو نحوها ، وليس في تمثيل الله الكبير بالأشياء الصغيرة الحقيرة ، في النظر حياء ، أي مثل كان ، وهذا معنى قوله « ما » أي شيئا من الأشياء ، ( بَعُوضَةً ) وهي البقة ( فَما فَوْقَها ) ولعل ذكر البعوضة هنا لأنها أصغر حيوان متعارف يراه كل أحد ( فَأَمَّا الَّذِينَ آمَنُوا فَيَعْلَمُونَ أَنَّهُ ) أي المثل ( الْحَقُّ مِنْ رَبِّهِمْ ) وأتى به لغرض التوضيح والتبيين ( وَأَمَّا الَّذِينَ كَفَرُوا فَيَقُولُونَ ) معترضين ( ما ذا أَرادَ اللهُ بِهذا مَثَلاً ) ومثلا تمييز في معنى « بهذا المثل » ولماذا يأتي الله بهذا المثل ـ غير المناسب لجلال الله ـ ف ( يُضِلُّ بِهِ كَثِيراً وَيَهْدِي بِهِ كَثِيراً ) ويوجب انقسام الناس ، ومن المحتمل أن يكون « يضل .. . » جوابا عن اعتراضهم ، أي أن المقصود من المثل الإضلال والهداية ، لكنه ينافي السياق ، فإن المقصود بالمثل ليس ذلك ، وإنما التوضيح والتقريب ( وَما يُضِلُّ بِهِ ) أي بالمثل إِلاَّ الْفاسِقِينَ (26) الَّذِينَ يَنْقُضُونَ عَهْدَ اللهِ مِنْ بَعْدِ مِيثاقِهِ وَيَقْطَعُونَ ما أَمَرَ اللهُ بِهِ أَنْ يُوصَلَ وَيُفْسِدُونَ فِي الْأَرْضِ أُولئِكَ هُمُ الْخاسِرُونَ (27) كَيْفَ تَكْفُرُونَ بِاللهِ وَكُنْتُمْ أَمْواتاً فَأَحْياكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَ (28) ( إِلَّا الْفاسِقِينَ ) الذين فسقوا أي خرجوا عن طاعة ربهم ومقتضى عقولهم ، ثم بين الفاسقين بإبراز سماتهم بقوله :"},{"text":"كَيْفَ تَكْفُرُونَ بِٱللَّهِ وَكُنتُمْ أَمْوَٰتًا فَأَحْيَـٰكُمْ ۖ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَ","tafsir":"الميثاق ما وقع التوثيق به ، وميثاق الله هو ما أخذ عليهم في الكتب السالفة من الإيمان ، أو هو ما أودع فيهم من الفطرة بعرفان الحق ( وَيَقْطَعُونَ ما أَمَرَ اللهُ بِهِ أَنْ يُوصَلَ ) من صلة الأرحام ، أو صلة الرسول والمؤمنين ( وَيُفْسِدُونَ فِي الْأَرْضِ ) بالكفر والنفاق وإتيان المحرمات ( أُولئِكَ هُمُ الْخاسِرُونَ ) الذين خسروا أعمارهم ، فذهبت دنياهم ضنكا وآخرتهم عذابا ونارا. [29] ثم عاد سبحانه إلى حال الكافر ، ووجه الخطاب إليه مستدلا على بطلان كفره بقوله : ( كَيْفَ تَكْفُرُونَ بِاللهِ وَكُنْتُمْ أَمْواتاً ) لا روح فيكم ، فإن أصل الإنسان التراب ، ثم يكون نباتا ، ثم يكون حيوانا وما أشبه ، فيأكله الإنسان ، فيتولد منه المني ، ثم يصير إنسانا ، ثم يموت ويرجع ترابا ، ثم يعاد يوم القيامة إنسانا ( فَأَحْياكُمْ ) نباتا أو حيوانا أو إنسانا ( ثُمَّ يُمِيتُكُمْ ) وقت موتكم ( ثُمَّ يُحْيِيكُمْ ) يوم القيامة ( ثُمَ ) بعد الحياة الثانية ( إِلَيْهِ تُرْجَعُونَ ) لتساقون إلى المحاكمة الكبرى ، وكون هُوَ الَّذِي خَلَقَ لَكُمْ ما فِي الْأَرْضِ جَمِيعاً ثُمَّ اسْتَوى إِلَى السَّماءِ فَسَوَّاهُنَّ سَبْعَ سَماواتٍ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ (29) وَإِذْ قالَ رَبُّكَ لِلْمَلائِكَةِ الرجوع إليه ، مع إن الإنسان في جميع الأحوال ، بدءا وختاما ، تحت سلطة الله وقدرته وعلمه ، باعتبار محاسبته تعالى للإنسان."},{"text":"هُوَ ٱلَّذِى خَلَقَ لَكُم مَّا فِى ٱلْأَرْضِ جَمِيعًا ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبْعَ سَمَـٰوَٰتٍ ۚ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ","tafsir":"يرجى تزويدنا بنص الآية وتفسيرها لإضافتها."},{"text":"وَإِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى جَاعِلٌ فِى ٱلْأَرْضِ خَلِيفَةً ۖ قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ ۖ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَ","tafsir":"لمنفعتكم ( ما فِي الْأَرْضِ جَمِيعاً ) فمن خلقها غيره ، وكون الخلق للإنسان ، لا يدل على تحليل كل شيء ، بل كل شيء بحسبه ، فالأسماك المحرمة ، والحيوانات المفترسة لتمتع السمع والبصر ، لا للأكل ونحوه وهكذا ( ثُمَّ اسْتَوى ) أي توجه بالخلق والأمر ( إِلَى السَّماءِ فَسَوَّاهُنَّ سَبْعَ سَماواتٍ ) مدارات للنجوم السيارة ، فإن السماء في اللغة بمعنى المدار ـ هذا إذا قلنا بالنظر الفعلي حول السماوات ـ ويؤيده حديث عن الإمام الرضا عليه‌السلام ـ كما في « الهيئة والإسلام » (1) ـ ( وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ ) فلا يغيب عنه شيء ، فمن كفر كان الله مطلعا عليه لا يفوته ذلك ، ولا يخفى أن خلق الأرض كان أولا ، ثم خلق السماء ، ثم دحو الأرض ، كما قال ( وَالْأَرْضَ بَعْدَ ذلِكَ دَحاها ) (2) . [31] وحيث ذكر سبحانه قصة خلق السماء والأرض ، وثم البناء ، توجه الحديث إلى من استخلف فيها ( وَ ) اذكر ( إِذْ قالَ رَبُّكَ لِلْمَلائِكَةِ ) الذين هم مخلوقين في الملإ الأعلى لا يرون بالعين إلّا لمن شاء الله ( 1) للعلامة الشهرستاني. ( 2) النازعات : 31. إِنِّي جاعِلٌ فِي الْأَرْضِ خَلِيفَةً قالُوا أَ تَجْعَلُ فِيها مَنْ يُفْسِدُ فِيها وَيَسْفِكُ الدِّماءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ قالَ إِنِّي أَعْلَمُ ما لا تَعْلَمُونَ (30) ( إِنِّي جاعِلٌ فِي الْأَرْضِ خَلِيفَةً ) يخلفني في الأمر والنهي والإرشاد ، وهذا الحوار إنما كان لأجل إظهار كوامن ، وبيان حقائق ( قالُوا أَ تَجْعَلُ فِيها ) أي في الأرض ( مَنْ يُفْسِدُ فِيها وَيَسْفِكُ الدِّماءَ ) وهذا استفهام حقيقي ، يريدون بذلك استيضاح السبب ، ولعلهم إنما علموا بذلك ، لما كانوا يدرون من كدرة الأرض وثقلها الموجبة للفساد والتكدر ، أو لما رأوا من فعل بني الجان سابقا ( وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ ) ففينا الكفاية ، وليس هذا تزكية ، بل كقول العبد المطيع لمولاه : إني أقوم بخدمتك فلما ذا تأتي بغيري الذي لا يقوم بالواجب ، ومعنى التسبيح التنزيه ، وكان المراد من التسبيح بحمده ، التنزيه المقترن بالحمد ، مقابل التنزيه غير المقترن به ، كتنزيه الجوهرة الثمينة عن النقائص ، لكن التنزيه فيها لا يقترن بالحمد ، إذ ليس ذلك باختيارها بخلافه تعالى المقترن أفعاله وأعماله بالإرادة ( وَنُقَدِّسُ لَكَ ) أي أن تقديسنا وتنزيهنا لأجلك لا يشوبه رياء وسمعة ( قالَ ) الله تعالى في جواب الملائكة السائلين عن السبب ( إِنِّي أَعْلَمُ ما لا تَعْلَمُونَ ) فإن في استخلاف البشر ، مصالح أهم من الفساد الواقع منهم ، كما أن استخلافهم أهم من استخلافكم فإن منهم من الأخيار والصالحين من لا يلحقه الملك المقرب ، بالإضافة إلى أنه خلق يظهر من عظمة الصانع نوعا جديدا. [32] وإذا أراد الله تعالى إعلام الملائكة ببعض مزايا البشر ، وإنه من جنس وَعَلَّمَ آدَمَ الْأَسْماءَ كُلَّها ثُمَّ عَرَضَهُمْ عَلَى الْمَلائِكَةِ فَقالَ أَنْبِئُونِي بِأَسْماءِ هؤُلاءِ إِنْ كُنْتُمْ صادِقِينَ (31) قالُوا سُبْحانَكَ لا عِلْمَ لَنا إِلاَّ ما أرفع منهم ، علّم آدم عليه‌السلام ، علوما يتمكن هو من فهمها وهضمها ، بينما لا يقدر الملائكة على ذلك ، ثم قال تعالى للملائكة : هل تتحملون مثل ذلك ؟ فأبدوا عجزهم ، وإذا رأوا من آدم التحمل والقدرة ، اعترفوا بالتفوق ، وإنه أحق بالخلافة ، وتوضيح ذلك بمثال أنه إذا كان لإنسان خادم لا يقدر فطرة على بناء دار جميلة ، ثم أراد استخدام مهندس ، فقال الخادم : لماذا تستخدم غيري وأنا حاضر ؟ يقول له السيد : إني أعلم ما لا تعلم ، ثم يستخدم المهندس ، ويبين له ما يريده من الدار ، فيقدر المهندس من بنائها ، بينما لا يقدر الخادم على النزول عند رغبة السيد ، وهناك يعترف بالعجز ، وأن السيد كان عارفا حيث تركه إلى غيره ( وَعَلَّمَ ) الله تعالى ( آدَمَ ) عليه‌السلام ( الْأَسْماءَ كُلَّها ) أسماء الأشياء وعلائمها ، وذلك يستلزم تعليم المسميات والمعلومات ، فإذا علمت أحدا اسم زيد وعمرو وبكر ، كان اللازم تعريفهم له أيضا ، ولذا قال ( ثُمَّ عَرَضَهُمْ عَلَى الْمَلائِكَةِ ) بإتيان ضمير « هم » تغليبا للعقلاء على غيرهم ، والعرض على الملائكة ( فَقالَ أَنْبِئُونِي بِأَسْماءِ هؤُلاءِ إِنْ كُنْتُمْ صادِقِينَ ) صدقا خبريا يطابق كلامكم الواقع في أنكم كافين في الاستخلاف ، ولعل تعليم آدم كان بالإلهام ، وخلق العلم فيه ، مما هو قابل له ، دون الملائكة ، فإنهم لم يكونوا قابلين لهذا العلم والإلهام ، فلا يقال لماذا لم يعلّم الله تعالى الملائكة."},{"text":"وَعَلَّمَ ءَادَمَ ٱلْأَسْمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى ٱلْمَلَـٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِى بِأَسْمَآءِ هَـٰٓؤُلَآءِ إِن كُنتُمْ صَـٰدِقِينَ","tafsir":"يرجى تزويدنا بنص الآية وتفسيرها لإضافتها."},{"text":"قَالُوا۟ سُبْحَـٰنَكَ لَا عِلْمَ لَنَآ إِلَّا مَا عَلَّمْتَنَآ ۖ إِنَّكَ أَنتَ ٱلْعَلِيمُ ٱلْحَكِيمُ","tafsir":"يرجى تزويدنا بنص الآية وتفسيرها لإضافتها."},{"text":"قَالَ يَـٰٓـَٔادَمُ أَنۢبِئْهُم بِأَسْمَآئِهِمْ ۖ فَلَمَّآ أَنۢبَأَهُم بِأَسْمَآئِهِمْ قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ غَيْبَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَأَعْلَمُ مَا تُبْدُونَ وَمَا كُنتُمْ تَكْتُمُونَ","tafsir":"أنت منزه عن القبيح والعبث ( لا عِلْمَ لَنا إِلَّا ما عَلَّمْتَنا إِنَّكَ أَنْتَ الْعَلِيمُ الْحَكِيمُ (32) قالَ يا آدَمُ أَنْبِئْهُمْ بِأَسْمائِهِمْ فَلَمَّا أَنْبَأَهُمْ بِأَسْمائِهِمْ قالَ أَ لَمْ أَقُلْ لَكُمْ إِنِّي أَعْلَمُ غَيْبَ السَّماواتِ وَالْأَرْضِ وَأَعْلَمُ ما تُبْدُونَ وَما كُنْتُمْ تَكْتُمُونَ (33) وَإِذْ قُلْنا لِلْمَلائِكَةِ اسْجُدُوا لِآدَمَ عَلَّمْتَنا ) فليس لنا هذا العلم الذي لآدم مما هو قابل له ، ولسنا قابلين له ( إِنَّكَ أَنْتَ الْعَلِيمُ الْحَكِيمُ ) والحكيم هو الذي يفعل الأشياء عن حكمة ، بمعنى وضع الأشياء في مواضعها اللائقة بها."},{"text":"وَإِذْ قُلْنَا لِلْمَلَـٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَـٰفِرِينَ","tafsir":"أي بأسماء ما عرضهم على الملائكة ( فَلَمَّا أَنْبَأَهُمْ بِأَسْمائِهِمْ ) وعرفت الملائكة كون قابلية آدم فوق قابليتهم ( قالَ ) الله تعالى لهم ( أَ لَمْ أَقُلْ لَكُمْ إِنِّي أَعْلَمُ غَيْبَ السَّماواتِ وَالْأَرْضِ ) ما غاب عن إدراككم ( وَأَعْلَمُ ما تُبْدُونَ ) أي تظهرون ( وَما كُنْتُمْ تَكْتُمُونَ ) من حسد بعضكم ـ وهو الشيطان ـ لآدم عليه‌السلام : ثم أن مقتضى اللطف العام والرحمة الواسعة أن يخلق الله تعالى أنواع المخلوقات الممكنة ، التي لا يمنع عن خلقها مانع ، ولذا خلق الملائكة دون البشر ، وخلق بعض كل من الصنفين أرفع من البعض الأخر ، فلا مجال للتساؤل ، فلما ذا لم يجعل الله تعالى هذه القابلية البشرية في الملائكة ؟ وثم خلق آدم عليه‌السلام ، وانتهى كل شيء."},{"text":"وَقُلْنَا يَـٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَـٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّـٰلِمِينَ","tafsir":"أذكر ( إِذْ قُلْنا لِلْمَلائِكَةِ اسْجُدُوا لِآدَمَ ) إما بأن يكون هو قبلتهم ويكون السجود لله سبحانه ، وإما أن يكون السجود لآدم ، ولا دليل عقلي على إنه لا يجوز لغير الله تعالى ، نعم ورد الشرع بذلك بالنسبة فَسَجَدُوا إِلاَّ إِبْلِيسَ أَبى وَاسْتَكْبَرَ وَكانَ مِنَ الْكافِرِينَ (34) وَقُلْنا يا آدَمُ اسْكُنْ أَنْتَ وَزَوْجُكَ الْجَنَّةَ وَكُلا مِنْها رَغَداً حَيْثُ شِئْتُما وَلا تَقْرَبا هذِهِ الشَّجَرَةَ فَتَكُونا مِنَ الظَّالِمِينَ (35) إلى المسلمين ( فَسَجَدُوا إِلَّا إِبْلِيسَ ) هو الشيطان ( أَبى وَاسْتَكْبَرَ ) أي امتنع وأنف ( وَكانَ مِنَ الْكافِرِينَ ) التفات ، كما نقول نحن « كان أبو جهل كافرا » وليس حكاية ، عطفا على « أبى » حتى يستلزم كونه كافرا من قبل ذلك."},{"text":"فَأَزَلَّهُمَا ٱلشَّيْطَـٰنُ عَنْهَا فَأَخْرَجَهُمَا مِمَّا كَانَا فِيهِ ۖ وَقُلْنَا ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ ۖ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَـٰعٌ إِلَىٰ حِينٍ","tafsir":"حواء عليها‌السلام ، قال لهما ذلك ، بعد ما خلق حواء أيضا ، خلقا كخلق آدم ابتداء من غير أب وأم ( الْجَنَّةَ ) الجنة هو البستان ، وقد كانت لله تعالى جنة أسكنها آدم وحواء ( وَكُلا مِنْها رَغَداً ) أكلا واسعا ، بلا زحمة وتكلف ( حَيْثُ شِئْتُما ) من أطراف الجنة ( وَلا تَقْرَبا هذِهِ الشَّجَرَةَ ) فقد نهوا عن شجرة واحدة ، اختبارا وامتحانا ، وكانت الشجرة على قول جمع « الحنطة » وقد كان النهي إرشاديا ، كنهي الطبيب مريضه أن لا يأكل ما يضره ، وقد كانت فائدة عدم أكلهما لها أنهما يبقيان في الجنة ، كما قال سبحانه ( إِنَّ لَكَ أَلَّا تَجُوعَ فِيها وَلا تَعْرى * وَأَنَّكَ لا تَظْمَؤُا فِيها وَلا تَضْحى ) (1) ( فَتَكُونا مِنَ الظَّالِمِينَ ) فإن الإنسان إذا حرم نفسه من الخير ، كان ظالما لها ، إذ الظلم بمعنى وضع الشيء في غير موضعه ، كما إن العدل معناه وضع الشيء موضعه. ( 1) طه : 119 و 120. فَأَزَلَّهُمَا الشَّيْطانُ عَنْها فَأَخْرَجَهُما مِمَّا كانا فِيهِ وَقُلْنَا اهْبِطُوا بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِي الْأَرْضِ مُسْتَقَرٌّ وَمَتاعٌ إِلى حِينٍ (36) فَتَلَقَّى آدَمُ مِنْ رَبِّهِ كَلِماتٍ فَتابَ عَلَيْهِ إِنَّهُ هُوَ التَّوَّابُ الرَّحِيمُ (37) قُلْنَا اهْبِطُوا مِنْها جَمِيعاً فَإِمَّا"},{"text":"فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَـٰتٍ فَتَابَ عَلَيْهِ ۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ","tafsir":"أي حمل الشيطان آدم وحواء على الزلة عن الجنة ، بسبب إنه حملهما على الأكل من الشجرة ( فَأَخْرَجَهُما مِمَّا كانا فِيهِ ) من النعيم ( وَقُلْنَا اهْبِطُوا ) الخطاب لآدم وحواء والشيطان ، والهبوط إما حقيقي ، إن كان محل أعلى إلى أسفل ، أو رتبي ( بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ ) فإن الشيطان عدوهما ، وهما عدوان له ( وَلَكُمْ فِي الْأَرْضِ مُسْتَقَرٌّ ) محل القرار ( وَمَتاعٌ ) أي استمتاع ( إِلى حِينٍ ) إلى حين انقضاء الدنيا ، أو موت كل أحد ، وإذ ارتكب آدم خلاف الأولى بأكل الشجرة ، وأهبطه الله تعالى من الجنة تداركته الرحمة."},{"text":"قُلْنَا ٱهْبِطُوا۟ مِنْهَا جَمِيعًا ۖ فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًى فَمَن تَبِعَ هُدَاىَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ","tafsir":"أي أخذ ( آدَمُ مِنْ رَبِّهِ كَلِماتٍ ) تسبب التوبة والرجوع عن الزلة ، وكان ذلك بتعليم الله تعالى له أن يجري تلك الكلمات على لسانه ، فأجراها ( فَتابَ ) الله ( عَلَيْهِ ) أي على آدم ( إِنَّهُ هُوَ التَّوَّابُ ) أي كثير القبول للتوبة ( الرَّحِيمُ ) بعباده."},{"text":"وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ","tafsir":"إنما كرر الأمر بالهبوط توطئة لموضوع آخر ، وهو أمر الهداية ، بعد ذكر المقر والمتاع ، كما يقال : قلت له اذهب تربح ، قلت له اذهب تسلم ( فَإِمَّا ) أصله « إن » الشرطية ، و « ما » يَأْتِيَنَّكُمْ مِنِّي هُدىً فَمَنْ تَبِعَ هُدايَ فَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ (38) وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بِآياتِنا أُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ (39) الزائدة ، دخلت عليها لتصحيح نون التأكيد ، يعني فإن ( يَأْتِيَنَّكُمْ ) أيها البشر الذي في صلب آدم ( مِنِّي هُدىً ) يهديكم إلى الحق ( فَمَنْ تَبِعَ هُدايَ فَلا خَوْفٌ عَلَيْهِمْ ) في الدنيا ولا في الآخرة ( وَلا هُمْ يَحْزَنُونَ ) إذ الخوف الكامل ، إنما يكون من أمر مكروه ، ولا يعوض ، وكذلك الحزن ومصائب المؤمنين تعوّض ، فلا خوف كامل منها ، والفرق بين الخوف والحزن : أن الأول لأمر مترقب ، والثاني لأمر حادث ـ غالبا ـ ولا مانع من الخطاب إلى المعدوم إذا كان المقصود منه الوصول إليه بعد وجوده ، هذا مع الغض عن عالم الذر ، كما لا مانع من الجمع بين « إن » و « نون التوكيد » إذ المعنى إن أتاكم إتيانا قطعيا مقابل الإتيان المظنون."},{"text":"يَـٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُوا۟ بِعَهْدِىٓ أُوفِ بِعَهْدِكُمْ وَإِيَّـٰىَ فَٱرْهَبُونِ","tafsir":"فلم يؤمنوا بعد أن تمت عليهم الحجة ، ولعل هذا سر قوله « كذبوا » بعد « كفروا » إذ الكفر لا يلازم التكذيب ، إذا كان عن قصور ( أُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ ) أبدا ولا يخفى أن المقصر المعاند خالد أبدا أما غيره فيمتحن هناك. [41] ولما أتم القرآن الكريم قصة « آدم » واستخلافه في الأرض ، وجه الكلام إلى « بني إسرائيل » الذين هم نموذج للجنس البشري ، وقد أتتهم يا بَنِي إِسْرائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُوا بِعَهْدِي أُوفِ بِعَهْدِكُمْ وَإِيَّايَ فَارْهَبُونِ (40) وَآمِنُوا بِما أَنْزَلْتُ مُصَدِّقاً لِما مَعَكُمْ الأنبياء عليهم‌السلام « هدى » وأنعم عليهم الله تعالى ، فكفروا بالنعم ، وقتلوا الأنبياء ، ليكون فذلكة لقصة آدم ، ودرسا لأمة محمد صلى‌الله‌عليه‌وآله‌وسلم ( يا بَنِي إِسْرائِيلَ ) هم اليهود ، وإسرائيل اسم يعقوب النبي عليه‌السلام ، نسبوا إلى أبيهم الأعلى ، كما نسب البشر إلى أبيهم الأعلى ، في قوله ( يا بَنِي آدَمَ ) (1) ( اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ ) وحيث لم يذكر المتعلق أفاد العموم ، فيشمل كل نعمة مادية أو معنوية ( وَأَوْفُوا بِعَهْدِي ) وحيث لم يذكر المتعلق أفاد كل عهد عهده ، سواء كان ذلك وقت أخذ موسى عليه‌السلام عنهم العهد بالإيمان بالرسول صلى‌الله‌عليه‌وآله‌وسلم ، أم كان وقت أخذ الله عنهم العهد في عالم الذر ، ثم أودع فيهم الفطرة دليلا عليه ( أُوفِ بِعَهْدِكُمْ ) بإعطائكم الدنيا والآخرة ، فإن الله سبحانه ضمن لمن وفي بعهده ، أن يعمر دنياه وآخرته ( وَإِيَّايَ فَارْهَبُونِ ) الرهبة هي الخوف ، يعني يجب أن يكون الخوف من الله ، لا من الناس."},{"text":"وَءَامِنُوا۟ بِمَآ أَنزَلْتُ مُصَدِّقًا لِّمَا مَعَكُمْ وَلَا تَكُونُوٓا۟ أَوَّلَ كَافِرٍۭ بِهِۦ ۖ وَلَا تَشْتَرُوا۟ بِـَٔايَـٰتِى ثَمَنًا قَلِيلًا وَإِيَّـٰىَ فَٱتَّقُونِ","tafsir":"يرجى تزويدنا بنص الآية وتفسيرها لإضافتها."},{"text":"وَلَا تَلْبِسُوا۟ ٱلْحَقَّ بِٱلْبَـٰطِلِ وَتَكْتُمُوا۟ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ","tafsir":"من القرآن ( مُصَدِّقاً لِما مَعَكُمْ ) من التوراة ، فإن التوراة الأصلية ، كانت مصدقة ، حتى في زمان النبي صلى‌الله‌عليه‌وآله‌وسلم إلا ما نسخ منها ، والنسخ ليس إبطالا لها ، كما أن نسخ بعض الأحكام في ( 1) الأعراف : 28. وَلا تَكُونُوا أَوَّلَ كافِرٍ بِهِ وَلا تَشْتَرُوا بِآياتِي ثَمَناً قَلِيلاً وَإِيَّايَ فَاتَّقُونِ (41) وَلا تَلْبِسُوا الْحَقَّ بِالْباطِلِ وَتَكْتُمُوا الْحَقَّ وَأَنْتُمْ تَعْلَمُونَ (42) القرآن ـ على القول به ـ ليس إبطالا له ( وَلا تَكُونُوا أَوَّلَ كافِرٍ بِهِ ) أي أول من يكفر بما أنزلت ، وإنما كانوا أول كافر ، لأنهم بسبب علمهم كانوا مرجعا للجهال ، فيكون كفر الجهال بمرتبة ثانية ( وَلا تَشْتَرُوا بِآياتِي ثَمَناً قَلِيلاً ) أي بمقابل آياتي ، بأن تعطوا الآيات ـ بمعنى عدم الإيمان بها ـ في مقابل ثمن قليل ، هو رئاسة الدنيا وكونها قليلا لانقطاعها ( وَإِيَّايَ فَاتَّقُونِ ) فالتقوى يجب أن تكون منه تعالى ، لا أن يكون الاتقاء من غيره ، لأن الله بيده النفع والضر دون غيره ، كما قال تعالى ( قُلْ كُلٌّ مِنْ عِنْدِ اللهِ ) (1) ."},{"text":"وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱرْكَعُوا۟ مَعَ ٱلرَّٰكِعِينَ","tafsir":"اللبس هو التعمية ، أي لا تخلطوا الحق بالباطل ، فتأخذوا ببعض التوراة الذي هو في نفعكم ، وتتركوا بعضها الذي يضركم وهو بعض الأحكام التي تركوها ، ومنها التبشير بمحمد صلى‌الله‌عليه‌وآله‌وسلم ( وَ ) لا ( تَكْتُمُوا الْحَقَ ) الذي هو أوصاف النبي صلى‌الله‌عليه‌وآله‌وسلم وبعض الأحكام الأخر ، كما قال سبحانه ( قُلْ فَأْتُوا بِالتَّوْراةِ فَاتْلُوها إِنْ كُنْتُمْ صادِقِينَ ) (2) ( وَأَنْتُمْ تَعْلَمُونَ ) بصنعكم وأنه تلبيس المحق بالباطل ، وكتمان الحق. ( 1) النساء : 79. ( 2) آل عمران : 94. وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ (43) أَ تَأْمُرُونَ النَّاسَ بِالْبِرِّ وَتَنْسَوْنَ أَنْفُسَكُمْ وَأَنْتُمْ تَتْلُونَ الْكِتابَ أَ فَلا تَعْقِلُونَ (44) وَاسْتَعِينُوا بِالصَّبْرِ وَالصَّلاةِ وَإِنَّها"},{"text":"۞ أَتَأْمُرُونَ ٱلنَّاسَ بِٱلْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنتُمْ تَتْلُونَ ٱلْكِتَـٰبَ ۚ أَفَلَا تَعْقِلُونَ","tafsir":"كما يأمر الإسلام ( وَارْكَعُوا مَعَ الرَّاكِعِينَ ) الذين هم المسلمون."},{"text":"وَٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ ۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلْخَـٰشِعِينَ","tafsir":"استفهام إنكاري ، أي لم تأمرون الناس بالأعمال الخيرية ( وَتَنْسَوْنَ أَنْفُسَكُمْ ) فلا تعملون بها والنسيان كفاية عن عدم العمل لشبهه به في النتيجة ، كما قال سبحانه ( نَسُوا اللهَ فَنَسِيَهُمْ ) (1) فقد كان اليهود يخالفون أحكام التوراة ، ويرتشون ويفسدون ويكذبون ( وَأَنْتُمْ تَتْلُونَ الْكِتابَ ) جملة حالية ، أي والحال أنتم تقرءون كتاب الله ، فاللازم أن تكونوا أول العاملين به ( أَ فَلا تَعْقِلُونَ ) أي ألا تعلمون أن ما تأتون به قبيح ؟."},{"text":"ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَـٰقُوا۟ رَبِّهِمْ وَأَنَّهُمْ إِلَيْهِ رَٰجِعُونَ","tafsir":"في رجوعكم عن دينكم وإلغائكم لرؤسائكم ـ بما يجر ذلك عليكم من سلب بعض دنياكم ـ ( بِالصَّبْرِ ) فإنكم إذا صبرتم على ما تكرهون من اتباع النبي صلى‌الله‌عليه‌وآله‌وسلم عاد ذلك عليكم بخير مما أنتم فيه ( وَالصَّلاةِ ) فإن الصلاة توجب تهدئة النفس ، واطمئنان الخاطر ( أَلا بِذِكْرِ اللهِ تَطْمَئِنُّ الْقُلُوبُ ) (2) ( وَإِنَّها ) أي الاستعانة بالصبر والصلاة ( 1) التوبة : 67. ( 2) الرعد : 29. لَكَبِيرَةٌ إِلاَّ عَلَى الْخاشِعِينَ (45) الَّذِينَ يَظُنُّونَ أَنَّهُمْ مُلاقُوا رَبِّهِمْ وَأَنَّهُمْ إِلَيْهِ راجِعُونَ (46) يا بَنِي إِسْرائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعالَمِينَ (47) ( لَكَبِيرَةٌ إِلَّا عَلَى الْخاشِعِينَ ) فإن الصبر ليس أمرا هينا ، والصلاة الكاملة ليست عملا سهلا ، وإنما قيدنا الصلاة بالكاملة ، لأنها هي التي يستعان بها ، أو أن المراد الصلوات اليومية ، وهي صعبة جدا إلا على الذين يخشون الله سبحانه. [47] ثم فسر الخاشعين بأنهم ( الَّذِينَ يَظُنُّونَ أَنَّهُمْ مُلاقُوا رَبِّهِمْ ) الظن إما بمعنى اليقين ، وإما بمعنى الرجحان ، ولعل السر في هذا التعبير دون اليقين ، للإشارة إلى أدنى مراتب الرجحان يوجب الخشوع ، فإن من يظن أنه يلاقي الملك لبعثه ذلك على التهيئة ، فكيف بمن يظن أنه يلاقي مالك الملوك ، وملاقاة الله كناية عن الحضور للمحاسبة ، وإلا فالله سبحانه ليس أدنى إلى الناس في القيامة منه إليهم في الدنيا ( وَأَنَّهُمْ إِلَيْهِ راجِعُونَ ) والرجوع إليه معنوي كما تقدم."},{"text":"يَـٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَـٰلَمِينَ","tafsir":"يرجى تزويدنا بنص الآية وتفسيرها لإضافتها."},{"text":"وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا شَفَـٰعَةٌ وَلَا يُؤْخَذُ مِنْهَا عَدْلٌ وَلَا هُمْ يُنصَرُونَ","tafsir":"تكرار للتركيز والإلفات ، فإن الإنسان ربما كان غافلا حين التذكير الأول ، فيذكر ثانيا وثالثا ، بالإضافة إلى أن النفس ، إذا كررت عليها الموعظة ، رسخت فيها ( وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعالَمِينَ ) التفضيل على عالم زمانهم لا على كل العوالم ، فإن الظاهر من هكذا تفضيلات هو الاختصاص ، فلو قيل أن « الدولة الفلانية أقوى الدول » لم يفهم منه إلا وَاتَّقُوا يَوْماً لا تَجْزِي نَفْسٌ عَنْ نَفْسٍ شَيْئاً وَلا يُقْبَلُ مِنْها شَفاعَةٌ وَلا يُؤْخَذُ مِنْها عَدْلٌ وَلا هُمْ يُنْصَرُونَ (48) وَإِذْ نَجَّيْناكُمْ مِنْ آلِ فِرْعَوْنَ الإقوائية من الدول المعاصرة لها ، لأكل دولة أتت أو تأتي ، ثم أن تفضيلهم على العالمين إنما كان لأجل إيمانهم بموسى عليه‌السلام ، بينما كان العالم بين كافر به عنادا ، كفرعون ومن تبعه ، أو جهلا كمن كان في البلاد البعيدة التي لم تبلغهم دعوة موسى فكانوا قاصرين."},{"text":"وَإِذْ نَجَّيْنَـٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ ۚ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ","tafsir":"أي لا تغني ، فلا تدفع نفس عن نفس مكروها ، وإنما الأمر كله لله ، حتى أن الشفاعة تكون بإذنه ، والمراد بذلك اليوم ـ القيامة ـ ومعنى التقوى منه الاستعداد له ( وَلا يُقْبَلُ مِنْها ) أي من النفس ( شَفاعَةٌ ) إلا إذا أذن الله للشفيع ( وَلا يُؤْخَذُ مِنْها ) أي من النفس ( عَدْلٌ ) أي فدية ، وإنما سميت الفدية عدلا ، لأنها تعادل المفدى ( وَلا هُمْ يُنْصَرُونَ ) فإن طريق الخلاص في الدنيا إحدى هذه الأربعة ، وليست شيء منها في الآخرة ، إلا إذا أذن الله في الشفاعة ، وعدم الاستثناء من « شفاعة » لأجل أن المراد منها الشفاعات الارتجالية ، كما هو المعتاد في الدنيا."},{"text":"وَإِذْ فَرَقْنَا بِكُمُ ٱلْبَحْرَ فَأَنجَيْنَـٰكُمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ وَأَنتُمْ تَنظُرُونَ","tafsir":"اذكروا يا بني إسرائيل نعمة أنعمناها عليكم ( إِذْ نَجَّيْناكُمْ مِنْ آلِ فِرْعَوْنَ ) ومن المتعارف ، أن ينسب الشيء المرتبط ببعض الأمة إلى جميعها ، إذ يجمعهم العطف والهدى والانتصار ، فيقال بنو تميم قتلوا فلانا ، وإنما قتله بعضهم ، أو عشيرة فلان شجعان ، وإنما جماعة منهم كذلك ، ولذا قال سبحانه « نجيناكم » وقد كانت التنجية بالنسبة إلى يَسُومُونَكُمْ سُوءَ الْعَذابِ يُذَبِّحُونَ أَبْناءَكُمْ وَيَسْتَحْيُونَ نِساءَكُمْ وَفِي ذلِكُمْ بَلاءٌ مِنْ رَبِّكُمْ عَظِيمٌ (49) وَإِذْ فَرَقْنا بِكُمُ الْبَحْرَ أسلافهم ، والمراد بآل الرجل قومه وخواصه وإن لم تكن بينهم قرابة ، كما يقال « آل الله » لأهل البيت عليهم‌السلام ( يَسُومُونَكُمْ سُوءَ الْعَذابِ ) وسامه خسفا عذابا بمعنى ألقاه فيه ، ثم فسر سوء العذاب بقوله ( يُذَبِّحُونَ أَبْناءَكُمْ ) التذبيح هو التكثير في الذبح ( وَيَسْتَحْيُونَ نِساءَكُمْ ) أي يدعونهن أحياء ، فإن فرعون ملك القبط ، لما علم من الكهان ، أنه يولد في بني إسرائيل ـ الذين كانوا طائفة خاصة من آل يعقوب عليهم‌السلام ـ أمر بذبح الأولاد وإبقاء النساء للاسترقاق والنكاح ( وَفِي ذلِكُمْ ) « كم » خطاب فقط ، و « ذا » إشارة ، فإذا كان طرف الخطاب واحد يقال « ذلك » وإذا كان اثنين يقال « ذلكما » وإذا كانوا جماعة يقال « ذلكم » و « ذا » هنا اسم إشارة إلى سوء العذاب ( بَلاءٌ مِنْ رَبِّكُمْ عَظِيمٌ ) أنها كانت بالنسبة إلى الله تعالى ، لأنه لم يحل بين فرعون ، وبين هذا العمل ، كما يقال ، إن الأب أفسد ولده إذا لم يحل بينه وبين عمله الفاسد ، وعدم حيلولة الله تعالى ، لأجل الامتحان والاختبار ـ كما تقدم ـ والإنجاء ، إنما كان بإهلاك فرعون وقومه."},{"text":"وَإِذْ وَٰعَدْنَا مُوسَىٰٓ أَرْبَعِينَ لَيْلَةً ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَـٰلِمُونَ","tafsir":"اذكروا يا بني إسرائيل ( إِذْ فَرَقْنا بِكُمُ الْبَحْرَ ) أي جعلنا فواصل في البحر ، حتى صارت بين الماء شوارع ، وكان عملنا هذا بسببكم ولأجلكم ، والمراد بالبحر ـ البحر الأحمر في مصر ـ وقد كان طول فَأَنْجَيْناكُمْ وَأَغْرَقْنا آلَ فِرْعَوْنَ وَأَنْتُمْ تَنْظُرُونَ (50) وَإِذْ واعَدْنا مُوسى أَرْبَعِينَ لَيْلَةً ثُمَّ اتَّخَذْتُمُ الْعِجْلَ مِنْ بَعْدِهِ الشوارع التي أسفرت عنها الماء ما يقرب من أربعة فراسخ ، فإن موسى عليه‌السلام وبني إسرائيل فروا من فرعون فوصلوا إلى البحر وعقبهم فرعون وقومه ، فأمر الله موسى عليه‌السلام أن يضرب بعصاه البحر ، فضرب فانحسر الماء عن الشوارع حتى عبر بنوا إسرائيل ، وأتبعهم فرعون وجنوده ولما توسطوا الماء ، وخرج موسى عليه‌السلام وقومه ، رجع الماء إلى حالته الأولية ، فأغرق فرعون وقومه ( فَأَنْجَيْناكُمْ ) من عدوكم ( وَأَغْرَقْنا آلَ فِرْعَوْنَ ) مع فرعون ، ولم يذكر تغليبا للآل عليه ( وَأَنْتُمْ تَنْظُرُونَ ) كيف أغرقناهم لأجلكم ، ولا يخفى أن الإعجاز هين بالنسبة إلى الله سبحانه ، فتأويل بعض الناس للمعاجز انهزام مادي غربي."},{"text":"ثُمَّ عَفَوْنَا عَنكُم مِّنۢ بَعْدِ ذَٰلِكَ لَعَلَّكُمْ تَشْكُرُونَ","tafsir":"اذكروا يا بني إسرائيل ( إِذْ واعَدْنا مُوسى أَرْبَعِينَ لَيْلَةً ) واعد بمعنى وعد ، وإن موسى عليه‌السلام قبل ، ولذا جيء بصيغة المفاعلة ، ولا ينافي كون الوعد هنا أربعين ليلة ، وفي آية أخرى ثلاثين ، فإن هذه الآية بالنسبة إلى الوعدين ، وفي الآية الأخرى بالنسبة إلى الوعد الأول ، فقد كان الله سبحانه وعد موسى أولا ثلاثين ، ثم مدده وأضاف عشرا ، والوعد كان لإعطاء الثروة التي فيها أحكام الله ، وتنظيم أمور بني إسرائيل الذي هو نعمة عظيمة ( ثُمَّ اتَّخَذْتُمُ الْعِجْلَ مِنْ بَعْدِهِ ) ، أي من بعد موسى عليه‌السلام أي وقت ذهابه إلى الطور للوعد ، فإنهم بعد ما ذهب موسى عليه‌السلام ، لميقات ربه صنعوا عجلا من ذهب ، وجعلوه إلها لهم وسجدوا له ، فقابلوا نعم الله عليهم بالكفران ، وعبادة العجل. وَأَنْتُمْ ظالِمُونَ (51) ثُمَّ عَفَوْنا عَنْكُمْ مِنْ بَعْدِ ذلِكَ لَعَلَّكُمْ تَشْكُرُونَ (52) وَإِذْ آتَيْنا مُوسَى الْكِتابَ وَالْفُرْقانَ لَعَلَّكُمْ تَهْتَدُونَ (53) وَإِذْ قالَ مُوسى لِقَوْمِهِ يا قَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنْفُسَكُمْ بِاتِّخاذِكُمُ الْعِجْلَ فَتُوبُوا إِلى بارِئِكُمْ فَاقْتُلُوا أَنْفُسَكُمْ ذلِكُمْ ( وَأَنْتُمْ ظالِمُونَ ) جملة حالية ، والمراد ظلمهم بأنفسهم."},{"text":"وَإِذْ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ وَٱلْفُرْقَانَ لَعَلَّكُمْ تَهْتَدُونَ","tafsir":"عبادتكم للعجل ( مِنْ بَعْدِ ذلِكَ ) الاتخاذ ( لَعَلَّكُمْ تَشْكُرُونَ ) نعمنا عليكم ، فتعملوا بأوامرنا."},{"text":"وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَـٰقَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلْعِجْلَ فَتُوبُوٓا۟ إِلَىٰ بَارِئِكُمْ فَٱقْتُلُوٓا۟ أَنفُسَكُمْ ذَٰلِكُمْ خَيْرٌ لَّكُمْ عِندَ بَارِئِكُمْ فَتَابَ عَلَيْكُمْ ۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ","tafsir":"اذكروا يا بني إسرائيل ( إِذْ آتَيْنا مُوسَى ) نبيكم ( الْكِتابَ ) وهو التوراة ( وَالْفُرْقانَ ) أي الفارق بين الحق والباطل ، فهو أهم من الكتاب ( لَعَلَّكُمْ تَهْتَدُونَ ) ولعل ليس ترجيا من الله سبحانه بل بمعنى عاقبة الترجي."},{"text":"وَإِذْ قُلْتُمْ يَـٰمُوسَىٰ لَن نُّؤْمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهْرَةً فَأَخَذَتْكُمُ ٱلصَّـٰعِقَةُ وَأَنتُمْ تَنظُرُونَ","tafsir":"اذكروا يا بني إسرائيل ( إِذْ قالَ مُوسى لِقَوْمِهِ ) الذين عبدوا العجل وقت ذهاب موسى إلى الطور لتلقي التوراة والأوامر من الله سبحانه ( يا قَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنْفُسَكُمْ بِاتِّخاذِكُمُ الْعِجْلَ ) إلها فإن اتخاذه موجب للغضب والذلة في الحياة الدنيا والآخرة ( فَتُوبُوا ) توبة ( إِلى بارِئِكُمْ ) الذي برءكم وخلقكم وهو إلهكم ( فَاقْتُلُوا أَنْفُسَكُمْ ) بأن يقتل من لم يعبد العجل من عبده ولو كان قريبا له ، فإنه كفارة للقاتل حيث سكت ولم يتكلم ، وللمقتول حيث عبد العجل ( ذلِكُمْ ) القتل خَيْرٌ لَكُمْ عِنْدَ بارِئِكُمْ فَتابَ عَلَيْكُمْ إِنَّهُ هُوَ التَّوَّابُ الرَّحِيمُ (54) وَإِذْ قُلْتُمْ يا مُوسى لَنْ نُؤْمِنَ لَكَ حَتَّى نَرَى اللهَ جَهْرَةً فَأَخَذَتْكُمُ الصَّاعِقَةُ وَأَنْتُمْ تَنْظُرُونَ (55) ثُمَّ بَعَثْناكُمْ ( خَيْرٌ لَكُمْ ) إذ الألم القليل خير من عذاب النار الدائم ( عِنْدَ بارِئِكُمْ ) متعلق بخير ، أي إن هذا العمل خير عند الله تعالى ، وفي حكمه وإرادته ، وذلك مقابل الخير عند الناس الذي هو بالبقاء والعيش في الدنيا ( فَتابَ عَلَيْكُمْ ) بعد ما سمعتم الأمر بأن تبتم ، وقتل بعضكم بعضا ، ومعنى تاب عليكم ، قبل توبتكم ( إِنَّهُ هُوَ التَّوَّابُ الرَّحِيمُ ) بكم ، فلم يغضب حتى لا يقبل توبتكم أبدا."},{"text":"ثُمَّ بَعَثْنَـٰكُم مِّنۢ بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ","tafsir":"اذكروا يا بني إسرائيل ( إِذْ قُلْتُمْ يا مُوسى لَنْ نُؤْمِنَ لَكَ ) بأن لنا إلها خلقنا وبيده أمورنا ، أو لن نؤمن لك بأنك نبي مبعوث من قبل الله سبحانه ( حَتَّى نَرَى اللهَ جَهْرَةً ) أي علانية وعيانا ، فيخبرنا بذلك ، وذلك أن موسى عليه‌السلام اختار من قومه سبعين رجلا يحضرون معه إلى الميقات ، لما طلبت بنو إسرائيل منه ذلك ، ولما جاءوا طلبوا رؤية الله تعالى ( فَأَخَذَتْكُمُ الصَّاعِقَةُ ) وهي نار تنزل من السماء ، أو مادة مذابة من المعدن ونحوه ، فتصيب الإنسان فتقتله ، فإنهم لما طلبوا رؤية الله سبحانه ، نزلت صاعقة من السماء فقتلتهم جميعا ( وَأَنْتُمْ تَنْظُرُونَ ) حال نزولها ، وسبب موتكم ، فكان ذلك دليلا لكم على ذنبكم وخطإكم ولم يكن موتا لم يعرف سببه حتى تقولوا إنه أمر طبيعي."},{"text":"وَظَلَّلْنَا عَلَيْكُمُ ٱلْغَمَامَ وَأَنزَلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ ۖ كُلُوا۟ مِن طَيِّبَـٰتِ مَا رَزَقْنَـٰكُمْ ۖ وَمَا ظَلَمُونَا وَلَـٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ","tafsir":"أي أحييناكم لما طلب موسى عليه‌السلام ذلك لئلا يقول مِنْ بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ (56) وَظَلَّلْنا عَلَيْكُمُ الْغَمامَ وَأَنْزَلْنا عَلَيْكُمُ الْمَنَّ وَالسَّلْوى كُلُوا مِنْ طَيِّباتِ ما رَزَقْناكُمْ وَما ظَلَمُونا وَلكِنْ كانُوا أَنْفُسَهُمْ يَظْلِمُونَ (57) وَإِذْ قُلْنَا ادْخُلُوا هذِهِ الْقَرْيَةَ فَكُلُوا مِنْها حَيْثُ شِئْتُمْ الباقي من بني إسرائيل ، إنه عليه‌السلام قتلهم في الطور ( مِنْ بَعْدِ مَوْتِكُمْ ) بسبب الصاعقة ( لَعَلَّكُمْ تَشْكُرُونَ ) نعمنا عليكم."},{"text":"وَإِذْ قُلْنَا ٱدْخُلُوا۟ هَـٰذِهِ ٱلْقَرْيَةَ فَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ رَغَدًا وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا وَقُولُوا۟ حِطَّةٌ نَّغْفِرْ لَكُمْ خَطَـٰيَـٰكُمْ ۚ وَسَنَزِيدُ ٱلْمُحْسِنِينَ","tafsir":"اذكروا يا بني إسرائيل ، إذ كنتم في « التيه » حين أمرتم بحرب العمالقة فعصيتم فبقيتم في الصحراء مدة مديدة ، وكنتم تتأذون من حر الشمس ، ولم يكن لكم مأكل ف ( ظَلَّلْنا عَلَيْكُمُ الْغَمامَ ) بأن جعلناه سترة لكم تقيكم حر الشمس وبرد القمر ( وَأَنْزَلْنا عَلَيْكُمُ الْمَنَّ وَالسَّلْوى ) المن شيء يشبه « الترنجبين » مادة حلوة ، كانت تقع على أشجارهم فيأكلوها والسلوى طير السماني ، وإنزال السماني ، إما بكون هذا الطير ، كان كثيرا في التيه ، فكانوا يصطادونه ، أو بأنه كان ينزل عليهم الطير المشوي ، وقلنا لكم ( كُلُوا مِنْ طَيِّباتِ ما رَزَقْناكُمْ ) طيب مذاقا ، وحقيقة لكونه حلالا ، لكنهم كفروا بعد كل هذه النعم ( وَما ظَلَمُونا ) بكفرانهم ، فإنهم لن يضروا الله شيئا ( وَلكِنْ كانُوا أَنْفُسَهُمْ يَظْلِمُونَ ) لأنهم أورثوا لأنفسهم ذلة في الدنيا وعذابا في الآخرة."},{"text":"فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَنزَلْنَا عَلَى ٱلَّذِينَ ظَلَمُوا۟ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَفْسُقُونَ","tafsir":"اذكروا يا بني إسرائيل ( إِذْ قُلْنَا ) لكم بعد أن خرجتم عن التيه ( ادْخُلُوا هذِهِ الْقَرْيَةَ ) بيت المقدس ، أو « أريحا » وهي بلدة قريبة من بيت المقدس ( فَكُلُوا مِنْها حَيْثُ شِئْتُمْ ) من الأماكن أو المآكل رَغَداً وَادْخُلُوا الْبابَ سُجَّداً وَقُولُوا حِطَّةٌ نَغْفِرْ لَكُمْ خَطاياكُمْ وَسَنَزِيدُ الْمُحْسِنِينَ (58) فَبَدَّلَ الَّذِينَ ظَلَمُوا قَوْلاً غَيْرَ الَّذِي قِيلَ لَهُمْ فَأَنْزَلْنا عَلَى الَّذِينَ ظَلَمُوا رِجْزاً مِنَ السَّماءِ بِما كانُوا يَفْسُقُونَ (59) وَإِذِ اسْتَسْقى مُوسى لِقَوْمِهِ ( رَغَداً ) واسعا ( وَادْخُلُوا الْبابَ ) أي باب القرية ( سُجَّداً ) جمع ساجد ، أي في حال كونكم ساجدين ( وَقُولُوا حِطَّةٌ ) أي سجودنا لله حطة لذنوبنا ، ومحو لسيئاتنا ، فإن فعلتم ذلك ( نَغْفِرْ لَكُمْ خَطاياكُمْ ) السالفة ( وَسَنَزِيدُ الْمُحْسِنِينَ ) منكم من خير الدنيا وخير الآخرة على ما يستحقون ، كما قال سبحانه ( لِيُوَفِّيَهُمْ أُجُورَهُمْ وَيَزِيدَهُمْ مِنْ فَضْلِهِ ) (1) ."},{"text":"۞ وَإِذِ ٱسْتَسْقَىٰ مُوسَىٰ لِقَوْمِهِۦ فَقُلْنَا ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ ۖ فَٱنفَجَرَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًا ۖ قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ ۖ كُلُوا۟ وَٱشْرَبُوا۟ مِن رِّزْقِ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ","tafsir":"فقالوا « حنطة حمراء خير لنا » عوض « حطة » كما إنهم دخلوا بأستاهم عوض أن يدخلوا سجدا ( فَأَنْزَلْنا عَلَى الَّذِينَ ظَلَمُوا ) فيما فعلوا ( رِجْزاً مِنَ السَّماءِ ) الرجز العذاب ( بِما كانُوا يَفْسُقُونَ ) أي بسبب عصيانهم."},{"text":"وَإِذْ قُلْتُمْ يَـٰمُوسَىٰ لَن نَّصْبِرَ عَلَىٰ طَعَامٍ وَٰحِدٍ فَٱدْعُ لَنَا رَبَّكَ يُخْرِجْ لَنَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ مِنۢ بَقْلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا ۖ قَالَ أَتَسْتَبْدِلُونَ ٱلَّذِى هُوَ أَدْنَىٰ بِٱلَّذِى هُوَ خَيْرٌ ۚ ٱهْبِطُوا۟ مِصْرًا فَإِنَّ لَكُم مَّا سَأَلْتُمْ ۗ وَضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ وَٱلْمَسْكَنَةُ وَبَآءُو بِغَضَبٍ مِّنَ ٱللَّهِ ۗ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيْرِ ٱلْحَقِّ ۗ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ","tafsir":"اذكروا يا بني إسرائيل ( إِذِ اسْتَسْقى مُوسى لِقَوْمِهِ ) أي سأل موسى عليه‌السلام من الله تعالى أن يسقيهم ، وذلك حين كانوا في التيه ، ( 1) فاطر : 31. فَقُلْنَا اضْرِبْ بِعَصاكَ الْحَجَرَ فَانْفَجَرَتْ مِنْهُ اثْنَتا عَشْرَةَ عَيْناً قَدْ عَلِمَ كُلُّ أُناسٍ مَشْرَبَهُمْ كُلُوا وَاشْرَبُوا مِنْ رِزْقِ اللهِ وَلا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ (60) وَإِذْ قُلْتُمْ يا مُوسى لَنْ نَصْبِرَ عَلى طَعامٍ واحِدٍ فَادْعُ لَنا رَبَّكَ يُخْرِجْ لَنا مِمَّا تُنْبِتُ الْأَرْضُ مِنْ بَقْلِها وَقِثَّائِها وَفُومِها وَعَدَسِها وَبَصَلِها ولم يكن لهم ماء فظمئوا ( فَقُلْنَا اضْرِبْ بِعَصاكَ الْحَجَرَ ) وعصاه هي التي صارت ثعبانا ، والحجر ، إما كان حجرا خاصا ، أو مطلق الحجر ( فَانْفَجَرَتْ مِنْهُ اثْنَتا عَشْرَةَ عَيْناً ) بعدد أسباط بني إسرائيل ، فإنهم كانوا اثنتي عشرة قبيلة ، فكانت تجري لكل قبيلة عين ( قَدْ عَلِمَ كُلُّ أُناسٍ ) أي كل قبيلة ( مَشْرَبَهُمْ ) أي موضع شربهم ( كُلُوا وَاشْرَبُوا مِنْ رِزْقِ اللهِ ) أكلهم المن والسلوى ، وشربهم ماء العين المنفجر ( وَلا تَعْثَوْا فِي الْأَرْضِ ) الفساد ( مُفْسِدِينَ ) حالة مؤكدة."},{"text":"إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلنَّصَـٰرَىٰ وَٱلصَّـٰبِـِٔينَ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَعَمِلَ صَـٰلِحًا فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ","tafsir":"حين كنتم في التيه ، وينزل عليكم المن والسلوى ( لَنْ نَصْبِرَ عَلى طَعامٍ واحِدٍ ) أي قسم واحد من الطعام ، ولو كان ذي لونين ، فالمراد بالوحدة التكرر في كل يوم ( فَادْعُ ) أي فاسأل ( لَنا ) أي لأجلنا ( رَبَّكَ يُخْرِجْ لَنا مِمَّا تُنْبِتُ الْأَرْضُ ) أي من نباتها ( مِنْ بَقْلِها ) البقل أنواع الخضر ( وَقِثَّائِها ) الخيار ( وَفُومِها ) الحنطة ( وَعَدَسِها وَبَصَلِها ) حتى نتقوت بها ونأكلها عوض قالَ أَ تَسْتَبْدِلُونَ الَّذِي هُوَ أَدْنى بِالَّذِي هُوَ خَيْرٌ اهْبِطُوا مِصْراً فَإِنَّ لَكُمْ ما سَأَلْتُمْ وَضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ وَالْمَسْكَنَةُ وَباؤُ بِغَضَبٍ مِنَ اللهِ ذلِكَ بِأَنَّهُمْ كانُوا يَكْفُرُونَ بِآياتِ اللهِ المن والسلوى ( قالَ ) لهم موسى عليه‌السلام ( أَ تَسْتَبْدِلُونَ الَّذِي هُوَ أَدْنى بِالَّذِي هُوَ خَيْرٌ ) أي تتركون ما هو الأفضل مما اختاره الله لكم ، إلى ما هو الأدون مما ترغبون إليه ، وكونها أفضل وأدون ، أما باعتبار السهولة والصعوبة ، أو باعتبار الطعم واللذة ، أو باعتبار التقوية والتغذية ، وعلى أي حال ، دعا موسى واستجاب الله دعاءه ، وقال لهم ( اهْبِطُوا مِصْراً ) من الأمصار ( فَإِنَّ لَكُمْ ) في المصر ( ما سَأَلْتُمْ ) من الأطعمة ( وَ ) لكن اليهود بسبب تمردهم وعصيانهم ولجاجتهم المستمرة ( ضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ ) فهم أذلاء في الأرض لا حكومة لهم مستقلة ولا عزة لهم عند الناس ( وَالْمَسْكَنَةُ ) فإنهم مع ثروتهم أحيانا لا يفارقون المسكنة ، حيث إنهم دائمو التشكّي لمخافتهم من الفقر ، وهذه الآية من معاجز القرآن الكثيرة ، فإن اليهود لم تقم لهم حكومة من تاريخ القرآن إلى هذا اليوم ، إلا بحبل من الناس ، واتصال بالحكومات القوية ( وَباؤُ بِغَضَبٍ مِنَ اللهِ ) باء أي رجع ، والمراد أنهم بعملهم السيئ غضب الله عليهم ( ذلِكَ ) المذكور من ضرب الذلة والمسكنة ، والرجوع بالغضب بسبب أنهم ( كانُوا يَكْفُرُونَ بِآياتِ اللهِ ) المنزلة على موسى عليه‌السلام حيث لم يكونوا يطيعون وَيَقْتُلُونَ النَّبِيِّينَ بِغَيْرِ الْحَقِّ ذلِكَ بِما عَصَوْا وَكانُوا يَعْتَدُونَ (61) إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هادُوا وَالنَّصارى وَالصَّابِئِينَ مَنْ آمَنَ بِاللهِ وَالْيَوْمِ الْآخِرِ وَعَمِلَ صالِحاً فَلَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ (62) وَإِذْ أَخَذْنا مِيثاقَكُمْ ( وَيَقْتُلُونَ النَّبِيِّينَ ) فإن الأنبياء تواترت إليهم لكثرة لجاجتهم ، فكانوا يقتلونهم ، وقوله تعالى ( بِغَيْرِ الْحَقِ ) قيد توضيحي ، إذ لا يكون قتل النبي حقا أبدا ، وذلك بخلاف ما لو قيل يقتل البشر بغير الحق ( ذلِكَ ) المذكور من كفرانهم وقتلهم الأنبياء ( بِما عَصَوْا ) أي بسبب عصيانهم للأوامر العقلية والشرعية ( وَكانُوا يَعْتَدُونَ ) فإن عصيانهم واعتداءهم صار سببا للقتل والكفر ، وهما سببا ضرب الذلة والمسكنة والغضب."},{"text":"وَإِذْ أَخَذْنَا مِيثَـٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَـٰكُم بِقُوَّةٍ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ","tafsir":"من المسلمين ( وَالَّذِينَ هادُوا ) أي صاروا يهودا باليهودية ( وَالنَّصارى ) المؤمنين بعيسى عليه‌السلام ( وَالصَّابِئِينَ ) وفيهم غموض وخلاف ، وربما قيل أنهم عبدة النجوم ( مَنْ آمَنَ بِاللهِ وَالْيَوْمِ الْآخِرِ ) حقيقة ( وَعَمِلَ صالِحاً ) مما أمر به الله سبحانه ( فَلَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلا خَوْفٌ عَلَيْهِمْ ) لا في الدنيا ولا في الآخرة ـ كما تقدم ـ ( وَلا هُمْ يَحْزَنُونَ ) فلا ييأس أحد من روح الله ما دام في الدنيا ، وإنما قيدنا « من آمن » ب « حقيقة » لئلا ينافي ما في صدر الآية ( إِنَّ الَّذِينَ آمَنُوا ) ."},{"text":"ثُمَّ تَوَلَّيْتُم مِّنۢ بَعْدِ ذَٰلِكَ ۖ فَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَكُنتُم مِّنَ ٱلْخَـٰسِرِينَ","tafsir":"اذكروا يا بني إسرائيل ( إِذْ أَخَذْنا مِيثاقَكُمْ ) العهد الشديد ، وقد وَرَفَعْنا فَوْقَكُمُ الطُّورَ خُذُوا ما آتَيْناكُمْ بِقُوَّةٍ وَاذْكُرُوا ما فِيهِ لَعَلَّكُمْ تَتَّقُونَ (63) ثُمَّ تَوَلَّيْتُمْ مِنْ بَعْدِ ذلِكَ فَلَوْ لا فَضْلُ اللهِ عَلَيْكُمْ وَرَحْمَتُهُ لَكُنْتُمْ مِنَ الْخاسِرِينَ (64) وَلَقَدْ عَلِمْتُمُ الَّذِينَ اعْتَدَوْا مِنْكُمْ فِي السَّبْتِ تقدم مكان أخذ العهد ( وَرَفَعْنا فَوْقَكُمُ الطُّورَ ) وذلك أن موسى عليه‌السلام لما جاءهم بالتوراة لم يقبلوها ، فقطع جبرائيل عليه‌السلام قطعة من جبل طور ورفعها فوق رؤوسهم مهددا ، إنهم إن لم يقبلوا التوراة قذفها على رؤوسهم ، فقبلوا قبول التوراة مجبرين ، وقلنا لكم ( خُذُوا ما آتَيْناكُمْ بِقُوَّةٍ ) أي بجد ويقين وشدة لا تحيدوا عنه ( وَاذْكُرُوا ) أي احفظوا واعملوا ب ( ما فِيهِ ) أي في « ما آتيناكم » وهو التوراة ( لَعَلَّكُمْ تَتَّقُونَ ) أي كي تخافون ، فإن العامل بأوامر الله سبحانه يكون خائفا متقيا."},{"text":"وَلَقَدْ عَلِمْتُمُ ٱلَّذِينَ ٱعْتَدَوْا۟ مِنكُمْ فِى ٱلسَّبْتِ فَقُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَـٰسِـِٔينَ","tafsir":"أي أعرضتم أيها اليهود ( مِنْ بَعْدِ ذلِكَ ) الميثاق الأكيد ، فلم تعملوا بما في التوراة ، ولم تتمثلوا أوامرنا ( فَلَوْ لا فَضْلُ اللهِ عَلَيْكُمْ ) حيث تفضل عليكم بالتوبة ( وَرَحْمَتُهُ ) بأن رحمكم فلم يؤاخذكم بسيئات عملكم ( لَكُنْتُمْ مِنَ الْخاسِرِينَ ) في الدنيا والآخرة ، فإن من ينسلخ عنه الإيمان يكون من أخسر الناس."},{"text":"فَجَعَلْنَـٰهَا نَكَـٰلًا لِّمَا بَيْنَ يَدَيْهَا وَمَا خَلْفَهَا وَمَوْعِظَةً لِّلْمُتَّقِينَ","tafsir":"أي عرفتم أيها اليهود ( الَّذِينَ اعْتَدَوْا مِنْكُمْ فِي السَّبْتِ ) أي جاوزوا حدود الله فيه ، وذلك أنهم حرم عليهم اصطياد السمك في السبت فكانت الأسماك تأتي وتتجمع في هذا اليوم فَقُلْنا لَهُمْ كُونُوا قِرَدَةً خاسِئِينَ (65) فَجَعَلْناها نَكالاً لِما بَيْنَ يَدَيْها وَما خَلْفَها وَمَوْعِظَةً لِلْمُتَّقِينَ (66) وَإِذْ قالَ مُوسى لشعورها بأمنها في هذا اليوم ، فكان اليهود يحتالون لأخذها بإيصال الماء إلى أحواضهم ، فلما تأتي إليها الأسماك يوم السبت سدوا طريقها ، ثم يصطادونها يوم الأحد ، وكان هذا خرقا لحرمات الله ( فَقُلْنا لَهُمْ ) أي للمعتدين ( كُونُوا قِرَدَةً خاسِئِينَ ) أي مبعدين عن الخير دنيا وآخرة ، فإنكم أيها اليهود الذين شاهدتم هذا المسخ بالنسبة إلى المعتدي منكم كيف تعملون خلاف أوامر الله سبحانه."},{"text":"وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦٓ إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا۟ بَقَرَةً ۖ قَالُوٓا۟ أَتَتَّخِذُنَا هُزُوًا ۖ قَالَ أَعُوذُ بِٱللَّهِ أَنْ أَكُونَ مِنَ ٱلْجَـٰهِلِينَ","tafsir":"أي جعلنا المسخة التي مسخوا بها ، والعقوبة التي عوقبوا فيها ( نَكالاً ) أي عبرة ( لِما بَيْنَ يَدَيْها ) أي من كان في زمانهم من سائر اليهود والأمم ( وَما خَلْفَها ) الذين يأتون من بعدهم مما يسمعون بأخبارهم ، أو يكون معنى « نكالا » « عقوبة » فالمعنى جعلنا المسخة عقوبة للمعاصي التي ارتكبوها مما كانت بين يدي المسخة ، وهو « الاعتداء » وما خلف المسخة من سائر المعاصي التي كانوا يرتكبونها بعد اعتدائهم في السبت ( وَ ) جعلناها ( مَوْعِظَةً لِلْمُتَّقِينَ ) لئلا يرتكبوا خلاف أمر الله سبحانه."},{"text":"قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ ۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا فَارِضٌ وَلَا بِكْرٌ عَوَانٌۢ بَيْنَ ذَٰلِكَ ۖ فَٱفْعَلُوا۟ مَا تُؤْمَرُونَ","tafsir":"اذكروا أيها اليهود قصة البقرة ، وهي أنهم وجدوا قتيلا لم يعرفوا قاتله ، فرجعوا إلى موسى عليه‌السلام ، فأمرهم الله تعالى ، أن يذبحوا بقرة ، ثم يضربوا القتيل بها ليحيي القتيل ويخبرهم بالقاتل ، وكان هذا اختبارا لإيمانهم ، حيث أن كون ضرب ميت بميت موجبا للحياة مما لا يصدقه ضعفاء الإيمان ، ولهذا جعلوا يسألون أسئلة تافهة من موسى عليه‌السلام حول البقرة ( إِذْ قالَ مُوسى لِقَوْمِهِ إِنَّ اللهَ يَأْمُرُكُمْ أَنْ تَذْبَحُوا بَقَرَةً قالُوا أَ تَتَّخِذُنا هُزُواً قالَ أَعُوذُ بِاللهِ أَنْ أَكُونَ مِنَ الْجاهِلِينَ (67) قالُوا ادْعُ لَنا رَبَّكَ يُبَيِّنْ لَنا ما هِيَ قالَ إِنَّهُ يَقُولُ إِنَّها بَقَرَةٌ لا فارِضٌ وَلا بِكْرٌ عَوانٌ بَيْنَ ذلِكَ فَافْعَلُوا ما تُؤْمَرُونَ (68) قالُوا ادْعُ لَنا رَبَّكَ يُبَيِّنْ لَنا ما لَوْنُها قالَ إِنَّهُ يَقُولُ إِنَّها لِقَوْمِهِ ) بني إسرائيل ( إِنَّ اللهَ يَأْمُرُكُمْ أَنْ تَذْبَحُوا بَقَرَةً ) لإحياء القتيل ( قالُوا أَ تَتَّخِذُنا هُزُواً ) أي أ تسخر منا وتتخذنا سخرية ، فما الربط بين القتيل ، وبين ذبح البقرة ، أو كيف تكون البقرة الميتة سببا لإحياء القتيل ( قالَ ) موسى عليه‌السلام ( أَعُوذُ بِاللهِ أَنْ أَكُونَ مِنَ الْجاهِلِينَ ) الذين يستهزئون بالناس ، فإن السخرية من شأن الجهال والسفهاء."},{"text":"قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوْنُهَا ۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ صَفْرَآءُ فَاقِعٌ لَّوْنُهَا تَسُرُّ ٱلنَّـٰظِرِينَ","tafsir":"أي اطلب من أجلنا ( رَبَّكَ يُبَيِّنْ لَنا ما هِيَ ) أي ما هي البقرة ، من حيث سنها وعمرها ( قالَ ) موسى عليه‌السلام ( إِنَّهُ ) تعالى ( يَقُولُ إِنَّها ) أي البقرة يلزم أن تكون ( بَقَرَةٌ لا فارِضٌ وَلا بِكْرٌ ) الفارض الكبيرة الهرمة والبكر الصغيرة ( عَوانٌ ) أي وسط العمر ( بَيْنَ ذلِكَ ) أي المذكور بين الصغير والكبير ( فَافْعَلُوا ما تُؤْمَرُونَ ) من ذبح هكذا بقرة."},{"text":"قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ إِنَّ ٱلْبَقَرَ تَشَـٰبَهَ عَلَيْنَا وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهْتَدُونَ","tafsir":"أي اسأل من ربك لأجلنا ( يُبَيِّنْ لَنا ما لَوْنُها ) أي ما لون البقرة التي أمرنا بذبحها ( قالَ ) موسى عليه‌السلام ( إِنَّهُ ) تعالى ( يَقُولُ إِنَّها بَقَرَةٌ صَفْراءُ فاقِعٌ لَوْنُها تَسُرُّ النَّاظِرِينَ (69) قالُوا ادْعُ لَنا رَبَّكَ يُبَيِّنْ لَنا ما هِيَ إِنَّ الْبَقَرَ تَشابَهَ عَلَيْنا وَإِنَّا إِنْ شاءَ اللهُ لَمُهْتَدُونَ (70) قالَ إِنَّهُ يَقُولُ إِنَّها بَقَرَةٌ لا ذَلُولٌ تُثِيرُ الْأَرْضَ وَلا تَسْقِي الْحَرْثَ بَقَرَةٌ صَفْراءُ ) اللون ( فاقِعٌ لَوْنُها ) أي حسنة الصفرة لا تضرب إلى السواد لشدتها ، ولا إلى البياض لقلتها ( تَسُرُّ النَّاظِرِينَ ) إليها إي تعجب الناظرين وتفرحهم بسبب حسن لونها. [71] ولما بين سبحانه سن البقرة ، ولونها سألوا عن صفتها ( قالُوا ) يا موسى ( ادْعُ لَنا رَبَّكَ يُبَيِّنْ لَنا ما هِيَ ) البقرة ، أ تكون من العوامل ، أو من السوائم التي لا تعمل ، ف ( إِنَّ الْبَقَرَ ) الذي أمرتنا بذبحه ( تَشابَهَ ) أي اشتبه ( عَلَيْنا ) وإنه كيف ينبغي أن يكون ( وَإِنَّا إِنْ شاءَ اللهُ لَمُهْتَدُونَ ) إلى صفة البقرة بتعريف الله سبحانه لنا كيف يجب أن يكون ، وفي الحديث عن النبي صلى‌الله‌عليه‌وآله‌وسلم : إنهم لما شددوا على أنفسهم ، شدد الله عليهم ، ولو لم يستثنوا ما بينت لهم إلى آخر الأبد (1) ."},{"text":"قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا ذَلُولٌ تُثِيرُ ٱلْأَرْضَ وَلَا تَسْقِى ٱلْحَرْثَ مُسَلَّمَةٌ لَّا شِيَةَ فِيهَا ۚ قَالُوا۟ ٱلْـَٔـٰنَ جِئْتَ بِٱلْحَقِّ ۚ فَذَبَحُوهَا وَمَا كَادُوا۟ يَفْعَلُونَ","tafsir":"يرجى تزويدنا بنص الآية وتفسيرها لإضافتها."},{"text":"وَإِذْ قَتَلْتُمْ نَفْسًا فَٱدَّٰرَْٰٔتُمْ فِيهَا ۖ وَٱللَّهُ مُخْرِجٌ مَّا كُنتُمْ تَكْتُمُونَ","tafsir":"موسى عليه‌السلام ( إِنَّهُ ) سبحانه ( يَقُولُ إِنَّها ) أي البقرة التي أمرتم بذبحها ( بَقَرَةٌ لا ذَلُولٌ ) يذلها العمل ( تُثِيرُ الْأَرْضَ ) أي تعمل وتكرب لإثارة الأرض ( وَلا تَسْقِي الْحَرْثَ ) الحرث الزرع ، فلا ( 1) مستدرك الوسائل : ج 16 ص 54 ، باب حكم الحلف على ترك الطيبات. مُسَلَّمَةٌ لا شِيَةَ فِيها قالُوا الْآنَ جِئْتَ بِالْحَقِّ فَذَبَحُوها وَما كادُوا يَفْعَلُونَ (71) وَإِذْ قَتَلْتُمْ نَفْساً فَادَّارَأْتُمْ فِيها وَاللهُ مُخْرِجٌ ما كُنْتُمْ تَكْتُمُونَ (72) فَقُلْنا اضْرِبُوهُ بِبَعْضِها كَذلِكَ يُحْيِ اللهُ الْمَوْتى وَيُرِيكُمْ آياتِهِ تسقيه بالناعور ، والدلاء ، والمعنى أن لا تكون عاملة ( مُسَلَّمَةٌ ) أي سالمة لا نقص فيها فهي بريئة من العيوب ( لا شِيَةَ ) من الوشي بمعنى اللون ( فِيها ) أي لا لون فيها يخالف لونها ، وهذا ليس تأكيد لما سبق ، إذ كونها صفراء ، لا تدل على عدم الوشي فيها ( قالُوا ) لموسى عليه‌السلام ( الْآنَ ) وبعد هذه التوضيحات لصفات البقرة ( جِئْتَ بِالْحَقِ ) الواضح ، أو بما هو حق الكلام مقابل الإجمال الذي قاله عليه‌السلام سابقا بقوله ( إِنَّ اللهَ يَأْمُرُكُمْ أَنْ تَذْبَحُوا بَقَرَةً )( فَذَبَحُوها ) أي ذبح اليهود تلك البقرة المأمور بذبحها ( وَما كادُوا يَفْعَلُونَ ) أي كاد ، أن لا يذبحوا تلك البقرة لغلاء ثمنها ، فإنها انحصرت في بقرة واحدة ، لم يعطها صاحبها إلا بثمن فاحش."},{"text":"فَقُلْنَا ٱضْرِبُوهُ بِبَعْضِهَا ۚ كَذَٰلِكَ يُحْىِ ٱللَّهُ ٱلْمَوْتَىٰ وَيُرِيكُمْ ءَايَـٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ","tafsir":"اذكروا يا بني إسرائيل ( إِذْ قَتَلْتُمْ نَفْساً فَادَّارَأْتُمْ فِيها ) ادارأتم بمعنى اختلفتم ، وأصله تدارأتم ( وَاللهُ مُخْرِجٌ ما كُنْتُمْ تَكْتُمُونَ ) من أمر القاتل ، وإنه من القاتل ، ولماذا قتل."},{"text":"ثُمَّ قَسَتْ قُلُوبُكُم مِّنۢ بَعْدِ ذَٰلِكَ فَهِىَ كَٱلْحِجَارَةِ أَوْ أَشَدُّ قَسْوَةً ۚ وَإِنَّ مِنَ ٱلْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ ٱلْأَنْهَـٰرُ ۚ وَإِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ ٱلْمَآءُ ۚ وَإِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ ٱللَّهِ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ","tafsir":"أي اضربوا القتيل ( بِبَعْضِها ) أي ببعض البقرة المذبوحة التي أمروا بذبحها ( كَذلِكَ ) أي مثل هذا الإحياء ( يُحْيِ اللهُ الْمَوْتى ) في يوم القيامة ، فإن القتيل لما ضرب بالبقرة قام حيا وأوداجه تشخب دما ، وأخبر بسبب قتله ، وبالذي قتله ( وَيُرِيكُمْ آياتِهِ ) في لَعَلَّكُمْ تَعْقِلُونَ (73) ثُمَّ قَسَتْ قُلُوبُكُمْ مِنْ بَعْدِ ذلِكَ فَهِيَ كَالْحِجارَةِ أَوْ أَشَدُّ قَسْوَةً وَإِنَّ مِنَ الْحِجارَةِ لَما يَتَفَجَّرُ مِنْهُ الْأَنْهارُ وَإِنَّ مِنْها لَما يَشَّقَّقُ فَيَخْرُجُ مِنْهُ الْماءُ وَإِنَّ مِنْها لَما يَهْبِطُ مِنْ خَشْيَةِ اللهِ الكون وفي أنفسكم ، أو بمعنى يريكم معجزاته ( لَعَلَّكُمْ تَعْقِلُونَ ) أي كي تستعملوا عقولكم ، ولعل وجه تأخير آية « وإذ قتلتم » على الآيات السالفة ، مع إن النظم يقتضي تقديمها ، أن السياق لبيان لجاجة اليهود ، وعدم إطاعتهم الأوامر ، فكان المقتضى تقديم ما يدل على ذلك."},{"text":"۞ أَفَتَطْمَعُونَ أَن يُؤْمِنُوا۟ لَكُمْ وَقَدْ كَانَ فَرِيقٌ مِّنْهُمْ يَسْمَعُونَ كَلَـٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعْدِ مَا عَقَلُوهُ وَهُمْ يَعْلَمُونَ","tafsir":"من بعد ما رأيتم هذه الآيات أيها اليهود ( قَسَتْ قُلُوبُكُمْ ) أي غلظت ( مِنْ بَعْدِ ذلِكَ ) المذكور من آيات الله تعالى ، أو من بعد ذبح البقرة ، وما رأيتم من إحياء الله الميت ( فَهِيَ كَالْحِجارَةِ ) في القسوة للمعقول بالمحسوس ( أَوْ أَشَدُّ قَسْوَةً ) وبين سبب أشديتها قسوة ، بقوله ( وَإِنَّ مِنَ الْحِجارَةِ لَما ) اللام للتأكيد ، و « ما » موصولة ، أي الحجر الذي ( يَتَفَجَّرُ مِنْهُ الْأَنْهارُ ) فيكون مبعثا للخير نافعا ، بخلاف قلوبكم التي لا يأتي منها إلا الشر ( وَإِنَّ مِنْها لَما يَشَّقَّقُ ) أصله تشقق ( فَيَخْرُجُ مِنْهُ الْماءُ ) فيكون عينا ، وإن لم يجر ، وبهذا يفترق عن السابق ، وهو ما يتفجر منه الأنهار ( وَإِنَّ مِنْها ) أي من الحجارة ( لَما يَهْبِطُ ) أي ينزل من الجبل ويسقط ( مِنْ خَشْيَةِ اللهِ ) فإن كل حجارة تسقط ، لا بد وأن تكون سقطتها بإذن الله ، ومن خشيته خشية واقعية وَمَا اللهُ بِغافِلٍ عَمَّا تَعْمَلُونَ (74) أَ فَتَطْمَعُونَ أَنْ يُؤْمِنُوا لَكُمْ وَقَدْ كانَ فَرِيقٌ مِنْهُمْ يَسْمَعُونَ كَلامَ اللهِ ثُمَّ يُحَرِّفُونَهُ مِنْ بَعْدِ ما عَقَلُوهُ وَهُمْ يَعْلَمُونَ (75) وَإِذا لَقُوا أو تشبيه ، كالذي يخشى كثيرا فيسقط على وجهه ، وقلوبكم أيها اليهود أقسى من تلك الحجارة ، إذ لا تخشى من الله سبحانه ، ولا تتواضع لعظمته ( وَمَا اللهُ بِغافِلٍ عَمَّا تَعْمَلُونَ ) أيها اليهود ، فيجازيكم بسيئات أعمالكم."},{"text":"وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ قَالُوٓا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيْكُمْ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمْ ۚ أَفَلَا تَعْقِلُونَ","tafsir":"أيها المسلمون ( أَنْ يُؤْمِنُوا ) أي يؤمن اليهود ( لَكُمْ ) أي لنفعكم ، إذ كل من آمن يكون في نفع المؤمنين السابقين ، أو بمعنى الإيمان بمبادئكم ، وهذا استفهام إنكاري ، أي لن يؤمن هؤلاء اليهود بالإسلام ( وَقَدْ كانَ فَرِيقٌ مِنْهُمْ ) أي من هؤلاء ، وهم أسلافهم ، وإنما صحت النسبة إليهم ، لأن الأمة الواحدة ، والقبيلة الواحدة ، تكون متشابهة الأعمال والأفعال والأقوال ( يَسْمَعُونَ كَلامَ اللهِ ) الذي يتلوه الأنبياء عليهم ( ثُمَّ يُحَرِّفُونَهُ ) بالزيادة والنقصان لفظا أو معنى ، كما هو المتعارف عند من يريد نقل كلام لا يرضيه ، فإنه إما أن ينقص فيه أو يزيد ـ لو وجد إلى ذلك سبيل ـ وإما أن يفسره بغير ما أراد المتكلم ( مِنْ بَعْدِ ما عَقَلُوهُ ) وفهموه ( وَهُمْ يَعْلَمُونَ ) فكيف يؤمن هؤلاء الذين كانوا يعملون بكلام الله بعد تعقل هذا العمل."},{"text":"أَوَلَا يَعْلَمُونَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ","tafsir":"من الملاقاة ، أي لقي اليهود وكانت هذه خصلة بعضهم نسبت إلى الجميع ، كما هو المتعارف من نسبة ما يقوم به البعض إلى الَّذِينَ آمَنُوا قالُوا آمَنَّا وَإِذا خَلا بَعْضُهُمْ إِلى بَعْضٍ قالُوا أَ تُحَدِّثُونَهُمْ بِما فَتَحَ اللهُ عَلَيْكُمْ لِيُحَاجُّوكُمْ بِهِ عِنْدَ رَبِّكُمْ أَ فَلا تَعْقِلُونَ (76) أَ وَلا يَعْلَمُونَ أَنَّ اللهَ يَعْلَمُ ما يُسِرُّونَ وَما يُعْلِنُونَ (77) الجميع ( الَّذِينَ آمَنُوا قالُوا آمَنَّا ) بأن محمدا صلى‌الله‌عليه‌وآله‌وسلم هذا موجود في كتبنا بوصفه وحليته ، ولم يقصدوا الإيمان الحقيقي كسائر المسلمين ، ولا الإيمان الظاهري كالمنافقين ، وإنما أريد الإيمان بمعناه اللغوي ، وهذا ذم لهم ، حيث إنهم اتصفوا بصفات المنافقين ( وَإِذا خَلا بَعْضُهُمْ إِلى بَعْضٍ ) وجمع هؤلاء اليهود وغيرهم من سائر اليهود ، مجلس خال من المؤمنين ( قالُوا ) أي قال من لم يكن يظهر الإيمان لمن أظهره ( أَ تُحَدِّثُونَهُمْ ) أي لماذا تحدثون المسلمين ( بِما فَتَحَ اللهُ عَلَيْكُمْ ) أي بما عرفكم الله في كتابكم ، بأن محمدا صلى‌الله‌عليه‌وآله‌وسلم حق ، يقال فتح عليه باب العلم إذا أرشده إليه وعلمه به ( لِيُحَاجُّوكُمْ بِهِ عِنْدَ رَبِّكُمْ ) أي إذا أظهرتم أنتم أيها اليهود للمسلمين ، أن في كتابكم صفات محمد صلى‌الله‌عليه‌وآله‌وسلم حاجوكم يوم القيامة عند الله فيقول المسلمون لليهود المظهرين أنتم ذكرتم أن في كتابكم صفات النبي ، فلم لم تؤمنوا به ( أَ فَلا تَعْقِلُونَ ) أيها اليهود المظهرون للمسلمين ، أن إظهاركم سبب لغلبة المسلمين عليكم في الحجة عند الله."},{"text":"وَمِنْهُمْ أُمِّيُّونَ لَا يَعْلَمُونَ ٱلْكِتَـٰبَ إِلَّآ أَمَانِىَّ وَإِنْ هُمْ إِلَّا يَظُنُّونَ","tafsir":"يعني اليهود المنافقون ( أَنَّ اللهَ يَعْلَمُ ما يُسِرُّونَ ) يسر بعضهم إلى بعض ( وَما يُعْلِنُونَ ) وما الفائدة في أن لا يظهروا صفات وَمِنْهُمْ أُمِّيُّونَ لا يَعْلَمُونَ الْكِتابَ إِلاَّ أَمانِيَّ وَإِنْ هُمْ إِلاَّ يَظُنُّونَ (78) فَوَيْلٌ لِلَّذِينَ يَكْتُبُونَ الْكِتابَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هذا مِنْ عِنْدِ اللهِ لِيَشْتَرُوا بِهِ ثَمَناً قَلِيلاً فَوَيْلٌ لَهُمْ مِمَّا كَتَبَتْ أَيْدِيهِمْ النبي ، فإن الله يعلم أنهم يعلمون صفاته ، ولا يؤمنون به عنادا."},{"text":"فَوَيْلٌ لِّلَّذِينَ يَكْتُبُونَ ٱلْكِتَـٰبَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَـٰذَا مِنْ عِندِ ٱللَّهِ لِيَشْتَرُوا۟ بِهِۦ ثَمَنًا قَلِيلًا ۖ فَوَيْلٌ لَّهُم مِّمَّا كَتَبَتْ أَيْدِيهِمْ وَوَيْلٌ لَّهُم مِّمَّا يَكْسِبُونَ","tafsir":"أي من اليهود ( أُمِّيُّونَ ) منسوب إلى الأم ، بمعنى من لا يقرأ ولا يكتب كأنه نشأ تحت تربية أمه ، لا تحت تربية المعلم ( لا يَعْلَمُونَ الْكِتابَ إِلَّا أَمانِيَ ) الأماني جمع أمنية ، كالأغاني جمع أغنية ، والأماني الأحاديث المختلفة ، أي أنهم لا يعرفون ما في التوراة من صفات النبي صلى‌الله‌عليه‌وآله‌وسلم وغيرها ، وإنما هم جهلاء ، يأخذون أمور الكتاب عن علمائهم محرفة مختلفة ، فلا يميزون بين الحق والباطل ( وَإِنْ هُمْ ) أي ما هم ( إِلَّا يَظُنُّونَ ) بصحة ما يسمعون ، ولا يتيقنون لأنهم لم يطالعوا الكتاب بأنفسهم ، حتى يعرفون ما فيه."},{"text":"وَقَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَةً ۚ قُلْ أَتَّخَذْتُمْ عِندَ ٱللَّهِ عَهْدًا فَلَن يُخْلِفَ ٱللَّهُ عَهْدَهُۥٓ ۖ أَمْ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ","tafsir":"أي لعلمائهم الذين ( يَكْتُبُونَ الْكِتابَ ) أي التوراة ( بِأَيْدِيهِمْ ) كناية عن أنها غير منزلة ، وإنما مكتوبة مبعثها الأيدي لا الوحي والإلهام ( ثُمَّ يَقُولُونَ هذا ) المكتوب ( مِنْ عِنْدِ اللهِ ) وإنه منزل منه ( لِيَشْتَرُوا بِهِ ) أي بما يكتبونه ( ثَمَناً قَلِيلاً ) لأنهم لو كانوا يظهرون ما في التوراة حقيقة رجع مقلدوهم إلى النبي صلى‌الله‌عليه‌وآله‌وسلم ، فلم يكونوا يبذلون لهم الأموال والاحترام ( فَوَيْلٌ لَهُمْ ) أي للذين يكتبون الكتاب بأيديهم ( مِمَّا كَتَبَتْ أَيْدِيهِمْ ) فإنه يوجب عذابا ، لأنه تحريف وَوَيْلٌ لَهُمْ مِمَّا يَكْسِبُونَ (79) وَقالُوا لَنْ تَمَسَّنَا النَّارُ إِلاَّ أَيَّاماً مَعْدُودَةً قُلْ أَتَّخَذْتُمْ عِنْدَ اللهِ عَهْداً فَلَنْ يُخْلِفَ اللهُ عَهْدَهُ أَمْ تَقُولُونَ عَلَى اللهِ ما لا تَعْلَمُونَ (80) بَلى مَنْ كَسَبَ سَيِّئَةً وَأَحاطَتْ بِهِ خَطِيئَتُهُ فَأُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ (81) لكلام الله تعالى ( وَوَيْلٌ لَهُمْ مِمَّا يَكْسِبُونَ ) من الأموال إزاء تحريفاتهم ، فإن ثمن الحرام حرام آخر ، وذلك موجب للعذاب فإنه أكل للأموال بالباطل ، والويل أصله الهلاك والعذاب ، ثم استعمل في كل واقع في الهلكة."},{"text":"بَلَىٰ مَن كَسَبَ سَيِّئَةً وَأَحَـٰطَتْ بِهِۦ خَطِيٓـَٔتُهُۥ فَأُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ","tafsir":"أي قال قسم من اليهود ( لَنْ تَمَسَّنَا النَّارُ إِلَّا أَيَّاماً مَعْدُودَةً ) فلن نعذب في جهنم إلا سبعة أيام أو ما أشبه ، على تقدير كفرنا وعصياننا ، فلما ذا نترك رئاسة الدنيا خوفا من عذاب قليل ( قُلْ ) يا رسول الله لهم ( أَتَّخَذْتُمْ ) أي هل اتخذتم ( عِنْدَ اللهِ عَهْداً ) بذلك ( فَلَنْ يُخْلِفَ اللهُ عَهْدَهُ أَمْ تَقُولُونَ عَلَى اللهِ ) كذبا وزورا ( ما لا تَعْلَمُونَ ) ومن أدراكم أن العذاب أيام معدودة."},{"text":"وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَـٰلِدُونَ","tafsir":"ليس الأمر كما قالوا ولكن ( مَنْ كَسَبَ سَيِّئَةً وَ ) لم ينقلع عنها بل ( أَحاطَتْ بِهِ خَطِيئَتُهُ ) كالإنسان الذي يقع في دخان حيث يحيط به الدخان ، حتى لا يتنفس ولا يبصر ولا يسمع إلا في الدخان ، وكذلك المشرك المنحرف في الخطيئة ( فَأُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ ) إلى الأبد. وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ أُولئِكَ أَصْحابُ الْجَنَّةِ هُمْ فِيها خالِدُونَ (82) وَإِذْ أَخَذْنا مِيثاقَ بَنِي إِسْرائِيلَ لا تَعْبُدُونَ إِلاَّ اللهَ وَبِالْوالِدَيْنِ إِحْساناً وَذِي الْقُرْبى وَالْيَتامى وَالْمَساكِينِ وَقُولُوا لِلنَّاسِ حُسْناً وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكاةَ ثُمَّ تَوَلَّيْتُمْ إِلاَّ قَلِيلاً مِنْكُمْ وَأَنْتُمْ مُعْرِضُونَ (83)"},{"text":"وَإِذْ أَخَذْنَا مِيثَـٰقَ بَنِىٓ إِسْرَٰٓءِيلَ لَا تَعْبُدُونَ إِلَّا ٱللَّهَ وَبِٱلْوَٰلِدَيْنِ إِحْسَانًا وَذِى ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينِ وَقُولُوا۟ لِلنَّاسِ حُسْنًا وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيْتُمْ إِلَّا قَلِيلًا مِّنكُمْ وَأَنتُم مُّعْرِضُونَ","tafsir":"بقلوبهم وألسنتهم ( وَعَمِلُوا الصَّالِحاتِ ) التي أمر بها الإسلام ( أُولئِكَ أَصْحابُ الْجَنَّةِ هُمْ فِيها خالِدُونَ ) بها لا انقطاع لها ولا زوال."},{"text":"وَإِذْ أَخَذْنَا مِيثَـٰقَكُمْ لَا تَسْفِكُونَ دِمَآءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم مِّن دِيَـٰرِكُمْ ثُمَّ أَقْرَرْتُمْ وَأَنتُمْ تَشْهَدُونَ","tafsir":"اذكروا يا بني إسرائيل ( إِذْ أَخَذْنا مِيثاقَ بَنِي إِسْرائِيلَ ) عهدهم الأكيد على لسان أنبيائهم ، بأن ( لا تَعْبُدُونَ إِلَّا اللهَ ) وحده ( وَ ) بأن أحسنوا ( بِالْوالِدَيْنِ إِحْساناً ) ولا تسيئوا إليهما ( وَ ) أحسنوا إلى ( ذِي الْقُرْبى ) أقربائهم ( وَالْيَتامى ) الذين مات والدهم ( وَالْمَساكِينِ ) الفقراء ( وَقُولُوا لِلنَّاسِ حُسْناً ) وذلك يشمل جميع أنواع الأمر بالمعروف والنهي عن المنكر ، والإرشاد ورد الاعتداء بالحسن ( وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكاةَ ) وهما في سائر الأمم ، لم يكونا بهذا الشكل الموجود فعلا في هذه الأمة ( ثُمَّ تَوَلَّيْتُمْ ) أعرضتم ( إِلَّا قَلِيلاً مِنْكُمْ ) الذين عملوا بأوامرنا ( وَأَنْتُمْ مُعْرِضُونَ ) تأكيدا لقوله « توليتم » . وَإِذْ أَخَذْنا مِيثاقَكُمْ لا تَسْفِكُونَ دِماءَكُمْ وَلا تُخْرِجُونَ أَنْفُسَكُمْ مِنْ دِيارِكُمْ ثُمَّ أَقْرَرْتُمْ وَأَنْتُمْ تَشْهَدُونَ (84) ثُمَّ أَنْتُمْ هؤُلاءِ تَقْتُلُونَ أَنْفُسَكُمْ وَتُخْرِجُونَ فَرِيقاً مِنْكُمْ مِنْ دِيارِهِمْ تَظاهَرُونَ عَلَيْهِمْ بِالْإِثْمِ وَالْعُدْوانِ وَإِنْ يَأْتُوكُمْ أُسارى تُفادُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْراجُهُمْ"},{"text":"ثُمَّ أَنتُمْ هَـٰٓؤُلَآءِ تَقْتُلُونَ أَنفُسَكُمْ وَتُخْرِجُونَ فَرِيقًا مِّنكُم مِّن دِيَـٰرِهِمْ تَظَـٰهَرُونَ عَلَيْهِم بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَإِن يَأْتُوكُمْ أُسَـٰرَىٰ تُفَـٰدُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْرَاجُهُمْ ۚ أَفَتُؤْمِنُونَ بِبَعْضِ ٱلْكِتَـٰبِ وَتَكْفُرُونَ بِبَعْضٍ ۚ فَمَا جَزَآءُ مَن يَفْعَلُ ذَٰلِكَ مِنكُمْ إِلَّا خِزْىٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَيَوْمَ ٱلْقِيَـٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلْعَذَابِ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ","tafsir":"اذكروا يا بني إسرائيل ( إِذْ أَخَذْنا مِيثاقَكُمْ ) عهدكم الأكيد على لسان الأنبياء ( لا تَسْفِكُونَ دِماءَكُمْ ) أي لا يسفك بعضكم دماء بعض ( وَلا تُخْرِجُونَ أَنْفُسَكُمْ مِنْ دِيارِكُمْ ) أي لا يخرج بعضكم بعضا من الديار ، بأن يسفرهم ويبعدهم ( ثُمَّ أَقْرَرْتُمْ ) بذلك الميثاق ، بأن أعطيتمونا العهود بذلك ( وَأَنْتُمْ تَشْهَدُونَ ) أيها اليهود ، بوقوع هذا الميثاق بيننا."},{"text":"أُو۟لَـٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْحَيَوٰةَ ٱلدُّنْيَا بِٱلْـَٔاخِرَةِ ۖ فَلَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنصَرُونَ","tafsir":"بعد ذلك الميثاق ( أَنْتُمْ هؤُلاءِ ) الذين ( تَقْتُلُونَ أَنْفُسَكُمْ وَتُخْرِجُونَ فَرِيقاً مِنْكُمْ مِنْ دِيارِهِمْ ) مخالفة لأوامرنا ( تَظاهَرُونَ ) أنتم أي يتعاون بعضكم مع بعض في إخراجكم لهم تظاهرا ( عَلَيْهِمْ بِالْإِثْمِ وَالْعُدْوانِ ) لا إخراجا بالحق ( وَ ) الحال ( إِنْ يَأْتُوكُمْ أُسارى تُفادُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْراجُهُمْ ) أي كيف يخرج بعضكم بعضا ، ويقتل بعضكم بعضا ، مع أنكم إذا وجدتم بعضكم أسيرا في أيدي غيرهم ، تعطون الفدية لخلاصهم ، فإن كان بينكم عداء ، فما هذه الفدية ، وإن كان بينكم وداد فما هذا القتل والإخراج. روي عن ابن عباس : أن قريظة والنضير ، كانا أخوين ، كالأوس والخزرج ، فافترقوا فكانت أَفَتُؤْمِنُونَ بِبَعْضِ الْكِتابِ وَتَكْفُرُونَ بِبَعْضٍ فَما جَزاءُ مَنْ يَفْعَلُ ذلِكَ مِنْكُمْ إِلاَّ خِزْيٌ فِي الْحَياةِ الدُّنْيا وَيَوْمَ الْقِيامَةِ يُرَدُّونَ إِلى أَشَدِّ الْعَذابِ وَمَا اللهُ بِغافِلٍ عَمَّا تَعْمَلُونَ (85) أُولئِكَ الَّذِينَ اشْتَرَوُا الْحَياةَ الدُّنْيا بِالْآخِرَةِ فَلا النضير مع الخزرج ، وكانت قريظة مع الأوس ، فإذا اقتتلوا عاونت كل فرقة حلفاءها ، فإذا وضعت الحرب أوزارها فدوا أسراها تصديقا لما في التوراة (1) ، وروي عن آخر أن اليهود كانوا إذا استضعفوا جماعة آخرين أخرجوهم من ديارهم ( أَ فَتُؤْمِنُونَ ) أيها اليهود ( بِبَعْضِ الْكِتابِ ) أي التوراة القائل بوجوب إعطاء الفدية لأسراكم ( وَتَكْفُرُونَ بِبَعْضٍ ) القائل بحرمة القتل والإخراج والتظاهر بالإثم والعدوان ( فَما جَزاءُ مَنْ يَفْعَلُ ذلِكَ مِنْكُمْ ) احكموا أنتم بأنفسكم ( إِلَّا خِزْيٌ فِي الْحَياةِ الدُّنْيا ) بالتفرقة والضعف والمهانة عند سائر الأمم ( وَيَوْمَ الْقِيامَةِ يُرَدُّونَ إِلى أَشَدِّ الْعَذابِ ) بمخالفتهم أوامر الله سبحانه ( وَمَا اللهُ ) أي ليس الله ( بِغافِلٍ عَمَّا تَعْمَلُونَ ) فإنه يعلم أعمالكم ، فيجازيكم عليها."},{"text":"وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ وَقَفَّيْنَا مِنۢ بَعْدِهِۦ بِٱلرُّسُلِ ۖ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَـٰتِ وَأَيَّدْنَـٰهُ بِرُوحِ ٱلْقُدُسِ ۗ أَفَكُلَّمَا جَآءَكُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُكُمُ ٱسْتَكْبَرْتُمْ فَفَرِيقًا كَذَّبْتُمْ وَفَرِيقًا تَقْتُلُونَ","tafsir":"اليهود الذين خالفوا الأوامر بتلك الأفعال ( الَّذِينَ اشْتَرَوُا الْحَياةَ الدُّنْيا بِالْآخِرَةِ ) فباعوا الآخرة ، وأخذوا الدنيا بدلها ( فَلا ( 1) راجع بحار الأنوار : ج 20 ص 166. يُخَفَّفُ عَنْهُمُ الْعَذابُ وَلا هُمْ يُنْصَرُونَ (86) وَلَقَدْ آتَيْنا مُوسَى الْكِتابَ وَقَفَّيْنا مِنْ بَعْدِهِ بِالرُّسُلِ وَآتَيْنا عِيسَى ابْنَ مَرْيَمَ الْبَيِّناتِ وَأَيَّدْناهُ بِرُوحِ الْقُدُسِ أَ فَكُلَّما جاءَكُمْ رَسُولٌ بِما لا تَهْوى أَنْفُسُكُمُ اسْتَكْبَرْتُمْ فَفَرِيقاً كَذَّبْتُمْ وَفَرِيقاً تَقْتُلُونَ (87) وَقالُوا قُلُوبُنا غُلْفٌ يُخَفَّفُ عَنْهُمُ الْعَذابُ ) يوم القيامة ( وَلا هُمْ يُنْصَرُونَ ) هناك."},{"text":"وَقَالُوا۟ قُلُوبُنَا غُلْفٌۢ ۚ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَقَلِيلًا مَّا يُؤْمِنُونَ","tafsir":"أعطينا التوراة إياه ( وَقَفَّيْنا ) أي أردفنا وأتبعنا بعضهم خلف بعض ( مِنْ بَعْدِهِ ) أي بعد موسى ( بِالرُّسُلِ ) رسول يتبع رسولا ( وَآتَيْنا عِيسَى ابْنَ مَرْيَمَ الْبَيِّناتِ ) جمع بينة ، أي الدلالة الواضحة ، وهي المعجزات التي أعطيت لعيسى عليه‌السلام من إبراء الأكمه والأبرص ، وإحياء الموتى ( وَأَيَّدْناهُ بِرُوحِ الْقُدُسِ ) التأييد التقوية ، وروح القدس ، إما جبرئيل عليه‌السلام ، أو روح قوية من الله سبحانه فيه تقوية على التبليغ والإرشاد مع كثرة أعدائه ( أَ فَكُلَّما جاءَكُمْ ) أيها اليهود ( رَسُولٌ بِما لا تَهْوى أَنْفُسُكُمُ ) ولا يمثل إليه من الأحكام ( اسْتَكْبَرْتُمْ ) وتكبرتم عن قبول أحكام الله سبحانه ( فَفَرِيقاً كَذَّبْتُمْ ) كعيسى ومحمد صلوات الله عليهما ( وَفَرِيقاً تَقْتُلُونَ ) كزكريا ويحيى عليها‌السلام ؟ وهذا استفهام إنكاري عليهم."},{"text":"وَلَمَّا جَآءَهُمْ كِتَـٰبٌ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ وَكَانُوا۟ مِن قَبْلُ يَسْتَفْتِحُونَ عَلَى ٱلَّذِينَ كَفَرُوا۟ فَلَمَّا جَآءَهُم مَّا عَرَفُوا۟ كَفَرُوا۟ بِهِۦ ۚ فَلَعْنَةُ ٱللَّهِ عَلَى ٱلْكَـٰفِرِينَ","tafsir":"أي قالت اليهود للنبي صلى‌الله‌عليه‌وآله‌وسلم ( قُلُوبُنا غُلْفٌ ) جمع أغلف ، بمعنى إنها في غطاء وغلاف عن هدايتكم ، فلا تصل الهداية إليها ، بَلْ لَعَنَهُمُ اللهُ بِكُفْرِهِمْ فَقَلِيلاً ما يُؤْمِنُونَ (88) وَلَمَّا جاءَهُمْ كِتابٌ مِنْ عِنْدِ اللهِ مُصَدِّقٌ لِما مَعَهُمْ وَكانُوا مِنْ قَبْلُ يَسْتَفْتِحُونَ عَلَى الَّذِينَ كَفَرُوا فَلَمَّا جاءَهُمْ ما عَرَفُوا كَفَرُوا بِهِ كما في آية أخرى ( وَقالُوا قُلُوبُنا فِي أَكِنَّةٍ ) (1) ( بَلْ ) ليس كذلك ، وإنما ( لَعَنَهُمُ اللهُ ) وأبعدهم عن الخير بسبب كفرهم فإنهم لما كفروا ولم يمتثلوا أوامر الله ، أبعدهم الله عن الخير ، كمن لا يسمع شخصا أمره فيتركه ولا يعتني به ( فَقَلِيلاً ما يُؤْمِنُونَ ) لما ران على قلوبهم ، وأظلمت نفوسهم بالكفر."},{"text":"بِئْسَمَا ٱشْتَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ أَن يَكْفُرُوا۟ بِمَآ أَنزَلَ ٱللَّهُ بَغْيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضْلِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۖ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٍ ۚ وَلِلْكَـٰفِرِينَ عَذَابٌ مُّهِينٌ","tafsir":"أي اليهود ( كِتابٌ مِنْ عِنْدِ اللهِ ) هو القرآن ( مُصَدِّقٌ لِما مَعَهُمْ ) أي الكتاب الذي مع اليهود ، وهو التوراة ، فإن القرآن يصدق التوراة الحقيقي المنزل على موسى عليه‌السلام ( إِنَّا أَنْزَلْنَا التَّوْراةَ فِيها هُدىً وَنُورٌ ) (2) ( وَكانُوا ) أي اليهود ( مِنْ قَبْلُ ) أي قبل أن يأتي الرسول صلى‌الله‌عليه‌وآله‌وسلم أو ينزل القرآن ( يَسْتَفْتِحُونَ ) أي يطلبون الفتح من الله ( عَلَى الَّذِينَ كَفَرُوا ) فإنهم كانوا يدعون الله ، أن يبعث الرسول ، حتى يكونوا أرجح كفة من الكفار ( فَلَمَّا جاءَهُمْ ما عَرَفُوا ) أي الرسول صلى‌الله‌عليه‌وآله‌وسلم الذي عرفوه بصفاته ومزاياه ( كَفَرُوا بِهِ ) وأخذوا يحاربوه ، بل فوق ذلك أنهم كانوا يرجحون الكافرين على ( 1) فصلت : 6. ( 2) المائدة : 45. فَلَعْنَةُ اللهِ عَلَى الْكافِرِينَ (89) بِئْسَمَا اشْتَرَوْا بِهِ أَنْفُسَهُمْ أَنْ يَكْفُرُوا بِما أَنْزَلَ اللهُ بَغْياً أَنْ يُنَزِّلَ اللهُ مِنْ فَضْلِهِ عَلى مَنْ يَشاءُ مِنْ عِبادِهِ الرسول والمؤمنين قائلين ( هؤُلاءِ أَهْدى مِنَ الَّذِينَ آمَنُوا سَبِيلاً ) (1) ( فَلَعْنَةُ اللهِ عَلَى ) اليهود ( الْكافِرِينَ ) بمحمد صلى‌الله‌عليه‌وآله‌وسلم وبالقرآن ، وهم يعرفون ذلك."},{"text":"وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ بِمَآ أَنزَلَ ٱللَّهُ قَالُوا۟ نُؤْمِنُ بِمَآ أُنزِلَ عَلَيْنَا وَيَكْفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ ٱلْحَقُّ مُصَدِّقًا لِّمَا مَعَهُمْ ۗ قُلْ فَلِمَ تَقْتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبْلُ إِن كُنتُم مُّؤْمِنِينَ","tafsir":"أي بئس الشيء الذي باع اليهود بذلك أنفسهم ، فأعطوا أنفسهم للعذاب الأبدي ، واشتروا الكفر ( أَنْ يَكْفُرُوا بِما أَنْزَلَ اللهُ ) بدل « ما » أي بئس الكفر الذي أخذوه مقابل أنفسهم ، وذلك تشبيه ، فكأن الكفر والإسلام ، سلعتان فمن أختار أحدهما باع نفسه بذلك الشيء ، إذ يصرف نفسه في سبيل ذلك ، فإذا باع نفسه مقابل الإسلام كان نعم ما اشترى به نفسه ، وإذا باع نفسه مقابل الكفر كان بئسما اشترى به نفسه ، واشترى هنا بمعنى البيع ، كما قال ( وَمِنَ النَّاسِ مَنْ يَشْرِي نَفْسَهُ ابْتِغاءَ مَرْضاتِ اللهِ ) (2) ( بَغْياً ) أي حسدا ، وهو علة لاشترائهم السيئ ، أي كان سبب شرائهم الكفر الحسد ، الذي كان فيهم لمحمد صلى‌الله‌عليه‌وآله‌وسلم ، حيث أنه من ولد إسماعيل ، لا من ولد جدهم إسحاق عليهما‌السلام ( أَنْ يُنَزِّلَ اللهُ ) الدين ( مِنْ فَضْلِهِ عَلى مَنْ يَشاءُ مِنْ عِبادِهِ ) وأن ينزل ، متعلق ب « بغيا » أي أن الحسد من جهة نزول القرآن ( 1) النساء : 52. ( 2) البقرة : 208. فَباؤُ بِغَضَبٍ عَلى غَضَبٍ وَلِلْكافِرِينَ عَذابٌ مُهِينٌ (90) وَإِذا قِيلَ لَهُمْ آمِنُوا بِما أَنْزَلَ اللهُ قالُوا نُؤْمِنُ بِما أُنْزِلَ عَلَيْنا وَيَكْفُرُونَ بِما وَراءَهُ وَهُوَ الْحَقُّ مُصَدِّقاً لِما مَعَهُمْ قُلْ فَلِمَ تَقْتُلُونَ أَنْبِياءَ اللهِ مِنْ قَبْلُ إِنْ كُنْتُمْ مُؤْمِنِينَ (91) على محمد صلى‌الله‌عليه‌وآله‌وسلم دون غيره ( فَباؤُ ) أي رجع اليهود ( بِغَضَبٍ عَلى غَضَبٍ ) فإنهم كانوا مغضوب عليهم من جهة تعدياتهم في زمان موسى وعيسى ، وسائر الأنبياء عليهم‌السلام ، فغضب الله عليهم مرة أخرى من جهة كفرهم بمحمد صلى‌الله‌عليه‌وآله‌وسلم ( وَلِلْكافِرِينَ ) الذين من أظهر مصاديقهم اليهود ( عَذابٌ مُهِينٌ ) وهو العذاب الذي يذل صاحبه ويهينه."},{"text":"۞ وَلَقَدْ جَآءَكُم مُّوسَىٰ بِٱلْبَيِّنَـٰتِ ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَـٰلِمُونَ","tafsir":"أي لليهود ( آمِنُوا بِما أَنْزَلَ اللهُ ) على محمد صلى‌الله‌عليه‌وآله‌وسلم ( قالُوا نُؤْمِنُ بِما أُنْزِلَ عَلَيْنا ) من التوراة ( وَيَكْفُرُونَ بِما وَراءَهُ ) أي وراء ما نزل عليه من كتاب عيسى عليه‌السلام ومحمد صلى‌الله‌عليه‌وآله‌وسلم ( وَهُوَ ) أي ما وراء كتابهم ( الْحَقُّ مُصَدِّقاً لِما مَعَهُمْ ) والجملة حالية ( قُلْ ) إنكم تكذبون في قولكم ( نُؤْمِنُ بِما أُنْزِلَ عَلَيْنا ) فإنكم لستم بمؤمنين ، حتى بالتوراة وإلا ( فَلِمَ تَقْتُلُونَ أَنْبِياءَ اللهِ مِنْ قَبْلُ ) في السابق ( إِنْ كُنْتُمْ مُؤْمِنِينَ ) بالتوراة ، فإن كتابكم حرم قتل الأنبياء ، فأنتم لستم بمؤمنين ، لا بكتابكم ، ولا بما بعد كتابكم من الإنجيل والقرآن. وَلَقَدْ جاءَكُمْ مُوسى بِالْبَيِّناتِ ثُمَّ اتَّخَذْتُمُ الْعِجْلَ مِنْ بَعْدِهِ وَأَنْتُمْ ظالِمُونَ (92) وَإِذْ أَخَذْنا مِيثاقَكُمْ وَرَفَعْنا فَوْقَكُمُ الطُّورَ خُذُوا ما آتَيْناكُمْ بِقُوَّةٍ وَاسْمَعُوا قالُوا سَمِعْنا وَعَصَيْنا وَأُشْرِبُوا فِي قُلُوبِهِمُ الْعِجْلَ بِكُفْرِهِمْ قُلْ بِئْسَما يَأْمُرُكُمْ بِهِ إِيمانُكُمْ"},{"text":"وَإِذْ أَخَذْنَا مِيثَـٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَـٰكُم بِقُوَّةٍ وَٱسْمَعُوا۟ ۖ قَالُوا۟ سَمِعْنَا وَعَصَيْنَا وَأُشْرِبُوا۟ فِى قُلُوبِهِمُ ٱلْعِجْلَ بِكُفْرِهِمْ ۚ قُلْ بِئْسَمَا يَأْمُرُكُم بِهِۦٓ إِيمَـٰنُكُمْ إِن كُنتُم مُّؤْمِنِينَ","tafsir":"كيف تقولون ( نُؤْمِنُ بِما أُنْزِلَ عَلَيْنا ) وعملكم ، يدل على خلاف ذلك ، ف ( لَقَدْ جاءَكُمْ مُوسى بِالْبَيِّناتِ ) أي بالحجج الواضحة ( ثُمَّ اتَّخَذْتُمُ الْعِجْلَ ) إلها لكم ( مِنْ بَعْدِهِ ) أي بعد رواحة إلى الطور ( وَ ) الحال ( أَنْتُمْ ظالِمُونَ ) لأنفسكم في عبادة العجل ، فلو كنتم مؤمنين بما نزل عليكم ، لم تتخذوا العجل إلها ؟."},{"text":"قُلْ إِن كَانَتْ لَكُمُ ٱلدَّارُ ٱلْـَٔاخِرَةُ عِندَ ٱللَّهِ خَالِصَةً مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَـٰدِقِينَ","tafsir":"اذكروا يا بني إسرائيل ( إِذْ أَخَذْنا مِيثاقَكُمْ ) عهدكم الشديد ، بالعمل بالتوراة ( وَرَفَعْنا فَوْقَكُمُ الطُّورَ ) أي قطعة من جبل الطور ـ كما تقدم ـ وقلنا لكم ( خُذُوا ما آتَيْناكُمْ بِقُوَّةٍ ) أي بشدة ، بمعنى العمل ، بكل ما في الكتاب عملا مستمرا قويا ( وَاسْمَعُوا ) أوامر الله سبحانه ( قالُوا سَمِعْنا وَعَصَيْنا ) حكاية حالهم ، ويحتمل أنهم قالوه بلفظهم استهزاء ( وَأُشْرِبُوا فِي قُلُوبِهِمُ الْعِجْلَ ) فكما أن من شرب الماء يدخل الماء في جوفه ، كذلك اليهود ، دخل العجل ـ أي حبه ـ في قلوبهم بسبب كفرهم بالله سبحانه ( قُلْ ) يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم لهم ( بِئْسَما يَأْمُرُكُمْ بِهِ إِيمانُكُمْ ) الذي قلتم ( نُؤْمِنُ بِما أُنْزِلَ عَلَيْنا ) فإن الإيمان الذي يأمر باتباع العجل ، ليس إيمانا ، وإنما هو كفر. إِنْ كُنْتُمْ مُؤْمِنِينَ (93) قُلْ إِنْ كانَتْ لَكُمُ الدَّارُ الْآخِرَةُ عِنْدَ اللهِ خالِصَةً مِنْ دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِنْ كُنْتُمْ صادِقِينَ (94) وَلَنْ يَتَمَنَّوْهُ أَبَداً بِما قَدَّمَتْ أَيْدِيهِمْ وَاللهُ عَلِيمٌ بِالظَّالِمِينَ (95) ( إِنْ كُنْتُمْ مُؤْمِنِينَ ) وهذا استهزاء لهم ، ثم إنه إنما كرر « رفع الطور » للدلالة ، على أنهم عكسوا الميثاق الذي أخذ منهم ، حال الرفع ، بل اتخذوا العجل إلها."},{"text":"وَلَن يَتَمَنَّوْهُ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّـٰلِمِينَ","tafsir":"يا رسول الله لهؤلاء اليهود ، الذين يقولون أن الآخرة هي لهم وحدهم لا يشركون فيها غيرهم من النصارى والمسلمين وغيرهما ( إِنْ كانَتْ لَكُمُ الدَّارُ الْآخِرَةُ عِنْدَ اللهِ خالِصَةً مِنْ دُونِ النَّاسِ ) عند الله صفة للدار الآخرة ، أي الدار التي هي عند الله ، ومن دون الناس صفة لخالصته ، أو لقوله « لكم » ( فَتَمَنَّوُا الْمَوْتَ ) لأن من يدري أن مصيره الجنة ، لا بد وأن يتمنى الموت ، حتى يخلص من آلام الدنيا وأتعابها ( إِنْ كُنْتُمْ صادِقِينَ ) في مقالكم وكنتم تعتقدون ما تقولونه بألسنتكم. [96] ثم أخبر سبحانه بأنهم ليسوا صادقين ( وَ ) الدليل على ذلك أنهم ( لَنْ يَتَمَنَّوْهُ ) أي الموت ( أَبَداً ) في حين من الأحيان بسبب ما ( قَدَّمَتْ أَيْدِيهِمْ ) من المعاصي والمنكرات والكفر ، وإنما نسب التقديم إلى اليد لأنها الآلة الظاهرة في تقديم الأشياء المحسوسة غالبا ( وَاللهُ عَلِيمٌ بِالظَّالِمِينَ ) فلا يغترون بمقالهم ، أن لهم الآخرة ، وأنهم أحباء الله دون سواهم. وَلَتَجِدَنَّهُمْ أَحْرَصَ النَّاسِ عَلى حَياةٍ وَمِنَ الَّذِينَ أَشْرَكُوا يَوَدُّ أَحَدُهُمْ لَوْ يُعَمَّرُ أَلْفَ سَنَةٍ وَما هُوَ بِمُزَحْزِحِهِ مِنَ الْعَذابِ أَنْ يُعَمَّرَ وَاللهُ بَصِيرٌ بِما يَعْمَلُونَ (96) قُلْ مَنْ كانَ عَدُوًّا"},{"text":"وَلَتَجِدَنَّهُمْ أَحْرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةٍ وَمِنَ ٱلَّذِينَ أَشْرَكُوا۟ ۚ يَوَدُّ أَحَدُهُمْ لَوْ يُعَمَّرُ أَلْفَ سَنَةٍ وَمَا هُوَ بِمُزَحْزِحِهِۦ مِنَ ٱلْعَذَابِ أَن يُعَمَّرَ ۗ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ","tafsir":"(قُلْ) يا رسول الله لهؤلاء اليهود، الذين يقولون أن الآخرة هي لهم وحدهم لا يشركون فيها غيرهم من النصارى والمسلمين وغيرهما (إِنْ كانَتْ لَكُمُ الدَّارُ الْآخِرَةُ عِنْدَ اللهِ خالِصَةً مِنْ دُونِ النَّاسِ) عند الله صفة للدار الآخرة، أي الدار التي هي عند الله، ومن دون الناس صفة لخالصته، أو لقوله «لكم» (فَتَمَنَّوُا الْمَوْتَ) لأن من يدري أن مصيره الجنة، لا بد وأن يتمنى الموت، حتى يخلص من آلام الدنيا وأتعابها (إِنْ كُنْتُمْ صادِقِينَ) في مقالكم وكنتم تعتقدون ما تقولونه بألسنتكم."},{"text":"قُلْ مَن كَانَ عَدُوًّا لِّجِبْرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلْبِكَ بِإِذْنِ ٱللَّهِ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَهُدًى وَبُشْرَىٰ لِلْمُؤْمِنِينَ","tafsir":"كيف يتمنون الموت ، والحال أنك يا رسول الله ( لَتَجِدَنَّهُمْ أَحْرَصَ النَّاسِ عَلى حَياةٍ ) فإنهم أشد حرصا من سائر الناس على البقاء في الدنيا ، لأنهم يعلمون أن آخرتهم إلى النار والعذاب ( وَ ) حتى أنهم أحرص ( مِنَ الَّذِينَ أَشْرَكُوا ) إذ المشرك ، يزعم أنه لا شيء وراءه ، فيكون حريصا على البقاء لئلا يفنى ، وهؤلاء حيث يعلمون العقاب ، فهم أحرص من المشركين ( يَوَدُّ ) أي يحب ( أَحَدُهُمْ ) أي كل واحد منهم ( لَوْ يُعَمَّرُ ) ويطول عمره ( أَلْفَ سَنَةٍ ) حتى لا يذوق العذاب عاجلا ( وَ ) الحال ( ما هُوَ ) أي ليس التعمير ألف سنة ( بِمُزَحْزِحِهِ مِنَ الْعَذابِ ) زحزحه أي نحاه ، وقوله ( أَنْ يُعَمَّرَ ) بدل « هو » أي ما التعمير بمزحزحه من العذاب ، فما الفائدة في البقاء ألف سنة لمن عاقبته النار ( وَاللهُ بَصِيرٌ بِما يَعْمَلُونَ ) من الكفر والسيئات ، فيجازيهم عليها يوم القيامة بالنار والعذاب."},{"text":"مَن كَانَ عَدُوًّا لِّلَّهِ وَمَلَـٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبْرِيلَ وَمِيكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوٌّ لِّلْكَـٰفِرِينَ","tafsir":"يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم لليهود الذين جاءوك وقالوا لك لو أن الملك الذي يأتيك ميكائيل لآمنّا بك فإنه ملك الرحمة يأتي بالسرور والرخاء وهو صديقنا وجبرائيل ملك العذاب ينزل بالقتل والشدة والحرب وهو عدونا فإن كان ينزل عليك جبرائيل لا نؤمن بك ( مَنْ كانَ عَدُوًّا لِجِبْرِيلَ فَإِنَّهُ نَزَّلَهُ عَلى قَلْبِكَ بِإِذْنِ اللهِ مُصَدِّقاً لِما بَيْنَ يَدَيْهِ وَهُدىً وَبُشْرى لِلْمُؤْمِنِينَ (97) مَنْ كانَ عَدُوًّا لِلَّهِ وَمَلائِكَتِهِ وَرُسُلِهِ وَجِبْرِيلَ وَمِيكالَ فَإِنَّ اللهَ عَدُوٌّ لِلْكافِرِينَ (98) وَلَقَدْ أَنْزَلْنا إِلَيْكَ آياتٍ بَيِّناتٍ وَما يَكْفُرُ بِها إِلاَّ الْفاسِقُونَ (99) لِجِبْرِيلَ فَإِنَّهُ ) ليس سببا فيما يعمل حتى تتخذونه عدوا بل إنه ( نَزَّلَهُ ) أي القرآن ( عَلى قَلْبِكَ بِإِذْنِ اللهِ ) لا من عند نفسه ( مُصَدِّقاً لِما بَيْنَ يَدَيْهِ ) أي للكتاب الذي قبله وهو التوراة ( وَهُدىً وَبُشْرى لِلْمُؤْمِنِينَ ) فأي ذنب لجبريل عليه‌السلام حتى تتخذونه عدوا ولا تؤمنون بالكتاب الذي يأتي به."},{"text":"وَلَقَدْ أَنزَلْنَآ إِلَيْكَ ءَايَـٰتٍۭ بَيِّنَـٰتٍ ۖ وَمَا يَكْفُرُ بِهَآ إِلَّا ٱلْفَـٰسِقُونَ","tafsir":"أي يفعل فعل المعادي من الإتيان بما يكرهه سبحانه ( وَمَلائِكَتِهِ وَرُسُلِهِ وَجِبْرِيلَ وَمِيكالَ ) وإنما خصهما بالذكر لأنهما موضع البحث مع اليهود ( فَإِنَّ اللهَ عَدُوٌّ لِلْكافِرِينَ ) إذ كل من يعادي أحد هؤلاء يكون كافرا والله عدو لمن كفر أي يفعل معه فعل المعادي من الإهانة والتعذيب والعقاب."},{"text":"أَوَكُلَّمَا عَـٰهَدُوا۟ عَهْدًا نَّبَذَهُۥ فَرِيقٌ مِّنْهُم ۚ بَلْ أَكْثَرُهُمْ لَا يُؤْمِنُونَ","tafsir":"يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( آياتٍ بَيِّناتٍ ) واضحات ( وَما يَكْفُرُ بِها إِلَّا الْفاسِقُونَ ) الفاسق هو الخارج عن طاعة الله سبحانه. أَ وَكُلَّما عاهَدُوا عَهْداً نَبَذَهُ فَرِيقٌ مِنْهُمْ بَلْ أَكْثَرُهُمْ لا يُؤْمِنُونَ (100) وَلَمَّا جاءَهُمْ رَسُولٌ مِنْ عِنْدِ اللهِ مُصَدِّقٌ لِما مَعَهُمْ نَبَذَ فَرِيقٌ مِنَ الَّذِينَ أُوتُوا الْكِتابَ كِتابَ اللهِ وَراءَ ظُهُورِهِمْ كَأَنَّهُمْ لا يَعْلَمُونَ (101) وَاتَّبَعُوا ما تَتْلُوا الشَّياطِينُ عَلى مُلْكِ سُلَيْمانَ"},{"text":"وَلَمَّا جَآءَهُمْ رَسُولٌ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ نَبَذَ فَرِيقٌ مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ كِتَـٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمْ كَأَنَّهُمْ لَا يَعْلَمُونَ","tafsir":"أي اليهود ( عَهْداً نَبَذَهُ ) أي نقضه ( فَرِيقٌ مِنْهُمْ ) أي جماعة ( بَلْ أَكْثَرُهُمْ لا يُؤْمِنُونَ ) وهذا إنكار عليهم في نقضهم عهود الأنبياء السابقين بإطاعتهم ونقضهم عهود رسول الله صلى‌الله‌عليه‌وآله‌وسلم في قصة نضير وقريضة والمراد بالإيمان : إما الإيمان بالعهود وإما الإيمان بالله ورسله وإما الإيمان بالرسول صلى‌الله‌عليه‌وآله‌وسلم ، وإنما قال أكثرهم لأن بعضهم آمن كعبد الله بن سلام."},{"text":"وَٱتَّبَعُوا۟ مَا تَتْلُوا۟ ٱلشَّيَـٰطِينُ عَلَىٰ مُلْكِ سُلَيْمَـٰنَ ۖ وَمَا كَفَرَ سُلَيْمَـٰنُ وَلَـٰكِنَّ ٱلشَّيَـٰطِينَ كَفَرُوا۟ يُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحْرَ وَمَآ أُنزِلَ عَلَى ٱلْمَلَكَيْنِ بِبَابِلَ هَـٰرُوتَ وَمَـٰرُوتَ ۚ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ ۖ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيْنَ ٱلْمَرْءِ وَزَوْجِهِۦ ۚ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنْ أَحَدٍ إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ ۚ وَلَقَدْ عَلِمُوا۟ لَمَنِ ٱشْتَرَىٰهُ مَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِنْ خَلَـٰقٍ ۚ وَلَبِئْسَ مَا شَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ","tafsir":"أي اليهود ( رَسُولٌ مِنْ عِنْدِ اللهِ ) كعيسى عليه‌السلام ومحمد صلى‌الله‌عليه‌وآله‌وسلم ( مُصَدِّقٌ لِما مَعَهُمْ ) من التوراة ( نَبَذَ فَرِيقٌ ) أي جماعة ( مِنَ الَّذِينَ أُوتُوا الْكِتابَ ) من اليهود الذين آتاهم الله التوراة ( كِتابَ اللهِ وَراءَ ظُهُورِهِمْ ) وتركوا أوامره باتباع الأنبياء عليهم‌السلام من بعد موسى عليه‌السلام ( كَأَنَّهُمْ لا يَعْلَمُونَ ) أي من أحكام التوراة الإيمان بالأنبياء واتباع الرسل."},{"text":"وَلَوْ أَنَّهُمْ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَمَثُوبَةٌ مِّنْ عِندِ ٱللَّهِ خَيْرٌ ۖ لَّوْ كَانُوا۟ يَعْلَمُونَ","tafsir":"عوض الكتاب ـ السحر ـ فنبذوا الكتاب وراء ظهورهم وراحوا يتعلقون ب ( ما تَتْلُوا ) وتقر ( الشَّياطِينُ ) والسحرة ( عَلى مُلْكِ سُلَيْمانَ ) بن داود عليهم‌السلام حيث أن الشياطين على لسان السحرة على وَما كَفَرَ سُلَيْمانُ وَلكِنَّ الشَّياطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ زمان سليمان كانوا يتلون السحر للناس و « على » بمعنى « في » كما قال ابن مالك « على للاستعلاء ومعنى في وعن » أي أن اليهود أخذوا يتعلقون بالسحر الذي كان في زمان سليمان يريدون بذلك جلب الأموال والتقرب إلى الناس وكانوا يقولون أن سليمان عليه‌السلام إنما أوتي الملك العظيم بسبب أنه كان يعمل بالسحر فرد الله عليهم بقوله ( وَما كَفَرَ سُلَيْمانُ ) فإن السحر موجب للكفر ولا يخفى أن الكفر على نوعين : كفر في العقيدة وكفر في العمل ، فالكفر في العقيدة هو إنكار أصول الدين ، والكفر في العمل هو ترك واجب أو فعل ، ولذا شاع استعمال الكفر على ترك الأوامر وفعل النواهي كقوله تعالى ( وَمَنْ كَفَرَ فَإِنَّ اللهَ غَنِيٌّ عَنِ الْعالَمِينَ ) (1) في قصة الحج وقوله ( وَلَئِنْ كَفَرْتُمْ إِنَّ عَذابِي لَشَدِيدٌ ) (2) في باب الشكر و قول النبي صلى‌الله‌عليه‌وآله‌وسلم « كفر بالله العظيم من هذه الأمة عشرة » وعدّ منها النمام ونحوه وعلى أي حال فسليمان ما كان ساحرا ولم ينل ما نال بالسحر وإنما بالنبوة والموهبة الإلهية. ( وَلكِنَّ الشَّياطِينَ كَفَرُوا ) بعملهم بالسحر وتعليمهم للناس إياه والشياطين أرواح شريرة تلقي الشر في النفوس كما ثبت في العلم الحديث أيضا وغيره في باب التحضير والتنويم المغناطيسي ( يُعَلِّمُونَ النَّاسَ السِّحْرَ ) والسحر أمور غير طبيعية تأتي بعلاج خفي ومنه التصرف ( 1) آل عمران : 98. ( 2) إبراهيم : 8. وَما أُنْزِلَ عَلَى الْمَلَكَيْنِ بِبابِلَ هارُوتَ وَمارُوتَ وَما يُعَلِّمانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّما نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ فَيَتَعَلَّمُونَ مِنْهُما ما يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ في العين وفي النفس وفي العقل فيوجب عداوة بين الناس ومرضا وما أشبه ( وَما أُنْزِلَ عَلَى الْمَلَكَيْنِ ) عطف على قوله « ما تتلوا » أي أن اليهود تركوا الكتاب واتبعوا سحر الشياطين وسحر الملكين ومن قصتهما أن بعد نوح عليه‌السلام كثرت السحرة فأنزل الله ملكين في « بابل » على نبي ذلك الزمان حتى يعلمان الناس إبطال السحر فكانا يقولان للناس « هذا السحر وهذا إبطاله » كالطبيب الذي يكتب كتاب الطب فيصف الداء وما يسببه والدواء المزيل له فيقول مثلا إن الشيء الفلاني سم ودواؤه كذا فكان الملكان يعلمان السحر وإبطاله ويحذران الناس أن يعملوا بالسحر وإنما يصران أن يبطلوا السحر فإذا تعلم منهما الناس أخذ بعضهم بالسحر كما أن الشخص يقرأ كتاب الطب فيسقي الناس السم لم يكن ذلك من ذنب المؤلف للطب وإنما هو من العامل بما يضر الناس. فقد ترك اليهود كتاب الله وأخذوا بالعلم الذي أنزل ـ أي أنزل الله ـ على الملكين الذين نزلا ( بِبابِلَ ) وهما ( هارُوتَ وَمارُوتَ ) ولا يظن أحد أنهما كيف يعلمان السحر للناس وهما ملكان من قبل الله تعالى ( وَ ) ذلك لأنه ( ما يُعَلِّمانِ مِنْ أَحَدٍ ) أي ما يعلمان أحد السحر ( حَتَّى يَقُولا ) له ( إِنَّما نَحْنُ فِتْنَةٌ ) وامتحان لك وكان تعليم للعلاج لا للإضرار ( فَلا تَكْفُرْ ) بأعمال السحر ( فَيَتَعَلَّمُونَ ) أي الناس ( مِنْهُما ) أي من الملكين ( ما يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ ) وما وَما هُمْ بِضارِّينَ بِهِ مِنْ أَحَدٍ إِلاَّ بِإِذْنِ اللهِ وَيَتَعَلَّمُونَ ما يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَلَقَدْ عَلِمُوا لَمَنِ اشْتَراهُ ما لَهُ فِي الْآخِرَةِ مِنْ خَلاقٍ وَلَبِئْسَ ما شَرَوْا بِهِ أَنْفُسَهُمْ لَوْ كانُوا يَعْلَمُونَ (102) يوجب العداوة والبغضاء بين الزوجين مما يؤول إلى الفراق والطلاق ( وَ ) لا يتوهم أن الأمر خرج من يد الله سبحانه كلا بل إنما شاء الله أن يختبر عباده كما أنه حين يخلق العنب ويعطي القدرة للبشر فيعصره خمرا لا يخرج الأمر من يده سبحانه بل إنما ذلك للامتحان والابتلاء ولهذا قال سبحانه ( ما هُمْ ) أي الملكان ومتعلم السحر منهما ( بِضارِّينَ بِهِ ) أي بسبب السحر ( مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللهِ ) فإن شيئا لا يؤثر في شيء إطلاقا إلا بإذن الله ومعنى إذنه أنه يخلي بين المؤثر والمتأثر ولو لم يخل كان عالم الجبر وبطل الامتحان والاختبار والمراد بهذه الجملة أن شيئا لا يخرج من إرادة الله سبحانه حتى أن يتمكن من الردع لكنه لا يردع. ( وَيَتَعَلَّمُونَ ) أي يتعلم الناس من الملكين ( ما يَضُرُّهُمْ ) أي الشيء الذي يضرهم في دنياهم ودينهم ( وَلا يَنْفَعُهُمْ ) أكد بذلك ردّا لزعمهم أن السحر ينفعهم حيث يوصلهم إلى أغراضهم ( وَلَقَدْ عَلِمُوا لَمَنِ اشْتَراهُ ) أي علم المتعلمون للسحر أن من اشترى السحر وباع دينه ( ما لَهُ فِي الْآخِرَةِ مِنْ خَلاقٍ ) أي من نصيب ( وَلَبِئْسَ ما شَرَوْا بِهِ أَنْفُسَهُمْ ) فإنهم أعطوا أنفسهم للنار مقابل اشتراء السحر الذي زعموا وَلَوْ أَنَّهُمْ آمَنُوا وَاتَّقَوْا لَمَثُوبَةٌ مِنْ عِنْدِ اللهِ خَيْرٌ لَوْ كانُوا يَعْلَمُونَ (103) يا أَيُّهَا الَّذِينَ آمَنُوا لا تَقُولُوا راعِنا وَقُولُوا انْظُرْنا وَاسْمَعُوا وَلِلْكافِرِينَ عَذابٌ أَلِيمٌ (104) إنه ينفع دنياهم ( لَوْ كانُوا يَعْلَمُونَ ) نزل العالم بالشيء منزلة الجاهل حيث لم يعمل بعلمه فإن من لا يعمل بعلمه هو والجاهل سواء."},{"text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقُولُوا۟ رَٰعِنَا وَقُولُوا۟ ٱنظُرْنَا وَٱسْمَعُوا۟ ۗ وَلِلْكَـٰفِرِينَ عَذَابٌ أَلِيمٌ","tafsir":"أي اليهود بدل اتباع السحر ( آمَنُوا ) حقيقة ( وَاتَّقَوْا ) عن فعل المعاصي ( لَمَثُوبَةٌ ) أي ثواب ( مِنْ عِنْدِ اللهِ خَيْرٌ ) لهم في دنياهم وآخرتهم ( لَوْ كانُوا يَعْلَمُونَ ) لكنهم حيث لا يعملون بذلك فكأنهم لا يعلمونه."},{"text":"مَّا يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَلَا ٱلْمُشْرِكِينَ أَن يُنَزَّلَ عَلَيْكُم مِّنْ خَيْرٍ مِّن رَّبِّكُمْ ۗ وَٱللَّهُ يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ","tafsir":"للرسول حين كلامكم معه ( راعِنا ) فإن راعنا في اللغة العربية من المراعاة والرعاية ، ولكنها في لغة اليهود بمعنى « أسمعت لا سمعت » فهو سب ودعاء على المخاطب وقد كانت اليهود اغتنمت هذه الكلمة المتشابهة لسب النبي صلى‌الله‌عليه‌وآله‌وسلم بهذا العنوان فكانوا يأتون إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم ويقولون له « راعنا » يريدون بذلك سبه صلى‌الله‌عليه‌وآله‌وسلم فنهى الله المسلمين عن هذه اللفظة حتى لا يتمكن اليهود من التكلم بهذه الكلمة ( وَقُولُوا ) عوض ذلك ( انْظُرْنا ) أي انظر إلينا بنظرتك الرحيمة ( وَاسْمَعُوا ) أيها المؤمنون أوامرنا وأوامر الرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَلِلْكافِرِينَ ) من اليهود الشاتمين للنبي صلى‌الله‌عليه‌وآله‌وسلم تحت ستار لفظة « راعنا » ( عَذابٌ أَلِيمٌ ) أي مؤلم في الآخرة. ما يَوَدُّ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتابِ وَلا الْمُشْرِكِينَ أَنْ يُنَزَّلَ عَلَيْكُمْ مِنْ خَيْرٍ مِنْ رَبِّكُمْ وَاللهُ يَخْتَصُّ بِرَحْمَتِهِ مَنْ يَشاءُ وَاللهُ ذُو الْفَضْلِ الْعَظِيمِ (105) ما نَنْسَخْ مِنْ آيَةٍ أَوْ نُنْسِها نَأْتِ بِخَيْرٍ مِنْها أَوْ مِثْلِها أَ لَمْ تَعْلَمْ"},{"text":"۞ مَا نَنسَخْ مِنْ ءَايَةٍ أَوْ نُنسِهَا نَأْتِ بِخَيْرٍ مِّنْهَآ أَوْ مِثْلِهَآ ۗ أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ","tafsir":"من اليهود والنصارى والمجوس ( وَلَا ) من ( الْمُشْرِكِينَ أَنْ يُنَزَّلَ عَلَيْكُمْ مِنْ خَيْرٍ مِنْ ) قبل ( رَبِّكُمْ ) سواء كان خيرا معنويا كالنبوة والإرشاد والوحي أو ماديا كالغلبة والنصر والمال ( وَاللهُ يَخْتَصُّ بِرَحْمَتِهِ مَنْ يَشاءُ ) فليس إرادة الله تبعا لإرادة الكفار والمشركين ( وَاللهُ ذُو الْفَضْلِ الْعَظِيمِ ) فليس فضله خاصا بقوم من الكفار كما كانت اليهود تزعم أن النبوة فيهم دون غيرهم."},{"text":"أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۗ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ","tafsir":"بأن نرفع حكمها ونجعل مكانه حكما آخر ( أَوْ نُنْسِها ) بأن نرفع رسمها ونبلي عن القلوب حفظها ، والنسيان لا يقع بالنسبة إلى القرآن الكريم وإنما بالنسبة إلى الكتب السالفة ولذا لا يوجد كثير منها فعلا ، أما النسخ فإنه وقع بالنسبة إلى القرآن ـ على الأشهر ـ وإلى غيره ( نَأْتِ بِخَيْرٍ مِنْها أَوْ مِثْلِها ) وإنما يقع النسخ والإنساء فيما يؤتى بالمثل لأن المثل أصلح من المنسوخ والمنسي ، فمثلا إذا سقطت ورقة مالية عن الاعتبار فيأتي الحاكم بورقة أخرى مثلها في القيمة ، كما أنه قد يأخذ درهما من زيد ليعطيه بدله دينارا ( أَ لَمْ تَعْلَمْ ) أيها اليهودي أَنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ (106) أَ لَمْ تَعْلَمْ أَنَّ اللهَ لَهُ مُلْكُ السَّماواتِ وَالْأَرْضِ وَما لَكُمْ مِنْ دُونِ اللهِ مِنْ وَلِيٍّ وَلا نَصِيرٍ (107) أَمْ تُرِيدُونَ أَنْ تَسْئَلُوا رَسُولَكُمْ كَما سُئِلَ مُوسى المنكر للنسخ ( أَنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) فإن اليهود كانوا يلقون الشبهة بأنه كيف يمكن نسخ كتابهم بالقرآن وأنه إن كان كتابهم صالحا فلما ذا ينسخ وإن لم يكن صالحا فلما ذا أنزله الله تعالى ، وقد كان الجواب إن عدم النسخ إما لعدم مثل أو أصلح وإما لعدم قدرة الله تعالى على النسخ وكلا الأمرين مفقودان ، فالمثل والأصلح موجودان والله على كل شيء قدير."},{"text":"أَمْ تُرِيدُونَ أَن تَسْـَٔلُوا۟ رَسُولَكُمْ كَمَا سُئِلَ مُوسَىٰ مِن قَبْلُ ۗ وَمَن يَتَبَدَّلِ ٱلْكُفْرَ بِٱلْإِيمَـٰنِ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ","tafsir":"أيها المنكر للنسخ ( أَنَّ اللهَ لَهُ مُلْكُ السَّماواتِ وَالْأَرْضِ ) فيتصرف فيما يشاء من الأوضاع والأحكام كيف يشاء ( وَما لَكُمْ مِنْ دُونِ اللهِ ) أي غير الله ( مِنْ وَلِيٍ ) يلي أموركم ( وَلا نَصِيرٍ ) ينصركم فهو سبحانه يرى صلاحكم في النسخ والإنساء فإن المصالح تختلف حسب اختلاف الأعصار والأشخاص ، ولقد كان شأن آيات الله أن تنهض بالبشر مرتبة فمرتبة حتى وصلت النوبة لرسالة الإسلام وهذه بدلت بعض جزئياتها قبل تمامها وكمالها تحقيقا للتناسق بين الرسالة وبين العصر ، حتى إذا كملت لم يبق مبرر أو تحوير بل تبقى إلى الأبد."},{"text":"وَدَّ كَثِيرٌ مِّنْ أَهْلِ ٱلْكِتَـٰبِ لَوْ يَرُدُّونَكُم مِّنۢ بَعْدِ إِيمَـٰنِكُمْ كُفَّارًا حَسَدًا مِّنْ عِندِ أَنفُسِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْحَقُّ ۖ فَٱعْفُوا۟ وَٱصْفَحُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦٓ ۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ","tafsir":"أيها المعاصرون للرسول صلى‌الله‌عليه‌وآله‌وسلم من مسلم وكتابي ومشرك ( أَنْ تَسْئَلُوا رَسُولَكُمْ ) أسئلة تعنت ولجاجة ( كَما سُئِلَ مُوسى مِنْ قَبْلُ وَمَنْ يَتَبَدَّلِ الْكُفْرَ بِالْإِيمانِ فَقَدْ ضَلَّ سَواءَ السَّبِيلِ (108) وَدَّ كَثِيرٌ مِنْ أَهْلِ الْكِتابِ لَوْ يَرُدُّونَكُمْ مِنْ بَعْدِ إِيمانِكُمْ كُفَّاراً حَسَداً مِنْ عِنْدِ أَنْفُسِهِمْ مِنْ قَبْلُ ) حيث كانوا يقترحون عليه اقتراحات ويسألونه محالات كقولهم لن نؤمن لك حتى نرى الله جهرة ، فإن المعاصرين كانوا يسألون ما لا يعنيهم أو ما أشبه كقولهم ( أَوْ تُسْقِطَ السَّماءَ كَما زَعَمْتَ عَلَيْنا كِسَفاً ) (1) فقد زجرهم الله سبحانه لهذه الأسئلة التي لا ترتبط بمقام الرسول والرسالة من بعد ما تبين لهم الهدى ، وقوله « رسولكم » لا يختص بالمؤمنين إذ يكفي في الإضافة أدنى ملابسة ( وَمَنْ يَتَبَدَّلِ الْكُفْرَ بِالْإِيمانِ ) بأن يأخذ الكفر ويترك الإيمان الذي من مصاديقه الأسئلة التعنتية إذ إنها من سمات الكفر والانحراف ( فَقَدْ ضَلَّ سَواءَ السَّبِيلِ ) أي وسطه الموصل إلى المطلوب."},{"text":"وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ ٱللَّهِ ۗ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ","tafsir":"أي أحب ( كَثِيرٌ مِنْ أَهْلِ الْكِتابِ ) اليهود والنصارى والمجوس ( لَوْ يَرُدُّونَكُمْ ) أيها المسلمون ( مِنْ بَعْدِ إِيمانِكُمْ كُفَّاراً ) فتكونون مثلهم ( حَسَداً ) لكم كيف صرتم إلى حضرة الإيمان وتقدمتم في الحياة وهذا الحب ليس من جهة أنهم متدينون فيأسفون عليكم لماذا تركتم الإيمان بل الحب ( مِنْ عِنْدِ أَنْفُسِهِمْ ) تشبيها ( 1) الإسراء : 93. مِنْ بَعْدِ ما تَبَيَّنَ لَهُمُ الْحَقُّ فَاعْفُوا وَاصْفَحُوا حَتَّى يَأْتِيَ اللهُ بِأَمْرِهِ إِنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ (109) وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكاةَ وَما تُقَدِّمُوا لِأَنْفُسِكُمْ مِنْ خَيْرٍ تَجِدُوهُ عِنْدَ اللهِ إِنَّ اللهَ بِما تَعْمَلُونَ بَصِيرٌ (110) وَقالُوا لَنْ يَدْخُلَ الْجَنَّةَ إِلاَّ مَنْ كانَ هُوداً أَوْ نَصارى تِلْكَ وحسب أهوائهم أي أن مبدأ الحب هوى النفس لا الدين ( مِنْ بَعْدِ ما تَبَيَّنَ لَهُمُ الْحَقُ ) فليس ذلك لجهلهم بدينكم وحقيقتكم ( فَاعْفُوا ) أيها المسلمون عنهم ( وَاصْفَحُوا ) عن أعمال الكفار ولا تقابلوا إساءتهم بالمثل ( حَتَّى يَأْتِيَ اللهُ بِأَمْرِهِ ) فيأذن لكم في المبارزة والمقاتلة والمقابلة بالمثل ( إِنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) فيأتي يوم يجعلكم أقوياء فتتمكنوا من محاربة هؤلاء الكفار فيأذن لكم في المبارزة معهم."},{"text":"وَقَالُوا۟ لَن يَدْخُلَ ٱلْجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوْ نَصَـٰرَىٰ ۗ تِلْكَ أَمَانِيُّهُمْ ۗ قُلْ هَاتُوا۟ بُرْهَـٰنَكُمْ إِن كُنتُمْ صَـٰدِقِينَ","tafsir":"أما إذا لم يأت الله بأمره ف ( أَقِيمُوا الصَّلاةَ وَآتُوا الزَّكاةَ ) ولا تبارزوا ( وَما تُقَدِّمُوا لِأَنْفُسِكُمْ ) من إعطاء الزكاة وسائر الخيرات التي هي لأنفسكم لأنها تعود إليكم في الدنيا بالألفة وفي الآخرة بالثواب ( مِنْ خَيْرٍ تَجِدُوهُ عِنْدَ اللهِ ) يوم القيامة و ( إِنَّ اللهَ بِما تَعْمَلُونَ بَصِيرٌ ) فلا يضيع شيء يصرف في وجهه ولا عمل يؤتى لأجله."},{"text":"بَلَىٰ مَنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌ فَلَهُۥٓ أَجْرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ","tafsir":"قالت اليهود : لن يدخلها إلا اليهود ، وقالت النصارى : لن يدخلها إلا النصارى ، وهود جمع هائد ، كعود جمع عائد ( تِلْكَ ) المقالة أَمانِيُّهُمْ قُلْ هاتُوا بُرْهانَكُمْ إِنْ كُنْتُمْ صادِقِينَ (111) بَلى مَنْ أَسْلَمَ وَجْهَهُ لِلَّهِ وَهُوَ مُحْسِنٌ فَلَهُ أَجْرُهُ عِنْدَ رَبِّهِ وَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ (112) وَقالَتِ الْيَهُودُ لَيْسَتِ النَّصارى عَلى شَيْءٍ وَقالَتِ النَّصارى لَيْسَتِ الْيَهُودُ عَلى شَيْءٍ وَهُمْ يَتْلُونَ الْكِتابَ ( أَمانِيُّهُمْ ) جمع أمنية أي رغبتهم الكاذبة ( قُلْ ) يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم لهم ( هاتُوا ) أي احضروا وجيئوا ( بُرْهانَكُمْ ) ودليلكم على ما تدّعون ( إِنْ كُنْتُمْ صادِقِينَ ) في مقالتكم."},{"text":"وَقَالَتِ ٱلْيَهُودُ لَيْسَتِ ٱلنَّصَـٰرَىٰ عَلَىٰ شَىْءٍ وَقَالَتِ ٱلنَّصَـٰرَىٰ لَيْسَتِ ٱلْيَهُودُ عَلَىٰ شَىْءٍ وَهُمْ يَتْلُونَ ٱلْكِتَـٰبَ ۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ لَا يَعْلَمُونَ مِثْلَ قَوْلِهِمْ ۚ فَٱللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ ٱلْقِيَـٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ","tafsir":"جواب سؤال تقديره أ فليس يدخل الجنة أحد ومن هو ؟ فقيل ( مَنْ أَسْلَمَ وَجْهَهُ لِلَّهِ ) وخص الوجه لأنه أشرف الأعضاء فإذا أسلمه الشخص فقد أسلم جميع جوارحه ( وَهُوَ مُحْسِنٌ ) في عمله ( فَلَهُ أَجْرُهُ عِنْدَ رَبِّهِ وَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ ) فهو يدخل الجنة سواء كان يهوديا في زمان موسى أو نصرانيا في زمان عيسى أو مسلما في زمان محمد أو من سائر الأمم في زمان أنبيائها عليهم‌السلام . وهذا كلام معه دليله إذ معيار الدخول في الجنة الإيمان والعمل الصالح فلا يقال لمن يقول ذلك : هات برهانك."},{"text":"وَمَنْ أَظْلَمُ مِمَّن مَّنَعَ مَسَـٰجِدَ ٱللَّهِ أَن يُذْكَرَ فِيهَا ٱسْمُهُۥ وَسَعَىٰ فِى خَرَابِهَآ ۚ أُو۟لَـٰٓئِكَ مَا كَانَ لَهُمْ أَن يَدْخُلُوهَآ إِلَّا خَآئِفِينَ ۚ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ","tafsir":"من دين وإيمان وتقوى فكل طائفة تجعل نفسها الناجية وغيرها الهالكة ( وَ ) الحال إن ( هُمْ يَتْلُونَ الْكِتابَ ) والتالي كَذلِكَ قالَ الَّذِينَ لا يَعْلَمُونَ مِثْلَ قَوْلِهِمْ فَاللهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيامَةِ فِيما كانُوا فِيهِ يَخْتَلِفُونَ (113) وَمَنْ أَظْلَمُ مِمَّنْ مَنَعَ مَساجِدَ اللهِ أَنْ يُذْكَرَ فِيهَا اسْمُهُ وَسَعى فِي خَرابِها أُولئِكَ ما كانَ لَهُمْ أَنْ للكتاب لا يحق له أن يقول مثل هذه المقالة إذ كل منهم يعلم أن صاحبه على بعض الشيء ، فإن اليهود يعرفون أن النصارى لهم إيمان في الجملة وكذلك النصارى يعرفون أن اليهود لهم إيمان في الجملة ( كَذلِكَ ) القول ( قالَ الَّذِينَ لا يَعْلَمُونَ ) من الكفار ( مِثْلَ قَوْلِهِمْ ) وهذا تأنيب للطائفتين حيث صاروا كمن لا كتاب له وهو جاهل فإن الجاهل يمكن إن يقول ليس اليهود أو النصارى على شيء لأنه يزعم بطلان كليهما ( فَاللهُ يَحْكُمُ بَيْنَهُمْ ) جميعا ( يَوْمَ الْقِيامَةِ ) وهناك يتبين لكل طائفة إنه على شيء أم لا ( فِيما كانُوا فِيهِ يَخْتَلِفُونَ ) ولعل تخصيص الحكم بهناك لأن هناك لا تبقى شبهة في الحكم بخلاف حكمه سبحانه في الدنيا فإن من لا يؤمن بالإسلام لا يعترف بحكمه."},{"text":"وَلِلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ ۚ فَأَيْنَمَا تُوَلُّوا۟ فَثَمَّ وَجْهُ ٱللَّهِ ۚ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمٌ","tafsir":"وهي عامة لكل مانع وإن كان ينطبق على أهل مكة الذين منعوا الرسول صلى‌الله‌عليه‌وآله‌وسلم عن المسجد الحرام وبخت نصّر الذي منع عن بيت المقدس ( أَنْ يُذْكَرَ فِيهَا اسْمُهُ ) أي لا أحد أظلم من هكذا شخص والحصر المستفاد من الآية إضافي وإلا فمن قتل الأنبياء أظلم ( وَسَعى فِي خَرابِها ) خرابا معنويا بمنع المصلين عنها أو خراب العمارة والبناء ( أُولئِكَ ما كانَ لَهُمْ أَنْ يَدْخُلُوها إِلاَّ خائِفِينَ لَهُمْ فِي الدُّنْيا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذابٌ عَظِيمٌ (114) وَلِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ فَأَيْنَما تُوَلُّوا فَثَمَّ وَجْهُ اللهِ إِنَّ اللهَ واسِعٌ عَلِيمٌ (115) وَقالُوا اتَّخَذَ اللهُ وَلَداً يَدْخُلُوها إِلَّا خائِفِينَ ) من عذاب الله سبحانه ، فمن يسعى في خراب المساجد كيف يدخلها آمنا أو خائفين من المسلمين أن يعاقبوهم ( لَهُمْ فِي الدُّنْيا خِزْيٌ ) بالعقاب الإسلامي لمن فعل ذلك أو إخبار بخزي عن الله سبحانه ينزل بمن يسعى في خراب المساجد ( وَلَهُمْ فِي الْآخِرَةِ عَذابٌ عَظِيمٌ ) حيث يذوق النار مهانا ولعل هاتين الآيتين أيضا تلميح إلى فعل اليهود بمنعهم عن المساجد."},{"text":"وَقَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا ۗ سُبْحَـٰنَهُۥ ۖ بَل لَّهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ كُلٌّ لَّهُۥ قَـٰنِتُونَ","tafsir":"فكلتا الجهتين له سبحانه خلقها وهما ملك له وحده ( فَأَيْنَما تُوَلُّوا ) وجوهكم ( فَثَمَّ وَجْهُ اللهِ ) وجه الله جانبه أي أن الله سبحانه محيط بالعلم والقدرة على كل ناحية فإذا توجه الإنسان إلى المشرق فقد توجه إلى الله وإذا توجه إلى المغرب فقد توجه إلى الله ، وليس الله جسما حتى يكون له مكان معين يلزم التوجه إليه ( إِنَّ اللهَ واسِعٌ ) علما وقدرة لأنه محيط بجميع الجهات ( عَلِيمٌ ) بما يفعله الإنسان من التوجه إلى أية ناحية ، وربما قيل بأنها نزلت في رد اليهود الذين قالوا كيف انصرف محمد صلى‌الله‌عليه‌وآله‌وسلم عن قبلة بيت المقدس إلى الكعبة."},{"text":"بَدِيعُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ وَإِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ","tafsir":"اليهود عزير ابن الله والنصارى قالوا المسيح ابن الله والمشركون قالوا الملائكة بنات الله ( اتَّخَذَ اللهُ وَلَداً ) أما بأن أولده سُبْحانَهُ بَلْ لَهُ ما فِي السَّماواتِ وَالْأَرْضِ كُلٌّ لَهُ قانِتُونَ (116) بَدِيعُ السَّماواتِ وَالْأَرْضِ وَإِذا قَضى أَمْراً فَإِنَّما يَقُولُ لَهُ كُنْ فَيَكُونُ (117) وَقالَ الَّذِينَ لا يَعْلَمُونَ لَوْ لا يُكَلِّمُنَا اللهُ أَوْ تَأْتِينا آيَةٌ كَذلِكَ قالَ الَّذِينَ مِنْ قَبْلِهِمْ مِثْلَ كما زعم بعضهم أو أتخذ بعنوان التبني ( سُبْحانَهُ ) أي أنزهه عن ذلك تنزيها ( بَلْ لَهُ ما فِي السَّماواتِ وَالْأَرْضِ ) فكيف يكون المملوك ولدا إذ الولد ليس ملكا للوالد ، ثم إن المملوك تحت التصرف فالتبني لماذا .. . ؟ ( كُلٌ ) أي كل من السماوات والأرض ( لَهُ ) تعالى ( قانِتُونَ ) أي خاضعون ومطيعون."},{"text":"وَقَالَ ٱلَّذِينَ لَا يَعْلَمُونَ لَوْلَا يُكَلِّمُنَا ٱللَّهُ أَوْ تَأْتِينَآ ءَايَةٌ ۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ مِن قَبْلِهِم مِّثْلَ قَوْلِهِمْ ۘ تَشَـٰبَهَتْ قُلُوبُهُمْ ۗ قَدْ بَيَّنَّا ٱلْـَٔايَـٰتِ لِقَوْمٍ يُوقِنُونَ","tafsir":"أي مبدعهما ومنشئهما وخالقهما وهذا تأكيد لما في الآية السابقة من أنه ( لَهُ ما فِي السَّماواتِ وَالْأَرْضِ ) ( وَإِذا قَضى أَمْراً ) وأراده ( فَإِنَّما يَقُولُ لَهُ ) أي لذلك الأمر المراد ( كُنْ ) أي يأمره بأن يوجد ( فَيَكُونُ ) أي فيوجد عقيب أمره فالكون بهذا النحو طوع إرادته وأمره."},{"text":"إِنَّآ أَرْسَلْنَـٰكَ بِٱلْحَقِّ بَشِيرًا وَنَذِيرًا ۖ وَلَا تُسْـَٔلُ عَنْ أَصْحَـٰبِ ٱلْجَحِيمِ","tafsir":"بعد ذكر اختلاف أهل الكتاب ومنعهم وسائر المشركين عن المساجد ، وشركهم في باب التوحيد ، تعرض القرآن الحكيم حول كلامهم بالنسبة إلى الرسالة ، فقال ، و ( قالَ الَّذِينَ لا يَعْلَمُونَ ) موازين الوحي والرسالة ( لَوْ لا يُكَلِّمُنَا اللهُ ) أي هلّا يكلمنا ربنا ، بأن يأمرنا بأوامره ، بدون احتياج إلى وسيط ، أو يكلمنا بأنك نبي ( أَوْ تَأْتِينا آيَةٌ ) ومعجزة حسب اقتراحنا ( كَذلِكَ قالَ الَّذِينَ مِنْ قَبْلِهِمْ ) لأنبيائهم ( مِثْلَ قَوْلِهِمْ تَشابَهَتْ قُلُوبُهُمْ قَدْ بَيَّنَّا الْآياتِ لِقَوْمٍ يُوقِنُونَ (118) إِنَّا أَرْسَلْناكَ بِالْحَقِّ بَشِيراً وَنَذِيراً وَلا تُسْئَلُ عَنْ أَصْحابِ الْجَحِيمِ (119) وَلَنْ تَرْضى عَنْكَ الْيَهُودُ وَلا النَّصا رى حَتَّى تَتَّبِعَ مِلَّتَهُمْ قَوْلِهِمْ ) لموسى عليه‌السلام أرنا الله جهرة ( تَشابَهَتْ قُلُوبُهُمْ ) في الإنكار وفي الاقتراح والتعنت ( قَدْ بَيَّنَّا الْآياتِ ) فلا حاجة إلى تكليم الله ، ولا إلى الإتيان بخوارق اقترحوها ، إذ لو كان مرادهم بيان الحق والبرهان ، فقد فعلنا ذلك ، وإن كان مرادهم غير ذلك فليس على الله إلا إتمام الحجة ( لِقَوْمٍ يُوقِنُونَ ) إنما خصهم لأنهم الذين يستفيدون منها وينتفعون بها."},{"text":"وَلَن تَرْضَىٰ عَنكَ ٱلْيَهُودُ وَلَا ٱلنَّصَـٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمْ ۗ قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ ۗ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَ ٱلَّذِى جَآءَكَ مِنَ ٱلْعِلْمِ ۙ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ","tafsir":"يا رسول الله ( بِالْحَقِ ) تأكيد للإرسال ، إذ كل إرسال الله تعالى بالحق ( بَشِيراً ) تبشر المؤمنين المطيعين ( وَنَذِيراً ) تنذر الكافرين والعاصين ، فأنت رسولنا ، وإن كانوا يشكون في رسالتك ، ويسألونك عن أشياء تافهة ( وَلا تُسْئَلُ ) أنت ( عَنْ أَصْحابِ الْجَحِيمِ ) فلست أنت مكلفا عنهم ، وإنما عليك التذكير فقط."},{"text":"ٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يَتْلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُو۟لَـٰٓئِكَ يُؤْمِنُونَ بِهِۦ ۗ وَمَن يَكْفُرْ بِهِۦ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ","tafsir":"حيث أن من طبيعة الحال أن كل صاحب مبدأ ليستميله الخصماء إلى ناحيتهم ، ويعدونه الرضا عنه ، إذا مال نحوهم بيّن الله تعالى لنبيه ، أن ذلك سراب خادع ويجب أن لا يغتر به الإنسان ، إذ ( لَنْ تَرْضى عَنْكَ الْيَهُودُ وَلَا النَّصارى ) إلى الأبد ( حَتَّى تَتَّبِعَ مِلَّتَهُمْ ) وتدخل في طريقتهم ، إذ كل ذي طريقة لا يرض عن شخص إلا قُلْ إِنَّ هُدَى اللهِ هُوَ الْهُدى وَلَئِنِ اتَّبَعْتَ أَهْواءَهُمْ بَعْدَ الَّذِي جاءَكَ مِنَ الْعِلْمِ ما لَكَ مِنَ اللهِ مِنْ وَلِيٍّ وَلا نَصِيرٍ (120) الَّذِينَ آتَيْناهُمُ الْكِتابَ يَتْلُونَهُ حَقَّ تِلاوَتِهِ أُولئِكَ يُؤْمِنُونَ بِهِ وَمَنْ يَكْفُرْ بِهِ فَأُولئِكَ هُمُ الْخاسِرُونَ (121) يا بَنِي إِسْرائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ بدخوله في طريقته تماما وكمالا ( قُلْ ) يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( إِنَّ هُدَى اللهِ ) الذي هو الإسلام ( هُوَ الْهُدى ) فقط دون ما سواه من اليهودية والنصرانية ( وَلَئِنِ اتَّبَعْتَ أَهْواءَهُمْ ) إشارة إلى أن دينهم ليس إلا هوى أنفسهم ، وليس من عند الله سبحانه ( بَعْدَ الَّذِي جاءَكَ مِنَ الْعِلْمِ ) بالإسلام وشرائعه وبطلان اليهودية والنصرانية ( ما لَكَ ) أي ليس لك ( مِنَ اللهِ ) أي من طرف الله ( مِنْ وَلِيٍّ وَلا نَصِيرٍ ) أي فلا يلي الله تعالى أمورك ولا ينصرك."},{"text":"يَـٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَـٰلَمِينَ","tafsir":"التوراة والإنجيل الموصوفين بكذبهم ( يَتْلُونَهُ حَقَّ تِلاوَتِهِ ) بالعمل بما في الكتاب ( أُولئِكَ يُؤْمِنُونَ بِهِ ) أي بالنبي صلى‌الله‌عليه‌وآله‌وسلم أو بالقرآن أو بالإسلام أو بكتابهم إيمانا صحيحا ، لا كإيمان المعاندين الذين يأخذون ببعض الكتاب دون بعض ( وَمَنْ يَكْفُرْ بِهِ فَأُولئِكَ هُمُ الْخاسِرُونَ ) في الدنيا وفي الآخرة ، أما في الدنيا ، فلأن منهاج الله سبحانه هو المنهاج المسعد في الحياة ، فإذا عرض عنه الإنسان ، كانت معيشته ضنكا ، وأما في الآخرة ، فللعذاب المعد للكافرين."},{"text":"وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا عَدْلٌ وَلَا تَنفَعُهَا شَفَـٰعَةٌ وَلَا هُمْ يُنصَرُونَ","tafsir":"من إرسال وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعالَمِينَ (122) وَاتَّقُوا يَوْماً لا تَجْزِي نَفْسٌ عَنْ نَفْسٍ شَيْئاً وَلا يُقْبَلُ مِنْها عَدْلٌ وَلا تَنْفَعُها شَفاعَةٌ وَلا هُمْ يُنْصَرُونَ (123) وَإِذِ ابْتَلى إِبْراهِيمَ رَبُّهُ بِكَلِماتٍ الرسل إليكم ، وإهلاك عدوكم ، وجعلكم ملوكا وتوسيع الدنيا لكم ( وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعالَمِينَ ) في زمانكم ، التي هي من أعظم النعم ـ وقد تقدم الكلام في مثل هذه الآية ـ."},{"text":"۞ وَإِذِ ٱبْتَلَىٰٓ إِبْرَٰهِـۧمَ رَبُّهُۥ بِكَلِمَـٰتٍ فَأَتَمَّهُنَّ ۖ قَالَ إِنِّى جَاعِلُكَ لِلنَّاسِ إِمَامًا ۖ قَالَ وَمِن ذُرِّيَّتِى ۖ قَالَ لَا يَنَالُ عَهْدِى ٱلظَّـٰلِمِينَ","tafsir":"أي يوم القيامة ، الموصوف بأنه ( لا تَجْزِي نَفْسٌ عَنْ نَفْسٍ شَيْئاً ) هناك وإنما ترى كل نفس جزاؤها العادل ، فلا يحمل أحد وزر أحد ( وَلا يُقْبَلُ مِنْها عَدْلٌ ) أي فدية تعادله ، فيفك نفسه بالفدية والمال ( وَلا تَنْفَعُها شَفاعَةٌ ) بدون رضى الله سبحانه ( وَلا هُمْ يُنْصَرُونَ ) فلا ينصر أحد أحدا ، وقد تقدمت مثل هذه الآية ، لكن أريد الانتقال إلى موضوع آخر كرر المطلب السابق تذكيرا وتركيزا."},{"text":"وَإِذْ جَعَلْنَا ٱلْبَيْتَ مَثَابَةً لِّلنَّاسِ وَأَمْنًا وَٱتَّخِذُوا۟ مِن مَّقَامِ إِبْرَٰهِـۧمَ مُصَلًّى ۖ وَعَهِدْنَآ إِلَىٰٓ إِبْرَٰهِـۧمَ وَإِسْمَـٰعِيلَ أَن طَهِّرَا بَيْتِىَ لِلطَّآئِفِينَ وَٱلْعَـٰكِفِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ","tafsir":"حيث تم بعض الكلام عن اليهود والنصارى والمشركين ، انتقل السياق للكلام حول إبراهيم وإسحاق ويعقوب عليهم‌السلام وبناء البيت مما يشترك فيه الجميع ، وإن تاريخهم قبل تاريخ اليهودية والنصرانية ، وقد اعتاد أن يتكلم المتكلم عن الظروف المعاصرة ، ثم ينتقل إلى التواريخ الغابرة ، واذكر يا رسول الله ( إِذِ ابْتَلى ) امتحن ( إِبْراهِيمَ ) عليه‌السلام ( رَبُّهُ ) فاعل ابتلى ، أي امتحن الله إبراهيم ( بِكَلِماتٍ ) أي بأمور ، فإن الكلمة تقال للأمر ، ولا يبعد أن يكون المراد بالكلمة نفس معناها العرفي ، فالمعنى ابتلاه بكلمات تكلم الله أو الملك معه عليه‌السلام حولها لينفذها ، ويأتي بمعناها ، ولعل الكلمات كانت حول ذبح فَأَتَمَّهُنَّ قالَ إِنِّي جاعِلُكَ لِلنَّاسِ إِماماً قالَ وَمِنْ ذُرِّيَّتِي قالَ لا يَنالُ عَهْدِي الظَّالِمِينَ (124) وَإِذْ جَعَلْنَا الْبَيْتَ مَثابَةً لِلنَّاسِ وَأَمْناً وَاتَّخِذُوا مِنْ مَقامِ إِبْراهِيمَ مُصَلًّى إسماعيل عليه‌السلام ، أو حول مجابهة نمرود الطاغي ( فَأَتَمَّهُنَ ) بأن أطاع الأمر كاملا غير منقوص ( قالَ ) الله تعالى بعد إتمام الكلمات ( إِنِّي جاعِلُكَ ) يا إبراهيم ( لِلنَّاسِ إِماماً ) والإمام هو المقتدى ، وحيث أن « الناس » كالجمع المحلى باللام أفاد العموم ، ولا منافاة بين كونه عليه‌السلام سابقا نبيا ورسولا ، ولم يكن إماما عاما ، ثم صار كذلك جزاء إتمام الكلمات ( قالَ ) إبراهيم عليه‌السلام سائلا الله تعالى ( وَمِنْ ذُرِّيَّتِي ) هل تجعل يا رب إماما ؟ وهذا طلب المتأدب يأتي به في لسان الاستفهام ( قالَ لا يَنالُ عَهْدِي ) بالإمامة ( الظَّالِمِينَ ) وهذا جواب مع زيادة ، إذ المفهوم منه ، نعم أجعل بعض ذريتك ، لكن غير الظالم منهم ، وإنما خص هذا بالذكر ، لبيان عظم مقام الإمامة."},{"text":"وَإِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّ ٱجْعَلْ هَـٰذَا بَلَدًا ءَامِنًا وَٱرْزُقْ أَهْلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنْ ءَامَنَ مِنْهُم بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۖ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلًا ثُمَّ أَضْطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِ ۖ وَبِئْسَ ٱلْمَصِيرُ","tafsir":"اذكر يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( إِذْ جَعَلْنَا الْبَيْتَ ) الحرام بمكة المكرمة ( مَثابَةً ) بمعنى مرجعا فإن الناس يرجعون إليه كل عام ، والرجوع بمناسبة مجموع الناس ، وإن لم يرجع إليه كل فرد ( لِلنَّاسِ وَأَمْناً ) فلا يحل القتال فيه ، وإن من التجأ إليه يكون آمنا ، فلا يجري عليه الحد ، ثم صار في الكلام التفات إلى الخطاب قائلا ( وَاتَّخِذُوا ) أيها المسلمون ( مِنْ مَقامِ إِبْراهِيمَ ) وهو الحجر الذي كان يضعه إبراهيم عليه‌السلام تحت رجله لبناء أعالي الكعبة ، الذي هو الآن بالقرب من الكعبة ( مُصَلًّى ) أي محل للصلاة ، فإنه تجب الصلاة للطواف وَعَهِدْنا إِلى إِبْراهِيمَ وَإِسْماعِيلَ أَنْ طَهِّرا بَيْتِيَ لِلطَّائِفِينَ وَالْعاكِفِينَ وَالرُّكَّعِ السُّجُودِ (125) وَإِذْ قالَ إِبْراهِيمُ رَبِّ اجْعَلْ هذا بَلَداً آمِناً وَارْزُقْ أَهْلَهُ مِنَ الثَّمَراتِ مَنْ آمَنَ مِنْهُمْ بِاللهِ وَالْيَوْمِ الْآخِرِ قالَ وَمَنْ كَفَرَ فَأُمَتِّعُهُ قَلِيلاً حول مقام إبراهيم في الحج ( وَعَهِدْنا ) أي ذكرنا ( إِلى إِبْراهِيمَ وَإِسْماعِيلَ ) عليهما‌السلام : الأب والابن ( أَنْ طَهِّرا بَيْتِيَ ) طهارة معنوية ، بعدم السماح لنصب الأصنام فيه وطهارة ظاهرية بالنظافة ( لِلطَّائِفِينَ ) أي الذين يطوفون حول البيت ( وَالْعاكِفِينَ ) الذين يعتكفون في المسجد الحرام ، وللاعتكاف مسائل وأحكام مذكورة في كتب الفقه (1) ( وَالرُّكَّعِ ) جمع راكع ( السُّجُودِ ) جمع ساجد ، أي المصلين."},{"text":"وَإِذْ يَرْفَعُ إِبْرَٰهِـۧمُ ٱلْقَوَاعِدَ مِنَ ٱلْبَيْتِ وَإِسْمَـٰعِيلُ رَبَّنَا تَقَبَّلْ مِنَّآ ۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ","tafsir":"اذكر يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( إِذْ قالَ إِبْراهِيمُ ) في دعائه لله تعالى ( رَبِّ اجْعَلْ هذا ) البلد وهو مكة ، التي بنى فيها البيت ( بَلَداً آمِناً ) عن الأخطار ، أو محكوما بحكم الأمن حكما شرعيا ، وإن كان السياق يؤيد الأول ( وَارْزُقْ أَهْلَهُ مِنَ الثَّمَراتِ مَنْ آمَنَ مِنْهُمْ بِاللهِ وَالْيَوْمِ الْآخِرِ ) فإن دعاء إبراهيم عليه‌السلام كان خاصا بهم ( قالَ ) الله سبحانه في جواب إبراهيم عليه‌السلام ما يدل على استجابة دعائه مع الزيادة ، وهي ( وَمَنْ كَفَرَ ) من أهل هذا البلد ، لا نقطع عنه الثمار بل ( فَأُمَتِّعُهُ ) أي أعطيه المتاع من الحياة والرزق والأمن ، وسائر الأمور ( قَلِيلاً ) فإن ( 1) راجع موسوعة الفقه ج 77 ص 151 ، في أحكام الاعتكاف. ثُمَّ أَضْطَرُّهُ إِلى عَذابِ النَّارِ وَبِئْسَ الْمَصِيرُ (126) وَإِذْ يَرْفَعُ إِبْراهِيمُ الْقَواعِدَ مِنَ الْبَيْتِ وَإِسْماعِيلُ رَبَّنا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ (127) رَبَّنا وَاجْعَلْنا مُسْلِمَيْنِ لَكَ وَمِنْ ذُرِّيَّتِنا أُمَّةً مُسْلِمَةً لَكَ وَأَرِنا مَناسِكَنا عمر الدنيا قصير ، وأمدها قليل ( ثُمَّ أَضْطَرُّهُ ) أي أدفعه إلى النار باضطرار منه ، فما من أحد يرضى بالنار ( إِلى عَذابِ النَّارِ وَبِئْسَ الْمَصِيرُ ) أي بئس المأوى والمرجع."},{"text":"رَبَّنَا وَٱجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةً مُّسْلِمَةً لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَآ ۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ","tafsir":"أذكر يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( إِذْ يَرْفَعُ إِبْراهِيمُ الْقَواعِدَ مِنَ الْبَيْتِ ) أي كان يبني أساس البيت الحرام ، ويرفعه من الأرض ، ويعاونه في ذلك ( وَإِسْماعِيلُ ) ابنه ، وهما يقولان في حال البناء ( رَبَّنا تَقَبَّلْ مِنَّا ) بناء البيت ( إِنَّكَ أَنْتَ السَّمِيعُ ) دعاءنا ( الْعَلِيمُ ) بما نعمله ونقصده."},{"text":"رَبَّنَا وَٱبْعَثْ فِيهِمْ رَسُولًا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَـٰتِكَ وَيُعَلِّمُهُمُ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَيُزَكِّيهِمْ ۚ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ","tafsir":"في جميع أمورنا ، والدعاء بالإسلام ، لا ينافي كونهما كذلك قبل الدعاء إذ الإسلام كسائر العقائد ، والأعمال بحاجة إلى الاستمرار ، مما لا يكون إلا بهداية الله وتوفيقه ، فكما أن الابتداء لا يكون إلا بعونه سبحانه ، كذلك الاستمرار ، كما في ( اهْدِنَا الصِّراطَ الْمُسْتَقِيمَ ) (1) ( وَ ) اجعل ( مِنْ ذُرِّيَّتِنا ) وأولادنا ( أُمَّةً مُسْلِمَةً لَكَ ) والإسلام هو تسليم الأمور إلى الله سبحانه في الاعتقاد والقول والعمل ( وَأَرِنا ) أي عرفنا ( مَناسِكَنا ) جمع منسك ، أي المواضع التي ( 1) الفاتحة : 6. وَتُبْ عَلَيْنا إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ (128) رَبَّنا وَابْعَثْ فِيهِمْ رَسُولاً مِنْهُمْ يَتْلُوا عَلَيْهِمْ آياتِكَ وَيُعَلِّمُهُمُ الْكِتابَ وَالْحِكْمَةَ وَيُزَكِّيهِمْ إِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ (129) تتعلق النسك بها ، والنسك العبادة ، يقال رجل ناسك ، أي عابد ، وقد استجاب الله دعاءهما ، حيث أراهما جبرائيل عليه‌السلام موضع الصلاة ، والوقوف ، وغيرها ( وَتُبْ عَلَيْنا ) أي أرجع إلينا بالمغفرة والرحمة ، فإن التوبة بمعنى الرجوع ، ولذا يقال الله « التواب » أي كثير الرجوع إلى عبيده ، ومن ذلك تعرف أنه لا دلالة للآية ، على أنهما عليهما‌السلام ، كانا قد أذنبا ( إِنَّكَ أَنْتَ التَّوَّابُ ) بعبادك ( الرَّحِيمُ ) بهم."},{"text":"وَمَن يَرْغَبُ عَن مِّلَّةِ إِبْرَٰهِـۧمَ إِلَّا مَن سَفِهَ نَفْسَهُۥ ۚ وَلَقَدِ ٱصْطَفَيْنَـٰهُ فِى ٱلدُّنْيَا ۖ وَإِنَّهُۥ فِى ٱلْـَٔاخِرَةِ لَمِنَ ٱلصَّـٰلِحِينَ","tafsir":"أي في الأمة المسلمة ـ التي طلبناها منك ـ ( رَسُولاً مِنْهُمْ ) من نفس الأمة ، لا من سائر الأمم ، حتى يكون لهم الشرف بكون الرسول منهم ( يَتْلُوا عَلَيْهِمْ آياتِكَ ) دلائلك ، وبراهينك ، وأحكامك ( وَيُعَلِّمُهُمُ الْكِتابَ ) إما المراد : القرآن ، أو المراد : « كتابك » على نحو الكلي ( وَالْحِكْمَةَ ) هي وضع كل شيء موضعه والمراد بتعلمهم إياها ، تعليمهم العلوم الكونية والتشريعية ، فإن الجاهل لا يتمكن ، من وضع الأشياء مواضعها لجهله بها ( وَيُزَكِّيهِمْ ) أي يطهرهم من الأدناس والقذارات الأخلاقية والأعمالية ( إِنَّكَ أَنْتَ الْعَزِيزُ ) حقيقة ، فإن العزة لا تكون إلا بقلة الوجود ، وكثرة الاحتياج ، والله واحد لا شريك له ، وجميع الاحتياجات إليه وتخصيص العزة هنا بالذكر ، للتلميح إلى كون الاحتياج إليه ( الْحَكِيمُ ) فأفعالك صادرة عن حكمة ، وما طلباه إنما كان عين الحكمة. وَمَنْ يَرْغَبُ عَنْ مِلَّةِ إِبْراهِيمَ إِلاَّ مَنْ سَفِهَ نَفْسَهُ وَلَقَدِ اصْطَفَيْناهُ فِي الدُّنْيا وَإِنَّهُ فِي الْآخِرَةِ لَمِنَ الصَّالِحِينَ (130) إِذْ قالَ لَهُ رَبُّهُ أَسْلِمْ قالَ أَسْلَمْتُ لِرَبِّ الْعالَمِينَ (131) وَوَصَّى بِها [131] هذه هي طريقة إبراهيم عليه‌السلام ( وَمَنْ يَرْغَبُ عَنْ مِلَّةِ إِبْراهِيمَ ) أي من يعرض عن هذه الطريقة في التوحيد والتسليم وسائر ما ذكر مما يدل على أنها من أفضل الطرق ( إِلَّا مَنْ سَفِهَ نَفْسَهُ ) أي لا يترك هذه الملة ، إلا من ضرب نفسه بالسفاهة والحمق ، وهل هناك طريقة أفضل من هذه الطريقة ؟ والاستفهام في قوله « من يرغب » استنكاري ( وَلَقَدِ اصْطَفَيْناهُ ) جملة حالية ، أي إنا بسبب هذه الطريقة المستقيمة ، التي كانت لإبراهيم عليه‌السلام اخترناه نبيا ( فِي الدُّنْيا وَإِنَّهُ فِي الْآخِرَةِ لَمِنَ الصَّالِحِينَ ) الفائزين بالدرجات الرفيعة."},{"text":"إِذْ قَالَ لَهُۥ رَبُّهُۥٓ أَسْلِمْ ۖ قَالَ أَسْلَمْتُ لِرَبِّ ٱلْعَـٰلَمِينَ","tafsir":"(رَبَّنا وَابْعَثْ فِيهِمْ) أي في الأمة المسلمة ـ التي طلبناها منك ـ (رَسُولاً مِنْهُمْ) من نفس الأمة، لا من سائر الأمم، حتى يكون لهم الشرف بكون الرسول منهم (يَتْلُوا عَلَيْهِمْ آياتِكَ) دلائلك، وبراهينك، وأحكامك (وَيُعَلِّمُهُمُ الْكِتابَ) إما المراد: القرآن، أو المراد: «كتابك» على نحو الكلي (وَالْحِكْمَةَ) هي وضع كل شيء موضعه والمراد بتعلمهم إياها، تعليمهم العلوم الكونية والتشريعية، فإن الجاهل لا يتمكن، من وضع الأشياء مواضعها لجهله بها (وَيُزَكِّيهِمْ) أي يطهرهم من الأدناس والقذارات الأخلاقية والأعمالية (إِنَّكَ أَنْتَ الْعَزِيزُ) حقيقة، فإن العزة لا تكون إلا بقلة الوجود، وكثرة الاحتياج، والله واحد لا شريك له، وجميع الاحتياجات إليه وتخصيص العزة هنا بالذكر، للتلميح إلى كون الاحتياج إليه (الْحَكِيمُ) فأفعالك صادرة عن حكمة، وما طلباه إنما كان عين الحكمة."},{"text":"وَوَصَّىٰ بِهَآ إِبْرَٰهِـۧمُ بَنِيهِ وَيَعْقُوبُ يَـٰبَنِىَّ إِنَّ ٱللَّهَ ٱصْطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ","tafsir":"هذا متعلق بقوله « اصطفيناه » أي اخترناه لما قلنا له ( أَسْلِمْ ) في جميع أمورك لله ( قالَ ) إبراهيم عليه‌السلام ( أَسْلَمْتُ لِرَبِّ الْعالَمِينَ ) وحده لا شريك له ، ومعنى أسلم استقم على الإسلام ، واثبت على التوحيد ، كقوله تعالى ( فَاعْلَمْ أَنَّهُ لا إِلهَ إِلَّا اللهُ وَاسْتَغْفِرْ ) (1) وكما يقول أحدنا لمن كان جالسا في مكان : أجلس هنا حتى الساعة العاشرة ـ مثلا ـ."},{"text":"أَمْ كُنتُمْ شُهَدَآءَ إِذْ حَضَرَ يَعْقُوبَ ٱلْمَوْتُ إِذْ قَالَ لِبَنِيهِ مَا تَعْبُدُونَ مِنۢ بَعْدِى قَالُوا۟ نَعْبُدُ إِلَـٰهَكَ وَإِلَـٰهَ ءَابَآئِكَ إِبْرَٰهِـۧمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ إِلَـٰهًا وَٰحِدًا وَنَحْنُ لَهُۥ مُسْلِمُونَ","tafsir":"أي بالملة والطريقة التي كانت لإبراهيم عليه‌السلام ( 1) محمد : 20. إِبْراهِيمُ بَنِيهِ وَيَعْقُوبُ يا بَنِيَّ إِنَّ اللهَ اصْطَفى لَكُمُ الدِّينَ فَلا تَمُوتُنَّ إِلاَّ وَأَنْتُمْ مُسْلِمُونَ (132) أَمْ كُنْتُمْ شُهَداءَ إِذْ حَضَرَ يَعْقُوبَ الْمَوْتُ إِذْ قالَ لِبَنِيهِ ما تَعْبُدُونَ مِنْ بَعْدِي ( إِبْراهِيمُ بَنِيهِ ) أولاده ، وخصهم بالذكر ، مع أن دعوة إبراهيم عليه‌السلام كانت عامة ، إشارة إلى لزوم دعوة الأهل بصورة خاصة إلى الحق ، كما قال سبحانه ( قُوا أَنْفُسَكُمْ وَأَهْلِيكُمْ ناراً ) (1) ( وَ ) وصى بها ( يَعْقُوبُ ) حفيد إبراهيم من إسحاق ، بنيه أيضا وخص يعقوب لأنه جد اليهود ، وكانت الوصية ( يا بَنِيَ ) أي يا أبنائي ، فهو جمع ابن ، وأصله بنيني ( إِنَّ اللهَ اصْطَفى ) أي اختار ( لَكُمُ الدِّينَ ) حتى تكونوا متدينين ، ومعنى اختار الله الدين لهم ، أنه سبحانه أعطاهم الدين ، وأراد ذلك منهم مقابل بعض الأمم الوحشية الذين تركوا وشأنهم ، فلم تبلغهم دعوة الأنبياء ( فَلا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ ) أي لا تتركوا الإسلام ، فيصادفكم الموت على تركه ، وإنما خص الموت ، لأنه لو كان غير مسلم قبل ذلك ، ثم أسلم ومات مسلما لم يكن عليه بأس."},{"text":"تِلْكَ أُمَّةٌ قَدْ خَلَتْ ۖ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ ۖ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ","tafsir":"أيها المدعون إن الأنبياء كانوا يهودا أو نصارى ، فإن اليهود كانوا يقولون أن يعقوب النبي عليه‌السلام أوصى بنيه باليهودية ، فأنكر الله تعالى عليهم ذلك بأنكم لم تكونوا حضورا ( إِذْ حَضَرَ يَعْقُوبَ الْمَوْتُ ) واقترب من الوفاة ( إِذْ قالَ لِبَنِيهِ ما تَعْبُدُونَ مِنْ بَعْدِي ) على طريقة الاستفهام التقريري ( 1) التحريم : 7. قالُوا نَعْبُدُ إِلهَكَ وَإِلهَ آبائِكَ إِبْراهِيمَ وَإِسْماعِيلَ وَإِسْحاقَ إِلهاً واحِداً وَنَحْنُ لَهُ مُسْلِمُونَ (133) تِلْكَ أُمَّةٌ قَدْ خَلَتْ لَها ما كَسَبَتْ وَلَكُمْ ما كَسَبْتُمْ وَلا تُسْئَلُونَ عَمَّا كانُوا يَعْمَلُونَ (134) وَقالُوا كُونُوا هُوداً أَوْ نَصارى تَهْتَدُوا قُلْ ( قالُوا نَعْبُدُ إِلهَكَ وَإِلهَ آبائِكَ إِبْراهِيمَ وَإِسْماعِيلَ وَإِسْحاقَ ) إبراهيم جد يعقوب وإسماعيل عمه وإسحاق أبوه ، وقدم إسماعيل لأنه كان الأكبر سنا ، والأعلى منزلة ، وسمى العم أبا تغليبا ، ولأن العرب تسمي العم أبا والخالة أما ( إِلهاً واحِداً ) بغير شريك ( وَنَحْنُ لَهُ مُسْلِمُونَ ) فكان دينهم الإسلام ، والإسلام هو دين جميع الأنبياء عليهم‌السلام ، لأن معناه التسليم لله في أوامره ونواهيه ونفي الله سبحانه كون دين الأنبياء اليهودية أو النصرانية ، يراد به نفيها بالمعنى المتداول عند أهل الكتاب ، وإلا فلا يهم الاسم ، كما لا يخفى. [135] ثم بين الله حقيقة هي أن الأمة الماضية ليست تهمكم ، أيها المعاصرون للرسول صلى‌الله‌عليه‌وآله‌وسلم وإنما المهم أعمالكم ، فكيف كانت تلك الأمم ، فإنها قد ذهبت وفنت ( تِلْكَ ) أي إبراهيم وأولاده عليهم‌السلام ( أُمَّةٌ قَدْ خَلَتْ ) أي ذهبت ومضت ( لَها ما كَسَبَتْ ) فإن أعمالها ترتبط بها لا بكم ( وَلَكُمْ ما كَسَبْتُمْ ) فإن أعمالكم ترتبط بكم لا بهم ( وَلا تُسْئَلُونَ ) أنتم ( عَمَّا كانُوا يَعْمَلُونَ ) فأصلحوا أعمالكم."},{"text":"وَقَالُوا۟ كُونُوا۟ هُودًا أَوْ نَصَـٰرَىٰ تَهْتَدُوا۟ ۗ قُلْ بَلْ مِلَّةَ إِبْرَٰهِـۧمَ حَنِيفًا ۖ وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ","tafsir":"(أَمْ كُنْتُمْ شُهَداءَ) أيها المدعون إن الأنبياء كانوا يهودا أو نصارى، فإن اليهود كانوا يقولون أن يعقوب النبي عليه السلام أوصى بنيه باليهودية، فأنكر الله تعالى عليهم ذلك بأنكم لم تكونوا حضورا (إِذْ حَضَرَ يَعْقُوبَ الْمَوْتُ) واقترب من الوفاة (إِذْ قالَ لِبَنِيهِ ما تَعْبُدُونَ مِنْ بَعْدِي) على طريقة الاستفهام التقريري (قالُوا نَعْبُدُ إِلهَكَ وَإِلهَ آبائِكَ إِبْراهِيمَ وَإِسْماعِيلَ وَإِسْحاقَ) إبراهيم جد يعقوب وإسماعيل عمه وإسحاق أبوه، وقدم إسماعيل لأنه كان الأكبر سنا، والأعلى منزلة، وسمى العم أبا تغليبا، ولأن العرب تسمي العم أبا والخالة أما (إِلهاً واحِداً) بغير شريك (وَنَحْنُ لَهُ مُسْلِمُونَ) فكان دينهم الإسلام، والإسلام هو دين جميع الأنبياء عليهم السلام، لأن معناه التسليم لله في أوامره ونواهيه ونفي الله سبحانه كون دين الأنبياء اليهودية أو النصرانية، يراد به نفيها بالمعنى المتداول عند أهل الكتاب، وإلا فلا يهم الاسم، كما لا يخفى."},{"text":"قُولُوٓا۟ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبْرَٰهِـۧمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِىَ ٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ","tafsir":"أي قالت اليهود كونوا يهودا وقالت النصارى كونوا نصارى ( تَهْتَدُوا ) للحق وترشدوا ( قُلْ ) يا رسول بَلْ مِلَّةَ إِبْراهِيمَ حَنِيفاً وَما كانَ مِنَ الْمُشْرِكِينَ (135) قُولُوا آمَنَّا بِاللهِ وَما أُنْزِلَ إِلَيْنا وَما أُنْزِلَ إِلى إِبْراهِيمَ وَإِسْماعِيلَ وَإِسْحاقَ وَيَعْقُوبَ وَالْأَسْباطِ وَما أُوتِيَ مُوسى وَعِيسى وَما أُوتِيَ النَّبِيُّونَ مِنْ رَبِّهِمْ لا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْهُمْ وَنَحْنُ لَهُ مُسْلِمُونَ الله صلى‌الله‌عليه‌وآله‌وسلم ( بَلْ ) نتبع ( مِلَّةَ ) أي دين ( إِبْراهِيمَ ) الصافي من شوائب اليهودية والنصرانية ، وإنما هي الإسلام المصفى ، وإن كان فرق بين الإسلام وبين دين إبراهيم عليه‌السلام في بعض الخصوصيات التشريعية ، فالمراد نفي النصرانية واليهودية ( حَنِيفاً ) أي مستقيما عن الاعوجاج ( وَما كانَ ) إبراهيم ( مِنَ الْمُشْرِكِينَ ) كما أنتم أيها اليهود والنصارى مشركون ، إذ تقولون عزير ابن الله ، أو المسيح ابن الله ، وعلى هذا فالمراد بإتباع ملة إبراهيم عليه‌السلام إتباعها في التوحيد."},{"text":"فَإِنْ ءَامَنُوا۟ بِمِثْلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهْتَدَوا۟ ۖ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا هُمْ فِى شِقَاقٍ ۖ فَسَيَكْفِيكَهُمُ ٱللَّهُ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ","tafsir":"أيها المسلمون ، ما يجب عليكم أن تعتقدوا به ، وما هي خلاصة الأديان السابقة واللاحقة ، التي تعين زيف العقائد النصرانية واليهودية وغيرهما ( آمَنَّا بِاللهِ وَ ) آمنا ب ( ما أُنْزِلَ إِلَيْنا ) من القرآن الحكيم ( وَما أُنْزِلَ إِلى إِبْراهِيمَ وَإِسْماعِيلَ وَإِسْحاقَ وَيَعْقُوبَ وَالْأَسْباطِ ) أحفاد يعقوب فإن كثيرا منهم كانوا أنبياء عليهم‌السلام نزلت عليهم الصحف ( وَ ) آمنا ب ( ما أُوتِيَ مُوسى وَعِيسى وَ ) آمنا ب ( ما أُوتِيَ النَّبِيُّونَ ) قاطبة ( مِنْ رَبِّهِمْ لا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْهُمْ ) أي من الأنبياء عليهم‌السلام ، فإنا نعترف بالجميع ( وَنَحْنُ لَهُ ) أي لله سبحانه ( مُسْلِمُونَ ) فإن دين الأنبياء ، عليهم‌السلام كلهم يتلخص في أصول وفروع فَإِنْ آمَنُوا بِمِثْلِ ما آمَنْتُمْ بِهِ فَقَدِ اهْتَدَوْا وَإِنْ تَوَلَّوْا فَإِنَّما هُمْ فِي شِقاقٍ فَسَيَكْفِيكَهُمُ اللهُ وَهُوَ السَّمِيعُ الْعَلِيمُ (137) صِبْغَةَ اللهِ وَمَنْ أَحْسَنُ مِنَ اللهِ صِبْغَةً وَنَحْنُ لَهُ عابِدُونَ (138) وأخلاق فالأصول : التوحيد ، والعدل ، والنبوة ، والإمامة ، والمعاد ، فإن كل نبي كان يصدّق من سبقه ويبشّر بمن يلحقه ، كما إن الإمامة بمعنى الوصاية ، فإن كل نبي كان له أوصياء ، والفروع : الصلاة والصوم والزكاة وما أشبه من العبادات ، وأحكام المعاملات ـ بالمعنى الأعم ـ وكل الأديان كانت مشتركة فيها مع تفاوت يسير حسب اقتضاء الزمان والأمة ، فمثلا كان صوم الصمت في بعض الأمم وليس في الإسلام وهكذا ، والأخلاق : الصدق والأمانة ، والوفاء ، والحياء ، وما أشبه وكلها فطريات نفسيه كانت الأنبياء عليهم‌السلام تأمر بها وتنهى عن أضدادها."},{"text":"صِبْغَةَ ٱللَّهِ ۖ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ صِبْغَةً ۖ وَنَحْنُ لَهُۥ عَـٰبِدُونَ","tafsir":"أي آمن غير المسلمين من سائر الأديان والفرق ( بِمِثْلِ ما آمَنْتُمْ بِهِ ) أي كما تؤمنون أنتم أيها المسلمون ( فَقَدِ اهْتَدَوْا ) إلى الحق ( وَإِنْ تَوَلَّوْا ) عن مثل هذا الإيمان ، ولزموا طريقتهم المنحرفة ( فَإِنَّما هُمْ فِي شِقاقٍ ) أي في خلاف فهم في شق وأنتم في شق ( فَسَيَكْفِيكَهُمُ اللهُ ) فإن الله يكفيك يا رسول الله وينصرك عليهم ( وَهُوَ السَّمِيعُ ) كلامهم ( الْعَلِيمُ ) بأعمالكم ونواياكم. [139] اتبعوا ( صِبْغَةَ اللهِ ) واصبغوا أنفسكم بها ، وهي الإسلام ، فإن كل طريقة يتبعها الإنسان لون له ، لكنه لون غير محسوس ، تشبيها بالألوان المحسوسة ( وَمَنْ أَحْسَنُ مِنَ اللهِ صِبْغَةً ) وهذا استفهام إنكاري ، أي لا أحد أحسن من الله صبغة ودينا ( وَنَحْنُ ) المسلمون ( لَهُ عابِدُونَ ) قُلْ أَ تُحَاجُّونَنا فِي اللهِ وَهُوَ رَبُّنا وَرَبُّكُمْ وَلَنا أَعْمالُنا وَلَكُمْ أَعْمالُكُمْ وَنَحْنُ لَهُ مُخْلِصُونَ (139) أَمْ تَقُولُونَ إِنَّ إِبْراهِيمَ وَإِسْماعِيلَ وَإِسْحاقَ وَيَعْقُوبَ وَالْأَسْباطَ كانُوا هُوداً أَوْ نَصارى لا لغيره من الشركاء الذين أنتم تعبدونها مع الله ، أو من دون الله ، وربما يقال إن وجه التسمية ب ـ « الصبغة » أن النصارى كانوا يصبغون أولادهم بماء أصفر يعمدونهم فيه ، والآية من المشابهة كقوله سبحانه ( تَعْلَمُ ما فِي نَفْسِي وَلا أَعْلَمُ ما فِي نَفْسِكَ ) (1) ."},{"text":"قُلْ أَتُحَآجُّونَنَا فِى ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمْ وَلَنَآ أَعْمَـٰلُنَا وَلَكُمْ أَعْمَـٰلُكُمْ وَنَحْنُ لَهُۥ مُخْلِصُونَ","tafsir":"(فَإِنْ آمَنُوا) أي آمن غير المسلمين من سائر الأديان والفرق (بِمِثْلِ ما آمَنْتُمْ بِهِ) أي كما تؤمنون أنتم أيها المسلمون (فَقَدِ اهْتَدَوْا) إلى الحق (وَإِنْ تَوَلَّوْا) عن مثل هذا الإيمان، ولزموا طريقتهم المنحرفة (فَإِنَّما هُمْ فِي شِقاقٍ) أي في خلاف فهم في شق وأنتم في شق (فَسَيَكْفِيكَهُمُ اللهُ) فإن الله يكفيك يا رسول الله وينصرك عليهم (وَهُوَ السَّمِيعُ) كلامهم (الْعَلِيمُ) بأعمالكم ونواياكم."},{"text":"أَمْ تَقُولُونَ إِنَّ إِبْرَٰهِـۧمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطَ كَانُوا۟ هُودًا أَوْ نَصَـٰرَىٰ ۗ قُلْ ءَأَنتُمْ أَعْلَمُ أَمِ ٱللَّهُ ۗ وَمَنْ أَظْلَمُ مِمَّن كَتَمَ شَهَـٰدَةً عِندَهُۥ مِنَ ٱللَّهِ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ","tafsir":"يا رسول الله لهؤلاء اليهود والنصارى وغيرهم ( أَ تُحَاجُّونَنا ) أي تباحثون معنا ( فِي ) دين ( اللهِ ) وإنه لم أنسخ أديانكم ، ولم أختر من العرب رسولا ، ولم أفعل كذا وكذا ؟ ( وَهُوَ رَبُّنا وَرَبُّكُمْ ) أي أن الله ليس ربا لكم فقط حتى يكون معكم وحدكم إلى الأبد ( وَلَنا أَعْمالُنا وَلَكُمْ أَعْمالُكُمْ ) فليس عملنا غير منظور إليه عند الله ، وعملكم منظور إليه ، كما كانوا يزعمون قائلين نحن شعب الله المختار ، ونحن أبناء الله وأودائه ( وَنَحْنُ لَهُ مُخْلِصُونَ ) إذ لا نشرك به أحدا بخلافكم حيث جعلتم له شريكا."},{"text":"تِلْكَ أُمَّةٌ قَدْ خَلَتْ ۖ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ ۖ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ","tafsir":"تباحثون معنا في أمر الأنبياء عليهم‌السلام و ( تَقُولُونَ إِنَّ إِبْراهِيمَ وَإِسْماعِيلَ وَإِسْحاقَ وَيَعْقُوبَ وَالْأَسْباطَ ) أحفاد يعقوب الذين كانوا أنبياء عليهم‌السلام ( كانُوا هُوداً ) أي يهودا ( أَوْ نَصارى ) وهذا اشتباه منهم إذ اليهودية والنصرانية ، تولدتا بعد إبراهيم عليه‌السلام ، فكيف يكون إبراهيم ( 1) المائدة : 117. قُلْ أَ أَنْتُمْ أَعْلَمُ أَمِ اللهُ وَمَنْ أَظْلَمُ مِمَّنْ كَتَمَ شَهادَةً عِنْدَهُ مِنَ اللهِ وَمَا اللهُ بِغافِلٍ عَمَّا تَعْمَلُونَ (140) تِلْكَ أُمَّةٌ قَدْ خَلَتْ لَها ما كَسَبَتْ وَلَكُمْ ما كَسَبْتُمْ وَلا تُسْئَلُونَ عَمَّا كانُوا يَعْمَلُونَ (141) أحدهما ، كما قال سبحانه ( وَما أُنْزِلَتِ التَّوْراةُ وَالْإِنْجِيلُ إِلَّا مِنْ بَعْدِهِ ) (1) ( قُلْ ) يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم لهؤلاء المدعين بيهودية هؤلاء الأنبياء ، أو نصرانيتهم ( أَ أَنْتُمْ أَعْلَمُ أَمِ اللهُ ) فالله سبحانه يقول لم يكونوا يهودا ولا نصارى ، وأنتم تقولون كانوا ( وَمَنْ أَظْلَمُ مِمَّنْ كَتَمَ شَهادَةً عِنْدَهُ مِنَ اللهِ ) أي لا أحد أظلم ممن يكتم الشهادة التي عنده من الله سبحانه ، فإن اليهود كانوا يكتمون ما أنزل إليهم من البينات والهدى حول الأنبياء السابقين وحول نبي الإسلام ( وَمَا اللهُ ) أي ليس الله ( بِغافِلٍ عَمَّا تَعْمَلُونَ ) فإنه يعلم أعمالكم التي منها كتمانكم للشهادة ، ثم يجازيكم عليها."},{"text":"۞ سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمْ عَن قِبْلَتِهِمُ ٱلَّتِى كَانُوا۟ عَلَيْهَا ۚ قُل لِّلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ ۚ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ","tafsir":"الأنبياء عليهم‌السلام وما كانوا يعملون ويتدينون لا يرتبطون بكم أيها المعاصرون للرسول ، فإنها ( أُمَّةٌ قَدْ خَلَتْ ) ومضت ( لَها ما كَسَبَتْ ) من الأعمال والأفعال ( وَلَكُمْ ما كَسَبْتُمْ ) من الخير والشر ( وَلا تُسْئَلُونَ ) أنتم ( عَمَّا كانُوا يَعْمَلُونَ ) فلم هذه المباحثة والمحاجة والمجادلة. ( 1) آل عمران : 66. تقريب القران الى الأذهان من آية ( 143) إلى ( 253) بسم الله الرّحمن الرّحيم الحمد لله رب العالمين ، والصلاة والسلام على أشرف الأنبياء والمرسلين محمد المصطفى وعترته الطاهرين. سَيَقُولُ السُّفَهاءُ مِنَ النَّاسِ ما وَلاَّهُمْ عَنْ قِبْلَتِهِمُ الَّتِي كانُوا عَلَيْها قُلْ لِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ يَهْدِي مَنْ يَشاءُ إِلى صِراطٍ مُسْتَقِيمٍ (142) وَكَذلِكَ جَعَلْناكُمْ أُمَّةً وَسَطاً لِتَكُونُوا"},{"text":"وَكَذَٰلِكَ جَعَلْنَـٰكُمْ أُمَّةً وَسَطًا لِّتَكُونُوا۟ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيْكُمْ شَهِيدًا ۗ وَمَا جَعَلْنَا ٱلْقِبْلَةَ ٱلَّتِى كُنتَ عَلَيْهَآ إِلَّا لِنَعْلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيْهِ ۚ وَإِن كَانَتْ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُ ۗ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَـٰنَكُمْ ۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٌ رَّحِيمٌ","tafsir":"جمع سفيه ، وهو الغر والجاهل ، وناقص العقل ( مِنَ النَّاسِ ما وَلَّاهُمْ ) أي أيّ شيء صرف المسلمون ( عَنْ قِبْلَتِهِمُ ) السابقة ( الَّتِي كانُوا عَلَيْها ) يتوجهون في صلاتهم ، وهي بيت المقدس ، فإن الرسول صلى‌الله‌عليه‌وآله‌وسلم والمسلمون كانوا يصلون إلى بيت المقدس ، وهو قبلة اليهود ، ثم في المدينة حولت القبلة إلى الكعبة ، وكان السبب الظاهر لذلك أن اليهود عابوا النبي بأنه يصلي إلى قبلتهم ، فحوله الله عنها إلى الكعبة ، فأخذ اليهود يهرجون حول تحويل القبلة ( قُلْ ) يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( لِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ ) فمتى شاء وجه عبيده إلى حيث يشاء ، وليست القبلة احتكارا حتى لا يمكن تحويلها ( يَهْدِي مَنْ يَشاءُ إِلى صِراطٍ مُسْتَقِيمٍ ) وكما كان الصراط المستقيم قبلا بيت المقدس حال التوجه ، كذلك صار الصراط المستقيم ، فعلا الكعبة."},{"text":"قَدْ نَرَىٰ تَقَلُّبَ وَجْهِكَ فِى ٱلسَّمَآءِ ۖ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَىٰهَا ۚ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۚ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ ۗ وَإِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ لَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا يَعْمَلُونَ","tafsir":"أي كما أن لله المشرق والمغرب ، وأنه لا مناقشة في ذلك ( جَعَلْناكُمْ ) أيها المسلمون ، وفي التأويل ، إن المراد بالخطاب الأئمة عليهم‌السلام ( أُمَّةً وَسَطاً ) متوسطا ، والإطلاق وإن كان يفيد الوسطية في كل شيء في العقيدة ، فلا جمود ولا إلجاء ، وفي المكان فهم متوسطون بين شرق الأرض وغربها ، وفي التشريع ، فليس ناقصا ولا مغاليا ، وهكذا إلا أن ظاهر قوله سبحانه بعد ذلك ( لِتَكُونُوا شُهَداءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيداً وَما جَعَلْنَا الْقِبْلَةَ الَّتِي كُنْتَ عَلَيْها إِلاَّ لِنَعْلَمَ مَنْ يَتَّبِعُ الرَّسُولَ مِمَّنْ يَنْقَلِبُ عَلى عَقِبَيْهِ شُهَداءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيداً ) يفيد أن المراد بالتوسط الوسيطة بين الرسول وبين سائر الناس ، فالأمة تأخذ من الرسول ـ ويشهد الرسول عليهم بأنهم أخذوا منه ، حتى لا يقولوا ما عرفنا ـ وسائر الناس يأخذون من الأمة ـ وتشهد الأمة عليهم بأنهم أخذوا منها ، حتى لا يقول الناس لم نعرف ـ وهذا هو الظاهر من « لام » العلة في قوله « لتكونوا .. ويكون » ولعل ارتباط هذه الآية بما سبقها من حكم القبلة ، وما لحقها بيان أن المسلمين لهم مكان القيادة ، لأنهم الآخذون عن الرسول المبلغون للناس فالذي ينبغي أن تكون لهم سمة خاصة في شرائعهم ، حتى لا يرمون بالذيلية ، والإتباع لقبلة الآخرين ، ثم رجع السياق إلى حكم القبلة فقال سبحانه ( وَما جَعَلْنَا الْقِبْلَةَ الَّتِي كُنْتَ عَلَيْها ) وهي بيت المقدس الذي كان النبي صلى‌الله‌عليه‌وآله‌وسلم يتوجه نحوه في الصلاة ، طيلة كونه في مكة المكرمة ، ومدة بعد الهجرة ( إِلَّا لِنَعْلَمَ مَنْ يَتَّبِعُ الرَّسُولَ مِمَّنْ يَنْقَلِبُ عَلى عَقِبَيْهِ ) معنى « لنعلم » أن يتحقق علمنا في الخارج ، بأن يظهر المتبع من المخالف ، فإنه قد يقال لنعلم ، ويراد به حصول العلم للمتكلم ، وقد يقال لنعلم ، والمراد به وقوع المعلوم في الخارج ، وفي بعض التفاسير أن قوما ارتدوا على أدبارهم لما حولت القبلة (1) ، فظهر ( 1) مجمع البيان : ص 418. وَإِنْ كانَتْ لَكَبِيرَةً إِلاَّ عَلَى الَّذِينَ هَدَى اللهُ وَما كانَ اللهُ لِيُضِيعَ إِيمانَكُمْ إِنَّ اللهَ بِالنَّاسِ لَرَؤُفٌ رَحِيمٌ (143) قَدْ نَرى إنهم لم يكونوا يتبعون الرسول صلى‌الله‌عليه‌وآله‌وسلم حقيقة وإنما حسب الأهواء ، والعقب مؤخر القدم ، والمعنى التشبيه لمن يرتد كافرا ، بمن يرجع القهقرى ( وَإِنْ كانَتْ ) مفارقة القبلة الأولى إلى قبلة أخرى ( لَكَبِيرَةً ) إذ هو خرق لاعتياد قديم متركز ( إِلَّا عَلَى الَّذِينَ هَدَى اللهُ ) إياهم بأن قوى قلوبهم بالإيمان ( وَما كانَ اللهُ لِيُضِيعَ إِيمانَكُمْ ) أيها المسلمون الراسخون الذين اتبعتم النبي صلى‌الله‌عليه‌وآله‌وسلم ، وهذا تقدير لهم في ثباتهم ، ووعد لهم في الجزاء على إيمانهم الكامل ، ويحتمل أن يكون جوابا عن سؤال وقع من بعضهم ، وهو إنه كيف تكون حال صلواتهم السابقة التي صلوها إلى بيت المقدس ، وإن كان الظاهر من كلمة « إيمان » المعنى الأول ( إِنَّ اللهَ بِالنَّاسِ لَرَؤُفٌ رَحِيمٌ ) فلا يضيع أتعابهم وأعمالهم. [145] وبعد ما بين الحكم ، وأن القبلة تحولت ، بيّن الله سبحانه قصة التحويل ، فإنها كالعلة للحكم المتقدم ، والعلة دائما تأتي متأخرة في الكلام ، وإن كانت سابقة في التحقيق ، كما يقال إنه إنسان طيب لأن تربيته حسنة ( قَدْ نَرى ) « قد » هنا للتحقيق نحو ( قَدْ يَعْلَمُ اللهُ ) (1) وإن كان الغالب في « قد » الداخلة على المضارع ، أن تكون بمعنى التقليل ، ولعل سر دخولها ، إشراب الفعل معنى التقليل ، حيث لا يريد المتكلم ( 1) النور : 64. تَقَلُّبَ وَجْهِكَ فِي السَّماءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضاها فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرامِ وَحَيْثُ ما كُنْتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ وَإِنَّ الَّذِينَ أُوتُوا الْكِتابَ إظهار العلم بالبت ، مثله ( وَإِنَّا أَوْ إِيَّاكُمْ لَعَلى هُدىً ) (1) ( تَقَلُّبَ وَجْهِكَ ) يا رسول الله ( فِي السَّماءِ ) أي في ناحية السماء ، فإن الرسول صلى‌الله‌عليه‌وآله‌وسلم كان يقلب وجهه في أطراف السماء ، فينتظر الوحي حول القبلة ، وإن اليهود عيروه صلى‌الله‌عليه‌وآله‌وسلم قائلين له أنك تابع لقبلتنا فلما كان في بعض الليل خرج صلى‌الله‌عليه‌وآله‌وسلم ، يقلب وجهه في آفاق السماء ، فلما أصبح صلى الغداة ، فلما صلى من الظهر ركعتين ، جاء جبرائيل عليه‌السلام بهذه الآية ، ثم أخذ بيده فحول وجهه إلى الكعبة ، وحول من خلفه وجوههم ، حتى قام الرجال مقام النساء ، والنساء مقام الرجال ( فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضاها ) إذ الرسول كان يحب الكعبة التي هي بناء جده إبراهيم عليه‌السلام وعندها موطنه ( فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرامِ ) الشطر الجزء ، أي حول وجهك نحو جزء من المسجد الحرام ، والمسجد لكونه محيطا بالكعبة يكون المتوجه إليه متوجها إليها إذا كان من بعيد ( وَحَيْثُ ما كُنْتُمْ ) أيها المسلمون ( فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ ) وذكر « الوجه » في المقامين ، لأنه الشيء الذي يتوجه به في جسد الإنسان ( وَإِنَّ الَّذِينَ أُوتُوا الْكِتابَ ) من اليهود والنصارى الذين يستشكلون عليكم قائلين إن كانت القبلة ( 1) سبأ : 25. لَيَعْلَمُونَ أَنَّهُ الْحَقُّ مِنْ رَبِّهِمْ وَمَا اللهُ بِغافِلٍ عَمَّا يَعْمَلُونَ (144) وَلَئِنْ أَتَيْتَ الَّذِينَ أُوتُوا الْكِتابَ بِكُلِّ آيَةٍ ما تَبِعُوا قِبْلَتَكَ وَما أَنْتَ بِتابِعٍ قِبْلَتَهُمْ وَما بَعْضُهُمْ بِتابِعٍ قِبْلَةَ بَعْضٍ وَلَئِنِ اتَّبَعْتَ أَهْواءَهُمْ مِنْ بَعْدِ ما جاءَكَ مِنَ الْعِلْمِ السابقة حقا ، فهذه باطلة ، وإن كانت هذه حقا ، فتوجهكم في السابق إلى بيت المقدس باطل ( لَيَعْلَمُونَ أَنَّهُ الْحَقُّ مِنْ رَبِّهِمْ ) أي تحويل القبلة أو هذه القبلة حق من قبل الله ، فإن الله سبحانه يعبده عباده كيف يشاء ، فمن الجائز أن يعبد الأمة بتشريع إلى مدة ، ثم يعبدهم بتشريع آخر ( وَمَا اللهُ بِغافِلٍ عَمَّا يَعْمَلُونَ ) أي يعمل أهل الكتاب من الإرجاف وبث الأباطيل حول تحويل القبلة وسائر الأمور المرتبطة بالنبي صلى‌الله‌عليه‌وآله‌وسلم ."},{"text":"وَلَئِنْ أَتَيْتَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ بِكُلِّ ءَايَةٍ مَّا تَبِعُوا۟ قِبْلَتَكَ ۚ وَمَآ أَنتَ بِتَابِعٍ قِبْلَتَهُمْ ۚ وَمَا بَعْضُهُم بِتَابِعٍ قِبْلَةَ بَعْضٍ ۚ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم مِّنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ ۙ إِنَّكَ إِذًا لَّمِنَ ٱلظَّـٰلِمِينَ","tafsir":""},{"text":"ٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمْ ۖ وَإِنَّ فَرِيقًا مِّنْهُمْ لَيَكْتُمُونَ ٱلْحَقَّ وَهُمْ يَعْلَمُونَ","tafsir":"يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( الَّذِينَ أُوتُوا الْكِتابَ ) من اليهود والنصارى ( بِكُلِّ آيَةٍ ) من الآيات الدالة على أن قبلتك حق ( ما تَبِعُوا قِبْلَتَكَ ) لأنهم معاندون ، والمعاند لا ينفع معه الدليل ( وَما أَنْتَ ) يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( بِتابِعٍ قِبْلَتَهُمْ ) بعد ما تعلم أن قبلتهم منسوخة ، كقوله تعالى ( لا أَعْبُدُ ما تَعْبُدُونَ* وَلا أَنْتُمْ عابِدُونَ ما أَعْبُدُ ) (1) ( وَما بَعْضُهُمْ بِتابِعٍ قِبْلَةَ بَعْضٍ ) اليهود لا يتبعون قبلة النصارى ، والنصارى لا يتبعون قبلة اليهود ( وَلَئِنِ اتَّبَعْتَ ) يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( أَهْواءَهُمْ ) في باب القبلة وسائر التشريعات ( مِنْ بَعْدِ ما جاءَكَ مِنَ الْعِلْمِ ) بأن ( 1) الكافرون : 3 ـ 4. إِنَّكَ إِذاً لَمِنَ الظَّالِمِينَ (145) الَّذِينَ آتَيْناهُمُ الْكِتابَ يَعْرِفُونَهُ كَما يَعْرِفُونَ أَبْناءَهُمْ وَإِنَّ فَرِيقاً مِنْهُمْ لَيَكْتُمُونَ الْحَقَّ وَهُمْ يَعْلَمُونَ (146) الْحَقُّ مِنْ رَبِّكَ فَلا تَكُونَنَّ مِنَ الْمُمْتَرِينَ (147) طريقتهم باطلة ( إِنَّكَ إِذاً لَمِنَ الظَّالِمِينَ ) وهذه الجملة ، وإن كانت موجهة إلى الرسول ، لكن المقصود منها العموم ، ولا تنافي العصمة ، فإن الاشتراط يلائم المحال ، كقوله تعالى ( إِنْ كانَ لِلرَّحْمنِ وَلَدٌ فَأَنَا أَوَّلُ الْعابِدِينَ ) (1) وقد تقرر في المنطق أن صدق الشرطية إنما هو بوجود العلية ونحوها ، لا بصدق الطرفين."},{"text":"ٱلْحَقُّ مِن رَّبِّكَ ۖ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ","tafsir":"من اليهود والنصارى ( يَعْرِفُونَهُ ) أي الرسول ، أو هذا الحكم ، أعني كون تغيير القبلة بأمر الله سبحانه ، وإن كان الأول أقرب إلى سياق التشبيه ( كَما يَعْرِفُونَ أَبْناءَهُمْ وَإِنَّ فَرِيقاً مِنْهُمْ ) ممن لم يؤمن بالرسول ( لَيَكْتُمُونَ الْحَقَّ وَهُمْ يَعْلَمُونَ ) فليس عذر هؤلاء جهلهم ، حتى يرجى زواله ، وإنما العناد الذي لا علاج له."},{"text":"وَلِكُلٍّ وِجْهَةٌ هُوَ مُوَلِّيهَا ۖ فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ ۚ أَيْنَ مَا تَكُونُوا۟ يَأْتِ بِكُمُ ٱللَّهُ جَمِيعًا ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ","tafsir":"يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ، أي هذا هو الحق من عند الله ( فَلا تَكُونَنَّ مِنَ الْمُمْتَرِينَ ) أي الشاكين فيه ، فإن المحق إذا كثرت عليه التهجمات ورمي بأنه على غير حق ، يكاد يشك فيه ، ولذا يثبت الله الرسول صلى‌الله‌عليه‌وآله‌وسلم ، كما قال تعالى ( وَلَوْ لا أَنْ ثَبَّتْناكَ لَقَدْ كِدْتَ تَرْكَنُ إِلَيْهِمْ شَيْئاً قَلِيلاً ) (2) . ( 1) الزخرف : 82. ( 2) الإسراء : 75. وَلِكُلٍّ وِجْهَةٌ هُوَ مُوَلِّيها فَاسْتَبِقُوا الْخَيْراتِ أَيْنَ ما تَكُونُوا يَأْتِ بِكُمُ اللهُ جَمِيعاً إِنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ (148) وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرامِ"},{"text":"وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۖ وَإِنَّهُۥ لَلْحَقُّ مِن رَّبِّكَ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ","tafsir":"أي لكل أمة من الأمم طريقة ( هُوَ ) أي الله سبحانه ( مُوَلِّيها ) أي أمرهم بالتوجه إليها ، فلا غرابة أن يكون للمسلمين وجهة خاصة في قبلتهم ( فَاسْتَبِقُوا ) أي سارعوا إلى ( الْخَيْراتِ ) تنافسوا فيها ، فإن الله موليكم هذه الطرائق ، ولا تبقوا جامدين على طريقة منسوخة ، فإن ذلك انصراف عن الخير إلى الشر ، ومن المحتمل أن يكون « هو » راجعا إلى « كل » أي لكل فرد أو أمة ، طريقة في العمل والتفكير فذلك الشخص مولي وموجه نفسه إياها ، فليكن هم كل فريق وفرد أن يسابق غيره في الخيرات ( أَيْنَ ما تَكُونُوا ) من بقاع الأرض ( يَأْتِ بِكُمُ اللهُ جَمِيعاً ) يوم القيامة ، حتى يجازيكم على أعمالكم ( إِنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) فيتمكن من جمعكم ، ولا يفوته شيء [150] كان لتحويل القبلة نحو الكعبة أسباب وعلل ، العلة الأولى : رغبة الرسول صلى‌الله‌عليه‌وآله‌وسلم في أن تحول القبلة لما عيرته اليهود ، العلة الثانية : أن التحويل كان للحق ، وأن يكون للمسلمين ميزة خاصة يمتازون بها عن سائر الأمم ، حتى في اتجاه الصلاة ، العلة الثالثة : أن التحويل كان لقطع حجة الناس ، الذين كانوا يتعجبون من كون المسلمين ، يدعون دينا جديدا ، ومع ذلك يتوجهون إلى قبلة بني إسرائيل ، وتبعا لهذه العلل ، تكرر الأمر بالتوجه إلى المسجد الحرام ، وقال سبحانه ( وَمِنْ حَيْثُ خَرَجْتَ ) للسفر من البلاد ( فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرامِ ) وَإِنَّهُ لَلْحَقُّ مِنْ رَبِّكَ وَمَا اللهُ بِغافِلٍ عَمَّا تَعْمَلُونَ (149) وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرامِ وَحَيْثُ ما كُنْتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ لِئَلاَّ يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ إِلاَّ الَّذِينَ ظَلَمُوا مِنْهُمْ فَلا تَخْشَوْهُمْ وَاخْشَوْنِي فإنه قبلة في السفر كما هو قبلة في الحضر ، وفي هذا فائدة ثانية للتكرار ( وَإِنَّهُ ) أي توجيه الوجه نحو المسجد الحرام ( لَلْحَقُ ) الذي جاء ( مِنْ رَبِّكَ وَمَا اللهُ بِغافِلٍ عَمَّا تَعْمَلُونَ ) فمن أعرض عن هذه القبلة كان جزاءه سيئا ، ومن اتبعها كان جزاءه حسنا."},{"text":"وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۚ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِى وَلِأُتِمَّ نِعْمَتِى عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَ","tafsir":""},{"text":"كَمَآ أَرْسَلْنَا فِيكُمْ رَسُولًا مِّنكُمْ يَتْلُوا۟ عَلَيْكُمْ ءَايَـٰتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَيُعَلِّمُكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ","tafsir":"للسفر من البلاد ( فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرامِ ) هذا للسفر ( وَحَيْثُ ما كُنْتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ ) وهذه الآية ، جمع بين الآيتين السابقتين ( وَمِنْ حَيْثُ خَرَجْتَ ) ، الآية : 150 » ( وَحَيْثُ ما كُنْتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ ) ، الآية : 145 » وقد عرفت إنه كرر لفائدة العلة المذكورة في الآية ( لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ ) أي إن تحويل القبلة ، إنما هو لنقطع احتجاج الناس عليكم حيث يقولون : كيف إن المسلمين يدعون إلى دين جديد وقبلتهم هي قبلة أهل الكتاب ( إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ ) فإن هؤلاء لا ينفعهم المنطق ، فالمعاند لا تفيده الحجة ( فَلا تَخْشَوْهُمْ وَاخْشَوْنِي ) فالخشية ، إنما تكون ممن بيده النفع والضر ، وهؤلاء ليس بيدهم شيء منهما ، وإنما كل ذلك بيد الله سبحانه ، ولا يخفى أن الاستثناء منقطع كقولك : إنما فعلت الفعلة الفلانية ليعرف الناس بالأمر ، إلا من يريد وَلِأُتِمَّ نِعْمَتِي عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَ (150) كَما أَرْسَلْنا فِيكُمْ رَسُولاً مِنْكُمْ يَتْلُوا عَلَيْكُمْ آياتِنا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتابَ وَالْحِكْمَةَ وَيُعَلِّمُكُمْ ما لَمْ تَكُونُوا تَعْلَمُونَ (151) العناد ( وَ ) بعد ذلك فتحويل القبلة إنما كان ( لِأُتِمَّ نِعْمَتِي عَلَيْكُمْ ) بتميزكم عن أهل الكتاب وقطع تعيير اليهود ، وإرجاعكم إلى بناء جدكم إبراهيم الذي هو إحياء لذكراكم ( وَلَعَلَّكُمْ تَهْتَدُونَ ) إلى الحق اهتداء كاملا ، فإن في تشريف الإنسان بشرف سببا لتقريبه إلى الهداية الكاملة. [152] وقد أتممنا النعمة عليكم بتحويل القبلة ( كَما ) أنعمنا عليكم قبل ذلك بنعمة عظمي ف ( أَرْسَلْنا فِيكُمْ ) أيها المسلمون ( رَسُولاً مِنْكُمْ ) لا من غيركم ، فاخترتكم لأن تكون رسالتي بيد واحد منكم ( يَتْلُوا عَلَيْكُمْ آياتِنا ) وقرآننا تلاوة ( وَيُزَكِّيكُمْ ) يطهركم من أدناس الجاهلية والقذارات الخلقية ، والنجاسات البدنية ـ بإرشاده إياكم إليها ـ ( وَيُعَلِّمُكُمُ الْكِتابَ ) ومن المعلوم أن التلاوة غير التعليم ، فرب تال غير معلم ، بالإضافة إلى أن التعليم فيه معنى التركيز والتثبيت ( وَالْحِكْمَةَ ) يرشدكم بمواضع الأشياء ومواقع الخطأ والصواب ، فالحكمة ـ كما عرفت ـ وضع كل شيء موضعه ( وَيُعَلِّمُكُمْ ما لَمْ تَكُونُوا تَعْلَمُونَ ) بصورة عامة ، فيشمل القصص والتواريخ المفيدة وأحوال الأنبياء ، وأحوال المعاد مما ينفعهم في دينهم ودنياهم. فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلا تَكْفُرُونِ (152) يا أَيُّهَا الَّذِينَ آمَنُوا اسْتَعِينُوا بِالصَّبْرِ وَالصَّلاةِ إِنَّ اللهَ مَعَ الصَّابِرِينَ (153) وَلا تَقُولُوا لِمَنْ يُقْتَلُ فِي سَبِيلِ اللهِ أَمْواتٌ"},{"text":"فَٱذْكُرُونِىٓ أَذْكُرْكُمْ وَٱشْكُرُوا۟ لِى وَلَا تَكْفُرُونِ","tafsir":""},{"text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ ۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِينَ","tafsir":"أيها المسلمون بالطاعة والعبادة ، وتنفيذ الأوامر ( أَذْكُرْكُمْ ) بالنعمة والإحسان والجنان ( وَاشْكُرُوا لِي ) بإظهار النعمة والحمد عليها ( وَلا تَكْفُرُونِ ) كفرا في الاعتقاد ، أو كفرا في العمل بأن لا تعملوا بأوامري."},{"text":"وَلَا تَقُولُوا۟ لِمَن يُقْتَلُ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتٌۢ ۚ بَلْ أَحْيَآءٌ وَلَـٰكِن لَّا تَشْعُرُونَ","tafsir":"في أموركم التي تريدونها سواء كانت تحت اختياركم ، أم لم تكن كالصحة والغنى ( بِالصَّبْرِ ) وتحمل النفس ، فإن كثيرا من الأمور تتنجز بعد حين ، فإذا صبر الإنسان تنجزت أموره ونعم براحة البال ، واطمئنان النفس ، وإذا لم يصبر جرى القدر ، وهو مضطرب البال كئيب ( وَالصَّلاةِ ) فإن الصلاة توجب توجه الإنسان إلى الله سبحانه ، والانصراف عن الدنيا مما يشع في النفس الهدوء والسكينة ، وعدم الاهتمام بمكاره الدنيا ( إِنَّ اللهَ مَعَ الصَّابِرِينَ ) باللطف والعناية والرحمة والأجر والثواب ، وهكذا يهذب الإنسان والأمة ويرشدهم إلى مهمتهم العظيمة ، ويمرّنهم على الصبر والتحمل ، ولذا يخطوا القرآن الحكيم خطوة أخرى معهم بعد الصبر والصلاة ، قائلا : إنكم لا بد وأن تتحملوا مشاق القيادة من القتل وسائر أنواع المصائب التي تتعرض لمن أراد الإصلاح والإرشاد ، ولذا يقول سبحانه :"},{"text":"وَلَنَبْلُوَنَّكُم بِشَىْءٍ مِّنَ ٱلْخَوْفِ وَٱلْجُوعِ وَنَقْصٍ مِّنَ ٱلْأَمْوَٰلِ وَٱلْأَنفُسِ وَٱلثَّمَرَٰتِ ۗ وَبَشِّرِ ٱلصَّـٰبِرِينَ","tafsir":"فالميت من لا تأثير له بَلْ أَحْياءٌ وَلكِنْ لا تَشْعُرُونَ (154) وَلَنَبْلُوَنَّكُمْ بِشَيْءٍ مِنَ الْخَوْفِ وَالْجُوعِ وَنَقْصٍ مِنَ الْأَمْوالِ وَالْأَنْفُسِ وَالثَّمَراتِ وَبَشِّرِ الصَّابِرِينَ (155) الَّذِينَ إِذا أَصابَتْهُمْ مُصِيبَةٌ قالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ راجِعُونَ (156) في الحياة ولا امتداد ، وهؤلاء ليسوا كذلك ( بَلْ أَحْياءٌ ) حياة واقعية في الدنيا بتأثيراتهم وامتداداتهم ، وفي الآخرة ، لأنهم في نعيم مقيم ، ( وَلكِنْ لا تَشْعُرُونَ ) أنتم بحياتهم ، إذ الحياة في نظركم الحس والحركة ، مع إنها معنى سطحي للحياة."},{"text":"ٱلَّذِينَ إِذَآ أَصَـٰبَتْهُم مُّصِيبَةٌ قَالُوٓا۟ إِنَّا لِلَّهِ وَإِنَّآ إِلَيْهِ رَٰجِعُونَ","tafsir":"أي نمتحنكم أيها المسلمون ( بِشَيْءٍ مِنَ الْخَوْفِ ) وكونه شيئا ، إما باعتبار أنه لا يمتد ، وإنما الخوف في زمان يسير ، وإما باعتبار أنه لا يبلغ الخوف ـ غالبا ـ أشده ( وَالْجُوعِ ) ولم يذكر العطش لأن الماء غالبا متوفر ( وَنَقْصٍ مِنَ الْأَمْوالِ ) المبذولة في الحرب ، أو ما ينهب منها في التصادم ، أو الضيق الاقتصادي ، أو ما أشبه ( وَ ) نقص من ( الْأَنْفُسِ ) ممن يقتل في سبيل الله ( وَ ) نقص من ( الثَّمَراتِ ) بسبب النهب ، أو الحصاد قبل أوانه من أجل الأعداء ، كما وقع في قصة الخندق حيث أمر النبي صلى‌الله‌عليه‌وآله‌وسلم المسلمين أن يحصدوها ، لئلا ينتفع بها المشركون ـ كما في بعض التواريخ ـ أو بأسباب أخر ( وَبَشِّرِ ) يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( الصَّابِرِينَ ) في هذه المكاره."},{"text":"أُو۟لَـٰٓئِكَ عَلَيْهِمْ صَلَوَٰتٌ مِّن رَّبِّهِمْ وَرَحْمَةٌ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُهْتَدُونَ","tafsir":"أي إنا مملوكون له سبحانه ( وَإِنَّا إِلَيْهِ راجِعُونَ ) فهو مرجعنا ومعه حسابنا وجزاؤنا ، وفي هذه أُولئِكَ عَلَيْهِمْ صَلَواتٌ مِنْ رَبِّهِمْ وَرَحْمَةٌ وَأُولئِكَ هُمُ الْمُهْتَدُونَ (157) إِنَّ الصَّفا وَالْمَرْوَةَ مِنْ شَعائِرِ اللهِ فَمَنْ حَجَّ الْبَيْتَ أَوِ اعْتَمَرَ الجملة تسلية للمصاب ، إذ اعتراف الإنسان بأن كل شيء له إنما هو لله ، يهوّن ذهاب بعضها ، فإن صاحب المال أخذه ، كما أن اعتقاد الشخص ، بأن الله هو الذي يجازي يهوّن الأمر ، فإن ما فقده سوف يعوّض ولذا من كرر هذه الجملة في المصيبة عارفا معناها متوجها إلى الله سبحانه ، في التسليم والرضا ، يجد برد الاطمئنان في قلبه."},{"text":"۞ إِنَّ ٱلصَّفَا وَٱلْمَرْوَةَ مِن شَعَآئِرِ ٱللَّهِ ۖ فَمَنْ حَجَّ ٱلْبَيْتَ أَوِ ٱعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَن يَطَّوَّفَ بِهِمَا ۚ وَمَن تَطَوَّعَ خَيْرًا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ","tafsir":"والصلوات هي العطف ، فإن صلى بمعنى عطف ، وهي من الله التوجه بالبركة والإحسان ( وَرَحْمَةٌ ) ترحم في الدنيا والآخرة ( وَأُولئِكَ هُمُ الْمُهْتَدُونَ ) الذين اهتدوا إلى واقع الأمر مما ينفع دنياهم وعقباهم ، فبذلوا ما بذلوا في سبيل الله راضين مرضين. [159] وحيث ألمع سابقا إلى الجهاد ، أتى الإلماع إلى الحج ، فإنهما صنوان في التعداد والمشقة ـ في الجملة ـ فقال سبحانه ( إِنَّ الصَّفا وَالْمَرْوَةَ ) وهما جبلان قرب المسجد الحرام ( مِنْ شَعائِرِ اللهِ ) جمع شعيرة ، وهي مشتقة من اللباس الملتصق بشعر البدن ، فكل شيء مرتبط بشيء ارتباطا وثيقا يدل عليه يكون من شعائره ، فالمراد أن هذين الجبلين من الأمور المرتبطة بالله سبحانه ، حيث جعلهما محلا لعبادته بالسعي بينهما ( فَمَنْ حَجَّ الْبَيْتَ ) أي قصد البيت الحرام ، والحج القصد ( أَوِ اعْتَمَرَ ) والعمرة هي الزيارة أخذ من العمارة ، لأن فَلا جُناحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِما وَمَنْ تَطَوَّعَ خَيْراً فَإِنَّ اللهَ شاكِرٌ عَلِيمٌ (158) إِنَّ الَّذِينَ يَكْتُمُونَ ما أَنْزَلْنا مِنَ الْبَيِّناتِ الزائر يعمر المكان بزيارته ، والحج والعمرة عملان من أعمال الحج ( فَلا جُناحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِما ) أي يسعى بينهما ، وإنما عبر ب « لا جناح » لأن المسلمين تحرجوا من الطواف بهما ظنا منهم أنه من عمل المشركين ، حيث كان على الصفا صنم يسمى « أساف » وعلى المروة صنم يسمى « نائلة » فهو ترخيص في مقام توهم الحصر ، ومن المعلوم أن الإباحة في مقام توهم الحصر ، والنهي في مقام توهم الوجوب ، لا يدلان على مفادهما الأولية ، لأنه لإثبات أصل الطرف الآخر ، لا خصوصيته الإباحية والتمويمية ( وَمَنْ تَطَوَّعَ خَيْراً ) أي أتى بخير من الأعمال والأفعال تطوعا ، والتطوع التبرع بالشيء من الطوع بمعنى الانقياد ( فَإِنَّ اللهَ شاكِرٌ ) لعملهم ومعنى شكره تقديره وجزائه للعامل ( عَلِيمٌ ) بأعمالهم ، فلا يفوته شيء منها. [160] لعل ارتباط هذه الآية بما ورد قبلها ، أن اليهود والنصارى لم يفعلوا مثل ما فعل الرسول صلى‌الله‌عليه‌وآله‌وسلم حول الصفا والمروة ، فالرسول أبطل كل شيء حول الحج ، وأقام كل حق فيه ، فالصفا والمروة ، حيث كانا حقا أثبتهما الرسول صلى‌الله‌عليه‌وآله‌وسلم ، وإن ظن الناس أنهما من الباطل ، لكن أهل الكتاب حشروا كل ما أتى به الرسول صلى‌الله‌عليه‌وآله‌وسلم ـ مما عرفوه حقا ـ في زمرة الباطل ، ولذا صار الكلام السابق ، فاتحة للتعريض بهم ، فهو مثل أن يقول أحد أنا اعترفت بالحق ، لكنه لم يعترف بما علم من الحق ، والله أعلم بموارده ( إِنَّ الَّذِينَ يَكْتُمُونَ ما أَنْزَلْنا مِنَ الْبَيِّناتِ ) فيخفون الأدلة وَالْهُدى مِنْ بَعْدِ ما بَيَّنَّاهُ لِلنَّاسِ فِي الْكِتابِ أُولئِكَ يَلْعَنُهُمُ اللهُ وَيَلْعَنُهُمُ اللاَّعِنُونَ (159) إِلاَّ الَّذِينَ تابُوا وَأَصْلَحُوا وَبَيَّنُوا فَأُولئِكَ أَتُوبُ عَلَيْهِمْ وَأَنَا التَّوَّابُ الرَّحِيمُ (160) إِنَّ الَّذِينَ كَفَرُوا وَماتُوا وَهُمْ كُفَّارٌ أُولئِكَ عَلَيْهِمْ لَعْنَةُ اللهِ وَالْمَلائِكَةِ وَالنَّاسِ أَجْمَعِينَ (161) الدالة على حقية الإسلام ، مما نزلت في الكتب السالفة ( وَالْهُدى مِنْ بَعْدِ ما بَيَّنَّاهُ لِلنَّاسِ فِي الْكِتابِ ) أي يكتمون الهدى الذي يرونه ، وإن لم يكن منزلا وبيّنا ( أُولئِكَ يَلْعَنُهُمُ اللهُ ) يبعدهم عن الخير في الدنيا وفي الآخرة ، بتضييق الأمور عليهم هنا والعذاب هناك ( وَيَلْعَنُهُمُ اللَّاعِنُونَ ) الذين يأتي منهم اللعن من الناس والملائكة والجن."},{"text":"إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلْنَا مِنَ ٱلْبَيِّنَـٰتِ وَٱلْهُدَىٰ مِنۢ بَعْدِ مَا بَيَّنَّـٰهُ لِلنَّاسِ فِى ٱلْكِتَـٰبِ ۙ أُو۟لَـٰٓئِكَ يَلْعَنُهُمُ ٱللَّهُ وَيَلْعَنُهُمُ ٱللَّـٰعِنُونَ","tafsir":""},{"text":"إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَبَيَّنُوا۟ فَأُو۟لَـٰٓئِكَ أَتُوبُ عَلَيْهِمْ ۚ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ","tafsir":""},{"text":"إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌ أُو۟لَـٰٓئِكَ عَلَيْهِمْ لَعْنَةُ ٱللَّهِ وَٱلْمَلَـٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ","tafsir":"منهم واتبعوا الحق وأظهروه ( وَأَصْلَحُوا ) ما فسد من عقائدهم وأعمالهم ( وَبَيَّنُوا ) للناس ما أنزله الله من الهدى والبينات ( فَأُولئِكَ أَتُوبُ عَلَيْهِمْ ) فالتوبة معناها الرجوع ، ورجوع الله بمعنى إعادة الإحسان والرحمة عليهم بعد انقطاعها عنهم بسبب كفرهم وكتمانهم ( وَأَنَا التَّوَّابُ ) أي كثير الرجوع ، فإن العاصي إذا عصى ألف مرة ورجع ألف مرة قبلت توبته ، إذا تاب توبة نصوحا ( الرَّحِيمُ ) بالعباد."},{"text":"خَـٰلِدِينَ فِيهَا ۖ لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ","tafsir":"ولم يتوبوا ( وَماتُوا وَهُمْ كُفَّارٌ ) بالعقائد الصحيحة ( أُولئِكَ عَلَيْهِمْ لَعْنَةُ اللهِ وَالْمَلائِكَةِ وَالنَّاسِ أَجْمَعِينَ ) فإن الكل يلعنون الظالم ، والكافر ظالم ، فإنه وإن لم يقصده اللاعن خالِدِينَ فِيها لا يُخَفَّفُ عَنْهُمُ الْعَذابُ وَلا هُمْ يُنْظَرُونَ (162) وَإِلهُكُمْ إِلهٌ واحِدٌ لا إِلهَ إِلاَّ هُوَ الرَّحْمنُ الرَّحِيمُ (163) إِنَّ فِي خَلْقِ السَّماواتِ وَالْأَرْضِ وَاخْتِلافِ اللَّيْلِ وَالنَّهارِ وَالْفُلْكِ الَّتِي تَجْرِي فِي الْبَحْرِ بِما يَنْفَعُ النَّاسَ وَما أَنْزَلَ اللهُ مِنَ السَّماءِ مِنْ ماءٍ فَأَحْيا بِهِ الْأَرْضَ بالذات ، لكنه داخل في عموم اللعن."},{"text":"وَإِلَـٰهُكُمْ إِلَـٰهٌ وَٰحِدٌ ۖ لَّآ إِلَـٰهَ إِلَّا هُوَ ٱلرَّحْمَـٰنُ ٱلرَّحِيمُ","tafsir":"أي في تلك اللعنة ، إذ لعنة الدنيا تتصل بلعنة الآخرة ( لا يُخَفَّفُ عَنْهُمُ الْعَذابُ ) إذ لا أمد لعذاب الله بالنسبة إلى الكافرين ( وَلا هُمْ يُنْظَرُونَ ) فلا ينظر أحد إليهم نظرة رحمة وإحسان ، أو لا يمهلون للاعتذار ، أو لا يؤخر عنهم العذاب. [164] ولما تقدم حال الكافر صار السياق لبيان التوحيد ، والأدلة على الوحدانية ( وَإِلهُكُمْ ) أيها الناس ( إِلهٌ واحِدٌ ) لا شريك له ( لا إِلهَ إِلَّا هُوَ ) الموصوف ب ( الرَّحْمنُ الرَّحِيمُ ) لا كما يصور الإله بعض الكتب السماوية من أنه إله انتقام وغضب وعذاب."},{"text":"إِنَّ فِى خَلْقِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَـٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَٱلْفُلْكِ ٱلَّتِى تَجْرِى فِى ٱلْبَحْرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن مَّآءٍ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍ وَتَصْرِيفِ ٱلرِّيَـٰحِ وَٱلسَّحَابِ ٱلْمُسَخَّرِ بَيْنَ ٱلسَّمَآءِ وَٱلْأَرْضِ لَـَٔايَـٰتٍ لِّقَوْمٍ يَعْقِلُونَ","tafsir":""},{"text":"وَمِنَ ٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادًا يُحِبُّونَهُمْ كَحُبِّ ٱللَّهِ ۖ وَٱلَّذِينَ ءَامَنُوٓا۟ أَشَدُّ حُبًّا لِّلَّهِ ۗ وَلَوْ يَرَى ٱلَّذِينَ ظَلَمُوٓا۟ إِذْ يَرَوْنَ ٱلْعَذَابَ أَنَّ ٱلْقُوَّةَ لِلَّهِ جَمِيعًا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلْعَذَابِ","tafsir":"بهذا النظام البديع والترتيب الرائع ( وَالْأَرْضِ ) بهذا الأسلوب المنظم المتكامل ( وَ ) في ( اخْتِلافِ اللَّيْلِ وَالنَّهارِ ) يأتي أحدهما عقب الأخر خليفة ، لتنظيم الحياة على الأرض بأجمل صورة ( وَ ) في ( الْفُلْكِ ) السفينة ( الَّتِي تَجْرِي فِي الْبَحْرِ بِما يَنْفَعُ النَّاسَ ) في أسفارهم وتجارتهم ( وَ ) في ( ما أَنْزَلَ اللهُ مِنَ السَّماءِ ) جهة العلو ( مِنْ ماءٍ ) ببيان « ما » ( فَأَحْيا بِهِ الْأَرْضَ ) بَعْدَ مَوْتِها وَبَثَّ فِيها مِنْ كُلِّ دَابَّةٍ وَتَصْرِيفِ الرِّياحِ وَالسَّحابِ الْمُسَخَّرِ بَيْنَ السَّماءِ وَالْأَرْضِ لَآياتٍ لِقَوْمٍ يَعْقِلُونَ (164) وَمِنَ النَّاسِ مَنْ يَتَّخِذُ مِنْ دُونِ اللهِ أَنْداداً يُحِبُّونَهُمْ بالإنبات ( بَعْدَ مَوْتِها ) أي جمودها وركودها ( وَبَثَ ) أي نشر وفرق ( فِيها ) أي في الأرض ( مِنْ كُلِّ دَابَّةٍ ) تدب وتتحرك على وجه الأرض ، وكلمة « بث » عطف على « أحيا » أي كان المطر سببا لإحياء الأرض ، وانتشار الحيوانات فيها ، إذ لو لا المطر لم يكن للحيوان ماء ، ولا طعام فيهلك ، ولم يبق له نسل ( وَ ) في ( تَصْرِيفِ الرِّياحِ ) أي صرفها ونقلها من مكان إلى مكان لتروح وتذهب بالأمراض والعفونات ، وتنقل السحاب من هنا إلى هناك ، ولو كانت الريح راكدة لم تنفع أي شيء ( وَ ) في ( السَّحابِ الْمُسَخَّرِ بَيْنَ السَّماءِ وَالْأَرْضِ ) فإنه بما يكونه من أطنان من الماء ، يبقى معلقا بين الجهتين ، ويسير إلى كل ناحية ( لَآياتٍ ) وعلامات دالة على الله ، ووحدته وسائر صفاته ( لِقَوْمٍ يَعْقِلُونَ ) ويعملون عقولهم في استفادة النتائج من المقدمات والمسبب عن الأسباب ، وينتقلون من العلم بالمعلول إلى العلم بالعلة."},{"text":"إِذْ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُوا۟ مِنَ ٱلَّذِينَ ٱتَّبَعُوا۟ وَرَأَوُا۟ ٱلْعَذَابَ وَتَقَطَّعَتْ بِهِمُ ٱلْأَسْبَابُ","tafsir":"أي بعضهم ( مَنْ يَتَّخِذُ مِنْ دُونِ اللهِ ) أي غير الله ( أَنْداداً ) جمع ند ، بمعنى الأشباه ، والمراد بذلك آلهة يجعلها شبيهة لله في أنه يعبدها ، وهي الأوثان ( يُحِبُّونَهُمْ ) أي يحب هؤلاء الناس كَحُبِّ اللهِ وَالَّذِينَ آمَنُوا أَشَدُّ حُبًّا لِلَّهِ وَلَوْ يَرَى الَّذِينَ ظَلَمُوا إِذْ يَرَوْنَ الْعَذابَ أَنَّ الْقُوَّةَ لِلَّهِ جَمِيعاً وَأَنَّ اللهَ شَدِيدُ الْعَذابِ (165) إِذْ تَبَرَّأَ الَّذِينَ اتُّبِعُوا مِنَ الَّذِينَ اتَّبَعُوا وَرَأَوُا الْعَذابَ تلك الآلهة ، وإنما أتى بجمع العاقل لكونها ردفت مع الله سبحانه ، والقاعدة تغليب الرديف على رديفه كقوله تعالى ( مَنْ يَمْشِي عَلى بَطْنِهِ ) (1) وقوله ( وَارْكَعِي مَعَ الرَّاكِعِينَ ) (2) ( كَحُبِّ اللهِ ) أي كحبهم لله ، أو حبا شبيها بما يستحق الله ، وعلى الأول ، فالمراد بهم المشركون الذين يعتقدون بالله ( وَالَّذِينَ آمَنُوا أَشَدُّ حُبًّا لِلَّهِ ) من حب هؤلاء لأوثانهم ، فالمؤمنين حيث يعرفون أن كل خير من الله يحبونه حبا بالغا ( وَلَوْ يَرَى الَّذِينَ ظَلَمُوا إِذْ يَرَوْنَ الْعَذابَ أَنَّ الْقُوَّةَ لِلَّهِ جَمِيعاً ) يعني لو يرون هؤلاء المشركين يوم القيامة كون القوة جميعا لرأوا مضرة فعلهم ، وسوء عاقبة شركهم ، وحذف جواب لو ، تهويلا للأمر ، كما تقول لعدوك : لو ظفرت بك ( وَأَنَّ اللهَ شَدِيدُ الْعَذابِ ) عطف على « أن القوة » . [167] إن الرؤية من الظالم للعذاب ، إنما يكون ( إِذْ تَبَرَّأَ الَّذِينَ اتُّبِعُوا ) من القادة ( مِنَ الَّذِينَ اتَّبَعُوا ) وهم التابعون لهم ( وَرَأَوُا ) جميعا ( الْعَذابَ ( 1) النور : 46. ( 2) آل عمران : 44. وَتَقَطَّعَتْ بِهِمُ الْأَسْبابُ (166) وَقالَ الَّذِينَ اتَّبَعُوا لَوْ أَنَّ لَنا كَرَّةً فَنَتَبَرَّأَ مِنْهُمْ كَما تَبَرَّؤُا مِنَّا كَذلِكَ يُرِيهِمُ اللهُ أَعْمالَهُمْ حَسَراتٍ عَلَيْهِمْ وَما هُمْ بِخارِجِينَ مِنَ النَّارِ (167) يا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الْأَرْضِ حَلالاً طَيِّباً وَتَقَطَّعَتْ بِهِمُ ) أي فيما بينهم ( الْأَسْبابُ ) فما كان في الدنيا يسبب وصلة بعضهم لبعض من المال والرئاسة والقرابة والحلف وأشباهها ، تنقطع هناك ، فلا داعي لنصرة الرؤساء أتباعهم الذين كانوا يتبعونهم في الدنيا."},{"text":"وَقَالَ ٱلَّذِينَ ٱتَّبَعُوا۟ لَوْ أَنَّ لَنَا كَرَّةً فَنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُوا۟ مِنَّا ۗ كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعْمَـٰلَهُمْ حَسَرَٰتٍ عَلَيْهِمْ ۖ وَمَا هُم بِخَـٰرِجِينَ مِنَ ٱلنَّارِ","tafsir":""},{"text":"يَـٰٓأَيُّهَا ٱلنَّاسُ كُلُوا۟ مِمَّا فِى ٱلْأَرْضِ حَلَـٰلًا طَيِّبًا وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَـٰنِ ۚ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ","tafsir":"إي التابعين لرؤسائهم ( لَوْ أَنَّ لَنا كَرَّةً ) أي يا ليت لنا عودة إلى دار الدنيا ( فَنَتَبَرَّأَ مِنْهُمْ ) أي من هؤلاء الرؤساء ( كَما تَبَرَّؤُا مِنَّا ) هنا في القيامة حال حاجتنا إلى العون ( كَذلِكَ ) أي هكذا ( يُرِيهِمُ اللهُ أَعْمالَهُمْ ) أي أعمال كل من التابعين والمتبوعين ( حَسَراتٍ عَلَيْهِمْ ) فإن صلاتهم وأعمالهم ، كلها ذهبت أدراج الرياح ، فيتحسرون لماذا لم يعملوا بأوامر الله سبحانه ( وَما هُمْ بِخارِجِينَ مِنَ النَّارِ ) فإن المشرك يبقى في النار إلى الأبد ، إن تمت عليه الحجة وعاند. [169] وإذ تم الكلام حول العقيدة ، توجه إلى الحياة التي هي مقصد الإنسان ، وإليها يرجع كثير من حركته وسكونه ( يا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الْأَرْضِ ) من نباتها وحيوانها ومائها ومعدنها ( حَلالاً طَيِّباً ) أي في حال كون المأكول حلالا طيبا ، إلا ما حرم منه ، وفي قوله « طيبا » وَلا تَتَّبِعُوا خُطُواتِ الشَّيْطانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ (168) إِنَّما يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشاءِ وَأَنْ تَقُولُوا عَلَى اللهِ ما لا تَعْلَمُونَ (169) وَإِذا قِيلَ لَهُمُ اتَّبِعُوا ما أَنْزَلَ اللهُ قالُوا بَلْ نَتَّبِعُ ما أَلْفَيْنا عَلَيْهِ آباءَنا أَ وَلَوْ كانَ آباؤُهُمْ لا يَعْقِلُونَ شَيْئاً وَلا يَهْتَدُونَ (170) إشارة إلى أن كل حلال طيب ، وليس فيه خبث يوجب انحراف الصحة ، أو انحراف الخلق ( وَلا تَتَّبِعُوا خُطُواتِ الشَّيْطانِ ) فكأن الشيطان يخطو نحو الآثام ، ومن أثم كأنه تتبع خطواته إذ مشى خلفه ( إِنَّهُ ) أي الشيطان ( لَكُمْ عَدُوٌّ مُبِينٌ ) أي عدوا ظاهرا."},{"text":"إِنَّمَا يَأْمُرُكُم بِٱلسُّوٓءِ وَٱلْفَحْشَآءِ وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ","tafsir":""},{"text":"وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُوا۟ مَآ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلْ نَتَّبِعُ مَآ أَلْفَيْنَا عَلَيْهِ ءَابَآءَنَآ ۗ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْقِلُونَ شَيْـًٔا وَلَا يَهْتَدُونَ","tafsir":"أي الأعمال السيئة ( وَالْفَحْشاءِ ) وهي الأعمال السيئة للغاية ، فهو مشتق من الفحش ، بمعنى التعدي ( وَأَنْ تَقُولُوا عَلَى اللهِ ) أي تنسبوا إلى الله ( ما لا تَعْلَمُونَ ) من العقائد والأحكام ، وعدم العلم هنا أعم من العلم بالعدم ، كما قال سبحانه ( أَمْ تُنَبِّئُونَهُ بِما لا يَعْلَمُ ) (1) ."},{"text":"وَمَثَلُ ٱلَّذِينَ كَفَرُوا۟ كَمَثَلِ ٱلَّذِى يَنْعِقُ بِمَا لَا يَسْمَعُ إِلَّا دُعَآءً وَنِدَآءً ۚ صُمٌّۢ بُكْمٌ عُمْىٌ فَهُمْ لَا يَعْقِلُونَ","tafsir":"من الأحكام وسائر الوحي ( قالُوا بَلْ نَتَّبِعُ ما أَلْفَيْنا عَلَيْهِ آباءَنا ) أي وجدنا عليه آباءنا من التقاليد ، فأنكر الله ذلك عليهم بالاستفهام الإنكاري ، بقوله ( أَ وَلَوْ كانَ آباؤُهُمْ لا يَعْقِلُونَ شَيْئاً ) من أمور الدين والدنيا ( وَلا يَهْتَدُونَ ) إلى الحق فإذا ( 1) الرعد : 34. وَمَثَلُ الَّذِينَ كَفَرُوا كَمَثَلِ الَّذِي يَنْعِقُ بِما لا يَسْمَعُ إِلاَّ دُعاءً وَنِداءً صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لا يَعْقِلُونَ (171) يا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِنْ طَيِّباتِ ما رَزَقْناكُمْ وَاشْكُرُوا لِلَّهِ إِنْ كُنْتُمْ إِيَّاهُ تَعْبُدُونَ (172) إِنَّما حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ ظهر لكم أن آباءكم لا يعلمون ، فكيف تتبعونهم. [172] ثم بين الله سبحانه ، أن هؤلاء الكفار لعنادهم وتعصبهم ، قد غلقت منافذ السمع والبصر عنهم ، فلا يفيد فيهم وعظ ولا تذكير ( وَمَثَلُ الَّذِينَ كَفَرُوا ) بعد ما يروا الآيات ، ويسمعوا نداءك يا رسول الله ( كَمَثَلِ الَّذِي يَنْعِقُ ) أي يرفع صوته ( بِما ) أي بالحيوان الذي ( لا يَسْمَعُ ) ولا يفهم الكلام ، وإنما يسمع ( إِلَّا دُعاءً وَنِداءً ) فالحيوان ، إذا صحت به ، لا يفهم من كلامك إلا مجرد الدعوة والنداء ، فهؤلاء الكفار كذلك ، إذ لا ينتفعون بكلامك أبدا ، فهم ( صُمٌ ) جمع أصم ( بُكْمٌ ) جمع أبكم ( عُمْيٌ ) جمع أعمى ، فإنهم ولو كانت لهم آذان وألسنة وعيون ، لكنها كالمعطلة ، لأنها لا تؤدي وظيفتها ( فَهُمْ لا يَعْقِلُونَ )"},{"text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُلُوا۟ مِن طَيِّبَـٰتِ مَا رَزَقْنَـٰكُمْ وَٱشْكُرُوا۟ لِلَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ","tafsir":""},{"text":"إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَٱلدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيْرِ ٱللَّهِ ۖ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَلَآ إِثْمَ عَلَيْهِ ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ","tafsir":"تكرارا لما تقدم لإلحاق مسألتي الشكر والمحرمات به ( وَاشْكُرُوا لِلَّهِ إِنْ كُنْتُمْ إِيَّاهُ تَعْبُدُونَ ) ولا تشكروا سائر الآلهة ، كالمشركين الذين يزعمون أنهم يمطرون بالأنواء ، ويرزقون بالآلهة المزعومة."},{"text":"إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلْكِتَـٰبِ وَيَشْتَرُونَ بِهِۦ ثَمَنًا قَلِيلًا ۙ أُو۟لَـٰٓئِكَ مَا يَأْكُلُونَ فِى بُطُونِهِمْ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوْمَ ٱلْقِيَـٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ","tafsir":"وهي التي لم تذبح على النحو الشرعي وَالدَّمَ وَلَحْمَ الْخِنْزِيرِ وَما أُهِلَّ بِهِ لِغَيْرِ اللهِ فَمَنِ اضْطُرَّ غَيْرَ باغٍ وَلا عادٍ فَلا إِثْمَ عَلَيْهِ إِنَّ اللهَ غَفُورٌ رَحِيمٌ (173) إِنَّ الَّذِينَ يَكْتُمُونَ ما أَنْزَلَ اللهُ مِنَ الْكِتابِ ( وَالدَّمَ ) وهو وإن كان مطلقا ، إلا إنه مقيد بالمسفوح لقوله سبحانه ( إِلَّا أَنْ يَكُونَ مَيْتَةً أَوْ دَماً مَسْفُوحاً ) (1) ( وَلَحْمَ الْخِنْزِيرِ ) وخص اللحم بالكلام ، وإن كانت جملته محرمة ، لأن اللحم هو المعظم المقصود في الغالب ( وَما أُهِلَّ بِهِ لِغَيْرِ اللهِ ) الإهلال في الذبيحة رفع الصوت بالتسمية ، وقد كان المشركون عند ذبحهم ، يرفعون أصواتهم بتسمية الأوثان ، فنهى الله سبحانه عن أكل ذبيحة ذكر غير اسم الله عليها ( فَمَنِ اضْطُرَّ ) بصيغة المجهول ، فإن « اضطر » متعد من باب الافتعال ، وحيث لم يكن المقصود ، سبب الاضطرار ، ذكر مجهولا ( غَيْرَ باغٍ ) أي لم يكن باغيا وطالبا للذة في أكله وشربه ( وَلا عادٍ ) أي متعد في الأكل والشرب ، عن حد الضرورة ، أو غير باغ على إمام المسلمين ، ولا عاد بالمعصية طريق المحقين ( فَلا إِثْمَ عَلَيْهِ ) في تناول هذه المحرمات ( إِنَّ اللهَ غَفُورٌ ) يستر العصيان إذا اضطر إليه ، فغفر بمعنى ستر ، وستر العصيان ، عدم المؤاخذة به ( رَحِيمٌ ) بكم ، ولذا جاز تناول المحرم في حال الاضطرار."},{"text":"أُو۟لَـٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَـٰلَةَ بِٱلْهُدَىٰ وَٱلْعَذَابَ بِٱلْمَغْفِرَةِ ۚ فَمَآ أَصْبَرَهُمْ عَلَى ٱلنَّارِ","tafsir":"وهم اليهود والنصارى الذين كانوا يكتمون العقائد الحقة الموجودة في كتابهم ، وينسبون إلى ( 1) الأنعام : 146. وَيَشْتَرُونَ بِهِ ثَمَناً قَلِيلاً أُولئِكَ ما يَأْكُلُونَ فِي بُطُونِهِمْ إِلاَّ النَّارَ وَلا يُكَلِّمُهُمُ اللهُ يَوْمَ الْقِيامَةِ وَلا يُزَكِّيهِمْ وَلَهُمْ عَذابٌ أَلِيمٌ (174) أُولئِكَ الَّذِينَ اشْتَرَوُا الضَّلالَةَ بِالْهُدى الكتاب أحكاما لم توجد فيه ، كما قال سبحانه ( قُلْ فَأْتُوا بِالتَّوْراةِ فَاتْلُوها إِنْ كُنْتُمْ صادِقِينَ ) (1) ولعل ارتباط هذه الآية بما قبلها من جهة الأمور التي كانوا يحرمونها ، ولم يكن في كتبهم تحريم لها ( وَيَشْتَرُونَ بِهِ ) أي بهذا الكتاب ( ثَمَناً قَلِيلاً ) من رئاسة الدنيا وأموالها ، فإنها قليل بالنسبة إلى الآخرة ( أُولئِكَ ما يَأْكُلُونَ فِي بُطُونِهِمْ ) أي لا يجرون إلى بطونهم ولعل ذكر في بطونهم للاحتراز عن الأكل في بطن الغير ، فإن العرب تقول شبع فلان في بطنه ، إذا أكله بنفسه ، وتقول شبع فلان في بطن غيره ، إذا أكله من يتعلق به ( إِلَّا النَّارَ ) فإن ما أكلوه ينقلب نارا تحرق بطونهم في جهنم ( وَلا يُكَلِّمُهُمُ اللهُ يَوْمَ الْقِيامَةِ ) فيهملهم ليذوقوا الهوان جزاء ما فعلوا ( وَلا يُزَكِّيهِمْ ) أي لا يطهرهم عن الآثام ، فإن البطن إذا مليء حراما يقسو ، فلا يهتدي حتى يتزكى الإنسان ويتطهر ( وَلَهُمْ عَذابٌ أَلِيمٌ ) مؤلم."},{"text":"ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلْكِتَـٰبَ بِٱلْحَقِّ ۗ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِى ٱلْكِتَـٰبِ لَفِى شِقَاقٍۭ بَعِيدٍ","tafsir":"الذين يكتمون ما أنزل الله هم ( الَّذِينَ اشْتَرَوُا الضَّلالَةَ بِالْهُدى ) أي عوض الهداية ، فكأن نفس الإنسان ثمن لأحد أمرين الضلالة والهداية ، فهم أعطوا أنفسهم ، واشتروا الضلالة عوض أن ( 1) آل عمران : 94. وَالْعَذابَ بِالْمَغْفِرَةِ فَما أَصْبَرَهُمْ عَلَى النَّارِ (175) ذلِكَ بِأَنَّ اللهَ نَزَّلَ الْكِتابَ بِالْحَقِّ وَإِنَّ الَّذِينَ اخْتَلَفُوا فِي الْكِتابِ لَفِي شِقاقٍ بَعِيدٍ (176) لَيْسَ الْبِرَّ أَنْ تُوَلُّوا وُجُوهَكُمْ قِبَلَ الْمَشْرِقِ وَالْمَغْرِبِ وَلكِنَّ الْبِرَّ مَنْ آمَنَ بِاللهِ وَالْيَوْمِ الْآخِرِ يشتروا الهداية ( وَ ) اشتروا ( الْعَذابَ بِالْمَغْفِرَةِ ) فعوض أن يشتروا المغفرة لأنفسهم اشتروا العذاب ( فَما أَصْبَرَهُمْ عَلَى النَّارِ ) تعجب عن صبرهم على النار التي هي عاقبة عملهم ، أي كيف أنهم يصبرون على النار حينما فعلوا ما عاقبته النار."},{"text":"۞ لَّيْسَ ٱلْبِرَّ أَن تُوَلُّوا۟ وُجُوهَكُمْ قِبَلَ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ وَلَـٰكِنَّ ٱلْبِرَّ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَٱلْمَلَـٰٓئِكَةِ وَٱلْكِتَـٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلْمَالَ عَلَىٰ حُبِّهِۦ ذَوِى ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينَ وَٱبْنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِى ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلْمُوفُونَ بِعَهْدِهِمْ إِذَا عَـٰهَدُوا۟ ۖ وَٱلصَّـٰبِرِينَ فِى ٱلْبَأْسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلْبَأْسِ ۗ أُو۟لَـٰٓئِكَ ٱلَّذِينَ صَدَقُوا۟ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُتَّقُونَ","tafsir":"العذاب ، إنما توجه إليهم بسبب أن ( اللهَ نَزَّلَ الْكِتابَ ) أي التوراة ( بِالْحَقِّ وَإِنَّ الَّذِينَ اخْتَلَفُوا فِي الْكِتابِ ) بكتمان بعضه وإظهار بعض ( لَفِي شِقاقٍ ) وخلاف عن الحق ( بَعِيدٍ ) فهم إنما استحقوا العذاب ، لأنهم خالفوا الحق ، وكتموا ما لزم إظهاره ، ومن المحتمل أن يكون المراد بالكتاب « القرآن » أي أن عذابهم بسبب كتمانهم كون القرآن حقا واختلافهم فيه ، بأنه سحر وكهانة أو كلام بشر."},{"text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلْقِصَاصُ فِى ٱلْقَتْلَى ۖ ٱلْحُرُّ بِٱلْحُرِّ وَٱلْعَبْدُ بِٱلْعَبْدِ وَٱلْأُنثَىٰ بِٱلْأُنثَىٰ ۚ فَمَنْ عُفِىَ لَهُۥ مِنْ أَخِيهِ شَىْءٌ فَٱتِّبَاعٌۢ بِٱلْمَعْرُوفِ وَأَدَآءٌ إِلَيْهِ بِإِحْسَـٰنٍ ۗ ذَٰلِكَ تَخْفِيفٌ مِّن رَّبِّكُمْ وَرَحْمَةٌ ۗ فَمَنِ ٱعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌ","tafsir":"كل البر أيها اليهود المجادلون حول تحويل القبلة الصارفون أوقاتكم في هذه البحوث العقيمة ( أَنْ تُوَلُّوا وُجُوهَكُمْ قِبَلَ الْمَشْرِقِ وَالْمَغْرِبِ ) فإن ذلك أمر فرعي مرتبط بتكليف الله سبحانه ، وقد كلفنا أن نصرف الوجوه إلى الكعبة ( وَلكِنَّ الْبِرَّ ) فعل ، أي ولكن ذا البر ( مَنْ آمَنَ بِاللهِ وَالْيَوْمِ الْآخِرِ ) فذلك هو الأصل الذي وَالْمَلائِكَةِ وَالْكِتابِ وَالنَّبِيِّينَ وَآتَى الْمالَ عَلى حُبِّهِ ذَوِي الْقُرْبى وَالْيَتامى وَالْمَساكِينَ وَابْنَ السَّبِيلِ وَالسَّائِلِينَ وَفِي الرِّقابِ وَأَقامَ الصَّلاةَ وَآتَى الزَّكاةَ وَالْمُوفُونَ بِعَهْدِهِمْ إِذا عاهَدُوا وَالصَّابِرِينَ يتفرع عليه أحكام الصلاة وغيرها ( وَ ) آمن ب ( الْمَلائِكَةِ وَالْكِتابِ ) المنزل من عند الله على أنبيائه ( وَ ) آمن ب ( النَّبِيِّينَ ) كلهم أولهم وأوسطهم وأخرهم ( وَآتَى الْمالَ ) أي أعطاه وأنفقه ( عَلى حُبِّهِ ) أي مع أنه يحبه ، أو على حب الله تعالى ( ذَوِي الْقُرْبى ) أي قراباته وأرحامه ( وَالْيَتامى ) الذين مات أبوهم ( وَالْمَساكِينَ ) الذين لا يجدون النفقة لأنفسهم وأهليهم ( وَابْنَ السَّبِيلِ ) الذي انقطع في سفره ، فلا مال له يوصله إلى أهله ومقصده ، وسمي ابن السبيل ، لعدم معرفة أبيه وعشيرته ( وَالسَّائِلِينَ ) من الفقراء الذين يسألون الناس ( وَ ) آتى المال ( فِي ) فك ( الرِّقابِ ) أي اشتراء العبيد أو إعتاقهم ، حتى يتحرروا عن ربق العبودية ( وَأَقامَ الصَّلاةَ ) أي أداها على حدودها ( وَآتَى الزَّكاةَ ) الواجبة والمستحبة ( وَالْمُوفُونَ ) الذين يفون ( بِعَهْدِهِمْ إِذا عاهَدُوا ) سواء كان عهدا مع الله كالنذر والبيعة ، أو مع الناس كالعقود ، وهذا عطف على قوله « من آمن » ( وَالصَّابِرِينَ ) عطف على من آمن على طريق القطع بتقدير المدح ، كما قال ابن مالك : و اقطع أو اتبع أن يكن معينا بدونها أو بعضها اقطع معلنا فِي الْبَأْساءِ وَالضَّرَّاءِ وَحِينَ الْبَأْسِ أُولئِكَ الَّذِينَ صَدَقُوا وَأُولئِكَ هُمُ الْمُتَّقُونَ (177) يا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الْقِصاصُ فِي الْقَتْلى و ارفع أو انصب إن قطعت مضمرا مبتدءا أو ناصبا لن يظهرا فإن عادة العربي أن يتفنن بالقطع رفعا ونصبا إذا طالت الصفات تقليلا للكلل وتنشيطا للذهن بالتلون في الكلام ( فِي الْبَأْساءِ ) البؤس الفقر ( وَالضَّرَّاءِ ) والمضر الموجع والعلة وكل ضرر ( وَحِينَ الْبَأْسِ ) أي الصابرين حين القتال ( أُولئِكَ ) الموصوفون بهذه الصفات هم ( الَّذِينَ صَدَقُوا ) في نياتهم وأعمالهم ، لا من يجادل في أمر كتحويل القبلة ( وَأُولئِكَ هُمُ الْمُتَّقُونَ ) الخائفون من الله سبحانه ، وفي هذه الآية الكريمة إلماح إلى حال كثير من الناس حيث يتركون المهام ويناقشون في أمر غير مهم عنادا وعصبية. [179] وحيث ذكر سبحانه ما هو البر عقبه ببعض الأحكام التي ينبغي لأهل البر المؤمنين بالله واليوم الآخر المتصفين بتلك الصفات أن يلتزموا بها ( يا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الْقِصاصُ ) ومعنى كتابته تشريعه إذ الشرائع تكتب ( فِي الْقَتْلى ) جمع قتيل ، فقد ورد أنها نزلت في حيين من العرب لأحدهما طول على الأخر ، وكانوا يتزوجون نساء بغير حلال ، وأقسموا لنقتلن بالعبد منا الحر منهم ، وبالمرأة منا الرجل منهم ، وبالرجل منا الرجلين منهم ، وجعلوا جراحاتهم على الضعف من جراح أولئك ، حتى جاء الإسلام ، وأبطل تلك الأحكام ، ف ـ الْحُرُّ بِالْحُرِّ وَالْعَبْدُ بِالْعَبْدِ وَالْأُنْثى بِالْأُنْثى فَمَنْ عُفِيَ لَهُ مِنْ أَخِيهِ شَيْءٌ فَاتِّباعٌ بِالْمَعْرُوفِ وَأَداءٌ إِلَيْهِ بِإِحْسانٍ ذلِكَ تَخْفِيفٌ مِنْ رَبِّكُمْ وَرَحْمَةٌ فَمَنِ اعْتَدى بَعْدَ ذلِكَ فَلَهُ عَذابٌ أَلِيمٌ (178) وَلَكُمْ فِي الْقِصاصِ حَياةٌ الحر ب ـ مقابل الحر يقتل لا مقابل العبد ( وَالْعَبْدُ بِالْعَبْدِ وَالْأُنْثى ) تقتل بمقابل الأنثى لا الذكر يقتل في قبال الأنثى ( فَمَنْ عُفِيَ لَهُ مِنْ ) قبل ( أَخِيهِ شَيْءٌ ) بأن عفى الأخ الولي للمقتول عن قتل القاتل ، وبدله بالدية ، أو عفى عن بعض الدية ، وبقي بعضها الأخر فالواجب على الطرفين ، مراقبة الله في الأخذ والإعطاء ، فمن طرف الولي للمقتول ( فَاتِّباعٌ ) للقاتل ( بِالْمَعْرُوفِ ) بأن لا يشدد في طلب الدية ، ومن طرف القاتل ( وَأَداءٌ إِلَيْهِ ) أي إلى العافي ( بِإِحْسانٍ ) من غير مطل وتصعيب ( ذلِكَ ) الحكم في باب القتيل بالمماثلة ، أولا ، والتخيير بين القتل والدية والعفو ثانيا ( تَخْفِيفٌ مِنْ رَبِّكُمْ ) عليكم ( وَرَحْمَةٌ ) منه بكم ، وفي المجمع أنه كان لأهل التوراة القصاص أو العفو ، ولأهل الإنجيل العفو والدية ( فَمَنِ اعْتَدى ) عن الحكم المقرر ( بَعْدَ ذلِكَ ) الذي قررناه من الأحكام ( فَلَهُ عَذابٌ أَلِيمٌ ) مؤلم في الدنيا والآخرة."},{"text":"وَلَكُمْ فِى ٱلْقِصَاصِ حَيَوٰةٌ يَـٰٓأُو۟لِى ٱلْأَلْبَـٰبِ لَعَلَّكُمْ تَتَّقُونَ","tafsir":""},{"text":"كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ إِن تَرَكَ خَيْرًا ٱلْوَصِيَّةُ لِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ بِٱلْمَعْرُوفِ ۖ حَقًّا عَلَى ٱلْمُتَّقِينَ","tafsir":"في باب القتل ، بأن يقتل القاتل عمدا ( حَياةٌ ) للمجموع ، لأن كل من افتكر إنه لو قتل قتل ارتدع إلا النادر ، وأيضا إن القصاص يوجب عدم تعدي أولياء المقتول على يا أُولِي الْأَلْبابِ لَعَلَّكُمْ تَتَّقُونَ (179) كُتِبَ عَلَيْكُمْ إِذا حَضَرَ أَحَدَكُمُ الْمَوْتُ إِنْ تَرَكَ خَيْراً الْوَصِيَّةُ لِلْوالِدَيْنِ وَالْأَقْرَبِينَ بِالْمَعْرُوفِ حَقًّا عَلَى الْمُتَّقِينَ (180) أقرباء القاتل ، بأن يقتلوا منهم عددا كثيرا ، كما كان هو المتعارف في زمان الجاهلية ، حتى ربما فنيت القبيلة لأجل قتيل واحد ( يا أُولِي الْأَلْبابِ ) جمع لب ، بمعنى العقل ، أي يا أصحاب العقول ( لَعَلَّكُمْ تَتَّقُونَ ) القتل ، أي شرع القصاص ، حتى تتقون من القتل. [181] وحيث ألمح القرآن الحكيم إلى حكم القتل ، أشار إلى ما يرتبط به من الوصية ، فقال ( كُتِبَ عَلَيْكُمْ ) كتابة راجحة ، فإن الكتابة تشمل الواجب والمندوب ، والوصية مندوبة ، إلا إذا وجبت بالعارض ( إِذا حَضَرَ أَحَدَكُمُ الْمَوْتُ ) بأن رأى مقدماته من مرض وهرم ونحوهما ( إِنْ تَرَكَ خَيْراً ) أي مالا فإذا لم يترك الخير ، لا داعي للوصية وإن كانت مستحبة أيضا ، لكنها ليست مثل تأكيد من ترك الخير ( الْوَصِيَّةُ ) نائب فاعل « كتب » ( لِلْوالِدَيْنِ وَالْأَقْرَبِينَ ) أي الأقرباء ( بِالْمَعْرُوفِ ) بأن يوصي لوالديه وأقربائه ، ولو كانوا وراثا ، شيئا من الثلث ، وهذا يوجب نشر الألفة والمحبة أكثر فأكثر ، وإنما قيده بالمعروف ، حتى لا يوصي بما يوجب إثارة الشحناء ، كأن يترك الأقرب ، ويوصي للأبعد ، أو يفضل بعضا على بعض بما يورث البغضاء ، والمراد بالمعروف ، الذي يعرف أهل التميز ، إنه لا جور فيه ولا حيف ، وهذه الوصية تكون ( حَقًّا عَلَى الْمُتَّقِينَ ) الذين يؤثرون التقوى. فَمَنْ بَدَّلَهُ بَعْدَ ما سَمِعَهُ فَإِنَّما إِثْمُهُ عَلَى الَّذِينَ يُبَدِّلُونَهُ إِنَّ اللهَ سَمِيعٌ عَلِيمٌ (181) فَمَنْ خافَ مِنْ مُوصٍ جَنَفاً أَوْ إِثْماً فَأَصْلَحَ بَيْنَهُمْ"},{"text":"فَمَنۢ بَدَّلَهُۥ بَعْدَ مَا سَمِعَهُۥ فَإِنَّمَآ إِثْمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓ ۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ","tafsir":""},{"text":"فَمَنْ خَافَ مِن مُّوصٍ جَنَفًا أَوْ إِثْمًا فَأَصْلَحَ بَيْنَهُمْ فَلَآ إِثْمَ عَلَيْهِ ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ","tafsir":"أي بدل الإيصاء وغيّره وزوّره ( بَعْدَ ما سَمِعَهُ ) أي علمه ، فالسماع يستعمل بمعنى العلم ( فَإِنَّما إِثْمُهُ ) أي إثم التبديل ( عَلَى الَّذِينَ يُبَدِّلُونَهُ ) وليس إثم على الذي يأكل المال إرثا بغير علم ، والذي يأكله زيادة على حصته ، من غير علم فإن الغالب ، أن يبدل الجيل الأول ، ويتصرف سائر الأجيال ، بلا علم منهم بالتبديل ( إِنَّ اللهَ سَمِيعٌ ) لوصاياكم وأقوالكم ( عَلِيمٌ ) بنواياكم وتبديلكم ، أو تنفيذكم للوصية ، ولعل هناك نكتة أخرى في قوله ( فَإِنَّما إِثْمُهُ عَلَى الَّذِينَ يُبَدِّلُونَهُ ) هي أن كثيرا من الناس لا يوصون خوفا من أن يلحقهم إثم التبديل من بعدهم ، لأنهم بوصيتهم أعانوا من بدل ومهدوا الطريق له ، كما رأيت ذلك متعارفا في كلام كثير من الناس ، حيث يقولون من أوصى ألقى ورثته في المعصية ، فيكف بعضهم عن الوصية ، فأشار سبحانه إلى كون هذا الحكم غلطا ، فإن الموصي فعل خيرا ، وإنما المغير هو الذي يتحمل الإثم. [183] ثم استثنى سبحانه عن حرمة تبديل الوصية ، بأنه إنما يكون حراما ، إذا كان تغيرا من حق إلى باطل ، أما إذا كان من باطل إلى حق ، فلا إثم في التغيير ( فَمَنْ خافَ ) وخشي ( مِنْ مُوصٍ ) أي الذي يوصي ( جَنَفاً ) أي ميلا عن الحق إلى الباطل ، بأن أوصى أزيد مما يحق له الإيصاء به ( أَوْ إِثْماً ) بأن حرم ورثته بإيصائه ، وفي الحديث أن الإثم الخطأ عن عمد ، والجنف الخطأ لا عن عمد ( فَأَصْلَحَ بَيْنَهُمْ ) أي بين الورثة والموصي ، والموصى له ، بأن رد الزائد إلى الورثة ، وأبطل ما فَلا إِثْمَ عَلَيْهِ إِنَّ اللهَ غَفُورٌ رَحِيمٌ (182) يا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيامُ كَما كُتِبَ عَلَى الَّذِينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ (183) أَيَّاماً مَعْدُوداتٍ فَمَنْ كانَ مِنْكُمْ مَرِيضاً فيه الإثم ( فَلا إِثْمَ عَلَيْهِ ) أي على المبدل للوصية ( إِنَّ اللهَ غَفُورٌ رَحِيمٌ ) بمن يأثم ، فكيف بمن لا يأثم ، وقد ثبت في الشريعة إن الوصية بما زاد على الثلث لا تنفذ إلا برضى الورثة (1) . [184] ثم انتقل السياق إلى حكم آخر من أحكام الإسلام ـ لما ذكرنا من أن القرآن الحكيم ، بعد بيان أصول التوحيد ، ذكر جملة من الأحكام ـ فقال سبحانه ، ( يا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيامُ ) فإنه مفروض عليكم ، فيجب عليكم أن تصوموا ( كَما كُتِبَ عَلَى الَّذِينَ مِنْ قَبْلِكُمْ ) فلستم أنتم وحدكم أمرتم بالصيام ، بل كان الصوم شريعة في الأديان السابقة أيضا ( لَعَلَّكُمْ تَتَّقُونَ ) النار بصيامكم ، فالصائم حيث يحس بالجوع والعطش والضعف يتذكر الله سبحانه فيخبت قلبه وتضعف فيه قوى الشر ، وترق نفسه وتصفو روحه ، وكل ذلك سبب للتقوى وترك المعاصي."},{"text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ","tafsir":""},{"text":"أَيَّامًا مَّعْدُودَٰتٍ ۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ ۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدْيَةٌ طَعَامُ مِسْكِينٍ ۖ فَمَن تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَّهُۥ ۚ وَأَن تَصُومُوا۟ خَيْرٌ لَّكُمْ ۖ إِن كُنتُمْ تَعْلَمُونَ","tafsir":""},{"text":"شَهْرُ رَمَضَانَ ٱلَّذِىٓ أُنزِلَ فِيهِ ٱلْقُرْءَانُ هُدًى لِّلنَّاسِ وَبَيِّنَـٰتٍ مِّنَ ٱلْهُدَىٰ وَٱلْفُرْقَانِ ۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهْرَ فَلْيَصُمْهُ ۖ وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ ۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلْيُسْرَ وَلَا يُرِيدُ بِكُمُ ٱلْعُسْرَ وَلِتُكْمِلُوا۟ ٱلْعِدَّةَ وَلِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ","tafsir":"أي إن الصيام في أيام ( مَعْدُوداتٍ ) أي محصورات ، فليست أيام كثيرة لا تعد ، وإنما هي ثلاثون يوما فقط ـ وفيه تسلية للصائم ـ وليس الصيام على كل أحد ( فَمَنْ كانَ مِنْكُمْ مَرِيضاً ) مرضا ( 1) راجع موسوعة الفقه : ج 82 و 83. أَوْ عَلى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعامُ مِسْكِينٍ فَمَنْ تَطَوَّعَ خَيْراً فَهُوَ خَيْرٌ لَهُ وَأَنْ تَصُومُوا خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ (184) يضره الصوم ( أَوْ عَلى سَفَرٍ ) فقد شبه السفر بمركوب لغلبة الركوب فيه ، وحد السفر معين في الشريعة ( فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ ) أي فليصم في أيام أخر غير شهر رمضان ، قضاء لما فاته بالمرض أو السفر ( وَعَلَى الَّذِينَ يُطِيقُونَهُ ) أي يطيقون الصيام ، بأن يكون آخر طاقاتهم وذلك موجب للعسر ، كما لا يخفى ، إذ آخر الطاقة عسر ، أو أن الذي يطيق الصوم كان في أول الشريعة مخيرا بين الصيام والإطعام ، ثم وجب الصوم وحده ، وذلك للتدرج بالأمة ( فِدْيَةٌ ) أي الواجب عليهم الفداء بدل الصوم ( طَعامُ مِسْكِينٍ ) واحد وهو مد من الطعام ( فَمَنْ تَطَوَّعَ خَيْراً ) بأن زاد على طعام المسكين ( فَهُوَ خَيْرٌ لَهُ وَأَنْ تَصُومُوا ) أيها المطيقون ، الذي يبلغ الصوم طاقتكم ( خَيْرٌ لَكُمْ ) من الإطعام ، فالإنسان إما أن يضره الصوم ضررا بالغا ، وهو الذي تقدم أن يفطر ويأتي بعدة من أيام أخر ، وإما أن يشق عليه إلى حد العسر ، وهو الذي يبلغ منتهى طاقته ، وهذا يخير بين الصيام والإطعام وإن كان الصيام خير ، وإما أن لا يشق عليه وهو الذي يجب عليه الصيام معينا مما بين في الآية التالية ( إِنْ كُنْتُمْ تَعْلَمُونَ ) لعلمتم أن الصيام خير لما فيه من الفوائد التي ليست في الإطعام ، وليس مفهومه ، إن لم تكونوا تعلمون ، فليس الصوم خير ، بل المفهوم إن لم تكونوا تعلمون ، لم تعلموا إن الصوم خير. شَهْرُ رَمَضانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ هُدىً لِلنَّاسِ وَبَيِّناتٍ مِنَ الْهُدى وَالْفُرْقانِ فَمَنْ شَهِدَ مِنْكُمُ الشَّهْرَ فَلْيَصُمْهُ وَمَنْ كانَ مَرِيضاً أَوْ عَلى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ يُرِيدُ اللهُ بِكُمُ الْيُسْرَ وَلا يُرِيدُ بِكُمُ الْعُسْرَ وَلِتُكْمِلُوا الْعِدَّةَ وَلِتُكَبِّرُوا اللهَ عَلى [186] الأيام المعدودات المفروض فيها الصيام هي ( شَهْرُ رَمَضانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ ) مما زاد في عظمته وحرمته ، إذ صار زمانا للنزول أعظم دستور للبشرية إلى الأبد في حال كون القرآن ( هُدىً لِلنَّاسِ ) يهديهم إلى الحق وإلى صراط مستقيم ( وَبَيِّناتٍ ) أي أمور واضحات ( مِنَ ) جنس ( الْهُدى ) فليس هدى غامضا يحتاج إلى إثبات ودليل ، بل واضح لائح ، ومن الهدى بيان لبينات ، إذ يمكن أن يكون شيئا بينا من حيث الشهادة ، أو المعاملة أو نحوها ( وَ ) من ( الْفُرْقانِ ) أي يفرق بين الحق والباطل والضلال والرشاد ( فَمَنْ شَهِدَ ) أي حضر ولم يغب بالسفر ( مِنْكُمُ الشَّهْرَ ) أي شهر رمضان ( فَلْيَصُمْهُ ) إيجابا ، ولما كان الحكم عاما استثنى منه بقوله ( وَمَنْ كانَ مَرِيضاً أَوْ عَلى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ ) وإنما كرر تمهيدا لقوله ( يُرِيدُ اللهُ بِكُمُ الْيُسْرَ وَلا يُرِيدُ بِكُمُ الْعُسْرَ ) ولذا أمركم بالإفطار في السفر والمرض ( وَ ) إنما شرع عدة من أيام أخر ( لِتُكْمِلُوا الْعِدَّةَ ) أي عدة الشهر ، فإن في صيامه فوائد لا يدركها إلا من أكملها ، فإن لم يتمكن من إكمالها في نفس شهر رمضان أكملها خارجه ( وَ ) إنما شرع الصوم ( لِتُكَبِّرُوا اللهَ عَلى ما هَداكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ (185) وَإِذا سَأَلَكَ عِبادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذا دَعانِ فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي لَعَلَّهُمْ يَرْشُدُونَ (186) ما هَداكُمْ ) أي تعظموه بسبب هدايته لكم إلى دينه وشريعته ، فالصيام سبب قرب النفس إلى الله سبحانه ، فيأتي منها التكبير عفوا ، وفي التأويل ، المراد به تكبير ليلة الفطر ( وَلَعَلَّكُمْ تَشْكُرُونَ ) فالصوم نعمة تستحق الشكر لما فيه من صلاح الدنيا والدين. [187] وحيث أن من عادة القرآن الحكيم أن يخلل الأحكام نفحة موجهة نحو الله تعالى ، ليرتبط الحكم بالخالق ، وليشع في النفس النشاط والعزيمة ، أتت أية استجابة الدعاء هنا ، بعد طول من بيان الأحكام ، ثم يأتي بعدة آيات ترتبط بالأحكام ثانية ، بالإضافة إلى أن استجابة الدعاء تناسب شهر رمضان ، فإنه شهر دعاء وضراعة ، و قد ورد أن سائلا سأل النبي صلى‌الله‌عليه‌وآله‌وسلم كيف ندعوا ، فنزلت ( وَإِذا سَأَلَكَ عِبادِي عَنِّي فَإِنِّي قَرِيبٌ ) إليهم ، قرب العلم والإحاطة والسمع والبصر ، لا قرب الزمان والمكان والجهة ، فإنه سبحانه منزه عن كل ذلك ( أُجِيبُ دَعْوَةَ الدَّاعِ ) الذي يدعوني ( إِذا دَعانِ ) ولعل في هذا القيد إفادة أن الإجابة وقت الدعوة مباشرة فإن « إذا » ظرف ، ويفيد تكرار كلمة « دعا » لتتركز في الذهن تركيزا ( فَلْيَسْتَجِيبُوا لِي ) أي يطيعوني في أوامري ونواهي ، إذ من يجيب الدعاء ، يستحق أن يستجيب له الإنسان ( وَلْيُؤْمِنُوا بِي ) إيمانا بذاتي وصفاتي ( لَعَلَّهُمْ يَرْشُدُونَ ) أي لكي يصيبوا الحق ويهتدوا إليه. أُحِلَّ لَكُمْ لَيْلَةَ الصِّيامِ الرَّفَثُ إِلى نِسائِكُمْ هُنَّ لِباسٌ لَكُمْ وَأَنْتُمْ لِباسٌ لَهُنَّ عَلِمَ اللهُ أَنَّكُمْ كُنْتُمْ تَخْتانُونَ"},{"text":"وَإِذَا سَأَلَكَ عِبَادِى عَنِّى فَإِنِّى قَرِيبٌ ۖ أُجِيبُ دَعْوَةَ ٱلدَّاعِ إِذَا دَعَانِ ۖ فَلْيَسْتَجِيبُوا۟ لِى وَلْيُؤْمِنُوا۟ بِى لَعَلَّهُمْ يَرْشُدُونَ","tafsir":""},{"text":"أُحِلَّ لَكُمْ لَيْلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمْ ۚ هُنَّ لِبَاسٌ لَّكُمْ وَأَنتُمْ لِبَاسٌ لَّهُنَّ ۗ عَلِمَ ٱللَّهُ أَنَّكُمْ كُنتُمْ تَخْتَانُونَ أَنفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنكُمْ ۖ فَٱلْـَٔـٰنَ بَـٰشِرُوهُنَّ وَٱبْتَغُوا۟ مَا كَتَبَ ٱللَّهُ لَكُمْ ۚ وَكُلُوا۟ وَٱشْرَبُوا۟ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلْخَيْطُ ٱلْأَبْيَضُ مِنَ ٱلْخَيْطِ ٱلْأَسْوَدِ مِنَ ٱلْفَجْرِ ۖ ثُمَّ أَتِمُّوا۟ ٱلصِّيَامَ إِلَى ٱلَّيْلِ ۚ وَلَا تُبَـٰشِرُوهُنَّ وَأَنتُمْ عَـٰكِفُونَ فِى ٱلْمَسَـٰجِدِ ۗ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَقْرَبُوهَا ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَـٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَ","tafsir":""},{"text":"وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَـٰطِلِ وَتُدْلُوا۟ بِهَآ إِلَى ٱلْحُكَّامِ لِتَأْكُلُوا۟ فَرِيقًا مِّنْ أَمْوَٰلِ ٱلنَّاسِ بِٱلْإِثْمِ وَأَنتُمْ تَعْلَمُونَ","tafsir":"الطيبات أيها الصائمون ( لَيْلَةَ الصِّيامِ ) التي تصومون غدها ( الرَّفَثُ ) أي الجماع ( إِلى نِسائِكُمْ ) وإنما عدى ب « إلى » لتعليم معنى الإفضاء ، أي الانتهاء إلى زوجاتكم بالجماع. وقد روي عن الصادق عليه‌السلام في سبب نزول هذه الآية أنه قال : كان الأكل محرما في شهر رمضان بالليل بعد النوم ، وكان النكاح حراما بالليل والنهار في شهر رمضان ، وكان رجل من أصحاب رسول الله صلى‌الله‌عليه‌وآله‌وسلم يقال له مطعم بن جبير ، أخو عبد الله بن جبير الذي كان رسول الله صلى‌الله‌عليه‌وآله‌وسلم وكله بفم الشعب يوم أحد في خمسين من الرماة ، وفارقه أصحابه وبقي في أثنى عشر رجلا ، فقتل على باب الشعب ، وكان أخوه هذا مطعم بن جبير شيخا ضعيفا ، وكان صائما فأبطأت عليه أهله بالطعام ، فنام قبل أن يفطر ، فلما انتبه قال لأهله : قد حرم عليّ الأكل في هذه الليلة ، فلما أصبح حضر حفر الخندق فأغمي عليه ، فرآه رسول الله صلى‌الله‌عليه‌وآله‌وسلم فرق له ، وكان قوم من الشباب ينكحون بالليل سرا في شهر رمضان ، فأنزل الله هذه الآية ، فأحل النكاح بالليل في شهر رمضان والأكل بعد النوم إلى طلوع الفجر (1) . ( هُنَّ لِباسٌ لَكُمْ وَأَنْتُمْ لِباسٌ لَهُنَ ) فكما أن اللباس يقي البدن وكما أنه ملاصق بالبدن ومحرم عليه ، كذلك كل من الزوجين بالنسبة إلى الآخر ( عَلِمَ اللهُ أَنَّكُمْ ) أيها الصائمون ( كُنْتُمْ تَخْتانُونَ ) من الخيانة ( 1) عوالي اللآلي : ج 2 ص 82. أَنْفُسَكُمْ فَتابَ عَلَيْكُمْ وَعَفا عَنْكُمْ فَالْآنَ بَاشِرُوهُنَّ وَابْتَغُوا ما كَتَبَ اللهُ لَكُمْ وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ مِنَ الْفَجْرِ ثُمَّ أَتِمُّوا الصِّيامَ إِلَى اللَّيْلِ وَلا تُبَاشِرُوهُنَّ وَأَنْتُمْ عاكِفُونَ فِي الْمَساجِدِ تِلْكَ ( أَنْفُسَكُمْ ) أي كنتم تخونونها بارتكاب المعصية فكأن المرتكب لها يخونها إذ يسبب لها خسارة ، وكل خائن كذلك يسبب لمن خانه خسارة ( فَتابَ عَلَيْكُمْ ) ما كنتم تأتون به من المحرم في جماع أهليكم ليلا ( وَعَفا عَنْكُمْ ) بالنسبة إلى هذا الحكم فمن الآن ( بَاشِرُوهُنَ ) أي يجوز لكم جماعهن ليلا والأمر في مقام نفي لا يفيد إلا الجواز ( وَابْتَغُوا ما كَتَبَ اللهُ لَكُمْ ) من الأولاد واللذة المحللة الموجبة للثواب ، وهذا بالنسبة إلى نسخ الحكم بتحريم الجماع ( وَكُلُوا وَاشْرَبُوا ) أي يباح لكم الأكل والشرب من أول المغرب ( حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ مِنَ الْفَجْرِ ) بيان الخيطين أي يتضح الفجر الصادق الذي هو في وسط الظلام كخيط أبيض قرب خيط أسود ( ثُمَّ أَتِمُّوا الصِّيامَ ) بالكف عن المفطرات المذكورة في الشريعة ، من أول الفجر الصادق ( إِلَى اللَّيْلِ ) وهو المغرب الشرعي ، وهذا بالنسبة إلى نسخ الحكم بتحريم الأكل والشرب لمن نام قبل أن يفطر ( وَلا تُبَاشِرُوهُنَ ) أي لا تجامعوا النساء ( وَأَنْتُمْ عاكِفُونَ فِي الْمَساجِدِ ) ليلا أو نهارا والاعتكاف هو اللبث في المسجد بقصد العبادة ويشترط فيه الصوم ، وأقله ثلاثة أيام بتفصيل مذكور في الفقه ، ومن أحكام الاعتكاف حرمة مباشرة النساء ليلا ونهارا ( تِلْكَ ) التي ذكرنا من أحكام حُدُودُ اللهِ فَلا تَقْرَبُوها كَذلِكَ يُبَيِّنُ اللهُ آياتِهِ لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَ (187) وَلا تَأْكُلُوا أَمْوالَكُمْ بَيْنَكُمْ بِالْباطِلِ وَتُدْلُوا بِها إِلَى الْحُكَّامِ لِتَأْكُلُوا فَرِيقاً الصيام (1) وغيرها ( حُدُودُ اللهِ ) التي جعلها لأفعال العباد من الفعل فلا يجوز تركه ، والترك فلا يجوز إقحامه كحدود المدينة والدار ونحوهما ( فَلا تَقْرَبُوها ) نهى عن الاقتراب ، مبالغة في النهي عن الاقتحام والمخالفة كقوله تعالى ( وَلا تَقْرَبُوا مالَ الْيَتِيمِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ ) (2) ( كَذلِكَ ) أي مثل هذا البيان الواضح الذي بين أحكام الصيام وغيره ( يُبَيِّنُ اللهُ آياتِهِ ) دلائله وأحكامه ( لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَ ) أي لكي يتقوا معاصيه. [189] ثم انتقل السياق إلى تشريع آخر له مناسبة ما ب « الأكل » الذي دار الحديث حوله في مسألة الصيام ( وَلا تَأْكُلُوا أَمْوالَكُمْ بَيْنَكُمْ بِالْباطِلِ ) بالغصب وما أشبه ، وكان وجه ذكر كلمة « بينكم » أن الآكلين للغصب ونحوه يتآمرون بينهم في خفاء حتى يبرروا أكلهم ( وَتُدْلُوا ) الإدلاء أي الإلقاء والإفضاء أي تلقوا ( بِها ) أي بتلك الأموال ( إِلَى الْحُكَّامِ ) جمع حاكم ، بمعنى القضاة بعنوان الرشوة والهدية ليأخذوا جانبكم في أكل المال بالباطل ( لِتَأْكُلُوا ) علة لتدلوا أي علة إعطائكم الرشوة أن تأكلوا ( فَرِيقاً ) ( 1) راجع موسوعة الفقه : ج 37 ص 251. ( 2) الأنعام : 153. مِنْ أَمْوالِ النَّاسِ بِالْإِثْمِ وَأَنْتُمْ تَعْلَمُونَ (188) يَسْئَلُونَكَ عَنِ الْأَهِلَّةِ قُلْ هِيَ مَواقِيتُ لِلنَّاسِ وَالْحَجِّ أي قسما ( مِنْ أَمْوالِ النَّاسِ بِالْإِثْمِ ) بدون حق ( وَأَنْتُمْ تَعْلَمُونَ ) بأن أكلكم وإرشاءكم باطل وإثم. [190] مرت أحكام كلها تحتاج إلى التوقيت من صيام واعتكاف ومحاكمات وغيرها فناسب أن يأتي تشريع الأهلة هنا مع الغض عما تقدم من أن المقصود بيان جملة من الأحكام بعد بيان أصول التوحيد ( يَسْئَلُونَكَ ) يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( عَنِ الْأَهِلَّةِ ) وعن سبب اختلاف الهلال في كل شهر من الهلال إلى البدر ثم إلى الهلال حتى المحاق أو عن فائدة هذا الاختلاف ولماذا لم يكن القمر كالشمس في الانتظام ( قُلْ ) يا رسول الله في جوابهم ( هِيَ مَواقِيتُ ) جمع ميقات بمعنى الوقت والزمان ( لِلنَّاسِ ) في عباداتهم ومعاملاتهم ( وَ ) ل ( الْحَجِ ) فمن أقرض إلى شهر أو باع ليقبض الثمن ، أو يدفع الثمن بعد شهرين ، أو أراد الصيام والإفطار أو الحج في أشهره لا بد وأن يكون له معلم يستند إليه ولذلك جعل الله الأهلة ، وهذا الجواب ينطبق على السؤال بناء على الوجه الثاني في معنى « يسألونك » وأما بناء على الوجه الأول وسؤالهم كان عن سبب اختلاف الأهلة ، فإن القرآن أعرض عن جوابهم لأن عقولهم ما كانت تتحمل الجواب الفلكي ، ولذا عبر عن ذلك إلى فائدة الأهلة التي هم أحوج إليها ، كما في آية أخرى ( يَسْئَلُونَكَ ما ذا يُنْفِقُونَ قُلْ ما أَنْفَقْتُمْ مِنْ خَيْرٍ فَلِلْوالِدَيْنِ ) (1) حيث أعرض عن جواب ماهية ( 1) البقرة : 216. وَلَيْسَ الْبِرُّ بِأَنْ تَأْتُوا الْبُيُوتَ مِنْ ظُهُورِها وَلكِنَّ الْبِرَّ مَنِ اتَّقى وَأْتُوا الْبُيُوتَ مِنْ أَبْوابِها وَاتَّقُوا اللهَ لَعَلَّكُمْ تُفْلِحُونَ (189) وَقاتِلُوا فِي سَبِيلِ اللهِ الَّذِينَ يُقاتِلُونَكُمْ المنفق أي محل الإنفاق لأن هذا هو الذي يترتب عليه الفائدة وهم بحاجة إليه ، وحيث ذكر الحج في الكلام انتقل السياق إلى ما كان يفعله الجاهليون من أنهم إذا أحرموا لم يدخلوا البيوت من أبوابها وإنما يدخلونها من ظهورها ، فنهى عن ذلك ، وفي هذا تلميح بأن السؤال عما لا يهمكم من الأهلة ، مثل إتيان البيوت من ظهورها وكالأكل من القفا ( وَلَيْسَ الْبِرُّ بِأَنْ تَأْتُوا ) تدخلوا ( الْبُيُوتَ مِنْ ظُهُورِها ) بأن تنقبوا البيوت وتدخلونها من النقب ( وَلكِنَّ الْبِرَّ مَنِ اتَّقى ) من الله سبحانه بإتيان أوامره واجتناب نواهيه ( وَأْتُوا الْبُيُوتَ مِنْ أَبْوابِها ) ولو في حال الإحرام ( وَاتَّقُوا اللهَ ) في أوامره ونواهيه ( لَعَلَّكُمْ تُفْلِحُونَ ) أي لكي تفلحوا بالوصول إلى السعادة الدنيوية والأخروية. [191] وهنا حكم آخر من أحكام الإسلام الكثيرة وهو القتال والجهاد ، ولقد كان بين هذا الحكم وبين « الحج » المتقدم مناسبة ، إذ المشركون قد منعوا الرسول صلى‌الله‌عليه‌وآله‌وسلم عن الحج عام الحديبية ، فكان على المسلمين أن يستعدوا للجهاد إن اقتضت الظروف ( وَقاتِلُوا ) أيها المسلمون ( فِي سَبِيلِ اللهِ ) لا لحب السيطرة والغلبة كما هو شأن ملوك الدنيا وزعمائها بل في سبيل إعلاء كلمة الله التي فيها سعادة البشر ( الَّذِينَ يُقاتِلُونَكُمْ ) وَلا تَعْتَدُوا إِنَّ اللهَ لا يُحِبُّ الْمُعْتَدِينَ (190) وَاقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأَخْرِجُوهُمْ مِنْ حَيْثُ أَخْرَجُوكُمْ وَالْفِتْنَةُ أَشَدُّ مِنَ الْقَتْلِ وَلا تُقاتِلُوهُمْ لا كل آمن ، فمن ألقى سلاحه ، وسكن إلى محله ، فإن في قتاله إيجاد فوضى واضطراب لا داعي إليهما ( وَلا تَعْتَدُوا ) إذا قاتلتم من قاتلكم فإن القتال قتال دفاع ، فلا معنى للاعتداء وأنتم مرتبطون بالله الذي تقاتلون لأجله فلا يصح الاعتداء من أمثالكم ( إِنَّ اللهَ لا يُحِبُّ الْمُعْتَدِينَ ) فهو الذي يأمر بالعدل والإحسان ، فكيف يحب من اعتدى وبغى ؟."},{"text":"۞ يَسْـَٔلُونَكَ عَنِ ٱلْأَهِلَّةِ ۖ قُلْ هِىَ مَوَٰقِيتُ لِلنَّاسِ وَٱلْحَجِّ ۗ وَلَيْسَ ٱلْبِرُّ بِأَن تَأْتُوا۟ ٱلْبُيُوتَ مِن ظُهُورِهَا وَلَـٰكِنَّ ٱلْبِرَّ مَنِ ٱتَّقَىٰ ۗ وَأْتُوا۟ ٱلْبُيُوتَ مِنْ أَبْوَٰبِهَا ۚ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ","tafsir":""},{"text":"وَقَـٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَـٰتِلُونَكُمْ وَلَا تَعْتَدُوٓا۟ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ","tafsir":""},{"text":"وَٱقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأَخْرِجُوهُم مِّنْ حَيْثُ أَخْرَجُوكُمْ ۚ وَٱلْفِتْنَةُ أَشَدُّ مِنَ ٱلْقَتْلِ ۚ وَلَا تُقَـٰتِلُوهُمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ حَتَّىٰ يُقَـٰتِلُوكُمْ فِيهِ ۖ فَإِن قَـٰتَلُوكُمْ فَٱقْتُلُوهُمْ ۗ كَذَٰلِكَ جَزَآءُ ٱلْكَـٰفِرِينَ","tafsir":""},{"text":"فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ","tafsir":"أي الذين يقاتلونكم ( حَيْثُ ثَقِفْتُمُوهُمْ ) أي وجدتموهم ( وَأَخْرِجُوهُمْ مِنْ حَيْثُ أَخْرَجُوكُمْ ) أي أخرجوهم من مكة كما أخرجوكم منها ، فمن قاتلكم قتلتموه ومن أخرجكم من دياركم أخرجتموه جزاء وفاقا ( وَالْفِتْنَةُ ) التي أثارها الكفار بتفتين المسلمين عن دينهم وإلقاء الارتياب والشك في قلوبهم ليجلبوهم إلى حظيرة الكفر بعد أن هداهم الله ( أَشَدُّ مِنَ الْقَتْلِ ) فالقتل يوجب ذهاب الدنيا والفتنة توجب ذهاب الدين ، فمن تقاتلونهم لا يستحقون عليكم أن يهرجوا بأن المسلمين يشهرون السلاح فإنهم يستحقون القتل لأنهم بدأوا بالقتال لأنهم فتنوا ، و روي أنها نزلت في مسلم قتل كافرا في الشهر الحرام فعابوا المؤمنين بذلك (1) ، فبين سبحانه أن الفتنة التي تصدر من الكفار أشد من القتل ( وَلا تُقاتِلُوهُمْ ) أي لا تقاتلوا ( 1) مجمع البيان : ج 2 ص 30. عِنْدَ الْمَسْجِدِ الْحَرامِ حَتَّى يُقاتِلُوكُمْ فِيهِ فَإِنْ قاتَلُوكُمْ فَاقْتُلُوهُمْ كَذلِكَ جَزاءُ الْكافِرِينَ (191) فَإِنِ انْتَهَوْا فَإِنَّ اللهَ غَفُورٌ رَحِيمٌ (192) وَقاتِلُوهُمْ حَتَّى لا تَكُونَ فِتْنَةٌ وَيَكُونَ الدِّينُ لِلَّهِ فَإِنِ انْتَهَوْا فَلا عُدْوانَ إِلاَّ عَلَى الظَّالِمِينَ (193) الكافرين أيها المسلمون ( عِنْدَ الْمَسْجِدِ الْحَرامِ ) أي في الحرم ( حَتَّى يُقاتِلُوكُمْ فِيهِ ) ويبدءوا بالقتال ( فَإِنْ قاتَلُوكُمْ ) بدءوكم بالقتال في الحرم ( فَاقْتُلُوهُمْ ) هناك ( كَذلِكَ ) الذي مر من وجوب قتال الكفار حيث وجدوا إلى آخر ما ذكر ( جَزاءُ الْكافِرِينَ )"},{"text":"وَقَـٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ ٱلدِّينُ لِلَّهِ ۖ فَإِنِ ٱنتَهَوْا۟ فَلَا عُدْوَٰنَ إِلَّا عَلَى ٱلظَّـٰلِمِينَ","tafsir":"عن الكفر بأن أسلموا ( فَإِنَّ اللهَ غَفُورٌ ) يغفر سيئاتهم حتى التي ارتكبوها قبل إسلامهم من القتال فالإسلام يجب ما قبله ( رَحِيمٌ ) بعباده المؤمنين."},{"text":"ٱلشَّهْرُ ٱلْحَرَامُ بِٱلشَّهْرِ ٱلْحَرَامِ وَٱلْحُرُمَـٰتُ قِصَاصٌ ۚ فَمَنِ ٱعْتَدَىٰ عَلَيْكُمْ فَٱعْتَدُوا۟ عَلَيْهِ بِمِثْلِ مَا ٱعْتَدَىٰ عَلَيْكُمْ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ","tafsir":"أي الكفار الذين يقاتلوكم لا لأجل القصاص فقط بل ( حَتَّى لا تَكُونَ فِتْنَةٌ ) بأن لا يفتن المسلمون عن دينهم ( وَيَكُونَ الدِّينُ ) والطريقة ( لِلَّهِ ) فلا يبقى منهج لسواه بأن ينتصر الحق على الباطل وهذان هما الغاية من إيجاب الدفاع ( فَإِنِ انْتَهَوْا ) عن الكفر ( فَلا عُدْوانَ ) أي تعدي بالدفاع والقتال ( إِلَّا عَلَى الظَّالِمِينَ ) الباقين على كفرهم ، أي إذا انتهى المعتدون عن الفتنة والتعرض لدين الله والتعرض للمسلمين بالأذى والقتال فلا قتال معهم لأن القتال لا يكون إلا مع الظالمين ، وسمي « عدوانا » تشبيها كما قال سبحانه في الآية المقبلة : ( فَمَنِ اعْتَدى عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ بِمِثْلِ مَا اعْتَدى عَلَيْكُمْ ) . الشَّهْرُ الْحَرامُ بِالشَّهْرِ الْحَرامِ وَالْحُرُماتُ قِصاصٌ فَمَنِ اعْتَدى عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ بِمِثْلِ مَا اعْتَدى عَلَيْكُمْ وَاتَّقُوا اللهَ وَاعْلَمُوا أَنَّ اللهَ مَعَ الْمُتَّقِينَ (194) وَأَنْفِقُوا فِي سَبِيلِ اللهِ وَلا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ وَأَحْسِنُوا إِنَّ اللهَ يُحِبُّ الْمُحْسِنِينَ (195)"},{"text":"وَأَنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلَا تُلْقُوا۟ بِأَيْدِيكُمْ إِلَى ٱلتَّهْلُكَةِ ۛ وَأَحْسِنُوٓا۟ ۛ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ","tafsir":"وهو ذو القعدة وذو الحجة والمحرم ورجب سميت هذه الأشهر حراما لتحريم القتال فيها ( بِالشَّهْرِ الْحَرامِ ) أي بمقابل الشهر الحرام فمن انتهك حرمة الشهر الحرام بالقتال فيه لم يحرم قتاله بل يقاتل ( وَالْحُرُماتُ قِصاصٌ ) كما أن الجروح قصاص فمن انتهك حرمة اقتص منه في نفس الشهر أو المكان الذي انتهكت حرمته ولذا يحارب المحارب في الحرم وفي الشهر الحرام ( فَمَنِ اعْتَدى عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ بِمِثْلِ مَا اعْتَدى عَلَيْكُمْ ) لا أزيد من ذلك وسمي اعتداء لأنه مثل الاعتداء فالتسمية إنما هي بالمجانسة ( وَاتَّقُوا اللهَ ) فلا تتجاوزوا الحدود ولا تبالغوا في القسوة والانتقام ( وَاعْلَمُوا أَنَّ اللهَ مَعَ الْمُتَّقِينَ ) فيأخذ بأيديهم في الدنيا ويسعدهم في الآخرة."},{"text":"وَأَتِمُّوا۟ ٱلْحَجَّ وَٱلْعُمْرَةَ لِلَّهِ ۚ فَإِنْ أُحْصِرْتُمْ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ ۖ وَلَا تَحْلِقُوا۟ رُءُوسَكُمْ حَتَّىٰ يَبْلُغَ ٱلْهَدْىُ مَحِلَّهُۥ ۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ بِهِۦٓ أَذًى مِّن رَّأْسِهِۦ فَفِدْيَةٌ مِّن صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ ۚ فَإِذَآ أَمِنتُمْ فَمَن تَمَتَّعَ بِٱلْعُمْرَةِ إِلَى ٱلْحَجِّ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ ۚ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَـٰثَةِ أَيَّامٍ فِى ٱلْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ ۗ تِلْكَ عَشَرَةٌ كَامِلَةٌ ۗ ذَٰلِكَ لِمَن لَّمْ يَكُنْ أَهْلُهُۥ حَاضِرِى ٱلْمَسْجِدِ ٱلْحَرَامِ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ","tafsir":"فإن الجهاد يحتاج إلى الإنفاق في تجهيز الجيش وهو من أعظم السبل ( وَلا تُلْقُوا بِأَيْدِيكُمْ ) أي لا تلقوا أنفسكم بأيديكم ( إِلَى التَّهْلُكَةِ ) بترك الإنفاق للجهاد حتى يتسلط عليكم العدو ( وَأَحْسِنُوا ) في إنفاقكم وجهادكم وسائر أموركم ( إِنَّ اللهَ يُحِبُّ الْمُحْسِنِينَ ) . [197] ثم يرجع السياق إلى أحكام الحج الذي ألمح إليه فيما سبق ، لأن وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ وَلا تَحْلِقُوا رُؤُسَكُمْ حَتَّى يَبْلُغَ الْهَدْيُ مَحِلَّهُ فَمَنْ كانَ مِنْكُمْ مَرِيضاً أَوْ بِهِ أَذىً مِنْ رَأْسِهِ فَفِدْيَةٌ مِنْ صِيامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ فَإِذا أَمِنْتُمْ فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ الحج كان في مقام صلح الحديبية وحج النبي صلى‌الله‌عليه‌وآله‌وسلم ( وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ ) أي ائتوا بها تماما وكاملا بإتيان مناسكهما قربة إلى الله تعالى لا لأجل رياء أو سمعة أو نحوهما ( فَإِنْ أُحْصِرْتُمْ ) بأن منعكم مانع عن الحج بعد ما أحرمتم فعليكم إذا أردتم التحلل عن الإحرام أن تقدموا أو تذبحوا ما ( اسْتَيْسَرَ ) أي ما أمكنكم ( مِنَ الْهَدْيِ ) الذي قدمتموه إلى الله ، والهدي هو البقر أو الإبل أو الغنم ( وَلا تَحْلِقُوا رُؤُسَكُمْ ) وهو كناية عن التحلل عن الأجسام أي لا تحلقوا ( حَتَّى يَبْلُغَ الْهَدْيُ مَحِلَّهُ ) الذي قرر في الشريعة من محل الحصى أو مكة أو منى كما فصل في الفقه ( فَمَنْ كانَ مِنْكُمْ مَرِيضاً ) لا يتمكن من أن لا يحلق ( أَوْ بِهِ أَذىً مِنْ رَأْسِهِ ) كأن قمل رأسه فيتأذى من هوائه فلا يتمكن من عدم الحلق فعليه إذا حلق قبل أن يبلغ الهدي محله فدية يقدمها بدل حلقه ( مِنْ صِيامٍ ) ثلاثة أيام ( أَوْ صَدَقَةٍ ) لستة مساكين ( أَوْ نُسُكٍ ) أي شاة يذبحها لأجل تعجيله في الحلق ( فَإِذا أَمِنْتُمْ ) من العدو الصاد وكذلك شفيتم من المرض وزال المانع ( فَمَنْ تَمَتَّعَ ) أي استمتع بالطيب والنساء وسائر الملذات التي يحرمها الإحرام بسبب إتيانه ( الْعُمْرَةَ ) فإن العمرة تنتهي سريعا فتحل المحرمات ( إِلَى الْحَجِ ) أي يكون تمتعه بالملذات إلى أن يحرم فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ فَمَنْ لَمْ يَجِدْ فَصِيامُ ثَلاثَةِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ إِذا رَجَعْتُمْ تِلْكَ عَشَرَةٌ كامِلَةٌ ذلِكَ لِمَنْ لَمْ يَكُنْ أَهْلُهُ حاضِرِي الْمَسْجِدِ الْحَرامِ وَاتَّقُوا اللهَ وَاعْلَمُوا أَنَّ اللهَ شَدِيدُ الْعِقابِ (196) للحج فعليه ما ( اسْتَيْسَرَ ) أي ما تمكن عليه ( مِنَ الْهَدْيِ ) إبل أو بقر أو شاة يجب عليه ذبحها في منى أيام العيد ( فَمَنْ لَمْ يَجِدْ ) الهدي فعليه صيام ( ثَلاثَةِ أَيَّامٍ فِي ) أيام ( الْحَجَ ) من ذي الحجة ( وَسَبْعَةٍ ) أيام ( إِذا رَجَعْتُمْ ) إلى بلادكم ( تِلْكَ عَشَرَةٌ كامِلَةٌ ) تكون بدلا عن الهدي ( ذلِكَ ) التمتع الذي يكون عمرته مقدمة على حجه فرض ( لِمَنْ لَمْ يَكُنْ أَهْلُهُ حاضِرِي الْمَسْجِدِ الْحَرامِ ) من كان في أطراف الحرم من كل جانب أثني عشر ميلا أو نحوه على خلاف ، أما من كان أهله حاضري المسجد الحرام بأن كان محله عند أقل من ذلك ففرضه القرآن أو الإفراد وفي كليهما يقدم الحج على العمرة ، والفرق بينهما أن القارن يعقد إحرامه بسوق الهدي دون المفرد ( وَاتَّقُوا اللهَ ) في أحكامه أيها المسلمون ( وَاعْلَمُوا أَنَّ اللهَ شَدِيدُ الْعِقابِ ) فلا تخالفوا أوامره ونواهيه. والحج يشتمل على فرضين : ( عمرة ) هي : « الإحرام والتلبية » ، « والطواف بالبيت » ، « صلاة الطواف » ، « والسعي بين الصفا والمروة » ، « والتقصير » . و ( حج ) هو : « الإحرام » ، « والوقوف بعرفات » ، « الوقوف بالمشعر » ، « الإفاضة إلى منى » ، « رمي جمرة العقبة » ، « نحر أو ذبح » ، « حلق أو تقصير » ، طواف الحج وصلاته وسعي وتقصير وطواف النساء وصلاته « طواف النساء » ، « صلاة طواف النساء » ، « السعي بين الصفا والمروة » ، « طواف الْحَجُّ أَشْهُرٌ مَعْلُوماتٌ الزيارة » ، « صلاة طواف الزيارة » ، « المبيت بمنى ليلة الحادي عشر والثاني عشر » ، « رمي الجمار الثلاث يومي الحادي عشر والثاني عشر » ، وقد أشار الشيخ البهائي إلى هذه الأعمال في بيته المشهور أطرست للعمرة اجعل نهج أو وأرنحط رسطر مر : لحج (1)"},{"text":"ٱلْحَجُّ أَشْهُرٌ مَّعْلُومَـٰتٌ ۚ فَمَن فَرَضَ فِيهِنَّ ٱلْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِى ٱلْحَجِّ ۗ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ يَعْلَمْهُ ٱللَّهُ ۗ وَتَزَوَّدُوا۟ فَإِنَّ خَيْرَ ٱلزَّادِ ٱلتَّقْوَىٰ ۚ وَٱتَّقُونِ يَـٰٓأُو۟لِى ٱلْأَلْبَـٰبِ","tafsir":""},{"text":"لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَبْتَغُوا۟ فَضْلًا مِّن رَّبِّكُمْ ۚ فَإِذَآ أَفَضْتُم مِّنْ عَرَفَـٰتٍ فَٱذْكُرُوا۟ ٱللَّهَ عِندَ ٱلْمَشْعَرِ ٱلْحَرَامِ ۖ وَٱذْكُرُوهُ كَمَا هَدَىٰكُمْ وَإِن كُنتُم مِّن قَبْلِهِۦ لَمِنَ ٱلضَّآلِّينَ","tafsir":"في ( أَشْهُرٌ مَعْلُوماتٌ ) أو أشهر الحج أشهر معلومات وهو شوال وذو القعدة وذو الحجة فلا يجوز تأخيره منها كما كان الجاهلون ( 1) الالف : الإحرام لعمرة التمتّع عن حجّة الإسلام. الطاء : طواف العمرة. الراء : ركعتان صلوات طواف لعمرة التمتّع. السين : السعي بين الصّفا والمروة عن عمرة التمتع. التاء : التقصير عن عمرة التمتع لحجّة الإسلام فهناك اعمال العمرة لحجّ التمتع. الألف : الإحرام لحجّ التمتّع. الواو الأول : الوقوف بعرفات في 9 من ذيحجة لحجّ التمتّع. الواو الثاني : الوقوف في مشعر الحرام ليلة العيد الى الصبح لحج التمتع. الالف : الإفاضة إلى منى يوم العيد. الراء : رمي جمرة للعقبة في يوم العيد لحج التمتّع. النون : نحر إبل أو ذبيحة لحج التمتّع. الحاء : الحلق في يوم العيد لحج التمتّع. الطاء : الطواف عن حجّة الإسلام. الراء : رمي الجمرات الثلاثة في يوم الحادي عشر من ذي حجة عن حج التمتّع. السين : السعي بين الصفا والمروة لحج التمتّع. الطاء : طواف النساء. الراء : رمي الجمرات الثلاثة في يوم الثاني عشر من ذي حجة عن حج التمتّع. الميم : المبيت في منى ثلاثة ليال عن حج التمتّع. ولا يخفى أنّ جملة ( مر لحج ) التي أتى بها البهائي ( رحمه‌الله ) تكون لتكملة الشعر فلا تدخل فيما أردناها من المناسك. فَمَن فَرَضَ فِيهِنَّ الْحَجَّ فَلاَ رَفَثَ وَلاَ فُسُوقَ وَلاَ جِدَالَ فِي الْحَجِّ وَمَا تَفْعَلُواْ مِنْ خَيْرٍ يَعْلَمْهُ اللّهُ وَتَزَوَّدُواْ فَإِنَّ خَيْرَ الزَّادِ التَّقْوَى وَاتَّقُونِ يَا أُوْلِي الأَلْبَابِ (197) لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن يفعلون حيث يؤخرون الحج ، ونزل فيهم ( إِنَّمَا النَّسِيءُ زِيادَةٌ فِي الْكُفْرِ ) (1) ( فَمَنْ فَرَضَ ) على نفسه ( فِيهِنَ ) أي في هذه الأشهر ( الْحَجُ ) فليعلم أنه لا ( رَفَثَ ) وهو الجماع ( وَلا فُسُوقَ ) وهو السباب والمفاخرة ( وَلا جِدالَ ) قول لا والله وبلى والله ( فِي الْحَجِ ) أي في حال الإحرام ( وَما تَفْعَلُوا مِنْ خَيْرٍ ) في الحج وغيره ( يَعْلَمْهُ اللهُ ) ولعل ذكره هنا لكثرة احتياج الحجاج بعضهم إلى بعض في مختلف الشؤون فأريد التنبيه بأن كل خير يصدر من الإنسان إنما هو بعلم الله سبحانه فيجازيه على ذلك ( وَتَزَوَّدُوا ) من الحج زادا للروح ( فَإِنَّ خَيْرَ الزَّادِ التَّقْوى ) وهو يحصل بكثرة هائلة في الحج حيث التجرد والكف عن الملذات ومقامات الشدائد والصعوبات ، ويحتمل أنها نزلت فيمن لم يكن يأخذ الزاد للحج بادعاء أنه ضيف الله ثم ليستعطي في الطريق فأمر بأخذ الزاد فإنه قرين بالتقوى دون الاستعطاء الذي فيه منقصة وذلة وحرمة أحيانا ( وَاتَّقُونِ ) أي خافوني في أعمالكم فلا تغفلوا ولا تتركوا واجبا ( يا أُولِي الْأَلْبابِ ) أي يا أصحاب العقول. [199] كانوا يتأثمون بالتجارة في الحج فنزلت ( لَيْسَ عَلَيْكُمْ جُناحٌ أَنْ ( 1) التوبة : 37. تَبْتَغُواْ فَضْلاً مِّن رَّبِّكُمْ فَإِذَا أَفَضْتُم مِّنْ عَرَفَاتٍ فَاذْكُرُواْ اللّهَ عِندَ الْمَشْعَرِ الْحَرَامِ وَاذْكُرُوهُ كَمَا هَدَاكُمْ وَإِن كُنتُم مِّن قَبْلِهِ لَمِنَ الضَّآلِّينَ (198) ثُمَّ أَفِيضُواْ مِنْ حَيْثُ أَفَاضَ النَّاسُ وَاسْتَغْفِرُواْ اللّهَ إِنَّ اللّهَ غَفُورٌ رَّحِيمٌ (199) فَإِذَا قَضَيْتُم مَّنَاسِكَكُمْ تَبْتَغُوا فَضْلاً مِنْ رَبِّكُمْ ) بالاتجار فإنه ليس بمحرم ( فَإِذا أَفَضْتُمْ ) منها كما يندفع الماء نحو الوهاد فإن الحجاج يندفعون كالسيل ( مِنْ عَرَفاتٍ فَاذْكُرُوا اللهَ عِنْدَ الْمَشْعَرِ الْحَرامِ ) وهو الموقف الثاني ووقته بين طلوع الفجر وطلوع الشمس من يوم العيد ( وَاذْكُرُوهُ كَما هَداكُمْ ) أي بإزاء هدايته سبحانه إياكم لدينه وما يسعدكم في الدنيا والآخرة ( وَإِنْ كُنْتُمْ مِنْ قَبْلِهِ ) أي قبل الهدي ( لَمِنَ الضَّالِّينَ ) عن دينه."},{"text":"ثُمَّ أَفِيضُوا۟ مِنْ حَيْثُ أَفَاضَ ٱلنَّاسُ وَٱسْتَغْفِرُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ","tafsir":""},{"text":"فَإِذَا قَضَيْتُم مَّنَـٰسِكَكُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَذِكْرِكُمْ ءَابَآءَكُمْ أَوْ أَشَدَّ ذِكْرًا ۗ فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا وَمَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِنْ خَلَـٰقٍ","tafsir":"من المشعر إلى منى ( مِنْ حَيْثُ أَفاضَ النَّاسُ ) من قبلكم إبراهيم عليه‌السلام وذريته ( وَاسْتَغْفِرُوا اللهَ ) اطلبوا غفرانه وعفوه ( إِنَّ اللهَ غَفُورٌ رَحِيمٌ ) هكذا يقتضي نظم الآية ، لكن ورد أن قريشا لا يقفون بعرفات ولا يفيضون منه ويقولون نحن أهل حرم الله فلا نخرج منه فيقفون بالمشعر ويفيضون منه ، فأمرهم الله أن يقفوا بعرفات ويفيضوا منه كسائر الناس."},{"text":"وَمِنْهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا حَسَنَةً وَفِى ٱلْـَٔاخِرَةِ حَسَنَةً وَقِنَا عَذَابَ ٱلنَّارِ","tafsir":"أي أديتم أعمالكم فالمناسك جمع منسك فَاذْكُرُواْ اللّهَ كَذِكْرِكُمْ آبَاءكُمْ أَوْ أَشَدَّ ذِكْرًا فَمِنَ النَّاسِ مَن يَقُولُ رَبَّنَا آتِنَا فِي الدُّنْيَا وَمَا لَهُ فِي الآخِرَةِ مِنْ خَلاَقٍ (200) وِمِنْهُم مَّن يَقُولُ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ (201) أُولَـئِكَ لَهُمْ نَصِيبٌ مِّمَّا كَسَبُواْ وهو مصدر ميمي بمعنى العمل ( فَاذْكُرُوا اللهَ كَذِكْرِكُمْ آباءَكُمْ أَوْ أَشَدَّ ذِكْراً ) فإن أهل الجاهلية كانوا إذا فرغوا من الحج يجتمعون هناك ويعدون مفاخر آبائهم ومآثرهم ويذكرون أيامهم القديمة وأياديهم الجسيمة فأمرهم الله أن يذكروه عوض ذكرهم آبائهم ، بل يجب أن يذكروه أكثر وأحسن من ذكر آبائهم فهو المنعم الحقيقي الذي بيده كل شيء ومنه كل خير ، وهنا يكون المجال واسعا لبيان نموذجين من الناس منهم من يريد الآخرة ومنهم من يريد الدنيا ولذا قال تعالى : ( فَمِنَ النَّاسِ مَنْ يَقُولُ رَبَّنا آتِنا فِي الدُّنْيا ) أي أعطنا من نعيمها ورفاهها وسعادتها ولا يسأل نعيم الآخرة لأنه غير مؤمن بها إذ كان الحج قبل الإسلام عامّا للمعتقد والمنكر ( وَما لَهُ فِي الْآخِرَةِ مِنْ خَلاقٍ ) أي نصيب."},{"text":"أُو۟لَـٰٓئِكَ لَهُمْ نَصِيبٌ مِّمَّا كَسَبُوا۟ ۚ وَٱللَّهُ سَرِيعُ ٱلْحِسَابِ","tafsir":"أي من الناس ( مَنْ يَقُولُ رَبَّنا آتِنا فِي الدُّنْيا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنا ) من وقى يقي أي احفظنا من ( عَذابَ النَّارِ ) فهو يسأل نعيم الدنيا ونعيم الآخرة ويتعوذ بالله من النار."},{"text":"۞ وَٱذْكُرُوا۟ ٱللَّهَ فِىٓ أَيَّامٍ مَّعْدُودَٰتٍ ۚ فَمَن تَعَجَّلَ فِى يَوْمَيْنِ فَلَآ إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلَآ إِثْمَ عَلَيْهِ ۚ لِمَنِ ٱتَّقَىٰ ۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُمْ إِلَيْهِ تُحْشَرُونَ","tafsir":"يسألون خير الدنيا والآخرة ( لَهُمْ نَصِيبٌ مِمَّا كَسَبُوا ) لأنهم يستحقون ثواب أعمالهم بخلاف الطائفة الأولى فإن كفرهم يمنع وَاللّهُ سَرِيعُ الْحِسَابِ (202) وَاذْكُرُواْ اللّهَ فِي أَيَّامٍ مَّعْدُودَاتٍ فَمَن تَعَجَّلَ فِي يَوْمَيْنِ فَلاَ إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلا إِثْمَ عَلَيْهِ لِمَنِ اتَّقَى وَاتَّقُواْ اللّهَ وَاعْلَمُوا أَنَّكُمْ إِلَيْهِ تُحْشَرُونَ (203) وَمِنَ النَّاسِ مَن يُعْجِبُكَ قَوْلُهُ فِي الْحَيَاةِ الدُّنْيَا عن ثوابهم ( وَاللهُ سَرِيعُ الْحِسابِ ) فلا يظن الإنسان أن الآخرة بعيدة فإنه لا تمر الأيام والليالي إلا والشخص دفين في التراب وإن طال عمره في الدنيا."},{"text":"وَمِنَ ٱلنَّاسِ مَن يُعْجِبُكَ قَوْلُهُۥ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيُشْهِدُ ٱللَّهَ عَلَىٰ مَا فِى قَلْبِهِۦ وَهُوَ أَلَدُّ ٱلْخِصَامِ","tafsir":"أيها الحجاج ( فِي أَيَّامٍ مَعْدُوداتٍ ) وهي أيام التشريق في منى ( فَمَنْ تَعَجَّلَ ) النفر إلى مكة من منى ( فِي يَوْمَيْنِ ) بأن نفر يوم الثاني عشر ( فَلا إِثْمَ عَلَيْهِ ) فإنه يجوز النفر بعد زوال الثاني عشر ( وَمَنْ تَأَخَّرَ ) في النفر فنفر في الثالث عشر ( فَلا إِثْمَ عَلَيْهِ ) فيجوز كل من الأمرين ( لِمَنِ اتَّقى ) الصيد في إحرامه وإلا فإن صاد وجب عليه النفر الثاني فلا يجوز أن ينفر في الثاني عشر ( وَاتَّقُوا اللهَ ) فيما أمركم ونهاكم ( وَاعْلَمُوا أَنَّكُمْ إِلَيْهِ تُحْشَرُونَ ) الحشر هو الجمع والمعنى تجمعون إلى حكم الله وجزائه يوم القيامة. [205] ثم يلتفت السياق إلى الإنسان طالحه وصالحه ، ويبين خصائص البشر ، ليعطي درسا لمن أراد الصلاح والرشاد فيقول سبحانه : ( وَمِنَ النَّاسِ مَنْ يُعْجِبُكَ قَوْلُهُ ) للباقته وفصاحته وكلامه المعسول فتستحسن كلامه وتصغي إلى بيانه ( فِي الْحَياةِ الدُّنْيا ) أما متعلق ب « قوله » ، أي وَيُشْهِدُ اللّهَ عَلَى مَا فِي قَلْبِهِ وَهُوَ أَلَدُّ الْخِصَامِ (204) وَإِذَا تَوَلَّى سَعَى فِي الأَرْضِ لِيُفْسِدَ فِيِهَا وَيُهْلِكَ الْحَرْثَ وَالنَّسْلَ وَاللّهُ لاَ يُحِبُّ الفَسَادَ (205) وَإِذَا قِيلَ لَهُ اتَّقِ اللّهَ أَخَذَتْهُ الْعِزَّةُ بِالإِثْمِ فَحَسْبُهُ جَهَنَّمُ وَلَبِئْسَ الْمِهَادُ (206) قوله في شؤون الدنيا معجب ، أو متعلق ب « يعجبك » أي أن إعجابك إنما هو في الدنيا ، والأول أقرب ( وَيُشْهِدُ اللهَ عَلى ما فِي قَلْبِهِ ) كما هو شأن المنافقين أبدا فإنهم حيث يرون نفاقهم يظنون أن الناس مطلعون على سرائرهم فيؤكدون بأنهم مخلصون وأن ما في قلبهم يطابق ما على لسانهم ( وَهُوَ أَلَدُّ الْخِصامِ ) الألد هو شديد الخصومة والخصام جمع يعني أنه من أكبر خصمائك في الباطن."},{"text":"وَإِذَا تَوَلَّىٰ سَعَىٰ فِى ٱلْأَرْضِ لِيُفْسِدَ فِيهَا وَيُهْلِكَ ٱلْحَرْثَ وَٱلنَّسْلَ ۗ وَٱللَّهُ لَا يُحِبُّ ٱلْفَسَادَ","tafsir":""},{"text":"وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتْهُ ٱلْعِزَّةُ بِٱلْإِثْمِ ۚ فَحَسْبُهُۥ جَهَنَّمُ ۚ وَلَبِئْسَ ٱلْمِهَادُ","tafsir":"وأدبر وذهب من عندك ( سَعى فِي الْأَرْضِ ) من هنا إلى هناك كما هو شأن المشاغب المفسد ( لِيُفْسِدَ فِيها ) بإثارة الفوضى والاضطراب ( وَيُهْلِكَ الْحَرْثَ ) أي الزراعة ( وَالنَّسْلَ ) أي الأولاد والذرية فإن إثارة الفوضى يوجب خراب الزراعات لاشتغال أهلها بالكفاح ، وفناء النسل إذ الشباب دائما يقدمون على الحرب والجلاء ( وَاللهُ لا يُحِبُّ الْفَسادَ ) ."},{"text":"وَمِنَ ٱلنَّاسِ مَن يَشْرِى نَفْسَهُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ ۗ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ","tafsir":"في عملك فلا تفسد ( أَخَذَتْهُ الْعِزَّةُ بِالْإِثْمِ ) أي حملته عزة وحمية الجاهلية بأن يأثم لأنه لا يرضخ للحق ولا يعتني به ( فَحَسْبُهُ جَهَنَّمُ ) أي تمكينه جهنم جزاء له ( وَلَبِئْسَ الْمِهادُ ) أي محل القرار ، وهذه الآيات نزلت في المنافقين أو في فرد خاص منهم يسمى وَمِنَ النَّاسِ مَنْ يَشْرِي نَفْسَهُ ابْتِغاءَ مَرْضاتِ اللهِ وَاللهُ رَؤُفٌ بِالْعِبادِ (207) يا أَيُّهَا الَّذِينَ آمَنُوا ادْخُلُوا فِي السِّلْمِ كَافَّةً وَلا تَتَّبِعُوا خُطُواتِ الشَّيْطانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ (208) الأخنس بن شريق ، كان يظهر المحبة للنبي ويبطن الفساد والنفاق ، ولعل وجه ارتباط هذه الآيات بالحج أن الكلام انتهى هناك حول من يفتخر بالآباء اعتزازا بالنفس وهذا مثلهم في الاعتزاز والاغترار."},{"text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱدْخُلُوا۟ فِى ٱلسِّلْمِ كَآفَّةً وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَـٰنِ ۚ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ","tafsir":"أي بعض الناس ( مَنْ يَشْرِي ) أي يبيع فإن كلا من البيع والشراء يجيء بمعنى الآخر ( نَفْسَهُ ابْتِغاءَ مَرْضاتِ اللهِ ) أي لأجل طلب رضاه سبحانه ( وَاللهُ رَؤُفٌ بِالْعِبادِ ) يرأف بهم فيجازيهم لعملهم الحسن ، ولعل ذكر الرأفة لأجل أن هذا البيع يحتوي على أخطاء وأضرار ، ففيه تنبيه إلى أن الله رؤف يجنب البائع الأخطار والإضرار ، وهذه الآية نزلت في الإمام أمير المؤمنين علي بن أبي طالب عليه‌السلام حين نام في فراش الرسول صلى‌الله‌عليه‌وآله‌وسلم ليلة الهجرة. [209] وحين ذكر أن من الناس من هو منافق ناسب الإرشاد العام فقال سبحانه ( يا أَيُّهَا الَّذِينَ آمَنُوا ) باللسان ( ادْخُلُوا فِي السِّلْمِ ) مع الله ورسوله في جميع أموركم ( كَافَّةً ) أي جميعا فاستسلموا للدين في جميع شؤونكم ( وَلا تَتَّبِعُوا خُطُواتِ الشَّيْطانِ ) بأن تخالفوا أمر الله سبحانه وتتبعوا أمر الشيطان وما يوحي اليه الهوى ( إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ ) أي عدو ظاهر لأنه يأمر بالمفاسد التي ترجع إلى ذهاب دينكم ودنياكم. فَإِنْ زَلَلْتُمْ مِنْ بَعْدِ ما جاءَتْكُمُ الْبَيِّناتُ فَاعْلَمُوا أَنَّ اللهَ عَزِيزٌ حَكِيمٌ (209) هَلْ يَنْظُرُونَ إِلاَّ أَنْ يَأْتِيَهُمُ اللهُ فِي ظُلَلٍ مِنَ الْغَمامِ وَالْمَلائِكَةُ وَقُضِيَ الْأَمْرُ وَإِلَى اللهِ تُرْجَعُ الْأُمُورُ (210) سَلْ بَنِي إِسْرائِيلَ كَمْ آتَيْناهُمْ مِنْ آيَةٍ بَيِّنَةٍ"},{"text":"فَإِن زَلَلْتُم مِّنۢ بَعْدِ مَا جَآءَتْكُمُ ٱلْبَيِّنَـٰتُ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ","tafsir":""},{"text":"هَلْ يَنظُرُونَ إِلَّآ أَن يَأْتِيَهُمُ ٱللَّهُ فِى ظُلَلٍ مِّنَ ٱلْغَمَامِ وَٱلْمَلَـٰٓئِكَةُ وَقُضِىَ ٱلْأَمْرُ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ","tafsir":"تشبيه للذنب بمن يزل له قدم ( مِنْ بَعْدِ ما جاءَتْكُمُ الْبَيِّناتُ ) الأدلة الواضحة على الحق ( فَاعْلَمُوا أَنَّ اللهَ عَزِيزٌ ) فلا يمتنع عليه العذاب والعقاب بمن زل ( حَكِيمٌ ) في فعله ليعفوا عمن يشاء ويعذب من يشاء. [211] وهنا يعود السياق إلى من تأخذه العزة فيقول سبحانه ( هَلْ يَنْظُرُونَ ) النظر بمعنى الانتظار أي هل ينتظر هؤلاء المنافقون ( إِلَّا أَنْ يَأْتِيَهُمُ اللهُ ) حتى يؤمنوا ويقلعوا عن نفاقهم وكفرهم ( فِي ظُلَلٍ مِنَ الْغَمامِ ) ظلل جمع ظلة وهي ما يستظل به من الشمس وسمي السحاب ظلة لأنه يستظل به من الشمس ، والغمام هو السحاب وقد كانت اليهود تزعم أن الله ينزل في ظلل من الغمام وكذلك الملائكة معه ولذا قال : ( وَالْمَلائِكَةُ ) عطفا على « الله » ( وَقُضِيَ الْأَمْرُ ) أي يوم تغيير الكون عن وضعه لا يبقى بعد مجال للتكليف إنما هو يوم القيامة ( وَإِلَى اللهِ تُرْجَعُ الْأُمُورُ ) ويكون ذلك اليوم يوم حساب وعقاب وثواب ، لا يوم عمل وشغل ، فالآية تشير إلى أساطير أهل الكتاب متهكما ساخرا ، ثم يهدد ويوعد بأن الأمر يقضي فلا مجال بعد التكليف. [212] وحيث أشير إلى أسطورة إسرائيلية ، توجه السياق إلى تأنيب بني إسرائيل الذين كانوا يعاندون في إنكارهم للآيات ( سَلْ بَنِي إِسْرائِيلَ كَمْ آتَيْناهُمْ مِنْ آيَةٍ بَيِّنَةٍ ) أي أعطيناهم أدلة واضحة ومع ذلك عاندوا وَمَن يُبَدِّلْ نِعْمَةَ اللّهِ مِن بَعْدِ مَا جَاءتْهُ فَإِنَّ اللّهَ شَدِيدُ الْعِقَابِ (211) زُيِّنَ لِلَّذِينَ كَفَرُواْ الْحَيَاةُ الدُّنْيَا وَيَسْخَرُونَ مِنَ الَّذِينَ آمَنُواْ وَالَّذِينَ اتَّقَواْ فَوْقَهُمْ يَوْمَ الْقِيَامَةِ وَاللّهُ يَرْزُقُ مَن يَشَاء بِغَيْرِ حِسَابٍ (212) كَانَ النَّاسُ أُمَّةً وَاحِدَةً فَبَعَثَ ولم يؤمنوا ( وَمَنْ يُبَدِّلْ نِعْمَةَ اللهِ ) كفرا فلا يؤمن بآياته ( مِنْ بَعْدِ ما جاءَتْهُ فَإِنَّ اللهَ شَدِيدُ الْعِقابِ ) فليهيئ نفسه لعقابه."},{"text":"سَلْ بَنِىٓ إِسْرَٰٓءِيلَ كَمْ ءَاتَيْنَـٰهُم مِّنْ ءَايَةٍۭ بَيِّنَةٍ ۗ وَمَن يُبَدِّلْ نِعْمَةَ ٱللَّهِ مِنۢ بَعْدِ مَا جَآءَتْهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ","tafsir":""},{"text":"زُيِّنَ لِلَّذِينَ كَفَرُوا۟ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَيَسْخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ ۘ وَٱلَّذِينَ ٱتَّقَوْا۟ فَوْقَهُمْ يَوْمَ ٱلْقِيَـٰمَةِ ۗ وَٱللَّهُ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ","tafsir":""},{"text":"كَانَ ٱلنَّاسُ أُمَّةً وَٰحِدَةً فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّـۧنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلْكِتَـٰبَ بِٱلْحَقِّ لِيَحْكُمَ بَيْنَ ٱلنَّاسِ فِيمَا ٱخْتَلَفُوا۟ فِيهِ ۚ وَمَا ٱخْتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَـٰتُ بَغْيًۢا بَيْنَهُمْ ۖ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ لِمَا ٱخْتَلَفُوا۟ فِيهِ مِنَ ٱلْحَقِّ بِإِذْنِهِۦ ۗ وَٱللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ","tafsir":"أي الحياة القريبة مقابل الحياة البعيدة وهي الآخرة والتي زينها لهم هي مجموعة عوامل بعضها حق وبعضها باطل فإن الحياة التي خلقها الله جميلة تزين نفسها كما أن الشيطان والنفس والهوى تزين الحياة لتصرف الناس عن الآخرة ( وَيَسْخَرُونَ مِنَ الَّذِينَ آمَنُوا ) حيث يرونهم منصرفين عنها مقبلين إلى الآخرة ـ التي لا يعتقد هؤلاء الكفار بها ـ ( وَالَّذِينَ اتَّقَوْا ) من المؤمنين ( فَوْقَهُمْ ) أي فوق هؤلاء الكفار منزلة ومقاما ورتبة ( يَوْمَ الْقِيامَةِ ) لأنهم عملوا لها فأدركوا خيرها والكفار لم يعملوا فيبقون هناك سائلين ( وَاللهُ يَرْزُقُ مَنْ يَشاءُ بِغَيْرِ حِسابٍ ) فالرزق في الدنيا ليس بالكفر والتوجه إليها حتى يحرم أهل الآخرة منها بل الرزق يصيب الكافر والمؤمن ، فالمؤمن منعم في الدنيا وفوق الكافر في الآخرة. [214] إن كل حركة إصلاحية لا بد وأن تشق صفوف الناس المتصافقة على الفساد وهكذا كان بعث الأنبياء عليهم‌السلام فقد ( كانَ النَّاسُ أُمَّةً واحِدَةً فَبَعَثَ اللّهُ النَّبِيِّينَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ الْكِتَابَ بِالْحَقِّ لِيَحْكُمَ بَيْنَ النَّاسِ فِيمَا اخْتَلَفُواْ فِيهِ وَمَا اخْتَلَفَ فِيهِ إِلاَّ الَّذِينَ أُوتُوهُ مِن بَعْدِ مَا جَاءتْهُمُ الْبَيِّنَاتُ بَغْيًا بَيْنَهُمْ فَهَدَى اللّهُ الَّذِينَ آمَنُواْ لِمَا اخْتَلَفُواْ فِيهِ مِنَ الْحَقِّ بِإِذْنِهِ وَاللّهُ يَهْدِي مَن يَشَاء إِلَى صِرَاطٍ مُّسْتَقِيمٍ (213) للهُ النَّبِيِّينَ مُبَشِّرِينَ ) لمن آمن وأصلح ( وَمُنْذِرِينَ ) لمن كفر أو عصى ( وَأَنْزَلَ مَعَهُمُ الْكِتابَ بِالْحَقِ ) قيد توضيحي إذ كل إنزال من الله بالحق وإنما أكد لمقابلته لسائر الكتب التي ترسلها رؤساء الحكومات إلى رعاياها فإن منها ما هو حق ومنها ما هو باطل ( لِيَحْكُمَ ) ذات الكتاب ( بَيْنَ النَّاسِ فِيمَا اخْتَلَفُوا فِيهِ ) من أمور معاملاتهم وسائر معاشراتهم والاختلاف هنا لا ينافي كون الناس أمة واحدة إذ وحدة الأمة تجتمع مع هذا النوع من الاختلاف ثم صار نفس الكتاب محلا لاختلاف الأمة فيه ، لكن هذا الاختلاف ليس عن واقع وشك ، لأن الكتاب واضح بل عن حسد وبغي وطمع ( وَمَا اخْتَلَفَ فِيهِ ) أي في الكتاب بأن فسره كل حسب نظره وهواه ( إِلَّا الَّذِينَ أُوتُوهُ ) أي الأمة التي أعطيت الكتاب ( مِنْ بَعْدِ ما جاءَتْهُمُ الْبَيِّناتُ ) أي الأدلة الواضحة على معاني الكتاب ( بَغْياً بَيْنَهُمْ ) أي الاختلاف إنما نشأ من البغي والظلم والحسد الحاصل بينهم ( فَهَدَى اللهُ الَّذِينَ آمَنُوا ) حقيقة وأرادوا اتباع أحكام الله واقعا ( لِمَا اخْتَلَفُوا فِيهِ مِنَ الْحَقِ ) أي للشيء الذي اختلفت الأمة فيه ( بِإِذْنِهِ ) أي بلطفه بهم حيث هداهم ( وَاللهُ يَهْدِي مَنْ يَشاءُ إِلى صِراطٍ مُسْتَقِيمٍ ) إما أَمْ حَسِبْتُمْ أَنْ تَدْخُلُوا الْجَنَّةَ وَلَمَّا يَأْتِكُمْ مَثَلُ الَّذِينَ خَلَوْا مِنْ قَبْلِكُمْ مَسَّتْهُمُ الْبَأْساءُ وَالضَّرَّاءُ وَزُلْزِلُوا حَتَّى يَقُولَ الرَّسُولُ وَالَّذِينَ آمَنُوا مَعَهُ مَتى نَصْرُ اللهِ أَلا إِنَّ نَصْرَ اللهِ قَرِيبٌ (214) معناه الإيصال إلى المطلوب وهو ليس بواجب بالنسبة إلى الجميع وإما معناه إرائة الطريق ومعنى من يشاء إنه لو لم يشأ لا يهدي أحد ، إذ الهداية لا تكون إلا بإرسال الرسل ، والأول أنسب بالسياق. [215] ثم يسأل الله المؤمنين الذين وقعوا في متاعب هذا الخلاف حيث يحاربونهم الكفار لأجل أنهم اهتدوا بهدي الله ( أَمْ حَسِبْتُمْ ) أي بل حسبتم وظننتم أيها المسلمون ( أَنْ تَدْخُلُوا الْجَنَّةَ ) اعتباطا وبلا مشقة وحرج ( وَلَمَّا يَأْتِكُمْ مَثَلُ الَّذِينَ خَلَوْا ) أي مضوا ( مِنْ قَبْلِكُمْ ) أي لم يأتكم بعد امتحان مثل امتحان الأمم المؤمنة السالفة الذين ثبتوا وصبروا تجاه الأحزان والكوارث وإنما قال « مثل » لأنهم صاروا مثلا للصبر وتحمل المكاره ( مَسَّتْهُمُ ) أي لمستهم ( الْبَأْساءُ ) الفقر ( وَالضَّرَّاءُ ) المرض والحرج وأشباههما ( وَزُلْزِلُوا ) أي حركوا بأنواع المحن والبلايا ( حَتَّى ) وصل الحال إلى أن ( يَقُولَ الرَّسُولُ ) لتلك الأمم ( وَالَّذِينَ آمَنُوا مَعَهُ مَتى نَصْرُ اللهِ ) استعجالا للنصر الموعود وتمنيا للخلاص من الشدائد والمحن ، فاستدرك الأمر وأجيب سؤالهم بأنه ( أَلا إِنَّ نَصْرَ اللهِ قَرِيبٌ ) وهذا جواب طبيعي يقوله الرسول صلى‌الله‌عليه‌وآله‌وسلم والمؤمنون كلما رأوا البلاء والمحن ، وفي الآية تعبير المؤمنين وأنهم إنما يفوزون بسعادة الدنيا والآخرة بعد مثل هذه الكوارث والمتاعب. [216] ويأتي هنا دور أسئلة وجهت إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم أجاب عنها القرآن يَسْئَلُونَكَ ما ذا يُنْفِقُونَ قُلْ ما أَنْفَقْتُمْ مِنْ خَيْرٍ فَلِلْوالِدَيْنِ وَالْأَقْرَبِينَ وَالْيَتامى وَالْمَساكِينِ وَابْنِ السَّبِيلِ وَما تَفْعَلُوا مِنْ خَيْرٍ فَإِنَّ اللهَ بِهِ عَلِيمٌ (215) كُتِبَ عَلَيْكُمُ الْقِتالُ وَهُوَ كُرْهٌ لَكُمْ وَعَسى الكريم يجمعها الإقلاع عن الملذات والصبر على الطاعة وبهذا يرتبط السياق بما قبله حيث كان الكلام في معرض التضحية في سبيل العقيدة والإيمان وما يأتي نوع من التضحية ( يَسْئَلُونَكَ ) يا رسول الله ( ما ذا يُنْفِقُونَ ) في سبيل الله من أقسام الأموال ( قُلْ ) ليس لهم الإنفاق فإنه أي شيء كان يقبل إذا كان المنفق عليه أهلا كما أنه لا يقبل إذا كان المنفق عليه غير أهل فمعيار الإنفاق ليس ماهية المنفق وإنما شخص المنفق عليه ف ( ما أَنْفَقْتُمْ مِنْ خَيْرٍ ) فاللازم أن يكون للوالدين ( وَالْأَقْرَبِينَ ) أقربائكم ( وَالْيَتامى وَالْمَساكِينِ وَابْنِ السَّبِيلِ ) وأشباه ذلك مما يقصد به وجه الله سبحانه ( وَما تَفْعَلُوا مِنْ خَيْرٍ ) إنفاق أو غيره ( فَإِنَّ اللهَ بِهِ عَلِيمٌ ) فيجازيكم بالخير خيرا. و روي أنها نزلت في عمرو ابن الجموح ، وكان شيخا كبيرا كثير المال فقال يا رسول الله بما ذا أتصدق ؟ وعلى من أتصدق فأنزل الله هذه الآية (1) . [217] ثم رجع السياق إلى الآية السابقة التي فيها ذكر التضحية والزلزال ( كُتِبَ عَلَيْكُمُ الْقِتالُ ) مع من تعدى عليكم أو على العقيدة الصحيحة أو على الناس ( وَهُوَ كُرْهٌ لَكُمْ ) تكرهونه ( وَعَسى ) ( 1) فقه القرآن : ج 1 ص 239. أَنْ تَكْرَهُوا شَيْئاً وَهُوَ خَيْرٌ لَكُمْ وَعَسى أَنْ تُحِبُّوا شَيْئاً وَهُوَ شَرٌّ لَكُمْ وَاللهُ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ (216) يَسْئَلُونَكَ عَنِ الشَّهْرِ الْحَرامِ قِتالٍ فِيهِ قُلْ قِتالٌ فِيهِ كَبِيرٌ وَصَدٌّ عَنْ سَبِيلِ اللهِ وَكُفْرٌ بِهِ وَالْمَسْجِدِ الْحَرامِ وَإِخْراجُ أَهْلِهِ مِنْهُ أَكْبَرُ بمعنى « قد » وما بعده فاعله ( أَنْ تَكْرَهُوا شَيْئاً وَهُوَ خَيْرٌ لَكُمْ ) والقتال من ذلك فإنه يوجب سيادتكم وسعادتكم ( وَعَسى أَنْ تُحِبُّوا شَيْئاً وَهُوَ شَرٌّ لَكُمْ ) وترك القتال كذلك لما فيه من راحة الجسم وعدم اضطراب القلب لكنه شر لما فيه من زوال السيادة والعزة وتسلط الكفار والأجانب ( وَاللهُ يَعْلَمُ ) ما فيه خيركم وشركم ( وَأَنْتُمْ لا تَعْلَمُونَ ) . [218] بعث رسول الله بسرية فاتفق أن قاتلت في شهر رجب وهي تترد في أن اليوم الذي حاربت فيه من جمادى أو رجب ، وشهر رجب من الأشهر الحرم ، ولذا كثر صخب المشركين وإنه كيف يقاتل الرسول في شهر حرام وأتى وفدهم إلى المدينة يسألون الرسول صلى‌الله‌عليه‌وآله‌وسلم عن ذلك فنزلت هذه الآية ( يَسْئَلُونَكَ عَنِ الشَّهْرِ الْحَرامِ قِتالٍ فِيهِ ) بدل شهر أي يسألونك يا رسول الله عن القتال في الشهر الحرام ( قُلْ قِتالٌ فِيهِ ) أي في الشهر الحرام ( كَبِيرٌ ) في نفسه لا يجوز ( وَ ) لكن ليس كبر ذنبه مثل عظم ذنب ما تفعلونه أنتم أيها المشركون ف ( صَدٌّ عَنْ سَبِيلِ اللهِ ) أي المنع عنه بأن لا يسلم أحد ( وَكُفْرٌ بِهِ ) أي بالله سبحانه ( وَ ) صد عن ( الْمَسْجِدِ الْحَرامِ ) لئلا يحج المسلمون ( وَإِخْراجُ أَهْلِهِ ) أي أهل المسجد الحرام ( مِنْهُ ) كما فعل المشركون بالنبي والمسلمين ( أَكْبَرُ عِنْدَ اللهِ وَالْفِتْنَةُ أَكْبَرُ مِنَ الْقَتْلِ وَلا يَزالُونَ يُقاتِلُونَكُمْ حَتَّى يَرُدُّوكُمْ عَنْ دِينِكُمْ إِنِ اسْتَطاعُوا وَمَنْ يَرْتَدِدْ مِنْكُمْ عَنْ دِينِهِ فَيَمُتْ وَهُوَ كافِرٌ فَأُولئِكَ حَبِطَتْ أَعْمالُهُمْ فِي الدُّنْيا وَالْآخِرَةِ وَأُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ (217) إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هاجَرُوا عِنْدَ اللهِ ) فكيف تؤاخذون المسلمين بذنب مهما عظم وتنسون ذنوبكم التي هي أعظم منه ( وَالْفِتْنَةُ ) التي أنتم تقيمون عليها من تفتين المسلمين عن دينهم وإغرائهم بالكفر بعد الإسلام ( أَكْبَرُ مِنَ الْقَتْلِ ) الذي صدر من المسلمين ، فالقتل يفسد دنيا المقتول والفتنة تفسد دين المفتتن وأخراه ( وَلا يَزالُونَ ) أي لا يزال الكفار ( يُقاتِلُونَكُمْ ) أيها المسلمون ( حَتَّى يَرُدُّوكُمْ عَنْ دِينِكُمْ ) إلى الكفر ( إِنِ اسْتَطاعُوا ) أن يردوكم ( وَمَنْ يَرْتَدِدْ مِنْكُمْ ) أيها المسلمون ( عَنْ دِينِهِ ) إلى الكفر ( فَيَمُتْ وَهُوَ كافِرٌ ) في مقابل من ارتد ورجع حتى مات مؤمنا ( فَأُولئِكَ حَبِطَتْ أَعْمالُهُمْ ) والحبط هو الإبطال والإفناء فلا حسنة لهم ولم ينتفعوا بإيمانهم السابق على الكفر ( فِي الدُّنْيا ) فليس لهم احترام المسلم وحقوقه ( وَالْآخِرَةِ ) فلا يجزى بالجنة والثواب ( وَأُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ ) إلى الأبد. [219] وهناك ظن أناس أن القاتل في رجب إن سلم من الإثم لم يكن له أجر لأنه انتهك حرمة الشهر الحرام فأنزل الله ( إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هاجَرُوا ) بأن قطعوا ديارهم وأهليهم وخلفوا أموالهم لأجل أن يكونوا وَجاهَدُوا فِي سَبِيلِ اللهِ أُولئِكَ يَرْجُونَ رَحْمَتَ اللهِ وَاللهُ غَفُورٌ رَحِيمٌ (218) يَسْئَلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِ قُلْ فِيهِما إِثْمٌ كَبِيرٌ وَمَنافِعُ لِلنَّاسِ وَإِثْمُهُما أَكْبَرُ مِنْ نَفْعِهِما وَيَسْئَلُونَكَ ما ذا يُنْفِقُونَ قُلِ الْعَفْوَ مع الرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَجاهَدُوا ) أي أوقعوا أنفسهم بالجهد والتعب ، وأوضح أفراده المقاتلة ( فِي سَبِيلِ اللهِ ) لكسب مراضيه ( أُولئِكَ يَرْجُونَ رَحْمَتَ اللهِ ) يأملونها في الدنيا والآخرة ( وَاللهُ غَفُورٌ ) يغفر لمن زل و ( رَحِيمٌ ) بعباده المؤمنين فلا ينقص أجورهم وإنما قال : « يرجون » لأن الإنسان لا يدري ما حاله في المستقبل وإنه هل يبقى على الإيمان والصلاح حتى يثاب أم يفتن في دينه حتى يحبط عمله."},{"text":"أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَأْتِكُم مَّثَلُ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِكُم ۖ مَّسَّتْهُمُ ٱلْبَأْسَآءُ وَٱلضَّرَّآءُ وَزُلْزِلُوا۟ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ مَتَىٰ نَصْرُ ٱللَّهِ ۗ أَلَآ إِنَّ نَصْرَ ٱللَّهِ قَرِيبٌ","tafsir":""},{"text":"يَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ ۖ قُلْ مَآ أَنفَقْتُم مِّنْ خَيْرٍ فَلِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينِ وَٱبْنِ ٱلسَّبِيلِ ۗ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ","tafsir":""},{"text":"كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ وَهُوَ كُرْهٌ لَّكُمْ ۖ وَعَسَىٰٓ أَن تَكْرَهُوا۟ شَيْـًٔا وَهُوَ خَيْرٌ لَّكُمْ ۖ وَعَسَىٰٓ أَن تُحِبُّوا۟ شَيْـًٔا وَهُوَ شَرٌّ لَّكُمْ ۗ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ","tafsir":""},{"text":"يَسْـَٔلُونَكَ عَنِ ٱلشَّهْرِ ٱلْحَرَامِ قِتَالٍ فِيهِ ۖ قُلْ قِتَالٌ فِيهِ كَبِيرٌ ۖ وَصَدٌّ عَن سَبِيلِ ٱللَّهِ وَكُفْرٌۢ بِهِۦ وَٱلْمَسْجِدِ ٱلْحَرَامِ وَإِخْرَاجُ أَهْلِهِۦ مِنْهُ أَكْبَرُ عِندَ ٱللَّهِ ۚ وَٱلْفِتْنَةُ أَكْبَرُ مِنَ ٱلْقَتْلِ ۗ وَلَا يَزَالُونَ يُقَـٰتِلُونَكُمْ حَتَّىٰ يَرُدُّوكُمْ عَن دِينِكُمْ إِنِ ٱسْتَطَـٰعُوا۟ ۚ وَمَن يَرْتَدِدْ مِنكُمْ عَن دِينِهِۦ فَيَمُتْ وَهُوَ كَافِرٌ فَأُو۟لَـٰٓئِكَ حَبِطَتْ أَعْمَـٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ ۖ وَأُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ","tafsir":""},{"text":"إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَاجَرُوا۟ وَجَـٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ أُو۟لَـٰٓئِكَ يَرْجُونَ رَحْمَتَ ٱللَّهِ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ","tafsir":""},{"text":"۞ يَسْـَٔلُونَكَ عَنِ ٱلْخَمْرِ وَٱلْمَيْسِرِ ۖ قُلْ فِيهِمَآ إِثْمٌ كَبِيرٌ وَمَنَـٰفِعُ لِلنَّاسِ وَإِثْمُهُمَآ أَكْبَرُ مِن نَّفْعِهِمَا ۗ وَيَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ قُلِ ٱلْعَفْوَ ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَـٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ","tafsir":""},{"text":"فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ ۗ وَيَسْـَٔلُونَكَ عَنِ ٱلْيَتَـٰمَىٰ ۖ قُلْ إِصْلَاحٌ لَّهُمْ خَيْرٌ ۖ وَإِن تُخَالِطُوهُمْ فَإِخْوَٰنُكُمْ ۚ وَٱللَّهُ يَعْلَمُ ٱلْمُفْسِدَ مِنَ ٱلْمُصْلِحِ ۚ وَلَوْ شَآءَ ٱللَّهُ لَأَعْنَتَكُمْ ۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ","tafsir":"يا رسول الله ( عَنِ الْخَمْرِ ) وهي كل مسكر وأظهر أفراده المسكر المتخذ من العنب ( وَالْمَيْسِرِ ) وهو القمار بجميع أصنافه والسؤال كان عن حكمهما ( قُلْ ) يا محمد ( فِيهِما إِثْمٌ كَبِيرٌ ) أي وزر عظيم لما فيهما من الفساد الكبير ( وَمَنافِعُ لِلنَّاسِ ) فإن الخمر تفيد اللذة والطرب وفي الاتجار بها ثمن وربح والقمار فيه لذة للاعب وربح للفائز ( وَإِثْمُهُما أَكْبَرُ مِنْ نَفْعِهِما ) إذ الفساد الذي يسببانه في البدن والعقل والمال أكبر من اللذة والربح الذي يحصل بسببهما بالإضافة إلى العقوبة الأخروية التي تصيب الإنسان من جرائها. ( وَيَسْئَلُونَكَ ) يا رسول الله ( ما ذا يُنْفِقُونَ ) وهنا جاء الجواب طبق السؤال وإنه « ماذا » لا إنه « لمن » فقال ( قُلْ ) يا محمد ( الْعَفْوَ ) أي الزائد من المال على النفقة فإن ما بقدر نفقة النفس والأهل لا ينفق تقديما كَذلِكَ يُبَيِّنُ اللهُ لَكُمُ الْآياتِ لَعَلَّكُمْ تَتَفَكَّرُونَ (219) فِي الدُّنْيا وَالْآخِرَةِ وَيَسْئَلُونَكَ عَنِ الْيَتامى قُلْ إِصْلاحٌ لَهُمْ خَيْرٌ وَإِنْ تُخالِطُوهُمْ لواجبي النفقة على غيره وهذا الإنفاق مستحب لما دل على حصر الحقوق الواجبة في أمور معدودة ( كَذلِكَ ) أي هكذا يا رسول الله فإن كذا تشبيه وإشارة والكاف الملحق بها اللام للخطاب ( يُبَيِّنُ اللهُ لَكُمُ الْآياتِ ) الأدلة المرتبطة بالتشريعات ( لَعَلَّكُمْ تَتَفَكَّرُونَ ) أي لكي تتفكروا."},{"text":"وَلَا تَنكِحُوا۟ ٱلْمُشْرِكَـٰتِ حَتَّىٰ يُؤْمِنَّ ۚ وَلَأَمَةٌ مُّؤْمِنَةٌ خَيْرٌ مِّن مُّشْرِكَةٍ وَلَوْ أَعْجَبَتْكُمْ ۗ وَلَا تُنكِحُوا۟ ٱلْمُشْرِكِينَ حَتَّىٰ يُؤْمِنُوا۟ ۚ وَلَعَبْدٌ مُّؤْمِنٌ خَيْرٌ مِّن مُّشْرِكٍ وَلَوْ أَعْجَبَكُمْ ۗ أُو۟لَـٰٓئِكَ يَدْعُونَ إِلَى ٱلنَّارِ ۖ وَٱللَّهُ يَدْعُوٓا۟ إِلَى ٱلْجَنَّةِ وَٱلْمَغْفِرَةِ بِإِذْنِهِۦ ۖ وَيُبَيِّنُ ءَايَـٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ","tafsir":"أمر ( الدُّنْيا وَ ) أمر ( الْآخِرَةِ ) فتجمعوهما في التفكير ثم ترون جمال الأحكام إذ التفكير في الدنيا فقط يوجب شلل قسم من الأحكام فلما ذا ينفق الإنسان ـ مثلا ـ وهو بحاجة إلى المال ، كما إن التفكير في الآخرة فقط يوجب شلل قسم آخر من الأحكام فلما ذا لا ينفق الإنسان جميع أمواله لتحصيل أجر الآخرة وهكذا سائر الأحكام فلا يعرف جمالها إلا إذا افتكر الإنسان في كلتا الحياتين وعرف المصلحتين ( وَيَسْئَلُونَكَ عَنِ الْيَتامى ) كيف يعاشروهم فقد ورد أنه لما نزل ( وَلا تَقْرَبُوا مالَ الْيَتِيمِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ ) (1) ذهب كل من عنده يتيم ليعزل اليتيم في مأكله ومشربه عن نفسه لئلا يبتلي بماله واشتد ذلك عليهم فسألوا النبي صلى‌الله‌عليه‌وآله‌وسلم فنزلت ( قُلْ ) يا رسول الله ( إِصْلاحٌ لَهُمْ خَيْرٌ ) بأن يصلح الإنسان أموال اليتيم ويعاشره معاشرة المصلحين بدون أجرة وعوض خير من عزلهم وطردهم ( وَإِنْ تُخالِطُوهُمْ ) بأن تخلطوا أموالهم ( 1) الأنعام : 153. فَإِخْوانُكُمْ وَاللهُ يَعْلَمُ الْمُفْسِدَ مِنَ الْمُصْلِحِ وَلَوْ شاءَ اللهُ لَأَعْنَتَكُمْ إِنَّ اللهَ عَزِيزٌ حَكِيمٌ (220) وَلا تَنْكِحُوا الْمُشْرِكاتِ حَتَّى يُؤْمِنَّ وَلَأَمَةٌ مُؤْمِنَةٌ خَيْرٌ مِنْ مُشْرِكَةٍ وَلَوْ أَعْجَبَتْكُمْ بأموالكم وتشاركون معهم بالنسبة وحفظ المقدار فهم إخوانكم في الإيمان والأخ يعاشر الأخ بالإصلاح والغبطة ( وَاللهُ يَعْلَمُ الْمُفْسِدَ مِنَ الْمُصْلِحِ ) فهو عارف بنية المخالطين للأيتام وإنهم يريدون بالمخالطة الإفساد وأكل مال اليتيم أو الإصلاح والتحفظ على اليتيم حتى يبلغ ويرشد ( وَلَوْ شاءَ اللهُ لَأَعْنَتَكُمْ ) أي أوقعكم في العنت والمشقة بالنسبة إلى اليتيم بأن يوجب الاجتناب عن أموالهم واعتزال أموالكم عن أموالهم فحيث أنه لم يفعل ذلك رحمة بكم فلا تأكلوا أموالهم فسادا وطمعا ( إِنَّ اللهَ عَزِيزٌ ) فهو يقدر ـ بعزته ـ من إعناتكم ( حَكِيمٌ ) لا يفعل إلا الصلاح وما تقتضيه الحكمة. [222] ثم انتقل السياق إلى فئة من أحكام الأسرة في النكاح والطلاق وشؤونها ولعل الارتباط العام بين هذه الآيات والآيات السابقة أنها انتهت إلى حكم اليتيم ، فاللازم بيان العش الذي يتربى فيه فراخ الإنسان ، وإنه كيف يلزم أن يكون لينشأ الأولاد صالحين أصحاء جسما وعقلا وعاطفة ( وَلا تَنْكِحُوا ) أيها الرجال المسلمون النساء ( الْمُشْرِكاتِ ) سواء كن أهل كتاب أم لا فأهل الكتاب أيضا مشركون كما قال سبحانه ( فَتَعالَى اللهُ عَمَّا يُشْرِكُونَ ) (1) ( حَتَّى يُؤْمِنَ ) ويدخلن في الإسلام ( وَلَأَمَةٌ مُؤْمِنَةٌ خَيْرٌ مِنْ مُشْرِكَةٍ وَلَوْ أَعْجَبَتْكُمْ ) تلك ( 1) النمل : 64. وَلا تُنْكِحُوا الْمُشْرِكِينَ حَتَّى يُؤْمِنُوا وَلَعَبْدٌ مُؤْمِنٌ خَيْرٌ مِنْ مُشْرِكٍ وَلَوْ أَعْجَبَكُمْ أُولئِكَ يَدْعُونَ إِلَى النَّارِ وَاللهُ يَدْعُوا إِلَى الْجَنَّةِ وَالْمَغْفِرَةِ بِإِذْنِهِ وَيُبَيِّنُ آياتِهِ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ (221) وَيَسْئَلُونَكَ عَنِ الْمَحِيضِ قُلْ هُوَ أَذىً فَاعْتَزِلُوا النِّساءَ فِي الْمَحِيضِ وَلا تَقْرَبُوهُنَّ حَتَّى يَطْهُرْنَ فَإِذا تَطَهَّرْنَ فَأْتُوهُنَّ المشركة لجمالها أو مالها أو حسبها أو نسبها ( وَلا تُنْكِحُوا الْمُشْرِكِينَ ) بناتكم أيها المسلمون ( حَتَّى يُؤْمِنُوا وَلَعَبْدٌ مُؤْمِنٌ ) تزوجوه بنتكم ( خَيْرٌ مِنْ مُشْرِكٍ وَلَوْ أَعْجَبَكُمْ ) ذلك المشرك ( أُولئِكَ ) المشركات والمشركون ( يَدْعُونَ إِلَى النَّارِ ) إما بالتبليغ إلى الشرك وإما بحكم دينهم فإن جليس الإنسان إذا كان غير متدين لا بد وأن يسري إلى جليسه ( وَاللهُ يَدْعُوا إِلَى الْجَنَّةِ وَالْمَغْفِرَةِ ) أي غفران الذنوب ( بِإِذْنِهِ ) فالمسلمات والمسلمون حين أخذوا مبادئهم عن الله سبحانه لا بد وأن يدعون بلسانهم أو بحكم دينهم إلى الجنة ( وَيُبَيِّنُ آياتِهِ ) أحكامه ودلائله ( لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ ) أي لكي يتذكروا ويتعظوا ويرشدوا."},{"text":"وَيَسْـَٔلُونَكَ عَنِ ٱلْمَحِيضِ ۖ قُلْ هُوَ أَذًى فَٱعْتَزِلُوا۟ ٱلنِّسَآءَ فِى ٱلْمَحِيضِ ۖ وَلَا تَقْرَبُوهُنَّ حَتَّىٰ يَطْهُرْنَ ۖ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ ٱللَّهُ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلْمُتَطَهِّرِينَ","tafsir":""},{"text":"نِسَآؤُكُمْ حَرْثٌ لَّكُمْ فَأْتُوا۟ حَرْثَكُمْ أَنَّىٰ شِئْتُمْ ۖ وَقَدِّمُوا۟ لِأَنفُسِكُمْ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُم مُّلَـٰقُوهُ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ","tafsir":"يا رسول الله ( عَنِ الْمَحِيضِ ) الحيض والمحيض بمعنى واحد وأنه هل يجوز مقاربة النساء في حالة الحيض أم لا ( قُلْ ) يا محمد صلى‌الله‌عليه‌وآله‌وسلم ( هُوَ ) أي المحيض ( أَذىً ) قذر نجس أو مشقة ( فَاعْتَزِلُوا النِّساءَ فِي الْمَحِيضِ ) والاعتزال هو الابتعاد عنهن ( وَلا تَقْرَبُوهُنَ ) بالجماع ( حَتَّى يَطْهُرْنَ ) وينظفن عن الدم ( فَإِذا تَطَهَّرْنَ ) عن الدم ( فَأْتُوهُنَ ) جامعوهن مِنْ حَيْثُ أَمَرَكُمُ اللهُ إِنَّ اللهَ يُحِبُّ التَّوَّابِينَ وَيُحِبُّ الْمُتَطَهِّرِينَ (222) نِساؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ وَقَدِّمُوا لِأَنْفُسِكُمْ وَاتَّقُوا اللهَ وَاعْلَمُوا أَنَّكُمْ مُلاقُوهُ وَبَشِّرِ الْمُؤْمِنِينَ (223) ( مِنْ حَيْثُ أَمَرَكُمُ اللهُ ) بمقاربتهن من الفرج الذي هو محل الدم ( إِنَّ اللهَ يُحِبُّ التَّوَّابِينَ ) الذين يرجعون كثيرا عن ذنوبهم إلى الندم والاستغفار بمعنى أنهم كلما أذنبوا تابوا ورجعوا واستغفروا ولعل ذكر التواب بمناسبة أن من زل فقارب في المحيض يقبل الله توبته وإن تكرر منه إذا ندم ندما حقيقيا وتاب توبة نصوحا ( وَيُحِبُّ الْمُتَطَهِّرِينَ ) بالماء عن الأقذار الباطنية والظاهرية أو بالاستغفار عن الذنوب."},{"text":"وَلَا تَجْعَلُوا۟ ٱللَّهَ عُرْضَةً لِّأَيْمَـٰنِكُمْ أَن تَبَرُّوا۟ وَتَتَّقُوا۟ وَتُصْلِحُوا۟ بَيْنَ ٱلنَّاسِ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ","tafsir":"أي مزرعة ومحترث فكما يحرث الحارث البذر في الأرض كذلك يحرث الرجل في زوجته ( فَأْتُوا حَرْثَكُمْ ) وزرعكم ( أَنَّى شِئْتُمْ ) « أنى » إما زمانية بمعنى أي وقت شئتم ، باستثناء أيام الحيض التي سبق أنها لا يجوز وسائر ما استثنى من حال الصوم والإحرام وشبههما ، وإما مكانية أي إتيانها في قبلها من خلفها أو قدامها أو جانبيها ، أو بمعنى الكيفية باركة ونائمة وقائمة ، أما أن يراد سياق السبيلان فبعيد عن سياق الآية ( وَقَدِّمُوا لِأَنْفُسِكُمْ ) بالولد فإنه يبقى ذخرا لكم ، أو قدموا لأنفسكم بالطاعة حيث ذكرت أوامر ونواهي ( وَاتَّقُوا اللهَ ) في أوامره ونواهيه ( وَاعْلَمُوا أَنَّكُمْ مُلاقُوهُ ) والملاقاة هنا بمعنى أنه عليكم حساب الملاقي لملاقيه ( وَبَشِّرِ الْمُؤْمِنِينَ ) بأنهم وَلا تَجْعَلُوا اللهَ عُرْضَةً لِأَيْمانِكُمْ أَنْ تَبَرُّوا وَتَتَّقُوا وَتُصْلِحُوا بَيْنَ النَّاسِ وَاللهُ سَمِيعٌ عَلِيمٌ (224) لا يُؤاخِذُكُمُ اللهُ بِاللَّغْوِ فِي أَيْمانِكُمْ وَلكِنْ يُؤاخِذُكُمْ بِما كَسَبَتْ قُلُوبُكُمْ وَاللهُ غَفُورٌ حَلِيمٌ (225) يفوزون بكل كرامة. [225] وناسب قصة النساء حلف بن رواحة حين حلف أن لا يدخل على ختنه ولا يكلمه ولا يصلح بينه وبين امرأته فكان يقول : إني حلفت بهذا فلا يحل لي أن أفعله ، فنزلت الآية مما ناسب قصة العائلة والنساء التي سبقت ، وتأتي ، فقال سبحانه : ( وَلا تَجْعَلُوا اللهَ عُرْضَةً ) أي معرضا ( لِأَيْمانِكُمْ ) بأن تحلفوا به ( أَنْ تَبَرُّوا ) أي لئلا تبروا ، أي تريدون بالحلف عدم البر ( وَتَتَّقُوا وَتُصْلِحُوا بَيْنَ النَّاسِ ) أي وعدم التقوى وعدم الإصلاح ، فإن هذه اليمين فاسدة لا تنعقد ( وَاللهُ سَمِيعٌ ) لأيمانكم وأقوالكم ( عَلِيمٌ ) بأحوالكم ونياتكم."},{"text":"لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَـٰنِكُمْ وَلَـٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتْ قُلُوبُكُمْ ۗ وَٱللَّهُ غَفُورٌ حَلِيمٌ","tafsir":""},{"text":"لِّلَّذِينَ يُؤْلُونَ مِن نِّسَآئِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ ۖ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ","tafsir":"ولا يعاقبكم ( بِاللَّغْوِ فِي أَيْمانِكُمْ ) جمع يمين ، ويمين اللغو هو ما يجري على عادة الناس من قول : لا والله وبلى والله من غير عقد على يمين يقتطع بها مال ولا يظلم بها أحد ( وَلكِنْ يُؤاخِذُكُمْ بِما كَسَبَتْ قُلُوبُكُمْ ) أي بحنث يمين نويتم اليمين الحقيقية حين إجرائها ( وَاللهُ غَفُورٌ ) يغفر الذنب ( حَلِيمٌ ) يحلم عن العصاة لعلهم يتوبوا ، وتكرار كلمة غفور في كثير من الآيات لفتح باب التوبة أمام العصاة الذين هم كثيرا ما يعصون عن شهوة ونزوات وهوى ، فإن لِلَّذِينَ يُؤْلُونَ مِنْ نِسائِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ فَإِنْ فاؤُ فَإِنَّ اللهَ غَفُورٌ رَحِيمٌ (226) وَإِنْ عَزَمُوا الطَّلاقَ فَإِنَّ اللهَ سَمِيعٌ عَلِيمٌ (227) وَالْمُطَلَّقاتُ يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ ثَلاثَةَ قُرُوءٍ وَلا يَحِلُّ لَهُنَّ أَنْ الله سبحانه لا يسد عليهم باب التوبة وإن تكررت منهم المعاصي والذنوب. [227] ثم يرجع السياق إلى أحكام الأسرة مع مناسبة للحكم مع الحلف فيقول سبحانه : ( لِلَّذِينَ يُؤْلُونَ مِنْ نِسائِهِمْ ) والإيلاء هو الحلف على ترك وطي المرأة على وجه الإضرار بهن ( تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ ) مبتدأ لقوله « للذين » أي توقف أربعة أشهر جائز للذين يؤلون من نسائهم وذلك لأن للرجل أن لا يطأ زوجته أربعة أشهر وبعد ما تم أربعة أشهر خيره الحاكم بين الوطي والكفارة وبين الطلاق وإن امتنع عن الأمرين حبسه ( فَإِنْ فاؤُ ) ورجعوا إلى زوجاتهم بالوطي بعد الأشهر الأربعة ( فَإِنَّ اللهَ غَفُورٌ ) يغفر لهم بهذا الحلف ( رَحِيمٌ ) بهم."},{"text":"وَإِنْ عَزَمُوا۟ ٱلطَّلَـٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ","tafsir":""},{"text":"وَٱلْمُطَلَّقَـٰتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلَـٰثَةَ قُرُوٓءٍ ۚ وَلَا يَحِلُّ لَهُنَّ أَن يَكْتُمْنَ مَا خَلَقَ ٱللَّهُ فِىٓ أَرْحَامِهِنَّ إِن كُنَّ يُؤْمِنَّ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۚ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِى ذَٰلِكَ إِنْ أَرَادُوٓا۟ إِصْلَـٰحًا ۚ وَلَهُنَّ مِثْلُ ٱلَّذِى عَلَيْهِنَّ بِٱلْمَعْرُوفِ ۚ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ","tafsir":"فطلقوا ( فَإِنَّ اللهَ سَمِيعٌ ) للطلاق ( عَلِيمٌ ) بالضمائر والنيات."},{"text":"ٱلطَّلَـٰقُ مَرَّتَانِ ۖ فَإِمْسَاكٌۢ بِمَعْرُوفٍ أَوْ تَسْرِيحٌۢ بِإِحْسَـٰنٍ ۗ وَلَا يَحِلُّ لَكُمْ أَن تَأْخُذُوا۟ مِمَّآ ءَاتَيْتُمُوهُنَّ شَيْـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ ۖ فَإِنْ خِفْتُمْ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا ٱفْتَدَتْ بِهِۦ ۗ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَعْتَدُوهَا ۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُو۟لَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ","tafsir":"أي يصبرن ( بِأَنْفُسِهِنَ ) أي يحفظنها عن الزواج ونحوه ( ثَلاثَةَ قُرُوءٍ ) جمع قرء وهو من ألفاظ الضد يطلق على الحيض وعلى الطهر والمراد هنا الطهر فإذا طلقت المرأة في طهر لم يواقعها فيه الرجل كان هذا الطهر وطهران آخران بينهما حيض موجبا لانتظار العدة فإذا رأت الدم الثالث انقضت عدتها ( وَلا يَحِلُّ لَهُنَّ أَنْ يَكْتُمْنَ مَا خَلَقَ اللّهُ فِي أَرْحَامِهِنَّ إِن كُنَّ يُؤْمِنَّ بِاللّهِ وَالْيَوْمِ الآخِرِ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَلِكَ إِنْ أَرَادُواْ إِصْلاَحًا وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ وَاللّهُ عَزِيزٌ حَكُيمٌ (228) يَكْتُمْنَ ) أي يخفين ( ما خَلَقَ اللهُ فِي أَرْحامِهِنَ ) من الولد ودم الحيض حتى يبطلن حق الرجعة في الطلاق الرجعي أو يستعجلن العدة ( إِنْ كُنَّ يُؤْمِنَّ بِاللهِ وَالْيَوْمِ الْآخِرِ ) يوم القيامة ، فمن آمن بهما لا بد وأن تستقيم حركاته وسكناته وأقواله وأفعاله ، لأنه يعلم أن الله مطلع عليه وأنه سوف يحاسبه ( وَبُعُولَتُهُنَ ) أي أزواج المطلقات الرجعيات ( أَحَقُّ بِرَدِّهِنَ ) إلى أنفسهم ( فِي ذلِكَ ) أي زمان التربص ( إِنْ أَرادُوا ) أي البعولة بردهن ( إِصْلاحاً ) لا إضرارا ، وذلك أن الرجل كان إذا أراد الإضرار بامرأته طلقها واحدة وتركها ، حتى إذا قرب انقضاء عدتها راجعها وتركها مدة ثم طلقها أخرى وتركها مدة كما فعل في الأولى ثم راجعها وتركها مدة ثم طلقها أخرى ، وهذا العمل حرام وإن كان يثبت حكم الرجعة به ( وَلَهُنَ ) أي حق النساء على أزواجهن ( مِثْلُ الَّذِي ) للأزواج ( عَلَيْهِنَ ) فلكل على الآخر حقوق تتكافأ ( بِالْمَعْرُوفِ ) من العشرة وسائر الأمور ( وَلِلرِّجالِ عَلَيْهِنَ ) زيادة ( دَرَجَةٌ ) فإن بيده الطلاق وله عليها الطاعة ( وَاللهُ عَزِيزٌ ) ينفذ أوامره ( حَكِيمٌ ) جعل أحكامه على طبق المصلحة والصلاح ، ومن المحتمل أن يكون قوله تعالى : ( وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَ ) بيان حال العدة أي أن لكل من الزوج والزوجة حقا على الآخر في حال العدة مع أن الرجل له فضيلة على المرأة بأن الاختيار إلى الزوج فقط. الطَّلاقُ مَرَّتانِ فَإِمْساكٌ بِمَعْرُوفٍ أَوْ تَسْرِيحٌ بِإِحْسانٍ وَلا يَحِلُّ لَكُمْ أَنْ تَأْخُذُوا مِمَّا آتَيْتُمُوهُنَّ شَيْئاً إِلاَّ أَنْ يَخافا أَلاَّ يُقِيما حُدُودَ اللهِ فَإِنْ خِفْتُمْ أَلاَّ يُقِيما حُدُودَ اللهِ فَلا جُناحَ عَلَيْهِما فِيمَا افْتَدَتْ بِهِ تِلْكَ حُدُودُ اللهِ فَلا تَعْتَدُوها وَمَنْ يَتَعَدَّ حُدُودَ اللهِ فَأُولئِكَ هُمُ الظَّالِمُونَ (229)"},{"text":"فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعْدُ حَتَّىٰ تَنكِحَ زَوْجًا غَيْرَهُۥ ۗ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن يُقِيمَا حُدُودَ ٱللَّهِ ۗ وَتِلْكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوْمٍ يَعْلَمُونَ","tafsir":"فإن للرجل أن يطلق زوجته تطليقتين فالواجب إذا راجعها بعد التطليقتين إمساك وحفظ لها في حبالته ( بِمَعْرُوفٍ ) بالعشرة الحسنة ( أَوْ تَسْرِيحٌ ) وطلاق ثالث ( بِإِحْسانٍ ) بإعطائها حقوقها وعدم التعدي ، وفوق ذلك إنه يحسن إليها جبرا لخاطرها المكسور. ( وَلا يَحِلُّ لَكُمْ ) أيها الأزواج ( أَنْ تَأْخُذُوا ) في حال الطلاق والاستبدال ( مِمَّا ) أي من الذي ( آتَيْتُمُوهُنَ ) وأعطيتموهن من المهور ( شَيْئاً إِلَّا أَنْ يَخافا ) أي الزوجان ( أَلَّا يُقِيما حُدُودَ اللهِ ) من حقوق الزوجية ( فَإِنْ خِفْتُمْ ) أيها الحكام ( أَلَّا يُقِيما حُدُودَ اللهِ ) من حقوق الزوجية ( فَلا جُناحَ ) ولا حرج ( عَلَيْهِما ) أي على الزوجة في البذل وعلى الزوج في قبول البذل ( فِيمَا ) أي في الذي ( افْتَدَتْ ) الزوجة ( بِهِ ) من المال ( تِلْكَ ) الأحكام المذكورة هي ( حُدُودَ اللهِ ) وأوامره ونواهيه ( فَلا تَعْتَدُوها ) ولا تجاوزوها بالمخالفة ( وَمَنْ يَتَعَدَّ ) منكم ويتجاوز ( حُدُودَ اللهِ ) ويخالف أوامره ونواهيه ( فَأُولئِكَ هُمُ الظَّالِمُونَ ) فَإِنْ طَلَّقَها فَلا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنْكِحَ زَوْجاً غَيْرَهُ فَإِنْ طَلَّقَها فَلا جُناحَ عَلَيْهِما أَنْ يَتَراجَعا إِنْ ظَنَّا أَنْ يُقِيما حُدُودَ اللهِ وَتِلْكَ حُدُودُ اللهِ يُبَيِّنُها لِقَوْمٍ يَعْلَمُونَ (230) وَإِذا طَلَّقْتُمُ النِّساءَ فَبَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ"},{"text":"وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ سَرِّحُوهُنَّ بِمَعْرُوفٍ ۚ وَلَا تُمْسِكُوهُنَّ ضِرَارًا لِّتَعْتَدُوا۟ ۚ وَمَن يَفْعَلْ ذَٰلِكَ فَقَدْ ظَلَمَ نَفْسَهُۥ ۚ وَلَا تَتَّخِذُوٓا۟ ءَايَـٰتِ ٱللَّهِ هُزُوًا ۚ وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ وَمَآ أَنزَلَ عَلَيْكُم مِّنَ ٱلْكِتَـٰبِ وَٱلْحِكْمَةِ يَعِظُكُم بِهِۦ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ","tafsir":"طلاقا ثلاثا ( فَلا تَحِلُّ لَهُ مِنْ بَعْدُ ) الطلاق الثالث فإنها تحرم عليه ( حَتَّى تَنْكِحَ ) المرأة المطلقة ثلاثا ( زَوْجاً غَيْرَهُ ) ويسمى هذا الزوج محللا ( فَإِنْ طَلَّقَها ) أي طلق المرأة الزوج الثاني وانقضت عدتها ( فَلا جُناحَ عَلَيْهِما ) أي على الزوجة والزوج الأول الذي طلقها ثلاث طلقات ( أَنْ يَتَراجَعا إِنْ ظَنَّا ) أي الزوجان ( أَنْ يُقِيما حُدُودَ اللهِ ) في حسن الصحبة والمعاشرة وإن لم يظنا صح الرجوع لكنه سبب للمعصية ، والحاصل أن الحكم الوضعي الصحة وإن كان الحكم التكليفي الحرمة كمن يغسل يده النجسة بالماء المغصوب الذي يوجب طهارة يده لكنه فعل حراما ( وَتِلْكَ ) المذكورات في باب الطلاق والنكاح ( حُدُودَ اللهِ ) أوامره ونواهيه ( يُبَيِّنُها لِقَوْمٍ يَعْلَمُونَ ) الأمور فإنهم هم الذين ينتفعون بهذه الأحكام."},{"text":"وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَلَا تَعْضُلُوهُنَّ أَن يَنكِحْنَ أَزْوَٰجَهُنَّ إِذَا تَرَٰضَوْا۟ بَيْنَهُم بِٱلْمَعْرُوفِ ۗ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمْ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۗ ذَٰلِكُمْ أَزْكَىٰ لَكُمْ وَأَطْهَرُ ۗ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ","tafsir":"أي قاربن تمام العدة وإنما عبر بهذا التعبير لأن انقضاء العدة يعبر عنه بانقضاء الأجل فما يقابله بلوغ الأجل إذا قاربه ، إذ البلوغ الدقي خارج عن محاورة العرف ( فَأَمْسِكُوهُنَ ) أي احفظوهن في حبالتكم بالرجوع إليهن في عدة الرجعة ( بِمَعْرُوفٍ ) الذي يعرفه العقلاء والمشرعون من القيام بحقوق أَوْ سَرِّحُوهُنَّ بِمَعْرُوفٍ وَلا تُمْسِكُوهُنَّ ضِراراً لِتَعْتَدُوا وَمَنْ يَفْعَلْ ذلِكَ فَقَدْ ظَلَمَ نَفْسَهُ وَلا تَتَّخِذُوا آياتِ اللهِ هُزُواً وَاذْكُرُوا نِعْمَتَ اللهِ عَلَيْكُمْ وَما أَنْزَلَ عَلَيْكُمْ مِنَ الْكِتابِ وَالْحِكْمَةِ يَعِظُكُمْ بِهِ وَاتَّقُوا اللهَ وَاعْلَمُوا أَنَّ اللهَ بِكُلِّ شَيْءٍ عَلِيمٌ (231) وَإِذا طَلَّقْتُمُ النِّساءَ فَبَلَغْنَ أَجَلَهُنَّ الزوجة ( أَوْ سَرِّحُوهُنَ ) أي اتركوهن حتى تنقضي عدتهن ( بِمَعْرُوفٍ ) بإعطاء حقوقهن كاملة من غير إيذاء لهن ( وَلا تُمْسِكُوهُنَ ) بأن ترجعوا إليهن ( ضِراراً ) بقصد الإضرار بهن لتطويل العدة أو التضييق في النفقة ـ كما تقدم ـ ( لِتَعْتَدُوا ) عليهن وتظلموهن ( وَمَنْ يَفْعَلْ ذلِكَ ) الإمساك بقصد الإضرار ( فَقَدْ ظَلَمَ نَفْسَهُ ) لأنه أساء بسمعته عند الناس وعرض نفسه لعذاب الله وسخطه ( وَلا تَتَّخِذُوا آياتِ اللهِ ) أحكامه وأوامره ونواهيه ( هُزُواً ) سخرية بأن تستخفوا بها ( وَاذْكُرُوا نِعْمَةَ اللهِ عَلَيْكُمْ ) حيث أنعم عليكم بكل نعمه ، التي منها نعمة الزوجة التي تسكنون إليها وتقضون مآربكم بسببها ( وَ ) اذكروا ( ما أَنْزَلَ عَلَيْكُمْ مِنَ الْكِتابِ وَالْحِكْمَةِ ) فشرفكم بتعلمكم الأحكام وإرشادكم إلى ما يصلحكم ويهيئ لكم حياة سعيدة ( يَعِظُكُمْ بِهِ ) أي بذلك الكتاب ، وهذا إما صفة للكتاب أو جملة مستأنفة ( وَاتَّقُوا اللهَ ) في أوامره ونواهيه ( وَاعْلَمُوا أَنَّ اللهَ بِكُلِّ شَيْءٍ عَلِيمٌ ) فلا يفوته عملكم ونيتكم فلا تتعرضوا لسخطه وغضبه."},{"text":"۞ وَٱلْوَٰلِدَٰتُ يُرْضِعْنَ أَوْلَـٰدَهُنَّ حَوْلَيْنِ كَامِلَيْنِ ۖ لِمَنْ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَ ۚ وَعَلَى ٱلْمَوْلُودِ لَهُۥ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِٱلْمَعْرُوفِ ۚ لَا تُكَلَّفُ نَفْسٌ إِلَّا وُسْعَهَا ۚ لَا تُضَآرَّ وَٰلِدَةٌۢ بِوَلَدِهَا وَلَا مَوْلُودٌ لَّهُۥ بِوَلَدِهِۦ ۚ وَعَلَى ٱلْوَارِثِ مِثْلُ ذَٰلِكَ ۗ فَإِنْ أَرَادَا فِصَالًا عَن تَرَاضٍ مِّنْهُمَا وَتَشَاوُرٍ فَلَا جُنَاحَ عَلَيْهِمَا ۗ وَإِنْ أَرَدتُّمْ أَن تَسْتَرْضِعُوٓا۟ أَوْلَـٰدَكُمْ فَلَا جُنَاحَ عَلَيْكُمْ إِذَا سَلَّمْتُم مَّآ ءَاتَيْتُم بِٱلْمَعْرُوفِ ۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ","tafsir":"أي انقضت عدتهن ـ وذلك فَلا تَعْضُلُوهُنَّ أَنْ يَنْكِحْنَ أَزْواجَهُنَّ إِذا تَراضَوْا بَيْنَهُمْ بِالْمَعْرُوفِ ذلِكَ يُوعَظُ بِهِ مَنْ كانَ مِنْكُمْ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ ذلِكُمْ أَزْكى لَكُمْ وَأَطْهَرُ وَاللهُ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ (232) وَالْوالِداتُ يُرْضِعْنَ أَوْلادَهُنَّ حَوْلَيْنِ كامِلَيْنِ لِمَنْ أَرادَ أَنْ يُتِمَّ الرَّضاعَةَ بقرينة : أن ينكحن ـ ( فَلا تَعْضُلُوهُنَ ) أي لا تمنعوهن ظلما ( أَنْ يَنْكِحْنَ أَزْواجَهُنَ ) إلى الزوج السابق أو من تريد الزواج به فعلا وسمى زوجا للأول وربما قيل في وجه النزول أن معقل بن يسار عضل أخته جملاء أن ترجع إلى الزوج الأول وهو عاصم بن عدي حين طلقها وخرجت من العدة ثم أراد أن يجتمعا بنكاح جديد فمنعهما من ذلك ، ولو كان كذلك كان المراد بأزواجهن بالمعنى الأول فإنه لا يحق لأحد أن يمنع المرأة الثيبة في الرجوع إلى زوجها بنكاح جديد ( إِذا تَراضَوْا بَيْنَهُمْ بِالْمَعْرُوفِ ) مما أباحه شرع الإسلام من شروط النكاح وآداب العشرة ( ذلِكَ ) المذكور من تحريم العضل ( يُوعَظُ بِهِ مَنْ كانَ مِنْكُمْ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ ) فإن المؤمن يجتنب سخط الله ويبتغي رضاه ( ذلِكُمْ ) الذي ذكرنا في باب الزواج ( أَزْكى لَكُمْ ) أنمى لكم ( وَأَطْهَرُ ) لنفوسكم فإن في الزواج النسل والتحصن وسير الحياة إلى الأمام ( وَاللهُ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ ) فاتبعوا أوامره وانتهوا عن زواجره."},{"text":"وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًا يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا ۖ فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ بِٱلْمَعْرُوفِ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ","tafsir":"فإن الأم ترضع ولدها سنتين تامتين أربعة وعشرين شهرا ( لِمَنْ أَرادَ أَنْ يُتِمَّ الرَّضاعَةَ ) التي وَعَلَى الْمَوْلُودِ لَهُ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ لا تُكَلَّفُ نَفْسٌ إِلاَّ وُسْعَها لا تُضَارَّ والِدَةٌ بِوَلَدِها وَلا مَوْلُودٌ لَهُ بِوَلَدِهِ وَعَلَى الْوارِثِ مِثْلُ ذلِكَ ندب إليها الإسلام ومن العلماء من أوجب ذلك ( وَعَلَى الْمَوْلُودِ لَهُ ) أي الأب ، وإنما عبر بهذا التعبير إثارة للعاطفة ، له فإن الأب قد ولد له الولد فاللازم أن يحنو عليه ( رِزْقُهُنَ ) الإدام والطعام ( وَكِسْوَتُهُنَ ) اللباس ( بِالْمَعْرُوفِ ) لدى الشرع والعرف من اللائق بحالها فإن على الأب أن يقوم بهذه الشؤون ما دامت الأم في الرضاع ، وقد استفاد أكثر المفسرين من هذه الجملة كون الكلام حول الأم المطلقة وإلا فالرزق والكسوة على الزوج لأجل النكاح لا لأجل الرضاع ( لا تُكَلَّفُ نَفْسٌ إِلَّا وُسْعَها ) فكل من الأب والأم يؤدي واجبه في حدود طاقته فلا تتحمل الأم الرضاع بلا بدل ولا ينتفع الأب بولده في المستقبل مجانا فسعة هذه أن ترضع ببدل ، وسعة ذاك أن يدفع الأجر لما يعود نفعه إليه ( لا تُضَارَّ والِدَةٌ بِوَلَدِها ) بأن ترضع مجانا وبلا عوض باستغلال الأب عاطفة الأم للولد فلا ينفق عليها ، أو بمعنى أن الوالدة لا يؤخذ منها الولد ليعطي للأجنبية غيظا من الأب عليها فتضر بفراق ولدها ( وَلا ) يضار ( مَوْلُودٌ لَهُ ) أي الأب ( بِوَلَدِهِ ) بأن تستغل الأم عاطفة الأب نحو الولد فتكلفه أكثر من الكسوة والرزق قبال رضاعها ، أو لا يضر الأب بولده بأن يأخذه من الأم ويعطيه للأجنبية ، فإن لبن الأم أوفق بالولد ، والأول أقرب إلى السياق ( وَعَلَى الْوارِثِ ) للأب إذا مات الأب ( مِثْلُ ذلِكَ ) الرزق والكسوة للأم في حال رضاعها للولد ، فَإِنْ أَرادا فِصالاً عَنْ تَراضٍ مِنْهُما وَتَشاوُرٍ فَلا جُناحَ عَلَيْهِما وَإِنْ أَرَدْتُمْ أَنْ تَسْتَرْضِعُوا أَوْلادَكُمْ فَلا جُناحَ عَلَيْكُمْ إِذا سَلَّمْتُمْ ما آتَيْتُمْ بِالْمَعْرُوفِ وَاتَّقُوا اللهَ وَاعْلَمُوا أَنَّ اللهَ بِما تَعْمَلُونَ بَصِيرٌ (233) وَالَّذِينَ يُت َوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ ولا يخفى أن أجر رضاع الصبي مما يرثه الصبي من أبيه لدى موت الأب ( فَإِنْ أَرادا ) أي الأب والأم ( فِصالاً ) للولد عن الرضاع بأن يفطماه قبل الحولين ( عَنْ تَراضٍ مِنْهُما وَتَشاوُرٍ ) بأن تشاور الأبوان وتراضيا في فطام الولد قبل العامين وذلك لئلا يتضرر الصبي إذا استقل أحدهما بالفطام فإن الرضا المتعقب للمشورة لا يكون إلا إذا كان الانفصال صلاحا ( فَلا جُناحَ عَلَيْهِما ) أي على الأبوين في هذا الفطام ( وَإِنْ أَرَدْتُمْ ) أيها الآباء ( أَنْ تَسْتَرْضِعُوا أَوْلادَكُمْ ) بأن تستأجروا لهم مرضعات غير أمهاتهم ( فَلا جُناحَ ) ولا حرج ( عَلَيْكُمْ ) في ذلك ( إِذا سَلَّمْتُمْ ) إلى المرضعات ( ما آتَيْتُمْ ) ووعدتم لهن من الأجر ( بِالْمَعْرُوفِ ) أي تسليما بالمعروف بدون نقصان ومطل ومن ، وهذا شرط تكليفي لا وضعي ، كما هو كثير في القرآن الحكيم ، لغاية الإلفات إلى لزوم كون الأعمال عن صدق وإخلاص وتقوى ( وَاتَّقُوا اللهَ ) في أعمالكم التي منها الأحكام السالفة حول الرضاع ( وَاعْلَمُوا أَنَّ اللهَ بِما تَعْمَلُونَ بَصِيرٌ ) فلا يغيب شيء عنه ولا تخفى عليه خافية ، فلتكن أعمالكم حسب مراضيه وأوامره."},{"text":"وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُم بِهِۦ مِنْ خِطْبَةِ ٱلنِّسَآءِ أَوْ أَكْنَنتُمْ فِىٓ أَنفُسِكُمْ ۚ عَلِمَ ٱللَّهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ وَلَـٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّآ أَن تَقُولُوا۟ قَوْلًا مَّعْرُوفًا ۚ وَلَا تَعْزِمُوا۟ عُقْدَةَ ٱلنِّكَاحِ حَتَّىٰ يَبْلُغَ ٱلْكِتَـٰبُ أَجَلَهُۥ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِىٓ أَنفُسِكُمْ فَٱحْذَرُوهُ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٌ","tafsir":"أي الرجال الذين يموتون ( وَيَذَرُونَ أَزْواجاً يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْراً فَإِذا بَلَغْنَ أَجَلَهُنَّ فَلا جُناحَ عَلَيْكُمْ فِيما فَعَلْنَ فِي أَنْفُسِهِنَّ بِالْمَعْرُوفِ وَاللهُ بِما تَعْمَلُونَ خَبِيرٌ (234) وَلا جُناحَ عَلَيْكُمْ فِيما عَرَّضْتُمْ بِهِ مِنْ خِطْبَةِ النِّساءِ أَوْ أَكْنَنْتُمْ فِي أَنْفُسِكُمْ أَزْواجاً ) أي يخلفون زوجاتهم ( يَتَرَبَّصْنَ بِأَنْفُسِهِنَ ) أي يحفظن أنفسهن عن الزواج ولعل في قوله إشارة إلى أن النفس ولو كانت تطمح نحو الزواج لكن الواجب اصطبارها والتحفظ عليها ( أَرْبَعَةَ أَشْهُرٍ وَعَشْراً ) ففي هذه المدة يجب عليها الحداد بترك الزينة والخطبة ( فَإِذا بَلَغْنَ أَجَلَهُنَ ) وانقضت المدة ( فَلا جُناحَ عَلَيْكُمْ ) أيها المسلمون ( فِيما فَعَلْنَ فِي أَنْفُسِهِنَ ) من الزينة أو الخطبة أو النكاح فإنها ترجع إلى نفسها والناس مسلطون على أنفسهم ( بِالْمَعْرُوفِ ) بأن لا تعمل منكرا ينافي الإسلام ( وَاللهُ بِما تَعْمَلُونَ خَبِيرٌ ) فيطلع على أعمالهم ، ولا يفوته شيء من إطاعتكم ومخالفتكم."},{"text":"لَّا جُنَاحَ عَلَيْكُمْ إِن طَلَّقْتُمُ ٱلنِّسَآءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا۟ لَهُنَّ فَرِيضَةً ۚ وَمَتِّعُوهُنَّ عَلَى ٱلْمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلْمُقْتِرِ قَدَرُهُۥ مَتَـٰعًۢا بِٱلْمَعْرُوفِ ۖ حَقًّا عَلَى ٱلْمُحْسِنِينَ","tafsir":"إذا كانت المرأة في العدة ف ( لا جُناحَ عَلَيْكُمْ ) أيها الراغبون في الزواج منهن ( فِيما عَرَّضْتُمْ بِهِ مِنْ خِطْبَةِ النِّساءِ ) بأن تلمحوا إلى رغبتكم في الزواج منهن وتعرضوا على ذلك تعريضا وإشارة من طرف خفي ، لا تصريحا فإن ذلك خلاف الجو الذي يحيط بالمرأة المعتدة من الربط الباقي بينها وبين زوجها الأول ( أَوْ أَكْنَنْتُمْ فِي أَنْفُسِكُمْ ) بأن أضمرتم إرادة زواجهن بدون أن تصرحوا أو تلمحوا بذلك فإن الكناية عَلِمَ اللهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ وَلكِنْ لا تُواعِدُوهُنَّ سِرًّا إِلاَّ أَنْ تَقُولُوا قَوْلاً مَعْرُوفاً وَلا تَعْزِمُوا عُقْدَةَ النِّكاحِ حَتَّى يَبْلُغَ الْكِتابُ أَجَلَهُ وَاعْلَمُوا أَنَّ اللهَ يَعْلَمُ ما فِي أَنْفُسِكُمْ فَاحْذَرُوهُ وَاعْلَمُوا أَنَّ اللهَ غَفُورٌ حَلِيمٌ (235) اللفظية والإضمار القلبي لا جناح فيهما ( عَلِمَ اللهُ أَنَّكُمْ ) أيها الرجال ( سَتَذْكُرُونَهُنَ ) وهن في العدة إرادة للزواج بهن ( وَلكِنْ ) لا تصرحوا بالخطبة و ( لا تُواعِدُوهُنَّ سِرًّا ) في الخلوة فتبدوا رغبتكم في الزواج بهن في منأى من الناس ( إِلَّا أَنْ تَقُولُوا قَوْلاً مَعْرُوفاً ) بالكناية والتلميح لا بالتصريح وذكر ما يقبح ذكره كما كانت عادة بعض الناس. ( وَلا تَعْزِمُوا ) أي لا تقصدوا ( عُقْدَةَ النِّكاحِ ) أي إجراء الصيغة التي هي كعقدة تعقد النكاح بين الجانبين ، وقد نهى عن العزم على ذلك مبالغة ، كقوله : ( وَلا تَقْرَبُوا مالَ الْيَتِيمِ ) (1) ( حَتَّى يَبْلُغَ الْكِتابُ ) الذي كتبناه في باب العدة من أربعة أشهر وعشرا (2) ( أَجَلَهُ ) أي أمده ، بأن تنقضي العدة ( وَاعْلَمُوا أَنَّ اللهَ يَعْلَمُ ما فِي أَنْفُسِكُمْ ) من عزم النكاح فكيف بما تسرون به من نكاح المعتدة سرا ( فَاحْذَرُوهُ ) أن تخالفوه ( وَاعْلَمُوا أَنَّ اللهَ غَفُورٌ ) يستر عاجلا فلا يغرنكم ستره ( حَلِيمٌ ) عليم فلا يعجل بالعقوبة فلا يسبب ذلك جرأتكم على انتهاك حرماته. ( 1) الأنعام : 153. ( 2) راجع موسوعة الفقه : ج 70. لا جُناحَ عَلَيْكُمْ إِنْ طَلَّقْتُمُ النِّساءَ ما لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا لَهُنَّ فَرِيضَةً وَمَتِّعُوهُنَّ عَلَى الْمُوسِعِ قَدَرُهُ وَعَلَى الْمُقْتِرِ قَدَرُهُ مَتاعاً بِالْمَعْرُوفِ حَقًّا عَلَى الْمُحْسِنِينَ (236) وَإِنْ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ ف َرِيضَةً فَنِصْفُ ما فَرَضْتُمْ [237] وبعد بيان حكم موت الزوج ، يأتي حكم الطلاق ، والطلاق إن كان قبل الدخول ولم يذكر في العقد مهر فللمرأة المتعة ، وإن كان قبل الدخول وذكر المهر فللمرأة نصف المهر ( لا جُناحَ عَلَيْكُمْ ) أيها الأزواج ( إِنْ طَلَّقْتُمُ النِّساءَ ما لَمْ تَمَسُّوهُنَ ) بالدخول ( أَوْ تَفْرِضُوا لَهُنَّ فَرِيضَةً ) « أو » بمعنى الواو ، أي لم يكن شيء من الأمرين لا المس ولا المهر ، ويسمى المهر فريضة لأنه يجب إذا سمي ، والمعنى أنه يباح الطلاق قبل المس والفرض ، فلا يتوهم أحد أن النكاح لأجل الوطي فكيف يصح الطلاق قبله ( وَمَتِّعُوهُنَ ) أي أعطوهن المتعة وهي ما تتمتع به المرأة ويوجب تعويضا يجبر خاطرها الكسير ( عَلَى الْمُوسِعِ ) أي الغني يقال أوسع الرجل إذا كثر ماله ( قَدَرُهُ ) من دار أو خادم أو نحوهما ( وَعَلَى الْمُقْتِرِ ) أي الفقير يقال أقتر الرجل إذا افتقر ( قَدَرُهُ ) كخاتم أو درهم أو نحوهما ( مَتاعاً بِالْمَعْرُوفِ ) ليس فيه إسراف ولا تقصير ( حَقًّا عَلَى الْمُحْسِنِينَ ) الذين يحسنون طاعة الأوامر والانتهاء عن الزواجر."},{"text":"وَإِن طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةً فَنِصْفُ مَا فَرَضْتُمْ إِلَّآ أَن يَعْفُونَ أَوْ يَعْفُوَا۟ ٱلَّذِى بِيَدِهِۦ عُقْدَةُ ٱلنِّكَاحِ ۚ وَأَن تَعْفُوٓا۟ أَقْرَبُ لِلتَّقْوَىٰ ۚ وَلَا تَنسَوُا۟ ٱلْفَضْلَ بَيْنَكُمْ ۚ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ","tafsir":""},{"text":"حَـٰفِظُوا۟ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلْوُسْطَىٰ وَقُومُوا۟ لِلَّهِ قَـٰنِتِينَ","tafsir":"طلاقا قبل الدخول ( وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةً ) بأن عينتم في النكاح المهر فعليكم أن تدفعوا إلى المرأة نصف ( ما فَرَضْتُمْ ) نصف المهر ، هذا هو الحكم إِلاَّ أَنْ يَعْفُونَ أَوْ يَعْفُوَا الَّذِي بِيَدِهِ عُقْدَةُ النِّكاحِ وَأَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوى وَلا تَنْسَوُا الْفَضْلَ بَيْنَكُمْ إِنَّ اللهَ بِما تَعْمَلُونَ بَصِيرٌ (237) الواجب ( إِلَّا أَنْ يَعْفُونَ ) أي تعفي المرأة عن نصفها فلا تأخذ شيئا وتهب مالها إلى الزوج ( أَوْ يَعْفُوَا الَّذِي بِيَدِهِ عُقْدَةُ النِّكاحِ ) يمكن أن يراد به الزوج بأن يعفو عن نصفه فيعطي للمرأة جميع مهر المرأة ، وروي أن المراد عفو ولي الزوجة ، فيما إذا كان لها ولي مفروض كالصغيرة ، أو موكل من قبلها في الكبيرة ( وَأَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوى ) فإن من يترك حق نفسه تبرعا أقرب إلى التقوى بأن تبقى معصية الله فلا يطلب ما ليس له ( وَلا تَنْسَوُا الْفَضْلَ بَيْنَكُمْ ) بأن يتفضل بعضكم على بعض فيتنازل عن حقوقه لأجل صاحبه ولعل الفرق بين العفو والفضل أن العفو هبة جميع حقوقه والفضل هبة بعضها ( إِنَّ اللهَ بِما تَعْمَلُونَ بَصِيرٌ ) فيجازيكم على أعمالكم إن حسنا وإن سيئا. [239] إن القرآن الحكيم دائما يلطف أجواء الأحكام بتلميح إلى قدرة إله الكون وعظمته ورحمته وغفرانه ونحوها ليسمو بالنفس ويربط الحكم بالخالق حتى يكون أقرب إلى التنفيذ ، ولما طالت آيات الأحكام وبالأخص ما له جو كابت حزين من طلاق وموت ونحوهما أتت آيات الصلاة متداخلة بينها لتشع في النفس الطمأنينة والهدوء ( أَلا بِذِكْرِ اللهِ تَطْمَئِنُّ الْقُلُوبُ ) (1) مع مناسبة لهذه الآيات مع الجو العام لما قبلها ( 1) الرعد : 29. حَافِظُواْ عَلَى الصَّلَوَاتِ والصَّلاَةِ الْوُسْطَى وَقُومُواْ لِلّهِ قَانِتِينَ (238) فَإِنْ خِفْتُمْ فَرِجالاً أَوْ رُكْباناً فَإِذا أَمِنْتُمْ فَاذْكُرُوا اللهَ كَما عَلَّمَكُمْ ما لَمْ تَكُونُوا تَعْلَمُونَ (239) وَالَّذِينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ أَزْواجاً وبعدها حيث تعرضت لصلاة الخوف والمطاردة ، هذا ما أحتمله أن يكون سببا لذكر هذه الآيات هنا متوسطة أحكام الموت والطلاق ( حافِظُوا عَلَى الصَّلَواتِ ) كلها ( وَالصَّلاةِ الْوُسْطى ) خاصة وهي صلاة الظهر لأنها تتوسط بين النهار فإن الرسول صلى‌الله‌عليه‌وآله‌وسلم كان يصليها بالهاجرة في مسجد مكشوف فكانت أثقل صلاة عليهم ولذا لم يكن يحضرها إلا الصف والصفان فقط ، كما ورد عن بعض الصحابة ( وَقُومُوا ) أيها المسلمون ( لِلَّهِ قانِتِينَ ) أي داعين فإن القنوت هو الدعاء ، ومنه القنوت في الصلاة والمراد إما القنوت في الصلاة أو مطلقا."},{"text":"فَإِنْ خِفْتُمْ فَرِجَالًا أَوْ رُكْبَانًا ۖ فَإِذَآ أَمِنتُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ","tafsir":""},{"text":"وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًا وَصِيَّةً لِّأَزْوَٰجِهِم مَّتَـٰعًا إِلَى ٱلْحَوْلِ غَيْرَ إِخْرَاجٍ ۚ فَإِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَيْكُمْ فِى مَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ مِن مَّعْرُوفٍ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ","tafsir":"فلم تتمكنوا من المحافظة على الصلاة بشرائطها وآدابها ، حيث ابتليتم بالعدو الذي لا يسمح لكم بالصلاة الكاملة فصلوا رجالا جمع راجل أي مشاة ( أَوْ رُكْباناً ) جمع راكب أي على ظهور دوابكم ( فَإِذا أَمِنْتُمْ ) من الخوف ( فَاذْكُرُوا اللهَ ) صلاة كاملة ( كَما عَلَّمَكُمْ ما لَمْ تَكُونُوا تَعْلَمُونَ ) من أمور دينكم ودنياكم. [241] ثم رجع السياق إلى تتمة الأحكام السابقة ، بعد ما أشعّت في النفس الاطمئنان وندى الجو بذكر الصلاة ( وَالَّذِينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ أَزْواجاً ) « يتوفون » مجازا بالمشارفة ، فإنه كثيرا ما يعبر عمن شارف وَصِيَّةً لِأَزْواجِهِمْ مَتاعاً إِلَى الْحَوْلِ غَيْرَ إِخْراجٍ فَإِنْ خَرَجْنَ فَلا جُناحَ عَلَيْكُمْ فِي ما فَعَلْنَ فِي أَنْفُسِهِنَّ مِنْ مَعْرُوفٍ وَاللهُ عَزِيزٌ حَكِيمٌ (240) وَلِلْمُطَلَّقاتِ مَتاعٌ بِالْمَعْرُوفِ حَقًّا عَلَى الْمُتَّقِينَ (241) أمرا بالداخل فيه ، كما يعكس كثيرا فيعبر عن الداخل بالمشارف ، نحو ( لا تَقْرَبُوا مالَ الْيَتِيمِ ) و ( لا تَعْزِمُوا عُقْدَةَ النِّكاحِ ) فالمراد الذين يقاربون الوفاة ، ولهم زوجات فمن الأفضل أن يوصوا ( وَصِيَّةً لِأَزْواجِهِمْ ) بأن يمتعهن الوصي ( مَتاعاً إِلَى الْحَوْلِ ) فيعطي النفقة والكسوة إليهن إلى سنة كاملة ( غَيْرَ إِخْراجٍ ) أي في حال كونهن غير مخرجات إخراجا عن بيوت أزواجهن ( فَإِنْ خَرَجْنَ ) عن رغبتهن ( فَلا جُناحَ عَلَيْكُمْ ) أيها الأولياء ( فِي ما فَعَلْنَ فِي أَنْفُسِهِنَّ مِنْ مَعْرُوفٍ ) بالزواج والزينة بعد انقضاء عدة الوفاة ـ وهي أربعة أشهر وعشرا ـ فإن قبل ذلك لا يكون معروفا ، بل منكرا ( وَاللهُ عَزِيزٌ ) فيحكم بمقتضى عزته وسلطته ( حَكِيمٌ ) لا يحكم اعتباطا بل عن مصالح وعلل ، وهذه الآية حسب ما ذكرنا لها من المعنى لا تكون منسوخة بآية ( أَرْبَعَةَ أَشْهُرٍ وَعَشْراً ) ."},{"text":"وَلِلْمُطَلَّقَـٰتِ مَتَـٰعٌۢ بِٱلْمَعْرُوفِ ۖ حَقًّا عَلَى ٱلْمُتَّقِينَ","tafsir":""},{"text":"كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَـٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ","tafsir":"يمتعهن الأزواج بشيء سواء كن واجبة النفقة أم لا ( بِالْمَعْرُوفِ ) فإن ذلك يسبب رفع الغضاضة ( حَقًّا عَلَى الْمُتَّقِينَ ) الذين يتقون مخالفة أوامر الله سبحانه إيجابا كانت أو ندبا. كَذلِكَ يُبَيِّنُ اللهُ لَكُمْ آياتِهِ لَعَلَّكُمْ تَعْقِلُونَ (242) أَ لَمْ تَرَ إِلَى الَّذِينَ خَرَجُوا مِنْ دِيارِهِمْ وَهُمْ أُلُوفٌ حَذَرَ الْمَوْتِ فَقالَ لَهُمُ اللهُ مُوتُوا ثُمَّ أَحْياهُمْ إِنَّ اللهَ لَذُو"},{"text":"۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ خَرَجُوا۟ مِن دِيَـٰرِهِمْ وَهُمْ أُلُوفٌ حَذَرَ ٱلْمَوْتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُوا۟ ثُمَّ أَحْيَـٰهُمْ ۚ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ","tafsir":"الذي بين الله لكم الأحكام ( يُبَيِّنُ اللهُ لَكُمْ آياتِهِ لَعَلَّكُمْ تَعْقِلُونَ ) أي لكي تعقلوا آياته وأحكامه. [244] ومن جو الأسرة وامتدادها وانقطاعها ينتقل السياق إلى قصة الحياة والموت التي تشبه قصة الأسرة في كونها امتدادا للحياة العائلية وانقطاعا لها في قصة عجيبة هي : أن أهل مدينة من مدائن الشام كانوا سبعين ألف بيت هربوا من الطاعون فمروا بمدينة خربة قد جلا أهلها عنها وأفناهم الطاعون فنزلوا بها فأماتهم الله من ساعتهم جميعا وصاروا رميما يلوح ، فمر بهم نبي من أنبياء بني إسرائيل يقال له « حزقيل » فبكى واستعبر وقال : يا رب لو شئت لأحييتهم الساعة كما أمتهم ، فعمروا بلادك وولدوا عبادك وعبدوك مع من يعبدك ، فأوحى الله إليه أن يقول الاسم الأعظم فقاله عليهم فعادوا أحياء ينظر بعضهم إلى بعض يسبحون الله ويكبرونه ويهللونه ( أَ لَمْ تَرَ ) استفهام تقريري أي ألم تعلم فإن الرؤية تأتي بمعنى العلم كقول الشاعر : « رأيت الله أكبر كل شيء » وقد يستفهم بمثل هذا الاستفهام لإيجاد العلم ( إِلَى الَّذِينَ خَرَجُوا مِنْ دِيارِهِمْ وَهُمْ أُلُوفٌ ) سبعون ألفا كما تقدم ( حَذَرَ الْمَوْتِ ) وفرارا من الطاعون ( فَقالَ لَهُمُ اللهُ مُوتُوا ) فأماتهم حيث ظنوا الهرب ( ثُمَّ أَحْياهُمْ ) بدعاء النبي حزقيل عليه‌السلام ( إِنَّ اللهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلكِنَّ أَكْثَرَ النَّاسِ لا يَشْكُرُونَ (243) وَقاتِلُوا فِي سَبِيلِ اللهِ وَاعْلَمُوا أَنَّ اللهَ سَمِيعٌ عَلِيمٌ (244) مَنْ ذَا الَّذِي يُقْرِضُ اللهَ قَرْضاً حَسَناً فَيُضاعِفَهُ لَهُ أَضْعافاً كَثِيرَةً وَاللهُ يَقْبِضُ وَيَبْصُطُ وَإِلَيْهِ تُرْجَعُونَ (245) فَضْلٍ عَلَى النَّاسِ ) كلهم بخلقهم ورزقهم وتدبير أمورهم ( وَلكِنَّ أَكْثَرَ النَّاسِ لا يَشْكُرُونَ ) نعمه وفضله عليهم بل يقللون فضله بالعصيان."},{"text":"وَقَـٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ","tafsir":""},{"text":"مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًا فَيُضَـٰعِفَهُۥ لَهُۥٓ أَضْعَافًا كَثِيرَةً ۚ وَٱللَّهُ يَقْبِضُ وَيَبْصُۜطُ وَإِلَيْهِ تُرْجَعُونَ","tafsir":"إذ علمتم أن الهروب من الموت لا ينفع ف ( قاتِلُوا فِي سَبِيلِ اللهِ ) ولا تهربوا خوف الموت ( وَاعْلَمُوا أَنَّ اللهَ سَمِيعٌ ) لأقوالكم ( عَلِيمٌ ) بنياتكم وأعمالكم. [246] إن القتال بإعطاء المال والنفس في سبيل الله ليس هدرا وإنما المقاتل والعامل للبر ، يقرض الله بما يذهب منه ثم يرجعه سبحانه إليه ف ( مَنْ ذَا الَّذِي يُقْرِضُ اللهَ قَرْضاً حَسَناً ) أي أيّ شخص ذاك الذي يقرض الله وينفق نفسه وماله في سبيله قرضا حسنا لا لرياء وسمعة ولا بمنّ وإكراه وسائر ما يشين القرض ( فَيُضاعِفَهُ لَهُ أَضْعافاً كَثِيرَةً ) ربما بلغت الملايين وعما ذا تخافون في قرض أموالكم هل من الفقر ؟ ( وَاللهُ يَقْبِضُ ) فيفقر ( وَيَبْصُطُ ) فيغني فلا ينفعكم البخل ولا يضركم القرض والسخاء ، أم تخافون في قرض أنفسكم لله من الموت ؟ ( وَإِلَيْهِ تُرْجَعُونَ ) فيعطيكم أفضل مما أخذ منكم ، قال الإمام أمير أَ لَمْ تَرَ إِلَى الْمَلَإِ مِنْ بَنِي إِسْرائِيلَ مِنْ بَعْدِ مُوسى إِذْ قالُوا لِنَبِيٍّ لَهُمُ ابْعَثْ لَنا مَلِكاً نُقاتِلْ فِي سَبِيلِ اللهِ قالَ هَلْ عَسَيْتُمْ إِنْ كُتِبَ عَلَيْكُمُ الْقِتالُ أَلاَّ تُقاتِلُوا قالُوا وَما لَنا أَلاَّ نُقاتِلَ فِي سَبِيلِ اللهِ وَقَدْ أُخْرِجْنا مِنْ دِيارِنا وَأَبْنائِنا المؤمنين عليه‌السلام لأحد أولاده « أعر الله جمجمتك » (1) . [247] وهنا قصة حياة أو موت أخرى تناسب القصة السابقة ( أَ لَمْ تَرَ ) أي ألم تعلم ـ كما تقدم ـ ( إِلَى الْمَلَإِ ) أي الجماعة ( مِنْ بَنِي إِسْرائِيلَ مِنْ بَعْدِ مُوسى ) النبي ( إِذْ قالُوا لِنَبِيٍّ لَهُمُ ) هو أشموئيل وبالعربية إسماعيل ( ابْعَثْ لَنا مَلِكاً ) أي سلطانا ( نُقاتِلْ فِي سَبِيلِ اللهِ ) تحت لوائه حيث أذلهم الجبابرة وأخرجتهم من بلادهم وقتلتهم وسبيت ذراريهم ونسائهم وكان النبي في ذلك الزمان ينظم أمور الدين والملك وينظم أمور الجيش والسلطة ( قالَ ) النبي ( هَلْ عَسَيْتُمْ ) أي لعلكم ( إِنْ كُتِبَ عَلَيْكُمُ الْقِتالُ أَلَّا تُقاتِلُوا ) أراد بذلك أخذ العهد عليهم في المقاتلة إن عيّن ملك لهم ( قالُوا ) أي قال الملأ في جواب النبي عليه‌السلام ( وَما لَنا أَلَّا نُقاتِلَ فِي سَبِيلِ اللهِ ) أي ليس بإمكاننا أن نترك القتال ( وَقَدْ أُخْرِجْنا مِنْ دِيارِنا ) أخرجنا الأعداء من بلادنا ( وَأَبْنائِنا ) أي إخراجنا من أبنائنا حيث قتل بعضهم وسبي البعض ، ( 1) نهج البلاغة : ص 64. فَلَمَّا كُتِبَ عَلَيْهِمُ الْقِتالُ تَوَلَّوْا إِلاَّ قَلِيلاً مِنْهُمْ وَاللهُ عَلِيمٌ بِالظَّالِمِينَ (246) وَقالَ لَهُمْ نَبِيُّهُمْ إِنَّ اللهَ قَدْ بَعَثَ لَكُمْ طالُوتَ مَلِكاً قالُوا أَنَّى يَكُونُ لَهُ الْمُلْكُ عَلَيْنا وَنَحْنُ أَحَقُّ بِالْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَةً مِنَ الْمالِ قالَ إِنَّ اللهَ اصْطَفاهُ عَلَيْكُمْ وَزادَهُ بَسْطَةً فِي الْعِلْمِ فسأل النبي عليه‌السلام من الله ذلك ، فاستجاب الله دعاءه وعين لهم ملكا وكتب عليهم القتال ( فَلَمَّا كُتِبَ عَلَيْهِمُ الْقِتالُ تَوَلَّوْا ) أدبروا وكرهوا القتال ( إِلَّا قَلِيلاً مِنْهُمْ وَاللهُ عَلِيمٌ بِالظَّالِمِينَ ) الذين فروا من الجهاد بعد طلب منهم وإلحاح."},{"text":"أَلَمْ تَرَ إِلَى ٱلْمَلَإِ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ مِنۢ بَعْدِ مُوسَىٰٓ إِذْ قَالُوا۟ لِنَبِىٍّ لَّهُمُ ٱبْعَثْ لَنَا مَلِكًا نُّقَـٰتِلْ فِى سَبِيلِ ٱللَّهِ ۖ قَالَ هَلْ عَسَيْتُمْ إِن كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ أَلَّا تُقَـٰتِلُوا۟ ۖ قَالُوا۟ وَمَا لَنَآ أَلَّا نُقَـٰتِلَ فِى سَبِيلِ ٱللَّهِ وَقَدْ أُخْرِجْنَا مِن دِيَـٰرِنَا وَأَبْنَآئِنَا ۖ فَلَمَّا كُتِبَ عَلَيْهِمُ ٱلْقِتَالُ تَوَلَّوْا۟ إِلَّا قَلِيلًا مِّنْهُمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّـٰلِمِينَ","tafsir":""},{"text":"وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ٱللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكًا ۚ قَالُوٓا۟ أَنَّىٰ يَكُونُ لَهُ ٱلْمُلْكُ عَلَيْنَا وَنَحْنُ أَحَقُّ بِٱلْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَةً مِّنَ ٱلْمَالِ ۚ قَالَ إِنَّ ٱللَّهَ ٱصْطَفَىٰهُ عَلَيْكُمْ وَزَادَهُۥ بَسْطَةً فِى ٱلْعِلْمِ وَٱلْجِسْمِ ۖ وَٱللَّهُ يُؤْتِى مُلْكَهُۥ مَن يَشَآءُ ۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ","tafsir":""},{"text":"وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ءَايَةَ مُلْكِهِۦٓ أَن يَأْتِيَكُمُ ٱلتَّابُوتُ فِيهِ سَكِينَةٌ مِّن رَّبِّكُمْ وَبَقِيَّةٌ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَـٰرُونَ تَحْمِلُهُ ٱلْمَلَـٰٓئِكَةُ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ","tafsir":"أشموئيل ( إِنَّ اللهَ قَدْ بَعَثَ لَكُمْ ) وعين عليكم ( طالُوتَ مَلِكاً ) وكان من أبناء « بن يامين » أخي يوسف عليه‌السلام ولم يكن من سبط النبوة ولا من سبط المملكة ، فإن النبوة كانت في أولاد « لاوي » ابن يعقوب عليه‌السلام ، والمملكة كانت في أولاد « يهوذا » ابن يعقوب عليه‌السلام ( قالُوا أَنَّى ) أي كيف ( يَكُونُ لَهُ الْمُلْكُ عَلَيْنا ) ويجعل سلطانا وملكا لنا ( وَنَحْنُ أَحَقُّ بِالْمُلْكِ مِنْهُ ) لأنا من أسباط النبوة والمملكة ( وَلَمْ يُؤْتَ سَعَةً مِنَ الْمالِ ) فهو فقير لا مال له والملك يحتاج إلى المال ليدير شؤون السلطة ( قالَ ) النبي عليه‌السلام في جوابهم ( إِنَّ اللهَ اصْطَفاهُ عَلَيْكُمْ ) والله لا يصطفي إلا من هو الأصلح بحال عباده ( وَزادَهُ بَسْطَةً ) أي سعة وزيادة ( فِي الْعِلْمِ ) والمملكة تحتاج وَالْجِسْمِ وَاللهُ يُؤْتِي مُلْكَهُ مَنْ يَشاءُ وَاللهُ واسِعٌ عَلِيمٌ (247) وَقالَ لَهُمْ نَبِيُّهُمْ إِنَّ آيَةَ مُلْكِهِ أَنْ يَأْتِيَكُمُ التَّابُوتُ فِيهِ سَكِينَةٌ مِنْ رَبِّكُمْ إلى علم الملك ليتمكن به من إدارتها ( وَالْجِسْمِ ) فهو رجل سمين يهابه الناس ، شجاع يخافه الأعداء وهذه الأمور هي مقومات الملك لا المال فإن العلم والشجاعة والهيبة تأتي بالمال ، وليس بالعكس ( وَ ) ليس كونه من « بن يامين » نقصا فكما جعل الله الملك في بيت « يهوذا » سابقا يجعله في « طالوت » حالا فإن ( اللهُ يُؤْتِي مُلْكَهُ مَنْ يَشاءُ ) وليس احتكارا على أحد ( وَاللهُ واسِعٌ ) قدرة وعطاء فيهب الملك لمن يشاء ( عَلِيمٌ ) بمصالح العباد فلا يجعل شيئا إلا إذا كان صالحا."},{"text":"فَلَمَّا فَصَلَ طَالُوتُ بِٱلْجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبْتَلِيكُم بِنَهَرٍ فَمَن شَرِبَ مِنْهُ فَلَيْسَ مِنِّى وَمَن لَّمْ يَطْعَمْهُ فَإِنَّهُۥ مِنِّىٓ إِلَّا مَنِ ٱغْتَرَفَ غُرْفَةًۢ بِيَدِهِۦ ۚ فَشَرِبُوا۟ مِنْهُ إِلَّا قَلِيلًا مِّنْهُمْ ۚ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ قَالُوا۟ لَا طَاقَةَ لَنَا ٱلْيَوْمَ بِجَالُوتَ وَجُنُودِهِۦ ۚ قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَـٰقُوا۟ ٱللَّهِ كَم مِّن فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةًۢ بِإِذْنِ ٱللَّهِ ۗ وَٱللَّهُ مَعَ ٱلصَّـٰبِرِينَ","tafsir":"أشموئيل زيادة في الدلالة على جعل الله « طالوت » ملكا عليهم ( إِنَّ آيَةَ مُلْكِهِ ) وأن الله تعالى جعله ملكا ( أَنْ يَأْتِيَكُمُ التَّابُوتُ ) وهو تابوت أنزله الله على أم موسى فوضعت موسى فيه حين ألقته في البحر وكان بنوا إسرائيل يتبركون به فلما حضر موسى الموت وضع فيه الألواح ودرعه وما كان عنده من آيات النبوة وأودعه يوشع وصيه فلم يزل التابوت بينهم حتى استخفوا به وكان الصبيان يلعبون به في الطرقات فلم يزل بنوا إسرائيل في عز وشرف ما دام التابوت بينهم فلما عملوا بالمعاصي واستخفوا بالتابوت رفعه الله عنهم ثم جعل رد التابوت عليهم دليلا على أنه جعل الله طالوت ملكا ( فِيهِ سَكِينَةٌ مِنْ رَبِّكُمْ ) تسكنون وَبَقِيَّةٌ مِمَّا تَرَكَ آلُ مُوسى وَآلُ هارُونَ تَحْمِلُهُ الْمَلائِكَةُ إِنَّ فِي ذلِكَ لَآيَةً لَكُمْ إِنْ كُنْتُمْ مُؤْمِنِينَ (248) فَلَمَّا فَصَلَ طالُوتُ بِالْجُنُودِ قالَ إِنَّ اللهَ مُبْتَلِيكُمْ بِنَهَرٍ فَمَنْ شَرِبَ مِنْهُ فَلَيْسَ مِنِّي إليه وتعلمون أنكم منصورون بسببه ويكون دليلا على ملك طالوت ( وَبَقِيَّةٌ مِمَّا تَرَكَ آلُ مُوسى وَآلُ هارُونَ ) عصا موسى عليه‌السلام والألواح وطست خاص بالأنبياء عليهم‌السلام وأشياء أخر ، فإنها وصلت بالإرث إلى آل هذين النبيين المعظمين وهم جعلوها في التابوت ( تَحْمِلُهُ الْمَلائِكَةُ ) حملا واقعيا أو حملا ظاهرا بأن رأى بنوا إسرائيل الملائكة بين السماء والأرض أتت بالتابوت ( إِنَّ فِي ذلِكَ ) التابوت الذي رجع إليكم بعد فقده ( لَآيَةً لَكُمْ ) على كون طالوت ملكا ( إِنْ كُنْتُمْ مُؤْمِنِينَ ) مصدقين ، أي إن كنتم مؤمنين قلبا ، تصدقون ذلك."},{"text":"وَلَمَّا بَرَزُوا۟ لِجَالُوتَ وَجُنُودِهِۦ قَالُوا۟ رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَـٰفِرِينَ","tafsir":"رأى بنوا إسرائيل التابوت صدقوا وانضووا تحت لواء طالوت ، وتحركوا نحو الجهاد مع أعدائهم ولما ( فَصَلَ ) خرج وانفصل عن المدينة ( طالُوتُ بِالْجُنُودِ ) الذين كانوا معه ( قالَ ) طالوت ممتحنا للجنود حتى يتبين مقدار صبرهم وثباتهم على المكاره وأنهم إن جازوا من نهر الماء عطاشا يوثق بهم في الحرب وإن لم يسمعوا ولم يتمكنوا من الصبر على عطش قليل فهم أحرى بأن لا يصبروا أمام السيوف والرماح ( إِنَّ اللهَ مُبْتَلِيكُمْ ) ممتحنكم ( بِنَهَرٍ ) من ماء في طريقكم ( فَمَنْ شَرِبَ مِنْهُ فَلَيْسَ مِنِّي ) ممن يتبعني وَمَنْ لَمْ يَطْعَمْهُ فَإِنَّهُ مِنِّي إِلاَّ مَنِ اغْتَرَفَ غُرْفَةً بِيَدِهِ فَشَرِبُوا مِنْهُ إِلاَّ قَلِيلاً مِنْهُمْ فَلَمَّا جاوَزَهُ هُوَ وَالَّذِينَ آمَنُوا مَعَهُ قالُوا لا طاقَةَ لَنَا الْيَوْمَ بِجالُوتَ وَجُنُودِهِ قالَ الَّذِينَ يَظُنُّونَ أَنَّهُمْ مُلاقُوا اللهِ كَمْ مِنْ فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةً بِإِذْنِ اللهِ وَاللهُ مَعَ الصَّابِرِينَ (249) ولينصرف ( وَمَنْ لَمْ يَطْعَمْهُ ) أي لم يذق طعم ذلك الماء ( فَإِنَّهُ مِنِّي ) ويتبعني ( إِلَّا مَنِ اغْتَرَفَ غُرْفَةً ) واحدة ( بِيَدِهِ ) فشربها فقط لا أكثر من ذلك ( فَشَرِبُوا مِنْهُ ) من النهر ( إِلَّا قَلِيلاً مِنْهُمْ ) الذين أطاعوا أمر طالوت فلم يشربوا إلا غرفة واحدة و هؤلاء الذين أطاعوا هم الذين اتبعوا طالوت إلى الحرب أما من عصاه فلم يتبعه ( فَلَمَّا جاوَزَهُ هُوَ ) أي جاوز طالوت النهر ( وَالَّذِينَ آمَنُوا مَعَهُ ) ممن تبعه ولم يشرب الماء إلا غرفة ( قالُوا لا طاقَةَ لَنَا الْيَوْمَ بِجالُوتَ ) وهو رئيس الكفار ( وَجُنُودِهِ ) لما رأوا من كثرتهم ( قالَ الَّذِينَ يَظُنُّونَ أَنَّهُمْ مُلاقُوا اللهِ ) من أصحاب طالوت ، وفي قوله « يظنون » إشارة إلى أن الظن بالمعاد كاف في تحفيز الإنسان نحو الجهاد والأعمال الصالحة ، وملاقاة الله كناية عن القيامة لأنهم يلاقون جزاء الله ( كَمْ مِنْ فِئَةٍ ) أي جماعة ( قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةً بِإِذْنِ اللهِ ) أي بنصره ( وَاللهُ مَعَ الصَّابِرِينَ ) الذين يصبرون على المكاره ويثبتون عند ملاقاة الكفار ، وبهذا الكلام شجعوا أنفسهم وأصحابهم لمقابلة جالوت وجنوده. وَلَمَّا بَرَزُوا لِجالُوتَ وَجُنُودِهِ قالُوا رَبَّنا أَفْرِغْ عَلَيْنا صَبْراً وَثَبِّتْ أَقْدامَنا وَانْصُرْنا عَلَى الْقَوْمِ الْكافِرِينَ (250) فَهَزَمُوهُمْ بِإِذْنِ اللهِ وَقَتَلَ داوُدُ جالُوتَ وَآتاهُ اللهُ الْمُلْكَ وَالْحِكْمَةَ وَعَلَّمَهُ مِمَّا يَشاءُ وَلَوْ لا دَفْعُ اللهِ النَّاسَ بَعْضَهُمْ بِبَعْضٍ لَفَسَدَتِ الْأَرْضُ وَلكِنَّ اللهَ ذُو"},{"text":"فَهَزَمُوهُم بِإِذْنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ وَٱلْحِكْمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُ ۗ وَلَوْلَا دَفْعُ ٱللَّهِ ٱلنَّاسَ بَعْضَهُم بِبَعْضٍ لَّفَسَدَتِ ٱلْأَرْضُ وَلَـٰكِنَّ ٱللَّهَ ذُو فَضْلٍ عَلَى ٱلْعَـٰلَمِينَ","tafsir":"أي ظهروا في محل الحرب ( لِجالُوتَ وَجُنُودِهِ ) الكثيرة ( قالُوا ) أي قال طالوت والمؤمنون ( رَبَّنا أَفْرِغْ ) أي أصبب ( عَلَيْنا صَبْراً ) لنكون صابرين في الحرب ( وَثَبِّتْ أَقْدامَنا ) حتى لا نفر ( وَانْصُرْنا عَلَى الْقَوْمِ الْكافِرِينَ ) فاستجاب الله سبحانه دعاءهم."},{"text":"تِلْكَ ءَايَـٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ ۚ وَإِنَّكَ لَمِنَ ٱلْمُرْسَلِينَ","tafsir":"أي هزم طالوت والمؤمنون ، جالوت والكفار ( بِإِذْنِ اللهِ ) ونصره ( وَقَتَلَ داوُدُ ) النبي عليه‌السلام وهو أبو سليمان عليه‌السلام ( جالُوتَ ) رئيس الكفار فإن داود أخذ حصاة ورماها بالمقلاع نحو جالوت فأصابت جبهته وكانت فيها ياقوتة فانتشرت ووصلت إلى دماغه وخر ميتا وهزم الكفار ( وَآتاهُ ) أي أعطى ( اللهِ ) داود عليه‌السلام ( الْمُلْكَ وَالْحِكْمَةَ ) فصار نبيا وملكا ( وَعَلَّمَهُ مِمَّا يَشاءُ ) من العلوم الدنيوية والأخروية ( وَلَوْ لا دَفْعُ اللهِ النَّاسَ بَعْضَهُمْ بِبَعْضٍ ) بأن يدفع الكافرين المفسدين بسبب المؤمنين المصلحين ( لَفَسَدَتِ الْأَرْضُ ) لما يوجدون فيها من القتل والحرق والسبي والإفساد ( وَلكِنَّ اللهَ ذُو فَضْلٍ عَلَى الْعالَمِينَ (251) تِلْكَ آياتُ اللهِ نَتْلُوها عَلَيْكَ بِالْحَقِّ وَإِنَّكَ لَمِنَ الْمُرْسَلِينَ (252) فَضْلٍ عَلَى الْعالَمِينَ ) فيدفع الفاسد بالصالح لتبقى الأرض عامرة وينمو الزرع والضرع."},{"text":"۞ تِلْكَ ٱلرُّسُلُ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍ ۘ مِّنْهُم مَّن كَلَّمَ ٱللَّهُ ۖ وَرَفَعَ بَعْضَهُمْ دَرَجَـٰتٍ ۚ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَـٰتِ وَأَيَّدْنَـٰهُ بِرُوحِ ٱلْقُدُسِ ۗ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلَ ٱلَّذِينَ مِنۢ بَعْدِهِم مِّنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَـٰتُ وَلَـٰكِنِ ٱخْتَلَفُوا۟ فَمِنْهُم مَّنْ ءَامَنَ وَمِنْهُم مَّن كَفَرَ ۚ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلُوا۟ وَلَـٰكِنَّ ٱللَّهَ يَفْعَلُ مَا يُرِيدُ","tafsir":"أي تلك التي ذكرت من إماتة الأحياء دفعة وإحياء الموتى دفعة وتمليك طالوت ونصرة المؤمنين على أعدائهم دلالات الله على وجوده وقدرته وعلمه وسائر صفاته ( نَتْلُوها ) نقرؤها ( عَلَيْكَ ) يا رسول الله ( بِالْحَقِ ) أي بالصدق فلا كذب فيها وأنزلت لأجل الصدق لا لأجل الباطل والكذب والغش ( وَإِنَّكَ لَمِنَ الْمُرْسَلِينَ ) حيث تخبر بهذه الأخبار عن غيب بدلالة الله لك ووحيه إياها إليك. تقريب القران الى الأذهان من آية ( 254) سورة البقرة إلى ( 93) سورة آل عمران بسم الله الرّحمن الرّحيم الحمد لله ربّ العالمين ، والصلاة والسّلام على أشرف الأنبياء والمرسلين محمّد المصطفى وعترته الطّاهرين. تِلْكَ الرُّسُلُ فَضَّلْنا بَعْضَهُمْ عَلى بَعْضٍ مِنْهُمْ مَنْ كَلَّمَ اللهُ وَرَفَعَ بَعْضَهُمْ دَرَجاتٍ وَآتَيْنا عِيسَى ابْنَ مَرْيَمَ الْبَيِّناتِ وَأَيَّدْناهُ بِرُوحِ الْقُدُسِ وَلَوْ شاءَ اللهُ مَا اقْتَتَلَ الَّذِينَ مِنْ بَعْدِهِمْ"},{"text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِمَّا رَزَقْنَـٰكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خُلَّةٌ وَلَا شَفَـٰعَةٌ ۗ وَٱلْكَـٰفِرُونَ هُمُ ٱلظَّـٰلِمُونَ","tafsir":"الذين أشير إليهم في قوله ( إِنَّكَ لَمِنَ الْمُرْسَلِينَ ) ( فَضَّلْنا بَعْضَهُمْ عَلى بَعْضٍ ) فهم وإن اشتركوا في أصل الرسالة إلا أنهم مختلفين في الفضيلة ( مِنْهُمْ مَنْ كَلَّمَ اللهُ ) إياه وهو موسى عليه‌السلام وحيث أن هناك محل سؤال : هل يمكن للإنسان أن يرتقي هذا المرتقى العظيم حتى يكلمه الله سبحانه ؟ ألمحت الآية إلى ذلك قائلة : ( وَرَفَعَ بَعْضَهُمْ دَرَجاتٍ ) لا درجة واحدة ، حتى سببت تلك الرفعة أن يتمكن من مكالمة الله مباشرة ( وَآتَيْنا عِيسَى ابْنَ مَرْيَمَ الْبَيِّناتِ ) وأنه لمن تفنن القرآن الحكيم في التعبير حيث لم يصرح باسم موسى وصرح باسم عيسى عليه‌السلام والبينات هي الدلالات الواضحات على نبوته من إحياء الموتى وإبراء الأكمه والأبرص ( وَأَيَّدْناهُ ) أي قويناه فإن التأييد بمعنى التقوية ( بِرُوحِ الْقُدُسِ ) أي روح مقدسة ، كما مر سابقا فلم يكن إنسانا عاديا ولا خالقا وربا وإنما نبي مؤيد من عند الله سبحانه ، وحيث كان هنا مجال سؤال هو أن الأنبياء عليهم‌السلام حيث أتوا بالدلالات لم يكن مجال لتشكيك الناس فيهم فكيف تقع الحروب بين الناس حول الأنبياء إثباتا أو نفيا أو إثباتا لنبي دون نبي ؟ أتى السياق مشيرا إلى جواب ذلك ( وَلَوْ شاءَ اللهُ ) بأن ألجأ الناس واضطرهم على الانقياد والاهتداء ( مَا اقْتَتَلَ الَّذِينَ مِنْ بَعْدِهِمْ ) أي من بعد الرسل أي بعد مجيء كل واحد منهم مِنْ بَعْدِ ما جاءَتْهُمُ الْبَيِّناتُ وَلكِنِ اخْتَلَفُوا فَمِنْهُمْ مَنْ آمَنَ وَمِنْهُمْ مَنْ كَفَرَ وَلَوْ شاءَ اللهُ مَا اقْتَتَلُوا وَلكِنَّ اللهَ يَفْعَلُ ما يُرِيدُ (253) يا أَيُّهَا الَّذِينَ آمَنُوا أَنْفِقُوا مِمَّا رَزَقْناكُمْ مِنْ قَبْلِ أَنْ يَأْتِيَ يَوْمٌ لا بَيْعٌ فِيهِ وَلا خُلَّةٌ وَلا شَفاعَةٌ ( مِنْ بَعْدِ ما جاءَتْهُمُ الْبَيِّناتُ ) أي جاءت الناس الأدلة الواضحة ( وَلكِنِ اخْتَلَفُوا ) أي الناس ( فَمِنْهُمْ مَنْ آمَنَ وَمِنْهُمْ مَنْ كَفَرَ ) بالرسول ( وَلَوْ شاءَ اللهُ مَا اقْتَتَلُوا ) تكريرا للتأكيد وأن المشيئة الإلجائية لم تتعلق حول التشريع وإن تعلقت حول التكوين ( وَلكِنَّ اللهَ يَفْعَلُ ما يُرِيدُ ) من إعطاء الاختيار بيد الإنسان ليؤمن من آمن عن اختيار ويكفر من كفر عن اختيار ليثبت الجزاء والحساب ولم يذكر الرسول صلى‌الله‌عليه‌وآله‌وسلم لأن الخطاب موجه إليه ( وَإِنَّكَ لَمِنَ الْمُرْسَلِينَ ) . [255] وحيث أن القتال يحتاج إلى الإنفاق يزاوج القرآن الحكيم في آياته بين الأمرين كثيرا ( يا أَيُّهَا الَّذِينَ آمَنُوا أَنْفِقُوا مِمَّا رَزَقْناكُمْ ) من مختلف أنواع الرزق ، ولعل عمومه يشمل مثل التعليم والشفاعة ونحوها فإن العلم والوجاهة من رزق الله سبحانه ( مِنْ قَبْلِ أَنْ يَأْتِيَ يَوْمٌ لا بَيْعٌ فِيهِ ) حتى يشتري الإنسان نفسه بشيء فينجيها من عذاب الله سبحانه ( وَلا خُلَّةٌ ) أي صداقة فيراعى الصديق المذنب لأجل صديقه ، أو صداقة بين الله وبين أحد حتى يراعيه ويغفر ذنبه لصداقته ( وَلا شَفاعَةٌ ) كشفاعات الدنيا حيث أن الشفيع ينبعث من نفسه فيشفع للمذنب ، فإن هناك لا يشفعون إلا لمن ارتضى وَالْكافِرُونَ هُمُ الظَّالِمُونَ (254) اللهُ لا إِلهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ لا تَأْخُذُهُ سِنَةٌ وَلا نَوْمٌ لَهُ ما فِي السَّماواتِ وَما فِي الْأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلاَّ بِإِذْنِهِ يَعْلَمُ ما بَيْنَ أَيْدِيهِمْ وَما خَلْفَهُمْ وَلا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلاَّ بِما شاءَ ( وَالْكافِرُونَ هُمُ الظَّالِمُونَ ) فليس حرمان الكافر في ذلك اليوم لأجل الظلم من قبل الله سبحانه بل الكافر هو الظالم الذي استحق العقاب بكفره وظلمه نفسه حيث حرمها من نيل المثوبة."},{"text":"ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ","tafsir":""},{"text":"لَآ إِكْرَاهَ فِى ٱلدِّينِ ۖ قَد تَّبَيَّنَ ٱلرُّشْدُ مِنَ ٱلْغَىِّ ۚ فَمَن يَكْفُرْ بِٱلطَّـٰغُوتِ وَيُؤْمِنۢ بِٱللَّهِ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ لَا ٱنفِصَامَ لَهَا ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ","tafsir":"فالأمور في يوم القيامة كلها بيده لا يشارك فيما يفعل ولعل هذا هو وجه الارتباط بين هذه الآية والآية السالفة ( الْحَيُ ) الذي لا يموت فلا يمكن التخلص منه ( الْقَيُّومُ ) القائم على الأمور يعلمها جميعا فلا يمكن الاختفاء منه. ( لا تَأْخُذُهُ سِنَةٌ ) وهي النوم الخفيف المسمى بالنعاس ( وَلا نَوْمٌ ) وقدم الأول لتقدمه في الخارج ( لَهُ ما فِي السَّماواتِ وَما فِي الْأَرْضِ ) فهو الخالق والمالك الوحيد الذي لا يشاركه أحد ، والظرف هنا يتبع المظروف فليست السماوات والأرض خارجتين عن الملكية ( مَنْ ذَا ) أي أي شخص ( الَّذِي يَشْفَعُ عِنْدَهُ ) يوم القيامة ( إِلَّا بِإِذْنِهِ ) استفهام إنكاري فإنهم لا يشفعون إلا لمن ارتضى ( يَعْلَمُ ما بَيْنَ أَيْدِيهِمْ وَما خَلْفَهُمْ ) أي ما يقدمون من أعمال خير وشر وما يخلفون من بعدهم كبناء مدرسة أو مخمر يبقيان بعده ( وَلا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ ) أي بما يعلمه من الماضي والحاضر والآتي ( إِلَّا بِما شاءَ ) أي وَسِعَ كُرْسِيُّهُ السَّماواتِ وَالْأَرْضَ وَلا يَؤُدُهُ حِفْظُهُما وَهُوَ الْعَلِيُّ الْعَظِيمُ (255) لا إِكْراهَ فِي الدِّينِ قَدْ تَبَيَّنَ الرُّشْدُ مِنَ الْغَيِّ فَمَنْ يَكْفُرْ بِالطَّاغُوتِ وَيُؤْمِنْ بِاللهِ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقى بما أراد من اطلاع الناس عليه فإن علم الشخص حتى بالضروريات مما تتعلق به مشيئة الله سبحانه فإنه هو الذي جعل الإنسان بحيث يعلم الأمور في الجملة ( وَسِعَ كُرْسِيُّهُ السَّماواتِ وَالْأَرْضَ ) الكرسي كناية عن السلطة والملكية يقال : كرسي فلان يسع العراق إذا كان ملكا عليها ، أي أن سلطة الله سبحانه تشمل جميع الكون ، فإنه لا يخلو من سماء وأرض ( وَلا يَؤُدُهُ ) أي لا يشق عليه تعالى ، من آده يأده ، إذا أثقله وجهده ( حِفْظُهُما ) أي حفظ السماوات والأرض بالتربية والتنمية والإصلاح ( وَهُوَ الْعَلِيُ ) أي الرفيع مقاما ( الْعَظِيمُ ) الشأن."},{"text":"ٱللَّهُ وَلِىُّ ٱلَّذِينَ ءَامَنُوا۟ يُخْرِجُهُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ ۖ وَٱلَّذِينَ كَفَرُوٓا۟ أَوْلِيَآؤُهُمُ ٱلطَّـٰغُوتُ يُخْرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَـٰتِ ۗ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ","tafsir":"فإن الله لم يلجأ الخلق إلى اعتناق الدين بل جعل فيهم الاختيار والإرادة فإن شاءوا دانوا وإن لم يشاءوا لم يدينوا ( قَدْ تَبَيَّنَ ) أي وضح ( الرُّشْدُ مِنَ الْغَيِ ) أي الهداية من الضلالة والإيمان من الكفر والحق من الباطل ( فَمَنْ يَكْفُرْ بِالطَّاغُوتِ ) وهو كل ما يعبد من دون الله ( وَيُؤْمِنْ بِاللهِ ) وحده ، وقدم نفي الكفر لأن النفي مقدم على الإثبات كما قدم في كلمة « لا إله إلا الله » ( فَقَدِ اسْتَمْسَكَ ) أي تمسك واعتصم وأخذ ( بِالْعُرْوَةِ ) وهي « المسكة » لمثل الكوز ( الْوُثْقى ) أي الوثيقة التي لا تنفصل فقد شبه الخير بإناء للسقي لا انْفِصامَ لَها وَاللهُ سَمِيعٌ عَلِيمٌ (256) اللهُ وَلِيُّ الَّذِينَ آمَنُوا يُخْرِجُهُمْ مِنَ الظُّلُماتِ إِلَى النُّورِ وَالَّذِينَ كَفَرُوا أَوْلِياؤُهُمُ الطَّاغُوتُ يُخْرِجُونَهُمْ مِنَ النُّورِ إِلَى الظُّلُماتِ أُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ (257) أو الطعام له عروة فالإيمان بالله عروة وثقى للخير لأنه ( لَا انْفِصامَ لَها ) ولا انقطاع بل تدوم الاستفادة من الخير بسبب الإيمان في الدنيا والآخرة بينما الإيمان بالطاغوت عروة واهية تنفصم إذا فارق الإنسان الحياة الدنيا ينقطع الخير الذي يناله الإنسان ـ فرضا ـ بسبب الكفر ( وَاللهُ سَمِيعٌ ) لأقوالكم ( عَلِيمٌ ) بنياتكم وأعمالكم."},{"text":"أَلَمْ تَرَ إِلَى ٱلَّذِى حَآجَّ إِبْرَٰهِـۧمَ فِى رَبِّهِۦٓ أَنْ ءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ إِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّىَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ قَالَ أَنَا۠ أُحْىِۦ وَأُمِيتُ ۖ قَالَ إِبْرَٰهِـۧمُ فَإِنَّ ٱللَّهَ يَأْتِى بِٱلشَّمْسِ مِنَ ٱلْمَشْرِقِ فَأْتِ بِهَا مِنَ ٱلْمَغْرِبِ فَبُهِتَ ٱلَّذِى كَفَرَ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ","tafsir":"يلي أمورهم وينصرهم ويعينهم ( يُخْرِجُهُمْ مِنَ الظُّلُماتِ ) ظلمات الحياة ومشاكلها ، من ظلمة العقيدة ، وظلمة القول وظلمة الدنيا كلها ( إِلَى النُّورِ ) نور الهداية ، ونور الآخرة ( وَالَّذِينَ كَفَرُوا أَوْلِياؤُهُمُ الطَّاغُوتُ ) أي أن جنس الطاغوت يكون أولياء لهم ، فإن الطواغيت من الجن والإنس يتولون أمورهم وضلالهم وحيث أن الطاغوت أريد به الجنس جاز الإتيان بصيغة الجمع في « أوليائهم » صفة له ( يُخْرِجُونَهُمْ مِنَ النُّورِ ) الكامن في فطرتهم ، ومن نور الدنيا ( إِلَى الظُّلُماتِ ) ظلمات الكفر والظلال في الدنيا وعذاب الله في الآخرة ( أُولئِكَ ) الذين كفروا ( أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ ) إلى الأبد فلا منجي لهم ولا مخلص [259] سبق الحديث عن الإيمان والكفر ، فلتناسب المقام قصة حوار أَ لَمْ تَرَ إِلَى الَّذِي حَاجَّ إِبْراهِيمَ فِي رَبِّهِ أَنْ آتاهُ اللهُ الْمُلْكَ إِذْ قالَ إِبْراهِيمُ رَبِّيَ الَّذِي يُحْيِي وَيُمِيتُ قالَ أَنَا أُحْيِي وَأُمِيتُ قالَ إِبْراهِيمُ فَإِنَّ اللهَ يَأْتِي بِالشَّمْسِ مِنَ الْمَشْرِقِ فَأْتِ بِها مِنَ الْمَغْرِبِ فَبُهِتَ الَّذِي كَفَرَ حول هذا الموضوع بين إبراهيم عليه‌السلام ونمرود ( أَ لَمْ تَرَ ) أي ألم تعلم ، وقد تقدم أن هذه العبارة تذكر لإفادة العلم ( إِلَى الَّذِي حَاجَ ) من المحاجة بمعنى المجادلة والمخاصمة ( إِبْراهِيمَ فِي رَبِّهِ ) أي في باب رب إبراهيم عليه‌السلام الذي كان يعبده ، أو رب الذي حاج وإن كان الأول أقرب ( أَنْ آتاهُ اللهُ الْمُلْكَ ) أي حيث أن الله أعطى نمرود الملك والسلطة بطر فأنكر وجود الخالق وجعل يجادل نبيه إبراهيم عليه‌السلام حول وجود الله سبحانه فقد قابل الإحسان بالإساءة ( إِذْ قالَ إِبْراهِيمُ رَبِّيَ الَّذِي يُحْيِي وَيُمِيتُ ) في جواب نمرود حيث قال له : من ربك ؟ والمراد بالإحياء إحياء الجماد فإن كل حي أصله التراب والماء إذ التراب بسبب الماء ينقلب عشبا والعشب ينقلب نطفة إنسانا أو حيوانا ( قالَ ) نمرود ( أَنَا أُحْيِي وَأُمِيتُ ) فأخرج نفرين من حبسه وضرب عنق أحدهما وأطلق الآخر وكان هذا مغالطة من نمرود إلا أن إبراهيم عليه‌السلام أراد أن يلزمه بحجة لا يتمكن حتى من المغالطة فيها ف ( قالَ إِبْراهِيمُ فَإِنَّ اللهَ يَأْتِي بِالشَّمْسِ مِنَ الْمَشْرِقِ ) هكذا يظهر للأبصار سواء دارت هي أو دارت الأرض كما يقوله بعض علماء الفلك ( فَأْتِ بِها مِنَ الْمَغْرِبِ ) إن كنت إلها خالقا ( فَبُهِتَ الَّذِي كَفَرَ ) أي تحير وَاللهُ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ (258) أَوْ كَالَّذِي مَرَّ عَلى قَرْيَةٍ وَهِيَ خاوِيَةٌ عَلى عُرُوشِها قالَ أَنَّى يُحْيِي هذِهِ اللهُ بَعْدَ مَوْتِها فَأَماتَهُ اللهُ مِائَةَ عامٍ ثُمَّ بَعَثَهُ قالَ كَمْ لَبِثْتَ قالَ لَبِثْتُ يَوْماً أَوْ بَعْضَ يَوْمٍ قالَ بَلْ لَبِثْتَ مِائَةَ عامٍ نمرود ولم يحر جوابا ( وَاللهُ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ ) الذين ظلموا أنفسهم بتعاميهم عن الحق فإنه سبحانه لا يلطف لطفه الخاص بمثل هؤلاء وإن أتم عليهم الحجة وأراهم الطريق."},{"text":"أَوْ كَٱلَّذِى مَرَّ عَلَىٰ قَرْيَةٍ وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحْىِۦ هَـٰذِهِ ٱللَّهُ بَعْدَ مَوْتِهَا ۖ فَأَمَاتَهُ ٱللَّهُ مِا۟ئَةَ عَامٍ ثُمَّ بَعَثَهُۥ ۖ قَالَ كَمْ لَبِثْتَ ۖ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ ۖ قَالَ بَل لَّبِثْتَ مِا۟ئَةَ عَامٍ فَٱنظُرْ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمْ يَتَسَنَّهْ ۖ وَٱنظُرْ إِلَىٰ حِمَارِكَ وَلِنَجْعَلَكَ ءَايَةً لِّلنَّاسِ ۖ وَٱنظُرْ إِلَى ٱلْعِظَامِ كَيْفَ نُنشِزُهَا ثُمَّ نَكْسُوهَا لَحْمًا ۚ فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعْلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ","tafsir":""},{"text":"وَإِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّ أَرِنِى كَيْفَ تُحْىِ ٱلْمَوْتَىٰ ۖ قَالَ أَوَلَمْ تُؤْمِن ۖ قَالَ بَلَىٰ وَلَـٰكِن لِّيَطْمَئِنَّ قَلْبِى ۖ قَالَ فَخُذْ أَرْبَعَةً مِّنَ ٱلطَّيْرِ فَصُرْهُنَّ إِلَيْكَ ثُمَّ ٱجْعَلْ عَلَىٰ كُلِّ جَبَلٍ مِّنْهُنَّ جُزْءًا ثُمَّ ٱدْعُهُنَّ يَأْتِينَكَ سَعْيًا ۚ وَٱعْلَمْ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ","tafsir":"أي ألم تر إلى الذي مر على قرية ، والمعنى إن شئت فانظر إلى الذي حاج وإن شئت فانظر إلى الذي مر على قرية وهو عزيز النبي عليه‌السلام أو أرميا ( وَهِيَ خاوِيَةٌ عَلى عُرُوشِها ) أي ساقطة حيطانها على سقوفها وأهلها موتى والسباع تأكل الجيف ففكر في نفسه ساعة ( قالَ أَنَّى ) أي كيف ( يُحْيِي هذِهِ ) الأموات ( اللهُ بَعْدَ مَوْتِها ) وكان ذلك منه تعجبا لا إنكارا ( فَأَماتَهُ اللهُ مِائَةَ عامٍ ) حتى بلي ونخرت عظامه ( ثُمَّ بَعَثَهُ ) أحياه كما كان ( قالَ ) الله سبحانه له بإيجاد صوت في الجو ( كَمْ لَبِثْتَ ) في مبيتك ومنامك ( قالَ ) النبي ( لَبِثْتُ يَوْماً ) ثم نظر فإذا هو نام صباحا والآن قبل غروب الشمس فأضرب قائلا ( أَوْ بَعْضَ يَوْمٍ قالَ ) الله سبحانه ( بَلْ لَبِثْتَ مِائَةَ عامٍ ) وقد كان معه طعام وشراب وحمار ، فكان الطعام والشراب باقيين كما هما وكان الحمار قد مات وتفرقت عظامه ونخرت دلالة على كمال قدرة الله فَانْظُرْ إِلى طَعامِكَ وَشَرابِكَ لَمْ يَتَسَنَّهْ وَانْظُرْ إِلى حِمارِكَ وَلِنَجْعَلَكَ آيَةً لِلنَّاسِ وَانْظُرْ إِلَى الْعِظامِ كَيْفَ نُنْشِزُها ثُمَّ نَكْسُوها لَحْماً فَلَمَّا تَبَيَّنَ لَهُ قالَ أَعْلَمُ أَنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ (259) وَإِذْ قالَ إِبْراهِيمُ رَبِّ أَرِنِي كَيْفَ تُحْيِ الْمَوْتى سبحانه ( فَانْظُرْ إِلى طَعامِكَ وَشَرابِكَ لَمْ يَتَسَنَّهْ ) لم تغيره السنون ، والإتيان بلفظ المفرد باعتبار كل واحد منهما ( وَانْظُرْ إِلى حِمارِكَ ) كيف مات ونخرت عظامه ( وَلِنَجْعَلَكَ ) أيها الرسول ( آيَةً لِلنَّاسِ ) أي حجة حيث أحييناك بعد مائة عام حتى يعرف الناس أن الله قادر على بعث الأموات ( وَانْظُرْ إِلَى الْعِظامِ ) لحمارك المتفتتة ( كَيْفَ نُنْشِزُها ) أي كيف نرفع بعضها إلى بعض لنركب منها الهيكل العظمي للحمار ( ثُمَّ نَكْسُوها ) أي نلبس العظام ( لَحْماً ) حتى يستوي حمارا حيا ( فَلَمَّا تَبَيَّنَ لَهُ ) أي وضح له إحياء الأموات عيانا ( قالَ ) النبي عليه‌السلام ( أَعْلَمُ أَنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) أي علما عيانا وإلا فقد كان يعلم ذلك قبل السؤال."},{"text":"مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتْ سَبْعَ سَنَابِلَ فِى كُلِّ سُنۢبُلَةٍ مِّا۟ئَةُ حَبَّةٍ ۗ وَٱللَّهُ يُضَـٰعِفُ لِمَن يَشَآءُ ۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ","tafsir":"اذكر يا رسول الله ( إِذْ قالَ إِبْراهِيمُ رَبِّ أَرِنِي كَيْفَ تُحْيِ الْمَوْتى ) فإنه عليه‌السلام رأى جيفة تمزقها السباع فيأكل منها سباع البر وسباع الهواء ودواب البحر فسأل الله إبراهيم عليه‌السلام فقال : يا رب قد علمت أنك تجمعها من بطون السباع والطير ودواب البر فأرني كيف قالَ أَ وَلَمْ تُؤْمِنْ قالَ بَلى وَلكِنْ لِيَطْمَئِنَّ قَلْبِي قالَ فَخُذْ أَرْبَعَةً مِنَ الطَّيْرِ فَصُرْهُنَّ إِلَيْكَ ثُمَّ اجْعَلْ عَلى كُلِّ جَبَلٍ مِنْهُنَّ جُزْءاً ثُمَّ ادْعُهُنَّ يَأْتِينَكَ سَعْياً وَاعْلَمْ أَنَّ اللهَ عَزِيزٌ حَكِيمٌ (260) تحييها لأعاين ذلك ( قالَ ) الله سبحانه ( أَ وَلَمْ تُؤْمِنْ ) على نحو استفهام التقرير ، ليقول آمنت ، كقولهم : « ألستم خير من ركب المطايا » ( قالَ ) إبراهيم عليه‌السلام ( بَلى ) أنا مؤمن ( وَلكِنْ ) أسأل ذلك ( لِيَطْمَئِنَّ قَلْبِي ) ويكون يقيني عين اليقين فإن الإنسان الذي يعلم أن النار ـ مثلا ـ حارة ، يسمى ذلك علم اليقين ، فإذا رآها سمي حق اليقين ، فإذا أدخل يده فيها فاحترقت سمي عين اليقين ، وورد أنه عليه‌السلام علم أن الله يتخذ عبدا له خليلا إذا سأله إحياء الموتى أحياها فأراد أن يطمئن أنه هو ( قالَ ) الله سبحانه ( فَخُذْ أَرْبَعَةً مِنَ الطَّيْرِ ) الطاووس والحمام والغراب والديك فاذبحهن وقطعهن واخلطهن بعضا ببعض ( فَصُرْهُنَّ إِلَيْكَ ) من صرته بمعنى قطعته و « إليك » إنما هو من مستلزمات القطع ، فإن الإنسان إذا أراد أن يقطع شيئا قطعا جيدا ويخلطه لا بد وأن يجذبه إليه ولعله كناية عن القطع الجيد والتخليط البالغ ( ثُمَّ اجْعَلْ عَلى كُلِّ جَبَلٍ ) من عشرة جبال ( مِنْهُنَّ جُزْءاً ) وإنما ذلك يدل على أن الأجزاء الميتة تجتمع من محلات متباعدة وقت الحشر ( ثُمَّ ادْعُهُنَ ) بأن تأخذ بمنقار كل واحد من الطيور الأربعة في يدك وتدعوه باسمه ( يَأْتِينَكَ ) تجتمع الأجزاء من الجبال ( سَعْياً ) مسرعات ( وَاعْلَمْ أَنَّ اللهَ عَزِيزٌ ) لا يمتنع عليه شيء ( حَكِيمٌ ) فيما يفعل فلا يفعل شيئا اعتباطا وعبثا ، ففعل إبراهيم عليه‌السلام ذلك فتطايرت مَثَلُ الَّذِينَ يُنْفِقُونَ أَمْوالَهُمْ فِي سَبِيلِ اللهِ كَمَثَلِ حَبَّةٍ أَنْبَتَتْ سَبْعَ سَنابِلَ فِي كُلِّ سُنْبُلَةٍ مِائَةُ حَبَّةٍ وَاللهُ يُضاعِفُ لِمَنْ يَشاءُ وَاللهُ واسِعٌ عَلِيمٌ (261) الَّذِينَ يُنْفِقُونَ أَمْوالَهُمْ فِي سَبِيلِ اللهِ ثُمَّ لا يُتْبِعُونَ ما أَنْفَقُوا مَنًّا الأجزاء بعضها إلى بعض حتى استوت الأبدان وجاء كل بدن حتى نظم إلى رقبته ورأسه فأطلقها إبراهيم عليه‌السلام فطرن فالتقطن الحب وشربن الماء ثم دعون لإبراهيم عليه‌السلام . [262] تقدم الكلام في الآيات السابقة عن من يقرض الله قرضا حسنا ، ثم تخلل الكلام دليل التوحيد والرسالة والمعاد والآن يرجع السياق إلى الإنفاق ( مَثَلُ الَّذِينَ يُنْفِقُونَ أَمْوالَهُمْ فِي سَبِيلِ اللهِ ) لا رياء أو سمعة وشهرة ونحوها ( كَمَثَلِ حَبَّةٍ ) من الحنطة أو الشعير أو نحوهما ( أَنْبَتَتْ ) أي أخرجت ( سَبْعَ سَنابِلَ ) جمع سنبلة وهي مجمع الحبات ( فِي كُلِّ سُنْبُلَةٍ مِائَةُ حَبَّةٍ ) فتكون النفقة في سبيل الله بسبعمائة ضعف ( وَاللهُ يُضاعِفُ ) أي يزيد كل سبعمائة ( لِمَنْ يَشاءُ ) من عباده من المنفقين ( وَاللهُ واسِعٌ عَلِيمٌ ) يسع علمه وقدرته فيعلم المنفق والإنفاق ، وقد مثل الإنفاق بهذا ليكون أوقع في النفس وأكثر في التأثير والتشويق. [263] ثم ذكر شرطا آخر للإنفاق المثمر الموجب للأجر بقوله تعالى : ( الَّذِينَ يُنْفِقُونَ أَمْوالَهُمْ فِي سَبِيلِ اللهِ ثُمَّ لا يُتْبِعُونَ ) أي لا يعقبون ( ما أَنْفَقُوا مَنًّا ) على المعطى له بأن يمن عليه في إنفاقه كأن يقول له : إني وَلا أَذىً لَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ (262) قَوْلٌ مَعْرُوفٌ وَمَغْفِرَةٌ خَيْرٌ مِنْ صَدَقَةٍ يَتْبَعُها أَذىً وَاللهُ غَنِيٌّ حَلِيمٌ (263) يا أَيُّهَا الَّذِينَ آمَنُوا لا تُبْطِلُوا صَدَقاتِكُمْ بِالْمَنِّ وَالْأَذى كَالَّذِي يُنْفِقُ مالَهُ رِئاءَ النَّاسِ أعطيتك فكن شاكرا ( وَلا أَذىً ) بأن يؤذى المعطى له ، كأن يقول : ابتليت بفلان الفقير ( لَهُمْ أَجْرُهُمْ ) وجزاء إنفاقهم ( عِنْدَ رَبِّهِمْ وَلا خَوْفٌ عَلَيْهِمْ ) من العذاب لأن من ينفق هكذا يكون مخلصا في جميع أعماله ، أو لا خوف عليهم من فوت الأجر ( وَلا هُمْ يَحْزَنُونَ ) وهو يحتمل الأمرين مثل ـ لا خوف ـ."},{"text":"ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتْبِعُونَ مَآ أَنفَقُوا۟ مَنًّا وَلَآ أَذًى ۙ لَّهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ","tafsir":""},{"text":"۞ قَوْلٌ مَّعْرُوفٌ وَمَغْفِرَةٌ خَيْرٌ مِّن صَدَقَةٍ يَتْبَعُهَآ أَذًى ۗ وَٱللَّهُ غَنِىٌّ حَلِيمٌ","tafsir":""},{"text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُبْطِلُوا۟ صَدَقَـٰتِكُم بِٱلْمَنِّ وَٱلْأَذَىٰ كَٱلَّذِى يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۖ فَمَثَلُهُۥ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابٌ فَأَصَابَهُۥ وَابِلٌ فَتَرَكَهُۥ صَلْدًا ۖ لَّا يَقْدِرُونَ عَلَىٰ شَىْءٍ مِّمَّا كَسَبُوا۟ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَـٰفِرِينَ","tafsir":"بأن يرد به السائل ، نحو الله يعطيك ( وَمَغْفِرَةٌ ) أي تجاوز عن السائل فيما إذا أساء ( خَيْرٌ مِنْ صَدَقَةٍ يَتْبَعُها أَذىً ) لأن الصدقة كذلك تجرح قلب السائل دونهما ، ولأنها تتبع العقاب ، لأن هكذا صدقة محرمة ، بخلافهما ( وَاللهُ غَنِيٌ ) فلا يحتاج إلى صدقاتكم أيها المعطون ، وإنما أنتم تحتاجون إليها ، فحث الله بالإنفاق لكم ، لا له ( حَلِيمٌ ) حليم عن عقابكم بسبب صدقاتكم التي يتبعها الأذى."},{"text":"وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ وَتَثْبِيتًا مِّنْ أَنفُسِهِمْ كَمَثَلِ جَنَّةٍۭ بِرَبْوَةٍ أَصَابَهَا وَابِلٌ فَـَٔاتَتْ أُكُلَهَا ضِعْفَيْنِ فَإِن لَّمْ يُصِبْهَا وَابِلٌ فَطَلٌّ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ","tafsir":"على السائل ( وَالْأَذى ) له فإن فيها إبطالا للصدقة من حيث الثواب فلا ثواب لها عند العرف لأن مثل هذه الصدقة لا تحسب جميلا وإنما قبيحا بشعا ، فإن من يبطل صدقته بالمن والأذى فهو ( كَالَّذِي يُنْفِقُ مالَهُ رِئاءَ النَّاسِ ) لأجل وَلا يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَمَثَلُهُ كَمَثَلِ صَفْوانٍ عَلَيْهِ تُرابٌ فَأَصابَهُ وابِلٌ فَتَرَكَهُ صَلْداً لا يَقْدِرُونَ عَلى شَيْءٍ مِمَّا كَسَبُوا وَاللهُ لا يَهْدِي الْقَوْمَ الْكافِرِينَ (264) أن يراه الناس فيمدحوه ( وَلا يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ ) بأن يكون الداعي له إلى التصدق أمر الله سبحانه أو ثواب الآخرة ( فَمَثَلُهُ كَمَثَلِ صَفْوانٍ عَلَيْهِ تُرابٌ فَأَصابَهُ وابِلٌ فَتَرَكَهُ صَلْداً ) الصفوان : الحجر الأملس ، والوابل : المطر الشديد الوقع ، والصلد من الأرض ما لا ينبت شيئا لصلابته ، فإن الإنسان الكافر كالحجر الصلب الذي لا يرجى منه خير ، وما يتحفظ به ظواهره بمنزلة تراب على الحجر يظن الناس أنه محل قابل للنبت ، والصدقة التي يرائي بها كالمطر الشديد ، فإنه إذا نزل بأرض صالحة كان مبعث الخير والنبات لكنه إذا نزل على الحجر المغطى بالتراب أزال ترابه وأظهر صلادته وعدم قبوله لأي إنبات أو عشب ، وكذلك الكافر الذي يظن به الناس بعض الخير إذا أنفق رياء ظهر على الناس حقيقته المنحرفة فتكون الصدقة ـ التي هي بذاتها سبب الخير والرحمة ـ معرية لحقيقة الكافر البشعة ، ومن ناحية أخرى أنها توجب سخط الله عليه أكثر من ذي قبل فتكون مذهبة لما يظن أنها حسنة له من بعض أعماله الخيرية السابقة ( لا يَقْدِرُونَ عَلى شَيْءٍ مِمَّا كَسَبُوا ) من مكاسبهم السابقة لأن الصدقة برياء ذهاب بها كما أن المطر يذهب بالتراب فلا يمكن إرجاعه وجمعه ( وَاللهُ لا يَهْدِي الْقَوْمَ الْكافِرِينَ ) فلا يلطف بهم اللطف الخاص لأنهم أسقطوا أنفسهم عن القابلية لجحودهم بعد أن عرفوا الحق. وَمَثَلُ الَّذِينَ يُنْفِقُونَ أَمْوالَهُمُ ابْتِغاءَ مَرْضاتِ اللهِ وَتَثْبِيتاً مِنْ أَنْفُسِهِمْ كَمَثَلِ جَنَّةٍ بِرَبْوَةٍ أَصابَها وابِلٌ فَآتَتْ أُكُلَها ضِعْفَيْنِ فَإِنْ لَمْ يُصِبْها وابِلٌ فَطَلٌّ وَاللهُ بِما تَعْمَلُونَ بَصِيرٌ (265) أَ يَوَدُّ أَحَدُكُمْ أَنْ"},{"text":"أَيَوَدُّ أَحَدُكُمْ أَن تَكُونَ لَهُۥ جَنَّةٌ مِّن نَّخِيلٍ وَأَعْنَابٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ لَهُۥ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَأَصَابَهُ ٱلْكِبَرُ وَلَهُۥ ذُرِّيَّةٌ ضُعَفَآءُ فَأَصَابَهَآ إِعْصَارٌ فِيهِ نَارٌ فَٱحْتَرَقَتْ ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَـٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ","tafsir":"أي لأجل طلب رضى الله سبحانه ( وَتَثْبِيتاً مِنْ أَنْفُسِهِمْ ) أي لأجل تثبيت أعمالهم الحسنة وتركيزها ، تثبيتا ناشئا من أنفسهم فأنفسهم هي التي توصي بذلك ، لا كالمرائي الذي يحمله على الصدقة رؤية الناس ، فهذه الجملة « من أنفسهم » مقابل جملة « رئاء الناس » في الآية السابقة ( كَمَثَلِ جَنَّةٍ بِرَبْوَةٍ ) أي بستان مرتفع ( أَصابَها وابِلٌ ) مطر غزير ( فَآتَتْ ) أي أعطت ( أُكُلَها ) وثمرها ( ضِعْفَيْنِ ) فإن الإنسان المؤمن كالبستان الواقع في مرتفع يزهو للناس ويكون أقرب إلى الاستفادة من الهواء والشمس والمطر ، فإن المؤمن أقرب إلى الخير فإذا تصدق تكون صدقته كالمطر الذي إذا نزل بالبستان يوجب نمو ثمارها وازدهار أشجارها ( فَإِنْ لَمْ يُصِبْها وابِلٌ ) مطر غزير فيكفي لإثمارها وإنضارها طل رذاذ من مطر قليل ( وَاللهُ بِما تَعْمَلُونَ بَصِيرٌ ) فيجازيكم على أعمالكم إن رياء وإن قربة. [267] ولما مثل سبحانه لصدقة كل من المؤمن والكافر ، مثل لصدقة المؤمن الذي يمن بصدقته فيبطلها ( أَ يَوَدُّ ) أي هل يحب ( أَحَدُكُمْ أَنْ تَكُونَ لَهُ جَنَّةٌ مِنْ نَخِيلٍ وَأَعْنابٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ لَهُ فِيها مِنْ كُلِّ الثَّمَراتِ وَأَصابَهُ الْكِبَرُ وَلَهُ ذُرِّيَّةٌ ضُعَفاءُ فَأَصابَها إِعْصارٌ فِيهِ نارٌ فَاحْتَرَقَتْ كَذلِكَ يُبَيِّنُ اللهُ لَكُمُ الْآياتِ لَعَلَّكُمْ تَتَفَكَّرُونَ (266) يا أَيُّهَا الَّذِينَ آمَنُوا أَنْفِقُوا مِنْ طَيِّباتِ ما كَسَبْتُمْ وَمِمَّا أَخْرَجْنا لَكُمْ مِنَ الْأَرْضِ تَكُونَ لَهُ جَنَّةٌ مِنْ نَخِيلٍ وَأَعْنابٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ ) أي تحت أشجارها ( لَهُ فِيها ) أي في تلك الجنة ( مِنْ كُلِّ الثَّمَراتِ وَأَصابَهُ الْكِبَرُ ) أي الشيخوخة ( وَلَهُ ذُرِّيَّةٌ ضُعَفاءُ ) عاجزون عن كسب المأكل والملبس ( فَأَصابَها ) أي أصاب الجنة ( إِعْصارٌ فِيهِ نارٌ فَاحْتَرَقَتْ ) كلا لا يحب أحد ذلك إنه في أشد أوقات حاجته ، فهل يرضى إصابة النار بأثمن ما يملك ؟ إن مثل من ينفق عن إيمان واعتقاد مثل تلك الجنة ، فإذا امتن بعد ذلك أو آذى السائل ، يكون ذلك نارا تحرق جنته في أشد أوقات حاجته ، فالإنسان في أشد الحاجة إلى خيره في الآخرة ، فإذا امتن بقي صفر اليدين هناك ( كَذلِكَ ) أي كهذا البيان الذي بين أمر الصدقة وغيرها ( يُبَيِّنُ اللهُ لَكُمُ الْآياتِ ) بضرب الأمثال والمشوقات ( لَعَلَّكُمْ تَتَفَكَّرُونَ ) فتستقيموا على الصراط المستقيم."},{"text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِن طَيِّبَـٰتِ مَا كَسَبْتُمْ وَمِمَّآ أَخْرَجْنَا لَكُم مِّنَ ٱلْأَرْضِ ۖ وَلَا تَيَمَّمُوا۟ ٱلْخَبِيثَ مِنْهُ تُنفِقُونَ وَلَسْتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغْمِضُوا۟ فِيهِ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَنِىٌّ حَمِيدٌ","tafsir":""},{"text":"ٱلشَّيْطَـٰنُ يَعِدُكُمُ ٱلْفَقْرَ وَيَأْمُرُكُم بِٱلْفَحْشَآءِ ۖ وَٱللَّهُ يَعِدُكُم مَّغْفِرَةً مِّنْهُ وَفَضْلًا ۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ","tafsir":"طيبا واقعيا بكونه حلالا وظاهريا بكونه جيدا و ( مِنْ ) طيبات ما ( أَخْرَجْنا لَكُمْ مِنَ الْأَرْضِ ) أي وَلا تَيَمَّمُوا الْخَبِيثَ مِنْهُ تُنْفِقُونَ وَلَسْتُمْ بِآخِذِيهِ إِلاَّ أَنْ تُغْمِضُوا فِيهِ وَاعْلَمُوا أَنَّ اللهَ غَنِيٌّ حَمِيدٌ (267) الشَّيْطانُ يَعِدُكُمُ الْفَقْرَ وَيَأْمُرُكُمْ بِالْفَحْشاءِ وَاللهُ يَعِدُكُمْ مَغْفِرَةً مِنْهُ وَفَضْلاً وَاللهُ واسِعٌ عَلِيمٌ (268) طيب مكسبكم وطيب ثماركم ، فلا تنفقوا من الربا ولا من الماء الآجن ولا من حشف التمر ـ مثلا ـ ( وَلا تَيَمَّمُوا ) أي لا تقصدوا ( الْخَبِيثَ ) الحرام الرديء ( مِنْهُ تُنْفِقُونَ ) للناس ( وَ ) الحال أنكم ( لَسْتُمْ بِآخِذِيهِ ) فإن أراد أحد إعطائكم من ذلك ما كنتم تأخذونه ( إِلَّا أَنْ تُغْمِضُوا فِيهِ ) أي تغمضوا عيونكم كراهة له ، فالإنسان إذا استبشع شيئا غمض عينه حتى لا يراه ، فكيف تنفقون مثل هذا الشيء الذي إذا أردتم أخذه غمضتم عينكم استبشاعا له ( وَاعْلَمُوا أَنَّ اللهَ غَنِيٌ ) عن صدقاتكم فلا يأخذ إلا الطيب ولا يقبل إلا الحسن ( حَمِيدٌ ) أي مستحق للحمد على نعمه ، ومن حمده أن يعطي الإنسان الشيء الطيب في سبيله ، فالإنسان إذا أراد تقدير شخص دفع إليه أحسن ما يتمكن ، لا أنه يدفع الرديء الخبيث."},{"text":"يُؤْتِى ٱلْحِكْمَةَ مَن يَشَآءُ ۚ وَمَن يُؤْتَ ٱلْحِكْمَةَ فَقَدْ أُوتِىَ خَيْرًا كَثِيرًا ۗ وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَـٰبِ","tafsir":"إذا أردتم الإنفاق في سبيل الله ( وَيَأْمُرُكُمْ بِالْفَحْشاءِ ) إذا أردتم الإنفاق يقول لكم : أنفقوا من الرديء الخبيث ، وهو قسم من الفحشاء ، أو المراد به الأعمال القبيحة مطلقا ، ( وَاللهُ يَعِدُكُمْ مَغْفِرَةً مِنْهُ ) فإنه يغفر ذنوبكم بسبب الصدقة وسائر المبرات ( وَفَضْلاً ) فيخلف ما أنفقتموه ( وَاللهُ واسِعٌ ) ليس ضيق المقدرة حتى لا يتمكن من التعويض ( عَلِيمٌ ) بما تعطون فيجازيكم بالحسن يُؤْتِي الْحِكْمَةَ مَنْ يَشاءُ وَمَنْ يُؤْتَ الْحِكْمَةَ فَقَدْ أُوتِيَ خَيْراً كَثِيراً وَما يَذَّكَّرُ إِلاَّ أُولُوا الْأَلْبابِ (269) وَما أَنْفَقْتُمْ مِنْ نَفَقَةٍ أَوْ نَذَرْتُمْ مِنْ نَذْرٍ فَإِنَّ اللهَ يَعْلَمُهُ وَما لِلظَّالِمِينَ مِنْ أَنْصارٍ (270) إِنْ تُبْدُوا الصَّدَقاتِ حسنا وبالسيئ سيئا. [270] إنّ الإنفاق في سبيل الله من الطيب بلا رياء ولا منّ ولا أذى من الحكمة التي هي وضع الأشياء موضعها اللائق والله سبحانه ( يُؤْتِي الْحِكْمَةَ مَنْ يَشاءُ ) ممن له قابلية بما سبق أن أخذ بالشريعة ( وَمَنْ يُؤْتَ الْحِكْمَةَ فَقَدْ أُوتِيَ خَيْراً كَثِيراً ) وأي خير أعظم من أن يعمر الإنسان دنياه وعقباه بأخذه بأوامر الله سبحانه وانتهاجه المنهج المستقيم الموجب لسعادة النشأتين ( وَما يَذَّكَّرُ ) أي ما يتذكر ولا يفهم ذلك ( إِلَّا أُولُوا الْأَلْبابِ ) أصحاب العقول فصاحب العقل هو الذي يتبع ما ينفعه ويذر ما يضره."},{"text":"وَمَآ أَنفَقْتُم مِّن نَّفَقَةٍ أَوْ نَذَرْتُم مِّن نَّذْرٍ فَإِنَّ ٱللَّهَ يَعْلَمُهُۥ ۗ وَمَا لِلظَّـٰلِمِينَ مِنْ أَنصَارٍ","tafsir":""},{"text":"إِن تُبْدُوا۟ ٱلصَّدَقَـٰتِ فَنِعِمَّا هِىَ ۖ وَإِن تُخْفُوهَا وَتُؤْتُوهَا ٱلْفُقَرَآءَ فَهُوَ خَيْرٌ لَّكُمْ ۚ وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمْ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ","tafsir":"قليلة أو كثيرة أي أية صدقة تصدقتم بها ( أَوْ نَذَرْتُمْ مِنْ نَذْرٍ ) أي ما أوجبتموه على أنفسكم لله بسب النذر ( فَإِنَّ اللهَ يَعْلَمُهُ ) فيجازيكم عليه ويكون ذلك سببا للإحسان إلى النفس ( وَما لِلظَّالِمِينَ ) الذين يظلمون أنفسهم بالشح ومنع الصدقات الواجبة وحنث النذر والمن والأذى والرياء في الصدقة ( مِنْ أَنْصارٍ ) ينصرونهم ويخلصونهم من عقاب الله سبحانه."},{"text":"۞ لَّيْسَ عَلَيْكَ هُدَىٰهُمْ وَلَـٰكِنَّ ٱللَّهَ يَهْدِى مَن يَشَآءُ ۗ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ فَلِأَنفُسِكُمْ ۚ وَمَا تُنفِقُونَ إِلَّا ٱبْتِغَآءَ وَجْهِ ٱللَّهِ ۚ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ","tafsir":"أي تظهروا ( الصَّدَقاتِ ) حين إعطائها ، بأن تعطوها فَنِعِمَّا هِيَ وَإِنْ تُخْفُوها وَتُؤْتُوهَا الْفُقَراءَ فَهُوَ خَيْرٌ لَكُمْ وَيُكَفِّرُ عَنْكُمْ مِنْ سَيِّئاتِكُمْ وَاللهُ بِما تَعْمَلُونَ خَبِيرٌ (271) لَيْسَ عَلَيْكَ هُداهُمْ وَلكِنَّ اللهَ يَهْدِي مَنْ يَشاءُ وَما تُنْفِقُوا مِنْ جهرا ، بقصد القربة لا بقصد الرياء ( فَنِعِمَّا هِيَ ) أي فنعم الشيء الصدقة الظاهرة فإنها توجب دفع التهمة واقتداء الناس ( وَإِنْ تُخْفُوها ) أي الصدقات ( وَتُؤْتُوهَا ) أي تعطوها سرا ( الْفُقَراءَ فَهُوَ خَيْرٌ لَكُمْ ) لأنه أقرب إلى القربة وأبعد عن الرياء وأحفظ لصون ماء وجه الآخذ ( وَيُكَفِّرُ ) أي يغفر ( عَنْكُمْ مِنْ سَيِّئاتِكُمْ ) أي بعض ذنوبكم بواسطة إعطاء الصدقة فإن صدقة السر تطفي غضب الرب ( وَاللهُ بِما تَعْمَلُونَ خَبِيرٌ ) فيجازيكم على أعمالكم ، فليس التصدق سرا غائبا عن الله سبحانه بل هو بكل شيء عليم. [273] امتنع بعض المسلمين عن التصدق إلى غير المسلم فنزلت ( لَيْسَ عَلَيْكَ هُداهُمْ ) فإنك لست مجبورا بأن تهديدهم وإنما عليك الإرشاد والبلاغ ( وَلكِنَّ اللهَ يَهْدِي مَنْ يَشاءُ ) إلى الصراط المستقيم ، بإراءته الطريق ، أو بإيصاله المطلوب ( وَما تُنْفِقُوا مِنْ خَيْرٍ فَلِأَنْفُسِكُمْ ) فإن نفعه الدنيوي والأخروي يعود إليكم ( وَما تُنْفِقُونَ ) أي ليس إنفاقكم ( إِلَّا ابْتِغاءَ وَجْهِ اللهِ ) أي لأجله سبحانه ، وأي شيء أحسن من أن ينفق الإنسان في سبيل خالقه ومنعمه والمتفضل عليه ( وَما تُنْفِقُوا مِنْ خَيْرٍ فَلِأَنْفُسِكُمْ وَما تُنْفِقُونَ إِلاَّ ابْتِغاءَ وَجْهِ اللهِ وَما تُنْفِقُوا مِنْ خَيْرٍ يُوَفَّ إِلَيْكُمْ وَأَنْتُمْ لا تُظْلَمُونَ (272) لِلْفُقَراءِ الَّذِينَ أُحْصِرُوا فِي سَبِيلِ اللهِ لا يَسْتَطِيعُونَ ضَرْباً فِي الْأَرْضِ يَحْسَبُهُمُ الْجاهِلُ أَغْنِياءَ مِنَ التَّعَفُّفِ تَعْرِفُهُمْ بِسِيماهُمْ لا يَسْئَلُونَ النَّاسَ إِلْحافاً خَيْرٍ يُوَفَّ إِلَيْكُمْ ) أي يوفر عليكم جزاءه وثوابه ( وَأَنْتُمْ لا تُظْلَمُونَ ) فتعطون جزاء إنفاقكم كاملا غير منقوص ، فالإنفاق لأنفسكم ، وثوابه يعود عليكم ، وهو في سبيل الله وما أجمل أن يعطي الإنسان شيئا يعود نفعه إليه ثم يثاب به في الآخرة ، ويرضى الله سبحانه عنه بذلك. [274] ولما بين الله سبحانه فضل الصدقة عقبه بأحسن مصارفها بقوله سبحانه : ( لِلْفُقَراءِ ) أي أن النفقة لهؤلاء ( الَّذِينَ أُحْصِرُوا فِي سَبِيلِ اللهِ ) أي منعوا والذي منعهم هو أنفسهم ، لأجل سبيل الله وإطاعته ، فقد نزلت الآية في أصحاب الصفة الذين تركوا كل شيء لأجل الإسلام وأحصروا أنفسهم للعبادة والجهاد بين يدي رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( لا يَسْتَطِيعُونَ ضَرْباً فِي الْأَرْضِ ) أي ذهابا فيها وعدم الاستطاعة اختيارية لا اضطرارية ( يَحْسَبُهُمُ الْجاهِلُ ) أي يظنهم الذي يجهل حالهم وباطن أمرهم ( أَغْنِياءَ مِنَ التَّعَفُّفِ ) الامتناع من السؤال فإن الناس إذا رأوا تعففهم ظنوهم أغنياء لما عهدوا من سؤال الفقراء ( تَعْرِفُهُمْ ) أي تعرف إنهم فقراء ( بِسِيماهُمْ ) أي من وجوههم وأحوالهم يكون الفقر عليها باد ( لا يَسْئَلُونَ النَّاسَ إِلْحافاً ) أي كما هو شأن كثير من الفقراء ، بمعنى أنه ليس منهم سؤال فيكون إلحافا ، وَما تُنْفِقُوا مِنْ خَيْرٍ فَإِنَّ اللهَ بِهِ عَلِيمٌ (273) الَّذِينَ يُنْفِقُونَ أَمْوالَهُمْ بِاللَّيْلِ وَالنَّهارِ سِرًّا وَعَلانِيَةً فَلَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ (274) الَّذِينَ يَأْكُلُونَ الرِّبا لا يَقُومُونَ إِلاَّ كَما يَقُومُ الَّذِي يَتَخَبَّطُهُ الشَّيْطانُ مِنَ الْمَسِّ لا إنهم يسألون من غير إلحاف ( وَما تُنْفِقُوا مِنْ خَيْرٍ ) كل شيء يطلق عليه الخير من دار أو عقار أو درهم أو دينار أو غيرها ( فَإِنَّ اللهَ بِهِ عَلِيمٌ ) لا يفوته شيء فيجازيكم جزاء حسنا."},{"text":"لِلْفُقَرَآءِ ٱلَّذِينَ أُحْصِرُوا۟ فِى سَبِيلِ ٱللَّهِ لَا يَسْتَطِيعُونَ ضَرْبًا فِى ٱلْأَرْضِ يَحْسَبُهُمُ ٱلْجَاهِلُ أَغْنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعْرِفُهُم بِسِيمَـٰهُمْ لَا يَسْـَٔلُونَ ٱلنَّاسَ إِلْحَافًا ۗ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ","tafsir":""},{"text":"ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُم بِٱلَّيْلِ وَٱلنَّهَارِ سِرًّا وَعَلَانِيَةً فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ","tafsir":""},{"text":"ٱلَّذِينَ يَأْكُلُونَ ٱلرِّبَوٰا۟ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِى يَتَخَبَّطُهُ ٱلشَّيْطَـٰنُ مِنَ ٱلْمَسِّ ۚ ذَٰلِكَ بِأَنَّهُمْ قَالُوٓا۟ إِنَّمَا ٱلْبَيْعُ مِثْلُ ٱلرِّبَوٰا۟ ۗ وَأَحَلَّ ٱللَّهُ ٱلْبَيْعَ وَحَرَّمَ ٱلرِّبَوٰا۟ ۚ فَمَن جَآءَهُۥ مَوْعِظَةٌ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمْرُهُۥٓ إِلَى ٱللَّهِ ۖ وَمَنْ عَادَ فَأُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ","tafsir":"بالليل سرا وعلانية وبالنهار سرا وعلانية ( فَلَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ ) إن الآية وإن كانت عامة إلا إنها نزلت في علي عليه‌السلام حيث كانت له أربعة دراهم فتصدق باثنين منها نهارا سرا وعلانية وباثنين ليلا سرا وعلانية (1) ، وقد تقدم معنى ( لا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ ) . [276] وحيث كانت الآيات حول الإنفاق ، ناسب السياق ذكر الربا ، فإنه عكس الإنفاق إذ هو استيلاء على أموال الناس من غير مبرر ، بخلاف الإنفاق الذي هو إعطاء ماله للناس من غير مكسب وتجارة ( الَّذِينَ يَأْكُلُونَ الرِّبا ) وأكله كناية عن أخذه وإن لم يتصرف فيه ( لا يَقُومُونَ إِلَّا كَما يَقُومُ الَّذِي يَتَخَبَّطُهُ الشَّيْطانُ مِنَ الْمَسِ ) الرجل الذي مسه ( 1) من لا يحضره الفقيه : ج 2 ص 288. ذلِكَ بِأَنَّهُمْ قالُوا إِنَّمَا الْبَيْعُ مِثْلُ الرِّبا وَأَحَلَّ اللهُ الْبَيْعَ وَحَرَّمَ الرِّبا الشيطان فصرع وتغير حاله ودارت عينه وزال توازن جسده وزبد فمه إذا أراد أن يقوم لبقية ما فيه من الشعور يقوم بعض القيام بكل انحراف وتأرجح ثم يسقط على الأرض ، وهكذا الإنسان الذي يأكل الربا حتى اعتاد ذلك يكون أشبه شيء في عملية انتهاب أموال الناس بمن تخبطه الشيطان الذي يريد أن يقوم فإن تفكيره تفكير منحرف كتفكير المطروح وعينه تنظر بزيغ إلى أموال الناس كعين المصروع وفيه يلهج حول المال بانحراف كفم المصروع وإذا أراد أن يقوم من كبوته ويترك الربا ويأخذ بالجادة المستقيمة حول المال لا يلبث أن يسقط في الربا كما اعتاد من أكله وصار الابتزاز لمال الناس ملكته ، وهذا تشبيه رائع مفزع وهكذا يكونون هؤلاء يوم القيامة. فقد روى الإمام الصادق عليه‌السلام عن الرسول صلى‌الله‌عليه‌وآله‌وسلم أنه قال : لما أسري بي إلى السماء رأيت أقواما يريد أحدهم أن يقوم ولا يقدر عليه من عظم بطنه فقلت من هؤلاء يا جبريل فقال : هؤلاء الذين يأكلون الربا لا يقومون إلا كما يقوم الذي يتخبطه الشيطان من المس (1) ، وقد ثبت في العلم أن الأرواح الشريرة قد تدخل في الإنسان فتسبب له صرعا ( ذلِكَ ) الأكل للربا الذي اعتادوه بسبب أنهم ( قالُوا ) ليس في أكل الربا بأس ف ( إِنَّمَا الْبَيْعُ مِثْلُ الرِّبا ) كلاهما تعامل برضى الطرفين ( وَ ) ليس كذلك فمنطقهم غلط فقد ( أَحَلَّ اللهُ الْبَيْعَ ) لما فيه من الفوائد ( وَحَرَّمَ الرِّبا ) لما فيه من ( 1) بحار الأنوار : ج 100 ص 116. فَمَنْ جاءَهُ مَوْعِظَةٌ مِنْ رَبِّهِ فَانْتَهى فَلَهُ ما سَلَفَ وَأَمْرُهُ إِلَى اللهِ وَمَنْ عادَ فَأُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ (275) المضار ، ويكفي أن نلمح إلى ضرر واحد هو أن معطي الربا إما ساقته الضرورة إلى الاقتراض كمرض أو نحوه مما ألجأ للاقتراض برباء فما أقبح أن يستغل الإنسان أخيه في مثل هذا الموقع مما يجدر به أن يساعده ويسعفه ، وإما اقترض للتجارة وهذا لا يخلو من أحد أحوال ثلاثة : الأول أن يخسر والثاني أن لا يربح ولا يخسر وما أقبح في هاتين الصورتين أن يأخذ صاحب المال زيادة بينما خسر العامل في الأول ولم يربح في الثاني والثالث أن يربح ، وقد قرر الإسلام المضاربة والاشتراك في المربح فيما يجبر المقترض أن يدفع بمقدار خاص إلى المقرض بينما قد ربح بمقداره وقد ربح أقل وقد ربح أكثر. ( فَمَنْ جاءَهُ مَوْعِظَةٌ مِنْ رَبِّهِ ) في تركه أخذ الربا ( فَانْتَهى ) وتاب ( فَلَهُ ما سَلَفَ ) فكل ربا أكله الناس بجهالة وعدم علم بحرمته أو قبل الإسلام لا يسترد منهم ( وَأَمْرُهُ إِلَى اللهِ ) سبحانه لا إلى الناس حتى يقول من أعطاه الربا : ردّ عليّ ما أخذت مني ، أو أمره في قبول الله توبته إليه سبحانه ( وَمَنْ عادَ ) إلى الربا بعد النهي والإسلام ( فَأُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ ) أبد الآبدين إلا أن يدركهم الله برحمته كما قال سبحانه : ( إِنَّ اللهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ ما دُونَ ذلِكَ لِمَنْ يَشاءُ ) (1) . ( 1) النساء : 117. يَمْحَقُ اللهُ الرِّبا وَيُرْبِي الصَّدَقاتِ وَاللهُ لا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ (276) إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ وَأَقامُوا الصَّلاةَ وَآتَوُا الزَّكاةَ لَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ (277) يا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللهَ وَذَرُوا ما بَقِيَ مِنَ الرِّبا"},{"text":"يَمْحَقُ ٱللَّهُ ٱلرِّبَوٰا۟ وَيُرْبِى ٱلصَّدَقَـٰتِ ۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ","tafsir":""},{"text":"إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ","tafsir":"أي ينقصه ويتلفه ويهلكه فما ظن المرابي أنه سبب زيادة أمواله يكون سببا لهلاكه ونقصانه فإن الربا يسبب غضب الناس وسخطهم على المرابي مما يثير حربا أو نهبا من الناس أو الحكومات لأمواله فيذهب الأصل والفرع ( وَيُرْبِي ) أي يزيد وينمي ( الصَّدَقاتِ ) فإنه وإن ذهب جزء من المال بالصدقة لكنها تسبب حب الناس والتفافهم وتعاونهم مع المتصدق مما ينجر إلى زيادة أمواله ، وهذا مع الغض عن المحق والنماء الخارجين عن الطبيعة مما يشأهما الله سبحانه بلا واسطة عادية ( وَاللهُ لا يُحِبُّ كُلَّ كَفَّارٍ ) كثير الكفر ( أَثِيمٍ ) أي مذنب وفي هذا دلالة على أن آكل الربا كفار أثيم."},{"text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَذَرُوا۟ مَا بَقِىَ مِنَ ٱلرِّبَوٰٓا۟ إِن كُنتُم مُّؤْمِنِينَ","tafsir":"بالأصول الاعتقادية ( وَعَمِلُوا الصَّالِحاتِ ) بأن أتوا بالواجبات وتركوا المحرمات ( وَأَقامُوا الصَّلاةَ وَآتَوُا الزَّكاةَ ) تخصيص بعد التعميم لأهميتهما ( لَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ ) وقد مر تفسير عدم الخوف وعدم الحزن."},{"text":"فَإِن لَّمْ تَفْعَلُوا۟ فَأْذَنُوا۟ بِحَرْبٍ مِّنَ ٱللَّهِ وَرَسُولِهِۦ ۖ وَإِن تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَٰلِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ","tafsir":"خافوا من عقابه ( وَذَرُوا ما بَقِيَ مِنَ الرِّبا ) إِنْ كُنْتُمْ مُؤْمِنِينَ (278) فَإِنْ لَمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِنَ اللهِ وَرَسُولِهِ وَإِنْ تُبْتُمْ فَلَكُمْ رُؤُسُ أَمْوالِكُمْ لا تَظْلِمُونَ وَلا تُظْلَمُونَ (279) مما كنتم تطلبونه قبل الإسلام وقد روي عن الإمام الباقر عليه‌السلام أنه قال : إن الوليد بن المغيرة كان يربي في الجاهلية وقد بقي له بقايا على ثقيف فأراد خالد بن الوليد المطالبة بها بعد أن أسلم فنزلت الآية ( إِنْ كُنْتُمْ مُؤْمِنِينَ ) بالإسلام حقا فإن المؤمن هو الذي يأتمر بالأوامر وينزجر بالزواجر."},{"text":"وَإِن كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَىٰ مَيْسَرَةٍ ۚ وَأَن تَصَدَّقُوا۟ خَيْرٌ لَّكُمْ ۖ إِن كُنتُمْ تَعْلَمُونَ","tafsir":"ولم تنقادوا إلى هذا النهي بل أكلتم الربا بعد النهي ( فَأْذَنُوا بِحَرْبٍ مِنَ اللهِ وَرَسُولِهِ ) أي اعملوا القتال مع الله ورسوله صلى‌الله‌عليه‌وآله‌وسلم ، فأكل الربا يكون كمن أعلن الحرب مع الإله والرسول صلى‌الله‌عليه‌وآله‌وسلم ، وذلك من أفظع الجرائم ، وعاقبته خسران الدين والدنيا ، و حكم آكل الربا إنه يؤدب مرتين ثم يقتل في الثالثة كما روي عن الإمام الصادق عليه‌السلام (1) ( وَإِنْ تُبْتُمْ ) ولم تأخذوا الربا ( فَلَكُمْ رُؤُسُ أَمْوالِكُمْ ) دون الزيادة التي حصلتموها بالربا ولا مفهوم للآية بأنهم إن لم يتوبوا فليس لهم رأس المال ، بل المراد أن لكم رأس المال فما تبغون بالزيادة ( لا تَظْلِمُونَ ) الناس بأخذ الزيادة منهم ( وَلا تُظْلَمُونَ ) بالنقصان من رأس المال. ( 1) من لا يحضره الفقيه : ج 4 ص 70. وَإِنْ كانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلى مَيْسَرَةٍ وَأَنْ تَصَدَّقُوا خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ (280) وَاتَّقُوا يَوْماً تُرْجَعُونَ فِيهِ إِلَى اللهِ ثُمَّ تُوَفَّى كُلُّ نَفْسٍ ما كَسَبَتْ وَهُمْ لا يُظْلَمُونَ (281) يا أَيُّهَا الَّذِينَ آمَنُوا إِذا تَدايَنْتُمْ"},{"text":"وَٱتَّقُوا۟ يَوْمًا تُرْجَعُونَ فِيهِ إِلَى ٱللَّهِ ۖ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ","tafsir":"فيمن تطلبون منه ـ ممن ذكر أنه يرجع رأس المال ـ ( ذُو عُسْرَةٍ ) بأن كان رأس مالكم الذي تطلبونه عند ذي عسرة لا يتمكن من أدائه لعسره وضيقه فاللازم نظرة إلى انتظار وتأخير ( إِلى مَيْسَرَةٍ ) أي إلى حال يسار المديون والجملة خبرية معناها الأمر ، أي فأنظروه إلى وقت يساره ( وَأَنْ تَصَدَّقُوا ) على المعسر بما عليه من الدين بأن تجعلوا طلبكم صدقة له ( خَيْرٌ لَكُمْ ) في الدنيا يجلب المحبة والبركة من الله سبحانه وفي الآخرة بالثواب الجزيل ( إِنْ كُنْتُمْ تَعْلَمُونَ ) أي إن كنتم تعلمون الخير من الشر وتميزون ما ينفعكم مما يضركم لعلمتم أن هبة الدين للمعسر خير لكم."},{"text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَدَايَنتُم بِدَيْنٍ إِلَىٰٓ أَجَلٍ مُّسَمًّى فَٱكْتُبُوهُ ۚ وَلْيَكْتُب بَّيْنَكُمْ كَاتِبٌۢ بِٱلْعَدْلِ ۚ وَلَا يَأْبَ كَاتِبٌ أَن يَكْتُبَ كَمَا عَلَّمَهُ ٱللَّهُ ۚ فَلْيَكْتُبْ وَلْيُمْلِلِ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبْخَسْ مِنْهُ شَيْـًٔا ۚ فَإِن كَانَ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ سَفِيهًا أَوْ ضَعِيفًا أَوْ لَا يَسْتَطِيعُ أَن يُمِلَّ هُوَ فَلْيُمْلِلْ وَلِيُّهُۥ بِٱلْعَدْلِ ۚ وَٱسْتَشْهِدُوا۟ شَهِيدَيْنِ مِن رِّجَالِكُمْ ۖ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌ وَٱمْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحْدَىٰهُمَا فَتُذَكِّرَ إِحْدَىٰهُمَا ٱلْأُخْرَىٰ ۚ وَلَا يَأْبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُوا۟ ۚ وَلَا تَسْـَٔمُوٓا۟ أَن تَكْتُبُوهُ صَغِيرًا أَوْ كَبِيرًا إِلَىٰٓ أَجَلِهِۦ ۚ ذَٰلِكُمْ أَقْسَطُ عِندَ ٱللَّهِ وَأَقْوَمُ لِلشَّهَـٰدَةِ وَأَدْنَىٰٓ أَلَّا تَرْتَابُوٓا۟ ۖ إِلَّآ أَن تَكُونَ تِجَـٰرَةً حَاضِرَةً تُدِيرُونَهَا بَيْنَكُمْ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَلَّا تَكْتُبُوهَا ۗ وَأَشْهِدُوٓا۟ إِذَا تَبَايَعْتُمْ ۚ وَلَا يُضَآرَّ كَاتِبٌ وَلَا شَهِيدٌ ۚ وَإِن تَفْعَلُوا۟ فَإِنَّهُۥ فُسُوقٌۢ بِكُمْ ۗ وَٱتَّقُوا۟ ٱللَّهَ ۖ وَيُعَلِّمُكُمُ ٱللَّهُ ۗ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ","tafsir":"فلا تأكلوا الربا ولا تؤاخذوا المعسرين بل تصدقوا عليهم ، فإن إتيان الحرام موجب للعقاب والتصدق موجب للثواب ( ثُمَّ تُوَفَّى ) أي تعطى وافيا ( كُلُّ نَفْسٍ ما كَسَبَتْ ) من خير أو شر ( وَهُمْ لا يُظْلَمُونَ ) شيئا فلا ينقص من أجورهم شيء كما لا يزاد في عذابهم أكثر من استحقاقهم ، ومعنى الرجوع إلى الله الرجوع إلى حكمه وأمره وقضائه وجزائه."},{"text":"۞ وَإِن كُنتُمْ عَلَىٰ سَفَرٍ وَلَمْ تَجِدُوا۟ كَاتِبًا فَرِهَـٰنٌ مَّقْبُوضَةٌ ۖ فَإِنْ أَمِنَ بَعْضُكُم بَعْضًا فَلْيُؤَدِّ ٱلَّذِى ٱؤْتُمِنَ أَمَـٰنَتَهُۥ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ ۗ وَلَا تَكْتُمُوا۟ ٱلشَّهَـٰدَةَ ۚ وَمَن يَكْتُمْهَا فَإِنَّهُۥٓ ءَاثِمٌ قَلْبُهُۥ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ","tafsir":"أي تعاملتم بالدين ودان بعضكم بِدَيْنٍ إِلى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ وَلْيَكْتُبْ بَيْنَكُمْ كاتِبٌ بِالْعَدْلِ وَلا يَأْبَ كاتِبٌ أَنْ يَكْتُبَ كَما عَلَّمَهُ اللهُ فَلْيَكْتُبْ وَلْيُمْلِلِ الَّذِي عَلَيْهِ الْحَقُّ وَلْيَتَّقِ اللهَ رَبَّهُ وَلا يَبْخَسْ مِنْهُ شَيْئاً بعضا في بيع أو غيره ( بِدَيْنٍ ) إما تأكيد وإما لدفع توهم أن يكون المراد من المداينة المجازاة كما قال الشاعر « ولا أنت دياني فتجزيني » ( إِلى أَجَلٍ مُسَمًّى ) أي مدة قد سميت في العقد كما لو دائنه إلى سنة أو باعه نسيئة إلى ستة أشهر مثلا ( فَاكْتُبُوهُ ) أي اكتبوا ذلك الدين في صك وأنه إلى أية مدة لئلا يقع فيه نسيان أو جحود أو خلاف ( وَلْيَكْتُبْ بَيْنَكُمْ ) كتاب الدين ( كاتِبٌ بِالْعَدْلِ ) بالحق لا يزيد في المقدار والأجل والوصف ولا ينقص منها ( وَلا يَأْبَ ) أي لا يمتنع ( كاتِبٌ ) أي شخص كان من المتعاملين أو غيرهما ( أَنْ يَكْتُبَ ) الصك ( كَما عَلَّمَهُ اللهُ ) بأن يبخل فلا يكتب ، فالتكليف من الله سبحانه وهو في مقابل أن علمه تعالى الكتابة والعلم فلا يثقل أو يبطئ أو يبخل ( فَلْيَكْتُبْ ) الكاتب ( وَلْيُمْلِلِ ) بمعنى ليملأ فإن الإملال والإملاء بمعنى واحد يلقي صيغة الكتابة على الكاتب ( الَّذِي عَلَيْهِ الْحَقُ ) أي المديون حتى يقر على نفسه أولا ، حتى لا يقول زائدا على الحق ثانيا ، فالذي له الحق لو أملى كان معرضا لأن يقول الزيادة ( وَلْيَتَّقِ اللهَ ) الكاتب أو المديون ( رَبَّهُ ) فإنه رب له فكيف يخالف أمره ( وَلا يَبْخَسْ ) أي لا ينقص الكاتب أو المديون ( مِنْهُ ) أي من الحق ( شَيْئاً ) أما نقص الكاتب فواضح وأما نقص المديون كأن يجعل فَإِنْ كانَ الَّذِي عَلَيْهِ الْحَقُّ سَفِيهاً أَوْ ضَعِيفاً أَوْ لا يَسْتَطِيعُ أَنْ يُمِلَّ هُوَ فَلْيُمْلِلْ وَلِيُّهُ بِالْعَدْلِ وَاسْتَشْهِدُوا شَهِيدَيْنِ مِنْ رِجالِكُمْ فَإِنْ لَمْ يَكُونا رَجُلَيْنِ فَرَجُلٌ وَامْرَأَتانِ مِمَّنْ تَرْضَوْنَ مِنَ الشُّهَداءِ أَنْ تَضِلَّ إِحْداهُما فَتُذَكِّرَ إِحْداهُمَا الْأُخْرى الدينار والذي هو مقابل ثوب في مقابل ثوبين ( فَإِنْ كانَ الَّذِي عَلَيْهِ الْحَقُّ سَفِيهاً ) بحيث لم يتمكن من الإملاء ( أَوْ ضَعِيفاً ) لجنون أو كبر أو صغر أو نحوها ( أَوْ لا يَسْتَطِيعُ أَنْ يُمِلَّ هُوَ ) لخرس أو عذر آخر مع عدم السفاهة والضعف ( فَلْيُمْلِلْ وَلِيُّهُ ) أي ولي من عليه الحق ( بِالْعَدْلِ ) بلا إفراط أو تفريط ( وَاسْتَشْهِدُوا ) أي اطلبوا شهادة ( شَهِيدَيْنِ مِنْ رِجالِكُمْ ) على المكتوب لينفع ذلك عند الترافع والمخاصمة لدى التخالف ، ولعل قيد من رجالكم لإخراج الكفار ( فَإِنْ لَمْ يَكُونا ) أي لم يكن الشاهدين ( رَجُلَيْنِ ) لعدم حضورهما أو عدم إرادة المستشهد ( فَرَجُلٌ وَامْرَأَتانِ ) يشهدون على الكتابة ، أو فليشهد رجل وامرأتان ( مِمَّنْ تَرْضَوْنَ مِنَ الشُّهَداءِ ) لوثاقتهم أو عدالتهم إذ لا تقبل شهادة من عداهم لدى المخالفة والتراخ ، وإنما جعلت المرأتان مكان رجل واحد لأن المرأة لضعف ذاكرتها كما ثبت في العلم الحديث يتطرق إليها من النسيان ما لا يتطرق إلى الرجل ، ولذا قال سبحانه : ( أَنْ تَضِلَّ إِحْداهُما ) من الضلال أي تخطأ وتشتبه وتنسى ( فَتُذَكِّرَ إِحْداهُمَا ) التي لم تضل ( الْأُخْرى ) التي نسيت وضلت ، و « أن » إما بمعنى « لئلا » وتكون جملة « فتذكر » منقطعة ، أي إن ضلّت تذكر الثانية الأولى ، وأما أصلها « إن » بالكسر ، صفة وَلا يَأْبَ الشُّهَداءُ إِذا ما دُعُوا وَلا تَسْئَمُوا أَنْ تَكْتُبُوهُ صَغِيراً أَوْ كَبِيراً إِلى أَجَلِهِ ذلِكُمْ أَقْسَطُ عِنْدَ اللهِ وَأَقْوَمُ لِلشَّهادَةِ وَأَدْنى أَلاَّ تَرْتابُوا إِلاَّ أَنْ تَكُونَ تِجارَةً حاضِرَةً لامرأتان ، والأول أقرب ( وَلا يَأْبَ ) أي لا يمتنع ( الشُّهَداءِ ) الذين يراد إشهادهم للدين ـ وسموا شهداء بمجاز المشارفة ـ ( إِذا ما دُعُوا ) لتحمل الشهادة وهذا أمر إيجابي أو استحبابي ، أو المراد الأعم من التحمل والأداء. ( وَلا تَسْئَمُوا ) أي لا تضجروا أيها المتداينون ( أَنْ تَكْتُبُوهُ ) أي تكتبوا الدين أو تكتبوا الحق ( صَغِيراً ) كان الحق والدين ( أَوْ كَبِيراً ) وهذا تأديب لمن يترك كتابة الصغير لعدم الاهتمام به ، فكثيرا ما يقع التنازع في الصغير ( إِلى أَجَلِهِ ) أي إلى أجل الدين ومدته ، وفيه تنبيه إلى أن الكتابة تبقى إلى الأجل فتنفع هناك ، أو المعنى كتابة تتضمن إلى الأجل ، فيعين في المكتوب أجل الدين. ( ذلِكُمْ ) ذا إشارة إلى الكتاب الذي يكتب في المداينة « وكم » خطاب إلى الذين آمنوا ( أَقْسَطُ عِنْدَ اللهِ ) أي أعدل ، بمعنى أقرب إلى العدل وإلا فليس في العدل مفاضلة حقيقية ( وَأَقْوَمُ لِلشَّهادَةِ ) فيه تقوم الشهادة التي تؤمن عن الزيادة والنقصان ( وَأَدْنى أَلَّا تَرْتابُوا ) أي أقرب إلى عدم الريب في المبلغ والأجل فالله يريده وأنتم لا تشكون ، والشهادة تستقيم ، بسبب الكتابة والصك وما ذكر من الكتابة عامة لكل مكان ( إِلَّا أَنْ تَكُونَ ) المعاملة ـ المفهوم من الكلام ـ ( تِجارَةً حاضِرَةً ) معجلة غير تُدِيرُونَها بَيْنَكُمْ فَلَيْسَ عَلَيْكُمْ جُناحٌ أَلاَّ تَكْتُبُوها وَأَشْهِدُوا إِذا تَبايَعْتُمْ وَلا يُضَارَّ كاتِبٌ وَلا شَهِيدٌ وَإِنْ تَفْعَلُوا فَإِنَّهُ فُسُوقٌ بِكُمْ وَاتَّقُوا اللهَ وَيُعَلِّمُكُمُ اللهُ وَاللهُ بِكُلِّ شَيْءٍ عَلِيمٌ (282) مؤجلة كغالب التجارات النقدية التي تجري في الأسواق ( تُدِيرُونَها بَيْنَكُمْ ) إدارة يد بيد ، ومعنى الإدارة المناقلة ، فينقل هذا ماله إلى ذاك وينقل ذاك عنه إلى هذا ( فَلَيْسَ عَلَيْكُمْ جُناحٌ ) وحرج ( أَلَّا تَكْتُبُوها ) فلا مانع من عدم كتابة التجارة النقدية إذ الكتابة للوثيقة وهنا لا يحتاج إلى الوثيقة ( وَأَشْهِدُوا إِذا تَبايَعْتُمْ ) فإنه يستحب للإنسان الذي يريد المبايعة أن يأخذ الشاهد ، ففي المعاملة كثيرا ما يقع من نزاع وخصام فإذا كان هناك شهادة يقل وطئ النزاع ، والآية وإن كانت عامة لفظا لكن لا يعد أن لا يراد بها الإطلاق من المعاملات الجزئية اليومية لعدم تعارف الأشهاد منذ زمان الرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَلا يُضَارَّ كاتِبٌ وَلا شَهِيدٌ ) بأن يكلف الكاتب الكتابة ويكلف الشاهد الشهادة في حال يكون حرجا عليهما وضررا ، كما تعارف الآن عند الحكومات المنحرفة فإنه يحضر الشاهد ويعنت ويضار فإن في مضارتها زهادة للناس عن الكتابة والشهادة ( وَإِنْ تَفْعَلُوا ) المضارة بها ( فَإِنَّهُ فُسُوقٌ بِكُمْ ) أي خروج عن أمر الله سبحانه لسببكم أيها المضارون ( وَاتَّقُوا اللهَ ) فيما أمركم ونهاكم ( وَيُعَلِّمُكُمُ اللهُ ) مصالحكم فاتبعوه ( وَاللهُ بِكُلِّ شَيْءٍ عَلِيمٌ ) وأنتم لا تعلون وما أجدر بالجاهل أن يتبع العالم ، عن علي بن إبراهيم أن في وَإِنْ كُنْتُمْ عَلى سَفَرٍ وَلَمْ تَجِدُوا كاتِباً فَرِهانٌ مَقْبُوضَةٌ فَإِنْ أَمِنَ بَعْضُكُمْ بَعْضاً فَلْيُؤَدِّ الَّذِي اؤْتُمِنَ أَمانَتَهُ وَلْيَتَّقِ اللهَ رَبَّهُ وَلا تَكْتُمُوا الشَّهادَةَ وَمَنْ يَكْتُمْها فَإِنَّهُ آثِمٌ قَلْبُهُ"},{"text":"لِّلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَإِن تُبْدُوا۟ مَا فِىٓ أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ ٱللَّهُ ۖ فَيَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ","tafsir":"أيها المتداينون المتبايعون ( عَلى سَفَرٍ ) أي مسافرين والتعبير بلفظ « على » لركوب المسافر غالبا ( وَلَمْ تَجِدُوا كاتِباً ) يكتب الدين والمعاملة ( فَرِهانٌ مَقْبُوضَةٌ ) تقوم مقام الصك ورهان جمع رهن ، وهو اسم للوثيقة ولذا جاءت الصفة بالتأنيث والقبض شرط في صحة الرهن ، ولذا وصفه بالقبض ( فَإِنْ أَمِنَ بَعْضُكُمْ ) وهو صاحب الحق ( بَعْضاً ) وهو من عليه الحق بأن وثق به وأنه يؤدي الدين بدون صك ولا رهن ، فأعطاه الدين مجردا عن الأمرين ( فَلْيُؤَدِّ الَّذِي اؤْتُمِنَ ) أي المديون ( أَمانَتَهُ ) فلا ينكر ولا يمطل ، كفاء لما رآه أهلا ( وَلْيَتَّقِ اللهَ رَبَّهُ ) فإن الله شهيد ويجازي فإن أنكر أو مطل أو بخس كان معرضا نفسه لعقوبة الله سبحانه ( وَلا تَكْتُمُوا ) أيها الشهود ( الشَّهادَةَ ) التي تحملتموها ( وَمَنْ يَكْتُمْها ) أي يخفي الشهادة فلا يحضر لأدائها أو يؤديها على خلاف الواقع ( فَإِنَّهُ آثِمٌ قَلْبُهُ ) فقد عزم القلب على الكتمان وأطاعته الجوارح واللسان ولأن الكتمان أنسب إلى القلب لكونه في محل وَاللهُ بِما تَعْمَلُونَ عَلِيمٌ (283) لِلَّهِ ما فِي السَّماواتِ وَما فِي الْأَرْضِ وَإِنْ تُبْدُوا ما فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحاسِبْكُمْ بِهِ اللهُ فَيَغْفِرُ لِمَنْ يَشاءُ وَيُعَذِّبُ مَنْ يَشاءُ وَاللهُ عَلى كُلِّ شَيْءٍ قَدِيرٌ (284) مكتوم ( وَاللهُ بِما تَعْمَلُونَ ) من إخفاء الشهادة وإبدائها ( عَلِيمٌ ) فلا تفعلوا ما يوجب عقابه وسخطه."},{"text":"ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَٱلْمُؤْمِنُونَ ۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَـٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِۦ ۚ وَقَالُوا۟ سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ ٱلْمَصِيرُ","tafsir":"فما تعاطونه من الأملاك ليست لكم إلا مجازا وإنما هي ملك له سبحانه فاعملوا فيها حسب ما أمركم ولا تخالفوا أمر المالك الحقيقي ( وَإِنْ تُبْدُوا ) أي تظهروا ( ما فِي أَنْفُسِكُمْ ) بما تعلمونه ويخفى على غيركم ( أَوْ تُخْفُوهُ ) فتكتموه ( يُحاسِبْكُمْ بِهِ اللهُ ) فإن جميع الأعمال والأقوال والأفكار تحت المحاسبة ، أو أن الإبداء والإخفاء لما في النفس محسوب عليهما ، وهذا العموم للتناسق مع إبداء الشهادة وكتمانها ( فَيَغْفِرُ لِمَنْ يَشاءُ وَيُعَذِّبُ مَنْ يَشاءُ ) حسب ما تقتضيه الحكمة البالغة فالغفران والشفاعة ليسا اعتباطا وإنما ينصبان على المحل القابل ( وَاللهُ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) من المغفرة والعقاب ولا يخفى أن العذاب على ما في النفس لا ينافي ما دل على عدم العقاب ، على العزم على المعصية لاختلاف المعاصي ، واختلاف أنواع العقاب فلا شبهة في أن من يعزم على المعاصي وإن لم يفعلها أبعد عن قرب الحلال ممن لا يعزم إطلاقا ، وهذا البعد هو نوع من العذاب أو يجمع بنحو ذلك. آمَنَ الرَّسُولُ بِما أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللهِ وَمَلائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقالُوا سَمِعْنا وَأَطَعْنا غُفْرانَكَ رَبَّنا وَإِلَيْكَ الْمَصِيرُ (285) [286] وهنا يرجع السياق إلى ذكر التوحيد والنبوة والشرائع جملة في لباس أنها لا تكلف الناس فوق الطاقة وسؤال المغفرة والعفو لتكون فذلكة للسورة ( آمَنَ الرَّسُولُ ) محمد صلى‌الله‌عليه‌وآله‌وسلم ( بِما أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ ) فهو أول مؤمن بما أنزل إليه وليس كرؤساء الأديان المفتعلة والملوك والحكام الذين لا يشملهم القانون ( وَالْمُؤْمِنُونَ كُلٌ ) أي كل واحد منهم ( آمَنَ بِاللهِ وَمَلائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ ) فليس المؤمن أن يقتنع بجانب واحد من جوانب الإسلام كما هو كثير في تابعي الأحزاب والمبادئ حيث أن ذا النشاط المتفايض منهم يقتنع منه بجانب واحد وإن ترك سائر الجوانب فإن لسان حال المؤمنين ( لا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ ) فلسنا كاليهود الذين لا يعترفون بالمسيح عليه‌السلام ونبي الإسلام صلى‌الله‌عليه‌وآله‌وسلم ولا كالنصارى الذين لا يعترفون بنبي الإسلام ، فلا تكون كمن يؤمن ببعض ويكفر ببعض ( وَقالُوا سَمِعْنا ) آيات الله وأحكامه ( وَأَطَعْنا ) أوامره ونواهيه لا كاليهود الذين قالوا سمعنا وعصينا ، يقولون ( غُفْرانَكَ ) أي نطلب مغفرتك ( رَبَّنا ) نعلم أن ( إِلَيْكَ الْمَصِيرُ ) فاغفر لنا حتى نكون في ذلك اليوم سعداء. [287] إن الأحكام التي سلفت في السورة وفي غيرها ليست مما لا يطاق لاَ يُكَلِّفُ اللّهُ نَفْسًا إِلاَّ وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لاَ تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا رَبَّنَا وَلاَ تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا فإنه ( لا يُكَلِّفُ اللهُ نَفْساً إِلَّا وُسْعَها ) فإن أوامره ونواهيه مستطاعة للمكلف وليس في الدين من حرج ، فلا يظن أحد أن الإيمان السابق ذكره في ( وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللهِ ) يوجب مشقة وعنتا وإرهاقا ( لَها ) أي للنفس ( ما كَسَبَتْ ) من الحسنات فالجزاء الحسن يجزى به من أحسن ( وَعَلَيْها ) أي على النفس ضرر ( مَا اكْتَسَبَتْ ) من الآثام والسيئات ولعل في مجيء الكسب من بابين « كسب » و « أكتسب » إفادة أن الطاعة طبيعية والمعصية تؤتي بالتكلف إذ للفظة الاكتساب ظلالا يفيد التعب والغضب بخلاف الكسب وتؤيده قاعدة « زيادة المبنى تدل على زيادة المعنى » وهناك يتوجه المؤمنون إلى الله داعين سائلين ( رَبَّنا لا تُؤاخِذْنا إِنْ نَسِينا أَوْ أَخْطَأْنا ) بلا نسيان وإنما تصح المؤاخذة فيهما لغلبة كون مقدماتهما اختيارية وما ينتهي إلى الاختيار يكون بالاختيار ( رَبَّنا وَلا تَحْمِلْ عَلَيْنا إِصْراً ) أي ثقلا فإن بعض التكاليف قد توجب ظروفها ثقلا وعنتا ، فالمؤمن يسأل أن يجنبه الله سبحانه مثل هذا الثقل ( كَما حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنا ) فإنهم بلجاجتهم استحقوا تحميل الثقل كما تقدم في قصة بقرة بني إسرائيل وكما قال سبحانه : ( فَبِظُلْمٍ مِنَ الَّذِينَ هادُوا حَرَّمْنا عَلَيْهِمْ طَيِّباتٍ أُحِلَّتْ لَهُمْ ) (1) ( 1) النساء : 161. رَبَّنَا وَلاَ تُحَمِّلْنَا مَا لاَ طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَآ أَنتَ مَوْلاَنَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ (286) ( رَبَّنا وَلا تُحَمِّلْنا ما لا طاقَةَ لَنا بِهِ ) وإن كان مقدورا لنا فإن عدم الطاقة ليس بمعنى عدم القدرة حتى يقال : إن الله لا يكلف غير المقدور فما وجه هذا الدعاء ؟ ( وَاعْفُ عَنَّا ) ذنوبنا ( وَاغْفِرْ لَنا ) خطايانا أي استرها ولا تبدها ( وَارْحَمْنا أَنْتَ مَوْلانا ) سيدنا والأولى بالتصرف فينا ( فَانْصُرْنا عَلَى الْقَوْمِ الْكافِرِينَ ) حتى نغلب عليهم في الحكم كما نغلب عليهم في الحجة. (3)"},{"text":"لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا ٱكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْرًا كَمَا حَمَلْتَهُۥ عَلَى ٱلَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ ۖ وَٱعْفُ عَنَّا وَٱغْفِرْ لَنَا وَٱرْحَمْنَآ ۚ أَنتَ مَوْلَىٰنَا فَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَـٰفِرِينَ","tafsir":""}]},"3":{"name":"آل عمران","verses":[{"text":"الٓمٓ","tafsir":""},{"text":"ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ","tafsir":"تقدم ما يحتمل أن يكون تفسيرا له."},{"text":"نَزَّلَ عَلَيْكَ ٱلْكِتَـٰبَ بِٱلْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَأَنزَلَ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ","tafsir":"فليس له شريك وهو الحي الذي لا يموت وإن كانت الحياة بالنسبة إليه تعالى تخالف الحياة بالنسبة إلينا فإن حياتنا غير ذواتنا وإنما هي صفة قائمة بنا بخلاف الحياة فيه سبحانه فإنه عين ذاته والقيوم هو القائم على كل نفس بما كسبت وعلى كل شيء"},{"text":"مِن قَبْلُ هُدًى لِّلنَّاسِ وَأَنزَلَ ٱلْفُرْقَانَ ۗ إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَـٰتِ ٱللَّهِ لَهُمْ عَذَابٌ شَدِيدٌ ۗ وَٱللَّهُ عَزِيزٌ ذُو ٱنتِقَامٍ","tafsir":"يا رسول الله ( الْكِتابَ ) أي القرآن ( بِالْحَقِ ) لا بالباطل فإن الإنزال قد يكون بالباطل وقد يكون بالحق ( مُصَدِّقاً لِما بَيْنَ يَدَيْهِ وَأَنْزَلَ التَّوْراةَ ) على موسى عليه‌السلام ( وَالْإِنْجِيلَ ) على عيسى عليه‌السلام ."},{"text":"إِنَّ ٱللَّهَ لَا يَخْفَىٰ عَلَيْهِ شَىْءٌ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ","tafsir":"إنزال القرآن عليك ، وكل هذه الكتب ( هُدىً لِلنَّاسِ ) فإنها تهديهم من الظلمات إلى النور ومن الباطل إلى الحق ومن الضلال إلى الرشاد ( وَأَنْزَلَ الْفُرْقانَ ) الفارق بين الحق والباطل وهو أعم من الكتب السابقة وسائر ما أنزل على أنبياء الله ورسله ( إِنَّ الَّذِينَ كَفَرُوا بِآياتِ اللهِ ) بحجج الله ودلالاته ( لَهُمْ عَذابٌ شَدِيدٌ ) في الدنيا بالفوضى والهرج والمرج والمشاكل كما قال تعالى ( وَمَنْ أَعْرَضَ عَنْ وَاللهُ عَزِيزٌ ذُو انْتِقامٍ (4) إِنَّ اللهَ لا يَخْفى عَلَيْهِ شَيْءٌ فِي الْأَرْضِ وَلا فِي السَّماءِ (5) هُوَ الَّذِي يُصَوِّرُكُمْ فِي الْأَرْحامِ كَيْفَ يَشاءُ لا إِلهَ إِلاَّ هُوَ الْعَزِيزُ الْحَكِيمُ (6) هُوَ الَّذِي أَنْزَلَ عَلَيْكَ الْكِتابَ مِنْهُ آياتٌ مُحْكَماتٌ ذِكْرِي فَإِنَّ لَهُ مَعِيشَةً ضَنْكاً ) (1) وفي الآخرة بالعقاب ( وَاللهُ عَزِيزٌ ) له العزة والقدرة بأن يفعل ما يشاء ( ذُو انْتِقامٍ ) ينتقم ممن حادّه وعصاه."},{"text":"هُوَ ٱلَّذِى يُصَوِّرُكُمْ فِى ٱلْأَرْحَامِ كَيْفَ يَشَآءُ ۚ لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ","tafsir":"فلا يظن عاص أنه يخفى على الله سبحانه ، فإنه يعلم كل شيء في الكون حتى وساوس القلوب وهواجس الصدور."},{"text":"هُوَ ٱلَّذِىٓ أَنزَلَ عَلَيْكَ ٱلْكِتَـٰبَ مِنْهُ ءَايَـٰتٌ مُّحْكَمَـٰتٌ هُنَّ أُمُّ ٱلْكِتَـٰبِ وَأُخَرُ مُتَشَـٰبِهَـٰتٌ ۖ فَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَـٰبَهَ مِنْهُ ٱبْتِغَآءَ ٱلْفِتْنَةِ وَٱبْتِغَآءَ تَأْوِيلِهِۦ ۗ وَمَا يَعْلَمُ تَأْوِيلَهُۥٓ إِلَّا ٱللَّهُ ۗ وَٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلٌّ مِّنْ عِندِ رَبِّنَا ۗ وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَـٰبِ","tafsir":"أي يعطيكم الصورة في بطون أمهاتكم ( كَيْفَ يَشاءُ ) من رجل وامرأة وجميل وقبيح وقصير وطويل وغيرها فكيف يخفى عليه شيء وهو يفعل مثل هذا الفعل الدقيق في ذلك المحل المظلم ( لا إِلهَ إِلَّا هُوَ ) فهو وحده إله الكون وخالقه ( الْعَزِيزُ ) في سلطانه ( الْحَكِيمُ ) فما يفعل شيئا عبثا بل يفعل ما يفعل بالحكمة."},{"text":"رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ ٱلْوَهَّابُ","tafsir":"يا رسول الله ( الْكِتابَ ) أي القرآن ( مِنْهُ ) أي قسم من الكتاب ( آياتٌ مُحْكَماتٌ ) غير متشابهات فالمفاد منها واضحة لا يخفى على أهل اللسان كقوله سبحانه ( قُلْ هُوَ اللهُ أَحَدٌ ) (2) ( 1) طه : 125. ( 2) الإخلاص : 2. هُنَّ أُمُّ الْكِتابِ وَأُخَرُ مُتَشابِهاتٌ فَأَمَّا الَّذِينَ فِي قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ ما تَشابَهَ مِنْهُ ( هُنَ ) أي تلك الآيات المحكمات ( أُمُّ الْكِتابِ ) أي أصله الذي يرجع إليه لدى الشك والخصام والجدال. ( وَأُخَرُ ) أي آيات أخر ( مُتَشابِهاتٌ ) والمتشابه هو الذي يحتمل وجهين أو وجوها مما سبب عدم إدراك الناس كلهم لها ، من تشابه ، وإنما يؤتى به إما امتحانا حتى يعرف المؤمن من المنافق أو لتقريب المطلب إلى أذهان الناس الذين لا يدركون الحقائق ككثير من آيات الصفات ونحوها كقوله سبحانه : ( إِلى رَبِّها ناظِرَةٌ ) (1) حيث أريد التفهيم من أن المؤمنين ينظرون إلى رحمة الله ، أو كقوله : ( ثُمَّ اسْتَوى إِلَى السَّماءِ ) (2) أو لأن المطلب دقيق لا تتحمله بعض العقول كآيات الجن والشيطان مما لا يتحملها عقل من إلف المادة فيشتبه الأمر عليه أو لأنه جيء به لاعتبار كلامي فاشتبه الأمر نحو ( نَسُوا اللهَ فَنَسِيَهُمْ ) (3) أو غير ذلك ، والمتشابه مما لا بد منه في الكلام الراقي كما لا يخفى بأدنى تأمل ( فَأَمَّا الَّذِينَ فِي قُلُوبِهِمْ زَيْغٌ ) أي ميل عن الحق وانحراف إما جهلا أو عنادا ( فَيَتَّبِعُونَ ما تَشابَهَ مِنْهُ ) اتباعا على خلاف المراد منه ويوجهون المتشابه حسب أهوائهم ومشتهياتهم كما يقول القائل ( 1) القيامة : 24. ( 2) البقرة : 30. ( 3) التوبة : 67. ابْتِغاءَ الْفِتْنَةِ وَابْتِغاءَ تَأْوِيلِهِ وَما يَعْلَمُ تَأْوِيلَهُ إِلاَّ اللهُ وَالرَّاسِخُونَ فِي الْعِلْمِ يَقُولُونَ آمَنَّا بِهِ كُلٌّ بالتجسم من ( إِلى رَبِّها ناظِرَةٌ ) وبالجبر من ( وَمَنْ يُضْلِلِ اللهُ فَما لَهُ مِنْ هادٍ ) (1) وبمعصية الأنبياء عليهم‌السلام من ( وَعَصى آدَمُ رَبَّهُ فَغَوى ) (2) ويكون الإسلام خاصا بالعرب من ( وَإِنَّهُ لَذِكْرٌ لَكَ وَلِقَوْمِكَ ) (3) وهكذا ( ابْتِغاءَ الْفِتْنَةِ ) أي لأجل تفتين الناس وإضلالهم ( وَابْتِغاءَ تَأْوِيلِهِ ) أي لأجل أن يكون له مجال في تأويل الكلام على غير المراد منه ليطابق هواه ومشتهاه ( وَما يَعْلَمُ تَأْوِيلَهُ ) التأويل هو ما يؤول وينتهي إليه الكلام فمثلا ظاهر ( إِلى رَبِّها ناظِرَةٌ ) إنهم ينظرون إلى الله لكن هذه الجملة تؤوّل إلى معنى أنهم ينظرون إلى رحمة الله ولطفه وثوابه ، كما يقال في العرف « إني أنظر إلى العقل وهو يسيّر الإنسان » إنه لا يريد النظر بالعين وإنما عرفان ذلك ( إِلَّا اللهُ ) فهو سبحانه يعلم المراد من كلامه ( وَالرَّاسِخُونَ ) أي الثابتون ( فِي الْعِلْمِ ) الذين لهم اطلاع على المعلومات وبأساليب الكلام وبما يدل عليه العقل والشرع وهذا ليس ببدع فإن القوانين المدنية لا يعرفها إلا من درسها وأتقنها وأساليب الكلام العربي لا يعرفها إلا من أتقن الأدب والبلاغة وهكذا ، إن الراسخين يعلمون تأويل المتشابه في حال كونهم ( يَقُولُونَ آمَنَّا بِهِ ) أي بالمتشابه كما آمنا بالمحكم ( كُلٌ ) من المحكم والمتشابه ( 1) الرعد : 34. ( 2) طه : 122. ( 3) الزخرف : 45. مِنْ عِنْدِ رَبِّنا وَما يَذَّكَّرُ إِلاَّ أُولُوا الْأَلْبابِ (7) رَبَّنا لا تُزِغْ قُلُوبَنا ( مِنْ عِنْدِ رَبِّنا ) فإذا لم يظهر المعنى في بادئ النظر لا ينكرون ولا يقولون بالتناقض ، فإنهم جمعوا بين فضيلتي العلم بالتأويل والإذعان بصحة المتشابه بخلاف الجهال فإنهم يعترضون على المتشابه أولا ويفسرون حسب أهوائهم ثانيا ، وهكذا نجد الآن في العرف العالم الورع يجمع بين الفضيلتين والجاهل يشتمل على الرذيلتين ( وَما يَذَّكَّرُ ) أي يتذكر ويرد المتشابه إلى المحكم وإلى ما دل من العقل والنقل ( إِلَّا أُولُوا الْأَلْبابِ ) أي أصحاب العقول الحصيفة ، ثم إنه ورد في الأحاديث أن المراد بالراسخين النبي والأئمة عليهم‌السلام ولا يخفى أنهم من أجلّ مصاديق الراسخين وذلك هو المراد لا الانحصار. [9] إن الراسخين في العلم يلتجئون إلى الله سبحانه قائلين ( رَبَّنا لا تُزِغْ قُلُوبَنا ) أي لا تملها عن الحق وإنما نسب الزيغ إليه سبحانه لأنه هو الذي هيأ الأسباب ليمتحن عباده فترك الإنسان ـ وعدم اللطف به ـ حتى يقع فريسة الشيطان من صنع الله سبحانه كما يقال أن الملك أفسد الرعية لا يراد أنه أفسدهم وإنما يراد تركهم حتى يفسدوا ، ولا يخفى الفرق بينه سبحانه وبين الملك لرعيته فإن الله حيث خلق الدنيا للاختبار لا بد وأن يهيئ الوسيلتين ليظهر المطيع من العاصي كما قال : ( كُلًّا نُمِدُّ هؤُلاءِ وَهَؤُلاءِ ) (1) بخلاف الملك فإنه لا يحق له أن يفسد الرعية حتى بتركهم وما يشاءون فإنه يأمر بالصلاح والإصلاح كما أن الله تعالى يسبل النعم على الجنات ولا يعاقبهم عقوبة ظاهرة في ( 1) الإسراء : 21. بَعْدَ إِذْ هَدَيْتَنا وَهَبْ لَنا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ (8) رَبَّنا إِنَّكَ جامِعُ النَّاسِ لِيَوْمٍ لا رَيْبَ فِيهِ إِنَّ اللهَ لا يُخْلِفُ الْمِيعادَ (9) إِنَّ الَّذِينَ كَفَرُوا الدنيا ، وذلك ليس جائز للملوك فإنه يجب إيقاف الجاني عند حده وإجراء العقاب عليه ثم إن الإنسان مهما كان من الرسوخ في العلم فإنه معرض للزلة كما زل « بلعم » قال سبحانه ( نَبَأَ الَّذِي آتَيْناهُ آياتِنا فَانْسَلَخَ مِنْها فَأَتْبَعَهُ الشَّيْطانُ فَكانَ مِنَ الْغاوِينَ ) (1) ولذا يدعو الراسخون ربهم سبحانه أن لا يقطع عنهم لطفه الخاص ولا يتركهم ليلعب بهم الشيطان كما يشاء ، إذ ( بَعْدَ إِذْ هَدَيْتَنا ) إلى دينك ( وَهَبْ لَنا مِنْ لَدُنْكَ ) من عندك ( رَحْمَةً ) ولطفا نثبت بها على دينك وطاعتك ( إِنَّكَ أَنْتَ الْوَهَّابُ ) الكثير الهبة لمن تشاء بما تشاء."},{"text":"رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوْمٍ لَّا رَيْبَ فِيهِ ۚ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ","tafsir":""},{"text":"إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَـٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا ۖ وَأُو۟لَـٰٓئِكَ هُمْ وَقُودُ ٱلنَّارِ","tafsir":"تجمعهم ( لِيَوْمٍ لا رَيْبَ فِيهِ ) هو يوم القيامة الذي لا شك فيه عند ذوي العقول وإن شك فيه أناس لا نصيب لهم من العلم والمعرفة وقد تقدم وجهه في أول سورة البقرة ( إِنَّ اللهَ لا يُخْلِفُ الْمِيعادَ ) أي الوعد الذي وعده أنبياءه والبشر بيوم القيامة ، فلا تزغ قلوبنا حتى نكون ذلك اليوم من المطرودين أو هذا إظهار من الراسخين بالاعتراف بالبعث وإنهم جمعوا بين فضيلتي الاعتراف بالمبدأ والمعاد."},{"text":"كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَذَّبُوا۟ بِـَٔايَـٰتِنَا فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ ۗ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ","tafsir":"من الذين في قلوبهم زيغ فيتبعون المتشابه وغيرهم ( 1) الأعراف : 176. لَنْ تُغْنِيَ عَنْهُمْ أَمْوالُهُمْ وَلا أَوْلادُهُمْ مِنَ اللهِ شَيْئاً وَأُولئِكَ هُمْ وَقُودُ النَّارِ (10) كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِنْ قَبْلِهِمْ كَذَّبُوا بِآياتِنا فَأَخَذَهُمُ اللهُ بِذُنُوبِهِمْ وَاللهُ شَدِيدُ الْعِقابِ (11) من سائر الكفار ( لَنْ تُغْنِيَ عَنْهُمْ أَمْوالُهُمْ ) كي يعطوها فينجون من عذاب الله سبحانه كما تنفع الفدية في الدنيا ( وَلا أَوْلادُهُمْ مِنَ اللهِ ) أي من عذاب الله وسخطه ( شَيْئاً ) فلا يتمكن أولادهم أن يقفوا ليمنعوا عنهم العذاب ( وَأُولئِكَ ) الكفار ( هُمْ وَقُودُ ) الوقود الحطب وكل ما يوقد به النار ( النَّارِ ) يوم القيامة تتقد النار بأجسامهم كما تتقد النار بالحطب والنفط ونحوها."},{"text":"قُل لِّلَّذِينَ كَفَرُوا۟ سَتُغْلَبُونَ وَتُحْشَرُونَ إِلَىٰ جَهَنَّمَ ۚ وَبِئْسَ ٱلْمِهَادُ","tafsir":"الدأب العادة ، أي عادة هؤلاء الكفار في التكذيب بك وبما أنزل إليك كعادة آل فرعون الذين كذبوا الرسل ( وَ ) كعادة ( الَّذِينَ مِنْ قَبْلِهِمْ ) من سائر الكفار الذين كانوا يكفرون بآيات الله ويكذبون أنبياءه ( كَذَّبُوا ) جميعا ( بِآياتِنا ) أي بدلائلنا الدالة على التوحيد وسائر الأصول ( فَأَخَذَهُمُ اللهُ بِذُنُوبِهِمْ ) أي بسبب عصيانهم ومعاصيهم ، ومعنى الأخذ العقاب أي عاقبهم ، كقوله ( وَكَذلِكَ أَخْذُ رَبِّكَ إِذا أَخَذَ الْقُرى وَهِيَ ظالِمَةٌ ) (1) ( وَاللهُ شَدِيدُ الْعِقابِ ) فليس عقابه كعقاب سائر الناس ، وإنما ( ناراً أَحاطَ بِهِمْ سُرادِقُها وَإِنْ يَسْتَغِيثُوا يُغاثُوا بِماءٍ كَالْمُهْلِ يَشْوِي الْوُجُوهَ ) (2) . ( 1) هود : 103. ( 2) الكهف : 30. قُلْ لِلَّذِينَ كَفَرُوا سَتُغْلَبُونَ وَتُحْشَرُونَ إِلى جَهَنَّمَ وَبِئْسَ الْمِهادُ (12) قَدْ كانَ لَكُمْ آيَةٌ فِي فِئَتَيْنِ الْتَقَتا فِئَةٌ تُقاتِلُ فِي سَبِيلِ اللهِ وَأُخْرى كافِرَةٌ يَرَوْنَهُم ْ مِثْلَيْهِمْ رَأْيَ الْعَيْنِ"},{"text":"قَدْ كَانَ لَكُمْ ءَايَةٌ فِى فِئَتَيْنِ ٱلْتَقَتَا ۖ فِئَةٌ تُقَـٰتِلُ فِى سَبِيلِ ٱللَّهِ وَأُخْرَىٰ كَافِرَةٌ يَرَوْنَهُم مِّثْلَيْهِمْ رَأْىَ ٱلْعَيْنِ ۚ وَٱللَّهُ يُؤَيِّدُ بِنَصْرِهِۦ مَن يَشَآءُ ۗ إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّأُو۟لِى ٱلْأَبْصَـٰرِ","tafsir":"يا رسول الله ( لِلَّذِينَ كَفَرُوا سَتُغْلَبُونَ ) أي بعد قليل يكونون مهزومين إما في الدنيا بغلبة الإسلام ، كما صار وكما أخبر حيث إن الإسلام غلبهم وأخذ بلادهم ( وَتُحْشَرُونَ إِلى جَهَنَّمَ ) يوم القيامة ، وإما في الآخرة بمعنى أنكم بعد قليل تهزمون أمام أمر الله سبحانه ، ويقبضكم ملك الموت الذي وكل بكم ، وبعد ذلك تحشرون إلى جهنم يوم القيامة ( وَبِئْسَ الْمِهادُ ) أي بئسما مهد لكم أو ما مهدتم لأنفسكم. [14] ولما بين سبحانه أن الكفار سيغلبون بين لذلك شاهدا محسوسا في قصة بدر حيث كان المسلمون ثلاثمائة وثلاثة عشر رجلا والكفار ألف رجل ولم يكن للمسلمين من العتاد إلا شيئا ضئيلا بينما كان الكفار بأكمل السلاح ومع ذلك فقد غلب المسلمون عليهم بنصر الله سبحانه ( قَدْ كانَ لَكُمْ ) أيها المسلمون أو أيها الكفار ( آيَةٌ ) أي علامة على صدق الرسول صلى‌الله‌عليه‌وآله‌وسلم وإن الله ينصره ويهزم الكفار ( فِي فِئَتَيْنِ ) أي جماعتين جماعة المسلمين وجماعة الكفار ( الْتَقَتا ) من الملاقاة إذ اجتمعتا في بدر ( فِئَةٌ تُقاتِلُ فِي سَبِيلِ اللهِ ) وهم المسلمون ( وَ ) فئة ( أُخْرى كافِرَةٌ ) وهم المشركون الذين أتوا من مكة ( يَرَوْنَهُمْ ) أي يرى المسلمون الكفار ( مِثْلَيْهِمْ ) أي ضعف أنفسهم ( رَأْيَ الْعَيْنِ ) وَاللهُ يُؤَيِّدُ بِنَصْرِهِ مَنْ يَشاءُ إِنَّ فِي ذلِكَ لَعِبْرَةً لِأُولِي الْأَبْصارِ (13) زُيِّنَ لِلنَّاسِ حُبُّ الشَّهَواتِ فلم يكن ذلك خيالا وإنما واقعا فإن الكفار في الواقع كانوا أكثر ، ومع ذلك فقد غلب المسلمون ، ولعل النكتة في ذكر ذلك بيان أن المسلمين غلبوا مع أنهم كانوا يعلمون بزيادة الكفار عليهم وإن ذلك يدل أن الله نصرهم وإلا فإن الجيش إذا علم أن العدو أكثر منه وهن في عضده ويسبب ذلك انهزامه في أكثر الأحيان ، وفي الآية أقوال أخر مذكورة في التفسيرات ( وَاللهُ يُؤَيِّدُ بِنَصْرِهِ مَنْ يَشاءُ ) أي يقوي بنصره فلا يضرهم قلة عددهم وعدتهم ( إِنَّ فِي ذلِكَ ) المذكور وهو غلبة المسلمين على المشركين مع أن الكفار كانوا ثلاثة أضعافهم ( لَعِبْرَةً ) أي اعتبار وهي بمعنى الآية وإنما سميت الآية عبرة لأنها تعبر بالإنسان من الجهل والغفلة إلى العلم والتذكير ( لِأُولِي الْأَبْصارِ ) أي أصحاب العقول ، وليس المراد بالبصر النظر بالعين وإنما النظر بالقلب كما يقال فلان بصير بالأمور أي يعرفها ويدركها. [15] وهنا يتساءل الإنسان ماذا صرف الكفار عن الحق وهم يرونه ؟ ويأتي الجواب إن الذي صرفهم هو جمال الدنيا ومالها كما قال الإمام أمير المؤمنين عليه‌السلام « لكنهم حليت الدنيا في أعينهم وراقهم زبرجها » (1) ( زُيِّنَ لِلنَّاسِ حُبُّ الشَّهَواتِ ) أي أن حب الإنسان للمشتهيات والملذات سبب لهم أن تتزين الدنيا في نفوسهم فيطلبون اللذائذ ولو ( 1) نهج البلاغة : خطبة 3 ـ 15. مِنَ النِّساءِ وَالْبَنِينَ وَالْقَناطِيرِ الْمُقَنْطَرَةِ مِنَ الذَّهَبِ وَالْفِضَّةِ وَالْخَيْلِ الْمُسَوَّمَةِ وَالْأَنْعامِ وَالْحَرْثِ ذلِكَ مَتاعُ الْحَياةِ الدُّنْيا وَاللهُ عِنْدَهُ حُسْنُ الْمَآبِ (14) في المحرمات ولم يذكر الفاعل ، لأنه ليس بمقصود وقد تقرر في علم البلاغة أن مقتضاه أن لا يذكر الفاعل أو المفعول حيث لم يكن مقصودا ( مِنَ النِّساءِ ) بيان « الشهوات » ( وَالْبَنِينَ ) فإن حب الأولاد يسبب إطاعتهم والتحفظ عليهم ولو بذهاب الدين ( وَالْقَناطِيرِ الْمُقَنْطَرَةِ ) القناطير جمع « قنطار » وهو ملء مسك ثور ذهبا وإنما سمي قنطارا لأنه يكفي للحياة فكأنه قنطرة يعبر بها مدة الحياة ، والمقنطرة بمعنى المجتمعة المكدسة كقولهم دراهم مدرهمة ودنانير مدنرة ( مِنَ الذَّهَبِ وَالْفِضَّةِ ) فإن الإنسان بحبه للأموال يعصي الله في جمعه وفي عدم إعطاء حقوقه ( وَالْخَيْلِ ) عطف على النساء ، والخيل الأفراس ( الْمُسَوَّمَةِ ) من سوم الخيل التي علمها ولا تعلم إلا الجيد الحسن منها ( وَالْأَنْعامِ ) جمع نعم وهي الإبل والبقر والغنم ( وَالْحَرْثِ ) أي الزرع فهذه كلها محببة للناس ، لكن ( ذلِكَ ) كله ( مَتاعُ الْحَياةِ الدُّنْيا ) أي ما يستمتع به في الدنيا ولا تنفع الآخرة إلا إذا بذلت في سبيل الله ـ كل حسب بذله ـ ( وَاللهُ عِنْدَهُ حُسْنُ الْمَآبِ ) المرجع أي أن المرجع الحسن في الآخرة منوط بالله سبحانه فاللازم أن يتزهد الإنسان في الملذات ولا يتناول المحرم منها رجاء ثواب الله ونعيمه المقيم الذي لا زوال له ولا اضمحلال ، فلا تسبب هذه المشتهيات عدول الإنسان عن الحق إلى الباطل وعن الرشاد إلى الضلال. قُلْ أَ أُنَبِّئُكُمْ بِخَيْرٍ مِنْ ذلِكُمْ لِلَّذِينَ اتَّقَوْا عِنْدَ رَبِّهِمْ جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ خالِدِينَ فِيها وَأَزْواجٌ مُطَهَّرَةٌ وَرِضْوانٌ مِنَ اللهِ وَاللهُ بَصِيرٌ بِالْعِبادِ (15) الَّذِينَ يَقُولُونَ رَبَّنا إِنَّنا آمَنَّا فَاغْفِرْ لَنا ذُنُوبَنا"},{"text":"زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلْبَنِينَ وَٱلْقَنَـٰطِيرِ ٱلْمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلْفِضَّةِ وَٱلْخَيْلِ ٱلْمُسَوَّمَةِ وَٱلْأَنْعَـٰمِ وَٱلْحَرْثِ ۗ ذَٰلِكَ مَتَـٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلْمَـَٔابِ","tafsir":""},{"text":"۞ قُلْ أَؤُنَبِّئُكُم بِخَيْرٍ مِّن ذَٰلِكُمْ ۚ لِلَّذِينَ ٱتَّقَوْا۟ عِندَ رَبِّهِمْ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا وَأَزْوَٰجٌ مُّطَهَّرَةٌ وَرِضْوَٰنٌ مِّنَ ٱللَّهِ ۗ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ","tafsir":""},{"text":"ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ","tafsir":"يا رسول الله للناس الذين زين لهم حب الشهوات ( أَ أُنَبِّئُكُمْ ) أي هل تريدون أن أخبركم ( بِخَيْرٍ مِنْ ذلِكُمْ ) أي بأحسن من هذه الشهوات ، و « كم » خطاب للناس ( لِلَّذِينَ اتَّقَوْا ) المحرمات وعملوا حسب أوامر الله سبحانه ( عِنْدَ رَبِّهِمْ ) في الآخرة ( جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ ) أي من تحت أشجارها ونخيلها وقصورها ( خالِدِينَ فِيها ) فإنهم يسكنون الجنة أبد الآبدين لا زوال لهم ولا تحويل ( وَأَزْواجٌ مُطَهَّرَةٌ ) أي نساء طاهرة من الأقذار الظاهرية كالحيض والوساخة ، والأقذار الباطنية كسوء الخلق والحقد والعداوة ( وَ ) أكبر من كل ذلك ( رِضْوانٌ مِنَ اللهِ ) فإن الله راض عنهم ومتى شعر الإنسان برضى الله سبحانه منه تنعم بأفضل نعمة نفسية كما لو علم فرد من الرعية أن الملك يحبه ويرضى عنه ( وَاللهُ بَصِيرٌ بِالْعِبادِ ) خبير بأفعالهم وأعمالهم فيجازيهم حسب ما يفعلون. [17] ثم وصف سبحانه المتقين الذين سبق ذكرهم بقوله « للذين اتقوا » فالمتقون هم ( الَّذِينَ يَقُولُونَ رَبَّنا إِنَّنا آمَنَّا ) أي صدقنا بك وبرسلك وبما أمرت ووعدت ( فَاغْفِرْ لَنا ذُنُوبَنا ) أي تجاوز عما صدر منا من وَقِنا عَذابَ النَّارِ (16) الصَّابِرِينَ وَالصَّادِقِينَ وَالْقانِتِينَ وَالْمُنْفِقِينَ وَالْمُسْتَغْفِرِينَ بِالْأَسْحارِ (17) شَهِدَ اللهُ أَنَّهُ لا إِلهَ إِلاَّ هُوَ وَالْمَلائِكَةُ وَأُولُوا الْعِلْمِ الخطايا ( وَقِنا ) أي احفظنا من « وقى » « يقي » بمعنى حفظ ( عَذابَ النَّارِ ) حتى لا نكون من أهلها."},{"text":"ٱلصَّـٰبِرِينَ وَٱلصَّـٰدِقِينَ وَٱلْقَـٰنِتِينَ وَٱلْمُنفِقِينَ وَٱلْمُسْتَغْفِرِينَ بِٱلْأَسْحَارِ","tafsir":""},{"text":"شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَـٰهَ إِلَّا هُوَ وَٱلْمَلَـٰٓئِكَةُ وَأُو۟لُوا۟ ٱلْعِلْمِ قَآئِمًۢا بِٱلْقِسْطِ ۚ لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ","tafsir":"صفة أخرى للمتقين فأولئك هم الصابرون في المصائب وعند الطاعة ، ولدى المعصية ( وَالصَّادِقِينَ ) في نياتهم وأقوالهم وأفعالهم ( وَالْقانِتِينَ ) من القنوت بمعنى الإطاعة والخضوع ( وَالْمُنْفِقِينَ ) لأموالهم في سبيل الله سبحانه ( وَالْمُسْتَغْفِرِينَ ) الذين يطلبون غفران ذنوبهم ( بِالْأَسْحارِ ) جمع سحر وهو ما يقرب من طلوع الفجر آخر الليل. [19] ويناسب السياق هنا الإشارة إلى صفات الباري عز اسمه حيث تقدم ذكر من اتقى وأوصاف المتقين الذين يعملون لله سبحانه ( شَهِدَ اللهُ أَنَّهُ لا إِلهَ إِلَّا هُوَ ) وشهادة الله لفظية وواقعية فإن الشهادة إظهار المطلب باللسان وقد أظهر الله سبحانه وحدته وسائر صفاته بما هو أقوى وأثبت وأولى من اللفظ ، وهو خلق المصنوعات التي تشهد جميعها بصفاته كما قال الشاعر « وفي كل شيء له آية .. * .. تدل على أنه واحد » وإنما تشهد المصنوعات على الوحدة لأنه لو كان فيهما آلهة غير الله لفسدتا فعدم الفساد دليل الوحدة ـ كما تقرر في علم الكلام ـ ( وَالْمَلائِكَةُ ) شهدوا بالوحدانية شهادة لفظية وحقيقية ( وَأُولُوا الْعِلْمِ ) أصحاب العلم الذين يدركون ، لا كل من يدعي العلم ، فإنه من ينظر إلى الكون قائِماً بِالْقِسْطِ لا إِلهَ إِلاَّ هُوَ الْعَزِيزُ الْحَكِيمُ (18) نظر عالم معتبر لا بد له من الإذعان بالوحدانية ( قائِماً بِالْقِسْطِ ) أي في حال كونه سبحانه قائما بالعدل ، فإن القسط بمعنى العدل ، ومعنى قيامه سبحانه بالعدل أنه يفعل ما يفعل بالعدل فخلقه ، وتقديره ، وتشريعه ، كل بالعدل ومعنى العدل الاستواء ، مقابل الظلم الذي هو الاعوجاج والانحراف ، فمثلا جعل الشمس في السماء عدل لأنها تنير وتشرق وتقيم المجموعة الشمسية بينما عدمها انحراف وظلم ، وكذلك تقدير هذا غنيا وذاك فقيرا ، وهذا رئيسا وذاك مرءوسا بالعدل ، وما يشاهد في ذلك من الانحراف فإنه ليس من التقدير وإنما من سوء اختيار الناس ، وكذلك تشريع الصلاة واجبة ، والخمر محرمة بالعدل. يقال أن رجلا سأل كسرى عن سبب عدله قال : لعدة أسباب منها أني رأيت في الصحراء يوما كلبا كسر رجل غزال ، فما لبث أن رماه إنسان بحجر فكسر رجله فلم يمض على الرجل إلا برهة إذا بفرس رفسه فكسر رجله ، فلم تمض على ذلك لحظات إلا بالفرس عثر فانكسرت رجله ، وهناك علمت أن الظلم عاقبته وخيمة .... والإنسان إذا لم يعرف الصلاح والعدل في بعض الأشياء فليس له أن يعترض ، والحال أنه يجهل أكثر الأشياء ، فهو كمن يعترض على أدوية وصفها الطبيب وهو لا يعرف من الطب شيئا ، ولفظة « قائما » فيها إيماءة لطيفة ، فإن القائم يشاهد ما لا يشاهده القاعد ، إذ هو مسيطر مشرف ( لا إِلهَ إِلَّا هُوَ ) تكرار للتأكيد ، فإن العالم قبل الإسلام كان مرتطما في أو حال الشرك حتى جاء الإسلام فأظهر التوحيد وجدد ما محي من سنن الأنبياء عليهم‌السلام وإرشادهم حول المبدأ تعالى ( الْعَزِيزُ ) في سلطانه ( الْحَكِيمُ ) الذي يفعل كل شيء عن حكمة وعلم. إِنَّ الدِّينَ عِنْدَ اللهِ الْإِسْلامُ وَمَا اخْتَلَفَ الَّذِينَ أُوتُوا الْكِتابَ إِلاَّ مِنْ بَعْدِ ما جاءَهُمُ الْعِلْمُ بَغْياً بَيْنَهُمْ وَمَنْ يَكْفُرْ بِآياتِ اللهِ فَإِنَّ اللهَ سَرِيعُ الْحِسابِ (19) [20] وبعد ما تقرر التوحيد والعدل أتى دور الدين الذي أرسله الله سبحانه إلى العباد ( إِنَّ الدِّينَ عِنْدَ اللهِ الْإِسْلامُ ) والدين هي الطريقة التي تؤمن السعادة للبشر دنيا وآخرة ، إنه عند الله الإسلام ، وإن كان عند غيره اليهودية والنصرانية والمجوسية وغيرها ، فإن الله سبحانه لم يرسل إلا الإسلام والإسلام هو دين الأنبياء جميعا فإنه عبارة عن تسليم منهج الأعمال إلى الله الذي خلق الكون وهو أعلم بالنظام السماوي له الذي إن تبعه البشر عاش سعيدا ومات حميدا ، وقد ذكرنا سابقا أن الاختلاف بين الأديان السماوية الواقعية في شرائط ومزايا لا في الجواهر والأصول ( وَمَا اخْتَلَفَ الَّذِينَ أُوتُوا الْكِتابَ ) أي ليس اختلاف أهل الكتاب بعضهم مع بعض وجميعهم مع المسلمين ( إِلَّا مِنْ بَعْدِ ما جاءَهُمُ الْعِلْمُ ) فعرفوا الصحيح من السقيم والحق من الباطل ، وإنما اختلفوا ( بَغْياً ) أي حسدا ( بَيْنَهُمْ ) فلم يقبل اليهود أن يرضخوا لعيسى عليه‌السلام حسدا ، ولم يقبل النصارى أن يؤمنوا بنبي الإسلام صلى‌الله‌عليه‌وآله‌وسلم حسدا ، كما قال سبحانه ( أَمْ يَحْسُدُونَ النَّاسَ عَلى ما آتاهُمُ اللهُ مِنْ فَضْلِهِ ) (1) ( وَمَنْ يَكْفُرْ بِآياتِ اللهِ ) فلم يؤمن بها فلا يظن أنه ربح وتهنأ بدنيا باقية بل خسر وذهبت دنياه وآخرته ( فَإِنَّ اللهَ سَرِيعُ الْحِسابِ ) يحاسب الكفار ( 1) النساء : 55. فَإِنْ حَاجُّوكَ فَقُلْ أَسْلَمْتُ وَجْهِيَ لِلَّهِ وَمَنِ اتَّبَعَنِ وَقُلْ لِلَّذِينَ أُوتُوا الْكِتابَ وَالْأُمِّيِّينَ أَأَسْلَمْتُمْ فَإِنْ أَسْلَمُوا فَقَدِ اهْتَدَوْا في الدنيا بأنواع من البلايا والمصائب كما قال ( وَمَنْ أَعْرَضَ عَنْ ذِكْرِي فَإِنَّ لَهُ مَعِيشَةً ضَنْكاً ) (1) وفي الآخرة بما اقترفوا من الكفر والآثام ، والآخرة قريبة جدا فإن « من فاته اليوم سهم لم يفته غدا » قال الشاعر : ألا إنما الدنيا كمنزل راكب أناخ عشيا وهو في الصبح راحل"},{"text":"إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلْإِسْلَـٰمُ ۗ وَمَا ٱخْتَلَفَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۗ وَمَن يَكْفُرْ بِـَٔايَـٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ","tafsir":""},{"text":"فَإِنْ حَآجُّوكَ فَقُلْ أَسْلَمْتُ وَجْهِىَ لِلَّهِ وَمَنِ ٱتَّبَعَنِ ۗ وَقُل لِّلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ وَٱلْأُمِّيِّـۧنَ ءَأَسْلَمْتُمْ ۚ فَإِنْ أَسْلَمُوا۟ فَقَدِ ٱهْتَدَوا۟ ۖ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْكَ ٱلْبَلَـٰغُ ۗ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ","tafsir":""},{"text":"إِنَّ ٱلَّذِينَ يَكْفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيْرِ حَقٍّ وَيَقْتُلُونَ ٱلَّذِينَ يَأْمُرُونَ بِٱلْقِسْطِ مِنَ ٱلنَّاسِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ","tafsir":"يا رسول الله وجادلوك في أمر التوحيد بعد وضوح الحجة ( فَقُلْ ) لهم ( أَسْلَمْتُ وَجْهِيَ لِلَّهِ ) فأنا لا أعبد إلا الله سبحانه لا أتخذ له شريكا ، وإسلام الوجه كناية عن الإسلام المطلق إذ تسليم الوجه إلى نحو يدل على تسليم القلب وسائر الجوارح ( وَمَنِ اتَّبَعَنِ ) أي الذين اتبعوني هم أيضا أسلموا وجوههم لله فقط دون غيره ( وَقُلْ ) يا رسول الله ( لِلَّذِينَ أُوتُوا الْكِتابَ ) أي أعطوا الكتاب السماوي من اليهود والنصارى والمجوس ( وَ ) قل لل ( الْأُمِّيِّينَ ) من المشركين الذين لا كتاب لهم وسموا أميين إما لجهلهم نسبة إلى الأم وإما لأنهم من أهل مكة ـ أم القرى ـ ( أَ أَسْلَمْتُمْ ) أي هل أسلمتم وجوهكم لله وحده ـ بلا جدال ولا نقاش معهم بعد ما تمت عليهم الحجة ـ ( فَإِنْ أَسْلَمُوا ) وتشرفوا بدين الإسلام ( فَقَدِ اهْتَدَوْا ) إلى ( 1) طه : 125. وَإِنْ تَوَلَّوْا فَإِنَّما عَلَيْكَ الْبَلاغُ وَاللهُ بَصِيرٌ بِالْعِبادِ (20) إِنَّ الَّذِينَ يَكْفُرُونَ بِآياتِ اللهِ وَيَقْتُلُونَ النَّبِيِّينَ بِغَيْرِ حَقٍّ وَيَقْتُلُونَ الَّذِينَ يَأْمُرُونَ بِالْقِسْطِ مِنَ النَّاسِ فَبَشِّرْهُمْ بِعَذابٍ أَلِيمٍ (21) الحق وإلى طريق مستقيم ( وَإِنْ تَوَلَّوْا فَإِنَّما عَلَيْكَ الْبَلاغُ ) أن تبلغهم الإسلام وليس عليك إجبارهم حتى لا يتولوا وحتى لا يعرضوا ( وَاللهُ بَصِيرٌ بِالْعِبادِ ) لا يفوته شيء من أعمالهم فهو يجازيهم بكفرهم وميثاقهم كما يجزيهم على إيمانهم وإطاعتهم. [22] ثم بين سبحانه أن أهل الكتاب كفروا بالله قديما وقتلوا الأنبياء عليهم‌السلام ، تسلية للنبي صلى‌الله‌عليه‌وآله‌وسلم أن لا يضيق صدره بتكذيبهم ولجاجتهم ( إِنَّ الَّذِينَ يَكْفُرُونَ بِآياتِ اللهِ ) فلا يقبلونها بعد وضوحها وعلمهم بها ( وَيَقْتُلُونَ النَّبِيِّينَ بِغَيْرِ حَقٍ ) فإن قتل النبي مطلقا ليس بحق وإنما يأتي القيد إفادة لأنه لا حجة لهم في قتل الأنبياء عليهم‌السلام حتى أنه ليس هناك حق مدعى أيضا ( وَيَقْتُلُونَ الَّذِينَ يَأْمُرُونَ بِالْقِسْطِ ) أي بالعدل ( مِنَ النَّاسِ ) فإن أهل الظلم والباطل الذين تتمثل فيهم القوة غالبا يقتلون من ينهاهم عن ذلك ويأمر بالقسط والعدل ( فَبَشِّرْهُمْ بِعَذابٍ أَلِيمٍ ) وكلمة البشارة استهزاء أو بعلاقة استعمال الضد في الضد كتسمية الزنجي بالكافور والأعمى بالبصير ، أو للمقابلة نحو ( فَمَنِ اعْتَدى عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ بِمِثْلِ مَا اعْتَدى عَلَيْكُمْ وَاتَّقُوا اللهَ وَاعْلَمُوا أَنَّ اللهَ مَعَ الْمُتَّقِينَ ) (1) ، فإن ( 1) البقرة : 195. أُولئِكَ الَّذِينَ حَبِطَتْ أَعْمالُهُمْ فِي الدُّنْيا وَالْآخِرَةِ وَما لَهُمْ مِنْ ناصِرِينَ (22) أَ لَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيباً مِنَ الْكِتابِ يُدْعَوْنَ إِلى كِتابِ اللهِ لِيَحْكُمَ بَيْنَهُمْ المؤمن يبشر بالثواب والكافر يبشر بالعقاب."},{"text":"أُو۟لَـٰٓئِكَ ٱلَّذِينَ حَبِطَتْ أَعْمَـٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمَا لَهُم مِّن نَّـٰصِرِينَ","tafsir":""},{"text":"أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًا مِّنَ ٱلْكِتَـٰبِ يُدْعَوْنَ إِلَىٰ كِتَـٰبِ ٱللَّهِ لِيَحْكُمَ بَيْنَهُمْ ثُمَّ يَتَوَلَّىٰ فَرِيقٌ مِّنْهُمْ وَهُم مُّعْرِضُونَ","tafsir":"الخيرية فإن لكل إنسان أعمال خيرية وإن كان كافرا ، ومعنى حبط العمل بطلانه وعدم إفادته ( فِي الدُّنْيا ) فإن كفرهم سبب هدر دمهم فعملهم الخير لم ينفعهم في حقن دمهم أو أعمال الخير التي تدفع البلايا والآفات لا تنفع مع الكفر والانحراف ( وَالْآخِرَةِ ) فلا تفيدهم أعمالهم الحسنة ثوابا كما قال سبحانه ( وَقَدِمْنا إِلى ما عَمِلُوا مِنْ عَمَلٍ فَجَعَلْناهُ هَباءً مَنْثُوراً ) (1) ( وَما لَهُمْ ) أي ليس لهم ( مِنْ ناصِرِينَ ) ينصرونهم من عذاب الله وسخطه."},{"text":"ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَٰتٍ ۖ وَغَرَّهُمْ فِى دِينِهِم مَّا كَانُوا۟ يَفْتَرُونَ","tafsir":"يا رسول الله ، ومعناه إفادة العلم بهذا الاستفهام ( إِلَى الَّذِينَ أُوتُوا ) أعطوا ( نَصِيباً مِنَ الْكِتابِ ) أي بعضا منه لأنهم بتحريفهم الكتاب قد فقدوا بعضه كما قال سبحانه ( وَنَسُوا حَظًّا مِمَّا ذُكِّرُوا بِهِ ) (2) ( يُدْعَوْنَ إِلى كِتابِ اللهِ لِيَحْكُمَ بَيْنَهُمْ ) يدعوهم الرسول صلى‌الله‌عليه‌وآله‌وسلم إلى كتاب الله ليجعل حكما بينهم وأن محمدا صلى‌الله‌عليه‌وآله‌وسلم حق أم لا فقد كان في التوراة والإنجيل صفاته صلى‌الله‌عليه‌وآله‌وسلم ، ولذا كان يدعوهم إلى تحكيم كتابهم في هذا الأمر لكنهم لم يقبلوا ( 1) الفرقان : 24. ( 2) المائدة : 14. ثُمَّ يَتَوَلَّى فَرِيقٌ مِنْهُمْ وَهُمْ مُعْرِضُونَ (23) ذلِكَ بِأَنَّهُمْ قالُوا لَنْ تَمَسَّنَا النَّارُ إِلاَّ أَيَّاماً مَعْدُوداتٍ وَغَرَّهُمْ فِي دِينِهِمْ ما كانُوا يَفْتَرُونَ (24) فَكَيْفَ إِذا جَمَعْناهُمْ لِيَوْمٍ لا رَيْبَ فِيهِ وَوُفِّيَتْ كُلُّ نَفْسٍ ( ثُمَّ يَتَوَلَّى فَرِيقٌ مِنْهُمْ ) أي يعرض عن تحكيم الكتاب وإنما قال فريق لأن بعضهم دخل في الإسلام بعد ما تمت له الدلالة والإرشاد كعبد الله بن سلام وغيره ( وَهُمْ مُعْرِضُونَ ) عن الحق وعن كتابهم وفي بعض الأحاديث أن الآية نزلت في مسألة زنا وقعت بين يهودي ويهودية وكان حكمهما الرجم في التوراة ورجعوا إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم لعله يحكم بغير ذلك فحكم الرسول بينهم بما في التوراة فكرهوا ذلك."},{"text":"فَكَيْفَ إِذَا جَمَعْنَـٰهُمْ لِيَوْمٍ لَّا رَيْبَ فِيهِ وَوُفِّيَتْ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ","tafsir":"الإعراض عن كتابهم وعن أوامر الله سبحانه بسبب أنهم أمنوا العقوبة بما لفقوه من الكذب حيث ( قالُوا لَنْ تَمَسَّنَا النَّارُ ) أي نار جهنم على فرض كفرنا وعصياننا ( إِلَّا أَيَّاماً مَعْدُوداتٍ ) سبعة أيام أو أربعين يوما وهذه المدة القليلة فلا ينبغي ترك الشهوات والرئاسة لأجلها ( وَغَرَّهُمْ ) أي خدعهم ( فِي ) باب ( دِينِهِمْ ما كانُوا يَفْتَرُونَ ) أي الذي افتروا ونسبوه إلى الدين من أن النار أيام معدودة فقط خدعهم وغرهم."},{"text":"قُلِ ٱللَّهُمَّ مَـٰلِكَ ٱلْمُلْكِ تُؤْتِى ٱلْمُلْكَ مَن تَشَآءُ وَتَنزِعُ ٱلْمُلْكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُ ۖ بِيَدِكَ ٱلْخَيْرُ ۖ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ","tafsir":"حالهم إذا انكشف غرورهم ( إِذا جَمَعْناهُمْ لِيَوْمٍ ) القيامة الذي ( لا رَيْبَ فِيهِ ) أي ليس محل ارتياب وشك ( وَوُفِّيَتْ كُلُّ نَفْسٍ ما كَسَبَتْ وَهُمْ لا يُظْلَمُونَ (25) قُلِ اللهُمَّ مالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَنْ تَشاءُ وَتَنْزِعُ الْمُلْكَ مِمَّنْ تَشاءُ وَتُعِزُّ مَنْ تَشاءُ وَتُذِلُّ مَنْ تَشاءُ بِيَدِكَ الْخَيْرُ إِنَّكَ عَلى كُلِّ شَيْءٍ قَدِيرٌ (26) تُولِجُ اللَّيْلَ فِي النَّهارِ ما كَسَبَتْ ) أي يعطى كل إنسان جزاءه وافيا غير منقوص ( وَهُمْ لا يُظْلَمُونَ ) بل يجزون على حسب أعمالهم. [27] وهنا يتوجه السياق إلى كون الملك لله فليس لأهل الكتاب أن يحسدوا الرسول والمسلمين فيما أوتوا من حول وطول وعزة وملك ، وفي بعض الأحاديث أن الآية نزلت بعد ما بشر الرسول المسلمين بأنهم يفتحون ملك فارس والروم ، فاستهزأ الكفار بذلك وقالوا أنى يكون لمثل هؤلاء أن يسيطروا على تلك الدولتين العظيمتين ( قُلِ ) يا رسول الله ( اللهُمَ ) أي يا الله ، والميم بدل عن حرف النداء ( مالِكَ الْمُلْكِ ) مالك منصوب على أنه مناد مضاف أي يا مالك الملك فكل شيء لك وحدك لا شريك وملك من عداك إنما هو مجازي اعتباري ( تُؤْتِي ) أي تعطي ( الْمُلْكَ مَنْ تَشاءُ ) أن تعطيه ( وَتَنْزِعُ الْمُلْكَ مِمَّنْ تَشاءُ ) أن تنزعه من غير فرق بين أن يكون الملك سلطانا أو ملكا لشيء كالدار والعقار ( وَتُعِزُّ مَنْ تَشاءُ ) أن تعزه عزة ظاهرية أو باطنية بالإيمان والطاعة ( وَتُذِلُّ مَنْ تَشاءُ ) أن تذله ( بِيَدِكَ الْخَيْرُ إِنَّكَ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) فتقدر على الإعطاء والمنع وأن تعز وتذل."},{"text":"تُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ ۖ وَتُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَتُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ ۖ وَتَرْزُقُ مَن تَشَآءُ بِغَيْرِ حِسَابٍ","tafsir":""},{"text":"لَّا يَتَّخِذِ ٱلْمُؤْمِنُونَ ٱلْكَـٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ ۖ وَمَن يَفْعَلْ ذَٰلِكَ فَلَيْسَ مِنَ ٱللَّهِ فِى شَىْءٍ إِلَّآ أَن تَتَّقُوا۟ مِنْهُمْ تُقَىٰةً ۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ ۗ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ","tafsir":"أي تدخل ( اللَّيْلَ فِي النَّهارِ ) فيأخذ الليل مكان النهار ، فيما وَتُولِجُ النَّهارَ فِي اللَّيْلِ وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ وَتَرْزُقُ مَنْ تَشاءُ بِغَيْرِ حِسابٍ (27) لا يَتَّخِذِ الْمُؤْمِنُونَ الْكافِرِينَ أَوْلِياءَ مِنْ دُونِ الْمُؤْمِنِينَ وَمَنْ يَفْعَلْ ذلِكَ فَلَيْسَ مِنَ اللهِ فِي شَيْءٍ إِلاَّ أَنْ تَتَّقُوا مِنْهُمْ تُقاةً ينقص اليوم ويزيد الليل ، أو فيما إذا جاء الليل وذهب النهار ، وهو كناية ، إذ ليس الإدخال حقيقة ( وَتُولِجُ النَّهارَ فِي اللَّيْلِ ) بأحد المعنيين السابقين ( وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ ) كما يخرج النبات الحي من الحب الميت والأرض الميتة ، أو يخرج الجنين الحي من الأم الميتة كما قد تموت الأم ويخرج الولد منها حيا ( وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِ ) كما يخرج الحب الميت من النبات الحي والبيضة الميتة من الدجاجة والولد الميت من المرأة الحية إذا مات الجنين في بطنها ، وفي التأويل إخراج المؤمن من الكافر ، والكافر من المؤمن ( وَتَرْزُقُ مَنْ تَشاءُ ) من عبادك وخلقك ( بِغَيْرِ حِسابٍ ) أي بغير تقتير كما يقال فلان ينفق بغير حساب ، أو بلا حساب من المنفق عليه وإن كان كل شيء عنده تعالى بحساب. [29] وحيث ثبت أن الملك بيد الله والعزة والذلة منه ف ( لا يَتَّخِذِ الْمُؤْمِنُونَ الْكافِرِينَ أَوْلِياءَ ) بأن يصادق المؤمن الكافر بزعم أنه ينفعه لأن بيد الكافر الملك أو أنه يسبب عزته وشوكته ( مِنْ دُونِ الْمُؤْمِنِينَ ) أي من دون أن يتخذ المؤمنين أولياء بل اللازم أن يتخذ المؤمن المؤمن وليا ، ويتخذ من الكافر عدوا ( وَمَنْ يَفْعَلْ ذلِكَ ) الاتخاذ للكافر وليا ( فَلَيْسَ مِنَ اللهِ فِي شَيْءٍ ) أي ليس ذا قدر عند الله سبحانه ( إِلَّا أَنْ تَتَّقُوا مِنْهُمْ تُقاةً ) أي وَيُحَذِّرُكُمُ اللهُ نَفْسَهُ وَإِلَى اللهِ الْمَصِيرُ (28) قُلْ إِنْ تُخْفُوا ما فِي صُدُورِكُمْ أَوْ تُبْدُوهُ يَعْلَمْهُ اللهُ وَيَعْلَمُ ما فِي السَّماواتِ وَما فِي الْأَرْضِ وَاللهُ عَلى كُلِّ شَيْءٍ قَدِيرٌ (29) يَوْمَ تَجِدُ كُلُّ نَفْسٍ ما عَمِلَتْ مِنْ خَيْرٍ مُحْضَراً تخافوا من الكفار فلا بأس باتخاذهم أولياء تقية ( وَيُحَذِّرُكُمُ اللهُ نَفْسَهُ ) أي يخوفكم الله من نفسه فإن من يتخذ الكافر وليا يشمله عقاب الله سبحانه ( وَإِلَى اللهِ الْمَصِيرُ ) أي المرجع فمن عصاه يجازيه بالنار والعذاب."},{"text":"قُلْ إِن تُخْفُوا۟ مَا فِى صُدُورِكُمْ أَوْ تُبْدُوهُ يَعْلَمْهُ ٱللَّهُ ۗ وَيَعْلَمُ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ","tafsir":""},{"text":"يَوْمَ تَجِدُ كُلُّ نَفْسٍ مَّا عَمِلَتْ مِنْ خَيْرٍ مُّحْضَرًا وَمَا عَمِلَتْ مِن سُوٓءٍ تَوَدُّ لَوْ أَنَّ بَيْنَهَا وَبَيْنَهُۥٓ أَمَدًۢا بَعِيدًا ۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ ۗ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ","tafsir":"يا رسول الله للمسلمين ( إِنْ تُخْفُوا ما فِي صُدُورِكُمْ ) أي نواياكم وما في قلوبكم ، كما لو اتخذتم الكافر وليا في قلبكم مما لم يعلم به الناس ( أَوْ تُبْدُوهُ ) أي تظهروه ( يَعْلَمْهُ اللهُ ) فإنه العالم بالنوايا وما في الصدور ( وَيَعْلَمُ ما فِي السَّماواتِ وَما فِي الْأَرْضِ ) فهو العالم بكل شيء فكيف لا يعلم ما في صدوركم ( وَاللهُ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) فهو العالم بالنوايا والقادر على العقاب فمن الجدير بالمسلم أن لا يتخذ الكافر وليا أو المؤمن عدوا حتى في قلبه إذ يعلمه الله ويقدر على عقابه. [31] اذكروا أيها الناس ( يَوْمَ تَجِدُ كُلُّ نَفْسٍ ما عَمِلَتْ مِنْ خَيْرٍ مُحْضَراً ) أي تجد كل أعماله الخيرية حاضرة كما قال سبحانه ( وَوَجَدُوا ما عَمِلُوا حاضِراً ) (1) ومعنى حضور العمل حضور حساباتها وثوابها وعقابها أو ( 1) الكهف : 50. وَما عَمِلَتْ مِنْ سُوءٍ تَوَدُّ لَوْ أَنَّ بَيْنَها وَبَيْنَهُ أَمَداً بَعِيداً وَيُحَذِّرُكُمُ اللهُ نَفْسَهُ وَاللهُ رَؤُفٌ بِالْعِبادِ (30) قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَاللهُ غَفُورٌ رَحِيمٌ (31) قُلْ أَطِيعُوا اللهَ وَالرَّسُولَ تجسم الأعمال كما ذهب إلى ذلك بعض ( وَما عَمِلَتْ مِنْ سُوءٍ ) أي تجد أعماله السيئة حاضرة ( تَوَدُّ ) تلك النفس العاصية ( لَوْ أَنَّ بَيْنَها ) أي بين النفس ( وَبَيْنَهُ ) أي بين ما عملت من سوء ( أَمَداً بَعِيداً ) أي مكانا بعيدا تشبيه بالأمر المحسوس فكما أن المتباعدين لا يتلاقيان فعلا كذلك لو كان العمل السيئ بعيدا عن عامله ( وَيُحَذِّرُكُمُ اللهُ نَفْسَهُ ) حتى تخافوا من عقابه فتتقوه ( وَاللهُ رَؤُفٌ ) ذو رأفة ورحمة ( بِالْعِبادِ ) ومن رأفته يحذركم عن المعاصي حتى لا يأخذكم وبالها وعاقبتها."},{"text":"قُلْ إِن كُنتُمْ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِى يُحْبِبْكُمُ ٱللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ ۗ وَٱللَّهُ غَفُورٌ رَّحِيمٌ","tafsir":""},{"text":"قُلْ أَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ ۖ فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْكَـٰفِرِينَ","tafsir":"يا رسول الله ( إِنْ كُنْتُمْ ) أيها المسلمون ، أو يا أهل الكتاب ( تُحِبُّونَ اللهَ ) حقيقة وتصدقون في مقالتكم هذه ( فَاتَّبِعُونِي ) فيما أمر الله وأنهى ( يُحْبِبْكُمُ اللهُ ) فإن الله لا يحب إلا من اتبع رسوله في أوامره ونواهيه وإلا مجرد دعوى حب الله بلا شاهد وحقيقة لا يكفي في حب الله تعالى للمدعي ( وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ ) فإن من أحسن واتبع الرسول يغفر ذنبه ويمحي سيئته ( وَاللهُ غَفُورٌ رَحِيمٌ ) بعباده."},{"text":"۞ إِنَّ ٱللَّهَ ٱصْطَفَىٰٓ ءَادَمَ وَنُوحًا وَءَالَ إِبْرَٰهِيمَ وَءَالَ عِمْرَٰنَ عَلَى ٱلْعَـٰلَمِينَ","tafsir":"يا رسول الله ( أَطِيعُوا اللهَ وَالرَّسُولَ ) وإطاعة الله سبحانه هي إطاعة الرسول لكن ذكر ذلك تعظيما للأمر وإردافا لإطاعة الرسول فَإِنْ تَوَلَّوْا فَإِنَّ اللهَ لا يُحِبُّ الْكافِرِينَ (32) إِنَّ اللهَ اصْطَفى آدَمَ وَنُوحاً وَآلَ إِبْراهِيمَ وَآلَ عِمْرانَ عَلَى الْعالَمِينَ (33) ب ذلك كما قال ( فَأَنَّ لِلَّهِ خُمُسَهُ وَلِلرَّسُولِ ) (1) مع أن خمس الله إنما هو للرسول ويحتمل أن يكون ذكر الله والرسول لإفادة وحدة الجهة أي إن الله والرسول لهما إطاعة واحدة فهو من قبيل أطع العلماء لا من قبيل أطع العالم أو أطع أباك ( فَإِنْ تَوَلَّوْا ) وأعرضوا فلم يطيعوا ( فَإِنَّ اللهَ لا يُحِبُّ الْكافِرِينَ ) الذين يعرضون عن أوامر الله ورسوله ومعنى لا يحبهم أنه يبغضهم لا النفي للحب فقط المجامع لعدم البغض. [34] وحيث كان الكلام حول وحدة الدين وأنه هو الإسلام والتعريض بالكفار وأخيرا انتهى المطاف إلى ميزان حب الله سبحانه ناسب السياق ذكر بعض الأفراد الذين اختارهم الله سبحانه أ ليسوا هم جميعا قادة دين واحد المنتهي إلى المسلمين فمن اللازم أن يعرفوهم ويقدروهم ، فقال سبحانه ( إِنَّ اللهَ اصْطَفى ) أي اختار لرسالته ووحيه وجعلهم أنبياء مرشدين ( آدَمَ وَنُوحاً وَآلَ إِبْراهِيمَ ) الأنبياء الذين من نسله إسحاق وإسماعيل ويعقوب ويوسف وعيسى ومحمد « صلوات الله عليهم أجمعين » ( وَآلَ عِمْرانَ ) موسى وهارون عليهما‌السلام ( عَلَى الْعالَمِينَ ) وإنما خصص هؤلاء الأنبياء ، لكون آدم أبو البشر ، ونوح وآل إبراهيم بما فيهم إبراهيم ـ فإنه يقال آل فلان للأعم منه ومن آله ـ وآل عمران الذين فيهم الأنبياء ، أولوا العزم هم مدار الرسالات العالمية. ( 1) الأنفال : 42. ذُرِّيَّةً بَعْضُها مِنْ بَعْضٍ وَاللهُ سَمِيعٌ عَلِيمٌ (34) إِذْ قالَتِ امْرَأَتُ عِمْرانَ رَبِّ إِنِّي نَذَرْتُ لَكَ ما فِي بَطْنِي مُحَرَّراً فَتَقَبَّلْ مِنِّي إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ (35) [35] حال كون نوح وآل إبراهيم وآل عمران ( ذُرِّيَّةً بَعْضُها مِنْ بَعْضٍ ) في أداء الرسالة ومناصرة الدين وإرشاد الناس ، فإن من خرج عن دين آبائه ليس منهم كما قال سبحانه ( إِنَّهُ لَيْسَ مِنْ أَهْلِكَ ) (1) بخلاف من اتبع آباءه ( وَاللهُ سَمِيعٌ ) لما تقوله الذرية ( عَلِيمٌ ) بضمائرهم وأعمالهم ولذا فضلهم على من سواهم إن هؤلاء الأنبياء كلهم ذووا خصائص واحدة موروثة من جدهم آدم عليه‌السلام مما تؤهلهم لحمل الرسالة الواحدة التي هي رسالة الإسلام. [36] وفي هذا الجو يأتي ذكر والدة عيسى عليهم‌السلام وأنها كيف كانت طاهرة زكية بحيث أهلت لإيداع النبي العظيم عندها ، اذكر يا رسول الله ( إِذْ قالَتِ امْرَأَتُ عِمْرانَ ) وهي حنّة جدة عيسى عليه‌السلام من الأم ( رَبِّ إِنِّي نَذَرْتُ لَكَ ما فِي بَطْنِي مُحَرَّراً ) وذلك حين حملت لم تكن تعلم أنها أنثى فنذرت أن تجعل ما في بطنها لخدمة المسجد ومعنى المحرر الفارغ من الأعمال الدنيوية الصارف جميع أوقاته في خدمة بيت الله سبحانه ، وهكذا كان قلب أم مريم عامرا بالإيمان جاعلة أعز شيء لديها لله وفي خدمة عباد الله ( فَتَقَبَّلْ مِنِّي ) نذري ( إِنَّكَ أَنْتَ السَّمِيعُ ) لدعائي ( الْعَلِيمُ ) بما في ضميري من صدق وإخلاص. ( 1) هود : 47. فَلَمَّا وَضَعَتْها قالَتْ رَبِّ إِنِّي وَضَعْتُها أُنْثى وَاللهُ أَعْلَمُ بِما وَضَعَتْ وَلَيْسَ الذَّكَرُ كَالْأُنْثى وَإِنِّي سَمَّيْتُها مَرْيَمَ وَإِنِّي أُعِيذُها بِكَ وَذُرِّيَّتَها مِنَ الشَّيْطانِ الرَّجِيمِ (36) فَتَقَبَّلَها رَبُّها بِقَبُولٍ حَسَنٍ وَأَنْبَتَها نَباتاً حَسَناً وَكَفَّلَها زَكَرِيَّا"},{"text":"ذُرِّيَّةًۢ بَعْضُهَا مِنۢ بَعْضٍ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ","tafsir":""},{"text":"إِذْ قَالَتِ ٱمْرَأَتُ عِمْرَٰنَ رَبِّ إِنِّى نَذَرْتُ لَكَ مَا فِى بَطْنِى مُحَرَّرًا فَتَقَبَّلْ مِنِّىٓ ۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ","tafsir":""},{"text":"فَلَمَّا وَضَعَتْهَا قَالَتْ رَبِّ إِنِّى وَضَعْتُهَآ أُنثَىٰ وَٱللَّهُ أَعْلَمُ بِمَا وَضَعَتْ وَلَيْسَ ٱلذَّكَرُ كَٱلْأُنثَىٰ ۖ وَإِنِّى سَمَّيْتُهَا مَرْيَمَ وَإِنِّىٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيْطَـٰنِ ٱلرَّجِيمِ","tafsir":""},{"text":"فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٍ وَأَنۢبَتَهَا نَبَاتًا حَسَنًا وَكَفَّلَهَا زَكَرِيَّا ۖ كُلَّمَا دَخَلَ عَلَيْهَا زَكَرِيَّا ٱلْمِحْرَابَ وَجَدَ عِندَهَا رِزْقًا ۖ قَالَ يَـٰمَرْيَمُ أَنَّىٰ لَكِ هَـٰذَا ۖ قَالَتْ هُوَ مِنْ عِندِ ٱللَّهِ ۖ إِنَّ ٱللَّهَ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ","tafsir":"أي وضعت امرأة عمران جنينها خاب ظنها ورأت أنها أنثى ف ( قالَتْ ) في يأس وتبتل ( رَبِّ إِنِّي وَضَعْتُها أُنْثى ) والأنثى لا تصلح للخدمة ( وَاللهُ أَعْلَمُ بِما وَضَعَتْ ) فإن الله كان يعلم ذلك منذ كانت جنينا في بطنها بينما هي لا تعلم إلا بعد الوضع ( وَلَيْسَ الذَّكَرُ كَالْأُنْثى ) فالذكر يأتي منه الخدمة ولا بأس بحشره في مكان العبادة في المسجد بخلاف الأنثى إذ لا تلائم الرجال ولا تلائم عادتها النسائية المسجد ، ثم قالت ( وَإِنِّي سَمَّيْتُها مَرْيَمَ ) أي جعلت اسمها « مريم » وهي في لغتهم بمعنى العابدة ( وَإِنِّي أُعِيذُها ) أي أجعلها في حفظك وحراستك ( بِكَ وَ ) أعيذ ( ذُرِّيَّتَها مِنَ الشَّيْطانِ الرَّجِيمِ ) أي المرجوم باللعن والمطرود عن الخير."},{"text":"هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥ ۖ قَالَ رَبِّ هَبْ لِى مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً ۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ","tafsir":"أي تقبل الله سبحانه مريم مع أنوثتها ( بِقَبُولٍ حَسَنٍ ) حيث قدر لها السعادة وأن يجعل منها عيسى المسيح عليه‌السلام ( وَأَنْبَتَها نَباتاً حَسَناً ) أي جعل نشوءها نشئا حسنا بالفضيلة والأخلاق والعفة والطهارة ( وَكَفَّلَها زَكَرِيَّا ) أي جعل الله سبحانه كفيلها زكريا وكان زوج خالة مريم ، وهو من أنبياء الله سبحانه فإن أم مريم كُلَّما دَخَلَ عَلَيْها زَكَرِيَّا الْمِحْرابَ وَجَدَ عِنْدَها رِزْقاً قالَ يا مَرْيَمُ أَنَّى لَكِ هذا قالَتْ هُوَ مِنْ عِنْدِ اللهِ إِنَّ اللهَ يَرْزُقُ مَنْ يَشاءُ بِغَيْرِ حِسابٍ (37) هُنالِكَ دَعا زَكَرِيَّا رَبَّهُ قالَ رَبِّ هَبْ لِي مِنْ لَدُنْكَ ذُرِّيَّةً طَيِّبَةً إِنَّكَ سَمِيعُ الدُّعاءِ (38) ذهبت بها إلى المسجد وسلمتها إلى الأحبار فتنازعوا في كفالتها حتى اقترعوا عليها وخرجت القرعة باسم زكريا فكانت مريم تخدم في صغرها المسجد حتى إذا بلغت مبلغ النساء انفصلت عنهم في غرفة خاصة بها بناها لها زكريا في وسط المسجد عالية لا يمكن الوصول إليها إلا بسلم وكان يأتي بحوائجها كل يوم وكان من غريب أمرها أن ( كُلَّما دَخَلَ عَلَيْها زَكَرِيَّا الْمِحْرابَ ) وهي غرفتها وسمي محرابا لأنه محل محاربة النفس والشيطان ( وَجَدَ عِنْدَها رِزْقاً ) فاكهة في غير حينها ( قالَ يا مَرْيَمُ أَنَّى لَكِ هذا ) أي من أين لك هذا الرزق ( قالَتْ ) مريم ( هُوَ مِنْ عِنْدِ اللهِ ) أرسله إلي الله تعالى من الجنة كرامة لي ( إِنَّ اللهَ يَرْزُقُ مَنْ يَشاءُ بِغَيْرِ حِسابٍ ) أي بغير تقتير أو محاسبة من المرزوق."},{"text":"فَنَادَتْهُ ٱلْمَلَـٰٓئِكَةُ وَهُوَ قَآئِمٌ يُصَلِّى فِى ٱلْمِحْرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحْيَىٰ مُصَدِّقًۢا بِكَلِمَةٍ مِّنَ ٱللَّهِ وَسَيِّدًا وَحَصُورًا وَنَبِيًّا مِّنَ ٱلصَّـٰلِحِينَ","tafsir":"الذي رأى زكريا إكرام الله سبحانه لمريم نحو خرق العادة من إرسال الفاكهة إليها ( دَعا زَكَرِيَّا رَبَّهُ قالَ رَبِّ هَبْ لِي مِنْ لَدُنْكَ ) أي من عندك ( ذُرِّيَّةً طَيِّبَةً ) أي نسلا صالحا ( إِنَّكَ سَمِيعُ الدُّعاءِ ) وكان زكريا يائسا من الأولاد حيث كبر وشاخ وكانت امرأته عاقرا لكن طلب ودعا مريدا على وجه الإعجاز وخرق العادة. فَنادَتْهُ الْمَلائِكَةُ وَهُوَ قائِمٌ يُصَلِّي فِي الْمِحْرابِ أَنَّ اللهَ يُبَشِّرُكَ بِيَحْيى مُصَدِّقاً بِكَلِمَةٍ مِنَ اللهِ وَسَيِّداً وَحَصُوراً وَنَبِيًّا مِنَ الصَّالِحِينَ (39) قالَ رَبِّ أَنَّى يَكُونُ لِي غُلامٌ وَقَدْ بَلَغَنِيَ الْكِبَرُ وَامْرَأَتِي عاقِرٌ"},{"text":"قَالَ رَبِّ أَنَّىٰ يَكُونُ لِى غُلَـٰمٌ وَقَدْ بَلَغَنِىَ ٱلْكِبَرُ وَٱمْرَأَتِى عَاقِرٌ ۖ قَالَ كَذَٰلِكَ ٱللَّهُ يَفْعَلُ مَا يَشَآءُ","tafsir":"أي نادت زكريا ( الْمَلائِكَةُ وَهُوَ قائِمٌ يُصَلِّي فِي الْمِحْرابِ ) إما المراد المحراب أو نفس المسجد وسمي محرابا لأنه محل محاربة الشيطان والنفس حيث يريدان صرف الإنسان إلى الدنيا والمسجد يصرفه إلى الآخرة ( أَنَّ اللهَ يُبَشِّرُكَ بِيَحْيى ) سماه سبحانه بهذا الاسم قبيل الولادة في حال كونه ( مُصَدِّقاً بِكَلِمَةٍ مِنَ اللهِ ) والمراد بالكلمة عيسى عليه‌السلام أي أن يحيى يصدق نبوة عيسى ، وإنما سمي عيسى عليه‌السلام كلمة الله لأنه كان بإلقاء الله إياها إلى مريم ، كما تلقى الكلمة من الفم ( وَسَيِّداً ) أي ذو سيادة وشرافة ( وَحَصُوراً ) يحصر نفسه عن الملذات ، أو عن النساء خاصة بمعنى أنه عليه‌السلام كان زاهدا ، وكون حصور مدحا ليحيي عليه‌السلام لأسباب خاصة لا ينافي استحباب الزواج في الشرائع ( وَنَبِيًّا مِنَ الصَّالِحِينَ ) الذين يصلحون ولا يكن فيهم فساد كما هو شأن جميع الأنبياء. [41] فاستفسر زكريا عليه‌السلام عن كيفية حصول الولد هل يرزقه وهما على ما هما عليه من الحالة أم تتبدل حالتهما ( قالَ ) زكريا في جواب الملائكة سائلا عن الله سبحانه ( رَبِّ أَنَّى يَكُونُ لِي غُلامٌ ) أي كيف يكون لي ولد ( وَقَدْ بَلَغَنِيَ الْكِبَرُ ) أي الشيخوخة ( وَامْرَأَتِي عاقِرٌ ) قالَ كَذلِكَ اللهُ يَفْعَلُ ما يَشاءُ (40) قالَ رَبِّ اجْعَلْ لِي آيَةً قالَ آيَتُكَ أَلاَّ تُكَلِّمَ النَّاسَ ثَلاثَةَ أَيَّامٍ إِلاَّ رَمْزاً وَاذْكُرْ رَبَّكَ كَثِيراً وَسَبِّحْ بِالْعَشِيِّ وَالْإِبْكارِ (41) وَإِذْ قالَتِ الْمَلائِكَةُ يا مَرْيَمُ إِ نَّ اللهَ اصْطَفاكِ وَطَهَّرَكِ ليس لها قابلية الولادة ( قالَ ) الملك في جوابه ( كَذلِكَ ) أي كالحال الذي أنتما عليه من الكبر والعقر ( اللهُ يَفْعَلُ ما يَشاءُ ) فإنه قادر على كل شيء."},{"text":"قَالَ رَبِّ ٱجْعَل لِّىٓ ءَايَةً ۖ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَـٰثَةَ أَيَّامٍ إِلَّا رَمْزًا ۗ وَٱذْكُر رَّبَّكَ كَثِيرًا وَسَبِّحْ بِٱلْعَشِىِّ وَٱلْإِبْكَـٰرِ","tafsir":""},{"text":"وَإِذْ قَالَتِ ٱلْمَلَـٰٓئِكَةُ يَـٰمَرْيَمُ إِنَّ ٱللَّهَ ٱصْطَفَىٰكِ وَطَهَّرَكِ وَٱصْطَفَىٰكِ عَلَىٰ نِسَآءِ ٱلْعَـٰلَمِينَ","tafsir":"زكريا عليه‌السلام ( رَبِّ اجْعَلْ لِي آيَةً ) أي علامة أعرف بها وقت الحمل لأزيد شكرا وسرورا أو علامة أعرف بها استجابة دعائي ليطمئن قلبي وأجده محسوسا ملموسا بعد ما وجدته سماعا بالبشارة ( قالَ ) الملك ، أو الله سبحانه بخلق الصوت في الفضاء ( آيَتُكَ ) أي الدليل على ذلك ( أَلَّا تُكَلِّمَ النَّاسَ ) أي لا تقدر على التكلم معهم كلما توجهت إليهم بالكلام يعقد لسانك ( ثَلاثَةَ أَيَّامٍ إِلَّا رَمْزاً ) بالإشارة باليد والرأس ( وَاذْكُرْ رَبَّكَ كَثِيراً ) فإن لسانك لا ينعقد عن الذكر والتسبيح لله سبحانه ( وَسَبِّحْ ) أي نزه الباري تعالى ( بِالْعَشِيِ ) آخر النهار ( وَالْإِبْكارِ ) أول النهار ، من أبكر فهو اسم مفرد لا جمع. [43] ثم رجع السياق إلى بقية قصة مريم عليها‌السلام حيث كانت قصة زكريا عليه‌السلام توسطت في الموضوع لمناسبة ( وَ ) اذكر يا رسول الله ( إِذْ قالَتِ الْمَلائِكَةُ يا مَرْيَمُ إِنَّ اللهَ اصْطَفاكِ ) اختارك لعبادته وإطاعته وأن تكوني وعاء لنبيه ( وَطَهَّرَكِ ) من الآثام والذنوب والأدناس وَاصْطَفاكِ عَلى نِساءِ الْعالَمِينَ (42) يا مَرْيَمُ اقْنُتِي لِرَبِّكِ وَاسْجُدِي وَارْكَعِي مَعَ الرَّاكِعِينَ (43) ذلِكَ مِنْ أَنْباءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَما كُنْتَ لَدَيْهِمْ إِذْ يُلْقُونَ أَقْلامَهُمْ أَيُّهُمْ يَكْفُلُ مَرْيَمَ والعادات النسائية ( وَاصْطَفاكِ عَلى نِساءِ الْعالَمِينَ ) وكرر الاصطفاء تأكيدا ومقدمة لذكر نساء العالمين فليس الاختيار لها في جملة مختارات وإنما هي مختارة على سائر نساء زمانها وعوالمها لأكل العالمين فإن فاطمة عليها‌السلام هي المختارة المطلقة على جميع النساء وقد تقدم أن مثل هذه العبارة تقال مرادا بها العوالم المعاصرة لأكل العوالم كما يقال إن الدولة الفلانية أقوى جميع الدول يراد الدول المعاصرة لها لا كل دولة في العالم أتت أو تأتي."},{"text":"يَـٰمَرْيَمُ ٱقْنُتِى لِرَبِّكِ وَٱسْجُدِى وَٱرْكَعِى مَعَ ٱلرَّٰكِعِينَ","tafsir":""},{"text":"ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ ۚ وَمَا كُنتَ لَدَيْهِمْ إِذْ يُلْقُونَ أَقْلَـٰمَهُمْ أَيُّهُمْ يَكْفُلُ مَرْيَمَ وَمَا كُنتَ لَدَيْهِمْ إِذْ يَخْتَصِمُونَ","tafsir":"القنوت الخضوع والإخلاص في العبادة ( لِرَبِّكِ وَاسْجُدِي وَارْكَعِي مَعَ الرَّاكِعِينَ ) أي في جملة الذين يركعون لله سبحانه."},{"text":"إِذْ قَالَتِ ٱلْمَلَـٰٓئِكَةُ يَـٰمَرْيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٍ مِّنْهُ ٱسْمُهُ ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ وَجِيهًا فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمِنَ ٱلْمُقَرَّبِينَ","tafsir":"الذي تقدم من قصص مريم وزكريا ويحيى ( مِنْ أَنْباءِ الْغَيْبِ ) أي الأخبار الغائبة عن الحواس فإن كل شيء غاب عن الحواس يسمى غيبا ( نُوحِيهِ إِلَيْكَ ) أي نلقيه عليك ليدل على أنك من المرسلين فإن الإخبار عما لم يحضره الإنسان ولم يعلمه من طريق التاريخ يدل على كونه بالإعجاز وخارق للعادة ( وَما كُنْتَ ) يا رسول الله ( لَدَيْهِمْ ) أي عند الأحبار والمعاصرين لمريم عليها‌السلام ( إِذْ يُلْقُونَ أَقْلامَهُمْ ) التي بها كانوا يكتبون التوراة ( أَيُّهُمْ يَكْفُلُ مَرْيَمَ ) فإن زوجة وَما كُنْتَ لَدَيْهِمْ إِذْ يَخْتَصِمُونَ (44) إِذْ قالَتِ الْمَلائِكَةُ يا مَرْيَمُ إِنَّ اللهَ يُبَشِّرُكِ بِكَلِمَةٍ مِنْهُ اسْمُهُ الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ وَجِيهاً فِي الدُّنْيا وَالْآخِرَةِ وَمِنَ الْمُقَرَّبِينَ (45) وَيُكَلِّمُ النَّاسَ فِي الْمَهْدِ عمران لما أتت بمريم إلى المسجد اختلفت الأحبار في من يكفلها لأنها كانت بنت إمامهم وصاحب قربانهم فقال لهم زكريا : أنا أحق بها لأن خالتها عندي فقال له الأحبار : إنها لو تركت لأحق الناس بها لتركت لأمها التي ولدتها ولكن نقترع عليها فتكون عند من خرج سهمه ، فانطلقوا وهم تسعة وعشرون رجلا إلى نهر جار فألقوا أقلامهم في الماء فأبرز قلم زكريا وارتفع فوق الماء ورسبت أقلامهم ولذا أخذها زكريا ( وَما كُنْتَ لَدَيْهِمْ إِذْ يَخْتَصِمُونَ ) في شأنها وأن أيهم يكفلها. [46] واذكر يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( إِذْ قالَتِ الْمَلائِكَةُ ) مخاطبة لمريم عليها‌السلام ( يا مَرْيَمُ إِنَّ اللهَ يُبَشِّرُكِ بِكَلِمَةٍ مِنْهُ ) أي بولد هو كلمة الله تلقى عليك ويخرج منك بصورة عيسى المسيح عليه‌السلام ( اسْمُهُ الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ ) قيل سمي مسيحا لأنه كان يمسح الأرض ويسير فيها ، وذكر في الكلام أمه دحضا لمن يفتري قائلا : أنه ابن الله ، في حال كونه ( وَجِيهاً فِي الدُّنْيا وَالْآخِرَةِ ) أي ذا جاه وقدر وشرف ( وَمِنَ الْمُقَرَّبِينَ ) لله تعالى قرب شرف وجاه لا زمان ومكان."},{"text":"وَيُكَلِّمُ ٱلنَّاسَ فِى ٱلْمَهْدِ وَكَهْلًا وَمِنَ ٱلصَّـٰلِحِينَ","tafsir":""},{"text":"قَالَتْ رَبِّ أَنَّىٰ يَكُونُ لِى وَلَدٌ وَلَمْ يَمْسَسْنِى بَشَرٌ ۖ قَالَ كَذَٰلِكِ ٱللَّهُ يَخْلُقُ مَا يَشَآءُ ۚ إِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ","tafsir":"أي في حال كونه صغيرا قبل أوان تكلم وَكَهْلاً وَمِنَ الصَّالِحِينَ (46) قالَتْ رَبِّ أَنَّى يَكُونُ لِي وَلَدٌ وَلَمْ يَمْسَسْنِي بَشَرٌ قالَ كَذلِكِ اللهُ يَخْلُقُ ما يَشاءُ إِذا قَضى أَمْراً فَإِنَّما يَقُولُ لَهُ كُنْ فَيَكُونُ (47) وَيُعَلِّمُهُ الْكِتابَ وَالْحِكْمَةَ وَالتَّوْراةَ وَالْإِنْجِيلَ (48) الأطفال والمهد هو الموضع الذي يوضع فيه الطفل ويهز من خشب أو حديد أو ثوب أو نحوها ( وَكَهْلاً ) أي يكلمهم كهلا بالوحي والكهل ما بين الشاب والشيخ أو يراد الإخبار عن بقائه إلى ذلك الوقت ( وَمِنَ الصَّالِحِينَ ) الذين فيهم الصلاح دون الفساد."},{"text":"وَيُعَلِّمُهُ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ","tafsir":"مريم لما سمعت هذا النبأ المدهش ( رَبِّ أَنَّى يَكُونُ لِي وَلَدٌ ) أي كيف يمكن أن ألد ولدا ( وَلَمْ يَمْسَسْنِي بَشَرٌ ) أي لم يقترب مني على نحو النكاح فإنها كانت دون زوج ( قالَ ) الملك في جواب مريم ( كَذلِكِ ) أي هكذا بدون المس والزوج ( اللهُ يَخْلُقُ ما يَشاءُ ) فإنه ليس بخارج عن قدرة الله سبحانه ( إِذا قَضى أَمْراً ) أراد خلقه وتكوينه ( فَإِنَّما يَقُولُ لَهُ كُنْ ) قولا أو إرادة بدون تلفظ ( فَيَكُونُ ) في الخارج ، فإن الله يوجد الأشياء بصرف الإرادة."},{"text":"وَرَسُولًا إِلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنِّى قَدْ جِئْتُكُم بِـَٔايَةٍ مِّن رَّبِّكُمْ ۖ أَنِّىٓ أَخْلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيْرًۢا بِإِذْنِ ٱللَّهِ ۖ وَأُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ وَأُحْىِ ٱلْمَوْتَىٰ بِإِذْنِ ٱللَّهِ ۖ وَأُنَبِّئُكُم بِمَا تَأْكُلُونَ وَمَا تَدَّخِرُونَ فِى بُيُوتِكُمْ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ","tafsir":"أي يعلم الله سبحانه المسيح ( الْكِتابَ ) أي الكتابة أو مطلق الكتاب المنزل من السماء ( وَالْحِكْمَةَ ) حتى يكون حكيما يعرف مواضع الأشياء أو المراد بالحكمة علم الشرائع من الحلال والحرام وسائر الأحكام ( وَالتَّوْراةَ ) وهو كتاب موسى عليه‌السلام ( وَالْإِنْجِيلَ ) وهو الكتاب الذي أنزل على المسيح بنفسه وقد ذكروا وَرَسُولاً إِلى بَنِي إِسْرائِيلَ أَنِّي قَدْ جِئْتُكُمْ بِآيَةٍ مِنْ رَبِّكُمْ أَنِّي أَخْلُقُ لَكُمْ مِنَ الطِّينِ كَهَيْئَةِ الطَّيْرِ فَأَنْفُخُ فِيهِ فَيَكُونُ طَيْراً بِإِذْنِ اللهِ وَأُبْرِئُ الْأَكْمَهَ وَالْأَبْرَصَ وَأُحْيِ الْمَوْتى بِإِذْنِ اللهِ وَأُنَبِّئُكُمْ بِما تَأْكُلُونَ وَ ما تَدَّخِرُونَ فِي بُيُوتِكُمْ أن معنى التوراة « التعليم والبشارة » ومعنى الإنجيل « البشارة والتعليم » ."},{"text":"وَمُصَدِّقًا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَلِأُحِلَّ لَكُم بَعْضَ ٱلَّذِى حُرِّمَ عَلَيْكُمْ ۚ وَجِئْتُكُم بِـَٔايَةٍ مِّن رَّبِّكُمْ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ","tafsir":"نجعله ( رَسُولاً إِلى بَنِي إِسْرائِيلَ ) لإرشادهم من الضلالة إلى الحق ، وانتقل السياق إلى كلام عيسى عليه‌السلام الذي كان يتكلم به بعد النبوة ، فكان يقول لبني إسرائيل ( أَنِّي قَدْ جِئْتُكُمْ بِآيَةٍ مِنْ رَبِّكُمْ ) أي بمعجزة وعلامة تدل على صدق دعواتي للنبوة وأني رسول إليكم ( أَنِّي أَخْلُقُ لَكُمْ ) أي أصنع لأجلكم ( مِنَ الطِّينِ كَهَيْئَةِ الطَّيْرِ ) أي على صورة الطائر ( فَأَنْفُخُ فِيهِ ) أي في الطائر المصنوع من الطين ( فَيَكُونُ طَيْراً بِإِذْنِ اللهِ ) وإرادته وقدرته ، فصنع صورة خفاش من الطين ونفخ فيه فطار ( وَأُبْرِئُ ) أي أشفي ( الْأَكْمَهَ ) الذي ولد أعمى ، أو مطلق الأعمى ( وَالْأَبْرَصَ ) الذي أصيب بمرض البرص وهو الوضح ( وَأُحْيِ الْمَوْتى ) كل ذلك ( بِإِذْنِ اللهِ ) فكان يقف على القبر ويقول للميت قم بإذن الله فيقوم ينفض عن جسمه الغبار كأنه لم يمت أصلا ( وَأُنَبِّئُكُمْ ) أي أخبركم ( بِما تَأْكُلُونَ ) إخبارا عن الغيب ( وَما تَدَّخِرُونَ ) من الادخار ( فِي بُيُوتِكُمْ ) فكان يقول إِنَّ فِي ذلِكَ لَآيَةً لَكُمْ إِنْ كُنْتُمْ مُؤْمِنِينَ (49) وَمُصَدِّقاً لِما بَيْنَ يَدَيَّ مِنَ التَّوْراةِ وَلِأُحِلَّ لَكُمْ بَعْضَ الَّذِي حُرِّمَ عَلَيْكُمْ وَجِئْتُكُمْ بِآيَةٍ مِنْ رَبِّكُمْ فَاتَّقُوا اللهَ وَأَطِيعُونِ (50) إِنَّ اللهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هذا صِراطٌ مُسْتَقِيمٌ (51) للشخص تغذيت بكذا أو حفظت لليل كذا ( إِنَّ فِي ذلِكَ ) الذي ذكرت من المعجزات ( لَآيَةً ) معجزة دالة على صدقي ( لَكُمْ إِنْ كُنْتُمْ مُؤْمِنِينَ ) بالله وإنما يقيد بالإيمان لأن من لا يؤمن بالله سبحانه لا يمكن أن يفرق بين المعجزة والسحر."},{"text":"إِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ ۗ هَـٰذَا صِرَٰطٌ مُّسْتَقِيمٌ","tafsir":"ذلك في حال كونه ( مُصَدِّقاً لِما بَيْنَ يَدَيَ ) أي ما تقدم علي وأنزل قبلي ( مِنَ التَّوْراةِ ) فإنه من أسباب لزوم تصديقي حيث لا أبطل كتاب بني إسرائيل ( وَلِأُحِلَّ لَكُمْ ) يا بني إسرائيل ( بَعْضَ الَّذِي حُرِّمَ عَلَيْكُمْ ) في شريعة موسى عليه‌السلام وهذا التحليل إنما كان لانقضاء ظرف التحريم ( وَجِئْتُكُمْ بِآيَةٍ مِنْ رَبِّكُمْ ) أي بحجة تشهد بصدقي وأني من قبل الله سبحانه ، وهي إما إجمال لما فصل في الآية السابقة ، جمعا لأعماله عليه‌السلام في الأمور الثلاثة ، التصديق ، والتحليل ، والإعجاز ، وإما يراد به آية أخرى لم تذكر في القرآن ( فَاتَّقُوا اللهَ ) وصدقوا برسالتي ( وَأَطِيعُونِ ) فيما آمركم به وأنهاكم عنه."},{"text":"۞ فَلَمَّآ أَحَسَّ عِيسَىٰ مِنْهُمُ ٱلْكُفْرَ قَالَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ ۖ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشْهَدْ بِأَنَّا مُسْلِمُونَ","tafsir":"فلست أنا ابنا له ، قال ذلك ردا على النصارى الذين اتخذوه إلها ( فَاعْبُدُوهُ ) وحده ولا تعبدوا من دونه الشركاء كما عبدت اليهود عزيرا ، وعبدت النصارى المسيح ( هذا صِراطٌ مُسْتَقِيمٌ ) فَلَمَّا أَحَسَّ عِيسى مِنْهُمُ الْكُفْرَ قالَ مَنْ أَنْصارِي إِلَى اللهِ قالَ الْحَوارِيُّونَ نَحْنُ أَنْصارُ اللهِ آمَنَّا بِاللهِ وَاشْهَدْ بِأَنَّا مُسْلِمُونَ (52) رَبَّنا آمَنَّا بِما أَنْزَلْتَ وَاتَّبَعْنَا الرَّسُولَ فَاكْتُبْنا مَعَ الشَّاهِدِينَ (53) لا اعوجاج له ولا انحراف بخلاف سائر الطرائق التي هي طرق معوجة منحرفة زائغة. [53] وبعد هذه الحجج لم يزدد بني إسرائيل إلا عنادا واستكبارا ( فَلَمَّا أَحَسَ ) من الحس أي وجد ( عِيسى ) عليه‌السلام ( مِنْهُمُ الْكُفْرَ ) وأنه لم تنفعهم الحجة والدليل ( قالَ مَنْ أَنْصارِي إِلَى اللهِ ) الذين ينصرون ديني للوصول إلى ثواب الله تعالى إذ المسلم يقطع طريق الوصول إلى الله لينتهي إلى ثوابه ( قالَ الْحَوارِيُّونَ ) هو جمع حواري من الحور بمعنى شدة البياض وسمي خاصة الإنسان بالحواري لنقاء قلبه وصفاء باطنه ( نَحْنُ أَنْصارُ اللهِ ) الذين ننصر دينه ونتابعك على ما أنت عليه ( آمَنَّا بِاللهِ ) إيمانا لا يشوبه شرك ( وَاشْهَدْ ) يا عيسى ( بِأَنَّا مُسْلِمُونَ ) في أدياننا. [54] ثم توجهوا إلى الله سبحانه داعين قائلين ( رَبَّنا ) أي يا ربنا ( آمَنَّا بِما أَنْزَلْتَ ) على رسولك عيسى عليه‌السلام ( وَاتَّبَعْنَا الرَّسُولَ ) فيما أمر ونهى ( فَاكْتُبْنا مَعَ الشَّاهِدِينَ ) الذين يشهدون على الأمم كما قال سبحانه ( لِتَكُونُوا شُهَداءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيداً ) (1) فالرسل ( 1) البقرة : 144. وَمَكَرُوا وَمَكَرَ اللهُ وَاللهُ خَيْرُ الْماكِرِينَ (54) إِذْ قالَ اللهُ يا عِيسى إِنِّي مُتَوَفِّيكَ شهداء على أصحابهم وهم شهداء على سائر الناس. [55] ذلك كان قول أنصار عيسى والمؤمنين به أما الكفار الذين جحدوه وأنكروه فلم يؤمنوا ( وَمَكَرُوا ) لعيسى عليه‌السلام بأن يقتلوه ( وَمَكَرَ اللهُ ) بإنقاذه منهم وقتل كبيرهم عوضه ، والمكر لغة بمعنى تطلب العلاج لأمر ما والغالب يستعمل في الشر ، ولعل نسبة المكر هنا إلى الله سبحانه للمقابلة نحو قوله ( تَعْلَمُ ما فِي نَفْسِي وَلا أَعْلَمُ ما فِي نَفْسِكَ ) (1) مع أن الله سبحانه ليس له نفس ( وَاللهُ خَيْرُ الْماكِرِينَ ) لأنه أعرف بطرق العلاج ، وفي بعض التفاسير أنه لما أراد ملك بني إسرائيل قتل عيسى عليه‌السلام دخل خوخته وفيها كوة فرفعه جبرائيل من الكوة إلى السماء وقال الملك لرجل خبيث من الكفار ادخل عليه فاقتله فدخل الخوخة فألقى الله عليه شبه عيسى عليه‌السلام فخرج إلى أصحابه يخبرهم أنه ليس في البيت فقتلوه بظن أنه عيسى وكان قتله على نحو الصلب وكلما صاح أنه ليس بعيسى لم يفد. [56] واذكر يا رسول الله ( إِذْ قالَ اللهُ ) أو ذاك إذ قال ، أو ومكر الله إذ قال ( يا عِيسى إِنِّي مُتَوَفِّيكَ ) أي آخذك وافيا فإن معنى توفاه أخذه وافيا ويقال توفى الله فلان حين يأخذ روحه وافية من الوفاء وهو في أخذ الروح والجسد أقرب إلى الحقيقة من أخذ الروح فقط فإنه ( 1) المائدة : 117. وَرافِعُكَ إِلَيَّ وَمُطَهِّرُكَ مِنَ الَّذِينَ كَفَرُوا وَجاعِلُ الَّذِينَ اتَّبَعُوكَ فَوْقَ الَّذِينَ كَفَرُوا إِلى يَوْمِ الْقِيامَةِ ثُمَّ إِلَيَّ مَرْجِعُكُمْ فَأَحْكُمُ بَيْنَكُمْ فِيما كُنْتُمْ فِيهِ تَخْتَلِفُونَ (55) فَأَمَّا الَّذِينَ كَفَرُوا فَأُعَذِّبُهُمْ عَذاباً شَدِيداً فِي الدُّنْيا بعلاقة الكل والجزء أي آخذك ( وَرافِعُكَ إِلَيَ ) فإنه عليه‌السلام رفع إلى السماء الرابعة كما في بعض الأحاديث وقد يظن أن ذلك ينافي ما اشتهر في العلم الحديث من عدم وجود سماوات ذات حجوم لكنه ظن غير تام إذ السماء حتى لو كان يراد بها المدار ـ كما هو معناه لغة ـ تكون هناك سماوات وللتوضيح راجع « الهيئة والإسلام » تأليف « العلامة الشهرستاني » ( وَمُطَهِّرُكَ مِنَ الَّذِينَ كَفَرُوا ) فإنهم أرجاس أنجاس فكما أن الجسم المحاط بالنجاسة إذا غسل يطهر عنها كذلك إن الإنسان الطيب في أناس كفرة عصاة إذا أخرج من بينهم كان تطهيرا له في المعنى عن لوثهم وكفرهم ( وَجاعِلُ الَّذِينَ اتَّبَعُوكَ ) من النصارى ( فَوْقَ الَّذِينَ كَفَرُوا ) بك من اليهود ( إِلى يَوْمِ الْقِيامَةِ ) وهذا من معاجز القرآن الحكيم فإن النصارى دائما فوق اليهود إلى يومنا هذا وسيكونون كذلك إلى يوم القيامة ( ثُمَّ إِلَيَّ مَرْجِعُكُمْ ) جميعا أنت وأصحابك الكفار ، وذلك يوم القيامة ( فَأَحْكُمُ بَيْنَكُمْ فِيما كُنْتُمْ فِيهِ تَخْتَلِفُونَ ) من التوحيد والشرك ومن كونك نبيا وسائر الأصول والفروع التي كنت تنادي بها وتبشر من أجلها وكان اليهود يكفرون بها."},{"text":"رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلْتَ وَٱتَّبَعْنَا ٱلرَّسُولَ فَٱكْتُبْنَا مَعَ ٱلشَّـٰهِدِينَ","tafsir":""},{"text":"وَمَكَرُوا۟ وَمَكَرَ ٱللَّهُ ۖ وَٱللَّهُ خَيْرُ ٱلْمَـٰكِرِينَ","tafsir":""},{"text":"إِذْ قَالَ ٱللَّهُ يَـٰعِيسَىٰٓ إِنِّى مُتَوَفِّيكَ وَرَافِعُكَ إِلَىَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُوا۟ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوْقَ ٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ ۖ ثُمَّ إِلَىَّ مَرْجِعُكُمْ فَأَحْكُمُ بَيْنَكُمْ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ","tafsir":""},{"text":"فَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَأُعَذِّبُهُمْ عَذَابًا شَدِيدًا فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمَا لَهُم مِّن نَّـٰصِرِينَ","tafsir":""},{"text":"وَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَيُوَفِّيهِمْ أُجُورَهُمْ ۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّـٰلِمِينَ","tafsir":"بك وبما جئت به ( فَأُعَذِّبُهُمْ عَذاباً شَدِيداً فِي الدُّنْيا ) وَالْآخِرَةِ وَما لَهُمْ مِنْ ناصِرِينَ (56) وَأَمَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَاللهُ لا يُحِبُّ الظَّالِمِينَ (57) ذلِكَ نَتْلُوهُ عَلَيْكَ مِنَ الْآياتِ وَالذِّكْرِ الْحَكِيمِ (58) بضرب الذلة والمسكنة عليهم وإنهم دائما تحت حكم أصحابك وأنه لا تقوم لهم دولة إلا بحبل من الله وحبل من الناس وإنهم مكروهون منفورون أبد الآبدين ( وَالْآخِرَةِ ) بإدخالهم نارا أحاطت بهم سرادقها وإن يستغيثوا يغاثوا بماء كالمهل ( وَما لَهُمْ مِنْ ناصِرِينَ ) ينصرونهم من بأس الله وعذابه."},{"text":"ذَٰلِكَ نَتْلُوهُ عَلَيْكَ مِنَ ٱلْـَٔايَـٰتِ وَٱلذِّكْرِ ٱلْحَكِيمِ","tafsir":"بك وبما بشرت به ( وَعَمِلُوا الصَّالِحاتِ ) مما أمرناهم به واجتنبوا عن المحرمات ، فإنه لا يقال يعمل فلان الصالحات إلا إذا اجتنب الآثام إلى جنب إتيانه بالواجبات ( فَيُوَفِّيهِمْ ) أي يعطيهم الله ( أُجُورَهُمْ ) كاملة غير منقوصة فإن الوفاء إعطاء المطلوب كاملا ( وَاللهُ لا يُحِبُّ الظَّالِمِينَ ) الذين ظلموا بالكفر أو بعدم العمل الصالح."},{"text":"إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَ ۖ خَلَقَهُۥ مِن تُرَابٍ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ","tafsir":"المذكور هنا من أخبار زكريا وعيسى ويحيى ومريم عليهم‌السلام ( نَتْلُوهُ عَلَيْكَ ) أي نقرأه عليك بسبب الوحي ( مِنَ الْآياتِ ) أي من جملة الآيات والحجج الدالة على صدقك وأنك نبي يوحى إليه ( وَ ) من ( الذِّكْرِ ) إي القرآن ( الْحَكِيمِ ) المحكم الذي لا يتطرق إليه بطلان أو زيغ. إِنَّ مَثَلَ عِيسى عِنْدَ اللهِ كَمَثَلِ آدَمَ خَلَقَهُ مِنْ تُرابٍ ثُمَّ قالَ لَهُ كُنْ فَيَكُونُ (59) الْحَقُّ مِنْ رَبِّكَ فَلا تَكُنْ مِنَ الْمُمْتَرِينَ (60) فَمَنْ حَاجَّكَ فِيهِ [60] وهنا تتهيأ النفوس لإدراك حقيقة عيسى هل كان بشرا وكيف ولد من غير أب فقال سبحانه ( إِنَّ مَثَلَ عِيسى عِنْدَ اللهِ كَمَثَلِ آدَمَ ) فليس ولادة عيسى من غير أب عجيبا وبدعا ولا يدل ذلك على أنه رب ، فآدم أعجب منه أ ليس الله سبحانه ( خَلَقَهُ ) أي خلق آدم ( مِنْ تُرابٍ ) صنعه وجسده ( ثُمَّ قالَ لَهُ كُنْ ) إنسانا حيا ( فَيَكُونُ ) كما قال ومقتضى القاعدة أن يقال « فكان » إلا أن هذه الجملة أخذت صيغة المثالية نحو الصيف ضيعت اللبن ، ولذا يؤتى بها على لفظها وقد تقدم أن كلمة « كن » تعبر عن الإرادة الأزلية لا أن في اللفظ خصوصية."},{"text":"ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلْمُمْتَرِينَ","tafsir":""},{"text":"فَمَنْ حَآجَّكَ فِيهِ مِنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ فَقُلْ تَعَالَوْا۟ نَدْعُ أَبْنَآءَنَا وَأَبْنَآءَكُمْ وَنِسَآءَنَا وَنِسَآءَكُمْ وَأَنفُسَنَا وَأَنفُسَكُمْ ثُمَّ نَبْتَهِلْ فَنَجْعَل لَّعْنَتَ ٱللَّهِ عَلَى ٱلْكَـٰذِبِينَ","tafsir":"يا رسول الله أي أن قصة عيسى هكذا أو خلقه كذلك حق من ربك ( فَلا تَكُنْ مِنَ الْمُمْتَرِينَ ) أي من الشاكين فإن امترى بمعنى شك والخطاب وإن كان للرسول لكنه عام لكل أحد ، ومن المعلوم أن توجيه الخطاب لا يلازم احتمال وجود الصفة ، وإنما أكد البيان بجملة « فلا تكن » لكثرة الشك والتشكيك لدى الناس في مختلف شؤون عيسى عليه‌السلام ."},{"text":"إِنَّ هَـٰذَا لَهُوَ ٱلْقَصَصُ ٱلْحَقُّ ۚ وَمَا مِنْ إِلَـٰهٍ إِلَّا ٱللَّهُ ۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ","tafsir":"وجادلك يا رسول الله ( فِيهِ ) أي في عيسى قائلا أنه ليس بشرا وإنما هو رب انفصل عن الرب ، ونزلت الآية في وفد نجران من المسيحيين الذين جاءوا للمجادلة مع الرسول صلى‌الله‌عليه‌وآله‌وسلم ولم تنفعهم الحجة والدليل فقرر الطرفان أن يخرجوا إلى الصحراء ليدعو مِنْ بَعْدِ ما جاءَكَ مِنَ الْعِلْمِ فَقُلْ تَعالَوْا نَدْعُ أَبْناءَنا وَأَبْناءَكُمْ وَنِساءَنا وَنِساءَكُمْ وَأَنْفُسَنا وَأَنْفُسَكُمْ ثُمَّ نَبْتَهِلْ فَنَجْعَلْ لَعْنَتَ اللهِ عَلَى الْكاذِبِينَ (61) إِنَّ هذا لَهُوَ الْقَصَصُ كل من الطرفين على الكاذب فخرج الرسول صلى‌الله‌عليه‌وآله‌وسلم يوم الموعد مع علي وفاطمة والحسن والحسين عليهم‌السلام فلما رأتهم النصارى أحجموا وقال كبيرهم : إني لأرى وجوها لو سألوا الله أن يزيل جبلا من مكانه لأزاله فلا تبتهلوا فتهلكوا ولا يبقى على وجه الأرض نصراني إلى يوم القيامة و قال الرسول صلى‌الله‌عليه‌وآله‌وسلم : والذي نفسي بيده لو لاعنوني لمسخوا قردة وخنازير ولاضطرم الوادي عليهم نارا ، ولما حال الحول على النصارى حتى يهلكوا ( مِنْ بَعْدِ ما جاءَكَ مِنَ الْعِلْمِ ) حول قصة عيسى عليه‌السلام ( فَقُلْ ) لهم يا رسول الله ( تَعالَوْا ) أي هلموا إلى حجة أخرى ليست محل نقاش وجدال ( نَدْعُ ) أي يدعو كل طائفة منا ( أَبْناءَنا وَأَبْناءَكُمْ وَنِساءَنا وَنِساءَكُمْ وَأَنْفُسَنا ) أي من هو بمنزلة أنفسنا ( وَأَنْفُسَكُمْ ) أي من هو بمنزلة أنفسكم ، والمراد دعوة كل طرف خواصه ومن يقترب إليه من الأبناء والنساء ومن هو بمنزلة نفسه ( ثُمَّ نَبْتَهِلْ ) الابتهال طلب اللعنة من الله سبحانه أي تدعو كل طائفة على الأخرى قائلين : لعن الكاذب ، وقد يستعمل الابتهال بمعنى مطلق الدعاء خيرا كان أو شرا ( فَنَجْعَلْ ) في ابتهالنا ( لَعْنَتَ اللهِ عَلَى الْكاذِبِينَ ) وقد أجمع المفسرون أن الرسول صلى‌الله‌عليه‌وآله‌وسلم لم يخرج معه إلا ابنيه الحسن والحسين وبنته فاطمة وابن عمه عليا عليهم‌السلام ."},{"text":"فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ عَلِيمٌۢ بِٱلْمُفْسِدِينَ","tafsir":"الذي أوحينا إليك في أمر عيسى وغيره ( لَهُوَ الْقَصَصُ ) الْحَقُّ وَما مِنْ إِلهٍ إِلاَّ اللهُ وَإِنَّ اللهَ لَهُوَ الْعَزِيزُ الْحَكِيمُ (62) فَإِنْ تَوَلَّوْا فَإِنَّ اللهَ عَلِيمٌ بِالْمُفْسِدِينَ (63) قُلْ يا أَهْلَ الْكِتابِ تَعالَوْا إِلى كَلِمَةٍ سَواءٍ بَيْنَنا وَبَيْنَكُمْ أَلاَّ نَعْبُدَ إِلاَّ اللهَ وَلا نُشْرِكَ بِهِ شَيْئاً وَلا يَتَّخِذَ بَعْضُنا بَعْضاً أَرْباباً مِنْ دُونِ اللهِ جمع قصة ( الْحَقُ ) الذي لا كذب فيه ولا زيغ ( وَما مِنْ إِلهٍ إِلَّا اللهُ ) فليس عيسى إلها كما يزعم النصارى ( وَإِنَّ اللهَ لَهُوَ الْعَزِيزُ ) في سلطانه ( الْحَكِيمُ ) في أفعاله فلا يتخذ البشر ابنا له كما يقول اليهود والنصارى."},{"text":"قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ تَعَالَوْا۟ إِلَىٰ كَلِمَةٍ سَوَآءٍۭ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا ٱللَّهَ وَلَا نُشْرِكَ بِهِۦ شَيْـًٔا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِّن دُونِ ٱللَّهِ ۚ فَإِن تَوَلَّوْا۟ فَقُولُوا۟ ٱشْهَدُوا۟ بِأَنَّا مُسْلِمُونَ","tafsir":"وأعرضوا مصرين على عقائدهم الفاسدة ( فَإِنَّ اللهَ عَلِيمٌ بِالْمُفْسِدِينَ ) الذين يفسدون عقائد الناس وأعمالهم فإنهم لا يفوتونه سبحانه بل هم بعلمه وسيجازيهم بأعمالهم وأفعالهم. [65] وحيث انتهى السياق من قصص عيسى عليه‌السلام تناول الحديث حول أهل الكتاب وانحرافاتهم للعلاقة الوثيقة بين الموضوعين فقال سبحانه ( قُلْ ) يا رسول الله ( يا أَهْلَ الْكِتابِ ) والمراد بهم اليهود والنصارى ( تَعالَوْا ) أي هلموا نجتمع جميعا ( إِلى كَلِمَةٍ سَواءٍ بَيْنَنا وَبَيْنَكُمْ ) أي إلى كلام عدل لا ميل له ونحن جميعا نعترف به وندع ما سوى ذلك ما لم يدل عليه دليل ( أَلَّا نَعْبُدَ إِلَّا اللهَ ) فإن العبادة لا تجوز إلا له إذ هو الذي خلق الكون ( وَلا نُشْرِكَ بِهِ شَيْئاً ) من إنسان أو حيوان أو جماد كما يصفه المشركون ( وَلا يَتَّخِذَ بَعْضُنا بَعْضاً ) أي بعض البشر ( أَرْباباً ) وآلهة ( مِنْ دُونِ اللهِ ) كاتخاذ النصارى المسيح إلها أو المراد فَإِنْ تَوَلَّوْا فَقُولُوا اشْهَدُوا بِأَنَّا مُسْلِمُونَ (64) يا أَهْلَ الْكِتابِ لِمَ تُحَاجُّونَ فِي إِبْراهِيمَ وَما أُنْزِلَتِ التَّوْراةُ وَالْإِنْجِيلُ إِلاَّ مِنْ بَعْدِهِ أَ فَلا تَعْقِلُونَ (65) ها أَنْتُمْ هؤُلاءِ حاجَجْتُمْ فِيما لَكُمْ بِهِ عِلْمٌ اتخاذ الأحبار والرهبان آلهة في الإطاعة فيما خالف الله سبحانه كما قال : ( اتَّخَذُوا أَحْبارَهُمْ وَرُهْبانَهُمْ أَرْباباً ) (1) ( فَإِنْ تَوَلَّوْا ) أي أعرضوا عن ذلك ( فَقُولُوا ) لهم ( اشْهَدُوا بِأَنَّا مُسْلِمُونَ ) لله وحده نتبع طريقه ولا نبتغي غير الإسلام دينا. [66] وقد كان أهل الكتاب يقولون أن إبراهيم كان على ديننا فاليهود منهم كانوا يقولون أنه عليه‌السلام كان يهوديا والنصارى منهم كانوا يقولون أنه عليه‌السلام كان مسيحيا فقال سبحانه في ردهم ( يا أَهْلَ الْكِتابِ لِمَ ) أي لماذا ( تُحَاجُّونَ ) وتجادلون ( فِي إِبْراهِيمَ ) عليه‌السلام وتنسبوه إلى اليهودية والنصرانية ( وَ ) الحال أنه متقدم زمانا على كلا الدينين ، فإبراهيم جد موسى وعيسى وهو سابق عليهما بقرون فإنه ( ما أُنْزِلَتِ التَّوْراةُ ) على موسى ( وَالْإِنْجِيلُ ) على عيسى ( إِلَّا مِنْ بَعْدِهِ ) أي بعد إبراهيم ( أَ فَلا تَعْقِلُونَ ) أ ليس لكم عقل حتى تعرفون التاريخ."},{"text":"يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لِمَ تُحَآجُّونَ فِىٓ إِبْرَٰهِيمَ وَمَآ أُنزِلَتِ ٱلتَّوْرَىٰةُ وَٱلْإِنجِيلُ إِلَّا مِنۢ بَعْدِهِۦٓ ۚ أَفَلَا تَعْقِلُونَ","tafsir":""},{"text":"هَـٰٓأَنتُمْ هَـٰٓؤُلَآءِ حَـٰجَجْتُمْ فِيمَا لَكُم بِهِۦ عِلْمٌ فَلِمَ تُحَآجُّونَ فِيمَا لَيْسَ لَكُم بِهِۦ عِلْمٌ ۚ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ","tafsir":""},{"text":"مَا كَانَ إِبْرَٰهِيمُ يَهُودِيًّا وَلَا نَصْرَانِيًّا وَلَـٰكِن كَانَ حَنِيفًا مُّسْلِمًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ","tafsir":"تفيد التنبيه ( أَنْتُمْ هؤُلاءِ ) يا معشر أهل الكتاب ( حاجَجْتُمْ ) وجادلتم ( فِيما لَكُمْ بِهِ عِلْمٌ ) مما تعلمون كالقبلة ( 1) التوبة : 31. فَلِمَ تُحَاجُّونَ فِيما لَيْسَ لَكُمْ بِهِ عِلْمٌ وَاللهُ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ (66) ما كانَ إِبْراهِيمُ يَهُودِيًّا وَلا نَصْرانِيًّا وَلكِنْ كانَ حَنِيفاً مُسْلِماً وَما كانَ مِنَ الْمُشْرِكِينَ (67) إِنَّ أَوْلَى النَّاسِ بِإِبْراهِيمَ لَلَّذِينَ اتَّبَعُوهُ وَهذَا النَّبِيُّ وَالَّذِينَ آمَنُوا وَاللهُ وَلِيُّ ونحوها ( فَلِمَ تُحَاجُّونَ فِيما لَيْسَ لَكُمْ بِهِ عِلْمٌ ) إذ لا تعلمون تاريخ إبراهيم وتجادلون في أنه كان يهوديا أو نصرانيا ( وَاللهُ يَعْلَمُ ) تاريخ إبراهيم ودينه ( وَأَنْتُمْ لا تَعْلَمُونَ ) فما هذه المخاصمة والمجادلة."},{"text":"إِنَّ أَوْلَى ٱلنَّاسِ بِإِبْرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَـٰذَا ٱلنَّبِىُّ وَٱلَّذِينَ ءَامَنُوا۟ ۗ وَٱللَّهُ وَلِىُّ ٱلْمُؤْمِنِينَ","tafsir":"فإنهما طريقتان متأخرتان انحرفتا عن سنن الأنبياء حتى أن المسيح وموسى عليهما‌السلام لم يكونا متصفين بهاتين الملتين ( وَلكِنْ كانَ حَنِيفاً ) مستقيما في دينه لا منحرفا ( مُسْلِماً ) لما تقدم من أن الإسلام دين الأنبياء جميعا ( وَما كانَ مِنَ الْمُشْرِكِينَ ) كشرك اليهود الذين جعلوا عزير ابن الله وشرك النصارى الذين جعلوا المسيح إلها أو ابن الله. [69] كانت اليهود تقول نحن أولى بإبراهيم لأنه على ديننا وكانت النصارى تقول مثل ذلك فنزلت ( إِنَّ أَوْلَى النَّاسِ بِإِبْراهِيمَ ) الذي يحق أن يفتخر به ويقول أنا على طريقته وأنه رئيس الملة لي ( لَلَّذِينَ اتَّبَعُوهُ ) في زمانه وبعده إذ التابع يحق له أن يفتخر برئيسه ومتبوعه لا من يتبع غيره كاليهود والنصارى الذين خالفوا إبراهيم ( وَهذَا النَّبِيُّ وَالَّذِينَ آمَنُوا ) عطف على « الذين اتبعوه » فإن هذا النبي والمؤمنين هم الذين اتبعوا إبراهيم وهم على ملته فإن ملته التوحيد وخلع الأنداد ( وَاللهُ وَلِيُّ الْمُؤْمِنِينَ (68) وَدَّتْ طائِفَةٌ مِنْ أَهْلِ الْكِتابِ لَوْ يُضِلُّونَكُمْ وَما يُضِلُّونَ إِلاَّ أَنْفُسَهُمْ وَما يَشْعُرُونَ (69) يا أَهْلَ الْكِتابِ لِمَ تَكْفُرُونَ بِآياتِ اللهِ وَأَنْتُمْ تَشْهَدُونَ (70) يا أَهْلَ الْكِتابِ الْمُؤْمِنِينَ ) يلي أمورهم وينصرهم على عدوهم."},{"text":"وَدَّت طَّآئِفَةٌ مِّنْ أَهْلِ ٱلْكِتَـٰبِ لَوْ يُضِلُّونَكُمْ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ","tafsir":""},{"text":"يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لِمَ تَكْفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ وَأَنتُمْ تَشْهَدُونَ","tafsir":"أي أحبت ورغبت ( طائِفَةٌ مِنْ أَهْلِ الْكِتابِ ) أي جماعة منهم فإن كثيرا من أهل الكتاب لم يكن يعنيهم هذه الأمور ( لَوْ يُضِلُّونَكُمْ ) عن دينكم حتى تدخلوا في دينهم أو ترجعوا كفارا ( وَما يُضِلُّونَ ) هؤلاء ( إِلَّا أَنْفُسَهُمْ ) فإنهم بتركهم الإسلام والتزامهم أديانهم المنحرفة سببوا ضلالا لأنفسهم ، أو المراد أنه لا يرجع وبال إضلالهم إلا على أنفسهم حيث يوجب ذلك لهم خزيا في الدنيا وعذابا في الآخرة ( وَما يَشْعُرُونَ ) أي ما يعلمون أنهم أضلوا أنفسهم أو ما شعروا بأنه رجع وبال إضلالهم إلى أنفسهم."},{"text":"يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لِمَ تَلْبِسُونَ ٱلْحَقَّ بِٱلْبَـٰطِلِ وَتَكْتُمُونَ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ","tafsir":"هم اليهود والنصارى ، والمجوس وإن كانوا أهل الكتاب إلا أن هذه المباحثات كانت مع الطائفتين فقط كما يستفاد من سياق الآيات ( لِمَ ) أي لماذا ( تَكْفُرُونَ بِآياتِ اللهِ ) بدلائله وحججه التي أقامها على التوحيد والرسالة وسائر الأمور ( وَأَنْتُمْ تَشْهَدُونَ ) بلزوم الإقرار بها شهادة فيما بينكم ، أو شهادة حسب كتبكم الدالة على التوحيد ورسالة محمد صلى‌الله‌عليه‌وآله‌وسلم وسائر الأمور المختلف فيها."},{"text":"وَقَالَت طَّآئِفَةٌ مِّنْ أَهْلِ ٱلْكِتَـٰبِ ءَامِنُوا۟ بِٱلَّذِىٓ أُنزِلَ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَجْهَ ٱلنَّهَارِ وَٱكْفُرُوٓا۟ ءَاخِرَهُۥ لَعَلَّهُمْ يَرْجِعُونَ","tafsir":"وخطابهم بهذا الخطاب إشعار بأنهم ينبغي أن لِمَ تَلْبِسُونَ الْحَقَّ بِالْباطِلِ وَتَكْتُمُونَ الْحَقَّ وَأَنْتُمْ تَعْلَمُونَ (71) وَقالَتْ طائِفَةٌ مِنْ أَهْلِ الْكِتابِ آمِنُوا بِالَّذِي أُنْزِلَ عَلَى الَّذِينَ آمَنُوا وَجْهَ النَّهارِ وَاكْفُرُوا آخِرَهُ لَعَلَّهُمْ يَرْجِعُونَ (72) لا يكونوا كذلك إذ هم أهل العلم والدراية وفيهم نزل كتاب الله سبحانه ( لِمَ ) أي لماذا ( تَلْبِسُونَ الْحَقَّ بِالْباطِلِ ) أي تخلطون الحق بالباطل ففي أعمالكم قسم من الحق وقسم من الباطل فالإيمان بموسى وعيسى حق والكفر بمحمد صلى‌الله‌عليه‌وآله‌وسلم باطل وهكذا بعض كتابهم حق وبعضه الذي حرفوه باطل ( وَتَكْتُمُونَ الْحَقَّ وَأَنْتُمْ تَعْلَمُونَ ) أي تعلمون أنه حق فقد كان علماؤهم يكتمون صفات الرسول صلى‌الله‌عليه‌وآله‌وسلم حتى لا يميلوا نحوه وتذهب رئاستهم. [73] وقد صدرت مكيدة من أهل الكتاب لتضليل الناس وأن لا يتعلقوا بدين الإسلام ، حيث يظهرون عملا يصورهم عند الناس في صورة المنصف وأنهم إنما لم يتبعوا الإسلام لأنهم لم يجدوه حقا ( وَقالَتْ طائِفَةٌ ) أي جماعة ( مِنْ أَهْلِ الْكِتابِ ) بعضهم لبعض ( آمِنُوا ) أي أظهروا الإيمان ( بِالَّذِي أُنْزِلَ عَلَى الَّذِينَ آمَنُوا ) أي بالقرآن ( وَجْهَ النَّهارِ ) أي أول الصبح ، فقولوا إنا آمنا بمحمد وكتابه لأنا وجدناه في كتبنا ( وَاكْفُرُوا آخِرَهُ ) أي آخر النهار فقولوا بعد أن آمنا رجعنا إلى صفات محمد ثانيا فوجدناها ليست كما ذكر في كتابنا ، فإن هذا العمل يريكم في أعين الناس منصفين حيث آمنتم بمحمد بمجرد علمكم بحقيقته ، وإنما رجعتم حيث ظهر لكم عدم الحقيقة ، فتوهمون الناس أنكم منصفون صادقون تريدون الحق ( لَعَلَّهُمْ يَرْجِعُونَ ) أي لعل هذا وَلا تُؤْمِنُوا إِلاَّ لِمَنْ تَبِعَ دِينَكُمْ قُلْ إِنَّ الْهُدى هُدَى اللهِ أَنْ يُؤْتى أَحَدٌ مِثْلَ ما أُوتِيتُمْ أَوْ يُحاجُّوكُمْ عِنْدَ رَبِّكُمْ قُلْ إِنَّ الْفَضْلَ بِيَدِ اللهِ يُؤْتِيهِ مَنْ يَشاءُ وَاللهُ واسِعٌ عَلِيمٌ (73) العمل الخداعي يسبب رجوع المسلمين عن إسلامهم حيث يوجب ذلك تشكيكا لهم."},{"text":"وَلَا تُؤْمِنُوٓا۟ إِلَّا لِمَن تَبِعَ دِينَكُمْ قُلْ إِنَّ ٱلْهُدَىٰ هُدَى ٱللَّهِ أَن يُؤْتَىٰٓ أَحَدٌ مِّثْلَ مَآ أُوتِيتُمْ أَوْ يُحَآجُّوكُمْ عِندَ رَبِّكُمْ ۗ قُلْ إِنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ","tafsir":""},{"text":"يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ ۗ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ","tafsir":"أي لا تظهروا الإيمان ( إِلَّا لِمَنْ تَبِعَ دِينَكُمْ ) فإيمانكم وجه النهار يكون عند أهل الكتاب لا عند المسلمين ، أو لا تؤمنوا إيمانا صادقا من قلوبكم إلا لأهل الكتاب ، فلا تؤمنوا للمسلمين ، ومعنى الإيمان لمن تبع دينهم أنهم يؤمنون بمثل ما آمن أهل الكتاب ( قُلْ ) لهم يا رسول الله ( إِنَّ الْهُدى ) الحقيقي ( هُدَى اللهِ ) لا هذا الهدى الاصطناعي الذين تريدون به خداع أصحابكم والمسلمين فلسنا في حاجة إلى هداكم كما لا نخاف من إضلالكم فإن الله إذا هدى شخصا لا يرجع بخداعكم ، ثم يرجع السياق إلى كلام اليهود بعضهم لبعض ، ولا تؤمنوا ( أَنْ يُؤْتى أَحَدٌ مِثْلَ ما أُوتِيتُمْ ) فإنما أوتيتم أيها اليهود هو خير مما أوتي غيركم فلا يكن إيمانكم بمحمد صلى‌الله‌عليه‌وآله‌وسلم إيمانا عن قلب أو صدق ( أَوْ يُحاجُّوكُمْ عِنْدَ رَبِّكُمْ ) أي لا تؤمنوا أن يحاجكم المسلمون عند ربكم بمعنى أنه لا يمكن أن يكون ذلك إذ المحاجة لا تكون من المبطل ـ والمسلم مبطل بزعمهم ـ ( قُلْ ) يا رسول الله ردا على قولهم ( أَنْ يُؤْتى أَحَدٌ مِثْلَ ما أُوتِيتُمْ ) ( إِنَّ الْفَضْلَ بِيَدِ اللهِ ) فأي مانع من أن يعطي المسلمين مثل ما أعطى اليهود وأفضل منه ( يُؤْتِيهِ مَنْ يَشاءُ وَاللهُ واسِعٌ ) الفضل لا ينفد فضله بإعطائه لأحد ( عَلِيمٌ ) بمصالح الخلق يَخْتَصُّ بِرَحْمَتِهِ مَنْ يَشاءُ وَاللهُ ذُو الْفَضْلِ الْعَظِيمِ (74) وَمِنْ أَهْلِ الْكِتابِ مَنْ إِنْ تَأْمَنْهُ بِقِنْطارٍ يُؤَدِّهِ إِلَيْكَ وَمِنْهُمْ مَنْ إِنْ تَأْمَنْهُ بِدِينارٍ لا يُؤَدِّهِ إِلَيْكَ إِلاَّ ما دُمْتَ عَلَيْهِ قائِماً ذلِكَ بِأَنَّهُمْ قالُوا لَيْسَ عَلَيْنا فِي الْأُمِّيِّينَ سَبِيلٌ يعلم حيث يجعل رسالته."},{"text":"۞ وَمِنْ أَهْلِ ٱلْكِتَـٰبِ مَنْ إِن تَأْمَنْهُ بِقِنطَارٍ يُؤَدِّهِۦٓ إِلَيْكَ وَمِنْهُم مَّنْ إِن تَأْمَنْهُ بِدِينَارٍ لَّا يُؤَدِّهِۦٓ إِلَيْكَ إِلَّا مَا دُمْتَ عَلَيْهِ قَآئِمًا ۗ ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَيْسَ عَلَيْنَا فِى ٱلْأُمِّيِّـۧنَ سَبِيلٌ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ","tafsir":"من عباده ( وَاللهُ ذُو الْفَضْلِ الْعَظِيمِ ) فإن فضله يبتدئ بالخلق وينتهي إلى حيث لا قابلية فوقه. [76] وقد جمع بعض أهل الكتاب إلى تلك الرذائل السابقة رذيلة الخيانة ( وَمِنْ أَهْلِ الْكِتابِ ) أي بعض أهل الكتاب ـ والمراد به من آمن منهم كعبد الله بن سلام ـ ( مَنْ إِنْ تَأْمَنْهُ بِقِنْطارٍ يُؤَدِّهِ إِلَيْكَ ) أي تجعله أمينا على قنطار من مال لا يخونه بل يؤديه إليك عند المطالبة ، وقد ورد أن عبد الله بن سلام أودعه رجل ألفا ومائتي أوقية من ذهب فأداه إليه فمدحه الله بهذه الآية ( وَمِنْهُمْ مَنْ إِنْ تَأْمَنْهُ بِدِينارٍ ) أي تجعله أمينا على مال قليل كدينار ( لا يُؤَدِّهِ إِلَيْكَ ) عند المطالبة فإن رجلا من قريش استودع « فخاص » دينارا فخانه ولم يرده إليه ( إِلَّا ما دُمْتَ عَلَيْهِ قائِماً ) بالضغط والإلحاح والمراقبة ( ذلِكَ ) الاستحلال والخيانة منهم لأموال الناس بسبب أنهم أي الخائن من أهل الكتاب ( قالُوا لَيْسَ عَلَيْنا فِي الْأُمِّيِّينَ سَبِيلٌ ) أي لا سبيل ولا غضاضة علينا في استحلالنا أموال الأميين أي العرب حيث أنهم خرجوا عن دينهم أي غير الشرك وقد أودعونا حال شركهم فإذا رفضوا طريقتهم إلى الإسلام سقط وَيَقُولُونَ عَلَى اللهِ الْكَذِبَ وَهُمْ يَعْلَمُونَ (75) بَلى مَنْ أَوْفى بِعَهْدِهِ وَاتَّقى فَإِنَّ اللهَ يُحِبُّ الْمُتَّقِينَ (76) إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللهِ وَأَيْمانِهِمْ ثَمَناً قَلِيلاً أُولئِكَ لا خَلاقَ لَهُمْ فِي الْآخِرَةِ وَلا يُكَلِّمُهُمُ اللهُ وَلا يَنْظُرُ إِلَيْهِمْ حقهم كذا كانوا يقولون وينسبونه إلى كتبهم ( وَيَقُولُونَ عَلَى اللهِ الْكَذِبَ ) فإنه ليس ذلك في كتبهم ، بل اللازم أداء الأمانة إلى البر والفاجر ( وَهُمْ يَعْلَمُونَ ) أنهم يكذبون على الله وأن عدم الأداء خيانة ورذيلة."},{"text":"بَلَىٰ مَنْ أَوْفَىٰ بِعَهْدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ","tafsir":""},{"text":"إِنَّ ٱلَّذِينَ يَشْتَرُونَ بِعَهْدِ ٱللَّهِ وَأَيْمَـٰنِهِمْ ثَمَنًا قَلِيلًا أُو۟لَـٰٓئِكَ لَا خَلَـٰقَ لَهُمْ فِى ٱلْـَٔاخِرَةِ وَلَا يُكَلِّمُهُمُ ٱللَّهُ وَلَا يَنظُرُ إِلَيْهِمْ يَوْمَ ٱلْقِيَـٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ","tafsir":"فيه نفي لما قبله وإثبات لما بعده أي لم يجز الله الخيانة بل أوجب الأداء ف ( مَنْ أَوْفى بِعَهْدِهِ ) وأدى الأمانة التي عنده ( وَاتَّقى ) من عذاب الله في الخيانة وغيرها ( فَإِنَّ اللهَ يُحِبُّ الْمُتَّقِينَ ) لا الخائنين الكاذبين."},{"text":"وَإِنَّ مِنْهُمْ لَفَرِيقًا يَلْوُۥنَ أَلْسِنَتَهُم بِٱلْكِتَـٰبِ لِتَحْسَبُوهُ مِنَ ٱلْكِتَـٰبِ وَمَا هُوَ مِنَ ٱلْكِتَـٰبِ وَيَقُولُونَ هُوَ مِنْ عِندِ ٱللَّهِ وَمَا هُوَ مِنْ عِندِ ٱللَّهِ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ","tafsir":"من يأكل الأمانة ويكذب على الله فقد باع دينه بثمن قليل و ( الَّذِينَ يَشْتَرُونَ ) بمقابل عهد ( اللهِ ) الذي هو الكتاب والدين ( وَ ) ب ( أَيْمانِهِمْ ) أي أقسامهم الكاذبة التي يحلفون بها لأجل الباطل ( ثَمَناً قَلِيلاً ) وقد تقدم أن الأمور الدنيوية مهما عظمت فإنها قليلة بالنسبة إلى الآخرة ( أُولئِكَ لا خَلاقَ لَهُمْ فِي الْآخِرَةِ ) أي لا نصيب لهم من رحمة الله وجنته في الآخرة ( وَلا يُكَلِّمُهُمُ اللهُ ) كلام لطف وحنان وهو كناية عن غضب الله عليهم كما أن من غضب على شخص لا يكلمه ( وَلا يَنْظُرُ إِلَيْهِمْ ) أي لا يعمهم بلطفه وإحسانه وهو كناية أخرى عن يَوْمَ الْقِيامَةِ وَلا يُزَكِّيهِمْ وَلَهُمْ عَذابٌ أَلِيمٌ (77) وَإِنَّ مِنْهُمْ لَفَرِيقاً يَلْوُونَ أَلْسِنَتَهُمْ بِالْكِتابِ لِتَحْسَبُوهُ مِنَ الْكِتابِ وَما هُوَ مِنَ الْكِتابِ وَيَقُولُونَ هُوَ مِنْ عِنْدِ اللهِ وَما هُوَ مِنْ عِنْدِ اللهِ وَيَقُولُونَ عَلَى اللهِ الْكَذِبَ وَهُمْ يَعْلَمُونَ (78) الغضب كالذي يغضب على شخص فلا ينظر إليه ( يَوْمَ الْقِيامَةِ ) ذلك اليوم الذي يحتاج كل أحد إلى فضله وإحسانه تعالى ( وَلا يُزَكِّيهِمْ ) أي لا يطهرهم من الدنس فإن قلب الخائن الكاذب أقذر ما يكون فلا يشمله الله سبحانه بلطفه الخاص الذي يلطف به على المؤمنين ( وَلَهُمْ عَذابٌ أَلِيمٌ ) أي مؤلم موجع."},{"text":"مَا كَانَ لِبَشَرٍ أَن يُؤْتِيَهُ ٱللَّهُ ٱلْكِتَـٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُوا۟ عِبَادًا لِّى مِن دُونِ ٱللَّهِ وَلَـٰكِن كُونُوا۟ رَبَّـٰنِيِّـۧنَ بِمَا كُنتُمْ تُعَلِّمُونَ ٱلْكِتَـٰبَ وَبِمَا كُنتُمْ تَدْرُسُونَ","tafsir":"أي بعض أهل الكتاب ( لَفَرِيقاً ) أي جماعة ( يَلْوُونَ أَلْسِنَتَهُمْ بِالْكِتابِ ) أي يطوون ألسنتهم عند قراءة الكتابة وطي لسانهم إنما هو بالزيادة والنقيصة فكما أن ليّ الشيء يخرجه عن الاستقامة بالزيادة في جانب والنقيصة في جانب كذلك ليّ اللسان بالكتاب ، فإنهم أضافوا على التوراة والإنجيل في مواضع ونقصوا منهما في مواضع ( لِتَحْسَبُوهُ ) أيها المسلمون ( مِنَ الْكِتابِ ) فيكون شاهدا لأباطيلهم المخترعة ( وَما هُوَ مِنَ الْكِتابِ ) بل من إضافاتهم وتحريفاتهم ( وَيَقُولُونَ هُوَ ) ما يتلونه باسم الكتاب ( مِنْ عِنْدِ اللهِ ) تعالى ( وَما هُوَ مِنْ عِنْدِ اللهِ ) بل من مخترعاتهم الكاذبة ( وَيَقُولُونَ عَلَى اللهِ الْكَذِبَ ) في نسبتهم ذلك التحريف إليه سبحانه ( وَهُمْ يَعْلَمُونَ ) أنه ليس من الكتاب وأنهم كاذبون. ما كانَ لِبَشَرٍ أَنْ يُؤْتِيَهُ اللهُ الْكِتابَ وَالْحُكْمَ وَالنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُوا عِباداً لِي مِنْ دُونِ اللهِ وَلكِنْ كُونُوا رَبَّانِيِّينَ بِما كُنْتُمْ تُعَلِّمُونَ الْكِتابَ وَبِما كُنْتُمْ تَدْرُسُونَ (79) [80] وحيث أنه كان من أظهر تلك التحريفات تحريفهم حول المسيح عليه‌السلام وادعائهم أنه شريك مع الله وأن ذلك موجود في كتابهم ، ردهم الله سبحانه بأن ذلك مستحيل في حق المسيح ، لأن الله سبحانه لا يعطي النبوة لرجل كاذب يدعي لنفسه الربوبية فإنه ( ما كانَ لِبَشَرٍ أَنْ يُؤْتِيَهُ اللهُ ) أي يعطيه ( الْكِتابَ وَالْحُكْمَ ) بين الناس ( وَالنُّبُوَّةَ ) والرسالة ( ثُمَّ يَقُولَ لِلنَّاسِ كُونُوا عِباداً لِي مِنْ دُونِ اللهِ ) أي اعبدوني دونه سبحانه ، أو المراد اعبدوني معه ، فإن عبادة الشريك عبادة لمن دون الله ، ولأن الشرك معناه عدم عبادة الله إطلاقا إذ الله لا شريك له ، فمن له شريك ليس هو بإله ، وفي بعض التفاسير أن سبب نزول هذه الآية أن يهوديا سأل النبي صلى‌الله‌عليه‌وآله‌وسلم ذلك ونزلت الآية ( وَلكِنْ ) اللازم على الرسول أن يقول للناس ( كُونُوا رَبَّانِيِّينَ ) منسوبين إلى الرب ترشدون الناس إلى التوحيد وتعبدون إلها واحدا بسبب ما ( كُنْتُمْ ) أي كونكم ( تُعَلِّمُونَ ) للناس ( الْكِتابَ ) الذي أخذتموه من نبيكم ( وَبِما كُنْتُمْ تَدْرُسُونَ ) أي بسبب درسكم إياه يعني أن الرسول يقول للناس إنكم بسبب كونكم علماء معلمين مدرسين يجب أن تكونوا ربانيين منسوبين إلى الرب فقط لا إلى غيره من الأنداد والشركاء. وَلا يَأْمُرَكُمْ أَنْ تَتَّخِذُوا الْمَلائِكَةَ وَالنَّبِيِّينَ أَرْباباً أَ يَأْمُرُكُمْ بِالْكُفْرِ بَعْدَ إِذْ أَنْتُمْ مُسْلِمُونَ (80) وَإِذْ أَخَذَ اللهُ مِيثاقَ النَّبِيِّينَ لَما آتَيْتُكُمْ مِنْ كِتابٍ وَحِكْمَةٍ ثُمَّ جاءَكُمْ رَسُولٌ مُصَدِّقٌ لِما مَعَكُمْ لَتُؤْمِنُنَّ بِهِ"},{"text":"وَلَا يَأْمُرَكُمْ أَن تَتَّخِذُوا۟ ٱلْمَلَـٰٓئِكَةَ وَٱلنَّبِيِّـۧنَ أَرْبَابًا ۗ أَيَأْمُرُكُم بِٱلْكُفْرِ بَعْدَ إِذْ أَنتُم مُّسْلِمُونَ","tafsir":""},{"text":"وَإِذْ أَخَذَ ٱللَّهُ مِيثَـٰقَ ٱلنَّبِيِّـۧنَ لَمَآ ءَاتَيْتُكُم مِّن كِتَـٰبٍ وَحِكْمَةٍ ثُمَّ جَآءَكُمْ رَسُولٌ مُّصَدِّقٌ لِّمَا مَعَكُمْ لَتُؤْمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥ ۚ قَالَ ءَأَقْرَرْتُمْ وَأَخَذْتُمْ عَلَىٰ ذَٰلِكُمْ إِصْرِى ۖ قَالُوٓا۟ أَقْرَرْنَا ۚ قَالَ فَٱشْهَدُوا۟ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّـٰهِدِينَ","tafsir":"يكون للنبي أن ( يَأْمُرَكُمْ ) عطف على ( ما كانَ لِبَشَرٍ أَنْ يُؤْتِيَهُ اللهُ ) ( أَنْ تَتَّخِذُوا الْمَلائِكَةَ وَالنَّبِيِّينَ أَرْباباً ) فإن ذلك محال إذ من يختاره الله للرسالة لا يأمر بالكفر ( أَ يَأْمُرُكُمْ ) أي هل يأمركم النبي ( بِالْكُفْرِ بَعْدَ إِذْ أَنْتُمْ مُسْلِمُونَ ) أسلمتم بإيمانكم بالنبي ، وهذا استفهام إنكاري أي لا يكون ذلك أبدا فقد أخرجكم النبي من الكفر إلى الإسلام فكيف يأمركم بالكفر ثانيا بأن تتخذوه شريكا لله. [82] وإذ تم الكلام حول عيسى وأنه ليس بشريك لله سبحانه رجع السياق إلى نبي الإسلام وأنه النبي بعد عيسى عليه‌السلام ، ( وَ ) اذكر يا رسول الله ( إِذْ أَخَذَ اللهُ مِيثاقَ النَّبِيِّينَ ) عهدهم المؤكد ( لَما آتَيْتُكُمْ مِنْ كِتابٍ وَحِكْمَةٍ ) « ما » بمعنى « مهما » أي أخذ الله عهد النبيين أنه مهما أعطاه الله الكتاب والحكمة والرسالة ( ثُمَّ جاءَكُمْ رَسُولٌ مُصَدِّقٌ لِما مَعَكُمْ ) يراد به نبي الإسلام ، أو كل نبي يأتي بعدهم ( لَتُؤْمِنُنَّ بِهِ ) هذا جواب « مهما » فالله سبحانه كان يأخذ من النبيين الميثاق أنه مهما أعطى أحدهم الرسالة فإن عليه أن يؤمن برسول الإسلام ، أو عليه أن يؤمن بالرسول الذي يتلوه وأن يناصره ويعاضده ، وفي الوجه الأول إفادة أن الأنبياء جميعا أقروا بالرسول صلى‌الله‌عليه‌وآله‌وسلم ، واعترفوا به وآمنوا به وفي الوجه الثاني إفادة أن كل رسول كان يؤمن بالرسول الذي يأتي وَلَتَنْصُرُنَّهُ قالَ أَ أَقْرَرْتُمْ وَأَخَذْتُمْ عَلى ذلِكُمْ إِصْرِي قالُوا أَقْرَرْنا قالَ فَاشْهَدُوا وَأَنَا مَعَكُمْ مِنَ الشَّاهِدِينَ (81) فَمَنْ تَوَلَّى بَعْدَ ذلِكَ فَأُولئِكَ هُمُ الْفاسِقُونَ (82) من بعده حتى أن الأنبياء كلهم كسلسلة واحدة يؤمن سابقهم بلاحقهم ويصدق لاحقهم سابقهم ( وَلَتَنْصُرُنَّهُ ) ومعنى نصرة النبي السابق للاحق أن يأخذ له العهد من أمته ( قالَ ) الله تأكيدا لأخذ الميثاق ( أَ أَقْرَرْتُمْ ) أي هل أقررتم أيها الأنبياء باستعدادكم للإيمان بالرسول ونصرته ( وَأَخَذْتُمْ عَلى ذلِكُمْ ) الإيمان بالرسول ونصرته ( إِصْرِي ) أي عهدي الأكيد من أممكم حتى يؤمنوا بالرسول وينصروه ( قالُوا ) أي قالت الأنبياء في جواب الله سبحانه ( أَقْرَرْنا ) بذلك وأخذنا الأمر ( قالَ ) الله سبحانه لهم ( فَاشْهَدُوا ) بذلك على أممكم أي كونوا شهداء عليهم حتى نحتج على المخالف يوم القيامة بشهادتكم ( وَأَنَا مَعَكُمْ مِنَ الشَّاهِدِينَ ) فإني أيضا شهيد عليهم بأنهم أقروا بأن يؤمنوا بالرسول وينصروه ، و قد روي عن الإمام أمير المؤمنين عليه‌السلام أنه لم يبعث الله نبيا آدم ومن بعده إلا أخذ عليه العهد بالإيمان بمحمد صلى‌الله‌عليه‌وآله‌وسلم وأمره بأخذ العهد بذلك من أمته (1) ."},{"text":"فَمَن تَوَلَّىٰ بَعْدَ ذَٰلِكَ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْفَـٰسِقُونَ","tafsir":""},{"text":"أَفَغَيْرَ دِينِ ٱللَّهِ يَبْغُونَ وَلَهُۥٓ أَسْلَمَ مَن فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ طَوْعًا وَكَرْهًا وَإِلَيْهِ يُرْجَعُونَ","tafsir":"وأعرض عن الإيمان والنصرة ( بَعْدَ ذلِكَ ) العهد الذي أخذه نبيه منه ( فَأُولئِكَ هُمُ الْفاسِقُونَ ) الخارجون عن إطاعة الله سبحانه حيث نقضوا العهد وخالفوا الوعد. ( 1) بحار الأنوار : ج 11 ص 13. أَ فَغَيْرَ دِينِ اللهِ يَبْغُونَ وَلَهُ أَسْلَمَ مَنْ فِي السَّماواتِ وَالْأَرْضِ طَوْعاً وَكَرْهاً وَإِلَيْهِ يُرْجَعُونَ (83) قُلْ آمَنَّا بِاللهِ وَما أُنْزِلَ عَلَيْنا وَما أُنْزِلَ عَلى إِبْراهِيمَ وَإِسْماعِيلَ وَإِسْحاقَ وَيَعْقُوبَ وَالْأَسْباطِ [84] إن عدم الإيمان بمحمد صلى‌الله‌عليه‌وآله‌وسلم خلاف عهدهم أولا وخلاف الواجب عليهم ثانيا ( أَ فَغَيْرَ دِينِ اللهِ يَبْغُونَ ) أي يطلبون ويريدون غير دين الله ودين الإسلام الذي ثبت بالآيات والحجج ( وَلَهُ ) أي لله ( أَسْلَمَ مَنْ فِي السَّماواتِ وَالْأَرْضِ ) فكل شيء في الكون خاضع له سبحانه منقاد لأمره فما بال هؤلاء يخالفون دين الله الذي أذعن له كل الكون ( طَوْعاً وَكَرْهاً ) فإن ذوي العقول من الملائكة ونحوه أسلم لله طوعا والجمادات أسلمت كرها بمعنى أنها مستمرة حسب مشيئة الله سبحانه ( وَإِلَيْهِ يُرْجَعُونَ ) أي إلى حكمه وأمره وثوابه وعقابه يرجعون عند الموت أو في القيامة. [85] هنا يأتي دور إظهار الأمة المسلمة إيمانها بجميع الأنبياء ، فإنه مقتضى وحدة الرسالات ومقتضى ما سلف من إيمان كل سابق باللاحق وتصديق كل لاحق للسابق ( قُلْ ) يا رسول الله صيغة الإيمان التي يجب الاعتراف بها على كل أمتك ( آمَنَّا بِاللهِ ) إلها واحدا ( وَ ) ب ( ما أُنْزِلَ عَلَيْنا ) من القرآن الحكيم وسائر الأحكام ( وَ ) ب ( ما أُنْزِلَ عَلى إِبْراهِيمَ وَإِسْماعِيلَ وَإِسْحاقَ وَيَعْقُوبَ وَالْأَسْباطِ ) أولاد يعقوب الذين وَما أُوتِيَ مُوسى وَعِيسى وَالنَّبِيُّونَ مِنْ رَبِّهِمْ لا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْهُمْ وَنَحْنُ لَهُ مُسْلِمُونَ (84) وَمَنْ يَبْتَغِ غَيْرَ الْإِسْلامِ دِيناً فَلَنْ يُقْبَلَ مِنْهُ وَهُوَ فِي الْآخِرَةِ مِنَ الْخاسِرِينَ (85) كَيْفَ يَهْدِي اللهُ قَوْماً كَفَرُوا بَعْدَ إِيمانِهِمْ كانوا أنبياء ( وَ ) ب ( ما أُوتِيَ ) أي أعطي ( مُوسى ) من التوراة ( وَعِيسى ) من الإنجيل ( وَ ) بما أعطي ( النَّبِيُّونَ مِنْ ) قبل ( رَبِّهِمْ لا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْهُمْ ) أي من هؤلاء الأنبياء لا كاليهود الذين لم يؤمنوا بعيسى عليه‌السلام ومحمد صلى‌الله‌عليه‌وآله‌وسلم ولا كالنصارى الذين لم يؤمنوا بمحمد صلى‌الله‌عليه‌وآله‌وسلم ( وَنَحْنُ لَهُ ) أي لله ( مُسْلِمُونَ ) منقادون فيما أمرنا ونهانا."},{"text":"قُلْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيْنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ","tafsir":""},{"text":"وَمَن يَبْتَغِ غَيْرَ ٱلْإِسْلَـٰمِ دِينًا فَلَن يُقْبَلَ مِنْهُ وَهُوَ فِى ٱلْـَٔاخِرَةِ مِنَ ٱلْخَـٰسِرِينَ","tafsir":""},{"text":"كَيْفَ يَهْدِى ٱللَّهُ قَوْمًا كَفَرُوا۟ بَعْدَ إِيمَـٰنِهِمْ وَشَهِدُوٓا۟ أَنَّ ٱلرَّسُولَ حَقٌّ وَجَآءَهُمُ ٱلْبَيِّنَـٰتُ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ","tafsir":"يطلب ويريد ( غَيْرَ الْإِسْلامِ دِيناً ) من الأديان السماوية أو المفتعلة ( فَلَنْ يُقْبَلَ مِنْهُ ) أبدا في الدنيا بل تجري عليه أحكام الكفار ( وَهُوَ فِي الْآخِرَةِ مِنَ الْخاسِرِينَ ) الذين خسروا أنفسهم وأموالهم وأهليهم جميعا. [87] إن الذين أدركوا حقيقة وحدة الرسالات وحقيقة محمد صلى‌الله‌عليه‌وآله‌وسلم ودين الإسلام ثم أنكروا وعاندوا فقد ظلموا أنفسهم وأبعدوها عن لطف الله وهدايته فلا يلطف بهم الله لطفا خاصا ولا يهديهم بل يتركهم في ظلمات كفرهم ( كَيْفَ يَهْدِي اللهُ قَوْماً كَفَرُوا بَعْدَ إِيمانِهِمْ ) والمراد بالإيمان علمهم بحقيقة الرسول الإيمان في الظاهر ، إلا إذا أخذنا بما ورد في بعض التفاسير والروايات من أنها نزلت في رجل آمن ثم ارتد ثم ندم فأرسل إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم من يسأله عن قبول توبته فأجاب الرسول صلى‌الله‌عليه‌وآله‌وسلم وَشَهِدُوا أَنَّ الرَّسُولَ حَقٌّ وَجاءَهُمُ الْبَيِّناتُ وَاللهُ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ (86) أُولئِكَ جَزاؤُهُمْ أَنَّ عَلَيْهِمْ لَعْنَةَ اللهِ وَالْمَلائِكَةِ وَالنَّاسِ أَجْمَعِينَ (87) خالِدِينَ فِيها لا يُخَفَّفُ عَنْهُمُ الْعَذابُ وَلا هُمْ يُنْظَرُونَ (88) إِلاَّ الَّذِينَ تابُوا مِنْ بَعْدِ ذلِكَ وَأَصْلَحُوا فَإِنَّ اللهَ غَفُورٌ بالإثبات فتاب وحسن إسلامه ، ولذا استثنى في آخر الآيات ( إِلَّا الَّذِينَ تابُوا )( وَشَهِدُوا أَنَّ الرَّسُولَ حَقٌ ) شهادة واقعية وإن لم يظهروها ولم يلتزموا بلوازمها ( وَجاءَهُمُ الْبَيِّناتُ ) الأدلة الواضحة على صدق الرسول صلى‌الله‌عليه‌وآله‌وسلم وحقيقة ما جاء به ( وَاللهُ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ ) أي لا يلطف بهم اللطف الخاص الذي يلطف به بمن استقام ولم يظلم نفسه."},{"text":"أُو۟لَـٰٓئِكَ جَزَآؤُهُمْ أَنَّ عَلَيْهِمْ لَعْنَةَ ٱللَّهِ وَٱلْمَلَـٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ","tafsir":""},{"text":"خَـٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ","tafsir":"الذين كفروا بعد إيمانهم ( جَزاؤُهُمْ أَنَّ عَلَيْهِمْ لَعْنَةَ اللهِ ) بإبعادهم عن رحمته ومغفرته وثوابه ( وَالْمَلائِكَةِ وَالنَّاسِ أَجْمَعِينَ ) فإنهم يدعون عليهم بالعذاب ويلعنونهم."},{"text":"إِلَّا ٱلَّذِينَ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ","tafsir":"أي يخلدون في اللعنة والطرد أبد الآبدين ( لا يُخَفَّفُ عَنْهُمُ الْعَذابُ ) أي لا يسهل عليهم لأنهم بكفرهم استحقوا العقاب الدائم ( وَلا هُمْ يُنْظَرُونَ ) أي لا يؤخر عنهم العذاب من وقت إلى وقت ، أو لا ينظر إليهم."},{"text":"إِنَّ ٱلَّذِينَ كَفَرُوا۟ بَعْدَ إِيمَـٰنِهِمْ ثُمَّ ٱزْدَادُوا۟ كُفْرًا لَّن تُقْبَلَ تَوْبَتُهُمْ وَأُو۟لَـٰٓئِكَ هُمُ ٱلضَّآلُّونَ","tafsir":"عن كفرهم ( مِنْ بَعْدِ ذلِكَ ) الكفر بأن آمنوا ( وَأَصْلَحُوا ) في أعمالهم أي عملوا الصالحات ( فَإِنَّ اللهَ غَفُورٌ ) رَحِيمٌ (89) إِنَّ الَّذِينَ كَفَرُوا بَعْدَ إِيمانِهِمْ ثُمَّ ازْدادُوا كُفْراً لَنْ تُقْبَلَ تَوْبَتُهُمْ وَأُولئِكَ هُمُ الضَّالُّونَ (90) إِنَّ الَّذِينَ كَفَرُوا وَماتُوا وَهُمْ كُفَّارٌ لكفرهم وذنوبهم ( رَحِيمٌ ) بهم فلا يؤاخذهم بسيئاتهم. [91] هذا حال من آمن بعد ارتداده وتاب ، أو آمن بعد علمه بالحق وكفره ، أما من بقي على كفره بعد الإيمان فجزاؤه ما يأتي ( إِنَّ الَّذِينَ كَفَرُوا بَعْدَ إِيمانِهِمْ ) بالنبي وبما جاء به ( ثُمَّ ازْدادُوا كُفْراً ) فإن الكافر ببقائه على الكفر يزداد كفرا فإن كل ساعة يكون كافرا فيها يكون أكثر كفرا من الساعة المتقدمة ، أو المراد ازدياد الكفر باستحكامه فإن الإنسان كما يزداد إيمانا كلما رأى آيات الله كذلك يزداد كفرا كلما أعرض عما يراه من الآيات ( لَنْ تُقْبَلَ تَوْبَتُهُمْ ) التي تأتي منهم حال الاحتضار فإن المحتضر حيث يرى حقيقة الإيمان يتوب في قلبه ويندم ولكن لا تقبل توبته كما قال سبحانه ( وَلَيْسَتِ التَّوْبَةُ لِلَّذِينَ يَعْمَلُونَ السَّيِّئاتِ حَتَّى إِذا حَضَرَ أَحَدَهُمُ الْمَوْتُ قالَ إِنِّي تُبْتُ الْآنَ ) (1) ( وَأُولئِكَ هُمُ الضَّالُّونَ ) الذين ضلوا طريق الحق في الدنيا وعذبوا في الآخرة."},{"text":"إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌ فَلَن يُقْبَلَ مِنْ أَحَدِهِم مِّلْءُ ٱلْأَرْضِ ذَهَبًا وَلَوِ ٱفْتَدَىٰ بِهِۦٓ ۗ أُو۟لَـٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌ وَمَا لَهُم مِّن نَّـٰصِرِينَ","tafsir":""},{"text":"لَن تَنَالُوا۟ ٱلْبِرَّ حَتَّىٰ تُنفِقُوا۟ مِمَّا تُحِبُّونَ ۚ وَمَا تُنفِقُوا۟ مِن شَىْءٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ","tafsir":"ممن لم يتب حتى في حال الاحتضار كما قال سبحانه ( وَلَا الَّذِينَ يَمُوتُونَ وَهُمْ كُفَّارٌ ) (2) بعد الآية ( 1) النساء : 19. ( 2) النساء : 19. فَلَنْ يُقْبَلَ مِنْ أَحَدِهِمْ مِلْءُ الْأَرْضِ ذَهَباً وَلَوِ افْتَدى بِهِ أُولئِكَ لَهُمْ عَذابٌ أَلِيمٌ وَما لَهُمْ مِنْ ناصِرِينَ (91) لَنْ تَنالُوا الْبِرَّ حَتَّى تُنْفِقُوا مِمَّا تُحِبُّونَ وَما تُنْفِقُوا مِنْ شَيْءٍ فَإِنَّ اللهَ بِهِ عَلِيمٌ (92) السابقة : ( وَلَيْسَتِ التَّوْبَةُ ) أو المراد التعقيب على ( لَنْ تُقْبَلَ تَوْبَتُهُمْ ) أي أن أولئك الذين لم تقبل توبتهم في الدنيا لا ينجون من عذاب الله يوم القيامة بإعطاء الفدية ( فَلَنْ يُقْبَلَ مِنْ أَحَدِهِمْ مِلْءُ الْأَرْضِ ذَهَباً ) أي مقدار ما يملأ الأرض من الذهب ( وَلَوِ افْتَدى بِهِ ) لا ينفعه ( أُولئِكَ لَهُمْ عَذابٌ أَلِيمٌ ) مؤلم وموجع ( وَما لَهُمْ مِنْ ناصِرِينَ ) ينصرونهم من عذاب الله وسخطه. [93] وحيث جرى حديث الإنفاق وأنه لن يقبل من الكافر يوم القيامة ناسب السياق بيان حكم الإنفاق وأنه ( لَنْ تَنالُوا الْبِرَّ ) أي لن تدركوا النفع الذي تأملونه من رضى الله وثوابه والجنة وخير الدنيا وغيرها ( حَتَّى تُنْفِقُوا مِمَّا تُحِبُّونَ ) لا أن تنفقوا ما لا تحبون كإنفاق ما تعانيه النفس كما قال سبحانه ( وَلَسْتُمْ بِآخِذِيهِ إِلَّا أَنْ تُغْمِضُوا ) (1) ( وَما تُنْفِقُوا مِنْ شَيْءٍ ) قليل أو كثير في مختلف أصناف الأشياء ( فَإِنَّ اللهَ بِهِ عَلِيمٌ ) فيجازيكم على قدره. ( 1) البقرة : 268. تقريب القران الى الأذهان من آية ( 94) من سورة آل عمران إلى ( 24) من سورة النساء بسم الله الرّحمن الرّحيم الحمد لله رب العالمين ، والصلاة والسلام على أشرف الأنبياء والمرسلين محمد المصطفى وعترته الطاهرين. كُلُّ الطَّعامِ كانَ حِلاًّ لِبَنِي إِسْرائِيلَ إِلاَّ ما حَرَّمَ إِسْرائِيلُ عَلى نَفْسِهِ مِنْ قَبْلِ أَنْ تُنَزَّلَ التَّوْراةُ قُلْ فَأْتُوا بِالتَّوْراةِ فَاتْلُوها إِنْ كُنْتُمْ صادِقِينَ (93) فَمَنِ افْتَرى عَلَى اللهِ الْكَذِبَ مِنْ بَعْدِ ذلِكَ فَأُولئِكَ هُمُ الظَّالِمُونَ (94) [94] يرجع السياق هنا إلى ما كانت الآيات بصدده من أحوال أهل الكتاب في أصولهم وفروعهم وعنادهم وجدالهم ، وفي بعض التفاسير أنهم أنكروا على رسول الله صلى‌الله‌عليه‌وآله‌وسلم تحليل لحم الجزور وادعوا تحريمه على إبراهيم عليه‌السلام وأن ذلك مذكور في التوراة فأنزل الله سبحانه ردا عليهم هذه الآية ( كُلُّ الطَّعامِ ) أي كل المأكولات ، والمراد ب « الكل » الإضافي في مقابل ما أدعوا تحريمه ( كانَ حِلًّا ) أي حلالا ( لِبَنِي إِسْرائِيلَ ) اليهود ( إِلَّا ما حَرَّمَ إِسْرائِيلُ ) أي يعقوب عليه‌السلام ( عَلى نَفْسِهِ ) وهو لحم الإبل كان إذا أكله هيّج عليه « الخاصرة » فحرمه على نفسه. وكان ذلك ( مِنْ قَبْلِ أَنْ تُنَزَّلَ التَّوْراةُ ) على موسى عليه‌السلام فليس تحريمه على إسرائيل دليلا على بقائه على الحرمة فإن التوراة لما نزلت لم تحرمه فلما ذا تقولون أيها اليهود بحرمته ( قُلْ ) يا رسول الله لهم : ( فَأْتُوا بِالتَّوْراةِ فَاتْلُوها ) حتى يظهر أنه لم تحرمه التوراة كما ذكرت لكم ( إِنْ كُنْتُمْ صادِقِينَ ) في دعواكم أن التوراة حرمت الإبل ، لكنهم لم يأتوا بالتوراة ، فتبين كذبهم ، وقد كان اليهود يظنون أن الرسول ـ لأنه أمي ـ لا علم له بالتوراة فلهذا كانوا ينسبون إلى التوراة أشياء ، لكن الوحي كان يفضحهم."},{"text":"۞ كُلُّ ٱلطَّعَامِ كَانَ حِلًّا لِّبَنِىٓ إِسْرَٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسْرَٰٓءِيلُ عَلَىٰ نَفْسِهِۦ مِن قَبْلِ أَن تُنَزَّلَ ٱلتَّوْرَىٰةُ ۗ قُلْ فَأْتُوا۟ بِٱلتَّوْرَىٰةِ فَٱتْلُوهَآ إِن كُنتُمْ صَـٰدِقِينَ","tafsir":""},{"text":"فَمَنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ مِنۢ بَعْدِ ذَٰلِكَ فَأُو۟لَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ","tafsir":""},{"text":"قُلْ صَدَقَ ٱللَّهُ ۗ فَٱتَّبِعُوا۟ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ","tafsir":"البرهان الدال على عدم تحريم التوراة ( فَأُولئِكَ هُمُ الظَّالِمُونَ ) الذين ظلموا أنفسهم بمنعها عن قُلْ صَدَقَ اللهُ فَاتَّبِعُوا مِلَّةَ إِبْراهِيمَ حَنِيفاً وَما كانَ مِنَ الْمُشْرِكِينَ (95) إِنَّ أَوَّلَ بَيْتٍ وُضِعَ لِلنَّاسِ لَلَّذِي بِبَكَّةَ مُبارَكاً الهداية وظلموا غيرهم بمنعهم عن الحق."},{"text":"إِنَّ أَوَّلَ بَيْتٍ وُضِعَ لِلنَّاسِ لَلَّذِى بِبَكَّةَ مُبَارَكًا وَهُدًى لِّلْعَـٰلَمِينَ","tafsir":"يا رسول الله لليهود ( صَدَقَ اللهُ ) فيما نقلت لكم من عدم تحريم الجزور وكذبتم أنتم ، بل تبيّن أن كل الطعام كان حلّا ( فَاتَّبِعُوا ) أيها اليهود ( مِلَّةَ إِبْراهِيمَ حَنِيفاً ) أي مستقيما ، وملة إبراهيم تحلّل كل الطعام ( وَما كانَ ) إبراهيم عليه‌السلام ( مِنَ الْمُشْرِكِينَ ) دحض لافتراء آخر من أهل الكتاب حول إبراهيم عليه‌السلام ، حيث كانوا يقولون أنه كان يهوديا أو نصرانيا ـ وكلاهما مشرك ـ ففي السابق نقل افتراءهم بالنسبة إلى الله في قصة الطعام ، وهنا نقل افتراءهم على أنبيائه بالشرك. [97] إن أهل الكتاب دحضت حجتهم في باب التحليل والتحريم ، ودحضت حجتهم في باب دين إبراهيم ، كما دحضت حجتهم من ذي قبل في سائر الشؤون التي ناقشوا فيها ، وبقيت الآن لهم حجة أخرى هي : أن بيت المقدس أشرف من الكعبة ، وأنه محل الأنبياء ، فالقرآن يدحض حجتهم هذه بأن الكعبة هي أشرف لأنها أول بيت وضع للناس ، ولأن إبراهيم عليه‌السلام الذي تنتسبون إليه هو الذي بناها ، ولأن الحج شرّع إليها ( إِنَّ أَوَّلَ بَيْتٍ وُضِعَ لِلنَّاسِ ) أي بني لأجل انتفاع الناس دينا ودنيا ، فإن الأرض دحيت من تحته ، ولم يكن قبله بيت مبنيّ ( لَلَّذِي ) اللام للتأكيد أي هو البيت الذي ( بِبَكَّةَ ) وهو اسم آخر لمكة ، وسميت بكة لازدحام الناس في الطواف ونحوه هناك ، فإن بكّ يبكّ بمعنى « زحم يزحم » ( مُبارَكاً ) أي كثير البركة والخير فإن فيه خير الدنيا ، حيث الألفة والاجتماع والاقتصاد وَهُدىً لِلْعالَمِينَ (96) فِيهِ آياتٌ بَيِّناتٌ مَقامُ إِبْراهِيمَ وَمَنْ دَخَلَهُ كانَ آمِناً وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطاعَ إِلَيْهِ سَبِيلاً وَمَنْ كَفَرَ وغيرها ، وخير الآخرة حيث غفران الذنوب ورفع الدرجات ( وَهُدىً لِلْعالَمِينَ ) أي سببا لهدايتهم فإنه مذكّر بالله سبحانه وفيه ذكريات أنبيائه ومعالم عبادته."},{"text":"فِيهِ ءَايَـٰتٌۢ بَيِّنَـٰتٌ مَّقَامُ إِبْرَٰهِيمَ ۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنًا ۗ وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلْبَيْتِ مَنِ ٱسْتَطَاعَ إِلَيْهِ سَبِيلًا ۚ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِىٌّ عَنِ ٱلْعَـٰلَمِينَ","tafsir":""},{"text":"قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لِمَ تَكْفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ وَٱللَّهُ شَهِيدٌ عَلَىٰ مَا تَعْمَلُونَ","tafsir":"أي في ذلك البيت ( آياتٌ بَيِّناتٌ ) أي دلالات واضحات على التوحيد والنبوة ونصرة الإسلام ( مَقامُ إِبْراهِيمَ ) أي موضع قدمه حيث كان هناك حجر يضعه إبراهيم ويصعد عليه لبناء أعالي الكعبة حتى رسخت قدماه في ذلك الحجر ، فإنه آية واضحة من آيات الله سبحانه ، وخصّ بالذكر لأهميته وتقديرا لإبراهيم الذي ضحّى بكل ما لديه في سبيل الله سبحانه ( وَمَنْ دَخَلَهُ كانَ آمِناً ) إما ابتداء ، أو عطف أي أن من آيات البيت أنه سبحانه جعله حرما آمنا فمن دخله فهو آمن على عرضه وماله ودمه لا يمسّ بسوء وإن كان مجرما يستحق العقاب والحد ( وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ ) أي يجب على الناس أن يحجوا إلى البيت ( مَنِ اسْتَطاعَ إِلَيْهِ سَبِيلاً ) أي من وجد إليه طريقا وذلك بأن يكون له ما يكفيه ذهابا وإيابا لنفسه ولعائلته ويرجع إلى الكفاية ، مع أمن الطريق وصحة الجسم ، إلى غير ذلك من الشروط المذكورة في الفقه (1) ( وَمَنْ كَفَرَ ) فلم يحج مع الاستطاعة ، وقد تقدم أن الكفر قسمان : كفر في الاعتقاد وهو إنكار أصل من أصول الدين ، وكفر في ( 1) راجع موسوعة الفقه / ج 38. فَإِنَّ اللهَ غَنِيٌّ عَنِ الْعالَمِينَ (97) قُلْ يا أَهْلَ الْكِتابِ لِمَ تَكْفُرُونَ بِآياتِ اللهِ وَاللهُ شَهِيدٌ عَلى ما تَعْمَلُونَ (98) قُلْ يا أَهْلَ الْكِتابِ لِمَ تَصُدُّونَ عَنْ سَبِيلِ اللهِ مَنْ آمَنَ تَبْغُونَها عِوَجاً وَأَنْتُمْ شُهَداءُ العمل وهو ترك واجب أو فعل محرّم. وقد كثر في القرآن والحديث استعمال الكفر بهذا المعنى ( فَإِنَّ اللهَ غَنِيٌّ عَنِ الْعالَمِينَ ) فلا يظن العاصي أن كفره يضر الله شيئا. [99] ويرجع السياق إلى أهل الكتاب ( قُلْ ) يا رسول الله : ( يا أَهْلَ الْكِتابِ لِمَ تَكْفُرُونَ بِآياتِ اللهِ ) أدلته الواضحة الدالة على نبوة نبي الإسلام وما جاء به ، الذي هو منه شؤون بيت الله الحرام ( وَاللهُ شَهِيدٌ ) أي يشهد ويعلم ( عَلى ما تَعْمَلُونَ ) فيجازيكم عليها."},{"text":"قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لِمَ تَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ تَبْغُونَهَا عِوَجًا وَأَنتُمْ شُهَدَآءُ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ","tafsir":""},{"text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ فَرِيقًا مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ يَرُدُّوكُم بَعْدَ إِيمَـٰنِكُمْ كَـٰفِرِينَ","tafsir":"يا رسول الله : ( يا أَهْلَ الْكِتابِ لِمَ تَصُدُّونَ عَنْ سَبِيلِ اللهِ ) أي تمنعون الناس عن الإيمان بالله ، فإن أهل الكتاب كانوا يرصدون لمن يريد الإيمان فيمنعونه ، وكانوا يلقون الشكوك حول الإيمان والمؤمنين ( مَنْ آمَنَ ) مفعول « تصدون » أي تمنعون من آمن عن سبيل الله ، وعلى هذا فالصد هنا خاص بالمؤمنين إلا أن يراد ب « من آمن » الأعم من المؤمن ومن يريد الإيمان ( تَبْغُونَها ) أي تطلبون السبيل ( عِوَجاً ) منحرفا لا سبيلا مستقيما ، أو تطلبون سبيل الله عوجا ، أي تريدون أن تكون السبيل عوجا بإدخال الشكوك عليها ، والعوج مفرد بمعنى الميل والانحراف ( وَأَنْتُمْ شُهَداءُ ) في واقع الأمر وإقرار وَمَا اللهُ بِغافِلٍ عَمَّا تَعْمَلُونَ (99) يا أَيُّهَا الَّذِينَ آمَنُوا إِنْ تُطِيعُوا فَرِيقاً مِنَ الَّذِينَ أُوتُوا الْكِتابَ يَرُدُّوكُمْ بَعْدَ إِيمانِكُمْ كافِرِينَ (100) وَكَيْفَ تَكْفُرُونَ وَأَنْتُمْ تُتْلى عَلَيْكُمْ آياتُ اللهِ وَفِيكُمْ رَسُولُهُ وَمَنْ يَعْتَصِمْ بِاللهِ فَقَدْ هُدِيَ إِلى صِراطٍ مُسْتَقِيمٍ (101) نفوسكم على عملكم الباطل ( وَمَا اللهُ بِغافِلٍ عَمَّا تَعْمَلُونَ ) بل مطّلع عليه عالم به ، وسيعاقبكم عليه. [101] وحيث تقدم أن أهل الكتاب يصدّون من آمن عن سبيل الله ، خاطب سبحانه المؤمنين أن لا يسمعوا إلى أهل الكتاب حتى يضلوا بتشكيكاتهم ( يا أَيُّهَا الَّذِينَ آمَنُوا إِنْ تُطِيعُوا فَرِيقاً ) جماعة ( مِنَ الَّذِينَ أُوتُوا الْكِتابَ ) أعطوا التوراة والإنجيل ( يَرُدُّوكُمْ بَعْدَ إِيمانِكُمْ كافِرِينَ ) أي يرجعونكم كفارا بعد أن آمنتم ، وإنما خصّ فريقا لأن أهل الكتاب لم يكونوا جميعهم سبب إضلال المؤمنين وإرجاعهم عن الإيمان."},{"text":"وَكَيْفَ تَكْفُرُونَ وَأَنتُمْ تُتْلَىٰ عَلَيْكُمْ ءَايَـٰتُ ٱللَّهِ وَفِيكُمْ رَسُولُهُۥ ۗ وَمَن يَعْتَصِم بِٱللَّهِ فَقَدْ هُدِىَ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ","tafsir":""},{"text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ","tafsir":"أيها المؤمنون بعد الإيمان ( وَأَنْتُمْ تُتْلى عَلَيْكُمْ آياتُ اللهِ ) فإنكم قد عرفتم آيات الله ودلائله وعلمتم ذلك ومثل هذا الإنسان لا يمكن أن يكفر ( وَفِيكُمْ رَسُولُهُ ) الذي يدعو إليه بالبراهين والمعاجز ، وهذا استفهام إنكاري تعجبي ، جيء به إبعادا لهم عن الكفر وإلفاتا لهم إلى الرصيد الإيماني الموجود عندهم ( وَمَنْ يَعْتَصِمْ بِاللهِ ) أي يتمسك بآيات الله وكتابه ودينه ورسوله ، فلا ينخرط إلى الشرك والكفر والعصيان ( فَقَدْ هُدِيَ إِلى صِراطٍ مُسْتَقِيمٍ ) في الدنيا حيث يا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللهَ حَقَّ تُقاتِهِ وَلا تَمُوتُنَّ إِلاَّ وَأَنْتُمْ مُسْلِمُونَ (102) وَاعْتَصِمُوا بِحَبْلِ اللهِ يوصله إلى حياة حرة كريمة مرفهة المرافق ، وفي الآخرة حيث يسعده في جنات النعيم. [103] كانت الجماعات المنضوية تحت لواء الإسلام بما فيهم الأوس والخزرج معرضة للتطاحن والتشاحن وقد كان الكفار وأهل الكتاب يستغلون سوابق هؤلاء وطبيعة النفس البشرية في إلقاء الفتن والتفرقة بينهم ليفتحوا ثغرة للنزاع بين أصحاب الرسول صلى‌الله‌عليه‌وآله‌وسلم ولذا نصحهم القرآن بأن يبقوا على وحدتهم وأن لا يتفرقوا ويتقوا الله فيما أمر ونهى ولا يطيعوا أهل الكتاب في أقوالهم المفرّقة ودسائسهم المشتتة ( يا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللهَ ) خافوا عقابه فأطيعوه فيما أمركم ونهاكم ( حَقَّ تُقاتِهِ ) من « وقيت » أي كما يحق أن تتقوه ، فإن التقوى من الله سبحانه أمر صعب جدا ، إذ يلازم الإنسان في جميع شؤونه وأحواله ( وَلا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ ) فلا يغرنكم الشيطان بأن يخرجكم من الإيمان حتى تموتوا كافرين. ولعل المناسبة بين الجملتين أن من لا يتقي ينجر آخر أمره إلى الكفر كما قال سبحانه : ( ثُمَّ كانَ عاقِبَةَ الَّذِينَ أَساؤُا السُّواى أَنْ كَذَّبُوا بِآياتِ اللهِ ) (1) ."},{"text":"وَٱعْتَصِمُوا۟ بِحَبْلِ ٱللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا۟ ۚ وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ كُنتُمْ أَعْدَآءً فَأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْتُم بِنِعْمَتِهِۦٓ إِخْوَٰنًا وَكُنتُمْ عَلَىٰ شَفَا حُفْرَةٍ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنْهَا ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَـٰتِهِۦ لَعَلَّكُمْ تَهْتَدُونَ","tafsir":""},{"text":"وَلْتَكُن مِّنكُمْ أُمَّةٌ يَدْعُونَ إِلَى ٱلْخَيْرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ ۚ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ","tafsir":"أي تمسكوا ( بِحَبْلِ اللهِ ) وحبل الله دينه وقرآنه ، شبّه بالحبل لمناسبة أن من يتمسك بالحبل لا بد وأن يرتفع به إلى الأعلى ، وكذلك من يتمسك بالإيمان يصعد به في الدنيا إلى المراتب الراقية وفي ( 1) الروم : 11. جَمِيعاً وَلا تَفَرَّقُوا وَاذْكُرُوا نِعْمَتَ اللهِ عَلَيْكُمْ إِذْ كُنْتُمْ أَعْداءً فَأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْتُمْ بِنِعْمَتِهِ إِخْواناً وَكُنْتُمْ عَلى شَفا حُفْرَةٍ مِنَ النَّارِ فَأَنْقَذَكُمْ مِنْها كَذلِكَ يُبَيِّنُ اللهُ لَكُمْ آياتِهِ لَعَلَّكُمْ تَهْتَدُونَ (103) الآخرة إلى جنات خالدة ( جَمِيعاً ) أي جميعكم لا بعضكم دون بعض. ( وَلا تَفَرَّقُوا ) بأن يتمسك البعض بحبل الله والبعض بحبل الشيطان ، وهذا تأكيد لقوله « جميعا » ( وَاذْكُرُوا ) أي تذكروا ( نِعْمَتَ اللهِ عَلَيْكُمْ إِذْ كُنْتُمْ أَعْداءً ) قبل الإسلام يعادي بعضكم بعضا ( فَأَلَّفَ بَيْنَ قُلُوبِكُمْ ) جعلها قريبة بعضها إلى بعض ، حيث أدخل الإيمان فيها فخرج ما كان فيها من الضغينة والإحن والحسد والعداوة ( فَأَصْبَحْتُمْ ) أيها المسلمون ( بِنِعْمَتِهِ ) أي بسبب نعمة الألفة التي وهبها الله إليكم ( إِخْواناً ) أحدكم أخ الآخر في الإيمان ، له ما لأخيه وعليه ما عليه. وأن هذه النعمة قد خرقت المقاييس الجاهلية القبلية والعشائرية والعرقية وما أشبهها. ( وَكُنْتُمْ عَلى شَفا حُفْرَةٍ مِنَ النَّارِ ) الشفا : الطرف ، والحفرة المكان المحفور من الأرض ، أي كنتم أيها المسلمون على طرف حفرة من النار ، نار الدنيا وهي العقوبات والاضطرابات ، ونار الآخرة التي أوقدت لكم ( فَأَنْقَذَكُمْ مِنْها ) بالإسلام الذي نظّم أمور دنياكم وأخراكم ، حتى لا تقعوا فيها ( كَذلِكَ ) أي كما بين لكم هذه الأمور واضحة وجلية ( يُبَيِّنُ اللهُ لَكُمْ آياتِهِ ) دلالاته وحججه ( لَعَلَّكُمْ تَهْتَدُونَ ) وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَأُولئِكَ هُمُ الْمُفْلِحُونَ (104) وَلا تَكُونُوا كَالَّذِينَ تَفَرَّقُوا وَاخْتَلَفُوا مِنْ بَعْدِ ما جاءَهُمُ الْبَيِّناتُ إلى الحق وإلى طريق مستقيم. وما ورد في بعض الأحاديث أن المراد من حبل الله الإمام أمير المؤمنين عليه‌السلام أو الأئمة عليهم‌السلام أو القرآن (1) ، فإنما هي مصاديق جلية. [105] وحيث أنقذكم الله من الهلاك ، وهداكم فمن الجدير أن تهدوا سائر الناس ( وَلْتَكُنْ مِنْكُمْ أُمَّةٌ ) أي يجب أن يكون منكم جماعة ( يَدْعُونَ إِلَى الْخَيْرِ ) كل خير من الإسلام والدين والأحكام وغيرها ( وَيَأْمُرُونَ بِالْمَعْرُوفِ ) والمعروف كل فعل استحسنه الشرع أو العقل سواء وصل إلى حد الوجوب أم إلى حد الندب ، وإنما سمي معروفا لأن الناس يعرفونه ( وَيَنْهَوْنَ عَنِ الْمُنْكَرِ ) وهو بعكس المعروف ، كل ما استقبحه الشرع أو العقل ، وسمي منكرا لأن الناس ينكرونه ( وَأُولئِكَ ) الذين يتصفون بهذه الصفات الثلاثة ( هُمُ الْمُفْلِحُونَ ) أي الفائزون الناجون."},{"text":"وَلَا تَكُونُوا۟ كَٱلَّذِينَ تَفَرَّقُوا۟ وَٱخْتَلَفُوا۟ مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْبَيِّنَـٰتُ ۚ وَأُو۟لَـٰٓئِكَ لَهُمْ عَذَابٌ عَظِيمٌ","tafsir":""},{"text":"يَوْمَ تَبْيَضُّ وُجُوهٌ وَتَسْوَدُّ وُجُوهٌ ۚ فَأَمَّا ٱلَّذِينَ ٱسْوَدَّتْ وُجُوهُهُمْ أَكَفَرْتُم بَعْدَ إِيمَـٰنِكُمْ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ","tafsir":"أيها المسلمون بعد الألفة والأخوّة ( كَالَّذِينَ ) من قبلكم تألفت قلوبهم بسبب الأنبياء ثم ( تَفَرَّقُوا ) شيعا وأحزابا ومذاهب ومبادئ ( وَاخْتَلَفُوا ) فأخذ كل فريق منهم جانبا ( مِنْ بَعْدِ ما جاءَهُمُ الْبَيِّناتُ ) الأدلة الواضحة على وحدة العقيدة والمبدأ وأركان الإيمان ( 1) تفسير العياشي : ج 1 ص 194 وبحار الأنوار : ج 36 ص 15 باب 27 ، أنه ( صلوات الله عليه ) حبل الله والعروة الوثقى. وَأُولئِكَ لَهُمْ عَذابٌ عَظِيمٌ (105 ) يَوْمَ تَبْيَضُّ وُجُوهٌ وَتَسْوَدُّ وُجُوهٌ فَأَمَّا الَّذِينَ اسْوَدَّتْ وُجُوهُهُمْ أَ كَفَرْتُمْ بَعْدَ إِيمانِكُمْ فَذُوقُوا الْعَذابَ بِما كُنْتُمْ تَكْفُرُونَ (106) وَأَمَّا الَّذِينَ ابْيَضَّتْ وُجُوهُهُمْ ( وَأُولئِكَ ) الذين اختلفوا وخالفوا الحق منهم ( لَهُمْ عَذابٌ عَظِيمٌ ) حيث بدّلوا وغيّروا وحرّفوا. [107] ثم بين سبحانه أن ذلك العذاب العظيم في أي وقت يكون ؟ إنه يكون في ( يَوْمَ ) هذه صفته ( تَبْيَضُ ) فيه ( وُجُوهٌ ) هي وجوه المؤمنين الذين آمنوا وعملوا الصالحات وابيضاض الوجه كناية عن فرحه ونضارته وتنعّمه ( وَتَسْوَدُّ ) فيه ( وُجُوهٌ ) هي وجوه الكافرين ، واسودادها حقيقة ، فإن الوجه عند الهمّ الكبير يميل لونه إلى السواد والكدرة لتهاجم الدم ونحوه ، أو كناية عن كلوحه وبؤسه وهمومه ( فَأَمَّا الَّذِينَ اسْوَدَّتْ وُجُوهُهُمْ ) يقال لهم : ( أَ كَفَرْتُمْ ) على نحو الاستفهام التوبيخي ( بَعْدَ إِيمانِكُمْ ) إما أن يراد ب « الإيمان » الإيمان الحقيقي بأن يكون المراد منهم الذين اختلفوا وتفرقوا وارتدوا بعد الإيمان ، وإما أن يراد به الإيمان الفطري فإن كل إنسان مؤمن فطرة كما قال صلى‌الله‌عليه‌وآله‌وسلم : « كل مولود يولد على الفطرة وإنما أبواه يهودانه وينصرانه ويمجسانه » (1) ( فَذُوقُوا الْعَذابَ بِما كُنْتُمْ تَكْفُرُونَ ) أي بسبب كفركم."},{"text":"وَأَمَّا ٱلَّذِينَ ٱبْيَضَّتْ وُجُوهُهُمْ فَفِى رَحْمَةِ ٱللَّهِ هُمْ فِيهَا خَـٰلِدُونَ","tafsir":""},{"text":"تِلْكَ ءَايَـٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ ۗ وَمَا ٱللَّهُ يُرِيدُ ظُلْمًا لِّلْعَـٰلَمِينَ","tafsir":"وهم المؤمنون الذين عملوا ( 1) عدة الداعي : ص 332. فَفِي رَحْمَتِ اللهِ هُمْ فِيها خالِدُونَ (107) تِلْكَ آياتُ اللهِ نَتْلُوها عَلَيْكَ بِالْحَقِّ وَمَا اللهُ يُرِيدُ ظُلْماً لِلْعالَمِينَ (108) وَلِلَّهِ ما فِي السَّماواتِ وَما فِي الْأَرْضِ وَإِلَى اللهِ تُرْجَعُ الْأُمُورُ (109) كُنْتُمْ الصالحات ( فَفِي رَحْمَتِ اللهِ ) ثوابه ورضوانه وجنته ( هُمْ فِيها خالِدُونَ ) أبد الآبدين."},{"text":"وَلِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ","tafsir":"الأمور التي ذكرت في أحوال المؤمنين والكافرين وغيرها ( آياتُ اللهِ ) علائمه ودلائله وحججه ( نَتْلُوها عَلَيْكَ ) يا رسول الله ( بِالْحَقِ ) فإن التلاوة قد تكون بالباطل إذا كان المتلوّ أو الغرض من التلاوة باطلا ( وَمَا اللهُ يُرِيدُ ظُلْماً لِلْعالَمِينَ ) أي لا يريد أن يظلم أحدا. فقد تقرر في علم الكلام أن إرادة الظلم ـ كالظلم نفسه ـ قبيحة ، فما يصير إليه حال الكافرين من اسوداد الوجه ليس ظلما لهم ، وإنما يكون بالعدل وجزاء لعملهم."},{"text":"كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِٱلْمَعْرُوفِ وَتَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَتُؤْمِنُونَ بِٱللَّهِ ۗ وَلَوْ ءَامَنَ أَهْلُ ٱلْكِتَـٰبِ لَكَانَ خَيْرًا لَّهُم ۚ مِّنْهُمُ ٱلْمُؤْمِنُونَ وَأَكْثَرُهُمُ ٱلْفَـٰسِقُونَ","tafsir":"كيف يريد الله ظلما والحال أنه ( لِلَّهِ ما فِي السَّماواتِ وَما فِي الْأَرْضِ ) والظلم ينشأ من الافتقار وهو الغني المطلق ( وَإِلَى اللهِ تُرْجَعُ الْأُمُورُ ) أمور الخلق فإن الله سبحانه يعيد المخلوق ليجازيه ، وهذا تشبيه بالرجوع المادي « في الدنيا » الذي يكون بين الحاكم والمحكوم حيث يساق المحكوم نحو الحاكم ليحكم عليه ، وحيث أن الأمر يرجع إلى الله فلا يظن الكافر أنه يتمكن من الفرار عنه سبحانه حتى لا يعاقب بما عمل من السيئات. [111] ويرجع السياق هنا إلى ما تقدم من لزوم الدعوة إلى الخير والأمر بالمعروف والنهي عن المنكر ( كُنْتُمْ ) أيها المسلمون ، و « كان » لمجرد خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنْكَرِ وَتُؤْمِنُونَ بِاللهِ وَلَوْ آمَنَ أَهْلُ الْكِتابِ لَكانَ خَيْراً لَهُمْ الربط ، لا بمعنى الماضي ( خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ ) أي خير جماعة ظهرت للناس فإن كل أمة تظهر للناس في فترة ثم تختفي وتغيب لتأخذ مكانها أمة أخرى. وإنما كان المسلمون خير أمة لخصال ثلاثة بها تترقى الأمم إلى أوج عزّها هي : ( تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنْكَرِ ) فإن المجتمع إذا خلا من هذين الواجبين أخذ يهوي نحو السّفل لما جبل عليه من الفساد والفوضى والشغب ، فإذا تحلّى المجتمع بهذين الأمرين أخذ يتقدم نحو الكمال بمدارج الإنسانية والحضارة الحقيقية حتى يصل إلى قمة البشرية ( وَتُؤْمِنُونَ بِاللهِ ) إيمانا صحيحا لا كإيمان أهل الكتاب والمشركين ، والإيمان الصحيح بالله رأس الفضائل فإنه مع قطع النظر عن كونه إدراكا لأعظم حقيقة كونية فإنه محفّز شديد نحو جميع أنواع الخير ومنفّر قوي عن جميع أصناف الشر ( وَلَوْ آمَنَ أَهْلُ الْكِتابِ ) إيمانا صحيحا بعدم الشرك وقبول قول الله سبحانه في نبوة نبي الإسلام محمد صلى‌الله‌عليه‌وآله‌وسلم ( لَكانَ ) إيمانهم ( خَيْراً لَهُمْ ) في دينهم ودنياهم حتى تنظم دنياهم على ضوء الإسلام فتخلو من الجهل والمرض والفقر والرذيلة ويكونون في الآخرة سعداء ينجون من عذاب الله ، وليس المراد ب « خير » معنى التفضيل بل هو تعبير عرفي ، حيث يظهر للناس أنهم في خير في الجملة ، وعلى هذا يكون إيمانهم أكثر خيرا وأفضل. ثم بين سبحانه أن ليس كل الذين كانوا من أهل الكتاب بقوا على مِنْهُمُ الْمُؤْمِنُونَ وَأَكْثَرُهُمُ الْفاسِقُونَ (110) لَنْ يَضُرُّوكُمْ إِلاَّ أَذىً وَإِنْ يُقاتِلُوكُمْ يُوَلُّوكُمُ الْأَدْبارَ ثُمَّ لا يُنْصَرُونَ (111) ضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ طريقتهم فإن ( مِنْهُمُ الْمُؤْمِنُونَ ) بالله وبالنبي صلى‌الله‌عليه‌وآله‌وسلم وبما جاء به كالنجاشي وابن سلام وغيرهما ( وَأَكْثَرُهُمُ الْفاسِقُونَ ) الخارجون عن طاعة الله باتباع أهوائهم المضلّة وطرائقهم الزائفة. [112] ولقد كان كفار أهل الكتاب يؤذون المؤمنين منهم خاصة وسائر المؤمنين عامة وكان المؤمنون من حيلهم ومؤامراتهم في قلق واضطراب ، ولذا هدأ الله سبحانه من روع المؤمنين بقوله : ( لَنْ يَضُرُّوكُمْ ) أي لن يضر أهل الكتاب إياكم أيها المؤمنون ( إِلَّا أَذىً ) يسيرا فإن مؤامراتهم تفشل وحيلهم تخسر ولا تبقى إلا تشويشات وإشاعات وهي مما لا تضر ضررا معتدا به ، أما ما يظن المسلمون أن أهل الكتاب يتمكنون من اقتلاع جذورهم وإبادة دينهم فلن يكون ذلك أبدا بل المسلمون هم المنصورون ( وَإِنْ يُقاتِلُوكُمْ يُوَلُّوكُمُ الْأَدْبارَ ) جمع دبر وهو الظهر ، أي ينهزمون فارين ( ثُمَّ لا يُنْصَرُونَ ) أي لا تنصرهم أقوالهن ، لما ألقي في قلوبهم من رعب الإسلام وخوف الرسول صلى‌الله‌عليه‌وآله‌وسلم وكان مصب الآية الكريمة اليهود فهم المعنيون بهذا الكلام بقرينة الآية التالية."},{"text":"لَن يَضُرُّوكُمْ إِلَّآ أَذًى ۖ وَإِن يُقَـٰتِلُوكُمْ يُوَلُّوكُمُ ٱلْأَدْبَارَ ثُمَّ لَا يُنصَرُونَ","tafsir":""},{"text":"ضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ أَيْنَ مَا ثُقِفُوٓا۟ إِلَّا بِحَبْلٍ مِّنَ ٱللَّهِ وَحَبْلٍ مِّنَ ٱلنَّاسِ وَبَآءُو بِغَضَبٍ مِّنَ ٱللَّهِ وَضُرِبَتْ عَلَيْهِمُ ٱلْمَسْكَنَةُ ۚ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ ۚ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ","tafsir":""},{"text":"۞ لَيْسُوا۟ سَوَآءً ۗ مِّنْ أَهْلِ ٱلْكِتَـٰبِ أُمَّةٌ قَآئِمَةٌ يَتْلُونَ ءَايَـٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيْلِ وَهُمْ يَسْجُدُونَ","tafsir":"أي ضربها الله عليهم فهم أذلاء إلى الأبد وهي ثابتة لهم ومحيطة بهم ، وأية ذلة أعظم من أنه ليست لهم دولة مستقلة وهم مهانون دائما ، وجميع الدول تطاردهم إلا في ظرف مصلحتها الخاصة فهم كالعبيد المسخرين إن استفاد مولاهم أطعمهم أَيْنَ ما ثُقِفُوا إِلاَّ بِحَبْلٍ مِنَ اللهِ وَحَبْلٍ مِنَ النَّاسِ وَباؤُ بِغَضَبٍ مِنَ اللهِ وَضُرِبَتْ عَلَيْهِمُ الْمَسْكَنَةُ ذلِكَ بِأَنَّهُمْ كانُوا يَكْفُرُونَ بِآياتِ اللهِ وَيَقْتُلُونَ الْأَنْبِياءَ بِغَيْرِ حَقٍّ وإلا طردهم ( أَيْنَ ما ثُقِفُوا ) أي وجدوا ( إِلَّا بِحَبْلٍ مِنَ اللهِ ) أي إلا إذا تمسكوا بحبل الله تعالى بالإيمان به وبمحمد صلى‌الله‌عليه‌وآله‌وسلم وبما جاء به حتى يكونوا كالمسلمين لهم ما لهم وعليهم ما عليهم ( وَحَبْلٍ مِنَ النَّاسِ ) أي تمسكوا بحبل دولة قوية تحميهم ، و « الواو » للتقسيم ـ نحو : الكلمة اسم وفعل وحرف ـ لا للجمع ( وَباؤُ ) رجعوا ( بِغَضَبٍ مِنَ اللهِ ) فكأن الناس جاءوا للاغتراف من مناهل الإسلام وكانت اليهود فيهم فالناس رجعوا بالإسلام وحب الله سبحانه وهؤلاء رجعوا بالكفر وغضب الله تعالى ( وَضُرِبَتْ عَلَيْهِمُ الْمَسْكَنَةُ ) أي الفقر الروحي الذي هو أعظم أقسام المسكنة فإن أرواحهم تهفو إلى المادة أكثر من روح أي فقير مسكين وهم على ثروتهم الظاهرة من أفقر الخلق نفسا وروحا ( ذلِكَ ) العقاب الدنيوي لهم بسبب أنهم ( كانُوا يَكْفُرُونَ بِآياتِ اللهِ ) فموسى عليه‌السلام نبيهم كان منهم في نصب وتعب فإنهم ما خرجوا من البحر إلا قالوا : يا موسى اجعل لنا إلها كما لهم آلهة ، واتخذوا العجل ، وآذوا موسى إلى غير ذلك ( وَيَقْتُلُونَ الْأَنْبِياءَ بِغَيْرِ حَقٍ ) أي كانوا يقتلونهم ، و « بغير حق » تأكيد ، إشارة إلى أنه لم يكن لهم حق في قتلهم حتى ظاهرا ، فإنهم يقتلون الأنبياء لمجرد الدعوة إلى الله والإرشاد والوعظ ، لا لأنهم قتلوا منهم أحدا أو نهبوا مالا أو نحو ذلك ـ وإن كان الأنبياء لو فعلوا ذلك كان بأمر الله وبالحق ـ لكن الأنبياء عليهم‌السلام لم يكونوا فعلوا ذلك ـ كما قال الإمام الحسين عليه‌السلام : « فبم تستحلون دمي ..؟ أعلى قتيل قتلته منكم ـ إلى ذلِكَ بِما عَصَوْا وَكانُوا يَعْتَدُونَ (112) لَيْسُوا سَواءً مِنْ أَهْلِ الْكِتابِ أُمَّةٌ قائِمَةٌ يَتْلُونَ آياتِ اللهِ آناءَ اللَّيْلِ وَهُمْ يَسْجُدُونَ (113) يُؤْمِنُونَ بِاللهِ وَالْيَوْمِ الْآخِرِ وَيَأْمُرُونَ آخر كلامه ـ » (1) . ( ذلِكَ ) أي كفرهم بآيات الله وقتلهم الأنبياء بسبب ما ( عَصَوْا ) أي عصيانهم لأوامر الله سبحانه سبب الكفر والقتل وهما سببا نقمة الله ولعنته ( وَكانُوا يَعْتَدُونَ ) يتجاوزون الحدود الدينية والبشرية. [114] ولمرة أخرى استثنى القرآن الحكيم من آمن من أهل الكتاب ، وأنه ليس كغيره ممن بقي على كفره وعناده وقد نزلت ـ كما قيل ـ حين أسلم جماعة من أهل الكتاب فقال الكفار منهم أنهم أشرارنا. ( لَيْسُوا سَواءً ) أي ليس أهل الكتاب متساوين في ما تقدم من أوصافهم ، ثم ابتدأ قوله سبحانه : ( مِنْ أَهْلِ الْكِتابِ أُمَّةٌ قائِمَةٌ ) على الحق لا زائفة زائلة ، وهم الذين آمنوا بالإسلام ( يَتْلُونَ آياتِ اللهِ ) المنزلة في القرآن المجيد ( آناءَ اللَّيْلِ ) ساعاته وأوقاته ، فإن لقراءة القرآن في الليل أثرا كبيرا حيث إن هدوء النفس وهدوء الجو يوجبان وقوع الآيات في النفس أكثر منه في النهار ( وَهُمْ يَسْجُدُونَ ) لله سبحانه ويخضعون له بالصلاة والتعفير."},{"text":"يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُسَـٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَأُو۟لَـٰٓئِكَ مِنَ ٱلصَّـٰلِحِينَ","tafsir":""},{"text":"وَمَا يَفْعَلُوا۟ مِنْ خَيْرٍ فَلَن يُكْفَرُوهُ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ","tafsir":"إيمانا صحيحا ( وَ ) يؤمنون ب ( الْيَوْمِ الْآخِرِ ) عن حقيقة فإن من آمن حقيقة بالحساب انقلع عن الكفر والمعاصي ( وَيَأْمُرُونَ ( 1) راجع بحار الأنوار : ج 44 ص 316. بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَيُسارِعُونَ فِي الْخَيْراتِ وَأُولئِكَ مِنَ الصَّالِحِينَ (114) وَما يَفْعَلُوا مِنْ خَيْرٍ فَلَنْ يُكْفَرُوهُ وَاللهُ عَلِيمٌ بِالْمُتَّقِينَ (115) إِنَّ الَّذِينَ كَفَرُوا لَنْ تُغْنِيَ عَنْهُمْ أَمْوالُهُمْ وَلا أَوْلادُهُمْ مِنَ اللهِ شَيْئاً وَأُولئِكَ أَصْحابُ النَّارِ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَيُسارِعُونَ فِي الْخَيْراتِ ) فإن المعتقد بيوم الحساب يسارع في الخير حيث لا يدري أي يوم يموت فينقطع عمله ولا يتمكن من المزيد « وكان الإتيان بباب المفاعلة للإشارة إلى تسابق بعضهم بعضا » ( وَأُولئِكَ مِنَ الصَّالِحِينَ ) الذين يصلحون ولا يفسدون ، وبتعبير آخر أعضاء صالحين في المجتمع ، وليسوا كما ذكر الكفار من أهل الكتاب أنهم أشرارهم ، بل هم من أفضل الأخيار والصلحاء."},{"text":"إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَـٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا ۖ وَأُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۚ هُمْ فِيهَا خَـٰلِدُونَ","tafsir":"أي ما يفعله هؤلاء المؤمنون من أهل الكتاب ( مِنْ خَيْرٍ ) من طاعة وعبادة ( فَلَنْ يُكْفَرُوهُ ) أي لن يمنع عنهم جزاؤهم بخلاف سائر الكفار الذين تحبط أعمالهم لكفرهم كرماد اشتدت به الريح في يوم عاصف ( وَاللهُ عَلِيمٌ بِالْمُتَّقِينَ ) يعلم أحوالهم وأعمالهم فيجازيهم على حسناتهم."},{"text":"مَثَلُ مَا يُنفِقُونَ فِى هَـٰذِهِ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَثَلِ رِيحٍ فِيهَا صِرٌّ أَصَابَتْ حَرْثَ قَوْمٍ ظَلَمُوٓا۟ أَنفُسَهُمْ فَأَهْلَكَتْهُ ۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَـٰكِنْ أَنفُسَهُمْ يَظْلِمُونَ","tafsir":"بالله ورسوله ( لَنْ تُغْنِيَ عَنْهُمْ ) أي لن تفيدهم ولن تدفع العذاب عنهم ( أَمْوالُهُمْ وَلا أَوْلادُهُمْ ) فالمال والولد إنما ينفعان في الدنيا حيث يدفعان المكروه بالرشوة والهدية والصلة ، والمدافعة والمناصرة ( مِنَ اللهِ ) أي من عقاب الله وعذابه ( شَيْئاً ) ولو ضئيلا ( وَأُولئِكَ أَصْحابُ النَّارِ ) الذين يلازمونها كما هُمْ فِيها خالِدُونَ (116) مَثَلُ ما يُنْفِقُونَ فِي هذِهِ الْحَياةِ الدُّنْيا كَمَثَلِ رِيحٍ فِيها صِرٌّ أَصابَتْ حَرْثَ قَوْمٍ ظَلَمُوا أَنْفُسَهُمْ فَأَهْلَكَتْهُ وَما ظَلَمَهُمُ اللهُ يقال : صاحب فلان لمن يلازمه ( هُمْ فِيها خالِدُونَ ) إلى الأبد. وقد تكرر أن الخلود للمعاند كما في دعاء كميل « من المعاندين » أما القاصر فإنه يمتحن هناك كما دلّ العقل والشرع. [118] وحيث تقدم حال المؤمن وحال الكافر ، ذكر حال إنفاق الكافر مقابلة لما تقدم من خير المؤمن في قوله : ( وَما يَفْعَلُوا مِنْ خَيْرٍ مَثَلُ ما يُنْفِقُونَ ) أي ينفقه الكفار ( فِي هذِهِ الْحَياةِ الدُّنْيا ) وكان ذكر « هذه » الخصوصية مع وضوحها للإشارة إلى أن الحياة التي هي مزرعة ومن المقتضي أن تنمو ويبقى أثرها للانتفاع به في الآخرة ، لا ينفع الكافر ( كَمَثَلِ رِيحٍ فِيها صِرٌّ ) الصرّ هو البرد الشديد ، أو السموم الحارة ( أَصابَتْ حَرْثَ قَوْمٍ ) فإنفاقهم كالحرث ، وكفرهم الموجب لبطلانه كالريح السامة ( ظَلَمُوا أَنْفُسَهُمْ ) بأن زرعوا في غير موقع الزراعة في مهب الرياح أو في غير أوانه كالشتاء مثلا لو زرعوا بذور الصيف ، أو المراد ظلموا أنفسهم بالمعصية فسلط الله عليهم الريح كما قال : ( وَلَوْ أَنَّ أَهْلَ الْقُرى آمَنُوا وَاتَّقَوْا لَفَتَحْنا عَلَيْهِمْ بَرَكاتٍ مِنَ السَّماءِ وَالْأَرْضِ وَلكِنْ كَذَّبُوا فَأَخَذْناهُمْ بِما كانُوا يَكْسِبُونَ ) (1) وإنما أوتي بهذه الجملة لظلم الكفار أنفسهم كظلم صاحب الحرث ( فَأَهْلَكَتْهُ ) أي أهلكت الريح الحرث ـ وهو الزرع ـ ( وَما ظَلَمَهُمُ اللهُ ) في إبطال نفقاتهم ، أو ( 1) الأعراف : 97. وَلكِنْ أَنْفُسَهُمْ يَظْلِمُونَ (117) يا أَيُّهَا الَّذِينَ آمَنُوا لا تَتَّخِذُوا بِطانَةً مِنْ دُونِكُمْ لا يَأْلُونَكُمْ خَبالاً وَدُّوا ما عَنِتُّمْ في إهلاك الريح حرثهم ( وَلكِنْ أَنْفُسَهُمْ يَظْلِمُونَ ) بكفرهم أو بظلمهم ، ولا يخفى أن قوله : « مثل ما ينفقون » « كمثل ريح » ليس المراد أن الإنفاق كالريح ، بل يضرب المثل فيما كان المجموع من « الأصل والشبه » مرتبطين وإن كانت مفردات الشبه لم تذكر حسب السياق اللفظي ، كما تقول : « مثل زيد في تكلمه كمثل صوت الحمار » فالجملة شبهت بالجملة لأن الصوت شبّه بزيد ، والحمار بالتكلم ، كما يقتضيه السياق اللفظي في الترتيب. [119] وفي سياق الكلام عن أحوال أهل الكتاب وبيان أنهم مختلفون مع المسلمين في العقيدة والعمل يأتي دور أن المسلم لا ينبغي له أن يتخذ صديقا من هؤلاء ( يا أَيُّهَا الَّذِينَ آمَنُوا لا تَتَّخِذُوا بِطانَةً مِنْ دُونِكُمْ ) أي لا تتخذوا الكفار الذين هم غير المسلمين بطانة ، وهي خاصة الرجل الذي يسرّ إليه بأمره ويستبطن خبره ، من « بطانة الثوب » الذي يلي البدن لقربه منه ، و « من » للتبيين كأنه قال : بطانة من المشركين ، فقد كان المسلمون يواصلون رجالا من أهل الكتاب لسابق صداقة أو قرابة أو جوار أو نحوها فنهوا عن ذلك. ثم بين سبحانه سبب ذلك ، ويحتمل أن يكون المراد ب « دونكم » المنافقين ، كما في بعض التفاسير بدليل قوله : « قالوا آمنا » فإنهم ( لا يَأْلُونَكُمْ خَبالاً ) لا يألونكم أي لا يقصّرون بالنسبة إليكم ، والخبال الفساد ، أي هؤلاء البطانة لا يقصرون في فساد أمركم ولا يتركون جهدهم في مضرتكم ( وَدُّوا ) أي أحبوا ( ما عَنِتُّمْ ) أي عنتكم ، قَدْ بَدَتِ الْبَغْضاءُ مِنْ أَفْواهِهِمْ وَما تُخْفِي صُدُورُهُمْ أَكْبَرُ قَدْ بَيَّنَّا لَكُمُ الْآياتِ إِنْ كُنْتُمْ تَعْقِلُونَ (118) ها أَنْتُمْ أُولاءِ تُحِبُّونَهُمْ وَلا يُحِبُّونَكُمْ وَتُؤْمِنُونَ بِالْكِتابِ كُلِّهِ وَإِذا لَقُوكُمْ قالُوا آمَنَّا وَإِذا خَلَوْا والعنت المشقة ، وهذه كلها من صفات الأعداء ( قَدْ بَدَتِ ) أي ظهرت ( الْبَغْضاءُ ) والعداوة ( مِنْ أَفْواهِهِمْ ) فإن فلتات كلامهم تدل على عداوتهم الكامنة ( وَما تُخْفِي صُدُورُهُمْ ) من الحقد لكم والعداوة ( أَكْبَرُ ) مما يظهر من ألسنتهم ( قَدْ بَيَّنَّا لَكُمُ ) أيها المؤمنون ( الْآياتِ ) والحجج التي تميزون بها الصديق من العدو ( إِنْ كُنْتُمْ تَعْقِلُونَ ) إن كان لكم عقل وإدراك. [120] ثم بيّن سبحانه أنه كيف يمكن أن يحب المؤمن هؤلاء مع أنهم أعداؤه ومع الاختلاف بينهم في العقيدة ( ها ) تنبيه ( أَنْتُمْ أُولاءِ ) أي الذين ( تُحِبُّونَهُمْ ) أي تحبون أولئك الكفار ( وَلا يُحِبُّونَكُمْ ) لأنهم يريدون لكم الكفر والضلالة ( وَتُؤْمِنُونَ ) أنتم ( بِالْكِتابِ كُلِّهِ ) وهم لا يؤمنون إلا ببعض الكتاب ، أما البعض الآخر الذي فيه أوصاف محمد صلى‌الله‌عليه‌وآله‌وسلم والإيمان به فلا يؤمنون به ، أو المراد ب « كله » أي جنس ما نزل على أنبياء الله ، بخلافهم فإنهم لا يؤمنون بكتاب محمد صلى‌الله‌عليه‌وآله‌وسلم ( وَإِذا لَقُوكُمْ ) من الملاقاة أي رأوكم ( قالُوا آمَنَّا ) نفاقا منهم لا أن الإيمان دخل قلوبهم ، ويحتمل أن يراد الكفار ، فإن من يتظاهر بالصداقة كثيرا ما يظهر قبول ما عليه صديقه مع أنه ليس بصبغة صديقه ، وهذا بناء على قوله : « من دونكم » للكفار لا للمنافقين ( وَإِذا خَلَوْا ) أي خلا بعضهم عَضُّوا عَلَيْكُمُ الْأَنامِلَ مِنَ الْغَيْظِ قُلْ مُوتُوا بِغَيْظِكُمْ إِنَّ اللهَ عَلِيمٌ بِذاتِ الصُّدُورِ (119) إِنْ تَمْسَسْكُمْ حَسَنَةٌ تَسُؤْهُمْ وَإِنْ تُصِبْكُمْ سَيِّئَةٌ يَفْرَحُوا بِها وَإِنْ تَصْبِرُوا وَتَتَّقُوا لا يَضُرُّكُمْ كَيْدُهُمْ شَيْئاً إِنَّ اللهَ بِما يَعْمَلُونَ مُحِيطٌ (120) مع بعض ( عَضُّوا عَلَيْكُمُ الْأَنامِلَ ) أي يعضون أطراف أصابعهم ( مِنَ الْغَيْظِ ) عليكم كيف تقدّمتم وقوي دينكم. ( قُلْ ) يا رسول الله لهم ( مُوتُوا بِغَيْظِكُمْ ) فإن الغيظ لا يبرحكم لأن المسلمين يتقدمون ويستمرون في أعمالهم. أو هو دعاء عليهم ( إِنَّ اللهَ عَلِيمٌ بِذاتِ الصُّدُورِ ) التي تضمن النفاق والكيد للمسلمين ، فيجازيهم بما اقترفوه من الآثام والذنوب و « بذات الصدور » بمعنى : بتلك الصدور. [121] وكيف تتخذونهم بطانة والحال أن صفتهم هكذا ( إِنْ تَمْسَسْكُمْ حَسَنَةٌ ) أي يصبكم خير ، من « المس » بمعنى الإصابة ( تَسُؤْهُمْ ) أي تحزنهم ( وَإِنْ تُصِبْكُمْ سَيِّئَةٌ ) أي بليّة ومصيبة بإصابة العدو منكم أو فقر أو موت أو نحوها ( يَفْرَحُوا بِها ) أي بسببها ـ كما هو حال العدو مع عدوه ـ ( وَإِنْ تَصْبِرُوا ) على أذيتهم ، وعلى مقاطعتكم إياهم التي تجر إليكم عداءهم الظاهري ، فإن كثيرا من الناس يخافون من مقاطعة المنافقين لئلا يبتلوا بعدائهم في الظاهر ( وَتَتَّقُوا ) الله سبحانه حتى يكون هو نصيركم ( لا يَضُرُّكُمْ ) أيها المؤمنون ( كَيْدُهُمْ ) ومكرهم وحيلتهم ضدكم ( شَيْئاً ) لأنه سبحانه ينصركم ( إِنَّ اللهَ بِما يَعْمَلُونَ ) هم جميعا المؤمنون والمنافقون ( مُحِيطٌ ) أي عالم بجميع أعمالهم ، وَإِذْ غَدَوْتَ مِنْ أَهْلِكَ تُبَوِّئُ الْمُؤْمِنِينَ مَقاعِدَ لِلْقِتالِ كالمحيط من الأجسام الذي لا يخلو منه طرف من المحاط ، فيجازيهم بأعمالهم. [122] وهنا يستعرض القرآن الحكيم قصة واحدة تدل على مدى تطبيق أحوال المنافقين التي سبقت على الواقع الخارجي ، وأن الله كيف ينصر المسلمين في أحرج الساعات وأحلك الظروف ، و ذلك في غزوة أحد حين خرجت قريش من مكة يريدون حرب النبي صلى‌الله‌عليه‌وآله‌وسلم فانتخب الرسول صلى‌الله‌عليه‌وآله‌وسلم موضعا للقتال وعبّاد أصحابه الذين بلغوا سبعمائة رجل فجعل عبد الله بن جبير في خمسين من الرماة على باب شعب في الجبل ليحفظوه حتى لا يهاجم العدو من خلف المسلمين فقال لهم : « لا تبرحوا من هذا المكان والزموا مراكزكم ، إن غلبنا أو غلبنا » . فلما انهزمت قريش وأخذ المسلمون ينهبون ثقلهم قال أصحاب ابن جبير له : قد غنم أصحابنا ونحن نبقى بغير غنيمة. فقال لهم : اتقوا الله فإن رسول الله صلى‌الله‌عليه‌وآله‌وسلم نهانا أن نبرح أماكننا. فلم يقبلوا منه وأخذوا ينسل الرجل منهم فالرجل حتى خلت المراكز وبقي عبد الله في اثني عشر رجلا ، واغتنم الكفار هذا الأمر فجاء خالد بن الوليد مع أصحابه وفرقوا من تبقّى من المسلمين وقتلوهم على الشعب وهجموا على المسلمين من خلفهم وهم مشتغلون بالنهب ورجع الكفار فطوقوا المسلمين من جوانبهم ففر المسلمون ولم يبق مع الرسول إلا علي عليه‌السلام وأبو دجانة ، وقتل من المسلمين جمع كثير بلغوا السبعين وفيهم حمزة عم النبي صلى‌الله‌عليه‌وآله‌وسلم أسد الله وأسد رسوله. ( وَإِذْ غَدَوْتَ ) أي خرجت ( مِنْ أَهْلِكَ ) أي من المدينة غدوة ، يا رسول الله ( تُبَوِّئُ الْمُؤْمِنِينَ مَقاعِدَ ) أي تهيئ لهم مراكز ( لِلْقِتالِ ) وَاللهُ سَمِيعٌ عَلِيمٌ (121) إِذْ هَمَّتْ طائِفَتانِ مِنْكُمْ أَنْ تَفْشَلا وَاللهُ وَلِيُّهُما وَعَلَى اللهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ (122) وَلَقَدْ نَصَرَكُمُ اللهُ بِبَدْرٍ وَأَنْتُمْ أَذِلَّةٌ فَاتَّقُوا اللهَ لَعَلَّكُمْ تَشْكُرُونَ (123) إِذْ تَقُولُ لِلْمُؤْمِنِينَ أَ لَنْ يَكْفِيَكُمْ في قصة أحد ( وَاللهُ سَمِيعٌ ) لأقوالك ( عَلِيمٌ ) بما تنويه من حب الخير والهداية للناس عامة."},{"text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ بِطَانَةً مِّن دُونِكُمْ لَا يَأْلُونَكُمْ خَبَالًا وَدُّوا۟ مَا عَنِتُّمْ قَدْ بَدَتِ ٱلْبَغْضَآءُ مِنْ أَفْوَٰهِهِمْ وَمَا تُخْفِى صُدُورُهُمْ أَكْبَرُ ۚ قَدْ بَيَّنَّا لَكُمُ ٱلْـَٔايَـٰتِ ۖ إِن كُنتُمْ تَعْقِلُونَ","tafsir":""},{"text":"هَـٰٓأَنتُمْ أُو۟لَآءِ تُحِبُّونَهُمْ وَلَا يُحِبُّونَكُمْ وَتُؤْمِنُونَ بِٱلْكِتَـٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمْ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ عَضُّوا۟ عَلَيْكُمُ ٱلْأَنَامِلَ مِنَ ٱلْغَيْظِ ۚ قُلْ مُوتُوا۟ بِغَيْظِكُمْ ۗ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ","tafsir":""},{"text":"إِن تَمْسَسْكُمْ حَسَنَةٌ تَسُؤْهُمْ وَإِن تُصِبْكُمْ سَيِّئَةٌ يَفْرَحُوا۟ بِهَا ۖ وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ لَا يَضُرُّكُمْ كَيْدُهُمْ شَيْـًٔا ۗ إِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ مُحِيطٌ","tafsir":""},{"text":"وَإِذْ غَدَوْتَ مِنْ أَهْلِكَ تُبَوِّئُ ٱلْمُؤْمِنِينَ مَقَـٰعِدَ لِلْقِتَالِ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ","tafsir":""},{"text":"إِذْ هَمَّت طَّآئِفَتَانِ مِنكُمْ أَن تَفْشَلَا وَٱللَّهُ وَلِيُّهُمَا ۗ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ","tafsir":""},{"text":"وَلَقَدْ نَصَرَكُمُ ٱللَّهُ بِبَدْرٍ وَأَنتُمْ أَذِلَّةٌ ۖ فَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تَشْكُرُونَ","tafsir":"وعزمت ( طائِفَتانِ ) أي جماعتان ( مِنْكُمْ ) أيها المسلمون ، وهما بنو سلمة وبنو حارثة ( أَنْ تَفْشَلا ) وتجبنا وترجعا عن القتال وذلك لأن ابن أبي سلول المنافق جبّنهما عن لقاء العدو فهمّا بالرجوع لكنهما لم يفعلا ( وَاللهُ وَلِيُّهُما ) ناصرهما فلم الفشل والخوف ( وَعَلَى اللهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ ) والتوكل معناه تفويض الأمر إليه سبحانه ( وَمَنْ يَتَوَكَّلْ عَلَى اللهِ فَهُوَ حَسْبُهُ ) (1) ."},{"text":"إِذْ تَقُولُ لِلْمُؤْمِنِينَ أَلَن يَكْفِيَكُمْ أَن يُمِدَّكُمْ رَبُّكُم بِثَلَـٰثَةِ ءَالَـٰفٍ مِّنَ ٱلْمَلَـٰٓئِكَةِ مُنزَلِينَ","tafsir":"أيها المسلمون ( بِبَدْرٍ ) في وقعة بدر وهي اسم بئر كانت هناك فسميت الغزوة باسمها ( وَأَنْتُمْ أَذِلَّةٌ ) جمع ذليل لأن عددهم وعددهم كانت قليلة لا تقوى على المقاومة ( فَاتَّقُوا اللهَ ) ولا تتوانوا عن الجهاد بعد ما رأيتم نصرة الله في بدر وهذا لأجل تقوية قلوبكم في « أحد » وتصديق لقوله : « والله وليهما » ( لَعَلَّكُمْ تَشْكُرُونَ ) أي نصركم لتقوموا بشكر نعمه عليكم."},{"text":"بَلَىٰٓ ۚ إِن تَصْبِرُوا۟ وَتَتَّقُوا۟ وَيَأْتُوكُم مِّن فَوْرِهِمْ هَـٰذَا يُمْدِدْكُمْ رَبُّكُم بِخَمْسَةِ ءَالَـٰفٍ مِّنَ ٱلْمَلَـٰٓئِكَةِ مُسَوِّمِينَ","tafsir":"يا رسول الله ( لِلْمُؤْمِنِينَ ) في غزوة بدر ( أَ لَنْ يَكْفِيَكُمْ ( 1) الطلاق : 4. أَنْ يُمِدَّكُمْ رَبُّكُمْ بِثَلاثَةِ آلافٍ مِنَ الْمَلائِكَةِ مُنْزَلِينَ (124) بَلى إِنْ تَصْبِرُوا وَتَتَّقُوا وَيَأْتُوكُمْ مِنْ فَوْرِهِمْ هذا يُمْدِدْكُمْ رَبُّكُمْ بِخَمْسَةِ آلافٍ مِنَ الْمَلائِكَةِ مُسَوِّمِينَ (125) أَنْ يُمِدَّكُمْ رَبُّكُمْ بِثَلاثَةِ آلافٍ مِنَ الْمَلائِكَةِ ) وذلك لتقوية قلوب المؤمنين ، وبيان أن الله أرسل ملائكة لتقويتهم وتعزيز مركزهم ، وهذا تذكير للمسلمين في أحد بسابق نصر الله لهم ( مُنْزَلِينَ ) أنزلهم الله سبحانه لنصرة المسلمين ولقد حاربوا الكفار وقتلوا منهم."},{"text":"وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ لَكُمْ وَلِتَطْمَئِنَّ قُلُوبُكُم بِهِۦ ۗ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ","tafsir":"ليس الإمداد في يوم بدر بثلاثة آلاف فقط ، بل قال لهم الرسول صلى‌الله‌عليه‌وآله‌وسلم يوم بدر ـ تقوية لقلوبهم ـ : ( إِنْ تَصْبِرُوا ) على الجهاد ( وَتَتَّقُوا ) المعاصي ( وَيَأْتُوكُمْ ) الكفار ( مِنْ فَوْرِهِمْ ) أي فورانهم مندفعين عاجلا نحوكم ( هذا ) الذي شاهدتموه إذ أتوكم كالسيل ، فإن المسلمين خذلوهم عند مجيئهم لما رأوا من كثرتهم ( يُمْدِدْكُمْ رَبُّكُمْ ) والإمداد إرسال المدد ( بِخَمْسَةِ آلافٍ ) أخر ـ غير الثلاثة آلاف ـ ( مِنَ الْمَلائِكَةِ مُسَوِّمِينَ ) من سوم الخيل إذا علّمه بعلامة ، أو علّموا أنفسهم بعلامة حيث كانت عليهم عمائم بيض وأرسلوا أذنابها على أكتافهم ، وهناك قول آخر هو أن قوله تعالى : « بلى » لموضوع أحد ، فإن الكفار هموا بالرجوع مرة ثانية بعد أن نالوا من المسلمين ما نالوا وخالف المسلمون فوعدهم الله تعالى أنهم إن رجعوا أمدهم بخمسة آلاف من الملائكة ، لكن السياق يؤيد المعنى الأول ، والله أعلم. [127] ثم بيّن سبحانه أن إنزال الملائكة والوعد به ليس لأجل أنهم السبب في نصر المسلمين ، بل لأجل البشارة وأما النصر فإنه من قبل الله وحده ولو بدون الملائكة ، حتى تتقوى قلوب المسلمين في الجهاد وَما جَعَلَهُ اللهُ إِلاَّ بُشْرى لَكُمْ وَلِتَطْمَئِنَّ قُلُوبُكُمْ بِهِ وَمَا النَّصْرُ إِلاَّ مِنْ عِنْدِ اللهِ الْعَزِيزِ الْحَكِيمِ (126) لِيَقْطَعَ طَرَفاً مِنَ الَّذِينَ كَفَرُوا أَوْ يَكْبِتَهُمْ فَيَنْقَلِبُوا خائِبِينَ (127) لَيْسَ لَكَ مِنَ الْأَمْرِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ ( وَما جَعَلَهُ اللهُ ) أي ما جعل إنزال الملائكة والوعد به ( إِلَّا بُشْرى لَكُمْ ) أي بشارة لكم أيها المسلمون ( وَلِتَطْمَئِنَّ قُلُوبُكُمْ بِهِ ) أي بهذا الإنزال والوعد ( وَمَا النَّصْرُ ) أي ليس العون ( إِلَّا مِنْ عِنْدِ اللهِ الْعَزِيزِ ) في سلطانه ( الْحَكِيمِ ) في أموره. [128] أما حكمة نصر المسلمين على أعدائهم في هذه الغزوة وسائر الحروب فهي ( لِيَقْطَعَ ) أي يفصل ( طَرَفاً مِنَ الَّذِينَ كَفَرُوا ) الطرف من الأنفس بالقتل ، ومن الأراضي بالفتح ومن الأموال بالغنيمة ( أَوْ يَكْبِتَهُمْ ) أي يخزيهم حتى يرغموا وتقل شوكتهم ( فَيَنْقَلِبُوا ) إلى أهليهم ( خائِبِينَ ) لم ينالوا بغنيمتهم بل انعكس الأمر فكبتوا وأرغموا."},{"text":"لِيَقْطَعَ طَرَفًا مِّنَ ٱلَّذِينَ كَفَرُوٓا۟ أَوْ يَكْبِتَهُمْ فَيَنقَلِبُوا۟ خَآئِبِينَ","tafsir":""},{"text":"لَيْسَ لَكَ مِنَ ٱلْأَمْرِ شَىْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَـٰلِمُونَ","tafsir":""},{"text":"وَلِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ","tafsir":"يا رسول الله ( مِنَ الْأَمْرِ ) المرتبط بهؤلاء الكفار ( شَيْءٌ ) فإن النصر والهزيمة والكبت كلها مرتبطة بإرادة الله سبحانه كما قال سبحانه : ( وَما رَمَيْتَ إِذْ رَمَيْتَ وَلكِنَّ اللهَ رَمى ) (1) وقال : ( هُوَ الَّذِي أَخْرَجَ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتابِ مِنْ دِيارِهِمْ ) (2) ثم رجع السياق إلى تتميم قوله في الآية السابقة « أو يكبتهم » ( أَوْ يَتُوبَ عَلَيْهِمْ ) بأن تكون نصرة المؤمنين على الكفار سببا لهداية جماعة منهم إلى ( 1) الأنفال : 18. ( 2) الحشر : 3. أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظالِمُونَ (128) وَلِلَّهِ ما فِي السَّماواتِ وَما فِي الْأَرْضِ يَغْفِرُ لِمَنْ يَشاءُ وَيُعَذِّبُ مَنْ يَشاءُ وَاللهُ غَفُورٌ رَحِيمٌ (129) يا أَيُّهَا الَّذِينَ آمَنُوا لا تَأْكُلُوا الرِّبَوا أَضْعافاً مُضاعَفَةً الإيمان فيتوب الله سبحانه عليهم فيما فعلوا سابقا من الكفر والعصيان ( أَوْ يُعَذِّبَهُمْ ) بأن تظفروا عليهم فتأسروهم ( فَإِنَّهُمْ ظالِمُونَ ) فتعذيبهم ليس ظلما من الله عليهم بل لظلمهم أنفسهم فالأمر ليس بيدك يا رسول الله ، وإنما ينصر الله المؤمنين لأحد أغراض أربعة : قطع طرف منهم ، أو هزيمتهم وإرغامهم ، أو هدايتهم ، أو تعذيبهم. والاعتراض بجملة « ليس لك » لتركيز كون النصر من عند الله ، فإن اعتراض جملة في وسط جملة متسقة توجب إلفات الذهن وتركيز المطلب أكثر من بيان الجملة في موقعها الطبيعي. [130] ليس لك شيء ( وَلِلَّهِ ما فِي السَّماواتِ وَما فِي الْأَرْضِ ) فيفعل ما يشاء بمن يشاء فإنه تصرّف في ملكه لحكمة وغاية ( يَغْفِرُ لِمَنْ يَشاءُ ) ممن استحق الغفران بالطاعة والتوبة ( وَيُعَذِّبُ مَنْ يَشاءُ ) ممن استحق العذاب بالكفر والعصيان ( وَاللهُ غَفُورٌ رَحِيمٌ ) فتعذيبه أقل من غفرانه فقد سبقت رحمته غضبه. [131] ويرجع السياق هنا إلى الربا والإنفاق مما مر بنا سابقا ، لمناسبة أن الربا من أسباب العذاب ، والإنفاق ، من أسباب الغفران ( يا أَيُّهَا الَّذِينَ آمَنُوا لا تَأْكُلُوا الرِّبَوا أَضْعافاً مُضاعَفَةً ) فإن من شأن الربا أن يتضاعف مرات ومرات فإن ربا الألف لو كان خمسينا يصبح ربا الألف وَاتَّقُوا اللهَ لَعَلَّكُمْ تُفْلِحُونَ (130) وَاتَّقُوا النَّارَ الَّتِي أُعِدَّتْ لِلْكافِرِينَ (131) وَأَطِيعُوا اللهَ وَالرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ (132) وَسارِعُوا إِلى مَغْفِرَةٍ مِنْ رَبِّكُمْ وَجَنَّةٍ عَرْضُهَا السَّماواتُ وَالْأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ (133) والخمسين ـ في سنة ثانية ـ ألفا ومائة واثنين ونصف ، وهكذا يتضاعف الربا ، ويمتص مال الفقراء وعملهم الذي يؤدون به الدين والربا معا ( وَاتَّقُوا اللهَ ) خافوا عقابه ( لَعَلَّكُمْ تُفْلِحُونَ ) أي لكي تفوزوا بالثواب والنعيم."},{"text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوا۟ ٱلرِّبَوٰٓا۟ أَضْعَـٰفًا مُّضَـٰعَفَةً ۖ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ","tafsir":""},{"text":"وَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِىٓ أُعِدَّتْ لِلْكَـٰفِرِينَ","tafsir":""},{"text":"وَأَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ","tafsir":"فلا تفعلوا ما يوجبها ( الَّتِي أُعِدَّتْ ) وهيّأت ( لِلْكافِرِينَ ) الذين يكفرون في الاعتقاد أو في العمل ، أو المراد الكفار العقائديون ، والتخصيص بهم من أن العصاة أيضا يذهبون إلى النار ، وأن دوامها وبقاءها عليهم ، أو أنهم معظمهم أهلها."},{"text":"۞ وَسَارِعُوٓا۟ إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا ٱلسَّمَـٰوَٰتُ وَٱلْأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ","tafsir":"فيما يأمركم وينهاكم ، وذكر الرسول صلى‌الله‌عليه‌وآله‌وسلم للتعظيم وإفادة أمره أمر الله سبحانه ( لَعَلَّكُمْ تُرْحَمُونَ ) أي لكي ترحموا في الدنيا والآخرة."},{"text":"ٱلَّذِينَ يُنفِقُونَ فِى ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلْكَـٰظِمِينَ ٱلْغَيْظَ وَٱلْعَافِينَ عَنِ ٱلنَّاسِ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ","tafsir":"أي بادروا ( إِلى مَغْفِرَةٍ مِنْ رَبِّكُمْ ) أي سبب المغفرة وهو الأعمال الصالحة الموجبة لغفرانه سبحانه ( وَ ) إلى ( جَنَّةٍ عَرْضُهَا ) أي سعتها ـ لا العرض مقابل الطول ـ ( السَّماواتُ وَالْأَرْضُ ) فهي واسعة وسع السماوات والأرض التي لا نهاية لها في التصور ـ فإن الفضاء الذي يعبّر عنه بالسماء مما لا يصل الفكر إلى آخره ونهايته ـ ( أُعِدَّتْ ) وهيّأت ( لِلْمُتَّقِينَ ) أي الذين يتقون المعاصي. الَّذِينَ يُنْفِقُونَ فِي السَّرَّاءِ وَالضَّرَّاءِ وَالْكاظِمِينَ الْغَيْظَ وَالْعافِينَ عَنِ النَّاسِ وَاللهُ يُحِبُّ الْمُحْسِنِينَ (134) وَالَّذِينَ إِذا فَعَلُوا فاحِشَةً أَوْ ظَلَمُوا أَنْفُسَهُمْ ذَكَرُوا اللهَ فَاسْتَغْفَرُوا لِذُنُوبِهِمْ وَمَنْ يَغْفِرُ الذُّنُوبَ إِلاَّ اللهُ وَلَمْ يُصِرُّوا عَلى ما فَعَلُوا وَهُمْ يَعْلَمُونَ (135) [135] ثم بيّن المتقين بقوله سبحانه : ( الَّذِينَ يُنْفِقُونَ ) أموالهم ( فِي السَّرَّاءِ وَالضَّرَّاءِ ) أي في حالتي اليسر والعسر ، أو حالتي السرور والاغتمام ( وَالْكاظِمِينَ الْغَيْظَ ) الذين يكظمون غيظهم ( وَالْعافِينَ عَنِ النَّاسِ ) يعفون عنهم إذا ظلموهم ( وَ ) من فعل ذلك فهو محسن إلى نفسه وإلى الناس و ( اللهُ يُحِبُّ الْمُحْسِنِينَ ) ولا يخفى أن المتقي هو الذي يجمع الصفات الحميدة كلها لكنها نثرت في القرآن الحكيم بمناسبات. وسوف نفسّر « المتقي » في كل مكان ببعض صفاته."},{"text":"وَٱلَّذِينَ إِذَا فَعَلُوا۟ فَـٰحِشَةً أَوْ ظَلَمُوٓا۟ أَنفُسَهُمْ ذَكَرُوا۟ ٱللَّهَ فَٱسْتَغْفَرُوا۟ لِذُنُوبِهِمْ وَمَن يَغْفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمْ يُصِرُّوا۟ عَلَىٰ مَا فَعَلُوا۟ وَهُمْ يَعْلَمُونَ","tafsir":""},{"text":"أُو۟لَـٰٓئِكَ جَزَآؤُهُم مَّغْفِرَةٌ مِّن رَّبِّهِمْ وَجَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ وَنِعْمَ أَجْرُ ٱلْعَـٰمِلِينَ","tafsir":"عطف على ( الَّذِينَ يُنْفِقُونَ ) أي أن المتقين هم الذين ( إِذا فَعَلُوا فاحِشَةً ) أي معصية تفحش ، أي تتجاوز الحد ( أَوْ ظَلَمُوا أَنْفُسَهُمْ ) بما لا يبلغ حد الفاحشة ، من سائر أقسام المعاصي ، فالفاحشة أخذ من مفهومها كون المعصية كبيرة ( ذَكَرُوا اللهَ ) أي تذكروا نهي الله وعقابه ( فَاسْتَغْفَرُوا لِذُنُوبِهِمْ ) أي طلبوا غفران الله وندموا على ما فعلوا ( وَمَنْ يَغْفِرُ الذُّنُوبَ إِلَّا اللهُ ) وهو استفهام استعطافي فالقرآن الحكيم يستعطف المذنبين نحو التوبة والاستغفار ( وَلَمْ يُصِرُّوا عَلى ما فَعَلُوا ) من المعاصي ، بل أقلعوا وندموا ( وَهُمْ يَعْلَمُونَ ) أي يعلمون كون الفعل خطيئة ، فلا يصرون أُولئِكَ جَزاؤُهُمْ مَغْفِرَةٌ مِنْ رَبِّهِمْ وَجَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ خالِدِينَ فِيها وَنِعْمَ أَجْرُ الْعامِلِينَ (136) قَدْ خَلَتْ مِنْ قَبْلِكُمْ سُنَنٌ فَسِيرُوا فِي الْأَرْضِ فَانْظُروا كَيْفَ كانَ عاقِبَةُ الْمُكَذِّبِينَ (137) هذا على الذنب مع علمهم به."},{"text":"قَدْ خَلَتْ مِن قَبْلِكُمْ سُنَنٌ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُكَذِّبِينَ","tafsir":"المتقون الذين هذه صفاتهم ( جَزاؤُهُمْ مَغْفِرَةٌ مِنْ رَبِّهِمْ ) يغفر ذنوبهم في الدنيا بسترها ، وفي الآخرة بالعفو عنها ( وَجَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ ) أي من تحت نخليها وأشجارها ( خالِدِينَ فِيها ) أبد الآبدين ( وَنِعْمَ أَجْرُ الْعامِلِينَ ) فإن الغفران والثواب من أفضل أجر العامل فإنّ أيّ أجر لا يبلغ مثل هذا الأمر الدائم الوارف."},{"text":"هَـٰذَا بَيَانٌ لِّلنَّاسِ وَهُدًى وَمَوْعِظَةٌ لِّلْمُتَّقِينَ","tafsir":"أي مضت وسبقت ( مِنْ قَبْلِكُمْ ) أيها المخاطبون ( سُنَنٌ ) جمع سنة بمعنى الطريقة ، فقد كانت في الأمم السالفة طرائق ، طريقة الحق وطريقة الباطل ، طريقة الخير وطريقة الشر .. وهكذا ( فَسِيرُوا فِي الْأَرْضِ ) اذهبوا إلى البلاد التي كانت فيها تلك الأمم المنقرضة ( فَانْظُروا كَيْفَ كانَ عاقِبَةُ الْمُكَذِّبِينَ ) أي تعرفوا على أخبارهم حتى تعلموا أنهم لم يربحوا وإنما أتوا وكذبوا الرسل وتأمروا ثم ماتوا ودفنوا ولم يبقى لهم ذكر طيب في الدنيا ولم تدم لهم النعمة التي من أجلها عملوا ما عملوا وإنما انتقلوا إلى عذاب الله سبحانه ، ليكون في ذلك عبرة لكم فلا تكونوا من المكذبين بل من المؤمنين المصدقين."},{"text":"وَلَا تَهِنُوا۟ وَلَا تَحْزَنُوا۟ وَأَنتُمُ ٱلْأَعْلَوْنَ إِن كُنتُم مُّؤْمِنِينَ","tafsir":"القرآن ، أو هذا الذي ذكرنا من أحوال المؤمن والكافر ، وما بَيانٌ لِلنَّاسِ وَهُدىً وَمَوْعِظَةٌ لِلْمُتَّقِينَ (138) وَلا تَهِنُوا وَلا تَحْزَنُوا وَأَنْتُمُ الْأَعْلَوْنَ إِنْ كُنْتُمْ مُؤْمِنِينَ (139) إِنْ يَمْسَسْكُمْ قَرْحٌ فَقَدْ مَسَّ الْقَوْمَ قَرْحٌ مِثْلُهُ قدمنا من العظة والإنذار ( بَيانٌ لِلنَّاسِ ) دلالة وحجة وتوضيح لهم كيف ينبغي أن يسلكوا ويعملوا ( وَهُدىً ) يهديهم إلى الحق ( وَمَوْعِظَةٌ ) وعظ وإرشاد ( لِلْمُتَّقِينَ ) فإنهم هم الذين يستفيدون منه ، وإن كان بيانا للناس عامة. [140] وهنا يرجع السياق إلى ذكر غزوة أحد ، لتشجيع المؤمنين وتصبيرهم على تحمّل المكاره ، بعد ما بيّن أحوال المؤمن والكافر ، حتى تقوى عزيمتهم ، وتطمئن قلوبهم ( وَلا تَهِنُوا ) من الوهن أي لا تضعفوا عن قتال الأعداء ( وَلا تَحْزَنُوا ) مما نالكم من القتل والجرح والهزيمة ( وَأَنْتُمُ الْأَعْلَوْنَ ) الظافرون الغالبون فإن الظفر يذهب بحرارة الخسارة ( إِنْ كُنْتُمْ مُؤْمِنِينَ ) فإن من كان مؤمنا لا يهن ولا يحزن فإن طاقة الإيمان تؤمّن الإنسان بالقوة والفرح أما القوة فهي مستمدة من الله سبحانه وأما الفرح فللغلبة أو لثواب الله سبحانه فيما لو غلب. [141] ثم بيّن سبحانه أن ما أصابهم من المكاره ليس خاصا بهم بل أصاب الكافرين مثل ما أصابهم فهم في ذلك سواء ، لكن المؤمنين يرجون ثواب الله سبحانه مما لا يترقّبه الكافرون فهم أجدر بالصبر والثبات وعدم الوهن والحزن ( إِنْ يَمْسَسْكُمْ ) أي يصبكم أيها المسلمون في غزوة أحد ( قَرْحٌ ) جرح وألم في أحد ( فَقَدْ مَسَّ الْقَوْمَ ) الكافرين ( قَرْحٌ مِثْلُهُ ) في أحد حيث أصيب الكفار بالألم والجرح أيضا ، أو المراد مسّهم القرح في بدر حيث قتل المشركون وَتِلْكَ الْأَيَّامُ نُداوِلُها بَيْنَ النَّاسِ وَلِيَعْلَمَ اللهُ الَّذِينَ آمَنُوا وَيَتَّخِذَ مِنْكُمْ شُهَداءَ وَاللهُ لا يُحِبُّ الظَّالِمِينَ (140) وهزموا ( وَتِلْكَ الْأَيَّامُ ) أيام النصر والهزيمة وأيام القرح ( نُداوِلُها ) أي نصرّفها ( بَيْنَ النَّاسِ ) فيوم لهؤلاء على أولئك ، ويوم لأولئك على هؤلاء ، فإذا نصرنا المؤمنين كان ذلك لإيمانهم وإذا هزموا كان امتحانا لهم. ( وَلِيَعْلَمَ اللهُ الَّذِينَ آمَنُوا ) أي أن صرف الأيام ليتميز المؤمن الحقيقي من غيره فإنه « عند تقلب الأحوال تعرف جواهر الرجال » (1) و « عند الامتحان يكرم الرجل أو يهان » (2) ، ومعنى « ليعلم » أن معلومه سبحانه يقع في الخارج ، لا أنه كان جاهلا ـ سبحانه ـ ثم علم ، فإن العلم لما كان أمرا إضافيا بين العالم والمعلوم ، يقال علم باعتبارين ، أما باعتبار العالم فيما كان جاهلا ثم علم ، وأما باعتبار المعلوم فيما كان المعلوم غير خارجي ثم صار خارجيا ( وَ ) ل ( يَتَّخِذَ مِنْكُمْ شُهَداءَ ) أي أن مداولة الأيام لفوائد ومن جملة تلك الفوائد أن يتخذ الله سبحانه منكم مقتولين يستشهدون في سبيل الله ويبلغون الدرجات الراقية بالشهادة ، أو ليكون جماعة شهداء على آخرين بالصبر أو الجزع ، بالثبات أو الهزيمة ، فإن إيصال جماعة قابلة إلى مرتبة أن يكونوا شهداء نعمة وغرض رفيع ، لكن المعنى الأول أقرب ( وَاللهُ لا يُحِبُّ الظَّالِمِينَ ) الذين يظلمون أنفسهم بالكفر ، أو بالهزيمة. ( 1) راجع بحار الأنوار : ج 71 ص 163. ( 2) غرر الحكم : ص 100. وَلِيُمَحِّصَ اللهُ الَّذِينَ آمَنُوا وَيَمْحَقَ الْكافِرِينَ (141) أَمْ حَسِبْتُمْ أَنْ تَدْخُلُوا الْجَنَّةَ وَلَمَّا يَعْلَمِ اللهُ الَّذِينَ جاهَدُوا مِنْكُمْ وَيَعْلَمَ الصَّابِرِينَ (142)"},{"text":"إِن يَمْسَسْكُمْ قَرْحٌ فَقَدْ مَسَّ ٱلْقَوْمَ قَرْحٌ مِّثْلُهُۥ ۚ وَتِلْكَ ٱلْأَيَّامُ نُدَاوِلُهَا بَيْنَ ٱلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَتَّخِذَ مِنكُمْ شُهَدَآءَ ۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّـٰلِمِينَ","tafsir":""},{"text":"وَلِيُمَحِّصَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَمْحَقَ ٱلْكَـٰفِرِينَ","tafsir":""},{"text":"أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَـٰهَدُوا۟ مِنكُمْ وَيَعْلَمَ ٱلصَّـٰبِرِينَ","tafsir":"من فوائد تداول الأيام بين الناس أنه ( لِيُمَحِّصَ اللهُ الَّذِينَ آمَنُوا ) أي يخلّصهم من المنافقين فيتبين المؤمن من المنافق ، أو يخلصهم من الذنوب ، فإن بالأهوال تذاب الذنوب ، وبالشدائد تكفّر الخطايا ( وَ ) ل ( يَمْحَقَ الْكافِرِينَ ) يهلكهم ، فإن الكفار ينقصون شيئا فشيئا حتى يهلكوا جميعا. [143] ثم يبين سبحانه فائدة أخرى لتداول الأيام وهي أن المؤمن لا يدخل الجنة بمجرد إظهار الشهادتين وإنما اللازم أن يجاهد ويعمل وفي تداول الأيام يحصل هذا العمل وهذا الامتحان المؤهل لدخول الجنة ، لكنه جاء الكلام في صورة الاستفهام تلوينا في الكلام ، وتفنّنا في التعبير ( أَمْ حَسِبْتُمْ ) أي هل حسبتم وظننتم أيها المسلمون ( أَنْ تَدْخُلُوا الْجَنَّةَ ) بمجرد الإيمان بدون الامتحان ( وَلَمَّا يَعْلَمِ اللهُ الَّذِينَ جاهَدُوا مِنْكُمْ ) أي لم يقع منكم جهاد حتى يتعلق علم الله به ( وَ ) لما ( يَعْلَمَ الصَّابِرِينَ ) فلم يقع منهم صبر حتى يتعلق به علم الله سبحانه ودخول الجنة بدون الجهاد والصبر لا يكون ، فتداول الأيام يوجب جهاد المؤمنين وصبرهم حتى يتأهلوا لدخول الجنة. [144] ثم يشير القرآن الحكيم إلى تأنيب المؤمنين في موقفهم يوم أحد ، حيث أن جماعة منهم قبل الغزوة كانوا يتطلعون إلى الجهاد ويتمنون الاستشهاد ثم فروا منهزمين ، وفوق ذلك أن إيمان بعضهم كان بدرجة وَلَقَدْ كُنْتُمْ تَمَنَّوْنَ الْمَوْتَ مِنْ قَبْلِ أَنْ تَلْقَوْهُ فَقَدْ رَأَيْتُمُوهُ وَأَنْتُمْ تَنْظُرُونَ (143) وَما مُحَمَّدٌ إِلاَّ رَسُولٌ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُ أَ فَإِنْ ماتَ أَوْ قُتِلَ انْقَلَبْتُمْ عَلى أَعْقابِكُمْ وَمَنْ يَنْقَلِبْ عَلى عَقِبَيْهِ فَلَنْ يَضُرَّ اللهَ شَيْئاً وَسَيَجْزِي اللهُ الشَّاكِرِينَ (144) من الوهن حتى أنهم لما سمعوا بموت الرسول صلى‌الله‌عليه‌وآله‌وسلم كادوا أن يرتدوا ( وَلَقَدْ كُنْتُمْ ) أيها المؤمنون ( تَمَنَّوْنَ الْمَوْتَ مِنْ قَبْلِ أَنْ تَلْقَوْهُ ) ولقاء الموت كناية عن لقاء مقدماته والوقوع في الأهوال المنتهية إليه ( فَقَدْ رَأَيْتُمُوهُ ) في الغزوة إذ رأيتم غلبة الكفار وقتل جماعة من المؤمنين ( وَأَنْتُمْ تَنْظُرُونَ ) أي تشاهدون المعركة ، وهذا تأكيد لمعنى « رأيتموه » حتى لا يتوهم أحد أن الرؤية كانت بالقلب ، فإن « رأى » يستعمل بمعنى « علم » ."},{"text":"وَلَقَدْ كُنتُمْ تَمَنَّوْنَ ٱلْمَوْتَ مِن قَبْلِ أَن تَلْقَوْهُ فَقَدْ رَأَيْتُمُوهُ وَأَنتُمْ تَنظُرُونَ","tafsir":""},{"text":"وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ ۚ أَفَإِي۟ن مَّاتَ أَوْ قُتِلَ ٱنقَلَبْتُمْ عَلَىٰٓ أَعْقَـٰبِكُمْ ۚ وَمَن يَنقَلِبْ عَلَىٰ عَقِبَيْهِ فَلَن يَضُرَّ ٱللَّهَ شَيْـًٔا ۗ وَسَيَجْزِى ٱللَّهُ ٱلشَّـٰكِرِينَ","tafsir":""},{"text":"وَمَا كَانَ لِنَفْسٍ أَن تَمُوتَ إِلَّا بِإِذْنِ ٱللَّهِ كِتَـٰبًا مُّؤَجَّلًا ۗ وَمَن يُرِدْ ثَوَابَ ٱلدُّنْيَا نُؤْتِهِۦ مِنْهَا وَمَن يُرِدْ ثَوَابَ ٱلْـَٔاخِرَةِ نُؤْتِهِۦ مِنْهَا ۚ وَسَنَجْزِى ٱلشَّـٰكِرِينَ","tafsir":"صلى‌الله‌عليه‌وآله‌وسلم ( إِلَّا رَسُولٌ ) أي ليس هو إلها لا يموت إنما هو بشر اختاره الله للرسالة فيجري عليه ما يجري على البشر من الموت والقتل ، وليس بدعا من الرسل بل ( قَدْ خَلَتْ ) أي مضت وتقدمت ( مِنْ قَبْلِهِ الرُّسُلُ ) الذين جرت عليهم سنة الله من الموت ومفارقة الحياة ( أَ فَإِنْ ماتَ ) موتا اعتياديا ( أَوْ قُتِلَ ) واستشهد ( انْقَلَبْتُمْ عَلى أَعْقابِكُمْ ) استفهام إنكاري توبيخي أي لم يكن حالكم هكذا ، حتى ترتدّوا بموت النبي ، وكنى عن الارتداد بالمشي القهقرى « الانقلاب على الأعقاب » الذي هو رجوع نحو الوراء ( وَمَنْ يَنْقَلِبْ عَلى عَقِبَيْهِ ) أي من يرتد عن دينه ( فَلَنْ يَضُرَّ اللهَ شَيْئاً ) إذ الله سبحانه غني مطلق لا يحتاج إلى إيمان أحد حتى يضره ارتداده ( وَسَيَجْزِي اللهُ الشَّاكِرِينَ ) الذين يشكرون نعمة الإيمان ويثبتون عليه وَما كانَ لِنَفْسٍ أَنْ تَمُوتَ إِلاَّ بِإِذْنِ اللهِ كِتاباً مُؤَجَّلاً وَمَنْ يُرِدْ ثَوابَ الدُّنْيا نُؤْتِهِ مِنْها وَمَنْ يُرِدْ ثَوابَ الْآخِرَةِ نُؤْتِهِ مِنْها وَسَنَجْزِي الشَّاكِرِينَ (145) فإن الارتداد من أعظم أقسام الكفر ، كما قال سبحانه : ( بَلِ اللهُ يَمُنُّ عَلَيْكُمْ أَنْ هَداكُمْ لِلْإِيمانِ ) (1) . [146] وهنا تلميح إلى عتاب آخر موجّه للمسلمين لانهزامهم يوم أحد خوف الموت ، فلم الفرار ؟ أمن خوف الموت ، وليس الموت إلا بإذن الله تعالى ، وما قدّر من أجل للإنسان ، فالفرار وعدمه سيان بالنسبة إلى الوقت المحدد لحياة الإنسان ( وَما كانَ لِنَفْسٍ أَنْ تَمُوتَ ) إن النفوس ليست هملا حتى تموت من تموت وتبقى من تبقى بأسباب عادية من غير توسط مشيئة الباري سبحانه ، فإن الموت لا يكون ( إِلَّا بِإِذْنِ اللهِ ) ومشيئته ( كِتاباً مُؤَجَّلاً ) أي كتب الله ذلك الوقت في اللوح المحفوظ كتابا ذا أجل ومدة محدودة معلومة ( وَمَنْ يُرِدْ ثَوابَ الدُّنْيا ) وخيرها وتعب وعمل لأجل المنافع الدنيوية ( نُؤْتِهِ مِنْها ) فإن الذي عمل يرى الله نتيجة عمله ( وَمَنْ يُرِدْ ثَوابَ الْآخِرَةِ ) وخيرها وعمل لأجل ثواب الآخرة ( نُؤْتِهِ مِنْها ) بقدر ما عمل ، فارغبوا أيها المسلمون في ثواب الله وأجره الأخروي بالجهاد والثبات ولا تفروا كما فررتم في أحد ( وَسَنَجْزِي الشَّاكِرِينَ ) جزاء حسنا ، ومن الشكر يعرف الإنسان قيمة ما خوّله الله سبحانه من الإسلام ووفقه للجهاد بين يدي رسوله لإعلاء كلمة الله ، فمن شكر ذلك يجزى جزاء الشاكرين. ( 1) الحجرات : 18. وَكَأَيِّنْ مِنْ نَبِيٍّ قاتَلَ مَعَهُ رِبِّيُّونَ كَثِيرٌ فَما وَهَنُوا لِما أَصابَهُمْ فِي سَبِيلِ اللهِ وَما ضَعُفُوا وَمَا اسْتَكانُوا وَاللهُ يُحِبُّ الصَّابِرِينَ (146) وَما كانَ قَوْلَهُمْ إِلاَّ أَنْ قالُوا رَبَّنَا اغْفِرْ لَنا ذُنُوبَنا وَإِسْرافَنا فِي أَمْرِنا وَثَبِّتْ أَقْدامَنا وَانْصُرْنا عَلَى الْقَوْمِ الْكافِرِينَ (147) [147] وما لكم أيها المسلمون وهنتم في غزوة أحد وفررتم ؟ ألم يمكنكم الاقتداء بالمؤمنين السابقين الذين كانوا مع الأنبياء يصمدون في وجه الباطل ؟ ( وَكَأَيِّنْ مِنْ نَبِيٍّ قاتَلَ مَعَهُ رِبِّيُّونَ كَثِيرٌ ) فإن كثيرا من الأنبياء عليه‌السلام قاتلوا ، وجاهد معهم وتحت لوائهم أناس من المؤمنين ربانيين منسوبون إلى الرب تعالى بالطاعة والعبادة والإيمان ، أو بمعنى أخيار فقهاء ( فَما وَهَنُوا ) أي ما فتروا ( لِما أَصابَهُمْ ) من القتل والسلب والجروح والقروح ( فِي سَبِيلِ اللهِ ) للتنبيه على شدائدهم التي كانت في سبيل الله سبحانه ( وَما ضَعُفُوا ) عن عدوهم ( وَمَا اسْتَكانُوا ) أي ما خضعوا ولا تضرعوا لعدوهم ( وَاللهُ يُحِبُّ الصَّابِرِينَ ) الذين يصبرون في الشدائد وفي الحروب."},{"text":"وَكَأَيِّن مِّن نَّبِىٍّ قَـٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرٌ فَمَا وَهَنُوا۟ لِمَآ أَصَابَهُمْ فِى سَبِيلِ ٱللَّهِ وَمَا ضَعُفُوا۟ وَمَا ٱسْتَكَانُوا۟ ۗ وَٱللَّهُ يُحِبُّ ٱلصَّـٰبِرِينَ","tafsir":""},{"text":"وَمَا كَانَ قَوْلَهُمْ إِلَّآ أَن قَالُوا۟ رَبَّنَا ٱغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِىٓ أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَـٰفِرِينَ","tafsir":""},{"text":"فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنْيَا وَحُسْنَ ثَوَابِ ٱلْـَٔاخِرَةِ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ","tafsir":"أي قول أولئك الربانيون عند الجهاد وملاقاة الأعداء ( إِلَّا أَنْ قالُوا رَبَّنَا اغْفِرْ لَنا ذُنُوبَنا ) فكانوا يستغفرون عند اللقاء مما فات منهم من الذنوب استعدادا للقاء الله سبحانه طاهرين ( وَإِسْرافَنا فِي أَمْرِنا ) أي تجاوزنا الحدود وتفريطنا وتقصيرنا ( وَثَبِّتْ أَقْدامَنا ) حتى لا تزل أمام الأعداء فننهزم ( وَانْصُرْنا عَلَى الْقَوْمِ الْكافِرِينَ ) فهم جاهدوا وجلين من ذنوبهم لم يطلبوا إلا العفو في تواضع وخشوع ، ولم يقصدوا إلا نصرة الدين على القوم الكافرين. فَآتاهُمُ اللهُ ثَوابَ الدُّنْيا وَحُسْنَ ثَوابِ الْآخِرَةِ وَاللهُ يُحِبُّ الْمُحْسِنِينَ (148) يا أَيُّهَا الَّذِينَ آمَنُوا إِنْ تُطِيعُوا الَّذِينَ كَفَرُوا يَرُدُّوكُمْ عَلى أَعْقابِكُمْ فَتَنْقَلِبُوا خاسِرِينَ (149) [149] فجزاء على ما سلف منهم من الصبر والثبات والجهاد في خشوع وتواضع آتاهم ( اللهُ ) أي أعطاهم الله سبحانه ( ثَوابَ الدُّنْيا ) بالفتح والغلبة والعزة والرفاه ( وَحُسْنَ ثَوابِ الْآخِرَةِ ) بجنات تجري من تحتها الأنهار ، أي ثواب الآخرة الحسن ، والإتيان بكلمة « حسن » هنا دون « ثواب الدنيا » لعله للإشارة إلى أن ثواب الآخرة هو الذي يوصف بالحسن ، أما الدنيا فإنها زائلة فلا قيمة لثوابها ، أو المراد « أحسن » أقسام ثواب الآخرة الذي لا يعطى إلا للمجاهدين ، بخلاف الدنيا فإن ثوابها عام للبرّ والفاجر ( وَاللهُ يُحِبُّ الْمُحْسِنِينَ ) ومحبة الله سبحانه فوق كل ثواب كما قال : ( وَرِضْوانٌ مِنَ اللهِ وَاللهُ بَصِيرٌ بِالْعِبادِ ) (1) . [150] لما اشتد الأمر يوم أحد أخذ جماعة من المنافقين يدعون الناس إلى الارتداد عن دينهم حتى يستريحوا فأنزل الله فيهم : ( يا أَيُّهَا الَّذِينَ آمَنُوا إِنْ تُطِيعُوا الَّذِينَ كَفَرُوا ) من المنافقين ، أو من اليهود والنصارى الذين أخذوا يشيعون أن محمدا صلى‌الله‌عليه‌وآله‌وسلم قتل فارجعوا إلى دينكم وعشائركم ( يَرُدُّوكُمْ عَلى أَعْقابِكُمْ ) كفارا كما كنتم ( فَتَنْقَلِبُوا خاسِرِينَ ) قد خسرتم الدنيا والدين ، فإن دنيا الجاهلية كانت فوضى وفقرا ورذيلة. ( 1) آل عمران : 16. بَلِ اللهُ مَوْلاكُمْ وَهُوَ خَيْرُ النَّاصِرِينَ (150) سَنُلْقِي فِي قُلُوبِ الَّذِينَ كَفَرُوا الرُّعْبَ بِما أَشْرَكُوا بِاللهِ ما لَمْ يُنَزِّلْ بِهِ سُلْطاناً وَمَأْواهُمُ النَّارُ وَبِئْسَ مَثْوَى الظَّالِمِينَ (151) وَلَقَدْ صَدَقَكُمُ اللهُ وَعْدَهُ"},{"text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ ٱلَّذِينَ كَفَرُوا۟ يَرُدُّوكُمْ عَلَىٰٓ أَعْقَـٰبِكُمْ فَتَنقَلِبُوا۟ خَـٰسِرِينَ","tafsir":""},{"text":"بَلِ ٱللَّهُ مَوْلَىٰكُمْ ۖ وَهُوَ خَيْرُ ٱلنَّـٰصِرِينَ","tafsir":""},{"text":"سَنُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ بِمَآ أَشْرَكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَـٰنًا ۖ وَمَأْوَىٰهُمُ ٱلنَّارُ ۚ وَبِئْسَ مَثْوَى ٱلظَّـٰلِمِينَ","tafsir":"أي هو أولى بكم من الكفار والمنافقين ، وهو ينصركم على أعدائكم ( وَهُوَ خَيْرُ النَّاصِرِينَ ) لأن في نصرته خيرا للدارين بخلاف نصرة غيره."},{"text":"وَلَقَدْ صَدَقَكُمُ ٱللَّهُ وَعْدَهُۥٓ إِذْ تَحُسُّونَهُم بِإِذْنِهِۦ ۖ حَتَّىٰٓ إِذَا فَشِلْتُمْ وَتَنَـٰزَعْتُمْ فِى ٱلْأَمْرِ وَعَصَيْتُم مِّنۢ بَعْدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَ ۚ مِنكُم مَّن يُرِيدُ ٱلدُّنْيَا وَمِنكُم مَّن يُرِيدُ ٱلْـَٔاخِرَةَ ۚ ثُمَّ صَرَفَكُمْ عَنْهُمْ لِيَبْتَلِيَكُمْ ۖ وَلَقَدْ عَفَا عَنكُمْ ۗ وَٱللَّهُ ذُو فَضْلٍ عَلَى ٱلْمُؤْمِنِينَ","tafsir":"أي نقذف الخوف والفزع في قلوبهم حتى تغلبوهم وهكذا ينصركم الله تعالى ( بِما أَشْرَكُوا بِاللهِ ) أي بسبب شركهم ( ما لَمْ يُنَزِّلْ بِهِ سُلْطاناً ) أي برهانا وحجة ، فإن شركهم كان تقليدا لا عن دليل وحجة ( وَمَأْواهُمُ ) أي محلهم ومستقرّهم ( النَّارُ ) في الآخرة ( وَبِئْسَ مَثْوَى الظَّالِمِينَ ) أي أن النار بئس مقام الظالمين الذين ظلموا أنفسهم بالكفر. وقد ورد أن الآية نزلت حين همّ المشركون ـ يوم أحد ـ بالرجوع إلى المسلمين لاستئصالهم عن آخرهم فلما عزموا ذلك ألقى الله في قلوبهم الرعب حتى رجعوا عما هموا به ، ولا يخفى أن إلقاء الرعب في قلب الكافر أمر طبيعي فإن المسلم يستمد القوة من الله سبحانه أما الكافر فحيث لا يعتقد به سبحانه يكون قلبه هواء فيتسرب إليه الخوف. [153] ثم بيّن سبحانه أن هزيمتهم يوم أحد لم تكن إلا بسبب مخالفتهم أوامر الله والرسول صلى‌الله‌عليه‌وآله‌وسلم ، وإلا فالله سبحانه نصرهم كما وعد ، حتى هزموا المشركين ( وَلَقَدْ صَدَقَكُمُ اللهُ وَعْدَهُ ) وفي لكم بما وعد من نصرتكم إِذْ تَحُسُّونَهُمْ بِإِذْنِهِ حَتَّى إِذا فَشِلْتُمْ وَتَنازَعْتُمْ فِي الْأَمْرِ وَعَصَيْتُمْ مِنْ بَعْدِ ما أَراكُمْ ما تُحِبُّونَ مِنْكُمْ مَنْ يُرِيدُ الدُّنْيا وَمِنْكُمْ مَنْ يُرِيدُ الْآخِرَةَ ثُمَّ صَرَفَكُمْ عَنْهُمْ على الكفار ( إِذْ تَحُسُّونَهُمْ بِإِذْنِهِ ) أي تقتلونهم ، فإن « حسّه » بمعنى قتله وأبطل حسّه وحياته ، ومعنى « بإذنه » : بأمره ، فإن الله أذن لهم في القتال كما قال : ( أُذِنَ لِلَّذِينَ يُقاتَلُونَ بِأَنَّهُمْ ظُلِمُوا ) (1) ، ( حَتَّى إِذا فَشِلْتُمْ ) جبنتم وكففتم وخالفتم أمر الرسول ( وَتَنازَعْتُمْ فِي الْأَمْرِ ) هل يبقى الرماة الخمسون في الشعب كما أمرهم الرسول أم يخرجوا يجمعون الغنائم ؟ ـ كما تقدم ـ ( وَ ) بالآخر ( عَصَيْتُمْ ) أمر الرسول في لزوم أماكنكم فتخليتم عن الشعب ، فقد تخلى من الخمسين سبع وثلاثون ( مِنْ بَعْدِ ما أَراكُمْ ) الله سبحانه ( ما تُحِبُّونَ ) من هزيمة الكفار ونصرة المسلمين ( مِنْكُمْ ) أيها المسلمون ( مَنْ يُرِيدُ الدُّنْيا ) وهم الذين خالفوا الرسول طلبا للغنيمة ( وَمِنْكُمْ مَنْ يُرِيدُ الْآخِرَةَ ) وهم : عبد الله رئيس الرماة في الشعب واثني عشر من أصحابه الذين ثبتوا في أماكنهم ( ثُمَّ صَرَفَكُمْ ) أيها المسلمون ( عَنْهُمْ ) أي عن الكفار ، بل توجهتم إلى الغنائم عوض أن تحتفظوا بأماكنكم ، فإن في حفظ المكان كان توجها نحو الكفار لئلا يرجعوا إلى المسلمين من ورائهم ، بخلاف التوجه نحو الغنيمة فإنه كان صرفا عن الكفار ، وإضافته إليه سبحانه كسائر الإضافات نحو « ومن يضلل » أو باعتبار أن الصرف كان عقوبة لهم على إرادتهم للدنيا ( 1) الحج : 40. لِيَبْتَلِيَكُمْ وَلَقَدْ عَفا عَنْكُمْ وَاللهُ ذُو فَضْلٍ عَلَى الْمُؤْمِنِينَ (152) إِذْ تُصْعِدُونَ وَلا تَلْوُونَ عَلى أَحَدٍ وَالرَّسُولُ يَدْعُوكُمْ فِي أُخْراكُمْ فَأَثابَكُمْ غَمًّا بِغَمٍّ لِكَيْلا تَحْزَنُوا عَلى ما فاتَكُمْ وَلا ما أَصابَكُمْ وَاللهُ خَبِيرٌ ( لِيَبْتَلِيَكُمْ ) أي يمتحنكم ويختبركم ، حتى يظهر ما أنتم عاملون ( وَلَقَدْ عَفا ) الله سبحانه ( عَنْكُمْ ) خطيئتكم بمخالفة الرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَاللهُ ذُو فَضْلٍ عَلَى الْمُؤْمِنِينَ ) ينصرهم على أعدائهم ويعفو عن ذنوبهم ، ومعنى الفضل : المن والنعمة ، فإنه يعطيهم فضلا أي فوق استحقاقهم. [154] ولقد عفا عنكم ( إِذْ تُصْعِدُونَ ) أي تذهبون في وادي أحد للانهزام ، فإن الإصعاد الذهاب في الأرض ( وَلا تَلْوُونَ عَلى أَحَدٍ ) أي لا تلتفتون إلى أحد من ورائكم بل كل همكم السرعة في الفرار حتى لا يأتيكم الطلب ( وَالرَّسُولُ ) محمد صلى‌الله‌عليه‌وآله‌وسلم ( يَدْعُوكُمْ ) يناديكم ( فِي أُخْراكُمْ ) أي من ورائكم ، يقال : جاء فلان في آخر الناس أي من ورائهم ( فَأَثابَكُمْ ) أي جازاكم الله على فراركم ( غَمًّا ) متصلا ( بِغَمٍ ) غمّ الهزيمة وغمّ القتلى الذين قتلوا منكم ـ ويحتمل في اللفظين أمور ـ ( لِكَيْلا تَحْزَنُوا عَلى ما فاتَكُمْ ) من الخير ( وَلا ما أَصابَكُمْ ) من الضرر ، فإن الإنسان إذا وقع في الشدائد وجرّبها ومارسها تصلب نفسه وتقوى روحه فلا تتزحزح بمصيبة ولا تهتز بكارثة ، وهكذا كانت هزيمة أحد درسا وعبرة حتى يصغر في نفوس المسلمين كل ما يفوتهم من خيرات وكل ما يصيبهم من شرور وآلام ( وَاللهُ خَبِيرٌ ) ذو خبر واطلاع بِما تَعْمَلُونَ (153) ثُمَّ أَنْزَلَ عَلَيْكُمْ مِنْ بَعْدِ الْغَمِّ أَمَنَةً نُعاساً يَغْشى طائِفَةً مِنْكُمْ وَطائِفَةٌ قَدْ أَهَمَّتْهُمْ أَنْفُسُهُمْ يَظُنُّونَ بِاللهِ غَيْرَ الْحَقِّ ظَنَّ الْجاهِلِيَّةِ يَقُولُونَ هَلْ لَنا مِنَ الْأَمْرِ مِنْ شَيْءٍ قُلْ إِنَّ الْأَمْرَ كُلَّهُ لِلَّهِ يُخْفُونَ فِي أَنْفُسِهِمْ ما لا يُبْدُونَ لَكَ ( بِما تَعْلَمُونَ ) فيجازيكم على حسب أعمالكم."},{"text":"۞ إِذْ تُصْعِدُونَ وَلَا تَلْوُۥنَ عَلَىٰٓ أَحَدٍ وَٱلرَّسُولُ يَدْعُوكُمْ فِىٓ أُخْرَىٰكُمْ فَأَثَـٰبَكُمْ غَمًّۢا بِغَمٍّ لِّكَيْلَا تَحْزَنُوا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا مَآ أَصَـٰبَكُمْ ۗ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ","tafsir":""},{"text":"ثُمَّ أَنزَلَ عَلَيْكُم مِّنۢ بَعْدِ ٱلْغَمِّ أَمَنَةً نُّعَاسًا يَغْشَىٰ طَآئِفَةً مِّنكُمْ ۖ وَطَآئِفَةٌ قَدْ أَهَمَّتْهُمْ أَنفُسُهُمْ يَظُنُّونَ بِٱللَّهِ غَيْرَ ٱلْحَقِّ ظَنَّ ٱلْجَـٰهِلِيَّةِ ۖ يَقُولُونَ هَل لَّنَا مِنَ ٱلْأَمْرِ مِن شَىْءٍ ۗ قُلْ إِنَّ ٱلْأَمْرَ كُلَّهُۥ لِلَّهِ ۗ يُخْفُونَ فِىٓ أَنفُسِهِم مَّا لَا يُبْدُونَ لَكَ ۖ يَقُولُونَ لَوْ كَانَ لَنَا مِنَ ٱلْأَمْرِ شَىْءٌ مَّا قُتِلْنَا هَـٰهُنَا ۗ قُل لَّوْ كُنتُمْ فِى بُيُوتِكُمْ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيْهِمُ ٱلْقَتْلُ إِلَىٰ مَضَاجِعِهِمْ ۖ وَلِيَبْتَلِىَ ٱللَّهُ مَا فِى صُدُورِكُمْ وَلِيُمَحِّصَ مَا فِى قُلُوبِكُمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ","tafsir":""},{"text":"إِنَّ ٱلَّذِينَ تَوَلَّوْا۟ مِنكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ إِنَّمَا ٱسْتَزَلَّهُمُ ٱلشَّيْطَـٰنُ بِبَعْضِ مَا كَسَبُوا۟ ۖ وَلَقَدْ عَفَا ٱللَّهُ عَنْهُمْ ۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٌ","tafsir":"الله ( عَلَيْكُمْ مِنْ بَعْدِ الْغَمِ ) الذي غشيكم لهزيمتكم ( أَمَنَةً ) أي أمنا ( نُعاساً ) أي نوما ، وهو بدل اشتمال ل « أمنة » فإنهم ناموا من شدة التعب والنصب بعد ما ذهب خوفهم وذهب الكفار ، و « أمنة » مصدر كالعظمة والغلبة. لكن هذا النعاس كان ( يَغْشى طائِفَةً مِنْكُمْ ) فقط الذين كانوا يعلمون أن محمدا صلى‌الله‌عليه‌وآله‌وسلم حق وأن الله لا يتركه وأن ما أصابهم يوجب الثواب والفائدة لهم ( وَ ) هناك ( طائِفَةً ) ثانية كانوا مع النبي منافقين ( قَدْ أَهَمَّتْهُمْ أَنْفُسُهُمْ ) يفكّرون في هزيمتهم لا ينامون من الحزن والخوف حين انتشر بينهم أن الكفار عازمون على الرجوع وكانوا يشكّون في نصرة الله ولذا لم يتمكنوا أن يناموا خوفا ( يَظُنُّونَ بِاللهِ غَيْرَ الْحَقِ ) وأنه لا ينصر نبيه ( ظَنَّ الْجاهِلِيَّةِ ) من الكفار المكذبين بوعد الله سبحانه ( يَقُولُونَ ) ما في نفوسهم من ظنون الجاهلية : ( هَلْ لَنا مِنَ الْأَمْرِ ) أمر الغلبة والنصرة ( مِنْ شَيْءٍ ) في مقام الاستنكار والتعجب أن ينتصروا على الكفار إذا رجعوا ( قُلْ ) لهم يا رسول الله : ( إِنَّ الْأَمْرَ كُلَّهُ لِلَّهِ ) ينصر من يشاء ، فللمسلمين النصر والغلبة بإعطاء الله لهم إياها ( يُخْفُونَ ) هؤلاء المنافقين ( فِي أَنْفُسِهِمْ ) النفاق والكفر ( ما لا يُبْدُونَ لَكَ ) يَقُولُونَ لَوْ كانَ لَنا مِنَ الْأَمْرِ شَيْءٌ ما قُتِلْنا هاهُنا قُلْ لَوْ كُنْتُمْ فِي بُيُوتِكُمْ لَبَرَزَ الَّذِينَ كُتِبَ عَلَيْهِمُ الْقَتْلُ إِلى مَضاجِعِهِمْ وَلِيَبْتَلِيَ اللهُ ما فِي صُدُورِكُمْ وَلِيُمَحِّصَ ما فِي قُلُوبِكُمْ وَاللهُ عَلِيمٌ بِذاتِ الصُّدُورِ (154) إِنَّ الَّذِينَ تَوَلَّوْا مِنْكُمْ أي لا يتجرءون على إظهاره ( يَقُولُونَ لَوْ كانَ لَنا مِنَ الْأَمْرِ ) أي من النصرة والغلبة ( شَيْءٍ ) وكنا حقيقة منصورين ( ما قُتِلْنا ) أي ما قتل أصحابنا ( هاهُنا ) في غزوة أحد ( قُلْ ) يا رسول الله في جوابهم : إن كون الأمر لنا لا يلازم أن لا يقتل منا أحد فإن الإنسان يموت إذا جاء أجله ولو كان في داره ومنزله ( لَوْ كُنْتُمْ فِي بُيُوتِكُمْ لَبَرَزَ الَّذِينَ كُتِبَ عَلَيْهِمُ الْقَتْلُ إِلى مَضاجِعِهِمْ ) أي خرج الذين كتب عليهم القتل ـ بأن رقم موتهم في اللوح المحفوظ ـ إلى مصارعهم. و « مضاجع » جمع مضجع بمعنى محل النوم ( وَلِيَبْتَلِيَ اللهُ ما فِي صُدُورِكُمْ ) يختبر الله ما في صدوركم ، فإن ما في الصدور من الإخلاص والنفاق ، والثبات والوهن ، إنما يظهر عند الشدائد والمحن ، وهذا عطف على قوله : « ليبتليكم » أو مستأنفة ، أي فعل الله سبحانه ما فعل ليبتلي ( وَلِيُمَحِّصَ ) أي يخلص ( ما فِي قُلُوبِكُمْ ) بأن يكشفه للناس ولكم ، حيث أن الإنسان يظن أشياء فإذا حدث الحادث يظهر له خلاف ما كان يظن بنفسه ( وَاللهُ عَلِيمٌ بِذاتِ الصُّدُورِ ) فليس الامتحان لأن يعلم هو تعالى ، بل لأن يظهر ما يعلمه."},{"text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِينَ كَفَرُوا۟ وَقَالُوا۟ لِإِخْوَٰنِهِمْ إِذَا ضَرَبُوا۟ فِى ٱلْأَرْضِ أَوْ كَانُوا۟ غُزًّى لَّوْ كَانُوا۟ عِندَنَا مَا مَاتُوا۟ وَمَا قُتِلُوا۟ لِيَجْعَلَ ٱللَّهُ ذَٰلِكَ حَسْرَةً فِى قُلُوبِهِمْ ۗ وَٱللَّهُ يُحْىِۦ وَيُمِيتُ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ","tafsir":"أدبروا وانهزموا ( مِنْكُمْ ) أيها المسلمون يَوْمَ الْتَقَى الْجَمْعانِ إِنَّمَا اسْتَزَلَّهُمُ الشَّيْطانُ بِبَعْضِ ما كَسَبُوا وَلَقَدْ عَفَا اللهُ عَنْهُمْ إِنَّ اللهَ غَفُورٌ حَلِيمٌ (155) يا أَيُّهَا الَّذِينَ آمَنُوا لا تَكُونُوا كَالَّذِينَ كَفَرُوا وَقالُوا لِإِخْوانِهِمْ إِذا ضَرَبُوا فِي الْأَرْضِ أَوْ كانُوا غُزًّى لَوْ كانُوا عِنْدَنا ما ماتُوا وَما قُتِلُوا ( يَوْمَ الْتَقَى الْجَمْعانِ ) يوم أحد الذي التقى فيه جمع المسلمين بقيادة الرسول صلى‌الله‌عليه‌وآله‌وسلم بجمع المشركين بقيادة أبي سفيان ( إِنَّمَا اسْتَزَلَّهُمُ الشَّيْطانُ ) طلب زلتهم وعصيانهم ( بِبَعْضِ ما كَسَبُوا ) أي بسبب بعض المعاصي التي كانوا يعملونها فأخذتهم عاقبتها وشؤمها ( وَلَقَدْ عَفَا اللهُ عَنْهُمْ ) بعد ما ندموا ورجعوا ( إِنَّ اللهَ غَفُورٌ ) يغفر للمذنب إذا تاب ( حَلِيمٌ ) لا يعجل بالعقوبة بل يمهل المذنب كي يتوب ويئوب."},{"text":"وَلَئِن قُتِلْتُمْ فِى سَبِيلِ ٱللَّهِ أَوْ مُتُّمْ لَمَغْفِرَةٌ مِّنَ ٱللَّهِ وَرَحْمَةٌ خَيْرٌ مِّمَّا يَجْمَعُونَ","tafsir":"اعتقادا ، وهم الكفار الذين لا يدينون بما وراء الغيب ، أو كفروا عملا وهم المنافقون ومن أشبههم ( وَقالُوا لِإِخْوانِهِمْ ) في العقيدة ، أو في الإنسانية ، حتى يشمل قول الكافرين للمؤمنين وقوله : « لإخوانهم » أي قالوا بالنسبة إلى الإخوان الذين سافروا فماتوا ، أو حاربوا فقتلوا ( إِذا ضَرَبُوا فِي الْأَرْضِ ) أي ذهبوا لأجل التجارة ونحوها ، يقال : ضرب فلان في الأرض إذا سافر ، وتخصيص الأرض بالذكر ، لكون السفر غالبا عن طريق البر ( أَوْ كانُوا غُزًّى ) جمع « غاز » ، أي حاربوا الأعداء : ( لَوْ كانُوا عِنْدَنا ) مقيمين في أوطانهم ( ما ماتُوا وَما قُتِلُوا ) فقد حسبوا أن الموت والقتل إنما هما لِيَجْعَلَ اللهُ ذلِكَ حَسْرَةً فِي قُلُوبِهِمْ وَاللهُ يُحْيِي وَيُمِيتُ وَاللهُ بِما تَعْمَلُونَ بَصِيرٌ (156) بالأسباب الطبيعية بما وراء المادة والإحساس. مع أن الموت والقتل لا يكونان إلا بتقدير وقضاء وليس يفيد في ذلك البقاء ، وفي هذا رد لإرجاف المنافقين الذين كانوا يلقون تبعة قتل المؤمنين في أحد على النبي وأنه صلى‌الله‌عليه‌وآله‌وسلم أخرجهم فقتلوا ، ومعنى القضاء والقدر في الأمور التكوينية : التخطيط وتهيئة الأسباب ، فكما أن المهندس الذي يريد بناء دار يخطط شكل الدار المراد بنائها ثم يحضر مواد البناء من آجر وجص وحديد وخشب ، كذلك ما في العالم من الأمور التكوينية خططت وعلمها الله سبحانه وأحضرت موادها. لكن ليس معنى ذلك أن الأمور خارجة عن أيدي البشر وإنما جعل الدعاء والصدقة والأسباب الظاهرة مستثنيات للتخطيط والآلات والأسباب وكل ذلك أيضا بعلمه سبحانه ، وعلى كلّ فليس الموت والقتل مما يكون سببهما السفر والغزو كما زعمه الكفار بل هناك أسباب خفية تدير هذين الأمرين إلى جنب الأسباب الظاهرية ، فليس كل سفر وغزو موجبا للموت كما ليس كل إقامة موجبا للبقاء ، والكفار إنما قالوا ذلك يريدون تثبيط الناس عن الجهاد ( لِيَجْعَلَ اللهُ ذلِكَ ) الاعتقاد ـ المفهوم من الكلام ـ ( حَسْرَةً فِي قُلُوبِهِمْ ) لما حصل لهم من الخيبة حيث رأوا رجوع إخوانهم من السفر والجهاد بالربح والظفر ، ومن الطبيعي أن يحزن ويخسر الشخص الجامد لما ناله الشخص المتحرك من الخير والتقدم المحتومين ، واللام في « ليجعل » إما لام الأمر ، لبيان التأكيد ، أو لام العاقبة ، أي كانت عاقبة هذا الاعتقاد الحسرة والحزن ( وَاللهُ يُحْيِي ) الأرض والجماد والإنسان ( وَيُمِيتُ ) فليس السفر والغزو تمام سبب الموت ( وَاللهُ بِما تَعْمَلُونَ بَصِيرٌ ) فارغبوا في الطاعة وَلَئِنْ قُتِلْتُمْ فِي سَبِيلِ اللهِ أَوْ مُتُّمْ لَمَغْفِرَةٌ مِنَ اللهِ وَرَحْمَةٌ خَيْرٌ مِمَّا يَجْمَعُونَ (157) وَلَئِنْ مُتُّمْ أَوْ قُتِلْتُمْ لَإِلَى اللهِ تُحْشَرُونَ (158) فَبِما رَحْمَةٍ مِنَ اللهِ لِنْتَ لَهُمْ والجهاد ، واحذروا من المخالفة والفرار ، فإن الله سبحانه يعلم أعمالكم ، ويبصر صنعكم. [158] ثم لنفرض أن السفر والغزو سبب الموت فهل الموت مع المغفرة خير أم الحياة لجمع الأموال التي يحياها الكافر الذي يبقى في بلده ( وَلَئِنْ قُتِلْتُمْ ) أيها المؤمنون ( فِي سَبِيلِ اللهِ ) وجهاد أعدائه ( أَوْ مُتُّمْ ) في سبيل اكتساب الرزق والتجارة والضرب في الأرض ( لَمَغْفِرَةٌ مِنَ اللهِ وَرَحْمَةٌ ) حيث يغفر لكم ويرحمكم حيث كنتم مطيعين له ممتثلين أمره ( خَيْرٌ مِمَّا يَجْمَعُونَ ) أي يجمع هؤلاء الكفار الباقون في بلدهم خوفا من الخروج ، فإن من يبقى يكتسب ويجمع مالا. [159] ثم أن الموت والقتل لا يسببان انقطاع الحياة حتى يخشاهما الإنسان ويرفع اليد عن مقاصده العالية من خشيتهما ( وَلَئِنْ مُتُّمْ أَوْ قُتِلْتُمْ لَإِلَى اللهِ تُحْشَرُونَ ) فيجازيكم على أعمالكم فخير لكم أن تطيعوه حتى تكونوا مرادا لثوابه وفضله. [160] وهنا يلتفت السياق ليثير في النبي صلى‌الله‌عليه‌وآله‌وسلم عاطفته الكامنة نحو المؤمنين حتى يعفو عن خطأهم في أحد ، حيث أخلوا الشعب حتى سيطر المشركون على المعركة ، وفعلوا تلك الأفاعيل بالنبي صلى‌الله‌عليه‌وآله‌وسلم وأصحابه من جرح وقتل وتمثيل ( فَبِما رَحْمَةٍ مِنَ اللهِ ) « ما » زائدة أي بسبب رحمة من الله سبحانه على المؤمنين ( لِنْتَ لَهُمْ ) أي كنت لينا رحيما بهم فقد وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لانْفَضُّوا مِنْ حَوْلِكَ فَاعْفُ عَنْهُمْ وَاسْتَغْفِرْ لَهُمْ وَشاوِرْهُمْ فِي الْأَمْرِ فَإِذا عَزَمْتَ فَتَوَكَّلْ عَلَى اللهِ إِنَّ اللهَ يُحِبُّ الْمُتَوَكِّلِينَ (159) إِنْ يَنْصُرْكُمُ اللهُ فَلا غالِبَ لَكُمْ وَإِنْ يَخْذُلْكُمْ فَمَنْ ذَا الَّذِي يَنْصُرُكُمْ مِنْ بَعْدِهِ جعله الله سبحانه رحيما بهم لينا عليهم ( وَلَوْ كُنْتَ ) يا رسول الله ( فَظًّا ) جافي اللسان قاسي القلب ( غَلِيظَ الْقَلْبِ ) غلظا معنويا وهو الذي لا يلين ولا يحنو ( لَانْفَضُّوا مِنْ حَوْلِكَ ) أي تفرقوا عنك ( فَاعْفُ عَنْهُمْ ) إذا أخطئوا ( وَاسْتَغْفِرْ لَهُمْ ) أي اطلب لهم من الله الغفران لما صدر من ذنوبهم ، والله سبحانه وإن كان أرحم بهم لكن ذلك لزيادة عطف النبي ، فإن من يطلب المغفرة لأحد لا بد وأن يزول من قلبه ما علق به من الكراهية ، ولتكثير محبة المؤمنين له صلى‌الله‌عليه‌وآله‌وسلم حيث يعلمون بأنه يستغفر لهم ( وَشاوِرْهُمْ فِي الْأَمْرِ ) لتأليف قلوبهم ولتعليمهم المشورة في أمورهم ، فإن النبي صلى‌الله‌عليه‌وآله‌وسلم كان في غنى عنهم بما كان يسدّده الله سبحانه بالوحي ( فَإِذا عَزَمْتَ ) بعد المشورة على فعل ( فَتَوَكَّلْ عَلَى اللهِ ) ولا تهتم بمن يخالف رأيه رأيك يا رسول الله ( إِنَّ اللهَ يُحِبُّ الْمُتَوَكِّلِينَ ) الواثقين به المعتمدين عليه الذين يوكلون أمورهم إليه."},{"text":"وَلَئِن مُّتُّمْ أَوْ قُتِلْتُمْ لَإِلَى ٱللَّهِ تُحْشَرُونَ","tafsir":""},{"text":"فَبِمَا رَحْمَةٍ مِّنَ ٱللَّهِ لِنتَ لَهُمْ ۖ وَلَوْ كُنتَ فَظًّا غَلِيظَ ٱلْقَلْبِ لَٱنفَضُّوا۟ مِنْ حَوْلِكَ ۖ فَٱعْفُ عَنْهُمْ وَٱسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِى ٱلْأَمْرِ ۖ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى ٱللَّهِ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَوَكِّلِينَ","tafsir":""},{"text":"إِن يَنصُرْكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمْ ۖ وَإِن يَخْذُلْكُمْ فَمَن ذَا ٱلَّذِى يَنصُرُكُم مِّنۢ بَعْدِهِۦ ۗ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ","tafsir":""},{"text":"وَمَا كَانَ لِنَبِىٍّ أَن يَغُلَّ ۚ وَمَن يَغْلُلْ يَأْتِ بِمَا غَلَّ يَوْمَ ٱلْقِيَـٰمَةِ ۚ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ","tafsir":"أيها المؤمنون ، وذلك إذا استحققتم ذلك بإيجاد أسباب النصر وإطاعة أوامره سبحانه ( فَلا غالِبَ لَكُمْ ) أي لا يقدر أحد على أن يغلبكم ( وَإِنْ يَخْذُلْكُمْ ) وخذلان الله سبحانه أن يكلهم إلى أنفسهم ولا يعينهم في أمورهم ( فَمَنْ ذَا الَّذِي يَنْصُرُكُمْ مِنْ بَعْدِهِ ) استفهام استنكاري ، أي لا يكون ناصر لكم ينصركم من بعده سبحانه وَعَلَى اللهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ (160) وَما كانَ لِنَبِيٍّ أَنْ يَغُلَّ وَمَنْ يَغْلُلْ يَأْتِ بِما غَلَّ يَوْمَ الْقِيامَةِ ثُمَّ تُوَفَّى كُلُّ نَفْسٍ ما كَسَبَتْ وَهُمْ لا يُظْلَمُونَ (161) أَ فَمَنِ اتَّبَعَ رِضْوانَ اللهِ كَمَنْ باءَ بِسَخَطٍ مِنَ اللهِ وَمَأْواهُ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ (162) ( وَعَلَى اللهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ ) يثقون به ويعتمدون عليه. [162] لقد كان من أسباب تخلّي المسلمين عن مكانهم من الجبل ـ يوم أحد ـ خوفهم ألا يقسّم لهم الرسول صلى‌الله‌عليه‌وآله‌وسلم من الغنائم ، وقد تكلم بعض المنافقين في وقعة بدر حول قطيفة حمراء فقدت فقالوا بأن الرسول أخذها ، ولذا نزلت الآية نافية أن يغلّ الأنبياء ويخونوا ( وَما كانَ لِنَبِيٍّ أَنْ يَغُلَ ) أي لا يجوز للأنبياء الغلول أي الخيانة ، والخيانة محرمة مطلقا لكن المورد أتى خاصا حيث أن الكلام كان حوله ( وَمَنْ يَغْلُلْ ) شريفا كان أو وضيعا قليلا كان غلوله أو كثيرا ( يَأْتِ بِما غَلَّ يَوْمَ الْقِيامَةِ ) و في الحديث : « يأتي به على ظهره » (1) . ( ثُمَّ تُوَفَّى كُلُّ نَفْسٍ ما كَسَبَتْ ) أي تعطى جزاء كسبها كاملا غير منقوص ( وَهُمْ لا يُظْلَمُونَ ) فلا ينقص من أجورهم شيء ولا يعذبون فوق استحقاقهم."},{"text":"أَفَمَنِ ٱتَّبَعَ رِضْوَٰنَ ٱللَّهِ كَمَنۢ بَآءَ بِسَخَطٍ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ ۚ وَبِئْسَ ٱلْمَصِيرُ","tafsir":""},{"text":"هُمْ دَرَجَـٰتٌ عِندَ ٱللَّهِ ۗ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ","tafsir":"باتباع أوامره واجتناب نواهيه ( كَمَنْ باءَ ) أي رجع ( بِسَخَطٍ مِنَ اللهِ ) فكأنه رجع إلى أعماله الدنيئة بعد أن ذهب إلى الله سبحانه فعلم ماذا يريد ، فقد رجع مع السخط بينما رجع غيره مع الرضوان ( وَمَأْواهُ ) أي مرجعه ومصيره ( جَهَنَّمُ وَبِئْسَ الْمَصِيرُ ) أي ( 1) بحار الأنوار : ج 7 ص 68. هُمْ دَرَجاتٌ عِنْدَ اللهِ وَاللهُ بَصِيرٌ بِما يَعْمَلُونَ (163) لَقَدْ مَنَّ اللهُ عَلَى الْمُؤْمِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُولاً مِنْ أَنْفُسِهِمْ أن المحل الذي صار إليه محل سيئ ، فعلى الإنسان أن لا يفرّ من الحرب ولا يتخلف عن أمر الله والرسول صلى‌الله‌عليه‌وآله‌وسلم حتى يبوء بالغضب والسخط ويكون مصيره النار."},{"text":"لَقَدْ مَنَّ ٱللَّهُ عَلَى ٱلْمُؤْمِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُولًا مِّنْ أَنفُسِهِمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَـٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَـٰلٍ مُّبِينٍ","tafsir":"أي هؤلاء الذين باءوا بالسخط والذين اتبعوا رضوان الله ، ذوو ( دَرَجاتٌ عِنْدَ اللهِ ) فللمؤمنين درجات رفيعة ولغيرهم درجات بذيئة ، أو أن لكل فريق درجات من حيث القرب والبعد ، وحذف كلمة « ذوو » لما تعارف من المجاز في هذه التعبيرات بعلاقة الحال والمحل فيقال عند العد : زيد الدرجة الأولى ، عمرو الدرجة الثانية ، وهكذا ( وَاللهُ بَصِيرٌ بِما يَعْمَلُونَ ) فيجازيهم حسب أعمالهم فلا يزهد الإنسان في الإحسان لأنه لا يقدّر ، ولا يجري العاصي في المعصية لأنه لا يرى. [165] إن النعمة التي أنعم الله بها على المسلمين مما يوجب شكرها والتضحية في سبيلها فهي نعمة كبيرة جدا لا تماثلها نعمة ولا يبلغ شأنها إحسان ومنّة ( لَقَدْ مَنَّ اللهُ ) أي أنعم الله ، فإن المنّ القطع ، وتسمى النعمة منّة لأنها تقطع الإنسان عن البلية والفاقة ( عَلَى الْمُؤْمِنِينَ ) إنما خصوا بالذكر مع أن المنة عامة لأنهم هم الذين استفادوا منها دون سواهم ( إِذْ بَعَثَ فِيهِمْ رَسُولاً ) فإنه أعظم النعم ، ولذا لم يمن الله على الإنسان بأية نعمة سواها ، فإن في الإرسال صلاح الدين والدنيا والآخرة وإكمال البشر حسب قابلياتهم ( مِنْ أَنْفُسِهِمْ ) تذكير بنعمة أخرى ، إذ كون الرسول صلى‌الله‌عليه‌وآله‌وسلم من جنس البشر ـ يَتْلُوا عَلَيْهِمْ آياتِهِ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ الْكِتابَ وَالْحِكْمَةَ وَإِنْ كانُوا مِنْ قَبْلُ لَفِي ضَلالٍ مُبِينٍ (164) أَ وَلَمَّا أَصابَتْكُمْ مُصِيبَةٌ قَدْ أَصَبْتُمْ مِثْلَيْها قُلْتُمْ أَنَّى هذا لا الملائكة والجن ـ تشريف لهم وإظهار لفضل هذا النوع ، وحيث أن السياق حول مؤمن الأنس لا يستشكل بأن المؤمنين أعم من الجن وليس الرسول من أنفسهم ( يَتْلُوا ) الرسول ( عَلَيْهِمْ آياتِهِ ) تلاوة ، كما يتلو المعلم الدرس على التلميذ ( وَيُزَكِّيهِمْ ) يطهرهم من الأدناس الظاهرية بأوامر النظافة وما أشبه ، والأقذار الخلقية والاعتقادية بإرشادهم إلى الحق والفضيلة ( وَيُعَلِّمُهُمُ الْكِتابَ ) يفهمهم معانيه ، وهو غير التلاوة ( وَالْحِكْمَةَ ) وهو علم الشريعة ، أو مطلقا ، بمعنى أنه يعلمهم مواضع الأشياء خيرها وشرها فإن الحكمة كما قالوا : « وضع الشيء موضعه » . ( وَإِنْ كانُوا مِنْ قَبْلُ ) أي قبل أن يأتيهم الرسول ( لَفِي ضَلالٍ مُبِينٍ ) أي انحراف واضح في عقائدهم وأخلاقهم وأعمالهم ، فعلى المؤمنين أن يضحوا في سبيل هذه النعمة بكل غال ورخيص ، فما فعلوا يوم أحد كان خلاف الشكر ، وما ضحوا فيه لم يكن كثيرا مقابل هذه النعمة العظمى."},{"text":"أَوَلَمَّآ أَصَـٰبَتْكُم مُّصِيبَةٌ قَدْ أَصَبْتُم مِّثْلَيْهَا قُلْتُمْ أَنَّىٰ هَـٰذَا ۖ قُلْ هُوَ مِنْ عِندِ أَنفُسِكُمْ ۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ","tafsir":""},{"text":"وَمَآ أَصَـٰبَكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ فَبِإِذْنِ ٱللَّهِ وَلِيَعْلَمَ ٱلْمُؤْمِنِينَ","tafsir":"أي هل أنتم بحيث لما أصابتكم مصيبة في أحد والحال أنكم في بدر ( قَدْ أَصَبْتُمْ ) من الكفار ( مِثْلَيْها ) فإنه قتل منكم في أحد سبعين ، وقد أصبتم من الكفار مائة وأربعين إذ قتلتم منهم سبعين وأسرتم منهم سبعين في واقعة بدر ( قُلْتُمْ أَنَّى هذا ) أي من أي وجه أصابنا هذا ونحن مسلمون ، وهذه الجملة « أو لما .. » استنكارية أي كيف تستنكرون إصابتكم بأحد والحال أنكم قد أصبتم قُلْ هُوَ مِنْ عِنْدِ أَنْفُسِكُمْ إِنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ (165) وَما أَصابَكُمْ يَوْمَ الْتَقَى الْجَمْعانِ فَبِإِذْنِ اللهِ وَلِيَعْلَمَ الْمُؤْمِنِينَ (166) وَلِيَعْلَمَ الَّذِينَ نافَقُوا وَقِيلَ لَهُمْ تَعالَوْا قاتِلُوا فِي سَبِيلِ اللهِ في بدر مثلي ما أصابكم ، ثم أن هذه الإصابة كانت لضعف نفوسكم حيث أغراكم المال وأخليتم أماكنكم في الجبل ( قُلْ ) يا رسول الله : ( هُوَ ) أي ما أصابكم ( مِنْ عِنْدِ أَنْفُسِكُمْ ) الجشعة إلى حب الغنيمة والمال ( إِنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) يقدر أن ينصركم على أعدائكم كما يقدر أن يخذلكم حين تتركون أوامره ، و في بعض الأحاديث : أنهم في بدر خيروا بين أخذ الفدية من الأسرى على أن يقتل منهم في العام القابل سبعون بعدد الأسرى ، وبين أن يقتلوا الأسرى ولا يأخذون الفدية. فطلبهم للمال أوجب اختيار الأول ، وعلى هذا كان ما أصابهم في أحد « من عند أنفسهم » ."},{"text":"وَلِيَعْلَمَ ٱلَّذِينَ نَافَقُوا۟ ۚ وَقِيلَ لَهُمْ تَعَالَوْا۟ قَـٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَوِ ٱدْفَعُوا۟ ۖ قَالُوا۟ لَوْ نَعْلَمُ قِتَالًا لَّٱتَّبَعْنَـٰكُمْ ۗ هُمْ لِلْكُفْرِ يَوْمَئِذٍ أَقْرَبُ مِنْهُمْ لِلْإِيمَـٰنِ ۚ يَقُولُونَ بِأَفْوَٰهِهِم مَّا لَيْسَ فِى قُلُوبِهِمْ ۗ وَٱللَّهُ أَعْلَمُ بِمَا يَكْتُمُونَ","tafsir":"أيها المسلمون ( يَوْمَ الْتَقَى الْجَمْعانِ ) أي حين تلاقى المسلمون والكفار في يوم أحد ( فَبِإِذْنِ اللهِ ) أي بعلمه ، أو بأنه لم يحل بين الكفار وبينكم حتى أصابوا منكم. وهذا كالإذن تكوينا ، وقد أذن سبحانه لفائدة التمييز بين المؤمن والمنافق ( وَلِيَعْلَمَ ) أي يتحصّل علمه في الخارج ( الْمُؤْمِنِينَ ) الذين جاهدوا."},{"text":"ٱلَّذِينَ قَالُوا۟ لِإِخْوَٰنِهِمْ وَقَعَدُوا۟ لَوْ أَطَاعُونَا مَا قُتِلُوا۟ ۗ قُلْ فَٱدْرَءُوا۟ عَنْ أَنفُسِكُمُ ٱلْمَوْتَ إِن كُنتُمْ صَـٰدِقِينَ","tafsir":"أظهروا الإسلام وأبطنوا النفاق وهم ابن أبي سلول وجماعته حيث أنهم انخذلوا يوم أحد نحوا من ثلاثمائة رجل قالوا : علام نقتل أنفسنا ؟! ( وَقِيلَ لَهُمْ تَعالَوْا قاتِلُوا فِي سَبِيلِ اللهِ ) فإن عمرو بن حزام الأنصاري قال لهم هذه المقالة أَوِ ادْفَعُوا قالُوا لَوْ نَعْلَمُ قِتالاً لاتَّبَعْناكُمْ هُمْ لِلْكُفْرِ يَوْمَئِذٍ أَقْرَبُ مِنْهُمْ لِلْإِيمانِ يَقُولُونَ بِأَفْواهِهِمْ ما لَيْسَ فِي قُلُوبِهِمْ وَاللهُ أَعْلَمُ بِما يَكْتُمُونَ (167) الَّذِينَ قالُوا لِإِخْوانِهِمْ وَقَعَدُوا لَوْ أَطاعُونا ( أَوِ ادْفَعُوا ) عن حريمكم وأنفسكم فإن الكفار إذا غلبوا نكّلوا بكم ( قالُوا ) أي قال أولئك المنافقون في جواب المؤمنين : ( لَوْ نَعْلَمُ قِتالاً لَاتَّبَعْناكُمْ ) فإن هذا الذي تخوضونه ليس بقتال إذ لو كان قتالا لأخذتم برأينا فيه ، أو تريدون إلقاء النفس في التهلكة فليس هذا قتالا يتكافأ فيه الجانبان ، ( هُمْ ) أي هؤلاء المنافقون ( لِلْكُفْرِ يَوْمَئِذٍ أَقْرَبُ مِنْهُمْ لِلْإِيمانِ ) فكلما عمل المنافق بالخلاف كان أقرب إلى الكفر وكلما عمل بالوفاق كان أقرب إلى الإيمان ( يَقُولُونَ بِأَفْواهِهِمْ ما لَيْسَ فِي قُلُوبِهِمْ ) فأفواههم تنطق بالإيمان وقلوبهم تضمر الكفر والعصيان ( وَاللهُ أَعْلَمُ بِما يَكْتُمُونَ ) في قلوبهم فيجازيهم حسب نفاقهم المضمر. أقول : الظاهر أن قوله : « وليعلم » إلى آخره ، ليس عطفا على « بإذن الله » إذ يكون المعنى حينئذ أن الإصابة علة للتمييز ، والحال أن إعلان الجهاد كان علة ذلك ، فقوله : « ليعلم » جملة مستأنفة ، أي أن حرب أحد كانت لأجل التمييز بين المؤمن والمنافق ، في جملة فوائدها الأخرى. [169] ثم ذكر سبحانه صفة أخرى للذين نافقوا بأنهم هم ( الَّذِينَ قالُوا لِإِخْوانِهِمْ ) أي قالوا حول إخوانهم الذين ذهبوا إلى ساحات الجهاد فقتلوا ( وَقَعَدُوا ) أي قعد هؤلاء المنافقون عن القتال ( لَوْ أَطاعُونا ) ما قُتِلُوا قُلْ فَادْرَؤُا عَنْ أَنْفُسِكُمُ الْمَوْتَ إِنْ كُنْتُمْ صادِقِينَ (168) وَلا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللهِ أَمْواتاً بَلْ أَحْياءٌ عِنْدَ رَبِّهِمْ يُرْزَقُونَ (169) فَرِحِينَ بِما آتاهُمُ اللهُ مِنْ فَضْلِهِ وَيَسْتَبْشِرُونَ في تركهم الخروج ( ما قُتِلُوا ) جملة ( لَوْ أَطاعُونا ما قُتِلُوا ) مقول قولهم. ( قُلْ ) لهم يا رسول الله : ( فَادْرَؤُا ) أي ادفعوا ( عَنْ أَنْفُسِكُمُ الْمَوْتَ إِنْ كُنْتُمْ صادِقِينَ ) في مقالكم أن البقاء في البيت موجب لعدم موت الإنسان ، فمن أين لكم أن من يبقى في بيته لا يموت ، فكم من الذين بقوا في بيوتهم وماتوا وكم خرجوا في القتال ورجعوا سالمين ؟! [170] ولو فرضنا أن الخارج إلى الجهاد قتل ، فما يضره ذلك ، فإن من استشهد في سبيل الله لا تنتهي حياته بل يبقى حيا يرزق ( وَلا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللهِ أَمْواتاً ) فكما أن هذه الحياة المادية ذات مراتب ، فمرتبة منها كاملة فيمن كان سعيدا فرحا ، ومرتبة منها ناقصة فيمن كان شقيا حزينا. كذلك من مات يكون على قسمين ـ بعد بقاء كليهما في حياة من لون آخر ـ قسم يكون حيا هناك أي سعيدا فرحا ، وقسم يكون ميتا هناك أي شقيا حزينا ، فليس للآية الكريمة مفهوم أن غير المقتول لا حياة له هناك ( بَلْ أَحْياءٌ عِنْدَ رَبِّهِمْ يُرْزَقُونَ ) حياة غير مادية بل حياة عند ربهم ولهم رزقهم فيها بكرة وعشيا. [171] في حال كونهم ( فَرِحِينَ بِما آتاهُمُ اللهُ مِنْ فَضْلِهِ ) من الحياة الباقية والسعادة والخير ( وَيَسْتَبْشِرُونَ ) أي يسرّ هؤلاء المقتولون في سبيل بِالَّذِينَ لَمْ يَلْحَقُوا بِهِمْ مِنْ خَلْفِهِمْ أَلاَّ خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ (170) يَسْتَبْشِرُونَ بِنِعْمَةٍ مِنَ اللهِ وَفَضْلٍ وَأَنَّ اللهَ لا يُضِيعُ أَجْرَ الْمُؤْمِنِينَ (171) الله ( بِالَّذِينَ لَمْ يَلْحَقُوا بِهِمْ ) من المؤمنين الذين بقوا في الحياة وبقوا ( مِنْ خَلْفِهِمْ ) واستبشارهم بهؤلاء من جهة ( أَلَّا خَوْفٌ عَلَيْهِمْ ) إذ الله سبحانه يتولى أمورهم ( وَلا هُمْ يَحْزَنُونَ ) بالنسبة إلى من خلفهم ، فهؤلاء المقتولون جمعوا بين خيرين خير أنفسهم حيث تنعموا بنعمة الله سبحانه وخير إخوانهم الذين من خلفهم حيث علموا بأنهم لا خوف عليهم ، وذلك بخلاف من بقي ولم يجاهد فإنهم جمعوا بين شرين مشاكل حياة أنفسهم ومشاكل حياة إخوانهم ، حيث لا يعلمون ماذا تكون عاقبة أمر أنفسهم وأمر إخوانهم."},{"text":"وَلَا تَحْسَبَنَّ ٱلَّذِينَ قُتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتًۢا ۚ بَلْ أَحْيَآءٌ عِندَ رَبِّهِمْ يُرْزَقُونَ","tafsir":""},{"text":"فَرِحِينَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ وَيَسْتَبْشِرُونَ بِٱلَّذِينَ لَمْ يَلْحَقُوا۟ بِهِم مِّنْ خَلْفِهِمْ أَلَّا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ","tafsir":""},{"text":"۞ يَسْتَبْشِرُونَ بِنِعْمَةٍ مِّنَ ٱللَّهِ وَفَضْلٍ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُؤْمِنِينَ","tafsir":""},{"text":"ٱلَّذِينَ ٱسْتَجَابُوا۟ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعْدِ مَآ أَصَابَهُمُ ٱلْقَرْحُ ۚ لِلَّذِينَ أَحْسَنُوا۟ مِنْهُمْ وَٱتَّقَوْا۟ أَجْرٌ عَظِيمٌ","tafsir":"أي هؤلاء المقتولون يسرّون ويفرحون ( بِنِعْمَةٍ مِنَ اللهِ ) ينعمها عليهم في الآخرة ( وَفَضْلٍ ) أي الزيادة على قدر استحقاقهم أو على ما يترقبون ( وَأَنَّ اللهَ لا يُضِيعُ أَجْرَ الْمُؤْمِنِينَ ) فإن من علم أن حقه وأجره مضمون فرح واستبشر ، فهؤلاء يرون عيانا أن حقهم محفوظ بخلاف الإنسان في الدنيا فإنه يعلم ذلك دون أن يراه. وفي تكرار المطلب زيادة تمكين المعنى في النفس ، ومثله كثير في التحذيرات والترغيبات المستقبلة وبالأخص إذا لم يشاهد الإنسان أمثاله بل كان غيبا محضا فإن في التكرار تركيز المطلب في النفس حتى تعمل تلقائيا كالذي شاهد وحضر. [173] لما انصرف أبو سفيان وأصحابه من « أحد » وبلغوا « الروحاء » ندموا الَّذِينَ اسْتَجابُوا لِلَّهِ وَالرَّسُولِ مِنْ بَعْدِ ما أَصابَهُمُ الْقَرْحُ لِلَّذِينَ أَحْسَنُوا مِنْهُمْ وَاتَّقَوْا أَجْرٌ عَظِيمٌ (172) الَّذِينَ قالَ لَهُمُ النَّاسُ إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ على انصرافهم عن المسلمين وتلاوموا فيما بينهم قائلين بعضهم لبعض : لا محمدا قتلتم ولا الكواعب أردفتم ، قتلتموهم حتى لم يبق منهم إلا الشريد وتركتموهم ، فارجعوا فاستأصلوهم. فبلغ ذلك الخبر الرسول صلّى الله عليه وآله وسلّم فأراد إرهابهم فخرج صلى‌الله‌عليه‌وآله‌وسلم ومعه من به جرح من أحد حتى بلغ « حمراء الأسد » وبلغ الخبر المشركين فخافوا خوفا شديدا وولوا منهزمين. ووجه اتصال الآية أنه سبحانه بعد ما بين أجر الشهداء وأنهم يستبشرون بالأحياء ذكر وصف الأحياء الذين يستبشر بهم المقتولون أنهم أولئك الذين لم تزلزلهم المحنة ولم تقعدهم الجراحات عن مواصلة الكفاح ولم يرهبهم تجمع الأعداء وإرجافهم بهذا التجمع وهم مثخنون بهذه الجراحات ( الَّذِينَ اسْتَجابُوا لِلَّهِ وَالرَّسُولِ ) أطاعوهما في أمرهما ، وقد ذكرنا سابقا أن ذكر الرسول صلى‌الله‌عليه‌وآله‌وسلم للتشريف وأن بيان أمره أمر الله سبحانه وإلا فالأمر واحد ( مِنْ بَعْدِ ما أَصابَهُمُ الْقَرْحُ ) أي نالتهم الجراحات يوم أحد ( لِلَّذِينَ أَحْسَنُوا مِنْهُمْ ) بعد الاستجابة ( وَاتَّقَوْا ) معاصي الله سبحانه ( أَجْرٌ عَظِيمٌ ) لأنهم أطاعوا في ثلاث دفعات حضورهم في أحد واستجابتهم ثانيا وإحسانهم وتقواهم ثالثا. [174] ثم وصفهم سبحانه بوصف آخر أنهم هم ( الَّذِينَ قالَ لَهُمُ النَّاسُ إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ ) فقد قال الناس لأصحاب الرسول صلى‌الله‌عليه‌وآله‌وسلم بعد فَاخْشَوْهُمْ فَزادَهُمْ إِيماناً وَقالُوا حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيلُ (173) فَانْقَلَبُوا بِنِعْمَةٍ مِنَ اللهِ وَفَضْلٍ لَمْ يَمْسَسْهُمْ سُوءٌ وَاتَّبَعُوا رِضْوانَ اللهِ وَاللهُ ذُو فَضْلٍ عَظِيمٍ (174) رجوعهم من أحد : إن « الناس » وهم أبو سفيان والمشركون قد جمعوا لكم ، أي جمعوا المشركين لأجل محاربتكم ( فَاخْشَوْهُمْ ) أي خافوا منهم لأنهم إذا رجعوا إليكم وأنتم ـ أيها المسلمون ـ مثخنون بالجراح من أحد لن يبقوا منكم باقية ( فَزادَهُمْ ) تجمع الناس عليهم ( إِيماناً ) فإن عند كل كارثة يتذكر المؤمن الله سبحانه فتقوى نفسه بمعونته وتشتد عزيمته بنصره ( وَقالُوا حَسْبُنَا اللهُ ) أي كافينا الله يكفينا شر أعدائنا ( وَنِعْمَ الْوَكِيلُ ) فإنه خير من جعله الإنسان وكيلا لعلمه بمواقع النفع والضرر وقدرته على جلب النفع ودفع الضرر عن الموكل."},{"text":"ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدْ جَمَعُوا۟ لَكُمْ فَٱخْشَوْهُمْ فَزَادَهُمْ إِيمَـٰنًا وَقَالُوا۟ حَسْبُنَا ٱللَّهُ وَنِعْمَ ٱلْوَكِيلُ","tafsir":""},{"text":"فَٱنقَلَبُوا۟ بِنِعْمَةٍ مِّنَ ٱللَّهِ وَفَضْلٍ لَّمْ يَمْسَسْهُمْ سُوٓءٌ وَٱتَّبَعُوا۟ رِضْوَٰنَ ٱللَّهِ ۗ وَٱللَّهُ ذُو فَضْلٍ عَظِيمٍ","tafsir":""},{"text":"إِنَّمَا ذَٰلِكُمُ ٱلشَّيْطَـٰنُ يُخَوِّفُ أَوْلِيَآءَهُۥ فَلَا تَخَافُوهُمْ وَخَافُونِ إِن كُنتُم مُّؤْمِنِينَ","tafsir":"أي رجع هؤلاء المؤمنون الذين استجابوا لله والرسول صلى‌الله‌عليه‌وآله‌وسلم ، تصحبهم نعمة الله وفضله ( لَمْ يَمْسَسْهُمْ سُوءٌ ) فهم بعد ما خرجوا في طلب أبي سفيان ، هرب أبو سفيان فرجع المسلمون وهم مرهوبو الجانب أشداء النفوس ( وَ ) قد ( اتَّبَعُوا رِضْوانَ اللهِ ) باتباع أمره في تعقب المشركين ( وَاللهُ ذُو فَضْلٍ عَظِيمٍ ) على من اتبع أمره فهو يسعده في الدنيا والآخرة. روي عن الإمام الصادق عليه‌السلام أنه قال : عجبت لمن خاف كيف لا يفزع إلى قوله : ( حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيلُ ) فإني سمعت الله يقول بعقبها : ( فَانْقَلَبُوا بِنِعْمَةٍ مِنَ اللهِ وَفَضْلٍ لَمْ يَمْسَسْهُمْ سُوءٌ ) (1) . ( 1) من لا يحضره الفقيه : ج 4 ص 392. إِنَّما ذلِكُمُ الشَّيْطانُ يُخَوِّفُ أَوْلِياءَهُ فَلا تَخافُوهُمْ وَخافُونِ إِنْ كُنْتُمْ مُؤْمِنِينَ (175) وَلا يَحْزُنْكَ الَّذِينَ يُسارِعُونَ فِي الْكُفْرِ إِنَّهُمْ لَنْ يَضُرُّوا اللهَ شَيْئاً"},{"text":"وَلَا يَحْزُنكَ ٱلَّذِينَ يُسَـٰرِعُونَ فِى ٱلْكُفْرِ ۚ إِنَّهُمْ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا ۗ يُرِيدُ ٱللَّهُ أَلَّا يَجْعَلَ لَهُمْ حَظًّا فِى ٱلْـَٔاخِرَةِ ۖ وَلَهُمْ عَذَابٌ عَظِيمٌ","tafsir":"« كم » للخطاب ، و « ذا » إشارة إلى التخويف من الأعداء أي أن التخويف الذي صدر عن بعض الناس بالنسبة إلى المسلمين من عمل الشيطان فإنه ( الشَّيْطانُ يُخَوِّفُ أَوْلِياءَهُ ) فإن المؤمنين لا يخافون وإنما أولياء الشيطان يخافون لأنهم بانقطاع صلتهم من الله سبحانه يخافون من كل شيء كما قال سبحانه في وصف المنافقين : ( يَحْسَبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْ ) (1) ، ( فَلا تَخافُوهُمْ ) أي لا تخافوا الناس الذين جمعوا لكم ، أو لا تخافوا الشيطان وأولياءه ( وَخافُونِ ) والخوف من الله سبحانه بمعنى إطاعته وترك عصيانه فإن في ترك ذلك ، النار والعقاب ( إِنْ كُنْتُمْ مُؤْمِنِينَ ) فإن الإيمان يوجب أن لا يخاف الإنسان إلا من الله سبحانه ، وليس المراد عدم الخوف مطلقا فإنه قهرا للإنسان وإنما المراد ترتيب الأثر على الخوف."},{"text":"إِنَّ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْكُفْرَ بِٱلْإِيمَـٰنِ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا وَلَهُمْ عَذَابٌ أَلِيمٌ","tafsir":"يا رسول الله ( الَّذِينَ يُسارِعُونَ فِي الْكُفْرِ ) أي يتسابقون في أعمالهم الكافرة كأنهم في سباق من كثرة نشاطهم ( إِنَّهُمْ لَنْ يَضُرُّوا اللهَ ) فإن دعوتك التي هي مرتبطة بالله سبحانه لا بد وأن تنجح وتتقدم وهذه المسارعات الكافرة لا تضرها ، فقد نسب موقف الدعوة إلى الله سبحانه ، إفادة لعلوها وقوة المدافع والمتولي لها ( شَيْئاً ) أصلا لا صغيرا ولا كبيرا ، بل إنهم يضرون بذلك أنفسهم فإن ( 1) المنافقون : 5. يُرِيدُ اللهُ أَلاَّ يَجْعَلَ لَهُمْ حَظًّا فِي الْآخِرَةِ وَلَهُمْ عَذابٌ عَظِيمٌ (176) إِنَّ الَّذِينَ اشْتَرَوُا الْكُفْرَ بِالْإِيْمانِ لَنْ يَضُرُّوا اللهَ شَيْئاً وَلَهُمْ عَذابٌ أَلِيمٌ (177) وَلا يَحْسَبَنَّ الَّذِينَ كَفَرُوا أَنَّما نُمْلِي لَهُمْ خَيْرٌ لِأَنْفُسِهِمْ إِنَّما نُمْلِي لَهُمْ لِيَزْدادُوا إِثْماً وَلَهُمْ عَذابٌ مُهِينٌ (178) إعطاء الله القدرة لهم في أن يفعلوا ما يشاءون لأنه ( يُرِيدُ اللهُ أَلَّا يَجْعَلَ لَهُمْ حَظًّا فِي الْآخِرَةِ ) وإنما أراد ذلك لأنهم أعرضوا عن الحق كما أنك إذا أديت إلى عبدك مالا ليتاجر به ، ثم ذهب يقامر به ، وأمهلته فلم تضرب على يده تقول : أريد أن أبدي سوءته وأعاقبه بعقاب كبير ( وَلَهُمْ عَذابٌ عَظِيمٌ ) بكفرهم ومسارعتهم ونشاطهم ضد الإسلام."},{"text":"وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّمَا نُمْلِى لَهُمْ خَيْرٌ لِّأَنفُسِهِمْ ۚ إِنَّمَا نُمْلِى لَهُمْ لِيَزْدَادُوٓا۟ إِثْمًا ۚ وَلَهُمْ عَذَابٌ مُّهِينٌ","tafsir":"أي بدّلوا ( الْكُفْرَ بِالْإِيْمانِ لَنْ يَضُرُّوا اللهَ ) بتبديلهم الكفر بالإيمان ( شَيْئاً ) أيّ شيء أبدا ( وَلَهُمْ ) أي للذين بدلوا الكفر بالإيمان ( عَذابٌ أَلِيمٌ ) بما بدلوا."},{"text":"مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلْمُؤْمِنِينَ عَلَىٰ مَآ أَنتُمْ عَلَيْهِ حَتَّىٰ يَمِيزَ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ ۗ وَمَا كَانَ ٱللَّهُ لِيُطْلِعَكُمْ عَلَى ٱلْغَيْبِ وَلَـٰكِنَّ ٱللَّهَ يَجْتَبِى مِن رُّسُلِهِۦ مَن يَشَآءُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۚ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ فَلَكُمْ أَجْرٌ عَظِيمٌ","tafsir":"أي لا يظن ( الَّذِينَ كَفَرُوا أَنَّما نُمْلِي لَهُمْ خَيْرٌ لِأَنْفُسِهِمْ ) الإملاء الإمهال ، أي أن إطالتنا لأعمارهم وإمهالنا إياهم وتوفير المال والجاه لهم ليس خيرا لهم فإن الخير هو الذي لا يسبب شرا وعقابا ( أَنَّما نُمْلِي لَهُمْ ) نطيل أعمارهم ونعطيهم ما نعطيهم ( لِيَزْدادُوا إِثْماً ) ومعصية ، فإنهم بإعراضهم عن الحق وخبث بواطنهم استحقوا العقاب والعذاب لكن حيث لا عقاب على الخبث الباطني فقط كان الإمهال مظهرا لذلك الخبث ، فبقاؤهم موجب لزيادة عقوبتهم ( وَلَهُمْ عَذابٌ مُهِينٌ ) يهينهم علاوة على ألمه وكربه وربما يقال : إن ما كانَ اللهُ لِيَذَرَ الْمُؤْمِنِينَ عَلى ما أَنْتُمْ عَلَيْهِ حَتَّى يَمِيزَ الْخَبِيثَ مِنَ الطَّيِّبِ وَما كانَ اللهُ لِيُطْلِعَكُمْ عَلَى الْغَيْبِ وَلكِنَّ اللهَ يَجْتَبِي مِنْ رُسُلِهِ مَنْ يَشاءُ « اللام » في قوله « ليزدادوا » لام العاقبة كقوله تعالى : ( فَالْتَقَطَهُ آلُ فِرْعَوْنَ لِيَكُونَ لَهُمْ عَدُوًّا وَحَزَناً ) (1) . [180] ثم يرتد السياق إلى قصة أحد حيث انكشف هناك المؤمن الذي تبع الرسول صلى‌الله‌عليه‌وآله‌وسلم في الحرب من المنافق الذي تخلّف عن الجهاد كعبد الله ابن أبي سلول بمن تخلف معه ( ما كانَ اللهُ ) أي ليس من سنته سبحانه أن لا يمتحن ( لِيَذَرَ الْمُؤْمِنِينَ ) أي يدعهم ويتركهم ( عَلى ما أَنْتُمْ عَلَيْهِ ) من ظاهر الإيمان الذي يتساوى فيه المؤمن والمنافق ( حَتَّى يَمِيزَ الْخَبِيثَ مِنَ الطَّيِّبِ ) لكي يظهر ما يضمره كل فريق. وفي بعض التفاسير : أن المشركين قالوا لأبي طالب : إن كان محمد صادقا فليخبرنا من يؤمن منا ومن يكفر ؟ فإن وجدنا خبره صدقا آمنا به. فنزلت الآية (2) . وعلى هذا فمعنى ( عَلى ما أَنْتُمْ عَلَيْهِ ) أي حالكم قبل الإيمان ، فلا يترك سبحانه المؤمن على كفره بين سائر الكفار ( وَما كانَ اللهُ لِيُطْلِعَكُمْ عَلَى الْغَيْبِ ) حتى تعلموا أن هذا مؤمن وهذا منافق ، بدون الاختبار الخارجي المظهر للضمائر ( وَلكِنَّ اللهَ يَجْتَبِي ) أي يختار لاطلاعه على الغيب ( مِنْ رُسُلِهِ ) وأنبيائه ( مَنْ يَشاءُ ) وهذا كقوله ( 1) القصص : 9. ( 2) مجمع البيان : ج 2 ص 456. فَآمِنُوا بِاللهِ وَرُسُلِهِ وَإِنْ تُؤْمِنُوا وَتَتَّقُوا فَلَكُمْ أَجْرٌ عَظِيمٌ (179) وَلا يَحْسَبَنَّ الَّذِينَ يَبْخَلُونَ بِما آتاهُمُ اللهُ مِنْ فَضْلِهِ تعالى : ( فَلا يُظْهِرُ عَلى غَيْبِهِ أَحَداً* إِلَّا مَنِ ارْتَضى مِنْ رَسُولٍ ) (1) ولا ينافي ذلك اطلاع بعض الملائكة والأئمة وبعض المؤمنين على بعض المغيبات إذ الملائكة خارج عن المستثنى منه والباقون إما بتعليم النبي أو بإلهام منه سبحانه وعدم استثنائه لندرته خارجا ، والقضايا الطبيعية ـ كما نحن فيه ـ لا تنافيها النوادر. وحيث عرفتم قيمة الإيمان ( فَآمِنُوا بِاللهِ وَرُسُلِهِ ) إيمانا حقيقيا لا يشوبه نفاق وخبث ضمير ( وَإِنْ تُؤْمِنُوا ) إيمانا صادقا ( وَتَتَّقُوا ) المعاصي وتعملوا الصالحات ( فَلَكُمْ أَجْرٌ عَظِيمٌ ) يبقى إلى الأبد في جنة عرضها السماوات والأرض ورضوان من الله. [181] وحيث تقدم الكلام حول الجهاد والتضحية عقبه سبحانه بذكر المال فهما يذكران غالبا مقترنين إذ الجهاد يحتاج إلى بذل المال والدين إنما يقام ببذل النفس وبذل المال معا ، فقال سبحانه : ( وَلا يَحْسَبَنَّ الَّذِينَ يَبْخَلُونَ بِما آتاهُمُ اللهُ مِنْ فَضْلِهِ ) أي أعطاهم سبحانه فضلا وإحسانا فإن المال وإن اجتهد الإنسان وكدّ في جمعه إنما هو فضل من الله سبحانه لأنه من خلقه وصنعه فالنقدان مثلا معدنان مخلوقان له وسائر الأموال من نبات الأرض وما أشبه كله له ، هذا بالإضافة إلى أن أجهزة الإنسان التي بها يتمكن من كسب المال كلها منه سبحانه. والمراد بالبخل هنا هو الحرام منه مما يجب إعطاؤه فيمنع ( 1) الجن : 27 ـ 28. هُوَ خَيْراً لَهُمْ بَلْ هُوَ شَرٌّ لَهُمْ سَيُطَوَّقُونَ ما بَخِلُوا بِهِ يَوْمَ الْقِيامَةِ وَلِلَّهِ مِيراثُ السَّماواتِ وَالْأَرْضِ ( هُوَ خَيْراً لَهُمْ ) حيث يزعمون أن البخل يوفر عليهم المال فيبقى عندهم ولا يخرج من أيديهم و « خيرا » مفعول « يحسبن » ( بَلْ هُوَ شَرٌّ لَهُمْ ) إن ذلك البخل شر لهم يعود عليهم في الدنيا بالشر حيث أن ذلك موجب لسوء السمعة الذي بدوره يوجب عدم التمكن من اكتساب المزيد من المال ويوجب ذهاب الكائن منه بمصادرات الحكام وثورات الفقراء ، والأسوأ من ذلك أنهم ( سَيُطَوَّقُونَ ما بَخِلُوا بِهِ ) أي يجعل المال الذي بخلوا به طوقا في أعناقهم ( يَوْمَ الْقِيامَةِ ) وهذا كناية عن لزوم تبعة المال ، كما يقال : المرأة طوق في عنق الإنسان ، والدّين طوق في عنق المدين ، وهكذا ، وفي الأحاديث الواردة عن النبي صلى‌الله‌عليه‌وآله‌وسلم والأئمة عليهم‌السلام أنه : « ما من أحد يمنع من زكاة ماله شيئا إلا جعل الله ذلك يوم القيامة ثعبانا من نار مطوقا في عنقه ينهش من لحمه حتى يفرغ من الحساب » (1) وفي بعضها تفسير الآية الكريمة بذلك. ثم ما بال هؤلاء يبخلون ؟ فإنه لا يبقى المال عندهم إلى الأبد ، بل يذهبون ويذرون المال ( وَلِلَّهِ مِيراثُ السَّماواتِ وَالْأَرْضِ ) فكل من يموت فيهما ويخلف شيئا فلا بد وأن يرثه الله سبحانه حيث تبقى الأموال له وحده بعد فناء الجميع فما بخل به عنه سبحانه ولم يصرف في سبيله لا بد وأن يرجع إليه ، وليس للبخيل إلا الإثم ( 1) الكافي : ج 3 ص 502. وَاللهُ بِما تَعْمَلُونَ خَبِيرٌ (180) لَقَدْ سَمِعَ اللهُ قَوْلَ الَّذِينَ قالُوا إِنَّ اللهَ فَقِيرٌ وَنَحْنُ أَغْنِياءُ سَنَكْتُبُ ما قالُوا وَقَتْلَهُمُ الْأَنْبِياءَ بِغَيْرِ حَقٍّ ( وَاللهُ بِما تَعْمَلُونَ خَبِيرٌ ) فما أنفقتم من نفقة يعلمها الله سبحانه فيجازيكم عليها جزاء حسنا. [182] وقد كان من بخلاء اليهود من لا ينفق مما آتاه الله ، ثم يزيد على ذلك فيقول : إن الله فقير لأنه يستقرض ـ تعريضا بقوله سبحانه : ( مَنْ ذَا الَّذِي يُقْرِضُ اللهَ ) (1) ـ وأنا غني لما لدي من الأموال ( لَقَدْ سَمِعَ اللهُ قَوْلَ الَّذِينَ قالُوا إِنَّ اللهَ فَقِيرٌ وَنَحْنُ أَغْنِياءُ ) ويكفيه تهديدا أن الله سمع قوله فلينتظر الجزاء العادل والعقاب الأليم ( سَنَكْتُبُ ما قالُوا ) حتى يكون كتابا مسجلا عليهم لا مجال لإنكاره يوم يعطى كل امرئ كتابه ، وقد كان منطق اليهود منحرفا إلى أبعد الحدود ، وكيف يكون الله سبحانه فقيرا وهو الذي يملك كل شيء حتى روح هذا القائل ؟! وإنما استقراضه امتحان وطلبه المال ابتلاء واختبار ، وكيف يكون هو غنيا والحال أنه لا يملك روحه فكيف بماله ؟! ( وَ ) سنكتب ( قَتْلَهُمُ ) أي قتل هؤلاء اليهود ( الْأَنْبِياءَ بِغَيْرِ حَقٍ ) وإنما عيّرهم الله سبحانه مع أن آباءهم هم الذين فعلوا ، لرضاهم بذلك أولا ولبيان أن هؤلاء خلفا عن سلف مجرمون فلا عجب أن يقول الخلف كفرا بعد ما عمل السلف أفظع من ذلك ثانيا ، ودخول « السين » في سنكتب ، لعله لبيان أن الكتابة لا تثبت إلا بعد أن يموتوا غير مؤمنين بمحمد صلى‌الله‌عليه‌وآله‌وسلم وإلا فالكتابة لا تضر إذا محيت ( 1) البقرة : 246. وَنَقُولُ ذُوقُوا عَذابَ الْحَرِيقِ (181) ذلِكَ بِما قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللهَ لَيْسَ بِظَلاَّمٍ لِلْعَبِيدِ (182) بالإيمان ، وهذا يصح بالنسبة إلى قولهم ، أما بالنسبة إلى قتل أسلافهم ، وقد كتب قتلهم ، فلأن كتابة ذلك عائد على الأخلاف إذا بقوا على الكفر ، ولعل العطف على المعنى أي « وكتبنا قتلهم الأنبياء » من قبيل « نحن بما عندنا وأنت بما عندك راض » وقوله : « علفته تبنا وماء باردا » . ( وَنَقُولُ ) حين عقابهم في الآخرة ( ذُوقُوا عَذابَ الْحَرِيقِ ) الذي يحرق أجسادكم بفعلكم وقولكم."},{"text":"وَلَا يَحْسَبَنَّ ٱلَّذِينَ يَبْخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ هُوَ خَيْرًا لَّهُم ۖ بَلْ هُوَ شَرٌّ لَّهُمْ ۖ سَيُطَوَّقُونَ مَا بَخِلُوا۟ بِهِۦ يَوْمَ ٱلْقِيَـٰمَةِ ۗ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ","tafsir":""},{"text":"لَّقَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ فَقِيرٌ وَنَحْنُ أَغْنِيَآءُ ۘ سَنَكْتُبُ مَا قَالُوا۟ وَقَتْلَهُمُ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ وَنَقُولُ ذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ","tafsir":""},{"text":"ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ","tafsir":""},{"text":"ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ عَهِدَ إِلَيْنَآ أَلَّا نُؤْمِنَ لِرَسُولٍ حَتَّىٰ يَأْتِيَنَا بِقُرْبَانٍ تَأْكُلُهُ ٱلنَّارُ ۗ قُلْ قَدْ جَآءَكُمْ رُسُلٌ مِّن قَبْلِى بِٱلْبَيِّنَـٰتِ وَبِٱلَّذِى قُلْتُمْ فَلِمَ قَتَلْتُمُوهُمْ إِن كُنتُمْ صَـٰدِقِينَ","tafsir":"العذاب إنما يكون ( بِما قَدَّمَتْ أَيْدِيكُمْ ) من الكفر والعصيان ، وإنما عبّر بتقديم الأيدي لأن الإنسان غالبا يقدّم الأشياء بيده ، فيكون ذلك من باب التشبيه للمعقول بالمحسوس ( وَأَنَّ اللهَ لَيْسَ بِظَلَّامٍ لِلْعَبِيدِ ) فأنتم عبيده خالفتم أوامره فاستحققتم هذا العقاب ، و « ظلّام » ليست لفظة مبالغة على غرار « علّام » وإنما للنسبة نحو « تمّار » بمعنى ذي تمر ، كما قال ابن مالك : و مع فاعل وفعّال فعل في نسب أغنى عن اليا فقبل ولعل اختيار هذه الكلمة لردّ التوهّم وهو أن الإحراق بالنار إنما يصدر من إنسان كثير الظلم ، فيكون الإتيان به للمجانسة اللفظية كقوله : قالوا اقترح شيئا نجد لك طبخة قلت اطبخوا لي جبة وقميصا الَّذِينَ قالُوا إِنَّ اللهَ عَهِدَ إِلَيْنا أَلاَّ نُؤْمِنَ لِرَسُولٍ حَتَّى يَأْتِيَنا بِقُرْبانٍ تَأْكُلُهُ النَّارُ قُلْ قَدْ جاءَكُمْ رُسُلٌ مِنْ قَبْلِي بِالْبَيِّناتِ وَبِالَّذِي قُلْتُمْ فَلِمَ قَتَلْتُمُوهُمْ إِنْ كُنْتُمْ صادِقِينَ (183) فَإِنْ كَذَّبُوكَ فَقَدْ كُذِّبَ رُسُلٌ مِنْ قَبْلِكَ [184] إن الذين قالوا إن الله فقير ونحن أغنياء ، والذين قتلوا أنبياءهم ، هم الذين لم يؤمنوا بالرسول صلى‌الله‌عليه‌وآله‌وسلم بحجة مكذوبة ، فقد قالوا : يا محمد إن الله عهد إلينا في التوراة أن لا نؤمن لرسول حتى يأتينا بقربان تأكله النار ، فإن زعمت أن الله بعثك إلينا فجئنا بالقربان حتى نصدقك ، فنزلت الآية ( الَّذِينَ قالُوا ) للرسول صلى‌الله‌عليه‌وآله‌وسلم و « الذين » في موضع الجر عطفا على ( الَّذِينَ قالُوا إِنَّ اللهَ فَقِيرٌ ) : ( إِنَّ اللهَ عَهِدَ إِلَيْنا ) أمرنا ووصّانا في الكتب المنزلة ( أَلَّا نُؤْمِنَ لِرَسُولٍ ) بأن لا نصدق بنبوته ( حَتَّى يَأْتِيَنا بِقُرْبانٍ ) أي ما يتقرّب به إلى الله سبحانه ( تَأْكُلُهُ النَّارُ ) تأتي نار من الغيب فتحرقه ، وقد كان ذلك علامة لصدق نبوة أنبياء بني إسرائيل ( قُلْ ) يا رسول الله في جوابهم : ( قَدْ جاءَكُمْ رُسُلٌ مِنْ قَبْلِي بِالْبَيِّناتِ ) الأدلة الواضحة ( وَبِالَّذِي قُلْتُمْ ) من القربان الذي أكلته النار ( فَلِمَ قَتَلْتُمُوهُمْ ) فإنهم قتلوا ذكريا ويحيى وغيرهما ( إِنْ كُنْتُمْ صادِقِينَ ) في دعواكم أنكم تؤمنون بالرسول إذا جاءكم بقربان تأكله النار ؟ وإنما ينسب فعل الأسلاف إلى الأخلاف لأن الطبيعة فيهم واحدة والاتجاه واحد فلا يمكن أن يقال : إن معاصري الرسول لم يكونوا يظهرون الرضا بفعل أسلافهم في قتل الأنبياء."},{"text":"فَإِن كَذَّبُوكَ فَقَدْ كُذِّبَ رُسُلٌ مِّن قَبْلِكَ جَآءُو بِٱلْبَيِّنَـٰتِ وَٱلزُّبُرِ وَٱلْكِتَـٰبِ ٱلْمُنِيرِ","tafsir":""},{"text":"كُلُّ نَفْسٍ ذَآئِقَةُ ٱلْمَوْتِ ۗ وَإِنَّمَا تُوَفَّوْنَ أُجُورَكُمْ يَوْمَ ٱلْقِيَـٰمَةِ ۖ فَمَن زُحْزِحَ عَنِ ٱلنَّارِ وَأُدْخِلَ ٱلْجَنَّةَ فَقَدْ فَازَ ۗ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَـٰعُ ٱلْغُرُورِ","tafsir":"يا رسول الله ولم يؤمنوا برسالتك ( فَقَدْ كُذِّبَ رُسُلٌ مِنْ قَبْلِكَ ) فلست بدعا في ذلك ولا يضيق صدرك بتكذيبهم ، فإن جاؤُ بِالْبَيِّناتِ وَالزُّبُرِ وَالْكِتابِ الْمُنِيرِ (184) كُلُّ نَفْسٍ ذائِقَةُ الْمَوْتِ وَإِنَّما تُوَفَّوْنَ أُجُورَكُمْ يَوْمَ الْقِيامَةِ فَمَنْ زُحْزِحَ عَنِ النَّارِ وَأُدْخِلَ الْجَنَّةَ فَقَدْ فازَ وَمَا الْحَياةُ الدُّنْيا الناس قد كذبوا رسلا قبلك والحال أنهم ( جاؤُ بِالْبَيِّناتِ ) الأدلة الواضحة ( وَالزُّبُرِ ) أي الصحف التي فيها الأحكام والشرائع ( وَالْكِتابِ الْمُنِيرِ ) وهو الكتاب الجامع للأحكام. والفرق بينهما أن الزبر صحائف متفرقة فيها أحكام متشتتة بخلاف الكتاب الذي هو الجامع المتسلسل ، كما أنه نزل على الرسول صلى‌الله‌عليه‌وآله‌وسلم الأحاديث القدسية والقرآن الحكيم .. وهنا سؤال هو : إن النبي صلى‌الله‌عليه‌وآله‌وسلم لم لم يأت بقربان تأكله النار ؟ والجواب : إنهم سألوا ذلك تعنّتا لا استرشادا ، وإلا فقد كان يكفيهم سائر الأدلة ، وليس شأن الأنبياء أن يفعلوا فوق اللازم من المعجزة لكل متعنت ومجادل ، وهذا هو السر في رد كثير ممن سأل المعجزة. [186] إن عدم الجهاد لخوف الموت ، وعدم الإيمان لخوف ذهاب الرئاسة ، وعدم الإنفاق لخوف الفقر ، مما له عاقبة سيئة هي النار ، فكل إنسان يموت وتذهب حياته ورئاسته وماله ، فما أجدر أن يفعل ما يسبّب له حسن العاقبة ( كُلُّ نَفْسٍ ذائِقَةُ الْمَوْتِ ) تذوقه وتلاقيه ( وَإِنَّما تُوَفَّوْنَ ) أيها الناس ( أُجُورَكُمْ ) الحسنة أو السيئة ( يَوْمَ الْقِيامَةِ ) فهنا عمل ولا حساب وغدا حساب وجزاء بلا عمل ( فَمَنْ زُحْزِحَ عَنِ النَّارِ ) أي بوعد عنها ( وَأُدْخِلَ الْجَنَّةَ فَقَدْ فازَ ) لأنه سرور وراحة لا انقطاع لهما ولا تكدّر فيها ( وَمَا الْحَياةُ الدُّنْيا ) بلذاتها وشهواتها إِلَّا مَتاعُ الْغُرُورِ (186) لَتُبْلَوُنَّ فِي أَمْوالِكُمْ وَأَنْفُسِكُمْ وَلَتَسْمَعُنَّ مِنَ الَّذِينَ أُوتُوا الْكِتابَ مِنْ قَبْلِكُمْ وَمِنَ الَّذِينَ أَشْرَكُوا أَذىً كَثِيراً وَإِنْ تَصْبِرُوا وَتَتَّقُوا فَإِنَّ ذلِكَ مِنْ عَزْمِ الْأُمُورِ (187) ( إِلَّا مَتاعُ الْغُرُورِ ) تسبب غرور الإنسان وغفلته عن الخير الدائم الباقي. فمن الجدير بالإنسان أن يحصل بحياته ورئاسته وماله تلك الدار الباقية لا أن يغتر بالدنيا ويعصي الله سبحانه حتى يدخل النار. [187] إن الدنيا دار محنة وابتلاء لا دار راحة وسعادة فاعلموا أيها المسلمون ( لَتُبْلَوُنَ ) أي تقع عليكم المحن والبلايا بكل تأكيد ( فِي أَمْوالِكُمْ ) بذهابها ونقصانها ووجوب الإنفاق منها ( وَ ) في ( أَنْفُسِكُمْ ) بالأمراض والشدائد والقتل في الجهاد ونحوه ( وَلَتَسْمَعُنَّ مِنَ الَّذِينَ أُوتُوا الْكِتابَ مِنْ قَبْلِكُمْ ) اليهود والنصارى والمجوس ( وَمِنَ الَّذِينَ أَشْرَكُوا ) من سائر أقسام الكفار ( أَذىً كَثِيراً ) سبا وشتما وتهمة ووقيعة واستهزاء ( وَإِنْ تَصْبِرُوا ) في البلايا والأذى ( وَتَتَّقُوا ) فلا تحملنّكم البلية والأذية على الابتعاد عن الدين وعمل المحرّم ( فَإِنَّ ذلِكَ ) الصبر والتقوى ( مِنْ عَزْمِ الْأُمُورِ ) أي الأمور التي يجب العزم عليها والمضي فيها. وفي الكلام مجاز إذ نسب العزم الذي هو للإنسان إلى الأمر ، مثل نسبة الإصرار إلى الأمر في قولك : « أصرّت الأمور عليّ » لبيان أن الأمر قد صار عزما ، من شدة لزومه ، وفرض وجوبه. [188] ثم يأتي السياق إلى ذكر صفة أخرى من أهل الكتاب مناسبة للمقام وَإِذْ أَخَذَ اللهُ مِيثاقَ الَّذِينَ أُوتُوا الْكِتابَ لَتُبَيِّنُنَّهُ لِلنَّاسِ وَلا تَكْتُمُونَهُ فَنَبَذُوهُ وَراءَ ظُهُورِهِمْ وَاشْتَرَوْا بِهِ ثَمَناً قَلِيلاً فَبِئْسَ ما يَشْتَرُونَ (188) حيث أنهم يعلمون رسالة الرسول وهي موجودة في كتبهم ، لكنهم بدل أن يؤمنوا ويظهروا ذلك للناس يصرّون على الجدال والعناد ويخفون الكتاب على الناس ( وَ ) اذكر يا رسول الله ( إِذْ أَخَذَ اللهُ مِيثاقَ الَّذِينَ أُوتُوا الْكِتابَ ) أخذ عهدهم الأكيد بواسطة الأنبياء عليهم‌السلام ( لَتُبَيِّنُنَّهُ لِلنَّاسِ ) أي تبينون الكتاب الذي فيه الأحكام والبشارة برسالة الرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَلا تَكْتُمُونَهُ ) أي لا تخفونه ( فَنَبَذُوهُ ) أي طرحوا الميثاق ( وَراءَ ظُهُورِهِمْ ) كناية عن إهمالهم له وعدم اعتنائهم به كما أن الذي يريد إهمال متاع يلقيه وراء ظهره ( وَاشْتَرَوْا بِهِ ثَمَناً قَلِيلاً ) أي بدلوا بأحكام الكتاب رئاسة قليلة في الدنيا وأموالا قليلة كانوا يتقاضونها من سائر اليهود ( فَبِئْسَ ما يَشْتَرُونَ ) من الثمن حيث يستحقون بذلك العذاب الدائم. [189] ومن الناس من لا يدخل في عمل الخير مع العاملين ، فإذا خسر العاملون ما أرادوا وصفوا أنفسهم بالحصانة والتعّقل ، وإذا ربحوا جعلوا أنفسهم من المؤيدين لهم ، وتوقعوا أن يثنى عليهم ثناء العاملين ، إن أمثال هؤلاء الذين لا يشتركون فيما يجب الاشتراك فيه ، لا بد وأن ينالهم العذاب لتركهم الواجب ، وغالبا يكونون من المنافقين ، ومن الذين يقعدون عن الجهاد ، وعن واجب الأمر بالمعروف والنهي عن المنكر ، ولهؤلاء ميزة أخرى وهي أنهم يفرحون بما يأتون من الأعمال حقا كان أو باطلا ، بخلاف المؤمنين الذين إذا لا تَحْسَبَنَّ الَّذِينَ يَفْرَحُونَ بِما أَتَوْا وَيُحِبُّونَ أَنْ يُحْمَدُوا بِما لَمْ يَفْعَلُوا فَلا تَحْسَبَنَّهُمْ بِمَفازَةٍ مِنَ الْعَذابِ وَلَهُمْ عَذابٌ أَلِيمٌ وَلِلَّهِ مُلْكُ السَّماواتِ وَالْأَرْضِ وَاللهُ عَلى كُلِّ شَيْءٍ قَدِيرٌ (189) عصوا استغفروا ، وإذا أحسنوا خافوا ، كما قال سبحانه : ( وَالَّذِينَ يُؤْتُونَ ما آتَوْا وَقُلُوبُهُمْ وَجِلَةٌ ) (1) . ( لا تَحْسَبَنَ ) يا رسول الله ( الَّذِينَ يَفْرَحُونَ بِما أَتَوْا ) من الأعمال صالحة كانت أو طالحة ( وَيُحِبُّونَ أَنْ يُحْمَدُوا ) أي يحمدهم الناس ( بِما لَمْ يَفْعَلُوا ) من الأعمال الخيرية ( فَلا تَحْسَبَنَّهُمْ ) يا رسول الله ( بِمَفازَةٍ ) من الفوز ، أي النجاة ( مِنَ الْعَذابِ ) فإنهم يعذبون بكل تأكيد لهذه الأفعال والصفات ( وَلَهُمْ عَذابٌ أَلِيمٌ ) مؤلم. وهذه الآية كما تراها عامة ، فتفسيرها بالمنافق أو نحوه من باب ذكر المصداق. [190] أين المفر لهؤلاء من عذاب الله ( وَلِلَّهِ مُلْكُ السَّماواتِ وَالْأَرْضِ ) فلا يمكن لأحد الفرار من حكومته ( وَاللهُ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) فلا يفوته ما يريد ويفعل ما يشاء. [191] وهنا ينتهي السياق بأدلة الإيمان وأحوال المؤمنين وأن أعمال الكافرين في انهيار ، مناسبة للجو العام من السورة الذي كان في الإيمان والعقيدة وأحوال المؤمنين والكافرين ، ومرتبطة بالآية السابقة ( 1) المؤمنون : 61. إِنَّ فِي خَلْقِ السَّماواتِ وَالْأَرْضِ وَاخْتِلافِ اللَّيْلِ وَالنَّهارِ لَآياتٍ لِأُولِي الْأَلْبابِ (190) الَّذِينَ يَذْكُرُونَ اللهَ قِياماً وَقُعُوداً وَعَلى جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِي خَلْقِ السَّماواتِ وَالْأَرْضِ رَبَّنا ما خَلَقْتَ هذا باطِلاً سُبْحانَكَ فَقِنا عَذابَ النَّارِ (191) ( وَلِلَّهِ مُلْكُ السَّماواتِ ) ( إِنَّ فِي خَلْقِ السَّماواتِ وَالْأَرْضِ ) أي في إيجادهما بما تشتملان عليه من العجائب ومختلف صنوف الخلق والإبداع ( وَاخْتِلافِ اللَّيْلِ وَالنَّهارِ ) تعاقبهما ومجيء أحدهما خلف الآخر بكل إتقان وانتظام ( لَآياتٍ ) دلالات وبراهين على وجود الله سبحانه وصفاته ( لِأُولِي الْأَلْبابِ ) أي أصحاب العقول فإن كل من نظر إلى الأثر لا بد أن يعقل وجود المؤثر وكلما كان الأثر أتقن وأجمل دلّ على كمال علم المؤثر وقدرته وإرادته وغيرها من الصفات الجمالية. [192] ثم بين صفات أولي الألباب بقوله سبحانه : ( الَّذِينَ يَذْكُرُونَ اللهَ ) ذكرا بالقلب ، أي تذكرا له سبحانه ( قِياماً ) في حال القيام ( وَقُعُوداً ) في حال القعود ( وَعَلى جُنُوبِهِمْ ) في حال الاضطجاع ، يعني أنهم دائما في التفكّر بالله سبحانه وذكره سواء كانوا قائمين أو قاعدين أو مضطجعين ( وَيَتَفَكَّرُونَ فِي خَلْقِ السَّماواتِ وَالْأَرْضِ ) كيف خلقتا بهذا النحو المتقن المدهش ، وكيف جريتا ، وكيف كانتا ، وكيف ستكونان ، وفي حال التفكر والدهشة لسان حال هؤلاء يقول : ( رَبَّنا ما خَلَقْتَ هذا ) الكون ، والخلق ( باطِلاً ) عبثا ولغوا ، بلا غاية ومقصود ( سُبْحانَكَ ) أي أنت منزّه عن الباطل واللغو ، وهو مفعول لفعل مقدر ، أي نسبحك سبحانك ( فَقِنا ) أي احفظنا من ( عَذابَ النَّارِ ) رَبَّنا إِنَّكَ مَنْ تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ وَما لِلظَّالِمِينَ مِنْ أَنْصارٍ (192) رَبَّنا إِنَّنا سَمِعْنا مُنادِياً يُنادِي لِلْإِيمانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا رَبَّنا فَاغْفِرْ لَنا ذُنُوبَنا وَكَفِّرْ عَنَّا سَيِّئاتِنا وَتَوَفَّنا مَعَ الْأَبْرارِ (193) رَبَّنا وَآتِنا ما وَعَدْتَنا ولعل دخول الفاء في « فقنا » لبيان أنهم يطلبون جزاء تصديقهم وإيمانهم وتفكّرهم. [193] ويقولون أيضا : ( رَبَّنا إِنَّكَ مَنْ تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ ) فضحته وأهلكته ( وَما لِلظَّالِمِينَ ) الذين ظلموا أنفسهم في دار الدنيا بالكفر أو العصيان ( مِنْ أَنْصارٍ ) ينصرونهم من عذاب الله سبحانه."},{"text":"۞ لَتُبْلَوُنَّ فِىٓ أَمْوَٰلِكُمْ وَأَنفُسِكُمْ وَلَتَسْمَعُنَّ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ مِن قَبْلِكُمْ وَمِنَ ٱلَّذِينَ أَشْرَكُوٓا۟ أَذًى كَثِيرًا ۚ وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ فَإِنَّ ذَٰلِكَ مِنْ عَزْمِ ٱلْأُمُورِ","tafsir":""},{"text":"وَإِذْ أَخَذَ ٱللَّهُ مِيثَـٰقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكْتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمْ وَٱشْتَرَوْا۟ بِهِۦ ثَمَنًا قَلِيلًا ۖ فَبِئْسَ مَا يَشْتَرُونَ","tafsir":""},{"text":"لَا تَحْسَبَنَّ ٱلَّذِينَ يَفْرَحُونَ بِمَآ أَتَوا۟ وَّيُحِبُّونَ أَن يُحْمَدُوا۟ بِمَا لَمْ يَفْعَلُوا۟ فَلَا تَحْسَبَنَّهُم بِمَفَازَةٍ مِّنَ ٱلْعَذَابِ ۖ وَلَهُمْ عَذَابٌ أَلِيمٌ","tafsir":""},{"text":"وَلِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ","tafsir":""},{"text":"إِنَّ فِى خَلْقِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَـٰفِ ٱلَّيْلِ وَٱلنَّهَارِ لَـَٔايَـٰتٍ لِّأُو۟لِى ٱلْأَلْبَـٰبِ","tafsir":""},{"text":"ٱلَّذِينَ يَذْكُرُونَ ٱللَّهَ قِيَـٰمًا وَقُعُودًا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِى خَلْقِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَـٰذَا بَـٰطِلًا سُبْحَـٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ","tafsir":""},{"text":"رَبَّنَآ إِنَّكَ مَن تُدْخِلِ ٱلنَّارَ فَقَدْ أَخْزَيْتَهُۥ ۖ وَمَا لِلظَّـٰلِمِينَ مِنْ أَنصَارٍ","tafsir":""},{"text":"رَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِى لِلْإِيمَـٰنِ أَنْ ءَامِنُوا۟ بِرَبِّكُمْ فَـَٔامَنَّا ۚ رَبَّنَا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلْأَبْرَارِ","tafsir":""},{"text":"رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ ٱلْقِيَـٰمَةِ ۗ إِنَّكَ لَا تُخْلِفُ ٱلْمِيعَادَ","tafsir":"هو الرسول صلى‌الله‌عليه‌وآله‌وسلم وكل من نادى الناس للإيمان بالله سبحانه ، فإن أولي الألباب يعترفون لله سبحانه بأنهم استجابوا لمنادي الإيمان ولم يلووا عن نداء الحق فقد سمعوا المنادي ينادي : ( أَنْ آمِنُوا بِرَبِّكُمْ ) ولا تكفروا ولا تشركوا ( فَآمَنَّا ) بك يا سيدنا ( رَبَّنا فَاغْفِرْ لَنا ذُنُوبَنا ) التي صدرت منا ( وَكَفِّرْ عَنَّا سَيِّئاتِنا ) وربما يقال بأن الفرق أن الذنوب هي الكبائر لأنها ذات أذناب وتبعات ، والسيئات هي الصغائر لأنها تسيء إلى الإنسان وإن لم تكن ذات تبعة لأنها مكفّرة لمن اجتنب عن الكبائر ، وهناك في الفرق أقوال أخرى ، ولعل التكرار للتأكيد إظهارا لكمال الخوف من الذنوب ( وَتَوَفَّنا ) أي اقبضنا إليك عند موتنا ( مَعَ الْأَبْرارِ ) في جملتهم ، والأبرار جمع « برّ » وهو الذي يبرّ الله بطاعته إياه."},{"text":"فَٱسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّى لَآ أُضِيعُ عَمَلَ عَـٰمِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَىٰ ۖ بَعْضُكُم مِّنۢ بَعْضٍ ۖ فَٱلَّذِينَ هَاجَرُوا۟ وَأُخْرِجُوا۟ مِن دِيَـٰرِهِمْ وَأُوذُوا۟ فِى سَبِيلِى وَقَـٰتَلُوا۟ وَقُتِلُوا۟ لَأُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ثَوَابًا مِّنْ عِندِ ٱللَّهِ ۗ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلثَّوَابِ","tafsir":"أي أعطنا ( ما وَعَدْتَنا ) من الخير والسعادة في الدنيا عَلى رُسُلِكَ وَلا تُخْزِنا يَوْمَ الْقِيامَةِ إِنَّكَ لا تُخْلِفُ الْمِيعادَ (194) فَاسْتَجابَ لَهُمْ رَبُّهُمْ أَنِّي لا أُضِيعُ عَمَلَ عامِلٍ مِنْكُمْ مِنْ ذَكَرٍ أَوْ أُنْثى بَعْضُكُمْ مِنْ بَعْضٍ فَالَّذِينَ هاجَرُوا وَأُخْرِجُوا مِنْ دِيارِهِمْ وَأُوذُوا فِي سَبِيلِي وَقاتَلُوا وَقُتِلُوا لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ ثَواباً مِنْ عِنْدِ اللهِ ( عَلى ) لسان ( رُسُلِكَ ) وأنبيائك ( وَلا تُخْزِنا ) أي لا تفضحنا ( يَوْمَ الْقِيامَةِ ) على رؤوس الأشهاد ( إِنَّكَ لا تُخْلِفُ الْمِيعادَ ) الذي وعدته للمؤمنين بسعادة الدنيا وخير الآخرة."},{"text":"لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُوا۟ فِى ٱلْبِلَـٰدِ","tafsir":"أي لهؤلاء المؤمنين الذين دعوا بالأدعية السابقة ( رَبُّهُمْ ) أي لبّى دعوتهم وقبل كلامهم ، قائلا : ( أَنِّي لا أُضِيعُ عَمَلَ عامِلٍ مِنْكُمْ ) أيها المؤمنون ( مِنْ ذَكَرٍ أَوْ أُنْثى ) فكل مؤمن محفوظ عمله ليعطي جزاءه ( بَعْضُكُمْ ) أيها المؤمنون ( مِنْ بَعْضٍ ) فكلكم من جنس واحد في نصرة بعضكم ولستم كالكافرين الذين ليس بعضهم من بعض بل بعضهم يباين بعضا فلكل فئة منهم لون وصبغة ( فَالَّذِينَ هاجَرُوا ) إلى المدينة ( وَأُخْرِجُوا مِنْ دِيارِهِمْ ) أخرجهم المشركون من مكة. والآية عامة لكل مهاجر عن دياره ، ومخرج من بلاده ( وَأُوذُوا فِي سَبِيلِي ) لأنهم آمنوا وأطاعوا ( وَقاتَلُوا ) لأجل الله سبحانه ( وَقُتِلُوا ) قتلهم الكفار ( لَأُكَفِّرَنَ ) أي أمحونّ ( عَنْهُمْ سَيِّئاتِهِمْ ) فلا آخذهم بها ( وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ ) أي تحت نخيلها وقصورها ـ كما تقدم ـ ( ثَواباً ) أي جزاء لهم ( مِنْ عِنْدِ اللهِ ) على أعمالهم ومشاقهم في سبيله وَاللهُ عِنْدَهُ حُسْنُ الثَّوابِ (195) لا يَغُرَّنَّكَ تَقَلُّبُ الَّذِينَ كَفَرُوا فِي الْبِلادِ (196) مَتاعٌ قَلِيلٌ ثُمَّ مَأْواهُمْ جَهَنَّمُ وَبِئْسَ الْمِهادُ (197) لكِنِ الَّذِينَ اتَّقَوْا رَبَّهُمْ لَهُمْ جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ خالِدِينَ فِيها نُزُلاً مِنْ عِنْدِ اللهِ وَما عِنْدَ اللهِ خَيْرٌ لِلْأَبْرارِ (198) ( وَاللهُ عِنْدَهُ حُسْنُ الثَّوابِ ) أي الجزاء الحسن ، وليس كغيره ممن لا يقدر ولا يملك الثواب الحسن. [197] وهنا يتأمل الإنسان كيف يكون الكفار في هذه النعمة والراحة والسياحة والأسفار والثمار ، والمسلمون مضطهدين يخرجون من بلادهم ويؤذون ، مع أن الله سبحانه ناصرهم وظهيرهم ؟ ويأتي الجواب : ( لا يَغُرَّنَّكَ ) وأصل الغرور إيهام حال السرور فيما الأمر بخلافه ، فالمعنى لا يوهمنك يا رسول الله أن الكفار في سرور ( تَقَلُّبُ الَّذِينَ كَفَرُوا فِي الْبِلادِ ) فإن تقلبهم لا يعود إليهم بنفع. [198] فإن ذلك ( مَتاعٌ قَلِيلٌ ) أي يتمتعون بذلك في زمان قليل ( ثُمَّ مَأْواهُمْ ) مصيرهم ( جَهَنَّمُ وَبِئْسَ الْمِهادُ ) أي ساء ذلك المستقر لهم."},{"text":"مَتَـٰعٌ قَلِيلٌ ثُمَّ مَأْوَىٰهُمْ جَهَنَّمُ ۚ وَبِئْسَ ٱلْمِهَادُ","tafsir":""},{"text":"لَـٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا نُزُلًا مِّنْ عِندِ ٱللَّهِ ۗ وَمَا عِندَ ٱللَّهِ خَيْرٌ لِّلْأَبْرَارِ","tafsir":""},{"text":"وَإِنَّ مِنْ أَهْلِ ٱلْكِتَـٰبِ لَمَن يُؤْمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْكُمْ وَمَآ أُنزِلَ إِلَيْهِمْ خَـٰشِعِينَ لِلَّهِ لَا يَشْتَرُونَ بِـَٔايَـٰتِ ٱللَّهِ ثَمَنًا قَلِيلًا ۗ أُو۟لَـٰٓئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ ۗ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ","tafsir":"بأن آمنوا وأطاعوا فإنهم وإن كانوا في أذية وضغط فعلا ( لَهُمْ جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ ) الجارية ( خالِدِينَ فِيها ) أبدا لا متاع قليل كمتاع الكفار في الدنيا ( نُزُلاً مِنْ عِنْدِ اللهِ ) النزل ما يعدّ للضيف من الكرامة والبرّ والطعام والشراب ( وَما عِنْدَ اللهِ ) من الثواب والكرامة ( خَيْرٌ لِلْأَبْرارِ ) من تقلب الكفار. وَإِنَّ مِنْ أَهْلِ الْكِتابِ لَمَنْ يُؤْمِنُ بِاللهِ وَما أُنْزِلَ إِلَيْكُمْ وَما أُنْزِلَ إِلَيْهِمْ خاشِعِينَ لِلَّهِ لا يَشْتَرُونَ بِآياتِ اللهِ ثَمَناً قَلِيلاً أُولئِكَ لَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ إِنَّ اللهَ سَرِيعُ الْحِسابِ (199) يا أَيُّهَا الَّذِينَ آمَنُوا اصْبِرُوا وَصابِرُوا [200] ثم يرجع السياق إلى أهل الكتاب الذين تقدّم أنهم يكفرون ويمكرون ( وَإِنَّ مِنْ أَهْلِ الْكِتابِ لَمَنْ يُؤْمِنُ بِاللهِ ) يصدّق بوحدانيته ويعترف بما يعترف به المؤمنون ( وَ ) ب ( ما أُنْزِلَ إِلَيْكُمْ ) من القرآن الحكيم ( وَ ) ب ( ما أُنْزِلَ إِلَيْهِمْ ) بخلاف سائر أهل الكتاب الذين لا يؤمنون بما أنزل إليهم إذ أنهم يحلّون ويحرمون ويخالفون كتابهم في أحكامه ، في حال كونهم ( خاشِعِينَ ) خاضعين ( لِلَّهِ ) سبحانه فيما أمر ونهى ( لا يَشْتَرُونَ بِآياتِ اللهِ ) أي بمقابل آيات الله ودلائله وبراهينه ( ثَمَناً قَلِيلاً ) كما كان يفعل ذلك رؤسائهم الذين كانوا يرتشون ويخفون الكتاب لئلا تزول رئاستهم ( أُولئِكَ ) الذين لهم هذه الصفات الخيرة من أهل الكتاب ( لَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ ) يجازيهم بما فعلوا من الخيرات وآمنوا وصدقوا ( إِنَّ اللهَ سَرِيعُ الْحِسابِ ) فليس أجرهم بعيدا عنهم فإن أمد الدنيا ولو طال قليل كما قال الشاعر : ألا إنما الدنيا كمنزل راكب أناخ عشيا وهو في الصبح يرحل [201] وأخيرا يتوجه الخطاب للمؤمنين وتنتهي السورة بهذه العظة البليغة ( يا أَيُّهَا الَّذِينَ آمَنُوا اصْبِرُوا ) على الإيمان والمكاره ( وَصابِرُوا ) أي غالبوا في الصبر ، ولعل المراد مصابرة الأعداء فكلما صبر الكفار زاد وَرابِطُوا وَاتَّقُوا اللهَ لَعَلَّكُمْ تُفْلِحُونَ (200) المؤمنون صبرا على صبر أولئك حتى يغلبوا ويأخذوا المعركة ( وَرابِطُوا ) وهو المرابطة في ثغور المسلمين للتطلّع على أحوال الكفار ( وَاتَّقُوا اللهَ ) في أعمالكم فلا تأتوا بالمعاصي ( لَعَلَّكُمْ تُفْلِحُونَ ) أي كي تفوزوا وتنجحوا في الدنيا والآخرة. (4)"},{"text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱصْبِرُوا۟ وَصَابِرُوا۟ وَرَابِطُوا۟ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ","tafsir":""}]}});
